namespace {
// Upstream-delta census (XE_GPU_DELTA_CENSUS): counts hits per (tag, key) and
// returns the new count. Callers log when it is a power of two, so every
// distinct shape is logged on its first hit and its volume stays visible
// without a line per draw. Command processor thread only.
uint64_t DeltaCensusKeyedCount(uint32_t tag, uint64_t key) {
  static std::unordered_map<uint64_t, uint64_t> counts;
  return ++counts[(uint64_t(tag) << 56) ^ key];
}
bool DeltaCensusLogCount(uint64_t count) { return (count & (count - 1)) == 0; }
}  // namespace

namespace {
// metal_unwritten_interpolators: on / off, or auto = the title's hint.
// Anything else reads as auto.
bool UnwrittenInterpolatorFillEnabled() {
  const std::string& mode = ::rex::graphics::metal::GetMetalSettings().metal_unwritten_interpolators.Get();
  bool enabled = mode == "on" ? true
                 : mode == "off"
                     ? false
                     : ::rex::graphics::metal::GetMetalSettings().metal_unwritten_interpolators_title.Get();
  static int s_logged = -1;
  if (s_logged != int(enabled)) {
    s_logged = int(enabled);
    REXLOG_INFO("Metal unwritten interpolators: mode={} title={} -> fill {}", mode,
           ::rex::graphics::metal::GetMetalSettings().metal_unwritten_interpolators_title.Get(), enabled ? "0.5" : "0");
  }
  return enabled;
}
}  // namespace

namespace {
// metal_completion_wait: on / off, or auto = the title's hint; the
// XE_METAL_EXPOSURE_WAIT env (0/1) overrides. Anything else reads as auto.
bool CompletionWaitEnabled() {
  static const int s_env = [] {
    const char* v = std::getenv("XE_METAL_EXPOSURE_WAIT");
    return v && (v[0] == '0' || v[0] == '1') && !v[1] ? v[0] - '0' : -1;
  }();
  const std::string& mode = ::rex::graphics::metal::GetMetalSettings().metal_completion_wait.Get();
  const bool enabled = s_env >= 0       ? s_env == 1
                       : mode == "on"  ? true
                       : mode == "off" ? false
                                       : ::rex::graphics::metal::GetMetalSettings().metal_completion_wait_title.Get();
  static int s_logged = -1;
  if (s_logged != int(enabled)) {
    s_logged = int(enabled);
    REXLOG_INFO("Metal completion wait: mode={} title={} env={} -> {}", mode,
           ::rex::graphics::metal::GetMetalSettings().metal_completion_wait_title.Get(), s_env,
           enabled ? "wait" : "commit only");
  }
  return enabled;
}
}  // namespace

namespace {
// Route-all (DEFAULT ON since 2026-09-29): the shared-buffer GPU load route
// also serves fetches that are not resolve-backed (ordinary textures and
// memexport-produced ones such as JC2's shadow map), the upstream D3D12 model
// where every texture is loaded from shared memory on the GPU. JC2 15.3 ->
// 22.9 fps live; 0 px vs the legacy path on all 40 renderable corpus traces
// once playback stopped clobbering in-frame output (the SF4 10395 "whiteout"
// was that artifact). XE_METAL_TEX_ROUTE_ALL=0 is the exact rollback.
inline bool TexRouteAllEnabled() {
  static const bool s_all = [] {
    const char* v = std::getenv("XE_METAL_TEX_ROUTE_ALL");
    if (!v || !v[0]) {
      return true;
    }
    if (v[0] == '0' && !v[1]) {
      return false;
    }
    if (!(v[0] == '1' && !v[1])) {
      REXLOG_WARN(
          "XE_METAL_TEX_ROUTE_ALL='{}' is malformed; failing open to the "
          "default (on; use 0 or 1)",
          v);
    }
    return true;
  }();
  return s_all;
}
// Route-all bisect (SF4 10395 oracle): XE_METAL_ROUTE_SKIP_BASE=<hex,...>
// keeps the named not-resolve-backed bases on the legacy path at BOTH the
// dependency declaration and the mask (the two must agree, or a fetch is
// declared buffer-read and then served from undrained RAM).
inline bool RouteAllSkipsBase(uint32_t fetch_base) {
  static const char* s_env = std::getenv("XE_METAL_ROUTE_SKIP_BASE");
  if (!s_env) {
    return false;
  }
  for (const char* p = s_env; *p;) {
    char* end;
    uint32_t v = uint32_t(strtoul(p, &end, 16));
    if (end == p) {
      break;
    }
    if (v == fetch_base) {
      return true;
    }
    p = (*end == ',') ? end + 1 : end;
  }
  return false;
}
// XE_METAL_ROUTE_DRAIN_BASE=<hex,...>: bisect lever — the named
// not-resolve-backed bases still ROUTE at the mask but are declared RAM
// readers at the dependency site, so their producers are awaited and drained
// before the load (separates "the loader misreads the bytes" from "the bytes
// are not there yet at load time").
inline bool RouteAllDrainsBase(uint32_t fetch_base) {
  static const char* s_env = std::getenv("XE_METAL_ROUTE_DRAIN_BASE");
  if (!s_env) {
    return false;
  }
  for (const char* p = s_env; *p;) {
    char* end;
    uint32_t v = uint32_t(strtoul(p, &end, 16));
    if (end == p) {
      break;
    }
    if (v == fetch_base) {
      return true;
    }
    p = (*end == ',') ? end + 1 : end;
  }
  return false;
}
// XE_METAL_SCALE_CENSUS=1 (exact-1, default OFF): OBSERVATIONAL census of
// how much resolve-written texture traffic is served from live snapshots
// (metal_scale_coverage_census.h). Counts only.
bool ScaleCoverageCensusEnabled() {
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_SCALE_CENSUS");
    return value && value[0] == '1' && value[1] == '\0';
  }();
  return s_enabled;
}

// Bytes per pixel (per sample) an attachment of this MTLPixelFormat loads or
// stores on a tile boundary. Combined depth/stencil counts its depth plane
// here; the stencil plane is 1 byte and accounted separately (Apple GPUs store
// the two planes apart, and Metal binds them apart).
uint32_t AttachmentBytesPerPixel(MTLPixelFormat format) {
  switch (format) {
    case MTLPixelFormatA8Unorm:
    case MTLPixelFormatR8Unorm:
    case MTLPixelFormatR8Snorm:
    case MTLPixelFormatR8Uint:
    case MTLPixelFormatR8Sint:
    case MTLPixelFormatStencil8:
      return 1;
    case MTLPixelFormatR16Unorm:
    case MTLPixelFormatR16Snorm:
    case MTLPixelFormatR16Uint:
    case MTLPixelFormatR16Sint:
    case MTLPixelFormatR16Float:
    case MTLPixelFormatRG8Unorm:
    case MTLPixelFormatRG8Snorm:
    case MTLPixelFormatRG8Uint:
    case MTLPixelFormatRG8Sint:
    case MTLPixelFormatB5G6R5Unorm:
    case MTLPixelFormatA1BGR5Unorm:
    case MTLPixelFormatABGR4Unorm:
    case MTLPixelFormatBGR5A1Unorm:
    case MTLPixelFormatDepth16Unorm:
      return 2;
    case MTLPixelFormatRGBA16Unorm:
    case MTLPixelFormatRGBA16Snorm:
    case MTLPixelFormatRGBA16Uint:
    case MTLPixelFormatRGBA16Sint:
    case MTLPixelFormatRGBA16Float:
    case MTLPixelFormatRG32Uint:
    case MTLPixelFormatRG32Sint:
    case MTLPixelFormatRG32Float:
      return 8;
    case MTLPixelFormatRGBA32Uint:
    case MTLPixelFormatRGBA32Sint:
    case MTLPixelFormatRGBA32Float:
      return 16;
    default:
      // RGBA8/BGRA8 (+sRGB), RG16*, R32*, RGB10A2, RG11B10, RGB9E5,
      // Depth32Float, Depth32Float_Stencil8 (depth plane).
      return 4;
  }
}

// XE_METAL_SCALED_COVER_ORDERING=0: a scaled-cover-served fetch over a
// pending GPU-current resolve waits for the resolve (the pre-2026-10-03
// behavior) instead of ordering against it on the GPU.
inline bool ScaledCoverOrderingEnabled() {
  static const bool s_enabled = [] {
    const char* v = std::getenv("XE_METAL_SCALED_COVER_ORDERING");
    return !(v && v[0] == '0' && !v[1]);
  }();
  return s_enabled;
}

inline bool RouteServiceOk(ResolvedFetchService service,
                           uint32_t fetch_base = 0,
                           bool declaration_site = false) {
  return service == ResolvedFetchService::kRamContent ||
         (TexRouteAllEnabled() &&
          service == ResolvedFetchService::kNotResolveBacked &&
          !RouteAllSkipsBase(fetch_base) &&
          !(declaration_site && RouteAllDrainsBase(fetch_base)));
}
inline uint32_t fetch_width_serve(const xenos::TextureFetch& f) {
  switch (f.dimension) {
    case xenos::DataDimension::k1D:
      return f.size_1d.width + 1;
    case xenos::DataDimension::k3D:
      return f.size_3d.width + 1;
    default:
      return f.size_2d.width + 1;
  }
}
inline uint32_t fetch_height_serve(const xenos::TextureFetch& f) {
  switch (f.dimension) {
    case xenos::DataDimension::k1D:
      return 1;
    case xenos::DataDimension::k3D:
      return f.size_3d.height + 1;
    default:
      return f.size_2d.height + 1;
  }
}
inline uint32_t fetch_pitch_serve(const xenos::TextureFetch& f) {
  uint32_t w = fetch_width_serve(f);
  return f.pitch ? (uint32_t(f.pitch) << 5) : ((w + 31u) & ~31u);
}
}  // namespace

namespace {

// Process physical footprint in MiB, or 0.0 if the query fails. One sampler
// for every consumer (frame telemetry and cache-clear resource evidence) so
// they cannot drift into measuring subtly different things. Internal linkage:
// there is no header or API consumer outside this translation unit.
double ProcessFootprintMiB() {
  task_vm_info_data_t vm_info;
  mach_msg_type_number_t vm_count = TASK_VM_INFO_COUNT;
  if (task_info(mach_task_self(), TASK_VM_INFO,
                reinterpret_cast<task_info_t>(&vm_info),
                &vm_count) != KERN_SUCCESS) {
    return 0.0;
  }
  return double(vm_info.phys_footprint) / (1024.0 * 1024.0);
}

// XE_METAL_TESSELLATION (port-xenios-tessellation task 4.6). Strict parse per
// the depth-semantics flag conventions: unset/empty/"0" off, "1" on, anything
// else warns once and takes the default. Default ON since the host
// tessellation route's promotion (2026-09-20); exact "0" is the rollback and
// makes every tessellation path unreachable (bit-identical to the pre-route
// OFF arm).
bool MetalTessellationGateOn() {
  static const bool s_gate_on = [] {
    const char* value = std::getenv("XE_METAL_TESSELLATION");
    MetalTessellationGate gate = ParseMetalTessellationGate(value);
    if (gate == MetalTessellationGate::kMalformed) {
      REXLOG_WARN(
          "XE_METAL_TESSELLATION='{}' is malformed; using the default (on) "
          "(use 0 or 1)",
          value);
    }
    return MetalTessellationGateEngaged(gate);
  }();
  return s_gate_on;
}


// extend-metal-rasterizing-memexport-producers task 2.1 (design D4):
// XE_METAL_MEMEXPORT_RASTER, default OFF, warn-once malformed. OFF is today
// exactly -- rasterizing producers still rasterize, their exports stay
// unrouted, and the unconditional gap report keeps counting them.
bool MetalMemexportRasterGateOn() {
  static const bool s_gate_on = [] {
    const char* value = std::getenv("XE_METAL_MEMEXPORT_RASTER");
    if (!value || !value[0]) {
      // Unset: the option. on / off, or auto = the title's hint (per-title
      // files set it for the titles that need the route). Anything else
      // reads as auto.
      const std::string& mode = ::rex::graphics::metal::GetMetalSettings().metal_memexport_raster_mode.Get();
      bool on = mode == "on"    ? true
                : mode == "off" ? false
                                : ::rex::graphics::metal::GetMetalSettings().metal_memexport_raster.Get();
      REXLOG_INFO("Metal rasterizing memexport: mode={} title={} -> {}", mode,
             ::rex::graphics::metal::GetMetalSettings().metal_memexport_raster.Get(), on ? "on" : "off");
      return on;
    }
    MetalMemexportRasterGate gate = ParseMetalMemexportRasterGate(value);
    if (gate == MetalMemexportRasterGate::kMalformed) {
      REXLOG_WARN(
          "XE_METAL_MEMEXPORT_RASTER='{}' is malformed; failing closed to off "
          "(use 0 or 1)",
          value);
    }
    return MetalMemexportRasterGateEngaged(gate);
  }();
  return s_gate_on;
}

// Pixel-stage memexport gate (default on): ::rex::graphics::metal::GetMetalSettings().metal_memexport_pixel.Get(), with
// XE_METAL_MEMEXPORT_PIXEL=0/1 overriding; malformed values keep the option.
bool MetalMemexportPixelGateOn() {
  static const bool s_gate_on = [] {
    const char* value = std::getenv("XE_METAL_MEMEXPORT_PIXEL");
    bool on = ::rex::graphics::metal::GetMetalSettings().metal_memexport_pixel.Get();
    if (value && value[0]) {
      if ((value[0] == '0' || value[0] == '1') && !value[1]) {
        on = value[0] == '1';
      } else {
        REXLOG_WARN(
            "XE_METAL_MEMEXPORT_PIXEL='{}' is malformed; keeping "
            "::rex::graphics::metal::GetMetalSettings().metal_memexport_pixel.Get()={} (use 0 or 1)",
            value, on);
      }
    }
    REXLOG_INFO("Metal pixel-stage memexport: {}", on ? "on" : "off");
    return on;
  }();
  return s_gate_on;
}

// Pixel-stage memexport from a draw that binds NO render target (default on;
// XE_METAL_MEMEXPORT_PIXEL_NO_RT=0 restores the old skip). Virtua Tennis 4
// (53450857) builds every UI texture this way: it uploads the linear image to
// a staging buffer, then draws one quad per texture with color writes off and
// a pixel shader that memexports each texel to its tiled address. Skipping
// the draw left the destination holding whatever was there before (logo
// noise, empty or scrambled glyph pages). The draw runs in its own pass with
// a scratch depth attachment covering the scissor; only the exports matter.
bool MetalMemexportPixelNoTargetGateOn() {
  static const bool s_gate_on = [] {
    const char* value = std::getenv("XE_METAL_MEMEXPORT_PIXEL_NO_RT");
    bool on = !(value && value[0] == '0' && !value[1]);
    REXLOG_INFO("Metal pixel-stage memexport without render targets: {}",
           on ? "on" : "off");
    return on;
  }();
  return s_gate_on;
}

// A draw with no color writes, depth and stencil off and no memory export
// changes nothing in EDRAM, but inside an open occlusion (ZPD) report it is
// what the report counts: with the depth test off every covered sample passes.
// Mafia II issues about a dozen such reports a frame (540-index triangle
// lists, no pixel shader; 5-125 samples each once drawn), and every one of
// them read 0 while they were skipped (2026-11-03, M4 mini census).
// D3D12 and Vulkan draw such a draw into the render targets already bound, so
// it is executed here the same way: the targets stay as they are (no
// ownership change, write mask 0, depth state disabled) and only the sample
// count is affected. XE_METAL_ZPD_COUNT_NO_TARGET_DRAWS=0 restores the skip.
bool MetalZPDCountNoTargetDrawsOn() {
  static const bool s_on = [] {
    const char* value = std::getenv("XE_METAL_ZPD_COUNT_NO_TARGET_DRAWS");
    return !(value && value[0] == '0' && !value[1]);
  }();
  return s_on;
}

// ATTRIBUTION DIAGNOSTICS (both default-off, log/route-filter only; neither
// can alter behavior unless explicitly set).
//
// XE_METAL_MEMEXPORT_RASTER_ONLY=<hexbase>[,<hexbase>...]: with the raster
// gate on, route ONLY producers whose destination base is in this list.
// Bisects "which producer moved the image" one destination at a time, which
// is the only way to attribute an image delta to a specific guest range
// without guessing.
const std::vector<uint32_t>& MemexportRasterOnlyBases() {
  static const std::vector<uint32_t> s_bases = [] {
    std::vector<uint32_t> bases;
    const char* value = std::getenv("XE_METAL_MEMEXPORT_RASTER_ONLY");
    if (!value || !value[0]) {
      return bases;
    }
    const char* cursor = value;
    while (*cursor) {
      char* end = nullptr;
      unsigned long parsed = std::strtoul(cursor, &end, 16);
      if (end == cursor) {
        break;
      }
      bases.push_back(uint32_t(parsed));
      cursor = (*end == ',') ? end + 1 : end;
    }
    REXLOG_WARN("XE_METAL_MEMEXPORT_RASTER_ONLY: routing {} destination base(s)",
           bases.size());
    return bases;
  }();
  return s_bases;
}

// True when this destination base is admitted by the bisect filter (an empty
// filter admits everything, so the default path is unchanged).
bool MemexportRasterBaseAdmitted(uint32_t base_bytes) {
  const std::vector<uint32_t>& bases = MemexportRasterOnlyBases();
  if (bases.empty()) {
    return true;
  }
  for (uint32_t base : bases) {
    if (base == base_bytes) {
      return true;
    }
  }
  return false;
}

// XE_METAL_MEMEXPORT_WATCH=<hexbase>[:<hexsize>]: an ACCESS CENSUS over one
// guest range, independent of whether a pending producer record still exists.
//
// WHY THIS EXISTS AND THE PENDING-PRODUCER LOG DOES NOT SUFFICE: the
// MetalMemexportConsumer line reports only producers the authority decision
// SELECTED, which requires the record to still be pending at that moment. A
// downstream reader whose record was already retired by an earlier unfiltered
// drain reads the converged bytes and logs NOTHING -- so "no consumer was
// logged" is not evidence of "no consumer exists". This census keys on range
// overlap alone and therefore cannot miss a reader for that reason.
struct MemexportWatchRange {
  uint32_t base = 0;
  uint32_t size = 0;
  bool enabled = false;
};

const MemexportWatchRange& MemexportWatch() {
  static const MemexportWatchRange s_watch = [] {
    MemexportWatchRange watch;
    const char* value = std::getenv("XE_METAL_MEMEXPORT_WATCH");
    if (!value || !value[0]) {
      return watch;
    }
    char* end = nullptr;
    watch.base = uint32_t(std::strtoul(value, &end, 16));
    watch.size = (end && *end == ':') ? uint32_t(std::strtoul(end + 1, nullptr,
                                                              16))
                                      : 0x10000u;
    watch.enabled = watch.size != 0;
    REXLOG_WARN("XE_METAL_MEMEXPORT_WATCH: census over {:08X}(+{})", watch.base,
           watch.size);
    return watch;
  }();
  return s_watch;
}

bool MemexportWatchOverlaps(uint32_t base, uint32_t size) {
  const MemexportWatchRange& watch = MemexportWatch();
  if (!watch.enabled || !size) {
    return false;
  }
  return metal::MetalGuestRangesOverlap(base, size, watch.base, watch.size);
}

// XE_METAL_MEMEXPORT_RASTER_FAULT=<no-tess-range|undersize-tess-range>: fault
// injection for the staleness backstop's own oracle. Default none. A safety
// net never observed firing is not evidence of safety, and the only honest way
// to observe this one is to break the mechanism it backs up.
MetalMemexportRasterFault MemexportRasterFault() {
  static const MetalMemexportRasterFault s_fault = [] {
    const char* value = std::getenv("XE_METAL_MEMEXPORT_RASTER_FAULT");
    MetalMemexportRasterFault fault = ParseMetalMemexportRasterFault(value);
    if (fault != MetalMemexportRasterFault::kNone) {
      REXLOG_WARN(
          "XE_METAL_MEMEXPORT_RASTER_FAULT='{}': the consumer-range mutation "
          "is deliberately broken -- the staleness backstop MUST fail closed",
          value);
    }
    return fault;
  }();
  return s_fault;
}


// Concrete task-3.1 RamWritePublicationTarget: forwards the seam's two
// invalidation primitives to the operations that already exist on this
// command processor's shared memory / legacy texture cache. Holds no state of
// its own and adds no new watch -- it is a thin adapter so PublishRamWrite can
// EXECUTE a writer's publication instead of only predicting it.
class MetalRamWritePublicationTarget : public metal::RamWritePublicationTarget {
 public:
  MetalRamWritePublicationTarget(::rex::gpu::SharedMemory* shared_memory,
                                 metal::MetalTextureCache* texture_cache,
                                 metal::MetalTextureCache::InvalidationScope
                                     texture_invalidation_scope =
                                         metal::MetalTextureCache::
                                             InvalidationScope::
                                                 kAllRepresentations)
      : shared_memory_(shared_memory),
        texture_cache_(texture_cache),
        texture_invalidation_scope_(texture_invalidation_scope) {}

  bool InvalidateSharedPages(uint32_t base, uint32_t length,
                             bool exact_range) override {
    if (!shared_memory_) {
      return false;
    }
    // Resolve convergence invalidates the shared pages and fires per-range
    // watches so the shared texture cache reloads, but the matching legacy
    // snapshot bridge must survive. The preceding resolve-drain call site
    // invalidates legacy RAM uploads with kRamUploadsOnly, so suppress only
    // duplicate global-watch fan-out for this self-publication.
    bool fire_global_watches =
        texture_invalidation_scope_ == metal::MetalTextureCache::
                                           InvalidationScope::
                                               kAllRepresentations;
    // Clobber hunt (reopen 3.1): see MarkRangeWrittenByGpu.
    static const uint64_t s_watch = [] {
      const char* v = std::getenv("XE_METAL_UPLOAD_WATCH");
      return v ? strtoull(v, nullptr, 16) : 0ull;
    }();
    if (s_watch && base < s_watch + ::rex::gpu::SharedMemory::kBufferSize &&
        base + length > s_watch) {
      REXLOG_WARN("MetalUploadWatch INVALIDATE {:08X}+{:X} exact={}", base, length,
             exact_range);
    }
    // Upstream reports the direction instead of fanning out itself: the range was written by the GPU, so its CPU-side
    // copies are the ones that go stale. fire_global_watches had no upstream counterpart and its only caller set it from
    // the invalidation scope, which the texture cache now owns.
    (void)fire_global_watches;
    shared_memory_->RangeWrittenByGPU(base, length);
    return true;
  }

  bool InvalidateLegacyTextures(uint32_t base, uint32_t length,
                                uint32_t* invalidated_entries) override {
    if (!texture_cache_) {
      return false;
    }
    *invalidated_entries = texture_cache_->InvalidateRange(
        base, length, texture_invalidation_scope_, "ram-write-publication");
    return true;
  }

 private:
  ::rex::gpu::SharedMemory* shared_memory_;
  metal::MetalTextureCache* texture_cache_;
  metal::MetalTextureCache::InvalidationScope texture_invalidation_scope_;
};

// Concrete task-3.3 memexport destination-preparation target: forwards to the
// existing ::rex::gpu::SharedMemory::RequestRange the direct call site used before.
class MetalMemexportPreparationTarget
    : public metal::MemexportPreparationTarget {
 public:
  explicit MetalMemexportPreparationTarget(::rex::gpu::SharedMemory* shared_memory)
      : shared_memory_(shared_memory) {}

  bool RequestDestinationRange(uint32_t base, uint32_t length) override {
    return shared_memory_ && shared_memory_->RequestRange(base, length);
  }

 private:
  ::rex::gpu::SharedMemory* shared_memory_;
};

// Concrete task-3.3 memexport GPU-write publication target: forwards to the
// existing ::rex::gpu::SharedMemory::RangeWrittenByGpu the direct call site used before.
class MetalMemexportPublicationTarget
    : public metal::MemexportPublicationTarget {
 public:
  explicit MetalMemexportPublicationTarget(::rex::gpu::SharedMemory* shared_memory)
      : shared_memory_(shared_memory) {}

  bool CanMarkRangeWrittenByGpu() const override {
    return shared_memory_ != nullptr;
  }

  void MarkRangeWrittenByGpu(uint32_t base, uint32_t length) override {
    // Clobber hunt (reopen 3.1): timeline of validity transitions on the
    // watched range, same env as the upload watch.
    static const uint64_t s_watch = [] {
      const char* v = std::getenv("XE_METAL_UPLOAD_WATCH");
      return v ? strtoull(v, nullptr, 16) : 0ull;
    }();
    if (s_watch && base < s_watch + ::rex::gpu::SharedMemory::kBufferSize &&
        base + length > s_watch) {
      REXLOG_WARN("MetalUploadWatch MARK-GPU-WRITTEN {:08X}+{:X}", base, length);
    }
    shared_memory_->RangeWrittenByGPU(base, length);
  }

 private:
  ::rex::gpu::SharedMemory* shared_memory_;
};

// Concrete task-3.3 memexport RAM-convergence target: publishes the completed
// export's exact bytes from the shared buffer to guest RAM and invalidates
// overlapping legacy texture-cache entries (the same direct call the drain
// used before). It never touches shared-memory page validity -- the shared
// buffer is the authoritative source of the converged bytes and is left
// exactly as-is.
//
// The byte movement itself is delegated to MetalSharedMemory, which owns the
// backing and is therefore the only place that can prove whether destination
// and source are one allocation (zero-copy pre-gate task 4.2). This target
// keeps the invalidation and reports the shared memory's FACTUAL byte count --
// zero on a proven alias, `length` on a real mirror copy -- so nothing
// downstream has to infer copying from the backing mode.
class MetalMemexportConvergenceTarget
    : public metal::MemexportConvergenceTarget {
 public:
  MetalMemexportConvergenceTarget(::rex::gpu::CommandProcessor* command_processor,
                                  ::rex::IPhysicalMemory* memory,
                                  MetalSharedMemory* shared_memory,
                                  metal::MetalTextureCache* texture_cache)
      : command_processor_(command_processor),
        physical_memory_(memory),
        shared_memory_(shared_memory),
        texture_cache_(texture_cache) {}

  bool CopyBufferToRam(uint32_t base, uint32_t length,
                       uint32_t* invalidated_entries,
                       uint64_t* bytes_copied) override {
    // Every out parameter is defined on EVERY exit, including the early
    // failures below. A caller that read an untouched `bytes_copied` would be
    // reporting stack garbage as evidence of a publication.
    *invalidated_entries = 0;
    *bytes_copied = 0;
    if (!shared_memory_) {
      return false;
    }
    // Pre-write journal notify (fix-replay-guest-ram-rollback 1.2). Under the
    // diagnostic zero-copy alias the GPU already wrote these bytes at draw
    // execution, so the captured pre-image is unsound there — an accepted
    // limitation of two diagnostic-only modes coinciding; production mirror
    // mode captures before the only RAM write, this copy.
    if (owned_only_) {
      // A lazily armed record copies only the pages it still owns: the rest
      // were published on first touch, discarded by a host overwrite or
      // superseded, and RAM there may hold newer CPU data. Copying them from
      // the buffer again clobbered Banjo-Kazooie's command buffers and shader
      // microcode (ring allocator reusing export scratch) with exports routed.
      const uint64_t end = uint64_t(base) + length;
      for (const auto& [owned_start, owned_length] : *owned_only_) {
        uint64_t sub_start = std::max<uint64_t>(base, owned_start);
        uint64_t sub_end =
            std::min<uint64_t>(end, uint64_t(owned_start) + owned_length);
        if (sub_end <= sub_start) {
          continue;
        }
        uint32_t sub_length = uint32_t(sub_end - sub_start);
        if (command_processor_) {
          shared_memory_->RangeWrittenByGPU(uint32_t(sub_start),
                                                  sub_length);
        }
        metal::SharedBufferConvergenceOutcome published =
            pre_image_
                ? shared_memory_->ConvergeChangedWordsToRam(
                      uint32_t(sub_start), sub_length,
                      pre_image_->data() + (uint32_t(sub_start) -
                                            pre_image_base_))
                : shared_memory_->ConvergeRangeToRam(uint32_t(sub_start),
                                                     sub_length);
        *bytes_copied += published.bytes_copied;
        if (!published.converged) {
          return false;
        }
      }
    } else {
      if (command_processor_) {
        shared_memory_->RangeWrittenByGPU(base, length);
      }
      metal::SharedBufferConvergenceOutcome published =
          shared_memory_->ConvergeRangeToRam(base, length);
      *bytes_copied = published.bytes_copied;
      if (!published.converged) {
        // Missing backing, missing RAM mapping, or an alias claim the addresses
        // do not support: publish nothing and let the caller retain the
        // record.
        return false;
      }
    }
    if (texture_cache_) {
      // Task 5.3 proved the earlier RangeWrittenByGpu watch is equivalent in
      // normal mode, but trace playback unregisters that global watch and
      // skips queue draining. Keep this direct retirement globally so replayed
      // memexports cannot leave aliases or resolved bridges stale.
      *invalidated_entries = texture_cache_->InvalidateRange(
          base, length,
          metal::MetalTextureCache::InvalidationScope::kAllRepresentations,
          "lazy-publish");
    }
    return true;
  }

  // Restricts the next copies to these guest ranges (a lazily armed record's
  // still-owned pages); nullptr copies whole records.
  void SetOwnedOnly(const std::vector<std::pair<uint32_t, uint32_t>>* owned) {
    owned_only_ = owned;
  }

  // The owned-only copies of the next record move only the words that differ
  // from its pre-image (indexed from `base`); nullptr copies whole pages.
  void SetPreImage(uint32_t base, const std::vector<uint8_t>* pre_image) {
    pre_image_base_ = base;
    pre_image_ = pre_image;
  }

 private:
  ::rex::gpu::CommandProcessor* command_processor_;
  ::rex::IPhysicalMemory* physical_memory_;
  MetalSharedMemory* shared_memory_;
  metal::MetalTextureCache* texture_cache_;
  const std::vector<std::pair<uint32_t, uint32_t>>* owned_only_ = nullptr;
  uint32_t pre_image_base_ = 0;
  const std::vector<uint8_t>* pre_image_ = nullptr;
};

// Snapshot-bridge lineage probe (XE_METAL_LINEAGE=<base hex>): writer-side half.
// Same base + strided-hash as the reader (metal_texture_cache.mm) so the
// resolve/writeback/drain events on the watched base share the fetch clock.
uint32_t xe_lineage_base() {
  static uint32_t b = [] {
    const char* v = std::getenv("XE_METAL_LINEAGE");
    return v ? uint32_t(strtoul(v, nullptr, 16)) : 0u;
  }();
  return b;
}
uint32_t xe_lineage_stridehash(const void* p, size_t n) {
  const uint8_t* b = static_cast<const uint8_t*>(p);
  uint32_t h = 2166136261u;
  for (size_t i = 0; i < n; i += 37) h = (h ^ b[i]) * 16777619u;
  return h;
}

// Origin experiment (reopen-metal-gpu-visible-resolve-authority 2.1,
// XE_METAL_ORIGIN_DUMP=<dir>): dump a resolve destination's whole extent with
// its record fields, from BOTH publication arms — "cpu" = guest RAM after the
// default CPU scatter (ground truth), "gpu" = the shared-buffer source region
// the GPU-current publication reads. Offline correlation of the two names the
// producer's effective write origin without pre-guessing candidates.
// Diagnostic-only, bounded, default off.
static void MetalOriginDumpExtent(const char* arm, uint32_t guest_addr,
                                  uint32_t width, uint32_t height,
                                  uint32_t bpp, uint32_t pitch_field,
                                  uint32_t height_aligned, uint32_t offset_x,
                                  uint32_t offset_y, uint32_t extent_bytes,
                                  uint32_t packed_bytes, uint32_t swap_rb,
                                  uint32_t endian, uint32_t draw_index,
                                  const uint8_t* bytes) {
  static const char* s_dir = std::getenv("XE_METAL_ORIGIN_DUMP");
  if (!s_dir || !bytes || !extent_bytes) {
    return;
  }
  static uint32_t s_dumps = 0;
  if (s_dumps >= 256) {
    return;
  }
  ++s_dumps;
  char path[1024];
  std::snprintf(path, sizeof(path), "%s/%s-%08X-d%u.bin", s_dir, arm,
                guest_addr, draw_index);
  FILE* f = std::fopen(path, "wb");
  if (!f) {
    return;
  }
  std::fwrite(bytes, 1, extent_bytes, f);
  std::fclose(f);
  REXLOG_WARN(
      "MetalOriginDump arm={} dest={:08X} {}x{} bpp={} pitch_field={} "
      "height_aligned={} off=({},{}) extent={} packed={} swap_rb={} endian={} "
      "draw={} -> {}",
      arm, guest_addr, width, height, bpp, pitch_field, height_aligned,
      offset_x, offset_y, extent_bytes, packed_bytes, swap_rb, endian,
      draw_index, path);
}

// Precise guest storage ranges of a texture fetch: base level(s) and mip chain
// as two DISJOINT ranges (mip_address is a separate pointer). Derived from the
// shared GetGuestTextureLayout, so compressed/tiled/linear/packed-mip/dimension
// semantics match the upload path exactly. Ends use 64-bit math clamped to
// UINT32_MAX so no address arithmetic wraps.
metal::FetchGuestRanges ComputeFetchGuestRangesUncached(const xenos::TextureFetch& f);

// A pure function of the six fetch-constant dwords, evaluated per binding at
// up to five sites per draw (Red Dead gameplay: ~2% of the command-processor
// thread in GetGuestTextureLayout). Direct-mapped memo keyed on all six
// dwords; XE_METAL_FETCH_RANGE_MEMO=0 computes every time.
metal::FetchGuestRanges ComputeFetchGuestRanges(
    const xenos::TextureFetch& f) {
  static const bool s_memo = [] {
    const char* v = std::getenv("XE_METAL_FETCH_RANGE_MEMO");
    return !(v && v[0] == '0' && !v[1]);
  }();
  if (!s_memo) {
    return ComputeFetchGuestRangesUncached(f);
  }
  struct MemoEntry {
    uint32_t key[6];
    bool valid = false;
    metal::FetchGuestRanges ranges;
  };
  static constexpr uint32_t kMemoEntries = 512;
  thread_local std::vector<MemoEntry> memo(kMemoEntries);
  const uint32_t key[6] = {f.dword_0, f.dword_1, f.dword_2, f.dword_3, f.dword_4, f.dword_5};
  uint32_t h = 2166136261u;
  for (uint32_t k : key) {
    h = (h ^ k) * 16777619u;
  }
  MemoEntry& entry = memo[(h ^ (h >> 15)) & (kMemoEntries - 1)];
  if (entry.valid && std::memcmp(entry.key, key, sizeof(key)) == 0) {
    return entry.ranges;
  }
  entry.ranges = ComputeFetchGuestRangesUncached(f);
  std::memcpy(entry.key, key, sizeof(key));
  entry.valid = true;
  return entry.ranges;
}

metal::FetchGuestRanges ComputeFetchGuestRangesUncached(const xenos::TextureFetch& f) {
  metal::FetchGuestRanges r;
  uint32_t w = 1, h = 1, d = 1;
  switch (f.dimension) {
    case xenos::DataDimension::k1D:
      w = f.size_1d.width + 1;
      break;
    case xenos::DataDimension::k2DOrStacked:
      w = f.size_2d.width + 1;
      h = f.size_2d.height + 1;
      d = f.stacked ? (f.size_2d.stack_depth + 1) : 1;
      break;
    case xenos::DataDimension::k3D:
      w = f.size_3d.width + 1;
      h = f.size_3d.height + 1;
      d = f.size_3d.depth + 1;
      break;
    case xenos::DataDimension::kCube:
      w = f.size_2d.width + 1;
      h = f.size_2d.height + 1;
      d = 6;
      break;
  }
  auto clamp_end = [](uint32_t begin, uint32_t size) -> uint32_t {
    uint64_t e = uint64_t(begin) + uint64_t(size);
    return e > 0xFFFFFFFFull ? 0xFFFFFFFFu : uint32_t(e);
  };
  ::rex::xenos::GuestTextureLayout lay = ::rex::xenos::GetGuestTextureLayout(
      f.dimension, f.pitch, w, h, d, f.tiled != 0, f.format,
      f.packed_mips != 0, /*has_base=*/true, uint32_t(f.mip_max_level));
  uint32_t base_addr = f.base_address << 12;
  r.base_begin = base_addr;
  r.base_end = clamp_end(base_addr, lay.base.level_data_extent_bytes);
  // The mip chain's page as the upload sees it: absent when normalization
  // drops it (a raw mip_max_level with no mip page used to yield a range at
  // physical 0), and the base page when level 0 is the packed tail.
  uint32_t mip_page = 0;
  ::rex::xenos::GetSubresourcesFromFetchConstant(
      f, nullptr, nullptr, nullptr, nullptr, &mip_page, nullptr, nullptr);
  if (uint32_t(f.mip_max_level) > 0 && mip_page && lay.mips_total_extent_bytes) {
    uint32_t mip_addr = mip_page << 12;
    r.mip_begin = mip_addr;
    r.mip_end = clamp_end(mip_addr, lay.mips_total_extent_bytes);
  }
  return r;
}

// Entries inside the small fixed system view table.
constexpr uint32_t kSystemViewSharedMemorySRV = 0;
constexpr uint32_t kSystemViewNullUAV = 1;
// Shared memory as a writable UAV (u0, space0) for memexport draws — the
// top-level AB slot kAbUavSpace0 points here only while encoding a draw whose
// shader actually exports (non-exporting draws keep the null entry).
constexpr uint32_t kSystemViewSharedMemoryUAV = 2;
constexpr uint32_t kSystemViewEntryCount = 3;

// Texture view slots: one per live host texture view (legacy cache entries,
// shared-cache swizzle/sign views, render-target and resolve views). 4096 was
// exhausted by GTA IV's streamed set once the shared route kept its textures
// alive (every legacy lookup then untiled with no slot to keep the result:
// 42 ms/frame); both caches shed LRU entries as the headroom goes, so the
// size bounds the resident working set, not correctness. 16 bytes a slot.
constexpr uint32_t kViewBindlessHeapSlots = 16384;
// Unique samplers (one slot each, never evicted; the space is bounded by the
// sampler parameters). D3D12's heap holds 2000 and rolls over; 256 was hit in
// long sessions, turning every later new sampler into a skipped draw. Clamped
// to the device's argument-buffer sampler limit at heap creation.
constexpr uint32_t kSamplerBindlessHeapSlots = 2048;
// Per-draw constants for a whole open submission must fit: a frame of ~10k
// draws (NBA 2K11's arena light show) filled 32 MB inside one submission and
// dropped ~700k draws a session (sysconst-alloc), since ArenaAllocate can only
// wait for committed submissions.
constexpr uint32_t kUploadArenaSize = 128u * 1024 * 1024;
// XE_METAL_ARENA_SIZE=<bytes>: ring-stress override — a small ring forces
// constant wrapping/reclaim pressure in trace replay, turning any ring
// lifetime bug into a deterministic headless corruption vs the baselines.
static uint32_t UploadArenaSize() {
  const char* v = std::getenv("XE_METAL_ARENA_SIZE");
  return v ? uint32_t(strtoul(v, nullptr, 10)) : kUploadArenaSize;
}

// A resolve joining a parent snapshot as a vertical strip: FindContainingSnapshot
// gives the row of the strip's adjusted destination base, which draw_util
// aligns down to a 32-row tile row, leaving the rest of the start row in the
// destination offset. Adds that offset to strip_y; false (no join) for an x
// offset, which is not a vertical strip. XE_METAL_STRIP_DEST_OFFSET=0 restores
// joining at the base row.
bool ApplyStripJoinDestOffset(const draw_util::ResolveInfo& resolve_info,
                              uint32_t& strip_y) {
  static const bool s_enabled = ParseMetalEnvironmentFlag(
      std::getenv("XE_METAL_STRIP_DEST_OFFSET"), true);
  if (!s_enabled) {
    return true;
  }
  const auto& dest = resolve_info.copy_dest_coordinate_info;
  if (dest.offset_x_div_8) {
    return false;
  }
  strip_y += uint32_t(dest.offset_y_div_8) << 3;
  return true;
}

bool MapPrimitiveType(xenos::PrimitiveType type, MTLPrimitiveType* out) {
  switch (type) {
    case xenos::PrimitiveType::kPointList:
      *out = MTLPrimitiveTypePoint;
      return true;
    case xenos::PrimitiveType::kLineList:
      *out = MTLPrimitiveTypeLine;
      return true;
    case xenos::PrimitiveType::kLineStrip:
      *out = MTLPrimitiveTypeLineStrip;
      return true;
    case xenos::PrimitiveType::kTriangleList:
      *out = MTLPrimitiveTypeTriangle;
      return true;
    case xenos::PrimitiveType::kTriangleStrip:
      *out = MTLPrimitiveTypeTriangleStrip;
      return true;
    case xenos::PrimitiveType::kRectangleList:
      // 3 guest vertices define a rectangle whose 4th corner (v3 = v0 + v2 - v1)
      // the guest GPU synthesizes. IssueDraw expands rect-lists through MSC
      // geometry emulation (the GS emits the true 4-corner rect) BEFORE reaching
      // MapPrimitiveType, so this is only hit as the fallback when the device
      // lacks mesh-shader support (or there's no pixel shader). Drawing 3 verts as
      // one triangle covers only half the screen with degenerate UVs, so skip
      // (render nothing) rather than draw garbage. See openspec
      // reduce-apple-gpu-frametime handoff.
      return false;
    case xenos::PrimitiveType::kTriangleFan:
      // No host triangle-fan primitive; IssueDraw expands it to a triangle list
      // with a generated index buffer. Report the target host primitive here.
      *out = MTLPrimitiveTypeTriangle;
      return true;
    default:
      // Quads and patches need primitive-processor conversion or geometry
      // emulation. Guest line loops are also intentionally not mapped here:
      // PP3-auto maps only the shared processor's host kLineStrip result.
      return false;
  }
}

// XE_METAL_HEAP_MISS_LOG=1: names each distinct texture that the
// heap path still declares per draw (diagnostic only).
void LogHeapMissTexture(void* tex) {
  static const bool enabled = [] {
    const char* v = std::getenv("XE_METAL_HEAP_MISS_LOG");
    return v && v[0] == '1';
  }();
  if (!enabled) {
    return;
  }
  static std::unordered_set<void*> seen;
  if (seen.size() >= 256 || !seen.insert(tex).second) {
    return;
  }
  __unsafe_unretained id<MTLTexture> t = (__bridge id<MTLTexture>)tex;
  __unsafe_unretained id<MTLTexture> root = t;
  uint32_t depth = 0;
  while (root.parentTexture && depth < 4) {
    root = root.parentTexture;
    ++depth;
  }
  REXLOG_INFO(
      "MetalHeapMiss: {} '{}' root '{}' depth {} {}x{}x{} fmt {} type {} "
      "storage {} usage {:X} samples {} buffer {}",
      fmt::ptr(tex), t.label ? [t.label UTF8String] : "",
      root.label ? [root.label UTF8String] : "", depth, uint32_t(root.width),
      uint32_t(root.height), uint32_t(root.arrayLength), uint32_t(root.pixelFormat),
      uint32_t(root.textureType), uint32_t(root.storageMode), uint32_t(root.usage),
      uint32_t(root.sampleCount), root.buffer ? 1 : 0);
}

// SwapIndicesInto (guest index byte-swap into the host arena) and IsPp1Routable
// (the routing predicate) are the shared production contracts, defined once in
// metal_primitive_processor.h so the device-free conformance test exercises the
// same code rather than a replica.

}  // namespace

MetalCommandProcessor::MetalCommandProcessor(::rex::gpu::XenosGraphicsDriverBase* driver,
                                             const TitleInfo& info, IPhysicalMemory& memory,
                                             IPhysicalWriteWatch& watch, IGuestInterrupts& interrupts)
    : ::rex::gpu::CommandProcessor(driver, info, memory, watch, interrupts) {}
MetalCommandProcessor::~MetalCommandProcessor() = default;

bool MetalCommandProcessor::GetOrCreateSamplerSlot(uint64_t key, uint32_t* out_slot) {
  *out_slot = 0;
  auto it = sampler_slot_cache_.find(key);
  if (it != sampler_slot_cache_.end()) {
    *out_slot = it->second;
    return true;
  }
  if (next_sampler_slot_ >= sampler_heap_slots_ || !sampler_bindless_heap_) {
    static bool s_full_logged = false;
    if (!s_full_logged) {
      s_full_logged = true;
      REXLOG_ERROR("MetalCommandProcessor: sampler heap full ({} unique samplers)",
             sampler_heap_slots_);
    }
    return false;
  }
  id<MTLDevice> device = (__bridge id<MTLDevice>)
      static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider())
          ->device();
  MTLSamplerDescriptor* d = [[MTLSamplerDescriptor alloc] init];
  const uint32_t aniso =
      ((draw_resolution_scale_x_ > 1 || draw_resolution_scale_y_ > 1) &&
       !metal::MetalScaledAnisotropyEnabled())
          ? 0u
          : uint32_t((key >> 15) & 7);
  const uint32_t border =
      uint32_t((key >> metal::kMetalSamplerKeyBorderShift) & 3);
  const bool force_bc_w_to_max =
      ((key >> metal::kMetalSamplerKeyForceBcWShift) & 1) != 0;
  const uint32_t mip_min_level = uint32_t((key >> 20) & 15);
  const bool base_map = ((key >> 24) & 1) != 0;
  // Quality override, off by default: Halo 3 asks for modest anisotropy and the GPU has time to spare at 720p, so the
  // sampler can be raised to Metal's maximum. The guest's choice is honoured when this is unset.
  static const bool s_force_max_aniso = [] {
    const char* v = std::getenv("XE_METAL_FORCE_MAX_ANISO");
    return v != nullptr && v[0] == '1' && v[1] == 0;
  }();
  const bool legacy = ((key >> 25) & 1) != 0;
  // Maximum level (D3D12 MaxLOD); 0 = unset (the pre-MINMIP key).
  const uint32_t mip_max_level = uint32_t((key >> 26) & 15);
  auto minmag = [](uint32_t f) {
    // TextureFilter: 0=point, 1=linear, 2=base-map (no mip; min/mag linear
    // gives the least-surprising look), 3 resolved before packing.
    return f == 0 ? MTLSamplerMinMagFilterNearest
                  : MTLSamplerMinMagFilterLinear;
  };
  uint32_t mip = uint32_t((key >> 4) & 3);
  if (legacy) {
    d.magFilter = minmag(uint32_t(key & 3));
    d.minFilter = minmag(uint32_t((key >> 2) & 3));
    d.mipFilter = mip == 1 ? MTLSamplerMipFilterLinear
                           : (mip == 0 ? MTLSamplerMipFilterNearest
                                       : MTLSamplerMipFilterNotMipmapped);
    if (aniso) {
      d.maxAnisotropy = s_force_max_aniso ? 16u : std::min(16u, 1u << (aniso - 1));
    }
  } else if (aniso) {
    // Shared contract: anisotropic filtering is always linear min/mag/mip.
    d.magFilter = MTLSamplerMinMagFilterLinear;
    d.minFilter = MTLSamplerMinMagFilterLinear;
    d.mipFilter = MTLSamplerMipFilterLinear;
    d.maxAnisotropy = s_force_max_aniso ? 16u : std::min(16u, 1u << (aniso - 1));
  } else {
    d.magFilter = minmag(uint32_t(key & 3));
    d.minFilter = minmag(uint32_t((key >> 2) & 3));
    d.mipFilter = mip == 1 ? MTLSamplerMipFilterLinear
                           : MTLSamplerMipFilterNearest;
  }
  // LOD range: the host texture holds levels 0..max, so the guest's minimum
  // level is a sampler clamp (D3D12 MinLOD). Base-map pins sampling to that
  // level (D3D12 MaxLOD = MinLOD, +0.25 with point mip filtering so
  // magnification vs minification is preserved).
  d.lodMinClamp = legacy ? 0.0f : float(mip_min_level);
  if (base_map && !legacy) {
    d.lodMaxClamp = float(mip_min_level) + (aniso ? 0.0f : 0.25f);
    if (!aniso) {
      d.mipFilter = MTLSamplerMipFilterNearest;
    }
  } else if (!legacy && mip_max_level) {
    d.lodMaxClamp = float(mip_max_level);
  }
  // Border colour per the shared contract (metal_sampler_contract.h):
  // ABGR black/white and the force_bc_w_to_max alpha forcing are exact;
  // the YCbCr blacks decay to black luma with the contract's alpha (Metal
  // has no custom border colours) and are counted as approximated.
  {
    const metal::MetalSamplerBorderDecision decision =
        metal::DecideMetalSamplerBorder(xenos::BorderColor(border),
                                        force_bc_w_to_max);
    switch (decision.border) {
      case metal::MetalSamplerBorder::kOpaqueWhite:
        d.borderColor = MTLSamplerBorderColorOpaqueWhite;
        break;
      case metal::MetalSamplerBorder::kOpaqueBlack:
        d.borderColor = MTLSamplerBorderColorOpaqueBlack;
        break;
      case metal::MetalSamplerBorder::kTransparentBlack:
      default:
        d.borderColor = MTLSamplerBorderColorTransparentBlack;
        break;
    }
    if (decision.approximated) {
      static uint32_t s_approximated_logs = 0;
      if (s_approximated_logs++ < 8) {
        REXLOG_WARN(
            "MetalSamplerBorderApprox: YCbCr border colour {} has no Metal "
            "border colour; using {} black (alpha {}) for sampler key {:016X}",
            border, "luma", force_bc_w_to_max ? 1 : 0, key);
      }
    }
  }
  auto addr = [](uint32_t c) {
    switch (xenos::ClampMode(c)) {
      case xenos::ClampMode::kRepeat:
        return MTLSamplerAddressModeRepeat;
      case xenos::ClampMode::kMirroredRepeat:
        return MTLSamplerAddressModeMirrorRepeat;
      case xenos::ClampMode::kMirrorClampToEdge:
      case xenos::ClampMode::kMirrorClampToHalfway:
      case xenos::ClampMode::kMirrorClampToBorder:
        return MTLSamplerAddressModeMirrorClampToEdge;
      case xenos::ClampMode::kClampToBorder:
        return MTLSamplerAddressModeClampToBorderColor;
      case xenos::ClampMode::kClampToEdge:
      case xenos::ClampMode::kClampToHalfway:
      default:
        return MTLSamplerAddressModeClampToEdge;
    }
  };
  d.sAddressMode = addr(uint32_t((key >> 6) & 7));
  d.tAddressMode = addr(uint32_t((key >> 9) & 7));
  d.rAddressMode = addr(uint32_t((key >> 12) & 7));
  // Diagnostic A/B (XE_METAL_SAMPLER_FORCE_BORDER=1): every clamp-to-border
  // sampler gets an opaque-white border regardless of the fetch, to prove
  // the sampler state reaches the shader (a byte-identical output under this
  // arm means the border is never sampled in the frame, or the state is
  // ignored).
  static const bool s_force_border =
      std::getenv("XE_METAL_SAMPLER_FORCE_BORDER") != nullptr;
  if (s_force_border) {
    d.borderColor = MTLSamplerBorderColorOpaqueWhite;
    d.sAddressMode = MTLSamplerAddressModeClampToBorderColor;
    d.tAddressMode = MTLSamplerAddressModeClampToBorderColor;
  }
  // Samplers live in the bindless argument-buffer heap.
  d.supportArgumentBuffers = YES;
  id<MTLSamplerState> state = [device newSamplerStateWithDescriptor:d];
  if (!state) {
    return false;
  }
  static const bool s_sampler_census_log =
      std::getenv("XE_METAL_SAMPLER_CENSUS") != nullptr;
  if (s_sampler_census_log) {
    REXLOG_INFO(
        "MetalSamplerCreate key={:016X} mag={} min={} mip={} aniso={} "
        "addr=({},{},{}) border={} force_bc_w={} lod=[{},{}] base_map={}",
        key, uint32_t(d.magFilter), uint32_t(d.minFilter),
        uint32_t(d.mipFilter), uint32_t(d.maxAnisotropy),
        uint32_t(d.sAddressMode), uint32_t(d.tAddressMode),
        uint32_t(d.rAddressMode), uint32_t(d.borderColor),
        force_bc_w_to_max ? 1 : 0, d.lodMinClamp, d.lodMaxClamp,
        base_map ? 1 : 0);
  }
  uint32_t slot = next_sampler_slot_++;
  auto* entries = static_cast<IRDescriptorTableEntry*>(
      [(__bridge id<MTLBuffer>)sampler_bindless_heap_ contents]);
  IRDescriptorTableSetSampler(&entries[slot], state, 0.0f);
  sampler_states_.push_back((__bridge_retained void*)state);
  sampler_slot_cache_.emplace(key, slot);
  *out_slot = slot;
  return true;
}

void MetalCommandProcessor::TracePlaybackWroteMemory(uint32_t base_ptr,
                                                     uint32_t length) {
  // Trace restore publishes bytes straight to RAM. Route the publication
  // through the typed task-3.1 seam: it invalidates the shared-memory pages
  // the trace stream just rewrote (so the next RequestConsumedRange
  // re-uploads them, mirroring the Vulkan backend) using the SAME
  // MemoryInvalidationCallback this call site used directly before.
  //
  // The direct MetalTextureCache::InvalidateRange call is durably RETAINED:
  // trace playback unregisters the legacy global watch, so the seam's policy
  // for kTraceRestore also requests legacy invalidation rather than relying on
  // watch fan-out. Task 5.3's writer-matrix comparison proved this leg is not
  // redundant (the legacy global-watch set is empty after SetTracePlayback), so
  // it stays by design. SetTracePlayback() must still run first regardless of
  // range count.
  if (texture_cache_) {
    texture_cache_->SetTracePlayback();
    if (shared_texture_cache_) {
      shared_texture_cache_->SetTracePlayback();
    }
  }
  auto publication = metal::DecideRamWritePublication(
      metal::WriterKind::kTraceRestore, base_ptr, length);
  if (publication) {
    MetalRamWritePublicationTarget target(shared_memory_.get(),
                                          texture_cache_.get());
    metal::PublishRamWrite(*publication, target);
  }
  // The capture's bytes for a range this replay's GPU already produced in the
  // frame are not this frame's output: a trace records what the CAPTURING
  // build had published when the capture read the range (SF4 10395: the
  // luminance pyramid at 19423000 is restored between draws 352 and 354,
  // after this replay's draw-351 resolve was drained, with the capture's
  // stale bytes -> the legacy RAM untile samples them -> streaked frame, while
  // the buffer-served route reads the replay's own resolve). Keep the
  // replay's GPU-written bytes, as the Vulkan backend does
  // (InvalidateRangeKeepingGpuWritten). Pending records need nothing here:
  // their drain publishes the buffer over RAM after the GPU runs them. For
  // records already drained this frame the shared buffer still holds their
  // bytes, because this hook runs right after the restore write and before
  // any upload. XE_METAL_TRACE_RESTORE_CLOBBER=1 restores the old behavior;
  // XE_METAL_TRACE_RESTORE_LOG=1 names each kept overlap.
  static const bool s_restore_clobber =
      std::getenv("XE_METAL_TRACE_RESTORE_CLOBBER") != nullptr;
  static const bool s_restore_log =
      std::getenv("XE_METAL_TRACE_RESTORE_LOG") != nullptr;
  if (s_restore_clobber || playback_gpu_written_.empty() || !shared_memory_ ||
      !length) {
    return;
  }
  id<MTLBuffer> buffer = (__bridge id<MTLBuffer>)shared_memory_->GetCpuBuffer();
  const uint8_t* contents =
      buffer ? static_cast<const uint8_t*>(buffer.contents) : nullptr;
  if (!contents) {
    return;
  }
  const uint64_t end = uint64_t(base_ptr) + length;
  auto pending_over = [&](uint64_t s0, uint64_t s1) {
    for (const PendingWriteback& wb : pending_writebacks_) {
      if (wb.gpu_current && !wb.staging && wb.guest_addr < s1 &&
          uint64_t(wb.guest_addr) + wb.range_bytes() > s0) {
        return true;
      }
    }
    for (const PendingMemexport& me : pending_memexports_) {
      if (me.base_address < s1 &&
          uint64_t(me.base_address) + me.size_bytes > s0) {
        return true;
      }
    }
    return false;
  };
  for (const auto& written : playback_gpu_written_) {
    uint64_t s0 = std::max<uint64_t>(written.first, base_ptr);
    uint64_t s1 =
        std::min<uint64_t>(uint64_t(written.first) + written.second, end);
    if (s0 >= s1 || pending_over(s0, s1)) {
      continue;
    }
    shared_memory_->EnsureCpuCurrent(uint32_t(s0), uint32_t(s1 - s0));
    uint8_t* ram = static_cast<uint8_t*>(shared_memory_->GetCpuBuffer()) + uint32_t(s0);
    if (!ram) {
      continue;
    }
    uint32_t differing = 0;
    for (uint64_t i = 0; i < s1 - s0; ++i) {
      differing += ram[i] != contents[s0 + i] ? 1u : 0u;
    }
    if (!differing) {
      continue;
    }
    std::memcpy(ram, contents + s0, size_t(s1 - s0));
    if (s_restore_log) {
      REXLOG_WARN(
          "MetalTraceRestore before draw={} {:08X}+{:X}: kept {} differing "
          "bytes of this frame's GPU output at {:08X}+{:X}",
          trace_draw_index_, base_ptr, length, differing, uint32_t(s0),
          uint32_t(s1 - s0));
    }
  }
}

void MetalCommandProcessor::RestoreEdramSnapshot(const void* snapshot) {
  // Trace playback: seed the EDRAM ownership + contents captured before the
  // frame (JC2 resolves the previous frame's depth/color early in the frame).
  if (render_target_cache_) {
    render_target_cache_->RestoreEdramSnapshot(snapshot);
  }
}

bool MetalCommandProcessor::DumpEdramToBuffer(
    std::vector<uint8_t>& edram_out) {
  if (!render_target_cache_) {
    return false;
  }
  // Flush all pending GPU work so texture contents are final. Mid-frame this
  // is a commit + wait; the next draw's BeginFrameEncoder starts a fresh
  // command buffer and LOADs the (persistent) render-target contents.
  EndFrameEncoderAndWait(metal::SeamBoundaryReason::kEdramDump);
  auto* provider =
      static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider());
  if (!provider || !provider->command_queue()) {
    return false;
  }
  id<MTLCommandQueue> queue =
      (__bridge id<MTLCommandQueue>)provider->command_queue();
  // XE_METAL_DUMP_SNAPSHOT=<hexbase> at a --capture_edram_at draw: the GPU is
  // idle here, so the resolve snapshot for that base is EXACTLY what the
  // captured draw samples. Raw texels to /tmp/xe_snapat_<base>_<draw>.bin.
  {
    static const uint32_t s_dump_snapshot_at = [] {
      const char* v = std::getenv("XE_METAL_DUMP_SNAPSHOT");
      return v ? uint32_t(strtoul(v, nullptr, 16)) : 0u;
    }();
    void* snap = s_dump_snapshot_at
                     ? render_target_cache_->GetResolveSnapshot(s_dump_snapshot_at)
                     : nullptr;
    if (snap) {
      @autoreleasepool {
        id<MTLTexture> st = (__bridge id<MTLTexture>)snap;
        uint32_t tw = uint32_t(st.width), th = uint32_t(st.height);
        uint32_t bpp = 4;
        switch (st.pixelFormat) {
          case MTLPixelFormatRGBA16Float:
          case MTLPixelFormatRGBA16Unorm:
          case MTLPixelFormatRGBA16Snorm:
          case MTLPixelFormatRG32Float:
            bpp = 8;
            break;
          case MTLPixelFormatRGBA32Float:
            bpp = 16;
            break;
          default:
            break;
        }
        id<MTLBuffer> rb =
            [st.device newBufferWithLength:size_t(tw) * th * bpp
                                   options:MTLResourceStorageModeShared];
        if (rb) {
          id<MTLCommandBuffer> dcb = [queue commandBuffer];
          id<MTLBlitCommandEncoder> dbl = [dcb blitCommandEncoder];
          [dbl copyFromTexture:st
                    sourceSlice:0
                    sourceLevel:0
                   sourceOrigin:MTLOriginMake(0, 0, 0)
                     sourceSize:MTLSizeMake(tw, th, 1)
                       toBuffer:rb
              destinationOffset:0
         destinationBytesPerRow:tw * bpp
       destinationBytesPerImage:size_t(tw) * th * bpp];
          [dbl endEncoding];
          [dcb commit];
          [dcb waitUntilCompleted];
          std::string path = fmt::format("/tmp/xe_snapat_{:08X}_{}.bin",
                                         s_dump_snapshot_at, trace_draw_index_);
          FILE* f = fopen(path.c_str(), "wb");
          if (f) {
            fwrite(rb.contents, 1, size_t(tw) * th * bpp, f);
            fclose(f);
            REXLOG_WARN("MetalSnapshotAt: draw={} wrote {} ({}x{} fmt={})",
                   uint32_t(trace_draw_index_), path, tw, th, uint32_t(st.pixelFormat));
          }
        }
      }
    }
  }
  if (render_target_cache_->sample_edram_enabled()) {
    // Canonical mode capture contract: snapshots, full dumps, and the base
    // command processor's per-tile/sample hashes all read the same private raw
    // physical-layout buffer. Attachment writes begin advancing it in tasks
    // 3.x; until then this intentionally exposes restored canonical state.
    if (!render_target_cache_->PrepareCanonicalEdramForReadback()) {
      return false;
    }
    // The pack operations above use the ordinary frame command buffer so they
    // remain ordered after the producing draws. Complete them before the dump
    // command buffer reads the private canonical buffer.
    EndFrameEncoderAndWait(metal::SeamBoundaryReason::kEdramDump);
    return render_target_cache_->DumpCanonicalEdram((__bridge void*)queue,
                                                     edram_out);
  }
  std::vector<MetalRenderTargetCache::EdramOwnerDump> owners;
  render_target_cache_->GetEdramOwnersForDump(owners);
  // The EDRAM image: 2048 tiles x 80x16 samples x 4 bytes, tile-major.
  constexpr uint32_t kTileBytes = 80 * 16 * 4;
  edram_out.assign(xenos::kEDRAMSizeBytes, 0);
  std::vector<uint8_t>& edram = edram_out;
  static const bool s_dump_owner_log = std::getenv("XE_METAL_DUMP_OWNER_LOG");
  for (const auto& owner : owners) {
    if (owner.is_64bpp) {
      continue;  // 64bpp encode not implemented in the dump yet.
    }
    if (s_dump_owner_log) {
      id<MTLTexture> ot = (__bridge id<MTLTexture>)owner.texture;
      REXLOG_WARN("MetalDumpOwner: tex={} {}x{} depth={} msaa={} base={} pitch={} "
             "rows[{},{})",
             owner.texture, ot.width, ot.height, owner.is_depth,
             owner.msaa_samples, uint32_t(owner.base_tiles), uint32_t(owner.pitch_tiles),
             owner.row_first, owner.row_first + owner.rows);
    }
    // Per-owner autorelease pool: with per-draw capture (--capture_edram_*)
    // this runs thousands of times on a pool-less replay thread; the
    // autoreleased command buffer/encoder otherwise retain the multi-MB
    // staging buffers until the process OOMs (SIGKILL ~2600 draws in).
    @autoreleasepool {
    id<MTLTexture> tex = (__bridge id<MTLTexture>)owner.texture;
    uint32_t tw = uint32_t(tex.width), th = uint32_t(tex.height);
    // Read the whole owner texture back once. Combined depth-stencil owners
    // read as two plane blits: depth floats (4B/px) + stencil bytes (1B/px,
    // appended after the depth plane in the staging buffer).
    bool combined_ds =
        owner.is_depth && tex.pixelFormat == MTLPixelFormatDepth32Float_Stencil8;
    id<MTLDevice> dev = tex.device;
    size_t depth_plane_bytes = size_t(tw) * th * 4;
    id<MTLBuffer> staging =
        [dev newBufferWithLength:depth_plane_bytes +
                                 (combined_ds ? size_t(tw) * th : 0)
                         options:MTLResourceStorageModeShared];
    if (!staging) {
      continue;
    }
    id<MTLCommandBuffer> cb = [queue commandBuffer];
    id<MTLBlitCommandEncoder> blit = [cb blitCommandEncoder];
    if (combined_ds) {
      [blit copyFromTexture:tex
                sourceSlice:0
                sourceLevel:0
               sourceOrigin:MTLOriginMake(0, 0, 0)
                 sourceSize:MTLSizeMake(tw, th, 1)
                   toBuffer:staging
          destinationOffset:0
     destinationBytesPerRow:tw * 4
   destinationBytesPerImage:depth_plane_bytes
                    options:MTLBlitOptionDepthFromDepthStencil];
      [blit copyFromTexture:tex
                sourceSlice:0
                sourceLevel:0
               sourceOrigin:MTLOriginMake(0, 0, 0)
                 sourceSize:MTLSizeMake(tw, th, 1)
                   toBuffer:staging
          destinationOffset:depth_plane_bytes
     destinationBytesPerRow:tw
   destinationBytesPerImage:size_t(tw) * th
                    options:MTLBlitOptionStencilFromDepthStencil];
    } else {
      [blit copyFromTexture:tex
                sourceSlice:0
                sourceLevel:0
               sourceOrigin:MTLOriginMake(0, 0, 0)
                 sourceSize:MTLSizeMake(tw, th, 1)
                   toBuffer:staging
          destinationOffset:0
     destinationBytesPerRow:tw * 4
   destinationBytesPerImage:depth_plane_bytes];
    }
    [blit endEncoding];
    [cb commit];
    [cb waitUntilCompleted];
    const uint8_t* pixels = static_cast<const uint8_t*>(staging.contents);
    const uint8_t* stencil_plane =
        combined_ds ? pixels + depth_plane_bytes : nullptr;
    // msaa_samples is the xenos::MSAASamples ENUM (k1X=0, k2X=1, k4X=2), not a
    // sample count: 2x+ doubles vertical, 4x also doubles horizontal. The old
    // >=3/>=2 count-style thresholds read 4x owners with xs=0 — the right half
    // of every sample row fell out of bounds and dumped as zeros (the phantom
    // "half-screen" divergence at the 7282/6756 draw-25 MSAA clears).
    EdramMsaaShifts msaa_shifts = GetEdramMsaaShifts(owner.msaa_samples);
    // The rect covers full-EDRAM 16-tile rows [row_first, row_first+rows).
    for (uint32_t er = owner.row_first; er < owner.row_first + owner.rows;
         ++er) {
      for (uint32_t ec = 0; ec < 16; ++ec) {
        uint32_t tile = er * 16 + ec;
        if (tile < uint32_t(owner.base_tiles)) {
          continue;
        }
        uint32_t local = tile - uint32_t(owner.base_tiles);
        if (uint32_t(owner.pitch_tiles) == 0 || local / uint32_t(owner.pitch_tiles) >= 100000) {
          continue;
        }
        uint8_t* tile_out = edram.data() + size_t(tile) * kTileBytes;
        // Per sample of the 80x16 tile: source pixel = sample >> shifts.
        // Depth EDRAM addressing swaps each tile's 40-sample column halves
        // (see the reference dump shader): word position sx holds the host
        // sample from the other half.
        for (uint32_t sy = 0; sy < 16; ++sy) {
          for (uint32_t sx = 0; sx < 80; ++sx) {
            uint32_t host_sx = owner.is_depth
                                   ? EdramDepthSwapX(
                                         sx, xenos::kEDRAMTileWidthSamples)
                                   : sx;
            uint32_t sample_x = (local % uint32_t(owner.pitch_tiles)) * 80 + host_sx;
            uint32_t sample_y = (local / uint32_t(owner.pitch_tiles)) * 16 + sy;
            uint32_t px = sample_x >> msaa_shifts.x;
            uint32_t py = sample_y >> msaa_shifts.y;
            uint32_t word = 0;
            if (px < tw && py < th) {
              const uint8_t* p = pixels + (size_t(py) * tw + px) * 4;
              if (owner.is_depth) {
                float d;
                std::memcpy(&d, p, 4);
                // unorm24 encode must be roundEven(d * 0xFFFFFF) to match
                // the guest-visible conversion (see the Vulkan dump shader:
                // +0.5-and-truncate is explicitly the WRONG conversion, and
                // biases the whole depth plane by up to 2 ULP24).
                uint32_t d24 =
                    owner.is_float24_depth
                        ? xenos::Float32To20e4(d, false)
                        : uint32_t(std::rint(
                              std::min(1.0f, std::max(0.0f, d)) *
                              16777215.0f));
                uint32_t stencil =
                    stencil_plane ? stencil_plane[size_t(py) * tw + px] : 0u;
                word = PackEdramDepthStencil(d24, stencil);
              } else if (owner.pixel_format == uint64_t(MTLPixelFormatR32Float)) {
                std::memcpy(&word, p, 4);
              } else {
                // Canonical RGBA8 storage: bytes ARE the guest EDRAM word.
                word = PackEdramColor8888(p[0], p[1], p[2], p[3]);
              }
            }
            std::memcpy(tile_out + (size_t(sy) * 80 + sx) * 4, &word, 4);
          }
        }
      }
    }
    }  // autoreleasepool
  }
  return true;
}

// Frame command buffers carry per-encoder execution status so a GPU fault
// names the encoder that caused it (labels are set at each encoder open). The
// alternative — a bare [queue commandBuffer] — reports only "Caused GPU
// Address Fault Error" with no attribution.
//
// Apple GPUs only by default: on the AMD driver every encoder of such a
// command buffer also opens a progress-tracking encoder whose pooled status
// resource costs a kernel round trip (IOAccelResourceSetPurgeable) -- 62% of
// the command-processor thread in Skate 2 on the Mac Pro, 2026-10-10.
// XE_METAL_ENCODER_STATUS=1/0 forces it on/off.
static bool MetalEncoderExecutionStatusEnabled(id<MTLDevice> device) {
  static const bool s_enabled = [device] {
    if (const char* v = std::getenv("XE_METAL_ENCODER_STATUS")) {
      return v[0] == '1';
    }
    return bool([device supportsFamily:MTLGPUFamilyApple7]);
  }();
  return s_enabled;
}

static id<MTLCommandBuffer> MakeAttributedCommandBuffer(
    id<MTLCommandQueue> queue) {
  if (!MetalEncoderExecutionStatusEnabled(queue.device)) {
    return [queue commandBuffer];
  }
  MTLCommandBufferDescriptor* desc = [[MTLCommandBufferDescriptor alloc] init];
  desc.errorOptions = MTLCommandBufferErrorOptionEncoderExecutionStatus;
  return [queue commandBufferWithDescriptor:desc];
}

// Per-encoder residency sweep for devices without an MTLResidencySet. On AMD
// (no residency sets) the sweep re-declared every cached texture on every
// render encoder -- ~1200 textures x 44 passes/frame in Skate 2, a third of the
// command-processor thread in amdMtl_HwCmdBufAddIndirectRsrc -- and skipping
// it doubled Skate 2 (10.3 -> 20.0 fps) with 0 faults across six titles. Its
// stale-slot guard dates from the sparse-b4 descriptor-index fault storm,
// fixed since. Default: on for Apple GPUs only (macOS 14, where residency sets
// are unavailable); per-draw useResource still covers each draw's fetches.
// XE_METAL_RESIDENT_SWEEP=1/0 overrides.
static bool ResidentSweepEnabled(id<MTLDevice> device) {
  static const bool s_enabled = [device] {
    if (const char* v = std::getenv("XE_METAL_RESIDENT_SWEEP")) {
      return v[0] == '1';
    }
    return bool([device supportsFamily:MTLGPUFamilyApple7]);
  }();
  return s_enabled;
}

// Geometry emulation (rectangle / point / quad lists) runs as object+mesh
// threadgroups through the shader-converter runtime: one guest draw is one
// mesh grid. XE_METAL_GEO_CHUNK=N splits a draw into dispatches of at most N
// object threadgroups each (0 = one dispatch per draw, the runtime's own
// behaviour). Returns the vertex/index count per dispatch, clamped to the
// draw. The per-object-threadgroup vertex stride mirrors the runtime's
// IRRuntimeCalculateDrawInfoForGSEmulation (16 KB payload less 32 bytes of
// metadata, 256 object threads, 1024 mesh threadgroups per object
// threadgroup), so a chunk boundary never splits a primitive.
static uint32_t GeometryEmulationChunkVertices(IRRuntimePrimitiveType primitive,
                                               uint32_t vertex_size,
                                               uint32_t max_input_primitives,
                                               uint32_t draw_vertices) {
  static const uint32_t s_chunk_threadgroups = [] {
    const char* v = std::getenv("XE_METAL_GEO_CHUNK");
    return v ? uint32_t(strtoul(v, nullptr, 10)) : 0u;
  }();
  if (!s_chunk_threadgroups || !vertex_size || !max_input_primitives ||
      !draw_vertices) {
    return draw_vertices;
  }
  const uint32_t per_primitive =
      primitive == IRRuntimePrimitiveTypePoint         ? 1u
      : primitive == IRRuntimePrimitiveTypeLineWithAdj ? 4u
                                                       : 3u;
  const uint32_t payload_vertices =
      (((16384u - 32u) / vertex_size) / per_primitive) * per_primitive;
  uint32_t primitives = std::min(payload_vertices / per_primitive,
                                 1024u * max_input_primitives);
  primitives = std::min(primitives, 256u / per_primitive);
  const uint32_t stride = std::max(primitives, 1u) * per_primitive;
  const uint64_t chunk = uint64_t(stride) * s_chunk_threadgroups;
  return uint32_t(std::min<uint64_t>(chunk, draw_vertices));
}

// Point sprites: expand in the vertex shader (the guest point drawn as a
// two-triangle strip of 4 host vertices, ::rex::gpu::Shader::HostVertexShaderType::
// kPointListAsTriangleStrip) instead of the shader-converter object+mesh
// geometry emulation. On the M1 Max under macOS 27.0.1 the mesh point
// pipelines made the GPU abort the scene pass' command buffer with
// "Insufficient ::rex::IPhysicalMemory" (kIOGPUCommandBufferCallbackErrorOutOfMemory) 50-110
// times per Banjo-Kazooie session (2026-10-18; RDR, Judgment and Tomb Raider
// too), and the whole mesh route held Banjo at 20 fps where the plain path
// runs its declared 30. ::rex::graphics::metal::GetMetalSettings().metal_point_sprite_vs_expansion.Get() / XE_METAL_POINT_VS=0
// restore the mesh path.
static bool PointSpriteVsExpansionEnabled() {
  static const bool s_enabled = [] {
    if (const char* v = std::getenv("XE_METAL_POINT_VS")) {
      return v[0] == '1';
    }
    return ::rex::graphics::metal::GetMetalSettings().metal_point_sprite_vs_expansion.Get();
  }();
  return s_enabled;
}

// XE_METAL_GEO_LOG=1: the first 200 geometry-emulation draws of 2,048 or more
// vertices, with the dispatch chunk in effect (mesh-grid size attribution).
static void NoteGeometryEmulationDraw(uint32_t geometry_type,
                                      uint32_t draw_vertices, uint32_t chunk) {
  static const bool s_log = [] {
    const char* v = std::getenv("XE_METAL_GEO_LOG");
    return v && v[0] == '1' && !v[1];
  }();
  if (!s_log || draw_vertices < 2048) {
    return;
  }
  static uint32_t s_logged = 0;
  if (s_logged++ < 200) {
    REXLOG_INFO("MetalGeoDraw type={} vertices={} chunk={} dispatches={}",
           geometry_type, draw_vertices, chunk,
           (draw_vertices + chunk - 1) / std::max(chunk, 1u));
  }
}

// Logs the per-encoder execution status carried by a faulted command buffer
// (requires MakeAttributedCommandBuffer): which encoders faulted vs completed.
//
// `submission` is the SERIAL of this faulted command-buffer completion. It is
// the ATTRIBUTION unit -- which submission failed -- and NOT by itself an
// independent fault incident: one GPU failure or queue revocation makes every
// in-flight submission complete with an error, so distinct serials still
// over-count root events.
//
// Fault reporting therefore needs FOUR separate counts, none of which
// substitutes for another:
//   1. FAULT EPISODES        -- the first error observed while the queue is
//                               healthy, grouped through its revoke/recovery.
//                               The closest thing to "how many times did the
//                               GPU actually break".
//   2. DISTINCT FAILED SERIALS -- submissions that completed with an error.
//   3. FAULT-BEARING SWAPS   -- presentation boundaries carrying any error.
//   4. FAULTED ENCODER LINES -- per-encoder attributions inside those buffers.
//
// Measured on VP both_r1: 45 completion-error headers across 19 swaps, 5
// FAULTED encoder lines, and 2 queue revokes -- most plausibly ~2 episodes
// with a large collateral radius, certainly not 45 independent faults and not
// necessarily 5 either. `grep -c` on any single one of these is misleading.
// Diagnostic (XE_METAL_CB_ENCODER_RING=1): every encoder a command buffer
// creates -- render, compute or blit, from any of the backend's call sites --
// is recorded with its caller, and a faulted command buffer lists them (the
// draw sequence names draws only; AMD reports no encoder status).
namespace {
struct CbEncoderNote {
  void* command_buffer;
  void* encoder;
  void* caller;
  uint32_t seq;
  char kind;
};
struct CbDispatchNote {
  void* encoder;
  void* caller;
  // g_cb_encoder_next when issued: after its encoder's own seq.
  uint32_t seq;
  uint32_t groups[3];
  uint32_t threads[3];
  // 'G' dispatchThreadgroups, 'T' dispatchThreads, 'I' indirect.
  char kind;
};
constexpr uint32_t kCbEncoderRingSize = 16384;
constexpr uint32_t kCbDispatchRingSize = 32768;
CbEncoderNote g_cb_encoder_ring[kCbEncoderRingSize];
CbDispatchNote g_cb_dispatch_ring[kCbDispatchRingSize];
std::atomic<uint32_t> g_cb_encoder_next{0};
std::atomic<uint32_t> g_cb_dispatch_next{0};
IMP g_cb_render_imp, g_cb_compute_imp, g_cb_compute_type_imp, g_cb_blit_imp;
IMP g_enc_groups_imp, g_enc_threads_imp, g_enc_indirect_imp;
// XE_METAL_CB_BREADCRUMBS=1: before each encoder a one-byte blit marks its
// seq in a shared buffer (cleared by the CPU first), so after a timeout the
// encoders the GPU reached are known.
id<MTLBuffer> g_breadcrumbs;
uint8_t* g_breadcrumb_bytes;
constexpr uint32_t kBreadcrumbCount = 65536;

uint32_t BeginCbEncoder(id self) {
  const uint32_t seq =
      g_cb_encoder_next.fetch_add(1, std::memory_order_relaxed);
  if (g_breadcrumbs) {
    const uint32_t slot = seq % kBreadcrumbCount;
    g_breadcrumb_bytes[slot] = 0;
    id<MTLBlitCommandEncoder> blit =
        reinterpret_cast<id (*)(id, SEL)>(g_cb_blit_imp)(
            self, @selector(blitCommandEncoder));
    [blit fillBuffer:g_breadcrumbs range:NSMakeRange(slot, 1) value:1];
    [blit endEncoding];
  }
  return seq;
}

id NoteCbEncoder(id self, uint32_t seq, char kind, void* caller, id encoder) {
  CbEncoderNote& note = g_cb_encoder_ring[seq % kCbEncoderRingSize];
  note.seq = seq;
  note.command_buffer = (__bridge void*)self;
  note.encoder = (__bridge void*)encoder;
  note.caller = caller;
  note.kind = kind;
  return encoder;
}
void NoteDispatch(id encoder, char kind, void* caller, MTLSize groups,
                  MTLSize threads) {
  CbDispatchNote& note =
      g_cb_dispatch_ring[g_cb_dispatch_next.fetch_add(
                             1, std::memory_order_relaxed) %
                         kCbDispatchRingSize];
  note.encoder = (__bridge void*)encoder;
  note.caller = caller;
  note.seq = g_cb_encoder_next.load(std::memory_order_relaxed);
  note.groups[0] = uint32_t(groups.width);
  note.groups[1] = uint32_t(groups.height);
  note.groups[2] = uint32_t(groups.depth);
  note.threads[0] = uint32_t(threads.width);
  note.threads[1] = uint32_t(threads.height);
  note.threads[2] = uint32_t(threads.depth);
  note.kind = kind;
}
id CbRenderHook(id self, SEL sel, id desc) {
  const uint32_t seq = BeginCbEncoder(self);
  return NoteCbEncoder(
      self, seq, 'R', __builtin_return_address(0),
      reinterpret_cast<id (*)(id, SEL, id)>(g_cb_render_imp)(self, sel, desc));
}
id CbComputeHook(id self, SEL sel) {
  const uint32_t seq = BeginCbEncoder(self);
  return NoteCbEncoder(
      self, seq, 'C', __builtin_return_address(0),
      reinterpret_cast<id (*)(id, SEL)>(g_cb_compute_imp)(self, sel));
}
id CbComputeTypeHook(id self, SEL sel, NSUInteger type) {
  const uint32_t seq = BeginCbEncoder(self);
  return NoteCbEncoder(self, seq, 'C', __builtin_return_address(0),
                       reinterpret_cast<id (*)(id, SEL, NSUInteger)>(
                           g_cb_compute_type_imp)(self, sel, type));
}
id CbBlitHook(id self, SEL sel) {
  const uint32_t seq = BeginCbEncoder(self);
  return NoteCbEncoder(
      self, seq, 'B', __builtin_return_address(0),
      reinterpret_cast<id (*)(id, SEL)>(g_cb_blit_imp)(self, sel));
}
void EncGroupsHook(id self, SEL sel, MTLSize groups, MTLSize threads) {
  NoteDispatch(self, 'G', __builtin_return_address(0), groups, threads);
  reinterpret_cast<void (*)(id, SEL, MTLSize, MTLSize)>(g_enc_groups_imp)(
      self, sel, groups, threads);
}
void EncThreadsHook(id self, SEL sel, MTLSize grid, MTLSize threads) {
  NoteDispatch(self, 'T', __builtin_return_address(0), grid, threads);
  reinterpret_cast<void (*)(id, SEL, MTLSize, MTLSize)>(g_enc_threads_imp)(
      self, sel, grid, threads);
}
void EncIndirectHook(id self, SEL sel, id buffer, NSUInteger offset,
                     MTLSize threads) {
  NoteDispatch(self, 'I', __builtin_return_address(0),
               MTLSizeMake(NSUInteger(offset), 0, 0), threads);
  reinterpret_cast<void (*)(id, SEL, id, NSUInteger, MTLSize)>(
      g_enc_indirect_imp)(self, sel, buffer, offset, threads);
}

bool CbEncoderRingEnabled() {
  static const bool s_enabled = [] {
    const char* v = std::getenv("XE_METAL_CB_ENCODER_RING");
    return v && v[0] == '1';
  }();
  return s_enabled;
}

void HookMethod(Class cls, SEL sel, IMP imp, const char* types,
                IMP* original) {
  Method m = class_getInstanceMethod(cls, sel);
  if (!m) {
    return;
  }
  *original = method_getImplementation(m);
  class_replaceMethod(cls, sel, imp, types);
}

void InstallCbEncoderRing(id<MTLCommandQueue> queue) {
  if (!CbEncoderRingEnabled() || !queue || g_cb_blit_imp) {
    return;
  }
  id<MTLCommandBuffer> probe = [queue commandBuffer];
  Class cls = object_getClass(probe);
  id<MTLComputeCommandEncoder> probe_encoder = [probe computeCommandEncoder];
  Class encoder_cls = object_getClass(probe_encoder);
  [probe_encoder endEncoding];
  HookMethod(cls, @selector(renderCommandEncoderWithDescriptor:),
             IMP(CbRenderHook), "@@:@", &g_cb_render_imp);
  HookMethod(cls, @selector(computeCommandEncoder), IMP(CbComputeHook), "@@:",
             &g_cb_compute_imp);
  HookMethod(cls, @selector(computeCommandEncoderWithDispatchType:),
             IMP(CbComputeTypeHook), "@@:Q", &g_cb_compute_type_imp);
  HookMethod(cls, @selector(blitCommandEncoder), IMP(CbBlitHook), "@@:",
             &g_cb_blit_imp);
  HookMethod(encoder_cls, @selector(dispatchThreadgroups:threadsPerThreadgroup:),
             IMP(EncGroupsHook), "v@:{MTLSize=QQQ}{MTLSize=QQQ}",
             &g_enc_groups_imp);
  HookMethod(encoder_cls, @selector(dispatchThreads:threadsPerThreadgroup:),
             IMP(EncThreadsHook), "v@:{MTLSize=QQQ}{MTLSize=QQQ}",
             &g_enc_threads_imp);
  HookMethod(encoder_cls,
             @selector(dispatchThreadgroupsWithIndirectBuffer:
                                          indirectBufferOffset:
                                         threadsPerThreadgroup:),
             IMP(EncIndirectHook), "v@:@Q{MTLSize=QQQ}", &g_enc_indirect_imp);
  if (const char* v = std::getenv("XE_METAL_CB_BREADCRUMBS");
      v && v[0] == '1') {
    g_breadcrumbs = [queue.device newBufferWithLength:kBreadcrumbCount
                                              options:MTLResourceStorageModeShared];
    g_breadcrumb_bytes = static_cast<uint8_t*>(g_breadcrumbs.contents);
  }
  Dl_info info = {};
  dladdr(reinterpret_cast<void*>(&InstallCbEncoderRing), &info);
  REXLOG_WARN("MetalCbEncoderRing: hooked {} + {} (image base {})",
         class_getName(cls), class_getName(encoder_cls), info.dli_fbase);
}

void LogCbEncoders(id<MTLCommandBuffer> command_buffer) {
  if (!CbEncoderRingEnabled()) {
    return;
  }
  void* cb = (__bridge void*)command_buffer;
  const uint32_t next = g_cb_encoder_next.load(std::memory_order_relaxed);
  const uint32_t dispatch_next =
      g_cb_dispatch_next.load(std::memory_order_relaxed);
  std::string line;
  uint32_t n = 0;
  for (uint32_t i = 0; i < kCbEncoderRingSize; ++i) {
    const CbEncoderNote& note =
        g_cb_encoder_ring[(next + i) % kCbEncoderRingSize];
    if (note.command_buffer != cb) {
      continue;
    }
    if (++n > 300) {
      line += " ...";
      break;
    }
    line += fmt::format(" {}{}{}", note.kind, note.caller,
                        !g_breadcrumbs ? ""
                        : g_breadcrumb_bytes[note.seq % kBreadcrumbCount]
                            ? "+"
                            : "-");
    if (note.kind != 'C' || !note.encoder) {
      continue;
    }
    // This encoder's dispatches: encoder objects are recycled, so only
    // those after its creation and before the pointer's next creation.
    uint32_t reuse_seq = UINT32_MAX;
    for (uint32_t j = 0; j < kCbEncoderRingSize; ++j) {
      const CbEncoderNote& other = g_cb_encoder_ring[j];
      if (other.encoder == note.encoder && other.seq > note.seq &&
          other.seq < reuse_seq) {
        reuse_seq = other.seq;
      }
    }
    uint32_t dispatches = 0;
    for (uint32_t j = 0; j < kCbDispatchRingSize; ++j) {
      const CbDispatchNote& d =
          g_cb_dispatch_ring[(dispatch_next + j) % kCbDispatchRingSize];
      if (d.encoder != note.encoder || d.seq <= note.seq ||
          d.seq > reuse_seq) {
        continue;
      }
      if (++dispatches > 4) {
        continue;
      }
      line += fmt::format("[{}{} {}x{}x{}/{}x{}x{}]", d.kind, d.caller,
                          d.groups[0], d.groups[1], d.groups[2], d.threads[0],
                          d.threads[1], d.threads[2]);
    }
    if (dispatches > 4) {
      line += fmt::format("[+{}]", dispatches - 4);
    }
  }
  REXLOG_ERROR("  encoders ({}):{}", n, line);
}
}  // namespace

static void LogCommandBufferFault(id<MTLCommandBuffer> command_buffer,
                                  const char* site, uint32_t swap_count,
                                  uint64_t submission, uint64_t episode) {
  LogCbEncoders(command_buffer);
  NSError* err = command_buffer.error;
  REXLOG_ERROR("Metal GPU FAULT ({}, swap#{}, episode={}, submission={}): {} "
         "(code {})", site,
         swap_count, episode, submission,
         err.localizedDescription ? err.localizedDescription.UTF8String
                                  : "(no description)",
         err ? long(err.code) : -1L);
  NSArray<id<MTLCommandBufferEncoderInfo>>* infos =
      err.userInfo[MTLCommandBufferEncoderInfoErrorKey];
  // The command buffer's label and the device-wide GPU allocation at the time
  // of the fault: an "Insufficient ::rex::IPhysicalMemory" completion is a per-submission
  // allocation failure, and both the submission's size (encoder count) and the
  // process's GPU-resident volume are needed to tell a volume problem from a
  // transient one.
  REXLOG_ERROR("  command buffer '{}': {} encoders, device allocated {} MB, "
         "kernel {:.3f}-{:.3f} s, GPU {:.3f}-{:.3f} s",
         command_buffer.label ? command_buffer.label.UTF8String
                              : "(unlabeled)",
         infos ? uint32_t(infos.count) : 0u,
         command_buffer.device
             ? uint64_t(command_buffer.device.currentAllocatedSize) >> 20
             : 0ull,
         command_buffer.kernelStartTime, command_buffer.kernelEndTime,
         command_buffer.GPUStartTime, command_buffer.GPUEndTime);
  // Every key the driver attached, in case it carries more than the encoder
  // status (e.g. a resource or address for a memory fault).
  for (NSString* key in err.userInfo) {
    if ([key isEqualToString:MTLCommandBufferEncoderInfoErrorKey]) {
      continue;
    }
    NSString* value = [err.userInfo[key] description];
    REXLOG_ERROR("  userInfo[{}] = {}", key.UTF8String,
           value ? value.UTF8String : "(nil)");
  }
  auto state_name = [](id<MTLCommandBufferEncoderInfo> info) {
    switch (info.errorState) {
      case MTLCommandEncoderErrorStateCompleted: return "completed";
      case MTLCommandEncoderErrorStateAffected: return "AFFECTED";
      case MTLCommandEncoderErrorStateUnknown: return "unknown";
      case MTLCommandEncoderErrorStatePending: return "pending";
      case MTLCommandEncoderErrorStateFaulted: return "FAULTED";
    }
    return "unknown";
  };
  uint32_t index = 0;
  for (id<MTLCommandBufferEncoderInfo> info in infos) {
    // Only the interesting ones — a frame can have hundreds of completed
    // encoders. Each is logged with its position and the labels of the two
    // encoders before and after it, so an unlabeled faulted encoder can be
    // placed inside the submission.
    if (info.errorState != MTLCommandEncoderErrorStateCompleted) {
      // Carry the serial on every encoder line too, so encoder attributions
      // can be grouped by the submission they belong to without re-parsing
      // the surrounding header.
      REXLOG_ERROR("  encoder '{}' [#{}/{}]: {} (episode={} submission={})",
             info.label ? info.label.UTF8String : "(unlabeled)", index,
             uint32_t(infos.count), state_name(info), episode, submission);
      const uint32_t lo = index >= 2 ? index - 2 : 0;
      const uint32_t hi = std::min<uint32_t>(uint32_t(infos.count), index + 3);
      for (uint32_t i = lo; i < hi; ++i) {
        if (i == index) {
          continue;
        }
        id<MTLCommandBufferEncoderInfo> near = infos[i];
        REXLOG_ERROR("    neighbour #{} '{}': {}", i,
               near.label ? near.label.UTF8String : "(unlabeled)",
               state_name(near));
      }
    }
    ++index;
  }
}

// XE_METAL_MEMEXPORT_MERGE=0 restores whole-range memexport publication.
static bool MemexportMergeEnabled() {
  static const bool s_merge = metal::ParseMetalEnvironmentFlag(
      std::getenv("XE_METAL_MEMEXPORT_MERGE"), true);
  return s_merge;
}

uint64_t MetalCommandProcessor::StageHazardUpload(uint32_t offset,
                                                  uint32_t length) {
  if (!length || !shared_memory_) {
    return 0;
  }
  id<MTLBuffer> shared = (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
  if (!shared || uint64_t(offset) + length > shared.length) {
    return 0;
  }
  const void* source = static_cast<const void*>(static_cast<const uint8_t*>(shared_memory_->GetCpuBuffer()) + offset);
  if (!source) {
    return 0;
  }
  void* cb_ptr = PrepareTransferCommandBuffer(
      uint32_t(metal::MetalTransferSite::kHazardUpload));
  if (!cb_ptr) {
    return 0;
  }
  id<MTLCommandBuffer> command_buffer = (__bridge id<MTLCommandBuffer>)cb_ptr;
  id<MTLBuffer> staging =
      [shared.device newBufferWithBytes:source
                                 length:length
                                options:MTLResourceStorageModeShared];
  if (!staging) {
    return 0;
  }
  id<MTLBlitCommandEncoder> blit = [command_buffer blitCommandEncoder];
  if (!blit) {
    return 0;
  }
  blit.label = @"staged hazard upload";
  [blit copyFromBuffer:staging
          sourceOffset:0
              toBuffer:shared
     destinationOffset:offset
                  size:length];
  [blit endEncoding];
  // The staging buffer lives until the blit has executed.
  [command_buffer addCompletedHandler:^(id<MTLCommandBuffer> cb) {
    (void)cb;
    (void)staging;
  }];
  if (MemexportMergeEnabled() && false) {
    const uint64_t completed =
        completed_submission_.load(std::memory_order_acquire);
    while (!staged_upload_images_.empty() &&
           staged_upload_images_.front().submission <= completed) {
      staged_upload_images_.pop_front();
    }
    constexpr size_t kMaxStagedUploadImages = 1024;
    if (staged_upload_images_.size() >= kMaxStagedUploadImages) {
      staged_upload_images_dropped_through_ = std::max(
          staged_upload_images_dropped_through_,
          staged_upload_images_.front().submission);
      staged_upload_images_.pop_front();
    }
    const uint8_t* bytes = static_cast<const uint8_t*>(source);
    staged_upload_images_.push_back(StagedUploadImage{
        offset, CurrentEncodingSubmission(),
        std::make_shared<const std::vector<uint8_t>>(bytes, bytes + length)});
  }
  return CurrentEncodingSubmission();
}

void MetalCommandProcessor::EndDiscreteUploadBlit() {
  if (!discrete_upload_blit_) {
    return;
  }
  id<MTLBlitCommandEncoder> blit =
      (__bridge_transfer id<MTLBlitCommandEncoder>)discrete_upload_blit_;
  discrete_upload_blit_ = nullptr;
  [blit endEncoding];
}

// Blit copies on macOS need 4-byte aligned offsets and sizes. Uploads are
// page pieces and vfetch renames are 4-byte multiples; a stray unaligned
// edge widens to the enclosing words (the CPU mirror holds the same bytes
// the GPU copy should, outside GPU-produced spans).
static inline void AlignBlitRange(uint32_t& offset, uint32_t& length,
                                  uint64_t limit) {
  uint64_t start = offset & ~uint64_t(3);
  uint64_t end = (uint64_t(offset) + length + 3) & ~uint64_t(3);
  end = std::min(end, limit);
  offset = uint32_t(start);
  length = uint32_t(end - start);
}

void MetalCommandProcessor::EncodeDiscreteMirrorUpload(uint32_t offset,
                                                       uint32_t length) {
  id<MTLBuffer> cpu = (__bridge id<MTLBuffer>)shared_memory_->GetCpuBuffer();
  id<MTLBuffer> gpu = (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
  if (!cpu || !gpu || cpu == gpu) {
    return;
  }
  AlignBlitRange(offset, length, gpu.length);
  if (!length) {
    return;
  }
  if (!frame_command_buffer_ &&
      !PrepareTransferCommandBuffer(
          uint32_t(metal::MetalTransferSite::kHazardUpload))) {
    REXLOG_ERROR("MetalSharedMemory: no command buffer for a VRAM upload");
    return;
  }
  if (!discrete_upload_blit_) {
    id<MTLCommandBuffer> side =
        (__bridge id<MTLCommandBuffer>)EnsureSideCommandBuffer();
    if (!side) {
      REXLOG_ERROR("MetalSharedMemory: no side command buffer for a VRAM upload");
      return;
    }
    id<MTLBlitCommandEncoder> blit = [side blitCommandEncoder];
    if (!blit) {
      return;
    }
    blit.label = @"shared memory upload";
    discrete_upload_blit_ = (__bridge_retained void*)blit;
  }
  id<MTLBlitCommandEncoder> blit =
      (__bridge id<MTLBlitCommandEncoder>)discrete_upload_blit_;
  [blit copyFromBuffer:cpu
          sourceOffset:offset
              toBuffer:gpu
     destinationOffset:offset
                  size:length];
  ++discrete_upload_blits_;
  discrete_upload_bytes_ += length;
}

void MetalCommandProcessor::NoteDiscreteProducedResolve(uint32_t start,
                                                        uint32_t length) {
  if (!discrete_mirror_ || !length) {
    return;
  }
  if (false &&
      !shared_memory_->IsVramHot(start)) {
    shared_memory_->MarkVramNewer(start, length, CurrentEncodingSubmission(),
                                  /*eager=*/false);
    ++discrete_deferred_ranges_;
    return;
  }
  discrete_produced_ranges_.emplace_back(start, length);
}

void MetalCommandProcessor::EncodeDiscreteMirrorReadback(void* command_buffer,
                                                         uint64_t submission) {
  if (discrete_produced_ranges_.empty()) {
    return;
  }
  id<MTLBuffer> cpu = (__bridge id<MTLBuffer>)shared_memory_->GetCpuBuffer();
  id<MTLBuffer> gpu = (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
  if (!cpu || !gpu || cpu == gpu) {
    discrete_produced_ranges_.clear();
    return;
  }
  // Merge overlapping and touching ranges (resolves to one target repeat).
  auto& ranges = discrete_produced_ranges_;
  std::sort(ranges.begin(), ranges.end());
  std::vector<std::pair<uint32_t, uint32_t>> merged;
  merged.reserve(ranges.size());
  for (const auto& r : ranges) {
    uint64_t start = r.first, end = uint64_t(r.first) + r.second;
    if (!merged.empty() &&
        start <= uint64_t(merged.back().first) + merged.back().second) {
      uint64_t back_end = uint64_t(merged.back().first) + merged.back().second;
      merged.back().second = uint32_t(std::max(back_end, end) - merged.back().first);
    } else {
      merged.emplace_back(uint32_t(start), uint32_t(end - start));
    }
  }
  ranges.clear();
  id<MTLCommandBuffer> cb = (__bridge id<MTLCommandBuffer>)command_buffer;
  id<MTLBlitCommandEncoder> blit = [cb blitCommandEncoder];
  if (!blit) {
    return;
  }
  blit.label = @"shared memory readback";
  for (auto r : merged) {
    uint32_t offset = r.first, length = r.second;
    AlignBlitRange(offset, length, gpu.length);
    if (!length) {
      continue;
    }
    [blit copyFromBuffer:gpu
            sourceOffset:offset
                toBuffer:cpu
       destinationOffset:offset
                    size:length];
    // An upload over these bytes while the readback is in flight must not
    // memcpy into the CPU mirror the blit is about to overwrite: as a
    // consumed range of this submission it takes the staged-blit path.
    shared_memory_->NoteGpuWriteInFlight(offset, length, submission);
    // An on-demand fetch overlapping it waits for this submission first.
    shared_memory_->MarkVramNewer(offset, length, submission, /*eager=*/true);
    ++discrete_readback_blits_;
    discrete_readback_bytes_ += length;
  }
  [blit endEncoding];
}

void* MetalCommandProcessor::PrepareTransferCommandBuffer(uint32_t site) {
  // A transfer is a pass boundary: close the open render encoder; ensure the
  // frame command buffer exists so the blits order before the next pass.
  EndRenderEncoder(metal::MetalPassEndReason::kTransfer, site);
  if (!frame_command_buffer_) {
    auto* provider =
        static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider());
    if (!provider || !provider->command_queue()) {
      return nullptr;
    }
    if (S7ArenaResetOff() && upload_arena_) {
      upload_arena_->Reset();
    }
    id<MTLCommandQueue> queue =
        (__bridge id<MTLCommandQueue>)provider->command_queue();
    id<MTLCommandBuffer> command_buffer = MakeAttributedCommandBuffer(queue);
    frame_command_buffer_ = (__bridge_retained void*)command_buffer;
  }
  return frame_command_buffer_;
}

void MetalCommandProcessor::WriteRegister(uint32_t index, uint32_t value) {
  // Texture fetch constants: 32 of 6 dwords from 0x4800
  // (XE_GPU_REG_SHADER_CONSTANT_FETCH_00_0). Mark the slot for the draw prep.
  constexpr uint32_t kFetchBase = 0x4800u;
  constexpr uint32_t kFetchEnd = kFetchBase + 32u * 6u;
  if (index >= kFetchBase && index < kFetchEnd &&
      register_file_->values[index] != value) {
    // Titles re-upload the whole fetch block before most draws; only a
    // changed dword makes the binding worth re-parsing.
    const uint32_t slot = (index - kFetchBase) / 6u;
    fetch_constant_dirty_mask_ |= 1u << slot;
    fetch_plain_known_mask_ &= ~(1u << slot);
    bind_memo_fetch_written_ |= 1u << slot;
  }
  CommandProcessor::WriteRegister(index, value);
}

void MetalCommandProcessor::OnRegistersRestoredRaw(uint32_t first_register,
                                                   uint32_t register_count) {
  // Trace playback restores register snapshots without WriteRegister: every
  // fetch constant in the range is dirty and its cached sign/plain state stale.
  constexpr uint32_t kFetchBase = 0x4800u;
  constexpr uint32_t kFetchEnd = kFetchBase + 32u * 6u;
  const uint32_t first = std::max(first_register, kFetchBase);
  const uint32_t end = std::min(first_register + register_count, kFetchEnd);
  if (first >= end) {
    return;
  }
  for (uint32_t slot = (first - kFetchBase) / 6u;
       slot <= (end - 1u - kFetchBase) / 6u; ++slot) {
    fetch_constant_dirty_mask_ |= 1u << slot;
    fetch_plain_known_mask_ &= ~(1u << slot);
    bind_memo_fetch_written_ |= 1u << slot;
  }
}

void* MetalCommandProcessor::PrepareSideTransferCommandBuffer() {
  // The caller encodes its own pass on the side buffer: an open discrete
  // mirror upload blit must end first (encode order is execution order, so
  // the load still sees the bytes uploaded before it).
  EndDiscreteUploadBlit();
  return EnsureSideCommandBuffer();
}

void* MetalCommandProcessor::EnsureSideCommandBuffer() {
  // No pass boundary: the side buffer is committed ahead of the frame one
  // (CommitSideCommandBuffer), so a load encoded here executes before every
  // draw of this submission. Only valid while a frame command buffer exists,
  // or the ordering claim has nothing to be ahead of.
  if (!frame_command_buffer_) {
    return nullptr;
  }
  if (!side_command_buffer_) {
    auto* provider =
        static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider());
    if (!provider || !provider->command_queue()) {
      return nullptr;
    }
    id<MTLCommandQueue> queue =
        (__bridge id<MTLCommandQueue>)provider->command_queue();
    id<MTLCommandBuffer> command_buffer = MakeAttributedCommandBuffer(queue);
    if (!command_buffer) {
      return nullptr;
    }
    command_buffer.label = @"side loads";
    side_command_buffer_ = (__bridge_retained void*)command_buffer;
  }
  return side_command_buffer_;
}

void MetalCommandProcessor::CommitSideCommandBuffer(uint64_t submission,
                                                    uint64_t submit_epoch) {
  EndDiscreteUploadBlit();
  if (!side_command_buffer_) {
    return;
  }
  id<MTLCommandBuffer> command_buffer =
      (__bridge_transfer id<MTLCommandBuffer>)side_command_buffer_;
  side_command_buffer_ = nullptr;
  // A fault here is a fault of the submission whose textures it loaded: the
  // same record the frame buffer's handler writes (minus the epoch
  // reservation, which the frame buffer owns), so DrainFaultedCommandBuffers
  // invalidates the routed textures of this submission as usual.
  [command_buffer addCompletedHandler:^(id<MTLCommandBuffer> cb) {
    if (cb.status == MTLCommandBufferStatusError && submission) {
      std::lock_guard<std::mutex> lock(fault_mutex_);
      faulted_completions_.push_back(
          FaultedCompletion{(__bridge_retained void*)cb, submission,
                            submit_epoch});
    }
  }];
  [command_buffer commit];
}

