// Crash-capture: JC2-on-Metal aborts recurrently via _objc_terminate — an
// uncaught ObjC/Metal exception (e.g. an MTL validation error thrown from a
// background thread) whose MESSAGE is lost in the bare abort. ObjC exceptions
// are thrown through the C++ ABI on arm64, so std::current_exception() captures
// the NSException and it can be @caught and logged. Installed once at Metal
// backend setup; chains to the previous handler so behavior is otherwise
// unchanged. Pair with MTL_DEBUG_LAYER=1 (and MallocGuardEdges for the
// separate double-free track) when hunting the abort on-device.
namespace {
std::terminate_handler g_prev_terminate = nullptr;
void MetalTerminateHandler() {
  std::exception_ptr eptr = std::current_exception();
  if (eptr) {
    // @catch only accepts ObjC pointer types; route everything else back
    // through a nested C++ catch to recover the std::exception message.
    @try {
      std::rethrow_exception(eptr);
    } @catch (NSException* ex) {
      REXLOG_ERROR("Metal FATAL: uncaught NSException {}: {}",
             ex.name ? ex.name.UTF8String : "(null)",
             ex.reason ? ex.reason.UTF8String : "(null)");
      fprintf(stderr, "Metal FATAL: uncaught NSException %s: %s\n",
              ex.name ? ex.name.UTF8String : "(null)",
              ex.reason ? ex.reason.UTF8String : "(null)");
      for (NSString* frame in ex.callStackSymbols) {
        REXLOG_ERROR("  {}", frame.UTF8String);
      }
    } @catch (...) {
      try {
        std::rethrow_exception(eptr);
      } catch (const std::exception& e) {
        REXLOG_ERROR("Metal FATAL: uncaught std::exception: {}", e.what());
      } catch (...) {
        REXLOG_ERROR("Metal FATAL: uncaught non-standard exception");
      }
    }
  }
  if (g_prev_terminate) {
    g_prev_terminate();
  }
  std::abort();
}
void InstallMetalCrashCapture() {
  static bool s_installed = false;
  if (s_installed) {
    return;
  }
  s_installed = true;
  g_prev_terminate = std::set_terminate(&MetalTerminateHandler);
}

// XE_METAL_TESS_DRAW_RANGE (bisection diagnostic, default unset = all): the
// tessellation route engages only for the selected trace draw indices; every
// other tessellated draw behaves exactly as the gate-OFF arm (skipped
// downstream). Proven tool for bisecting a defective tessellated draw out of
// a frame.
// Selector syntax: "a,b" inclusive range, or "L:a,b,c,..." exact index list.
bool TessDrawRangeAllows(uint32_t draw_index) {
  struct Selector {
    std::pair<uint32_t, uint32_t> range{0u, 0xFFFFFFFFu};
    std::vector<uint32_t> list;  // non-empty = list mode.
  };
  static const Selector selector = [] {
    Selector s;
    if (const char* v = std::getenv("XE_METAL_TESS_DRAW_RANGE")) {
      if (v[0] == 'L' && v[1] == ':') {
        const char* p = v + 2;
        while (*p) {
          s.list.push_back(uint32_t(strtoul(p, const_cast<char**>(&p), 10)));
          if (*p == ',') ++p;
        }
        REXLOG_WARN("TessDrawRange ENGAGED: list of {}", s.list.size());
      } else {
        unsigned a = 0, b = 0;
        if (std::sscanf(v, "%u,%u", &a, &b) == 2) {
          s.range = {a, b};
          REXLOG_WARN("TessDrawRange ENGAGED: [{},{}]", a, b);
        }
      }
    }
    return s;
  }();
  if (!selector.list.empty()) {
    return std::find(selector.list.begin(), selector.list.end(), draw_index) !=
           selector.list.end();
  }
  return draw_index >= selector.range.first &&
         draw_index <= selector.range.second;
}

}  // namespace

// XE_METAL_VALIDATION_OFF_OTHER=compute|render|all (diagnostic, with
// MTL_SHADER_VALIDATION=1): pipelines other than the guest draw pipelines
// (which XE_METAL_VALIDATION_OFF sets explicitly) are created without shader
// validation, by hooking the device's pipeline-creation methods. Compute
// pipelines here are built from bare functions, which carry no per-pipeline
// validation setting, so the hook rebuilds them from a descriptor. Returns
// pass through as raw pointers: these are "new" methods (+1 references).
namespace {
IMP g_validation_off_render = nullptr;
IMP g_validation_off_render_options = nullptr;
std::atomic<uint32_t> g_validation_off_logged{0};

void LogValidationOffPipeline(const char* kind, void* state) {
  if (!state ||
      g_validation_off_logged.fetch_add(1, std::memory_order_relaxed) >= 32) {
    return;
  }
  if (@available(macOS 15.0, *)) {
    id object = (__bridge id)state;
    MTLShaderValidation validation = MTLShaderValidationDefault;
    if ([object conformsToProtocol:@protocol(MTLComputePipelineState)]) {
      validation = ((id<MTLComputePipelineState>)object).shaderValidation;
    } else if ([object conformsToProtocol:@protocol(MTLRenderPipelineState)]) {
      validation = ((id<MTLRenderPipelineState>)object).shaderValidation;
    }
    REXLOG_INFO("MetalValidationOffOther: {} pipeline created, shaderValidation={}",
           kind, int(validation));
  }
}

void* ValidationOffComputeFromFunction(__unsafe_unretained id self, SEL,
                                       __unsafe_unretained id function,
                                       NSError* __autoreleasing* error) {
  void* state = nullptr;
  if (@available(macOS 15.0, *)) {
    MTLComputePipelineDescriptor* descriptor =
        [[MTLComputePipelineDescriptor alloc] init];
    descriptor.computeFunction = function;
    descriptor.shaderValidation = MTLShaderValidationDisabled;
    state = ((void* (*)(id, SEL, id, NSUInteger, id*, NSError* __autoreleasing*))
                 objc_msgSend)(
        self,
        @selector(newComputePipelineStateWithDescriptor:options:reflection:error:),
        descriptor, MTLPipelineOptionNone, nullptr, error);
  }
  LogValidationOffPipeline("compute", state);
  return state;
}

void* ValidationOffRender(__unsafe_unretained id self, SEL selector,
                          __unsafe_unretained MTLRenderPipelineDescriptor* desc,
                          NSError* __autoreleasing* error) {
  if (@available(macOS 15.0, *)) {
    if (desc.shaderValidation == MTLShaderValidationDefault) {
      desc.shaderValidation = MTLShaderValidationDisabled;
    }
  }
  void* state = ((void* (*)(id, SEL, id, NSError* __autoreleasing*))
                     g_validation_off_render)(self, selector, desc, error);
  LogValidationOffPipeline("render", state);
  return state;
}

void* ValidationOffRenderOptions(
    __unsafe_unretained id self, SEL selector,
    __unsafe_unretained MTLRenderPipelineDescriptor* desc,
    MTLPipelineOption options, id* reflection,
    NSError* __autoreleasing* error) {
  if (@available(macOS 15.0, *)) {
    if (desc.shaderValidation == MTLShaderValidationDefault) {
      desc.shaderValidation = MTLShaderValidationDisabled;
    }
  }
  void* state =
      ((void* (*)(id, SEL, id, MTLPipelineOption, id*,
                  NSError* __autoreleasing*))g_validation_off_render_options)(
          self, selector, desc, options, reflection, error);
  LogValidationOffPipeline("render", state);
  return state;
}

void InstallValidationOffHooks(id<MTLDevice> device) {
  static bool s_installed = false;
  const char* mode = std::getenv("XE_METAL_VALIDATION_OFF_OTHER");
  if (s_installed || !mode || !device) {
    return;
  }
  s_installed = true;
  const bool compute = !std::strcmp(mode, "compute") || !std::strcmp(mode, "all");
  const bool render = !std::strcmp(mode, "render") || !std::strcmp(mode, "all");
  Class device_class = object_getClass(device);
  if (compute) {
    SEL selector = @selector(newComputePipelineStateWithFunction:error:);
    Method method = class_getInstanceMethod(device_class, selector);
    if (method) {
      class_replaceMethod(device_class, selector,
                          (IMP)ValidationOffComputeFromFunction,
                          method_getTypeEncoding(method));
    }
  }
  if (render) {
    SEL selector = @selector(newRenderPipelineStateWithDescriptor:error:);
    Method method = class_getInstanceMethod(device_class, selector);
    if (method) {
      g_validation_off_render =
          class_getMethodImplementation(device_class, selector);
      class_replaceMethod(device_class, selector, (IMP)ValidationOffRender,
                          method_getTypeEncoding(method));
    }
    SEL options_selector =
        @selector(newRenderPipelineStateWithDescriptor:options:reflection:error:);
    Method options_method =
        class_getInstanceMethod(device_class, options_selector);
    if (options_method) {
      g_validation_off_render_options =
          class_getMethodImplementation(device_class, options_selector);
      class_replaceMethod(device_class, options_selector,
                          (IMP)ValidationOffRenderOptions,
                          method_getTypeEncoding(options_method));
    }
  }
  REXLOG_INFO("MetalValidationOffOther: {} on {} (compute={} render={})", mode,
         class_getName(device_class), compute, render);
}
}  // namespace

bool MetalCommandProcessor::SetupContext() {
  encode_stream_ = std::make_unique<MetalEncodeStream>();
  encode_stream_->Start(MetalEncodeStream::ModeFromEnvironment());
  // Effective submission/lifetime mode banner: config sessions were getting
  // misidentified from fps profiles alone — the log states the truth.
  REXLOG_INFO(
      "MetalCommandProcessor: MODE submission={} arena={} ({} MB) retire-tags={}",
      (std::getenv("XE_METAL_SYNC_WAIT") || !AsyncSubmissionEnabled())
          ? "SYNC-WAIT"
          : "async",
      S7ArenaResetOff() ? "reset-per-buffer" : "ring",
      UploadArenaSize() / (1024 * 1024), S7TagsOff() ? "OFF" : "on");
  if (!::rex::gpu::CommandProcessor::SetupContext()) {
    return false;
  }
  gpu_thread_id_ = std::this_thread::get_id();
  InstallMetalCrashCapture();
  // Surface active debug toggles prominently so logs are self-describing.
  static const char* kDebugEnvs[] = {
      "XE_METAL_DISABLE_GEO",    "XE_METAL_NO_SIGNS",
      "XE_METAL_NO_CENTROID",    "XE_METAL_NO_SMALL_DEPTH",
      "XE_METAL_NO_WRITEBACK",   "XE_METAL_WB_HOLD",
      "XE_METAL_SERIALIZE_RESOLVES", "XE_METAL_FLUSH_ALL_UPLOADS",
      "XE_METAL_FAULT_INJECT",  "XE_METAL_EXPO_TRACE",
      "XE_METAL_CHAIN_TRACE",   "XE_METAL_NO_RESOLVE_COMMIT",
      "XE_METAL_COLOR_BRIDGE",  "XE_METAL_STAGE3",
      "XE_METAL_SAMPLE_EDRAM",  "XE_METAL_SAMPLE_EDRAM_RASTER",
      "XE_METAL_CROSSMSAA_SHADOW",
      "XE_METAL_SAMPLE_EDRAM_FULL_SYNC",
      "XE_METAL_SAMPLE_EDRAM_SELF_CHECK",
      "XE_METAL_CANONICAL_DEPTH",
      "XE_METAL_MEMEXPORT",
      "XE_METAL_DUMP_RT",
      "XE_METAL_PRESENT_BASE",   "XE_METAL_PEEK",
      "XE_METAL_DUMP_PS",
  };
  for (const char* env : kDebugEnvs) {
    if (const char* value = std::getenv(env)) {
      REXLOG_WARN("MetalCommandProcessor: DEBUG TOGGLE {}={}", env, value);
    }
  }
  auto* provider =
      static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider());
  void* device = provider ? provider->device() : nullptr;
  InstallValidationOffHooks((__bridge id<MTLDevice>)device);
  if (provider) {
    InstallCbEncoderRing(
        (__bridge id<MTLCommandQueue>)provider->command_queue());
  }
  if (!device) {
    REXLOG_ERROR("MetalCommandProcessor: no Metal device from provider");
    return false;
  }
  {
    // implement-metal-draw-resolution-scaling: draw_resolution_scale_x/y
    // (1..3 per axis on Metal) apply at session start.
    // XE_METAL_DRAW_RESOLUTION_SCALE=0 is the kill switch that keeps every
    // session at 1x whatever the configuration says.
    const char* kill_value = std::getenv("XE_METAL_DRAW_RESOLUTION_SCALE");
    const bool scaling_killed = kill_value && kill_value[0] == '0';
    // Scaling exists only on the canonical EDRAM raster path; its rollbacks
    // keep the session at 1x.
    const bool canonical_raster =
        MetalRenderTargetCache::CanonicalRasterConfigured();
    const bool scaled_rendering_enabled = !scaling_killed && canonical_raster;
    const metal::MetalDrawResolutionScale scale =
        metal::ResolveMetalDrawResolutionScale(GetGraphicsDriver().GetResolutionScaleX(),
                                               GetGraphicsDriver().GetResolutionScaleY(),
                                               scaled_rendering_enabled);
    if (scale.clamped) {
      REXLOG_WARN(
          "MetalCommandProcessor: draw resolution scale {}x{} clamped to {}x{} "
          "(the Metal renderer supports 1 to {} per axis)",
          GetGraphicsDriver().GetResolutionScaleX(), GetGraphicsDriver().GetResolutionScaleY(),
          scale.requested_x, scale.requested_y,
          metal::kMetalMaxDrawResolutionScale);
    }
    if (scale.x != scale.requested_x || scale.y != scale.requested_y) {
      REXLOG_WARN(
          "MetalCommandProcessor: draw resolution scale {}x{} requested; "
          "rendering at 1x ({})",
          scale.requested_x, scale.requested_y,
          scaling_killed ? "XE_METAL_DRAW_RESOLUTION_SCALE=0"
                         : "canonical EDRAM raster disabled by "
                           "XE_METAL_SAMPLE_EDRAM / _RASTER");
    } else if (scale.x != 1 || scale.y != 1) {
      REXLOG_INFO("MetalCommandProcessor: draw resolution scale {}x{}", scale.x,
             scale.y);
    }
    draw_resolution_scale_x_ = scale.x;
    draw_resolution_scale_y_ = scale.y;
    zpd_draw_resolution_scale_x_ = scale.x;
    zpd_draw_resolution_scale_y_ = scale.y;
  }
  pipeline_cache_ = std::make_unique<MetalPipelineCache>(
      device, GetXenosSettings(), draw_resolution_scale_x_, draw_resolution_scale_y_);
  if (!pipeline_cache_->Initialize()) {
    REXLOG_ERROR("MetalCommandProcessor: pipeline cache init failed");
    return false;
  }
  render_target_cache_ = std::make_unique<MetalRenderTargetCache>(
      *register_file_, physical_memory_, GetXenosSettings(), *this, device,
      draw_resolution_scale_x_, draw_resolution_scale_y_);
  if (!render_target_cache_->Initialize()) {
    REXLOG_ERROR("MetalCommandProcessor: render target cache init failed");
    return false;
  }
  // Zero-copy runtime cost evidence (pre-gate tasks 6.3/6.4), parsed ONCE with
  // the same exact-"1" rule the alias gate uses. Enabled before the shared
  // memory exists so no production operation can run un-metered in an enabled
  // run, and left disabled -- hence structurally inert -- for every other value.
  zero_copy_cost_.SetEnabled(
      metal::IsZeroCopyReportEnabled(std::getenv(metal::kZeroCopyReportEnvVar)));
  shared_memory_ = std::make_unique<MetalSharedMemory>(physical_memory_, write_watch_, device);
  shared_memory_->SetSubmissionProvider([this]() {
    return S7TagsOff() ? 0 : CurrentEncodingSubmission();
  });
  // Zero-copy overlap evidence (pre-gate tasks 5.1/5.2). Installed before
  // Initialize so the observer is armed before the physical invalidation
  // callback exists, and never reassigned afterwards -- the faulting guest
  // thread reads one of them.
  //
  // The execution provider is NOT the S7-governed one above. That one returns 0
  // whenever S7TagsOff() is true, which is every default launch, and zero is
  // the observer's idle sentinel: reusing it would stamp every page "unclaimed"
  // and make the overlap counter permanently zero for a reason unrelated to
  // whether an overlap occurred. This one always reports the real encoding
  // submission.
  shared_memory_->SetOverlapSubmissionProvider(
      [this]() { return CurrentEncodingSubmission(); });
  // The completion source, independent of the stamps: one acquire load of the
  // high-water mark the submission-completion handler publishes.
  shared_memory_->SetOverlapCompletedSubmissionProvider([this]() {
    return completed_submission_.load(std::memory_order_acquire);
  });
  if (!shared_memory_->Initialize()) {
    REXLOG_ERROR("MetalCommandProcessor: shared memory init failed");
    return false;
  }
  // Not validated under frame-trace capture/playback (they restore and
  // record the CPU mirror directly); a live-play setting.
  discrete_mirror_ = shared_memory_->is_discrete_mirror();
  // Intra-frame rewrite hazard: commit + wait the open frame so already-
  // encoded draws consume the pre-rewrite bytes (also resets the consumed-
  // range set). Runs from inside RequestConsumedRange, which is only called
  // before the draw's encoder opens.
  // Must WAIT: the caller is about to memcpy over shared-buffer ranges that
  // in-flight submissions read.
  shared_memory_->SetHazardFlushCallback([this]() {
    EndFrameEncoderAndWait(metal::SeamBoundaryReason::kHazardFlush);
  });
  // Stage 3 (optimize-metal-gpu-resident-resolve-coherence): the hazard
  // no longer waits. The open buffer is committed (its draws read the old
  // bytes at execution) and the new bytes ride a blit in the next buffer.
  shared_memory_->SetHazardCommitCallback([this]() {
    EndFrameEncoder(metal::SeamBoundaryReason::kHazardFlush);
  });
  shared_memory_->SetStagedUploadCallback(
      [this](uint32_t offset, uint32_t length) {
        return StageHazardUpload(offset, length);
      });
  shared_memory_->SetCpuWriteCallback(
      [this](uint32_t offset, uint32_t length) {
        EncodeDiscreteMirrorUpload(offset, length);
      });
  shared_memory_->SetVramFetchHooks(
      [this]() { return CurrentEncodingSubmission(); },
      [this]() { return completed_submission_.load(std::memory_order_acquire); },
      [this](uint64_t submission) {
        return WaitForSubmission(submission, 4000, nullptr);
      });
  shared_memory_->SetCompletedSubmissionProvider([this]() {
    return completed_submission_.load(std::memory_order_acquire);
  });
  // Frame-trace fidelity: an upload's source range is recorded only after
  // the pending producers over it have converged to RAM (the same host-read
  // preparation the RAM frontbuffer present uses).
  shared_memory_->SetTracePublishCallback([this](uint32_t start,
                                                 uint32_t length) {
    if (false) {
      PrepareGuestMemoryForHostRead(start, length);
    }
  });
  // Straddler fix: uploads copy around pending GPU-current spans (the
  // pending lists live on this thread, the same one that uploads).
  shared_memory_->SetGpuCurrentSpanProvider(
      [this](uint32_t start, uint32_t length,
             std::vector<std::pair<uint32_t, uint32_t>>* out) {
        // XE_METAL_GPU_CURRENT_SKIP=0 (diagnostic): report no GPU-current
        // spans, so uploads copy guest RAM over pending GPU output too.
        static const bool s_skip = metal::ParseMetalEnvironmentFlag(
            std::getenv("XE_METAL_GPU_CURRENT_SKIP"), true);
        if (!s_skip) {
          return;
        }
        const uint64_t end = uint64_t(start) + length;
        // The producer index's page bitmap holds every pending writeback and
        // memexport range: no bit on the upload's 64 KiB pages means neither
        // walk below can find an overlap (uploads with no pending producer
        // nearby were walking both whole queues, ~1% of Red Dead's command
        // processor).
        static const bool s_index_early_out = [] {
          const char* v = std::getenv("XE_METAL_PRODUCER_INDEX");
          return !(v && v[0] == '0' && !v[1]);
        }();
        if (length && end <= (uint64_t(8192) << 16) && s_index_early_out) {
          EnsureProducerIndex();
          const uint32_t first = start >> 16;
          const uint32_t last =
              uint32_t(std::min<uint64_t>(end - 1u, 0xFFFFFFFFull) >> 16);
          bool any = false;
          for (uint32_t page = first; page <= last && page < 8192u; ++page) {
            if (producer_index_.pages[page >> 6] &
                (uint64_t(1) << (page & 63u))) {
              any = true;
              break;
            }
          }
          if (!any) {
            return;
          }
        }
        for (const PendingWriteback& wb : pending_writebacks_) {
          if (!wb.gpu_current || wb.staging) {
            continue;
          }
          const uint32_t wb_len = wb.range_bytes();
          if (wb.guest_addr < end && uint64_t(wb.guest_addr) + wb_len > start) {
            out->emplace_back(wb.guest_addr, wb_len);
          }
        }
        for (const PendingMemexport& me : pending_memexports_) {
          if (me.base_address < end &&
              uint64_t(me.base_address) + me.size_bytes > start) {
            out->emplace_back(me.base_address, me.size_bytes);
          }
        }
        // Only bytes the lazy table still OWNS are the GPU's newest. A page
        // it has published holds the same bytes in RAM, and a CPU write after
        // that publication makes RAM newer: skipping the upload there fed
        // Child of Eden's video copy (a vertex buffer the game placed over a
        // retired 832x624 resolve) the resolve's bytes instead of the decoded
        // frame. XE_METAL_GPU_CURRENT_OWNED_ONLY=0 restores whole-span skips.
        // Not in trace playback: a trace restore replays capture-time RAM, not
        // a newer guest write, and the frame's GPU output must survive it
        // (e63bb82d4); the whole-span skip is what keeps playback exact.
        static const bool s_owned_only = metal::ParseMetalEnvironmentFlag(
            std::getenv("XE_METAL_GPU_CURRENT_OWNED_ONLY"), true);
        if (s_owned_only && true &&
            lazy_read_callback_handle_ && !out->empty()) {
          std::vector<std::pair<uint32_t, uint32_t>> owned;
          for (const auto& span : *out) {
            uint32_t s0 = std::max(span.first, start);
            uint64_t s1 =
                std::min<uint64_t>(uint64_t(span.first) + span.second, end);
            if (s0 < s1) {
              // (lazy publication removed)
            }
          }
          out->swap(owned);
        }
        // Ordering census (XE_METAL_LAZY_ORDER_CENSUS): a pending span the
        // lazy table no longer owns was already published to RAM, so RAM and
        // the buffer agree unless the CPU wrote after the publication. A
        // difference there is a CPU write the upload skip keeps from the GPU.
        static const bool s_skip_census =
            std::getenv("XE_METAL_LAZY_ORDER_CENSUS") != nullptr;
        if (s_skip_census && !out->empty() && lazy_read_callback_handle_) {
          id<MTLBuffer> buffer =
              (__bridge id<MTLBuffer>)shared_memory_->GetCpuBuffer();
          const uint8_t* contents =
              buffer ? static_cast<const uint8_t*>(buffer.contents) : nullptr;
          static uint64_t s_unowned_spans = 0, s_realized = 0;
          for (const auto& span : *out) {
            uint32_t s0 = std::max(span.first, start);
            uint32_t s1 = uint32_t(
                std::min<uint64_t>(uint64_t(span.first) + span.second, end));
            if (!contents || s0 >= s1) {
              continue;
            }
            const uint8_t* ram = TranslateGuest<const uint8_t*>(s0);
            uint32_t differing = 0;
            for (uint32_t i = 0; ram && i < s1 - s0; ++i) {
              differing += ram[i] != contents[s0 + i] ? 1u : 0u;
            }
            ++s_unowned_spans;
            if (differing) {
              ++s_realized;
            }
            if (differing || s_unowned_spans <= 16) {
              REXLOG_WARN(
                  "MetalSkipCensus: upload {:08X}+{:X} skips unowned pending "
                  "span {:08X}+{:X}: {} bytes differ (realized {}/{} spans)",
                  start, length, s0, s1 - s0, differing, s_realized,
                  s_unowned_spans);
            }
          }
        }
      });
  // PP1 + PP2-auto: the shared ::rex::gpu::PrimitiveProcessor normalization authority for
  // routed native restart-disabled line/triangle list/strip draws and
  // auto-indexed triangle fans. Depends on shared_memory_ (constructed above).
  // A failure leaves primitive_processor_ null and every draw falls back to the
  // inline path (behavior-preserving), including auto fans.
  {
    // Quad lists as triangle lists everywhere (2026-10-18): on the M1 Max
    // under macOS 27.0.1 the shader-converter object+mesh quad pipelines made
    // the GPU abort Red Dead Redemption's scene pass ~1,000 times a session
    // ("Insufficient ::rex::IPhysicalMemory"). The conversion is the one other GPUs always
    // used ((0,1,2),(0,2,3) per quad, the shared table's order); reordering
    // it to the mesh path's 0,1,3,2 strip broke Viva Pinata's water, while
    // this order renders it and the mesh path drew it as green spikes.
    const char* v = std::getenv("XE_METAL_QUAD_CONVERT");
    convert_auto_quads_ = v ? (v[0] == '1') : ::rex::graphics::metal::GetMetalSettings().metal_quad_lists_as_triangles.Get();
    REXLOG_INFO("MetalCommandProcessor: quad lists via {}",
           convert_auto_quads_ ? "triangle-list conversion"
                               : "geometry emulation");
  }
  primitive_processor_ = std::make_unique<MetalPrimitiveProcessor>(
      *register_file_, GetXenosSettings(), physical_memory_, write_watch_, *shared_memory_);
  if (!primitive_processor_->Initialize(convert_auto_quads_)) {
    REXLOG_ERROR("MetalCommandProcessor: primitive processor init failed; routing "
           "disabled, all draws stay on the inline path");
    primitive_processor_.reset();
  }
  if (!InitializeDrawResources(device)) {
    REXLOG_ERROR("MetalCommandProcessor: draw resource init failed");
    return false;
  }
  return true;
}

bool MetalCommandProcessor::InitializeDrawResources(void* device_ptr) {
  id<MTLDevice> device = (__bridge id<MTLDevice>)device_ptr;

  // Mesh-shader support gates the geometry-emulation (rectangle/point/quad) path.
  // Apple Silicon is Apple7+; Mac2 covers AMD on macOS. Mirrors XeniOS.
  mesh_shader_supported_ = [device supportsFamily:MTLGPUFamilyApple7] ||
                           [device supportsFamily:MTLGPUFamilyMac2];
  // Diagnostic A/B: XE_METAL_DISABLE_GEO=1 forces the rect-list SKIP fallback so
  // the geometry-emulation output can be compared against no-geometry.
  if (std::getenv("XE_METAL_DISABLE_GEO")) {
    mesh_shader_supported_ = false;
  }
  // Rectangle lists in the vertex shader on non-Apple GPUs: the Radeon Pro
  // 580X's shader compiler (Polaris) crashes building every MSC geometry
  // emulation pipeline (MTLCompilerService segfault in register allocation,
  // XPC_ERROR_CONNECTION_INTERRUPTED), so all rectangle lists were dropped
  // there. Pre-Metal 3 GPUs only: on the RX 6900 XT geometry emulation
  // compiles and the per-draw index tables cost Mafia II ~9% (80.6 vs 72.3
  // fps). XE_METAL_RECT_VS=0/1 overrides.
  bool metal3 = false;
  if (@available(macOS 13.0, *)) {
    metal3 = [device supportsFamily:MTLGPUFamilyMetal3];
  }
  rect_vs_expansion_ =
      ![device supportsFamily:MTLGPUFamilyApple7] && !metal3;
  if (const char* v = std::getenv("XE_METAL_RECT_VS")) {
    rect_vs_expansion_ = v[0] == '1';
    rect_vs_env_forced_ = rect_vs_expansion_;
  }
  if (rect_vs_expansion_) {
    REXLOG_INFO("MetalCommandProcessor: rectangle lists expand in the vertex "
           "shader");
  }


  upload_arena_ = std::make_unique<MetalUploadArena>(device_ptr, UploadArenaSize());
  if (!upload_arena_->Initialize()) {
    return false;
  }

  // Small buffer standing in for inactive CBV slots so MSC never dereferences a
  // null gpuAddress.
  id<MTLBuffer> null_buffer =
      [device newBufferWithLength:256 options:MTLResourceStorageModeShared];
  if (!null_buffer) {
    return false;
  }
  std::memset([null_buffer contents], 0, 256);
  null_buffer_ = (__bridge_retained void*)null_buffer;

  // 1x1 null texture + default sampler so unbound bindless samples are safe.
  // Bring-up diagnostic: fill it mid-gray (not black) so geometry that samples
  // still-unimplemented textures shows up as visible gray shapes instead of
  // rendering black — proving the geometry is there and the gap is the texture
  // cache. (Turns black post-process composites gray.)
  // MUST be a 2D ARRAY texture (see MetalTextureCache): the guest shaders sample
  // texture2d_array, so a plain 2D null texture would sample as garbage.
  MTLTextureDescriptor* null_desc = [[MTLTextureDescriptor alloc] init];
  null_desc.textureType = MTLTextureType2DArray;
  null_desc.pixelFormat = MTLPixelFormatRGBA8Unorm;
  null_desc.width = 1;
  null_desc.height = 1;
  null_desc.arrayLength = 1;
  null_desc.mipmapLevelCount = 1;
  null_desc.usage = MTLTextureUsageShaderRead;
  null_desc.storageMode = MTLStorageModeShared;
  id<MTLTexture> null_texture = [device newTextureWithDescriptor:null_desc];
  if (!null_texture) {
    return false;
  }
  // The null texture samples as transparent black (0, 0, 0, 0), matching the
  // D3D12 null shader resource view and the Vulkan null image the shared
  // texture cache binds for invalid or unserved fetches. It used to be opaque
  // mid-gray, a diagnostic value with no reference basis. No corpus frame
  // changed with this (Halo 3 12514 was byte-identical either way; its grey
  // sprite squares were the narrow-format host swizzle, see
  // metal_texture_cache.mm). XE_METAL_NULL_GRAY=1 restores the old gray.
  static const bool s_null_gray = std::getenv("XE_METAL_NULL_GRAY") != nullptr;
  uint8_t null_pixel[4] = {0, 0, 0, 0};
  if (s_null_gray) {
    null_pixel[0] = null_pixel[1] = null_pixel[2] = 128;
    null_pixel[3] = 255;
  }
  [null_texture replaceRegion:MTLRegionMake2D(0, 0, 1, 1)
                  mipmapLevel:0
                        slice:0
                    withBytes:null_pixel
                  bytesPerRow:4
                bytesPerImage:0];
  null_texture_ = (__bridge_retained void*)null_texture;
  id<MTLSamplerState> null_sampler =
      [device newSamplerStateWithDescriptor:[[MTLSamplerDescriptor alloc] init]];
  null_sampler_ = (__bridge_retained void*)null_sampler;

  // Bindless view/sampler heaps (arrays of IRDescriptorTableEntry). Fill every
  // slot with the null texture/sampler so any index is valid.
  id<MTLBuffer> view_heap = [device
      newBufferWithLength:kViewBindlessHeapSlots * sizeof(IRDescriptorTableEntry)
                  options:MTLResourceStorageModeShared |
                          MTLResourceCPUCacheModeWriteCombined];
  sampler_heap_slots_ = uint32_t(std::min<NSUInteger>(
      kSamplerBindlessHeapSlots, device.maxArgumentBufferSamplerCount));
  id<MTLBuffer> sampler_heap = [device
      newBufferWithLength:sampler_heap_slots_ *
                          sizeof(IRDescriptorTableEntry)
                  options:MTLResourceStorageModeShared |
                          MTLResourceCPUCacheModeWriteCombined];
  if (!view_heap || !sampler_heap) {
    return false;
  }
  auto* view_entries =
      static_cast<IRDescriptorTableEntry*>([view_heap contents]);
  for (uint32_t i = 0; i < kViewBindlessHeapSlots; ++i) {
    IRDescriptorTableSetTexture(&view_entries[i], null_texture, 0.0f, 0);
  }
  auto* sampler_entries =
      static_cast<IRDescriptorTableEntry*>([sampler_heap contents]);
  for (uint32_t i = 0; i < sampler_heap_slots_; ++i) {
    IRDescriptorTableSetSampler(&sampler_entries[i], null_sampler, 0.0f);
  }
  view_bindless_heap_ = (__bridge_retained void*)view_heap;
  sampler_bindless_heap_ = (__bridge_retained void*)sampler_heap;

  // Fixed system view table: entry 0 = shared-memory SRV, entry 1 = null UAV.
  id<MTLBuffer> system_view = [device
      newBufferWithLength:kSystemViewEntryCount * sizeof(IRDescriptorTableEntry)
                  options:MTLResourceStorageModeShared |
                          MTLResourceCPUCacheModeWriteCombined];
  if (!system_view) {
    return false;
  }
  auto* system_entries =
      static_cast<IRDescriptorTableEntry*>([system_view contents]);
  id<MTLBuffer> shared_buffer =
      (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
  IRDescriptorTableSetBuffer(&system_entries[kSystemViewSharedMemorySRV],
                             [shared_buffer gpuAddress],
                             shared_memory_->gpu_visible_length());
  IRDescriptorTableSetBuffer(&system_entries[kSystemViewNullUAV],
                             [null_buffer gpuAddress], 256);
  IRDescriptorTableSetBuffer(&system_entries[kSystemViewSharedMemoryUAV],
                             [shared_buffer gpuAddress],
                             shared_memory_->gpu_visible_length());
  system_view_tables_ = (__bridge_retained void*)system_view;

  texture_cache_ = std::make_unique<MetalTextureCache>(
      device_ptr, shared_memory_.get(), view_bindless_heap_, kViewBindlessHeapSlots);
  if (render_target_cache_) {
    render_target_cache_->SetDeferredReleaseGuard([this](void* texture) {
      return texture_cache_ &&
             texture_cache_->RetireResolvedTargetsNaming(texture);
    });
  }
  texture_cache_->EnableTextureHeaps();
  if (render_target_cache_ && texture_cache_->texture_heaps_enabled()) {
    render_target_cache_->SetSnapshotTextureAllocator([this](void* desc) {
      return texture_cache_ ? texture_cache_->NewHeapTexture(desc) : nullptr;
    });
  }
  texture_cache_->SetDrawResolutionScale(draw_resolution_scale_x_,
                                         draw_resolution_scale_y_);
  {
    auto* residency_provider = static_cast<rex::ui::metal::MetalProvider*>(
        GetGraphicsDriver().GetProvider());
    InitializeResidencySet(
        device_ptr,
        residency_provider ? residency_provider->command_queue() : nullptr);
  }
  // The same null texture every heap slot is initialized to, so a slot freed
  // by a cache clear returns to a valid resource rather than an empty entry.
  texture_cache_->SetNullTexture(null_texture_);
  texture_cache_->SetSnapshotFitBlitter(
      [this](void* src, void* dst, uint32_t width, uint32_t height) {
        if (!src || !dst || !width || !height) {
          return false;
        }
        id<MTLCommandBuffer> cb =
            (__bridge id<MTLCommandBuffer>)PrepareTransferCommandBuffer(
                uint32_t(metal::MetalTransferSite::kSnapshotFit));
        if (!cb) {
          return false;
        }
        id<MTLBlitCommandEncoder> blit = [cb blitCommandEncoder];
        blit.label = @"texcache:snapshot-fit";
        [blit copyFromTexture:(__bridge id<MTLTexture>)src
                  sourceSlice:0
                  sourceLevel:0
                 sourceOrigin:MTLOriginMake(0, 0, 0)
                   sourceSize:MTLSizeMake(width, height, 1)
                    toTexture:(__bridge id<MTLTexture>)dst
             destinationSlice:0
             destinationLevel:0
            destinationOrigin:MTLOriginMake(0, 0, 0)];
        [blit endEncoding];
        return true;
      });
  // Heap-allocated fitted snapshot views (discrete GPUs) start zeroed: blit
  // row strips from one 4 MiB GPU-zeroed buffer, ordered before the fit blit.
  // Depth/stencil formats take the CPU-zeroed Shared fallback.
  texture_cache_->SetSnapshotZeroer(
      [this](void* texture, uint32_t width, uint32_t height) {
        id<MTLTexture> dst = (__bridge id<MTLTexture>)texture;
        if (!dst || !width || !height) {
          return false;
        }
        switch (dst.pixelFormat) {
          case MTLPixelFormatDepth16Unorm:
          case MTLPixelFormatDepth32Float:
          case MTLPixelFormatDepth32Float_Stencil8:
          case MTLPixelFormatStencil8:
            return false;
          default:
            break;
        }
        constexpr NSUInteger kZeroBytes = NSUInteger(4) << 20;
        const NSUInteger row_bytes =
            NSUInteger(width) * AttachmentBytesPerPixel(dst.pixelFormat);
        if (row_bytes > kZeroBytes) {
          return false;
        }
        id<MTLCommandBuffer> cb =
            (__bridge id<MTLCommandBuffer>)PrepareTransferCommandBuffer(
                uint32_t(metal::MetalTransferSite::kSnapshotFit));
        if (!cb) {
          return false;
        }
        id<MTLBlitCommandEncoder> blit = [cb blitCommandEncoder];
        blit.label = @"texcache:snapshot-zero";
        if (!snapshot_zero_buffer_) {
          id<MTLBuffer> zero =
              [dst.device newBufferWithLength:kZeroBytes
                                      options:MTLResourceStorageModePrivate];
          if (!zero) {
            [blit endEncoding];
            return false;
          }
          [blit fillBuffer:zero range:NSMakeRange(0, kZeroBytes) value:0];
          snapshot_zero_buffer_ = (__bridge_retained void*)zero;
        }
        id<MTLBuffer> zero = (__bridge id<MTLBuffer>)snapshot_zero_buffer_;
        const uint32_t strip = uint32_t(kZeroBytes / row_bytes);
        for (uint32_t y = 0; y < height; y += strip) {
          const uint32_t rows = std::min(strip, height - y);
          [blit copyFromBuffer:zero
                     sourceOffset:0
                sourceBytesPerRow:row_bytes
              sourceBytesPerImage:row_bytes * rows
                       sourceSize:MTLSizeMake(width, rows, 1)
                        toTexture:dst
                 destinationSlice:0
                 destinationLevel:0
                destinationOrigin:MTLOriginMake(0, y, 0)];
        }
        [blit endEncoding];
        return true;
      });
  texture_cache_->SetSubmissionProvider([this]() {
    return S7TagsOff() ? 0 : CurrentEncodingSubmission();
  });
  // C1T-R shared TextureCache subclass route (canonical for strict tiled
  // single-mip 2D k_8_8_8_8 kRamContent misses; the legacy cache serves
  // everything else and remains the universal fallback). All wiring uses
  // existing mechanisms only (seam audit M1-M5): the legacy cache is
  // the slot/residency/retirement authority, loads encode through
  // PrepareTransferCommandBuffer, lifetime keys off the same submission ids,
  // and faulted submissions are queried from the existing GPU-thread fault
  // recording.
  // Shared cross-backend resolve-copy pipelines (task 4.2). Built only when
  // the route is enabled: it is default OFF, and 9 pipeline creations are not
  // free at startup. A failure here is logged and non-fatal -- the dispatcher
  // checks `initialized()` and the existing resolve path continues.
  if ((SharedResolveShadersEnabled() || SharedResolveArraysEnabled()) &&
      !resolve_shader_pipelines_.Initialize(device_ptr)) {
    REXLOG_ERROR(
        "MetalCommandProcessor: shared resolve-copy pipelines failed to "
        "build; XE_METAL_SHARED_RESOLVE will not engage");
  }
  shared_texture_cache_ = std::make_unique<MetalSharedTextureCache>(
      *register_file_, GetXenosSettings(), *shared_memory_, device_ptr, texture_cache_.get(),
      draw_resolution_scale_x_, draw_resolution_scale_y_);
  shared_texture_cache_->SetPrepareTransferCallback(
      [this](bool side) {
        if (side) {
          // No frame command buffer yet (or none could be made): the frame
          // path has no pass to end then, so it is the right fallback.
          void* cb = PrepareSideTransferCommandBuffer();
          if (cb) {
            return cb;
          }
        }
        return PrepareTransferCommandBuffer(
            uint32_t(metal::MetalTransferSite::kTextureUpload));
      });
  shared_texture_cache_->SetRenderPassOpenQuery(
      [this]() { return frame_open_ && frame_render_encoder_ != nullptr; });
  // NOT gated on S7TagsOff: these ids drive the subclass's BeginSubmission
  // advance, LRU gating, and M4 faulted-submission matching — equality
  // bookkeeping that needs real monotonic ids in both sync and async
  // modes. (Retirement tags still flow through the legacy adapter's
  // S7-governed RetireSubmission.)
  shared_texture_cache_->SetSubmissionProvider(
      [this]() { return CurrentEncodingSubmission(); });
  shared_texture_cache_->SetSubmissionFaultQuery([this](uint64_t submission) {
    return faulted_submissions_.count(submission) != 0;
  });
  shared_texture_cache_->SetCompletedSubmissionProvider([this]() {
    return completed_submission_.load(std::memory_order_acquire);
  });
  if (!shared_texture_cache_->Initialize()) {
    REXLOG_ERROR(
        "MetalCommandProcessor: shared texture cache init failed; route "
        "disabled, legacy cache serves everything");
    shared_texture_cache_.reset();
  }
  return true;
}

void MetalCommandProcessor::ShutdownDrawResources() {
  // The shared-route subclass retires slots/textures through texture_cache_;
  // destroy it first.
  shared_texture_cache_.reset();
  {
    auto* provider = static_cast<rex::ui::metal::MetalProvider*>(
        GetGraphicsDriver().GetProvider());
    ShutdownResidencySet(provider ? provider->command_queue() : nullptr);
  }
  texture_cache_.reset();  // references view_bindless_heap_, free first.
  auto release = [](void*& p) {
    if (p) {
      id obj = (__bridge_transfer id)p;
      (void)obj;
      p = nullptr;
    }
  };
  release(view_bindless_heap_);
  release(sampler_bindless_heap_);
  release(system_view_tables_);
  release(null_buffer_);
  release(null_texture_);
  release(null_sampler_);
  release(snapshot_zero_buffer_);
  for (auto& pair : depth_stencil_states_) {
    release(pair.second);
  }
  depth_stencil_states_.clear();
  for (void*& state : sampler_states_) {
    release(state);
  }
  sampler_states_.clear();
  sampler_slot_cache_.clear();
  next_sampler_slot_ = 1;
  upload_arena_.reset();
}

void MetalCommandProcessor::ReportZeroCopyLifecycle(const char* site) {
  if (!shared_memory_) {
    return;
  }
  // ONE snapshot for both reporters. It is taken under the physical
  // invalidation callback's lock, so reading it twice would double that
  // acquisition purely because a diagnostic was enabled -- and would also let
  // the two lines describe two different moments.
  metal::ZeroCopyOverlapSnapshot snapshot =
      shared_memory_->zero_copy_overlap_snapshot();
  ReportZeroCopyOverlap(site, snapshot);
  ReportZeroCopyRuntimeCost(site, snapshot);
}

void MetalCommandProcessor::ReportZeroCopyOverlap(
    const char* site, const metal::ZeroCopyOverlapSnapshot& snapshot) {
  if (metal::ZeroCopyOverlapSnapshotIsSilent(snapshot)) {
    // The required silence: exact-off and every fallback arm never installed
    // the observer and never advanced anything, so the run emits no zero-copy
    // observation at all.
    return;
  }
  if (!snapshot.active) {
    // Nothing installed, yet something was counted. That is a defect in the
    // observation model itself, and staying silent about it would hide exactly
    // the case the installed-versus-advanced split exists to catch.
    REXLOG_ERROR(
        "MetalZeroCopyOverlap[{}]: INCONSISTENT -- no observer installed but "
        "{} stamps / {} CPU-write callbacks were recorded",
        site, snapshot.stamp_calls, snapshot.cpu_write_callbacks);
    return;
  }
  // Finalizations and successful swaps are reported SEPARATELY: they are equal
  // only when every frame published, and a run where they diverge is one where
  // presents were suppressed -- a fact worth reading off this line rather than
  // hiding behind a single "frames" number. Neither is evidence of an overlap;
  // both are the denominator for one.
  REXLOG_INFO(
      "MetalZeroCopyOverlap[{}]: finalizations={} swaps={} pages={}({}B) "
      "stamps={}/{}p "
      "zero_submission={}p writes={}cb/{}p clamped={}cb idle={}p "
      "completed_reader={}p in_flight_cpu_write_overlap={}p samples={}",
      site, swap_finalize_index_, swap_count_, snapshot.page_count,
      1u << snapshot.page_size_log2,
      snapshot.stamp_calls, snapshot.stamped_pages,
      snapshot.zero_submission_stamp_pages, snapshot.cpu_write_callbacks,
      snapshot.cpu_write_pages, snapshot.clamped_cpu_writes,
      snapshot.idle_pages, snapshot.completed_reader_pages,
      snapshot.in_flight_cpu_write_overlap, snapshot.sample_count);
  if (snapshot.zero_submission_stamp_pages) {
    // A zero-stamp enrolls nothing, so an overlap count taken while this is
    // nonzero cannot be read as "no overlap happened".
    REXLOG_WARN(
        "MetalZeroCopyOverlap[{}]: {} pages were enrolled with the idle "
        "sentinel -- the execution source is not reporting real submissions, "
        "so this run's overlap count is NOT evidence of safety",
        site, snapshot.zero_submission_stamp_pages);
  }
  // Bounded: at most kZeroCopyOverlapSampleSlots lines, deduplicated by page.
  for (uint32_t i = 0; i < snapshot.sample_count; ++i) {
    const metal::ZeroCopyOverlapSample& sample = snapshot.samples[i];
    REXLOG_WARN(
        "MetalZeroCopyOverlap[{}]: sample {} -- guest page {:08X} claimed by "
        "submission {} while completed was {}",
        site, i, uint64_t(sample.page_index) << snapshot.page_size_log2,
        sample.consumer_submission, sample.completed_submission);
  }
}

void MetalCommandProcessor::ReportZeroCopyRuntimeCost(
    const char* site, const metal::ZeroCopyOverlapSnapshot& snapshot) {
  metal::ZeroCopyCostSnapshot cost = zero_copy_cost_.Snapshot();
  if (metal::ZeroCopyCostSnapshotIsSilent(cost)) {
    // Unset, "0", or anything malformed: the meter never armed and nothing
    // advanced, so the run emits no cost line at all.
    return;
  }
  if (!cost.enabled) {
    // Something was counted by a meter that is not enabled. That is a defect in
    // the metering itself, and printing the numbers as if they were a measured
    // run would launder it.
    REXLOG_ERROR(
        "MetalZeroCopyCost[{}]: INCONSISTENT -- reporting is disabled but "
        "counters advanced",
        site);
    return;
  }
  if (!shared_memory_) {
    // The backing verdict and the upload accounting are both properties of the
    // shared memory. Without it there is no honest line to print.
    REXLOG_WARN("MetalZeroCopyCost[{}]: no shared memory; no cost line", site);
    return;
  }
  // The startup verdict is DERIVED from the recorded observation, exactly as
  // the startup line derives it, rather than restated from is_zero_copy(). Both
  // are printed: a disagreement between the derivation and the installed
  // backing is the one thing this pair exists to expose.
  metal::ZeroCopyStartupReport startup =
      metal::DeriveZeroCopyStartupReport(shared_memory_->zero_copy_observation());
  // One bounded line. Every number is read from a source that recorded it at
  // its own production operation; nothing here is inferred from the backing.
  REXLOG_INFO(
      "MetalZeroCopyCost[{}]: startup={} alias={} finalizations={} swaps={} "
      "upload_copied={}B upload_alias_skipped={}B "
      "{}={}B {}={} "
      "{}={} {}={} {}={} {}={} {}={} {}={} "
      "{}={} {}={} "
      "{}={} {}={} {}={} "
      "observer_active={} zero_submission={}p write_callbacks={} "
      "write_pages={}p in_flight_overlap={}p",
      site, metal::ZeroCopyStartupReportName(startup),
      shared_memory_->is_zero_copy(), swap_finalize_index_, swap_count_,
      shared_memory_->upload_bytes_copied(),
      shared_memory_->upload_bytes_aliased(),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kMemexportConvergenceBytesCopied),
      cost.Get(metal::ZeroCopyCostCounter::kMemexportConvergenceBytesCopied),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kMemexportRetirements),
      cost.Get(metal::ZeroCopyCostCounter::kMemexportRetirements),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kMemexportDestinationPreparations),
      cost.Get(metal::ZeroCopyCostCounter::kMemexportDestinationPreparations),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kMemexportNoOlderFastPaths),
      cost.Get(metal::ZeroCopyCostCounter::kMemexportNoOlderFastPaths),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kMemexportOrderingBarriers),
      cost.Get(metal::ZeroCopyCostCounter::kMemexportOrderingBarriers),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kMemexportSelectedPredecessors),
      cost.Get(metal::ZeroCopyCostCounter::kMemexportSelectedPredecessors),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kMemexportOrderingRetained),
      cost.Get(metal::ZeroCopyCostCounter::kMemexportOrderingRetained),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kMemexportPreparationFailures),
      cost.Get(metal::ZeroCopyCostCounter::kMemexportPreparationFailures),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kSubmissionCommits),
      cost.Get(metal::ZeroCopyCostCounter::kSubmissionCommits),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kSyncCommitWaits),
      cost.Get(metal::ZeroCopyCostCounter::kSyncCommitWaits),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kWaitForSubmissionCalls),
      cost.Get(metal::ZeroCopyCostCounter::kWaitForSubmissionCalls),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kWaitForSubmissionBlocked),
      cost.Get(metal::ZeroCopyCostCounter::kWaitForSubmissionBlocked),
      metal::ZeroCopyCostCounterName(
          metal::ZeroCopyCostCounter::kWaitForSubmissionTimeouts),
      cost.Get(metal::ZeroCopyCostCounter::kWaitForSubmissionTimeouts),
      // The overlap half is REUSED from the snapshot the lifecycle emitter
      // already took, not re-read. `observer_active` is false on every control
      // arm by construction, which is what makes the zero counts beside it
      // readable as "nobody was watching" rather than "nothing happened".
      snapshot.active, snapshot.zero_submission_stamp_pages,
      snapshot.cpu_write_callbacks, snapshot.cpu_write_pages,
      snapshot.in_flight_cpu_write_overlap);
}

void MetalCommandProcessor::ShutdownContext() {
  if (encode_stream_) {
    // Replays what is recorded and stops the encoder thread; later shutdown
    // paths that end an encoder then run direct.
    encode_stream_->Shutdown();
  }
  if (!sampler_census_.empty()) {
    for (const auto& kv : sampler_census_) {
      REXLOG_INFO("MetalSamplerCensus final key={:016X} count={}", kv.first,
             kv.second);
    }
    REXLOG_INFO("MetalSamplerCensus final unique={}", sampler_census_.size());
  }
  // Task 1.1: the run's final build totals, emitted BEFORE the caches are torn
  // down so a run killed during teardown still leaves a complete record. The
  // periodic samples are progress; this line is the measurement.
  REXLOG_INFO("{}", GetMetalShaderBuildCensus().Report("final"));
  if (ScaleCoverageCensusEnabled()) {
    // The headless trace-dump tool exits cleanly before any periodic tick.
    metal::ScaleCoverageCensus::Get().Dump(0);
  }
  if (ServingCensusEnabled()) {
    // The headless trace-dump tool DOES exit cleanly, so this is the only
    // emission a single-frame trace run ever reaches (the swap-tick dump needs
    // 128 swaps). The live app is SIGKILLed and relies on the periodic tick.
    using metal::ServingCensus;
    REXLOG_INFO(
        "MetalServingCensus final: gpu_served_declared_dependency={} "
        "(exact_cover={} bridge={}) | agreed_gpu_served={} agreed_ram={} "
        "not_resolve_backed={} unsafe_skips={}",
        ServingCensus::SpuriousDependencies(),
        ServingCensus::Get(ResolvedFetchService::kExactCoverSnapshot, false),
        ServingCensus::Get(ResolvedFetchService::kBridgeSnapshot, false),
        ServingCensus::Get(ResolvedFetchService::kBridgeSnapshot, true) +
            ServingCensus::Get(ResolvedFetchService::kExactCoverSnapshot, true),
        ServingCensus::Get(ResolvedFetchService::kRamContent, false),
        ServingCensus::Get(ResolvedFetchService::kNotResolveBacked, false),
        ServingCensus::UnsafeSkips());
    REXLOG_INFO(
        "MetalServingCensus final requests: total={} boundary_avoided={} "
        "boundary_retained={} corrected_stricter={}",
        ServingCensus::Requests::Total().load(std::memory_order_relaxed),
        ServingCensus::Requests::BoundaryAvoided().load(
            std::memory_order_relaxed),
        ServingCensus::Requests::BoundaryRetained().load(
            std::memory_order_relaxed),
        ServingCensus::Requests::CorrectedStricter().load(
            std::memory_order_relaxed));
        for (uint32_t k = 0; k < uint32_t(metal::ConsumerKind::kCount); ++k) {
          uint64_t ro = ServingCensus::Boundary(
                            k, ServingCensus::HeldBy::kResolveOnly)
                            .load(std::memory_order_relaxed);
          uint64_t mo = ServingCensus::Boundary(
                            k, ServingCensus::HeldBy::kMemexportOnly)
                            .load(std::memory_order_relaxed);
          uint64_t mx =
              ServingCensus::Boundary(k, ServingCensus::HeldBy::kMixed)
                  .load(std::memory_order_relaxed);
          if (!(ro || mo || mx)) {
            continue;
          }
          REXLOG_INFO(
              "MetalServingCensus boundary consumer={} resolve_only={} "
              "memexport_only={} mixed={} total={}",
              metal::ConsumerKindName(metal::ConsumerKind(k)), ro, mo, mx,
              ro + mo + mx);
        }
  }
  if (frame_open_) {
    EndFrameEncoderAndWait(metal::SeamBoundaryReason::kShutdown);
  }
  PumpCompletedActions();
  // Drops any resolve still queued and releases the visibility buffer; the
  // reports they belonged to are abandoned by the shared reset path.
  ShutdownZPDQueryResources();
  ShutdownDrawResources();
  // Task 5.4: the run's FINAL zero-copy evidence -- overlap AND runtime cost --
  // while shared_memory_ still holds both (its own Shutdown releases the
  // observer, and the upload accounting goes with it). Mandatory rather than
  // swap-cadence-only: a trace replay can end without ever reaching a swap, and
  // a missing line there would be indistinguishable from "nothing overlapped"
  // and from "no work was done".
  ReportZeroCopyLifecycle("final");
  // Seam-timing final report. NOTE: measured 2026-08-08, plain trace-dump
  // replay does NOT surface lines from this teardown path (the zero-copy
  // [final] line is likewise absent there); headless tools therefore call
  // EmitLifecycleReports explicitly while logging is alive. This emission
  // still covers live-run teardown remainders.
  EmitSeamTimingReport("final");
  // Need-based-waits engagement, on the same teardown path and with the same
  // headless caveat: a trace-dump run gets its line from EmitLifecycleReports.
  EmitNeedBasedWaitReport("final");
  // ::rex::gpu::PrimitiveProcessor: destroy before shared_memory_ (it holds a reference).
  primitive_processor_.reset();
  shared_memory_.reset();
  render_target_cache_.reset();
  pipeline_cache_.reset();
  CommandProcessor::ShutdownContext();
  // Drain the final frame's pool (pushed at the last IssueSwap; the teardown
  // above autoreleased into it). Runs on the same GPU thread as IssueSwap.
  if (frame_autorelease_pool_) {
    objc_autoreleasePoolPop(frame_autorelease_pool_);
    frame_autorelease_pool_ = nullptr;
  }
}

// Depth buffer is GATED OFF for now. When enabled it clears depth to 1.0 (far)
// assuming standard 0..1 depth, but many Xbox 360 titles use reverse-z (clear 0,
// "greater" test), so the fixed clear discards everything and 2D/menus go black.
// Re-enable only once the guest depth-clear value + z-direction are emulated
// (read from the guest's depth clear, not assumed). Keeps the pipeline's depth
// attachment format and the render pass consistent (both on or both off).
static constexpr bool kDepthEnabled = true;

bool MetalCommandProcessor::PassCensusEnabled() {
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_PASS_CENSUS");
    return value && value[0] == '1' && value[1] == '\0';
  }();
  return s_enabled;
}

bool MetalCommandProcessor::PassAttachmentsByUseEnabled() {
  static const bool s_enabled = [] {
    const char* legacy = std::getenv("XE_METAL_PASS_ATTACHMENTS_LEGACY");
    if (legacy && legacy[0] == '1' && legacy[1] == '\0') {
      return false;
    }
    return metal::MetalSwitchEnabled(::rex::graphics::metal::GetMetalSettings().metal_pass_attachments_by_use.Get(),
                                     std::getenv("XE_METAL_PASS_ATTACHMENTS"));
  }();
  return s_enabled;
}

uint64_t MetalCommandProcessor::PassAttachmentKey(bool dummy_depth,
                                                  bool memexport) const {
  uint64_t key = render_target_cache_->current_attachment_key();
  if (dummy_depth) {
    // Scratch-depth passes are distinct from same-color passes without one:
    // their pipelines carry a depth pixel format the plain pass lacks.
    key ^= 0x9E3779B97F4A7C15ull;
  }
  if (memexport) {
    // Memexport draws run in their own attachment-less pass; never share an
    // encoder with attachment passes.
    key = 0x4D454D4558504F52ull;  // 'MEMEXPOR'
  }
  return key;
}

// XE_METAL_PASS_TIMING=1: GPU time of every draw render pass from
// stage-boundary timestamp samples, summed per attachment key and logged
// with the per-128-swap stats. Instruments cannot attribute most render-pass
// work on Apple GPUs (its GPU intervals carry encoder id 0 for ~3/4 of
// fragment time, Far Cry 3 2x 2026-10-31), so this names the passes itself.
// CP thread: Attach / EndPass / TakeCommitRange. Completion handlers: Resolve.
namespace {
struct PassTimingAgg {
  uint64_t vertex_ticks = 0;
  uint64_t fragment_ticks = 0;
  uint64_t passes = 0;
  uint64_t draws = 0;
  uint32_t msaa = 0;
};
struct PassTimingState {
  // Four samples per pass; Apple caps a sample buffer at 32 KiB (4096
  // samples), which holds ~10 frames of passes in flight.
  static constexpr uint32_t kPasses = 1024;
  id<MTLCounterSampleBuffer> buffer = nil;
  bool init_tried = false;
  struct Slot {
    uint64_t rt_key;
    uint32_t draw_start;
    uint32_t draws;
    uint32_t msaa;
  };
  std::array<Slot, kPasses> slots{};
  uint64_t next = 0;       // CP thread
  uint64_t committed = 0;  // CP thread
  int64_t open = -1;       // CP thread
  uint64_t overruns = 0;   // CP thread
  std::atomic<uint64_t> resolved{0};
  std::mutex mutex;  // guards everything below
  std::unordered_map<uint64_t, PassTimingAgg> agg;
  std::unordered_map<uint64_t, std::string> describe;
  uint64_t invalid = 0;
  MTLTimestamp cal_gpu = 0;
  std::chrono::steady_clock::time_point cal_time;
};
PassTimingState& PassTiming() {
  static PassTimingState state;
  return state;
}
bool PassTimingEnabled() {
  static const bool enabled = [] {
    const char* v = std::getenv("XE_METAL_PASS_TIMING");
    return v && v[0] == '1' && !v[1];
  }();
  return enabled;
}
void PassTimingAttach(MTLRenderPassDescriptor* pass, id<MTLDevice> device,
                      uint64_t rt_key, uint32_t msaa, uint32_t draw_start,
                      const std::function<std::string()>& describe) {
  PassTimingState& pt = PassTiming();
  if (!pt.init_tried) {
    pt.init_tried = true;
    id<MTLCounterSet> timestamps = nil;
    for (id<MTLCounterSet> set in device.counterSets) {
      if ([set.name isEqualToString:MTLCommonCounterSetTimestamp]) {
        timestamps = set;
      }
    }
    if (timestamps &&
        [device supportsCounterSampling:MTLCounterSamplingPointAtStageBoundary]) {
      MTLCounterSampleBufferDescriptor* desc =
          [[MTLCounterSampleBufferDescriptor alloc] init];
      desc.counterSet = timestamps;
      desc.storageMode = MTLStorageModeShared;
      desc.sampleCount = PassTimingState::kPasses * 4;
      desc.label = @"xe pass timing";
      NSError* error = nil;
      pt.buffer = [device newCounterSampleBufferWithDescriptor:desc
                                                        error:&error];
      if (!pt.buffer) {
        REXLOG_WARN("MetalPassTiming: no sample buffer ({})",
               error ? [[error localizedDescription] UTF8String] : "nil");
      }
    } else {
      REXLOG_WARN("MetalPassTiming: stage-boundary timestamps unsupported");
    }
    MTLTimestamp cpu = 0;
    [device sampleTimestamps:&cpu gpuTimestamp:&pt.cal_gpu];
    pt.cal_time = std::chrono::steady_clock::now();
  }
  // The descriptor may be reused: clear a previous pass's attachment.
  pass.sampleBufferAttachments[0].sampleBuffer = nil;
  pt.open = -1;
  if (!pt.buffer) {
    return;
  }
  if (pt.next - pt.resolved.load(std::memory_order_acquire) >=
      PassTimingState::kPasses) {
    ++pt.overruns;
    return;
  }
  const uint32_t slot = uint32_t(pt.next % PassTimingState::kPasses);
  MTLRenderPassSampleBufferAttachmentDescriptor* a =
      pass.sampleBufferAttachments[0];
  a.sampleBuffer = pt.buffer;
  a.startOfVertexSampleIndex = slot * 4;
  a.endOfVertexSampleIndex = slot * 4 + 1;
  a.startOfFragmentSampleIndex = slot * 4 + 2;
  a.endOfFragmentSampleIndex = slot * 4 + 3;
  pt.slots[slot] = {rt_key, draw_start, 0, msaa};
  pt.open = int64_t(pt.next++);
  std::lock_guard<std::mutex> lock(pt.mutex);
  if (!pt.describe.count(rt_key)) {
    pt.describe.emplace(rt_key, describe());
  }
}
void PassTimingEndPass(uint32_t draw_count) {
  PassTimingState& pt = PassTiming();
  if (pt.open >= 0) {
    auto& slot = pt.slots[uint64_t(pt.open) % PassTimingState::kPasses];
    slot.draws = draw_count - slot.draw_start;
    pt.open = -1;
  }
}
std::pair<uint64_t, uint64_t> PassTimingTakeCommitRange() {
  PassTimingState& pt = PassTiming();
  // A pass still open belongs to the next command buffer's range.
  const uint64_t end = pt.open >= 0 ? uint64_t(pt.open) : pt.next;
  std::pair<uint64_t, uint64_t> range{pt.committed, end};
  pt.committed = end;
  return range;
}
void PassTimingResolve(std::pair<uint64_t, uint64_t> range) {
  PassTimingState& pt = PassTiming();
  if (range.second > range.first && pt.buffer) {
    std::lock_guard<std::mutex> lock(pt.mutex);
    for (uint64_t i = range.first; i < range.second; ++i) {
      const uint32_t slot = uint32_t(i % PassTimingState::kPasses);
      NSData* data =
          [pt.buffer resolveCounterRange:NSMakeRange(slot * 4, 4)];
      if (!data || data.length < 4 * sizeof(MTLCounterResultTimestamp)) {
        ++pt.invalid;
        continue;
      }
      const auto* t =
          static_cast<const MTLCounterResultTimestamp*>(data.bytes);
      const auto& s = pt.slots[slot];
      PassTimingAgg& agg = pt.agg[s.rt_key];
      agg.msaa = s.msaa;
      ++agg.passes;
      agg.draws += s.draws;
      bool ok = true;
      for (int k = 0; k < 4; ++k) {
        ok &= t[k].timestamp != MTLCounterErrorValue && t[k].timestamp != 0;
      }
      if (!ok || t[1].timestamp < t[0].timestamp ||
          t[3].timestamp < t[2].timestamp) {
        ++pt.invalid;
        continue;
      }
      agg.vertex_ticks += t[1].timestamp - t[0].timestamp;
      agg.fragment_ticks += t[3].timestamp - t[2].timestamp;
    }
  }
  pt.resolved.store(range.second, std::memory_order_release);
}
std::string PassTimingReport(uint32_t swaps, uint64_t count) {
  PassTimingState& pt = PassTiming();
  if (!pt.buffer) {
    return "MetalPassTiming: unavailable";
  }
  MTLTimestamp cpu = 0, gpu = 0;
  [pt.buffer.device sampleTimestamps:&cpu gpuTimestamp:&gpu];
  const auto now = std::chrono::steady_clock::now();
  std::lock_guard<std::mutex> lock(pt.mutex);
  // GPU timestamp ticks are not specified as nanoseconds; calibrate against
  // the host steady clock over the report interval.
  const double elapsed_ns =
      std::chrono::duration<double, std::nano>(now - pt.cal_time).count();
  const double ns_per_tick =
      gpu > pt.cal_gpu ? elapsed_ns / double(gpu - pt.cal_gpu) : 1.0;
  pt.cal_gpu = gpu;
  pt.cal_time = now;
  std::vector<std::pair<uint64_t, PassTimingAgg>> rows(pt.agg.begin(),
                                                       pt.agg.end());
  std::sort(rows.begin(), rows.end(), [](const auto& a, const auto& b) {
    return a.second.vertex_ticks + a.second.fragment_ticks >
           b.second.vertex_ticks + b.second.fragment_ticks;
  });
  double total_v = 0, total_f = 0, total_passes = 0;
  for (const auto& [key, a] : rows) {
    total_v += double(a.vertex_ticks);
    total_f += double(a.fragment_ticks);
    total_passes += double(a.passes);
  }
  const double to_ms = ns_per_tick / 1.0e6 / double(swaps);
  std::string out = fmt::format(
      "MetalPassTiming swap#{}: {:.1f} passes/frame vertex {:.2f} fragment "
      "{:.2f} ms/frame (stage spans; overlap between passes is not "
      "removed), {} keys, {} invalid, {} overruns, {:.3f} ns/tick",
      count, total_passes / double(swaps), total_v * to_ms, total_f * to_ms,
      rows.size(), pt.invalid, pt.overruns, ns_per_tick);
  for (size_t i = 0; i < rows.size() && i < 12; ++i) {
    const auto& [key, a] = rows[i];
    auto d = pt.describe.find(key);
    out += fmt::format(
        "\n  rt={:016X} msaa={} {:5.1f} passes/frame {:6.1f} draws/pass "
        "vertex {:6.2f} fragment {:6.2f} ms/frame  {}",
        key, a.msaa, double(a.passes) / double(swaps),
        double(a.draws) / std::max<double>(double(a.passes), 1.0),
        double(a.vertex_ticks) * to_ms, double(a.fragment_ticks) * to_ms,
        d != pt.describe.end() ? d->second.substr(0, 160) : "");
  }
  pt.agg.clear();
  pt.invalid = 0;
  pt.overruns = 0;
  return out;
}
}  // namespace

void* MetalCommandProcessor::BeginFrameEncoder() {
  // Attach whatever the RT cache accumulated for the current draw (Update()
  // ran in IssueDraw). The attachment key detects guest pass changes.
  // Passes that bind no guest target: memexport-only (VS) draws and
  // pixel-export draws with no render target (scratch depth only).
  const bool scratch_only_pass = memexport_pass_ || pixel_export_pass_;
  if (!scratch_only_pass &&
      !render_target_cache_->PrepareCurrentRasterViews()) {
    return nullptr;
  }
  uint64_t want_key = PassAttachmentKey(dummy_depth_pass_, memexport_pass_);
  if (pixel_export_pass_) {
    // Own encoder per scratch extent; never shared with attachment passes.
    want_key = 0x5049584558505254ull ^  // 'PIXEXPRT'
               (uint64_t(pixel_export_extent_[0]) << 32) ^
               uint64_t(pixel_export_extent_[1]);
  }
  // D2: the attachment subset this draw's pass must bind. Under the legacy
  // policy every present attachment is bound and the subset test is skipped.
  const bool by_use = PassAttachmentsByUseEnabled() && !scratch_only_pass;
  const uint32_t want_bound =
      by_use ? pending_pass_bound_ : metal::kMetalPassAttachmentAll;
  const bool attachments_covered =
      !by_use || (want_bound & ~encoder_bound_attachments_) == 0;
  bool reuse_encoder = frame_open_ && encoder_attachment_key_ == want_key &&
                       attachments_covered;
  bool zpd_rebuild = false;
  if (reuse_encoder && ZPDSegmentPending()) {
    // A report can open, and a closed segment can become pending again, while
    // this encoder is already current -- a path that would otherwise never
    // reach the segment resume below, because a reused encoder returns early.
    // Mafia II's "dead" frame is exactly this shape: its whole report lifetime
    // falls inside one unchanged attachment key.
    if (!zpd_visibility_pool_.is_initialized()) {
      EnsureZPDQueryResources();
    }
    if (encoder_has_zpd_visibility_) {
      OpenQuerySegment(false);
    } else if (zpd_visibility_pool_.is_initialized()) {
      // The encoder predates the pool. Metal only accepts a visibility buffer
      // on the descriptor, so the encoder has to be rebuilt to carry one.
      // Bounded: every encoder created afterwards carries it, so this happens
      // once per pool lifetime rather than per draw.
      reuse_encoder = false;
      zpd_rebuild = true;
    }
    // Pool unavailable: keep the encoder rather than rebuilding it forever.
  }
  // A render-to-render pass end below skips its Drain; any return before the
  // next pass is recorded must still wait for it.
  struct UndrainedPassEndGuard {
    MetalCommandProcessor* cp;
    ~UndrainedPassEndGuard() { cp->DrainUndrainedPassEnd(); }
  } undrained_pass_end_guard{this};
  if (frame_open_) {
    if (reuse_encoder) {
      return frame_render_encoder_;
    }
    ending_for_next_pass_ = true;
    EndRenderEncoder(
        zpd_rebuild ? metal::MetalPassEndReason::kZpdRebuild
        : (encoder_attachment_key_ == want_key && !attachments_covered)
            ? metal::MetalPassEndReason::kAttachmentNeeded
            : metal::MetalPassEndReason::kAttachmentKey);
    ending_for_next_pass_ = false;
  }
  auto* provider =
      static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider());
  if (!provider || !provider->command_queue() || !render_target_cache_) {
    return nullptr;
  }
  uint32_t raster_sample_count =
      scratch_only_pass ? 1u
                        : render_target_cache_->current_raster_sample_count();
  void* color_resolves[xenos::kMaxColorRenderTargets] = {};
  void* color_targets[xenos::kMaxColorRenderTargets] = {};
  void* primary_color_target = nullptr;
  bool any_color_target = false;
  if (!scratch_only_pass) {
    for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
      if (by_use && !(want_bound & metal::MetalPassColorAttachmentBit(i))) {
        // D2: no draw of this pass can touch the target; leave it unbound so
        // its texture is neither loaded nor stored (contents preserved).
        continue;
      }
      color_resolves[i] =
          render_target_cache_->current_color_texture(i, nullptr);
      color_targets[i] =
          render_target_cache_->current_color_raster_texture(i, nullptr);
      if (color_targets[i]) {
        any_color_target = true;
        if (!primary_color_target) {
          primary_color_target = color_targets[i];
        }
      }
    }
  }
  void* depth_resolve =
      (kDepthEnabled && !scratch_only_pass)
          ? render_target_cache_->current_depth_texture()
          : nullptr;
  void* depth = (kDepthEnabled && !scratch_only_pass)
                    ? render_target_cache_->current_depth_raster_texture()
                    : nullptr;
  // D2: the depth plane and the stencil plane of the combined texture bind
  // independently; a stencil-less pass skips the stencil plane's traffic.
  const bool bind_depth_plane =
      !by_use || (want_bound & metal::kMetalPassAttachmentDepth) != 0;
  const bool bind_stencil_plane =
      !by_use || (want_bound & metal::kMetalPassAttachmentStencil) != 0;
  if (depth && !bind_depth_plane && !bind_stencil_plane) {
    depth = nullptr;
    depth_resolve = nullptr;
  }
  if (!any_color_target && !depth && !scratch_only_pass) {
    // Nothing to attach (the caller should have skipped such draws).
    return nullptr;
  }
  // The command buffer lives until the next commit boundary; the upload ring
  // reclaims per-submission from the completion pump (S8) — no reset here.
  id<MTLCommandBuffer> command_buffer;
  bool new_frame = frame_command_buffer_ == nullptr;
  if (new_frame) {
    if (S7ArenaResetOff() && upload_arena_) {
      upload_arena_->Reset();
    }
    id<MTLCommandQueue> queue =
        (__bridge id<MTLCommandQueue>)provider->command_queue();
    command_buffer = MakeAttributedCommandBuffer(queue);
    frame_command_buffer_ = (__bridge_retained void*)command_buffer;
  } else {
    command_buffer = (__bridge id<MTLCommandBuffer>)frame_command_buffer_;
  }
  // Per-target clear policy: each logical target clears on its FIRST use in a
  // frame and loads afterwards. Same-target multi-pass accumulation (JC2's HUD
  // drawn over the composited front buffer after its resolve) keeps working,
  // while distinct targets no longer bleed into each other through a shared
  // texture (each has its own now).
  if (!scratch_only_pass) {
    // A deferred clear load whose attachment this pass does not bind must
    // materialize after all (compute, ahead of the render pass).
    uint32_t bound_color_mask = 0;
    for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
      if (color_targets[i]) {
        bound_color_mask |= 1u << i;
      }
    }
    const bool depth_both_planes =
        depth != nullptr && bind_depth_plane && bind_stencil_plane;
    if (pass_end_undrained_ &&
        render_target_cache_->HasPendingClearLoadsOutside(bound_color_mask,
                                                          depth_both_planes)) {
      DrainUndrainedPassEnd();
    }
    if (!render_target_cache_->FlushPendingClearLoads(
            (__bridge const void*)command_buffer, bound_color_mask,
            depth_both_planes)) {
      return nullptr;
    }
  }
  MTLRenderPassDescriptor* pass =
      [MTLRenderPassDescriptor renderPassDescriptor];
  if (memexport_pass_) {
    // Memexport-only draws: exports go to the shared-memory UAV; the raster
    // output is irrelevant but Metal requires a non-void VS return only when
    // rasterizing, and MSC shaders always return stage-out — so rasterize
    // into a small throwaway scratch depth (DontCare load/store), reusing
    // the dummy-depth texture pool.
    uint64_t dk = (64ull << 20) | 64ull;
    id<MTLTexture> scratch = nil;
    auto dit = dummy_depth_textures_.find(dk);
    if (dit != dummy_depth_textures_.end()) {
      scratch = (__bridge id<MTLTexture>)dit->second;
    } else {
      MTLTextureDescriptor* dd = [MTLTextureDescriptor
          texture2DDescriptorWithPixelFormat:(MTLPixelFormat)
                                                 MetalRenderTargetCache::
                                                     kDepthFormat
                                       width:64
                                      height:64
                                   mipmapped:NO];
      dd.usage = MTLTextureUsageRenderTarget;
      dd.storageMode = MTLStorageModePrivate;
      id<MTLDevice> dev = (__bridge id<MTLDevice>)
          static_cast<rex::ui::metal::MetalProvider*>(
              GetGraphicsDriver().GetProvider())->device();
      scratch = [dev newTextureWithDescriptor:dd];
      scratch.label = @"cp:memexport-scratch-depth";
      dummy_depth_textures_.emplace(dk, (__bridge_retained void*)scratch);
    }
    if (!scratch) {
      return nullptr;
    }
    pass.depthAttachment.texture = scratch;
    pass.depthAttachment.loadAction = MTLLoadActionDontCare;
    pass.depthAttachment.storeAction = MTLStoreActionDontCare;
    pass.stencilAttachment.texture = scratch;
    pass.stencilAttachment.loadAction = MTLLoadActionDontCare;
    pass.stencilAttachment.storeAction = MTLStoreActionDontCare;
  } else if (pixel_export_pass_) {
    // Pixel-export draw with no guest render target: the pixel shader must
    // run over the guest scissor, so rasterize into a scratch depth of that
    // extent (default depth state: test Always, write off). Memoryless on
    // Apple GPUs (DontCare load/store, never backed), private elsewhere.
    const uint32_t scratch_w = pixel_export_extent_[0];
    const uint32_t scratch_h = pixel_export_extent_[1];
    uint64_t dk = (1ull << 62) | (uint64_t(scratch_w) << 24) | scratch_h;
    id<MTLTexture> scratch = nil;
    auto dit = dummy_depth_textures_.find(dk);
    if (dit != dummy_depth_textures_.end()) {
      scratch = (__bridge id<MTLTexture>)dit->second;
    } else {
      id<MTLDevice> dev = (__bridge id<MTLDevice>)
          static_cast<rex::ui::metal::MetalProvider*>(
              GetGraphicsDriver().GetProvider())->device();
      MTLTextureDescriptor* dd = [MTLTextureDescriptor
          texture2DDescriptorWithPixelFormat:(MTLPixelFormat)
                                                 MetalRenderTargetCache::
                                                     kDepthFormat
                                       width:scratch_w
                                      height:scratch_h
                                   mipmapped:NO];
      dd.usage = MTLTextureUsageRenderTarget;
      dd.storageMode = [dev supportsFamily:MTLGPUFamilyApple1]
                           ? MTLStorageModeMemoryless
                           : MTLStorageModePrivate;
      scratch = [dev newTextureWithDescriptor:dd];
      scratch.label = @"cp:pixel-export-scratch-depth";
      if (scratch) {
        dummy_depth_textures_.emplace(dk, (__bridge_retained void*)scratch);
      }
    }
    if (!scratch) {
      return nullptr;
    }
    pass.depthAttachment.texture = scratch;
    pass.depthAttachment.loadAction = MTLLoadActionDontCare;
    pass.depthAttachment.storeAction = MTLStoreActionDontCare;
    pass.stencilAttachment.texture = scratch;
    pass.stencilAttachment.loadAction = MTLLoadActionDontCare;
    pass.stencilAttachment.storeAction = MTLStoreActionDontCare;
  }
  // MSAA draw passes used to end with StoreAndMultisampleResolve into each
  // target's 1-sample copy. In canonical mode nothing reads those copies:
  // packs, materializes and resolves use the MSAA attachment and the
  // canonical EDRAM. The one reader is the pre-resolve presentable fallback,
  // which resolves its target on demand (ResolvePresentableMsaaCopy).
  // USF4 fights 45.4 -> 49.4 fps (reduce-edram-pass-traffic).
  const bool ms_resolve_store =
      raster_sample_count > 1u && MsaaResolveOnStoreEnabled();
  // Attribution probes (frame output is wrong with either): measure what the
  // per-pass attachment load / store traffic costs on the GPU by dropping it.
  // XE_METAL_PROBE_LOAD_DONTCARE=1 loads nothing, XE_METAL_PROBE_STORE_DONTCARE=1
  // stores nothing (MSAA resolve-on-store keeps its resolve). Compare GPU busy
  // against the baseline run; the difference is the traffic share.
  static const bool s_probe_load_dontcare = [] {
    const char* v = std::getenv("XE_METAL_PROBE_LOAD_DONTCARE");
    return v && v[0] == '1' && !v[1];
  }();
  static const bool s_probe_store_dontcare = [] {
    const char* v = std::getenv("XE_METAL_PROBE_STORE_DONTCARE");
    return v && v[0] == '1' && !v[1];
  }();
  const MTLLoadAction probe_load =
      s_probe_load_dontcare ? MTLLoadActionDontCare : MTLLoadActionLoad;
  const MTLStoreAction probe_store =
      s_probe_store_dontcare ? MTLStoreActionDontCare : MTLStoreActionStore;
  const MTLStoreAction probe_store_resolve =
      s_probe_store_dontcare ? MTLStoreActionMultisampleResolve
                             : MTLStoreActionStoreAndMultisampleResolve;
  for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
    if (!color_targets[i]) {
      continue;
    }
    // Always LOAD: textures are cleared at creation; content comes from
    // ownership transfers / persistence, clears from guest resolve clears.
    pass.colorAttachments[i].texture =
        (__bridge id<MTLTexture>)color_targets[i];
    pass.colorAttachments[i].loadAction = probe_load;
    double clear_color[4];
    if (render_target_cache_->TakePendingClearLoad(i, clear_color)) {
      // Untouched whole-tile resolve clear in canonical EDRAM: open on the
      // value the materialize would have written instead of copying it.
      pass.colorAttachments[i].loadAction = MTLLoadActionClear;
      pass.colorAttachments[i].clearColor = MTLClearColorMake(
          clear_color[0], clear_color[1], clear_color[2], clear_color[3]);
    }
    if (ms_resolve_store) {
      pass.colorAttachments[i].resolveTexture =
          (__bridge id<MTLTexture>)color_resolves[i];
      pass.colorAttachments[i].storeAction = probe_store_resolve;
    } else {
      pass.colorAttachments[i].storeAction = probe_store;
    }
  }
  // Depth attachment: cleared to the GUEST's depth-clear value (RB_DEPTH_CLEAR,
  // 24-bit depth in the high bits), not a fixed 1.0. Reverse-z titles (JC2
  // menus) clear to 0 and test "greater"; a hardcoded 1.0 made every fragment
  // fail z>=1.0 -> black. Reading the guest value serves both directions.
  double depth_clear_value = 0.0;
  uint32_t stencil_clear_value = 0;
  const bool depth_clear_load =
      depth && bind_depth_plane && bind_stencil_plane &&
      render_target_cache_->TakePendingDepthClearLoad(&depth_clear_value,
                                                      &stencil_clear_value);
  if (depth && bind_depth_plane) {
    pass.depthAttachment.texture = (__bridge id<MTLTexture>)depth;
    pass.depthAttachment.loadAction = probe_load;
    if (depth_clear_load) {
      pass.depthAttachment.loadAction = MTLLoadActionClear;
      pass.depthAttachment.clearDepth = depth_clear_value;
    }
    if (ms_resolve_store) {
      pass.depthAttachment.resolveTexture =
          (__bridge id<MTLTexture>)depth_resolve;
      pass.depthAttachment.depthResolveFilter =
          MTLMultisampleDepthResolveFilterSample0;
      pass.depthAttachment.storeAction = probe_store_resolve;
    } else {
      pass.depthAttachment.storeAction = probe_store;
    }
  }
  if (depth && bind_stencil_plane) {
    pass.stencilAttachment.texture = (__bridge id<MTLTexture>)depth;
    pass.stencilAttachment.loadAction = probe_load;
    if (depth_clear_load) {
      pass.stencilAttachment.loadAction = MTLLoadActionClear;
      pass.stencilAttachment.clearStencil = stencil_clear_value;
    }
    if (ms_resolve_store) {
      pass.stencilAttachment.resolveTexture =
          (__bridge id<MTLTexture>)depth_resolve;
      pass.stencilAttachment.stencilResolveFilter =
          MTLMultisampleStencilResolveFilterSample0;
      pass.stencilAttachment.storeAction = probe_store_resolve;
    } else {
      pass.stencilAttachment.storeAction = probe_store;
    }
  }
  if (!depth && primary_color_target && dummy_depth_pass_) {
    // The draw's PS exports depth with no depth target bound — attach a
    // throwaway scratch depth so the pipeline is valid (see dummy_depth in
    // IssueDraw). Never loaded, never stored; content is irrelevant.
    id<MTLTexture> rt_tex =
        (__bridge id<MTLTexture>)primary_color_target;
    uint64_t dk = (1ull << 63) | (uint64_t(rt_tex.width) << 32) |
                  (uint64_t(rt_tex.height) << 8) | raster_sample_count;
    id<MTLTexture> dummy_tex = nil;
    auto dit = dummy_depth_textures_.find(dk);
    if (dit != dummy_depth_textures_.end()) {
      dummy_tex = (__bridge id<MTLTexture>)dit->second;
    } else {
      MTLTextureDescriptor* dd = [[MTLTextureDescriptor alloc] init];
      dd.textureType = raster_sample_count > 1u
                           ? MTLTextureType2DMultisample
                           : MTLTextureType2D;
      dd.pixelFormat =
          (MTLPixelFormat)MetalRenderTargetCache::kDepthFormat;
      dd.width = rt_tex.width;
      dd.height = rt_tex.height;
      dd.sampleCount = raster_sample_count;
      dd.usage = MTLTextureUsageRenderTarget;
      dd.storageMode = MTLStorageModePrivate;
      dummy_tex = [rt_tex.device newTextureWithDescriptor:dd];
      dummy_tex.label = @"cp:dummy-depth";
      dummy_depth_textures_.emplace(dk, (__bridge_retained void*)dummy_tex);
    }
    if (dummy_tex) {
      pass.depthAttachment.texture = dummy_tex;
      pass.depthAttachment.loadAction = MTLLoadActionDontCare;
      pass.depthAttachment.storeAction = MTLStoreActionDontCare;
      pass.stencilAttachment.texture = dummy_tex;
      pass.stencilAttachment.loadAction = MTLLoadActionDontCare;
      pass.stencilAttachment.storeAction = MTLStoreActionDontCare;
    }
  }
  // ZPD occlusion queries: Metal takes the visibility buffer on the DESCRIPTOR
  // and offers no way to attach one to a live encoder, so it must be decided
  // here. The pool is created lazily on the first encoder built while a guest
  // report is open -- a title that never issues a query allocates nothing and
  // every encoder below is byte-for-byte what it was before this change.
  if (ZPDSegmentPending() && !zpd_visibility_pool_.is_initialized()) {
    EnsureZPDQueryResources();
  }
  id<MTLBuffer> zpd_visibility_buffer =
      (__bridge id<MTLBuffer>)zpd_visibility_pool_.visibility_buffer();
  if (zpd_visibility_buffer) {
    pass.visibilityResultBuffer = zpd_visibility_buffer;
  }
  // Attribution probe: XE_METAL_PROBE_RT_BOUND_ROWS=N caps every draw pass's
  // render area to N rows (and the attachments' width). Host render targets
  // are allocated at EDRAM-capacity height (a 1280-wide 32bpp target is 2048
  // rows), so a 720-row game loads and stores 1328 untouched rows per pass
  // unless the pass is bounded. Draws past row N are clipped, so the frame is
  // only right when the title never renders below N; the GPU busy delta is
  // what the probe measures (RE5 2026-10-16).
  static const uint32_t s_probe_bound_rows = [] {
    const char* v = std::getenv("XE_METAL_PROBE_RT_BOUND_ROWS");
    return v ? uint32_t(strtoul(v, nullptr, 10)) : 0u;
  }();
  if (s_probe_bound_rows) {
    NSUInteger min_w = 0, min_h = 0;
    auto note_attachment = [&](id<MTLTexture> t) {
      if (!t) {
        return;
      }
      min_w = min_w ? std::min<NSUInteger>(min_w, t.width) : t.width;
      min_h = min_h ? std::min<NSUInteger>(min_h, t.height) : t.height;
    };
    for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
      note_attachment(pass.colorAttachments[i].texture);
    }
    note_attachment(pass.depthAttachment.texture);
    if (min_w && min_h) {
      pass.renderTargetWidth = min_w;
      pass.renderTargetHeight =
          std::min<NSUInteger>(min_h, NSUInteger(s_probe_bound_rows));
    }
  }

  if (PassTimingEnabled()) {
    PassTimingAttach(
        pass, command_buffer.device, want_key,
        memexport_pass_ ? 1u : render_target_cache_->current_msaa_samples(),
        draw_count_,
        [this] { return render_target_cache_->DescribeCurrentAttachments(); });
  }
  const bool deferred_pass = DeferredPassLifecycle();
  MTLRenderPassDescriptor* final_pass =
      metal::MetalApplyXenosSamplePositions(pass);
  // Deferred: the encoder thread creates (and later ends) the encoder; the
  // command processor records into the stream only.
  id<MTLRenderCommandEncoder> encoder =
      deferred_pass
          ? nil
          : [command_buffer renderCommandEncoderWithDescriptor:final_pass];
  NSString* encoder_label = nil;
  // Fault attribution: names this encoder in per-encoder execution status.
  // Formatting an NSString per pass was ~2% of RDR's command-processor
  // thread (CFString formatting, ~100 passes a frame); the label is only
  // read by fault reports and the xctrace breakdown, so it is built when
  // XE_METAL_ENCODER_LABELS=1 (attrib.sh sets it) or a GPU capture is on.
  static const bool s_encoder_labels = [] {
    const char* v = std::getenv("XE_METAL_ENCODER_LABELS");
    return (v && v[0] == '1' && !v[1]) ||
           std::getenv("MTL_CAPTURE_ENABLED") != nullptr;
  }();
  if (s_encoder_labels) {
    encoder_label = [NSString
        stringWithFormat:@"draws@%u rt=%016llX msaa=%u", draw_count_,
                         (unsigned long long)want_key,
                         memexport_pass_
                             ? 1u
                             : render_target_cache_->current_msaa_samples()];
    encoder.label = encoder_label;
  }
  if (deferred_pass) {
    encode_stream_->BeginRenderPass(command_buffer, final_pass, encoder_label);
    // The previous pass's end and this begin are ordered in the stream.
    pass_end_undrained_ = false;
  }
  // The label's rt= value is a one-way rolling hash of the accumulated
  // attachment set (current_attachment_key), so a recurring hash in fault
  // reports cannot be read back into a concrete render target. Log the
  // composition ONCE PER DISTINCT KEY -- bounded by the number of attachment
  // configurations a title uses (tens), not by draws -- so any rt= hash naming
  // a faulted encoder can be resolved after the fact.
  {
    static std::unordered_set<uint64_t> s_logged_attachment_keys;
    if (s_logged_attachment_keys.insert(want_key).second) {
      REXLOG_INFO("MetalRTKeyMap: rt={:016X} draws@{} {}", want_key, draw_count_,
             render_target_cache_->DescribeCurrentAttachments());
    }
  }
  if (deferred_pass) {
    encode_stream_->SetCullMode(MTLCullModeNone);
  } else {
    [encoder setCullMode:MTLCullModeNone];
  }
  // Residency sweep: make EVERY texture any live bindless slot can reach
  // resident on this encoder in one batched call. The per-draw useResource
  // loop covers only that draw's own fetches; a shader indexing any OTHER
  // live slot (stale descriptor index, prior-generation snapshot slot) reads
  // a non-resident texture -> GPU page fault (the attributed 'draws@N'
  // faults). Textures created after this sweep are covered by the per-draw
  // loop as before.
  if (residency_set_) {
    if (residency_set_dirty_) {
      if (@available(macOS 15.0, *)) {
        [(__bridge id<MTLResidencySet>)residency_set_ commit];
      }
      residency_set_dirty_ = false;
      ++residency_commits_;
    }
  } else if (!deferred_pass && texture_cache_ &&
             ResidentSweepEnabled(encoder.device)) {
    resident_sweep_scratch_.clear();
    texture_cache_->AppendAllTextures(resident_sweep_scratch_);
    if (shared_texture_cache_) {
      shared_texture_cache_->AppendAllTextures(resident_sweep_scratch_);
    }
    if (!resident_sweep_scratch_.empty()) {
      MTLRenderStages sweep_stages =
          MTLRenderStageVertex | MTLRenderStageFragment;
      if (mesh_shader_supported_) {
        sweep_stages |= MTLRenderStageObject | MTLRenderStageMesh;
      }
      // void* -> id<MTLTexture> in place (toll-free bridge array).
      [encoder useResources:reinterpret_cast<id<MTLResource> const*>(
                                resident_sweep_scratch_.data())
                      count:resident_sweep_scratch_.size()
                      usage:MTLResourceUsageRead
                     stages:sweep_stages];
    }
  }
  if (deferred_pass) {
    // A non-null token: callers only test the returned encoder for null.
    static char s_deferred_encoder_token;
    frame_render_encoder_ = &s_deferred_encoder_token;
  } else {
    frame_render_encoder_ = (__bridge_retained void*)encoder;
    encode_stream_->SetEncoder(encoder);
  }
  frame_encoder_deferred_ = deferred_pass;
  frame_open_ = true;
  encoder_attachment_key_ = want_key;
  {
    // The Load + Store set this pass binds (scratch DontCare attachments of
    // memexport and dummy-depth passes move no tile traffic and are excluded).
    uint32_t bound = 0;
    uint64_t attachment_bytes[metal::kMetalPassAttachmentCount] = {};
    for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
      if (!color_targets[i]) {
        continue;
      }
      bound |= metal::MetalPassColorAttachmentBit(i);
      id<MTLTexture> t = (__bridge id<MTLTexture>)color_targets[i];
      attachment_bytes[metal::kMetalPassAttachmentColorShift + i] =
          uint64_t(t.width) * t.height * t.sampleCount *
          AttachmentBytesPerPixel(t.pixelFormat);
    }
    if (depth) {
      id<MTLTexture> t = (__bridge id<MTLTexture>)depth;
      uint64_t pixels = uint64_t(t.width) * t.height * t.sampleCount;
      if (bind_depth_plane) {
        bound |= metal::kMetalPassAttachmentDepth;
        attachment_bytes[0] = pixels * AttachmentBytesPerPixel(t.pixelFormat);
      }
      if (bind_stencil_plane) {
        bound |= metal::kMetalPassAttachmentStencil;
        attachment_bytes[1] = pixels;  // the stencil plane
      }
    }
    encoder_bound_attachments_ = bound;
    encoder_pass_signature_ = pending_pass_signature_;
    encoder_depth_stencil_state_ = nullptr;
    encoder_stencil_ref_front_ = encoder_stencil_ref_back_ = ~0u;
    ResetEncoderDedupe();
    if (PassCensusEnabled()) {
      pass_census_.BeginPass(want_key, bound, attachment_bytes);
    }
  }
  encoder_has_zpd_visibility_ = zpd_visibility_buffer != nil;
  {
    static const bool s_zpd_trace =
        std::getenv("XE_METAL_ZPD_TRACE") != nullptr;
    if (s_zpd_trace && zpd_active_segment_.logical_active) {
      REXLOG_INFO("MetalZPDTrace new-encoder draw={} has_vis={} pending_begin={} "
             "segment_active={} query_open={}",
             trace_draw_index_, encoder_has_zpd_visibility_,
             zpd_active_segment_.segment_pending_begin,
             zpd_active_segment_.segment_active, zpd_query_open_);
    }
  }
  // A new encoder is the next valid opportunity for a report whose segment is
  // waiting to open -- either because the guest issued BEGIN with no eligible
  // encoder, or because the previous segment was closed at the last encoder
  // boundary. This is the Metal analogue of Vulkan reopening at render-pass
  // begin. can_close_submission is false: nothing here may commit the command
  // buffer this encoder was just created on.
  if (encoder_has_zpd_visibility_ && ZPDSegmentPending()) {
    OpenQuerySegment(false);
  }
  return frame_render_encoder_;
}

// XE_METAL_S7_OFF=1: live-bisect kill switch — restores pre-S7 lifetime
// semantics (retires/writebacks tagged 0 = reclaimable at the next
// completion, upload ring hard-reset at every new command buffer like the
// old bump arena). Only sound combined with XE_METAL_SYNC_WAIT=1.
// Split variants for narrowing: XE_METAL_S7_OFF_ARENA (ring reset only),
// XE_METAL_S7_OFF_TAGS (zero retire tags only).
bool MetalCommandProcessor::AsyncSubmissionEnabled() {
  // PROMOTED 2026-08-09 (promote-metal-async-submission, GO at gate binary
  // feadfe8f…): unset = ON. The historical ~1/500-swap fault did not occur in
  // 48,640 engaged async swaps (95% UB 1/16,236 swaps — a BOUND, monitored,
  // not "fixed"; see docs/dev/archive/decisions/metal_async_submission_promotion_gate.md). Exact
  // "0" restores full pre-promotion sync semantics bit-identically; malformed
  // warns once and fails closed to that same pre-promotion default — a
  // promotion never widens what counts as enabled beyond unset/exact-1.
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_ASYNC");
    if (!value || !value[0]) {
      return true;  // promoted default
    }
    if (value[0] == '1' && !value[1]) {
      return true;
    }
    if (!(value[0] == '0' && !value[1])) {
      REXLOG_WARN(
          "XE_METAL_ASYNC='{}' is malformed; failing closed to the "
          "pre-promotion synchronous default (use 0 or 1)",
          value);
    }
    return false;
  }();
  return s_enabled;
}

bool MetalCommandProcessor::S7LifetimeOff() {
  // Pre-promotion note (historical): the S7/S8 fast path faulted ~1/500
  // swaps in gameplay and hid under shader validation. The promotion gate
  // measured zero episodes over 48,640 engaged swaps; fault-free exposure is
  // a MONITORED property (standing metal-async-submission spec), and any
  // async fault episode is triaged against these lifetime seams first.
  static const bool s_async = AsyncSubmissionEnabled();
  static const bool s_off =
      std::getenv("XE_METAL_S7_OFF") != nullptr || !s_async;
  return s_off;
}

bool MetalCommandProcessor::S7ArenaResetOff() {
  static const bool s_off = std::getenv("XE_METAL_S7_OFF_ARENA") != nullptr;
  return s_off || S7LifetimeOff();
}

bool MetalCommandProcessor::S7TagsOff() {
  static const bool s_off = std::getenv("XE_METAL_S7_OFF_TAGS") != nullptr;
  return s_off || S7LifetimeOff();
}

bool MetalCommandProcessor::SwapLifetimeEnabled() {
  // DEFAULT ON since the 2026-09-27 counted gate (stage 4 of
  // optimize-metal-gpu-resident-resolve-coherence); XE_METAL_SWAP_LIFETIME=0
  // is the exact-0 rollback to the swap-drained frame lifetime.
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_SWAP_LIFETIME");
    return !(value && value[0] == '0' && !value[1]);
  }();
  return s_enabled;
}

static bool FenceCommitEnabled() {
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_FENCE_COMMIT");
    return !(value && value[0] == '0' && !value[1]);
  }();
  return s_enabled;
}







// A GPU-resident resolve record was just pushed: the shared buffer holds its
// bytes at the guest tiled addresses. Mark the pages GPU-written, fire the
// range watches, and (stage 2) arm demand-driven publication.
void MetalCommandProcessor::RegisterGpuResidentResolve(uint32_t base,
                                                       uint32_t extent_bytes) {
  if (false) {
    playback_gpu_written_.emplace_back(base, extent_bytes);
  }
  pending_writebacks_.back().gpu_current = 1u;
  if (GuestRamWatchOverlaps(base, extent_bytes)) {
    REXLOG_WARN("GuestRamWatch gpu_resolve {:08X}+{:X} seq={} sub={} swap#{}",
           base, extent_bytes, pending_writebacks_.back().authority_sequence,
           pending_writebacks_.back().submission, swap_count_);
  }
  NoteDiscreteProducedResolve(base, extent_bytes);
  // Mark the destination GPU-written so the shared-memory
  // validity model does not upload guest RAM over the freshly
  // scattered bytes. LEAN marking (validity bits only), NOT the
  // memexport-style RangeWrittenByGpu: that fires the global
  // watch, whose queued invalidation applies the DEFAULT
  // kAllRepresentations scope and ERASES the resolve's own
  // just-registered bridge — probe #5 measured 143k vs 13.5k
  // slot re-registrations per arm from exactly this. The CPU
  // path's publication deliberately suppresses the same global
  // fan-out for self-publications; cached-texture refresh is
  // owed (and delivered) by the drain-side invalidation, and
  // mid-frame consumers reach it through the corridor exactly
  // as on the default path.
  if (shared_memory_) {
    shared_memory_->ReassertGpuWritten(
        base, extent_bytes);
    // The content-change signal for WATCHING textures (the
    // shared-route entries reload from the buffer, GPU-ordered)
    // — per-range only, so the global fan-out's default-scope
    // invalidation cannot retire this resolve's own bridge
    // (the probe #5/#6 churn). Without this, an
    // ordering-served consumer reads the PREVIOUS generation's
    // route entry (SF4 10581: 125k px when ordering first
    // fired in replay).
    shared_memory_->FireRangeWatchesBackend(
        base, extent_bytes,
        /*invalidated_by_gpu=*/true);
  }
  if (lazy_read_callback_handle_ && true &&
      true) {
    // Stage 2: arm now (page ownership + read watch), and retire
    // older armed GPU-current records this one fully covers --
    // their bytes are superseded in the buffer, RAM will get the
    // newest on demand, and an unbounded pending list would make
    // every consumer decision O(records).
    const uint32_t new_start = pending_writebacks_.back().guest_addr;
    const uint32_t new_end =
        new_start + pending_writebacks_.back().range_bytes();
    const uint64_t newest_sequence =
        pending_writebacks_.back().authority_sequence;
    for (auto it = pending_writebacks_.begin();
         it != pending_writebacks_.end();) {
      if (it->authority_sequence != newest_sequence &&
          it->gpu_current && it->lazy_armed && !it->staging &&
          it->guest_addr >= new_start &&
          it->guest_addr + it->range_bytes() <= new_end) {
        // Ordering census (XE_METAL_LAZY_ORDER_CENSUS): byte-range nesting
        // does not imply the newer rectangle rewrote the older one's texels
        // (sub-rectangles at one base, different offsets). Count retires the
        // geometry cannot prove superseded.
        static const bool s_retire_census =
            std::getenv("XE_METAL_LAZY_ORDER_CENSUS") != nullptr;
        // Strict covered retire (XE_METAL_LAZY_RETIRE_STRICT=1, default OFF:
        // 2026-10-25 RotTR A/B made the flash MORE frequent, 56/409 vs
        // 7/135, so retention is not the answer there; kept as a lever):
        // a byte-range nesting is only a retirement when the newer rectangle
        // provably rewrites every texel of the older one. Otherwise the older
        // record stays pending: its bytes are still the GPU's newest for the
        // texels the newer resolve did not touch, uploads must keep skipping
        // its span and lazy publication must still own it. Rise of the Tomb
        // Raider 2026-10-25: its transient ring interleaves CPU scratch with
        // 32x32 colour-LUT slab resolves; an 8x8 resolve landing on a slab's
        // base retired the slab "covered", the slab was never published, and
        // the page's next CPU upload copied stale RAM over the slab while the
        // frame's LUT load (and the previous frame's, in flight) still read
        // it: one psychedelic frame (~8% of gameplay seconds).
        static const bool s_retire_strict = metal::ParseMetalEnvironmentFlag(
            std::getenv("XE_METAL_LAZY_RETIRE_STRICT"), false);
        if (s_retire_census || s_retire_strict) {
          const PendingWriteback& nw = pending_writebacks_.back();
          auto pitch = [](const PendingWriteback& w) {
            return w.dest_pitch_aligned ? w.dest_pitch_aligned
                                        : ((w.width + 31u) & ~31u);
          };
          // A tiled resolve whose rectangle is its whole pitch from row 0 in
          // whole 32-row bands writes every byte of its extent.
          bool newer_whole_extent =
              nw.dest_offset_x == 0 && nw.dest_offset_y == 0 &&
              nw.width == pitch(nw) && (nw.height & 31u) == 0;
          // Otherwise same pitch and bpp with a base offset of whole 32x32
          // tiles: tiled addresses are linear in the tile index and the
          // bank/pipe bits only see (x >> 3) & 3 and y & 24, which whole-tile
          // shifts leave unchanged, so the older rectangle sits at
          // (+shift_x, +shift_y) in the newer record's frame.
          bool contained = newer_whole_extent;
          const uint32_t tile_bytes = 32u * 32u * nw.bpp;
          const uint32_t tiles_per_row = pitch(nw) / 32u;
          if (!contained && it->bpp == nw.bpp && pitch(*it) == pitch(nw) &&
              tile_bytes && tiles_per_row && it->guest_addr >= nw.guest_addr &&
              (it->guest_addr - nw.guest_addr) % tile_bytes == 0) {
            uint32_t tiles = (it->guest_addr - nw.guest_addr) / tile_bytes;
            uint32_t shift_x = tiles % tiles_per_row * 32u;
            uint32_t shift_y = tiles / tiles_per_row * 32u;
            contained =
                it->dest_offset_x + shift_x >= nw.dest_offset_x &&
                it->dest_offset_x + shift_x + it->width <=
                    nw.dest_offset_x + nw.width &&
                it->dest_offset_y + shift_y >= nw.dest_offset_y &&
                it->dest_offset_y + shift_y + it->height <=
                    nw.dest_offset_y + nw.height;
          }
          static uint64_t s_retires = 0, s_unproven = 0;
          ++s_retires;
          if (!contained && s_retire_strict) {
            ++s_unproven;
            if (s_retire_census && s_unproven <= 100) {
              REXLOG_WARN(
                  "MetalLazyRetireCensus #{} swap#{}: KEPT {:08X} {}x{} "
                  "off=({},{}) bpp={} pitch={} under {:08X} {}x{} off=({},{}) "
                  "bpp={} pitch={} (not provably superseded)",
                  s_unproven, swap_count_, it->guest_addr, it->width,
                  it->height, it->dest_offset_x, it->dest_offset_y, it->bpp,
                  pitch(*it), nw.guest_addr, nw.width, nw.height,
                  nw.dest_offset_x, nw.dest_offset_y, nw.bpp, pitch(nw));
            }
            ++it;
            continue;
          }
          if (!contained) {
            ++s_unproven;
            if (s_unproven <= 100) {
              REXLOG_WARN(
                  "MetalLazyRetireCensus #{} swap#{}: retired {:08X} {}x{} "
                  "off=({},{}) bpp={} pitch={} under {:08X} {}x{} off=({},{}) "
                  "bpp={} pitch={}",
                  s_unproven, swap_count_, it->guest_addr, it->width,
                  it->height, it->dest_offset_x, it->dest_offset_y, it->bpp,
                  pitch(*it), nw.guest_addr, nw.width, nw.height,
                  nw.dest_offset_x, nw.dest_offset_y, nw.bpp, pitch(nw));
            }
          }
          if ((s_retires & 1023) == 1) {
            REXLOG_INFO(
                "MetalLazyRetireCensus summary: {} covered retires, {} not "
                "provably superseded",
                s_retires, s_unproven);
          }
        }
              // (lazy publication removed)
        it = pending_writebacks_.erase(it);
      } else {
        ++it;
      }
    }
    // Lazy publication is gone: every writeback publishes eagerly.
  }
}

bool MetalCommandProcessor::NeedBasedWaitsEnabled() {
  // DEFAULT ON since 2026-10-31: a consumer that needs a producer's output
  // waits for that producer's submission only, instead of committing and
  // draining the whole open command buffer. Fable II on the M1 Max 19 -> 30
  // fps (41 tess-factor reads/frame each drained ~410 draws); library sweeps
  // on the M1 Max and M4 mini unchanged elsewhere, 0 faults/skips. Rollback:
  // XE_METAL_NEED_BASED_WAITS=0 (exact 0 / malformed = off, the house shape).
  static const bool s_enabled = [] {
    const char* value = std::getenv(metal::kNeedBasedWaitsEnvVar);
    if (value && value[0] && !((value[0] == '0' || value[0] == '1') &&
                               !value[1])) {
      REXLOG_WARN(
          "XE_METAL_NEED_BASED_WAITS='{}' is malformed; failing closed to off "
          "(use 0 or 1)",
          value);
    }
    // Empty counts as unset (harness arms pass VAR= for the default).
    return metal::ParseMetalEnvironmentFlag(value && value[0] ? value : nullptr,
                                            true);
  }();
  return s_enabled;
}

bool MetalCommandProcessor::ResolveSnapshotsForAllEnabled() {
  static const bool enabled = [] {
    const char* value = std::getenv("XE_METAL_SNAPSHOT_ALL");
    return value && value[0] == '1' && !value[1];
  }();
  return enabled;
}

bool MetalCommandProcessor::ResolveOverlapsRecentFrontbuffer(
    uint32_t start, uint32_t length) const {
  for (const auto& [base, bytes] : recent_frontbuffers_) {
    if (bytes && start < base + bytes && start + std::max(length, 1u) > base) {
      return true;
    }
  }
  return false;
}

// Whether MSAA draw passes still resolve into their targets' 1-sample copies
// on store. Off by default (the copies are unread in canonical mode);
// XE_METAL_MS_RESOLVE_STORE=1 is the exact rollback. The diagnostics that read
// a target's 1-sample contents keep it on.
bool MetalCommandProcessor::MsaaResolveOnStoreEnabled() {
  static const bool enabled = [] {
    const char* value = std::getenv("XE_METAL_MS_RESOLVE_STORE");
    if (value && value[0] == '1' && !value[1]) {
      return true;
    }
    for (const char* diag : {"XE_METAL_PROBE_RESOLVE", "XE_METAL_DUMP_DEPTH",
                             "XE_METAL_DUMP_RT", "XE_METAL_PRECLEAR_RT"}) {
      if (std::getenv(diag)) {
        return true;
      }
    }
    return false;
  }();
  return enabled;
}

bool MetalCommandProcessor::SharedResolveArraysEnabled() {
  // Default ON (XE_METAL_SHARED_RESOLVE_ARRAYS=0 rolls back to the CPU slice
  // writeback). Array / slice destinations take the shared resolve shaders:
  // Rise of the Tomb Raider builds a 32x32x32 colour-grading LUT from 32
  // slice resolves a frame, and the CPU writeback cost ~8 ms of GPU wait and
  // 35 texture drains a swap. The route first shipped opt-in because the
  // volume consumer sampled stale bytes: the direct colour path skipped the
  // canonical EDRAM pack the shared shader reads, and RAM publication walked
  // the slice with the 2D addresser. Both fixed (replay oracle: frame 24610,
  // LUT texture and RAM byte-identical to the CPU path).
  static const bool s_enabled = [] {
    const char* v = std::getenv("XE_METAL_SHARED_RESOLVE_ARRAYS");
    return !(v && v[0] == '0' && !v[1]);
  }();
  return s_enabled;
}

bool MetalCommandProcessor::ResolveNumberFormatEnabled() {
  // Fixed-point resolve destinations pack by RB_COPY_DEST_INFO's number
  // format (signed fraction / integer) instead of always as an unsigned
  // fraction. Rise of the Tomb Raider resolves its -32..32 particle target
  // with exp_bias -5 into a signed 16_16_16_16 texture; the unsigned pack
  // zeroed every negative value and the composite washed the frame.
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_RESOLVE_NUMBER_FORMAT");
    return !(value && value[0] == '0' && !value[1]);
  }();
  return s_enabled;
}

bool MetalCommandProcessor::SharedResolveShadersEnabled() {
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_SHARED_RESOLVE");
    if (!value || !value[0]) {
      return false;
    }
    if (value[0] == '1' && !value[1]) {
      return true;
    }
    if (!(value[0] == '0' && !value[1])) {
      REXLOG_WARN(
          "XE_METAL_SHARED_RESOLVE='{}' is malformed; failing closed to off "
          "(use 0 or 1)",
          value);
    }
    return false;
  }();
  return s_enabled;
}

// Dispatch the SHARED resolve-copy shader for `resolve_info`, writing EDRAM
// output straight into the shared-memory buffer at guest tiled addresses.
// Mirrors the D3D12/Vulkan sequence exactly (d3d12_render_target_cache.cc
// ~1385-1412): shared selector -> commit destination -> bind -> dispatch ->
// invalidate. Returns false if anything is unavailable, and the caller keeps
// its existing path; nothing here is a fallback of its own.
bool MetalCommandProcessor::DispatchSharedResolveCopy(
    const draw_util::ResolveInfo& resolve_info) {
  // Bounded decline reporting. A route that silently declines looks exactly
  // like a route that ran and changed nothing -- which is precisely how the
  // first live run read (0 dispatches, identical fps, zero faults).
  static uint32_t s_decline_logs = 0;
  auto decline = [&](const char* reason) {
    if (s_decline_logs++ < 16) {
      REXLOG_WARN("MetalSharedResolve: declined ({}) dest={:08X}", reason,
             resolve_info.copy_dest_base);
    }
    return false;
  };
  if (!resolve_shader_pipelines_.initialized()) {
    return decline("pipelines-uninitialized");
  }
  if (!shared_memory_ || !render_target_cache_ || !frame_command_buffer_) {
    return decline("no-shared-memory-or-cache-or-cb");
  }
  draw_util::ResolveCopyShaderConstants constants;
  uint32_t group_count_x = 0;
  uint32_t group_count_y = 0;
  // ONE selector, shared with D3D12/Vulkan: it decides the shader, fills the
  // constants and returns the dispatch shape, at the draw resolution scale.
  draw_util::ResolveCopyShaderIndex shader_index = resolve_info.GetCopyShader(
      draw_resolution_scale_x_, draw_resolution_scale_y_, constants,
      group_count_x, group_count_y);
  if (shader_index == draw_util::ResolveCopyShaderIndex::kUnknown) {
    return decline("shader-index-unknown");
  }
  if (!group_count_x || !group_count_y) {
    return decline("empty-dispatch");
  }
  void* pipeline_ptr = resolve_shader_pipelines_.PipelineFor(shader_index);
  if (!pipeline_ptr) {
    return decline("no-pipeline-for-index");
  }
  // BISECT (task 6.1). The failing SF4 resolves differ from the working JC2
  // ones almost only in EDRAM source placement: base_tiles 48 vs 0 and
  // pitch_tiles 7 vs 4. Metal materializes its canonical EDRAM PER RESOLVE
  // (PrepareCanonicalEdramForResolve over the resolve's span), so a shared
  // shader reading a source region Metal never prepared would read garbage.
  // These gates isolate that without changing any default.
  static const bool s_base0_only =
      std::getenv("XE_METAL_SHARED_RESOLVE_BASE0") != nullptr;
  static const bool s_pitch4_only =
      std::getenv("XE_METAL_SHARED_RESOLVE_PITCH4") != nullptr;
  if (s_base0_only && uint32_t(resolve_info.color_edram_info.base_tiles) != 0) {
    return decline("bisect-nonzero-edram-base");
  }
  if (s_pitch4_only && uint32_t(resolve_info.color_edram_info.pitch_tiles) != 4) {
    return decline("bisect-pitch-not-4");
  }
  // Commit the destination pages before the GPU writes them, exactly as the
  // other backends do. Without this the buffer's content for the destination
  // extent is not established, and the parts of the extent the resolve does
  // not write (tiled alignment padding) would not hold guest content.
  if (!shared_memory_->RequestRange(resolve_info.copy_dest_extent_start,
                                    resolve_info.copy_dest_extent_length)) {
    return decline("dest-request-range-failed");
  }
  id<MTLBuffer> dest_buffer =
      (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
  id<MTLBuffer> edram_buffer =
      (__bridge id<MTLBuffer>)render_target_cache_->canonical_edram_buffer();
  if (!dest_buffer || !edram_buffer) {
    return decline("null-dest-or-edram-buffer");
  }
  // SENTINEL DIAGNOSTIC (XE_METAL_SHARED_RESOLVE_SENTINEL=1): stamp the
  // destination extent in the shared buffer with a known pattern BEFORE the
  // dispatch. Whatever survives to publication tells us, unambiguously,
  // whether the shared shader wrote these bytes at all -- the question the
  // grid-shrink null raised. The buffer is MTLStorageModeShared, so the CPU
  // fill lands before the GPU executes the dispatch encoded below.
  static const bool s_sentinel =
      std::getenv("XE_METAL_SHARED_RESOLVE_SENTINEL") != nullptr;
  if (s_sentinel) {
    uint8_t* contents = static_cast<uint8_t*>(dest_buffer.contents);
    if (contents) {
      std::memset(contents + resolve_info.copy_dest_extent_start, 0xA5,
                  resolve_info.copy_dest_extent_length);
    }
  }
  id<MTLCommandBuffer> command_buffer =
      (__bridge id<MTLCommandBuffer>)frame_command_buffer_;
  id<MTLComputeCommandEncoder> encoder = [command_buffer computeCommandEncoder];
  encoder.label = @"cp:shared-resolve-copy";
  [encoder setComputePipelineState:(__bridge id<MTLComputePipelineState>)
                                       pipeline_ptr];
  // Pass the SHARED struct verbatim, exactly as D3D12 does
  // (SetComputeRoot32BitConstants over &copy_shader_constants). Rebuilding it
  // field-by-field from accessors would put this backend's transcription
  // between the shared producer and the shared shader -- the same duplicated
  // contract this whole redirection exists to remove.
  static_assert(sizeof(draw_util::ResolveCopyShaderConstants) ==
                    sizeof(MetalResolveShaderPipelines::ResolveConstants),
                "Metal push-constant mirror must match the shared struct");
  [encoder setBytes:&constants
             length:sizeof(constants)
            atIndex:MetalResolveShaderPipelines::kBufferIndexPushConstants];
  [encoder setBuffer:dest_buffer
              offset:0
             atIndex:MetalResolveShaderPipelines::kBufferIndexDest];
  [encoder setBuffer:edram_buffer
              offset:0
             atIndex:MetalResolveShaderPipelines::kBufferIndexEdram];
  // THREADGROUP SIZE IS NOT THE GROUP'S PIXEL FOOTPRINT.
  // `resolve_copy_shader_info[].group_size_{x,y}_log2` is the number of PIXELS
  // a group covers (64x8 for the fast 32bpp shader), and the shared host
  // contract already used it to derive `group_count_{x,y}`. The MSL
  // threadgroup is the shader's own LOCAL_SIZE, which is 8x8 for EVERY
  // resolve copy shader in the family. Passing the pixel footprint here
  // dispatched 512 threads per group against a shader indexing by
  // `thread_position_in_grid`, so every thread resolved a correctly-addressed
  // but WRONG pixel -- dense content where the incumbent reads an empty
  // surface.
  static constexpr uint32_t kResolveLocalSizeX = 8;
  static constexpr uint32_t kResolveLocalSizeY = 8;
  MTLSize threads = MTLSizeMake(kResolveLocalSizeX, kResolveLocalSizeY, 1);
  [encoder dispatchThreadgroups:MTLSizeMake(group_count_x, group_count_y, 1)
          threadsPerThreadgroup:threads];
  [encoder endEncoding];
  // Engagement evidence. "Identical output" is only meaningful if the route
  // actually ran: a dispatcher that declined every resolve would produce a
  // byte-identical corpus for the trivial reason that nothing changed.
  ++shared_resolve_dispatches_;
  static uint32_t s_logs = 0;
  if (s_logs++ < 8) {
    REXLOG_INFO(
        "MetalSharedResolve: dispatched shader={} groups={}x{} dest={:08X} "
        "msaa={} sample_select={} edram_fmt={} 64bpp={} dest_fmt={} "
        "endian={} swap={} exp_bias={} edram_base={} edram_pitch={}",
        size_t(shader_index), group_count_x, group_count_y,
        resolve_info.copy_dest_base,
        uint32_t(resolve_info.color_edram_info.msaa_samples),
        uint32_t(resolve_info.copy_dest_coordinate_info.copy_sample_select),
        uint32_t(resolve_info.color_edram_info.format),
        uint32_t(resolve_info.color_edram_info.format_is_64bpp),
        uint32_t(resolve_info.copy_dest_info.copy_dest_format),
        uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
        uint32_t(resolve_info.copy_dest_info.copy_dest_swap),
        int32_t(resolve_info.copy_dest_info.copy_dest_exp_bias),
        uint32_t(uint32_t(resolve_info.color_edram_info.base_tiles)),
        uint32_t(uint32_t(resolve_info.color_edram_info.pitch_tiles)));
  }
  return true;
}

bool MetalCommandProcessor::GpuResolveScatterEnabled() {
  // XE_METAL_GPU_RESOLVE (exact-0 rollback, DEFAULT ON since the 2026-08-29
  // counted gate: JC2 +12.0% / VP +4.9% across 24 ordinals, zero faults,
  // 12k-swap soaks green — see
  // xenia-mac-evidence/stage-b-reopen-20260818/gate/).
  // Stage B of implement-metal-gpu-visible-resolve-authority. The canonical
  // packed resolve writes GUEST-TILED straight into the shared buffer, the
  // record becomes GPU-current, and shared-buffer consumers stop waiting for
  // it. =0 is byte-identical to the staging + CPU-scatter path.
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_GPU_RESOLVE");
    if (!value || !value[0]) {
      return true;
    }
    if (value[0] == '0' && !value[1]) {
      return false;
    }
    if (!(value[0] == '1' && !value[1])) {
      REXLOG_WARN(
          "XE_METAL_GPU_RESOLVE='{}' is malformed; failing open to the "
          "default (on; use 0 or 1)",
          value);
    }
    return true;
  }();
  return s_enabled;
}

bool MetalCommandProcessor::ServingCensusEnabled() {
  // Exact-1 opt-in, default OFF, same house shape as the flags above. No
  // banner: this census changes nothing about the run, so a run carrying it is
  // still an ordinary run — only the extra classification work is added, which
  // is why it is not enabled during counted performance arms.
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_SERVING_CENSUS");
    return value && value[0] == '1' && !value[1];
  }();
  return s_enabled;
}

bool MetalCommandProcessor::SkipConsumerWaitEnabled() {
  // Exact-1 opt-in, warn-once fail-closed, DEFAULT OFF -- the house flag shape
  // (SeamTimingEnabled). The banner is a WARNING and prints exactly
  // once, from the first consultation: any log containing it names a run whose
  // guest-visible output is untrusted, which is what makes the arm disclosure
  // checkable after the fact.
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_SKIP_CONSUMER_WAIT");
    if (!value || !value[0]) {
      return false;
    }
    if (value[0] == '1' && !value[1]) {
      REXLOG_WARN(
          "XE_METAL_SKIP_CONSUMER_WAIT=1: consumer-dependency completion "
          "waits are ELIDED and pending producer records publish without "
          "finality proof. Guest reads may see STALE data. Diagnostic "
          "ceiling probe -- performance evidence only, correctness "
          "intentionally broken.");
      return true;
    }
    if (!(value[0] == '0' && !value[1])) {
      REXLOG_WARN(
          "XE_METAL_SKIP_CONSUMER_WAIT='{}' is malformed; failing closed to "
          "off (use 0 or 1)",
          value);
    }
    return false;
  }();
  return s_enabled;
}

void MetalCommandProcessor::PublishCompletedSubmission(uint64_t submission) {
  {
    // The high-water advance happens INSIDE completion_mutex_, not beside it.
    // The mutex is the truth boundary the waiter's locked re-check reads
    // across: publishing outside it left a window where a waiter could hold
    // the lock, observe "not yet completed", and be overtaken by this advance
    // before it reached the condition variable — the waiter would then be
    // counted as blocked and never wait. WaitForSubmission's kWait...Blocked
    // counter is evidence, and an attempted wait reported as a stall is
    // exactly the misreport the cost vocabulary forbids.
    //
    // Monotonic CAS retained even though the mutex now serializes publishers:
    // the value is still read LOCK-FREE by acquire loads all over this file
    // (GetCompletedSubmission, PumpCompletedActions, the fast path below), so
    // the release store is what publishes this submission's work to them, and
    // the compare keeps a late/out-of-order completion callback from moving
    // the high-water backwards.
    std::lock_guard<std::mutex> lock(completion_mutex_);
    uint64_t prev = completed_submission_.load(std::memory_order_relaxed);
    while (prev < submission &&
           !completed_submission_.compare_exchange_weak(
               prev, submission, std::memory_order_release,
               std::memory_order_relaxed)) {
    }
  }
  // Wake WaitForSubmission (S8) AFTER unlocking: a waiter woken here would
  // otherwise immediately re-block on the mutex we still held. No wakeup is
  // lost, because a waiter either (a) already holds the mutex, in which case
  // this store could not have happened until it entered the wait, or (b) takes
  // the mutex after this store and its predicate sees the new value without
  // waiting at all.
  completion_cv_.notify_all();
}

namespace {
// XE_FRAME_PACING_CENSUS: the command-processor wait site of the current
// WaitForSubmission (-1 = untagged, e.g. a guest thread's lazy read; not
// counted), and the blocked time per site.
enum PacingWaitSite : int {
  kPacingInFlightCap,
  kPacingSyncWait,
  kPacingDrainNeed,
  kPacingDrainRequired,
  kPacingSwapRing,
  kPacingSeamDirect,
  kPacingWaitSiteCount,
};
thread_local int tls_pacing_wait_site = -1;
std::atomic<uint64_t> g_pacing_wait_site_ns[kPacingWaitSiteCount];
struct ScopedPacingWaitSite {
  int previous;
  explicit ScopedPacingWaitSite(int site) : previous(tls_pacing_wait_site) {
    tls_pacing_wait_site = site;
  }
  ~ScopedPacingWaitSite() { tls_pacing_wait_site = previous; }
};
}  // namespace

bool MetalCommandProcessor::WaitForSubmission(uint64_t submission,
                                              uint32_t timeout_ms,
                                              bool* out_did_block) {
  // Three separate facts, because collapsing them would misreport the cost: how
  // often the path was taken at all, how often it actually blocked, and how
  // often it gave up. The call is counted before the fast path so a wait
  // satisfied immediately is still visible as a wait that was requested.
  zero_copy_cost_.Count(metal::ZeroCopyCostCounter::kWaitForSubmissionCalls);
  if (out_did_block) {
    *out_did_block = false;
  }
  if (completed_submission_.load(std::memory_order_acquire) >= submission) {
    return true;
  }
  std::unique_lock<std::mutex> lock(completion_mutex_);
  // Counted here, not at the fast-path miss above: the submission can complete
  // between that unlocked check and this one, and a wait the condition variable
  // satisfies without sleeping is not a stall. Counting the miss would report
  // every completion race as a block.
  //
  // This re-check is EXACT, not merely likelier to be right, because
  // PublishCompletedSubmission advances the high-water under this same mutex,
  // which we hold continuously from here through wait_for's first predicate
  // evaluation. So a false re-check cannot be overtaken before the wait: the
  // count means the caller really did enter the condition-variable wait. It
  // does NOT claim the wait was long — a publisher already queued on this
  // mutex will wake it almost at once — only that the wait was entered, which
  // is the strongest fact this seam can state and the one the counter's name
  // is held to.
  if (completed_submission_.load(std::memory_order_acquire) < submission) {
    zero_copy_cost_.Count(
        metal::ZeroCopyCostCounter::kWaitForSubmissionBlocked);
    // The one exact blocking fact (see the comment above): callers wanting
    // blocked-attribution get it from HERE, never from their own unlocked
    // pre-checks.
    if (out_did_block) {
      *out_did_block = true;
    }
  }
  const int64_t pacing_wait_start =
      FramePacingCensusEnabled() ? FramePacingNowNs() : 0;
  bool ok = completion_cv_.wait_for(
      lock, std::chrono::milliseconds(timeout_ms), [&] {
        return completed_submission_.load(std::memory_order_acquire) >=
               submission;
      });
  if (pacing_wait_start && tls_pacing_wait_site >= 0) {
    const uint64_t waited = uint64_t(FramePacingNowNs() - pacing_wait_start);
    GetFramePacingClock().gpu_waited_ns.fetch_add(waited,
                                                  std::memory_order_relaxed);
    g_pacing_wait_site_ns[tls_pacing_wait_site].fetch_add(
        waited, std::memory_order_relaxed);
  }
  if (!ok) {
    zero_copy_cost_.Count(
        metal::ZeroCopyCostCounter::kWaitForSubmissionTimeouts);
    REXLOG_ERROR(
        "MetalCommandProcessor: TIMEOUT waiting for submission {} "
        "(completed {}) — GPU wedged?",
        submission, completed_submission_.load(std::memory_order_acquire));
  }
  return ok;
}

namespace {
void EmitFaultEpisode(const metal::FaultEpisodeSummary& s, const char* why) {
  if (!s.valid) {
    return;
  }
  // The one line answering "how many times did the GPU actually break".
  REXLOG_ERROR(
      "MetalGpuFaultEpisode episode={} epoch={} root_serial={} "
      "failed_submissions={} closed_by={}",
      s.episode, s.epoch, s.root_serial, s.failed_submissions, why);
}
}  // namespace

void MetalCommandProcessor::AssertFaultEpochOwnership() const {
  // ENFORCED, not merely documented. Episode attribution depends on epoch
  // capture/reservation never interleaving with epoch mutation/finalization,
  // and that is guaranteed only by both running on the GPU thread. A comment
  // cannot survive a future submission-thread refactor; this will fail it
  // loudly in Checked/Debug instead. worker_thread_ is null under trace replay,
  // where there is no separate GPU thread and the invariant holds trivially.
  assert_true(gpu_thread_id_ == std::thread::id{} ||
              std::this_thread::get_id() == gpu_thread_id_);
}

void MetalCommandProcessor::MarkFaultEpochClosed(uint64_t epoch) {
  AssertFaultEpochOwnership();
  // Closing is NOT finalizing: a late callback bearing this epoch can still
  // revise the root downward, so the summary waits for outstanding == 0.
  fault_episodes_.MarkEpochClosed(epoch);
  SweepFinalizedFaultEpisodes();
}

void MetalCommandProcessor::SweepFinalizedFaultEpisodes() {
  for (uint32_t i = 0; i < fault_episodes_.tracked_epoch_count(); ++i) {
    uint64_t epoch = fault_episodes_.tracked_epoch_at(i);
    uint32_t outstanding =
        epoch_outstanding_[epoch % kFaultEpochSlots].load(
            std::memory_order_acquire);
    metal::FaultEpisodeSummary summary =
        fault_episodes_.TryFinalize(epoch, outstanding);
    EmitFaultEpisode(summary, "closed+drained");
  }
}

uint64_t MetalCommandProcessor::NoteFaultEpisodeMember(uint64_t submission,
                                                       uint64_t submit_epoch) {
  metal::EpisodeAdmission admission = metal::EpisodeAdmission::kAdmitted;
  uint64_t episode =
      fault_episodes_.NoteMember(submission, submit_epoch, &admission);
  if (admission == metal::EpisodeAdmission::kNoCapacity &&
      !fault_capture_disabled_) {
    // NEVER evict: an evicted epoch may still receive a late callback, and
    // losing that attribution silently is the failure this accounting exists
    // to prevent. Fail loudly and stop capturing instead.
    fault_capture_disabled_ = true;
    REXLOG_ERROR(
        "MetalGpuFaultEpisode: episode capacity exhausted ({} live epochs, "
        "none finalizable); DISABLING further episode capture rather than "
        "evicting attribution that may still receive a late callback",
        fault_episodes_.live_epochs());
  }
  return episode;
}

void MetalCommandProcessor::DrainFaultedCommandBuffers() {
  // Owns every epoch mutation and every finalize sweep.
  AssertFaultEpochOwnership();
  std::vector<FaultedCompletion> faulted;
  {
    std::lock_guard<std::mutex> lock(fault_mutex_);
    faulted.swap(faulted_completions_);
  }
  std::vector<uint64_t> faulted_ids;
  faulted_ids.reserve(faulted.size());
  for (const FaultedCompletion& completion : faulted) {
    faulted_ids.push_back(completion.submission);
  }
  frame_gpu_fault_count_ += uint32_t(faulted_ids.size());
  // Any epoch that is closed and fully drained can now publish its FINAL root.
  SweepFinalizedFaultEpisodes();
  for (uint64_t id : faulted_ids) {
    faulted_submissions_.insert(id);
    // Bounded: fault-attribution evidence, not a growing ledger.
    if (faulted_submissions_.size() > 256) {
      faulted_submissions_.clear();
      faulted_submissions_.insert(id);
    }
  }
  // C1T-R M4 (mandatory): eagerly invalidate routed textures whose load rode
  // a lost submission — through the shared-memory authority, independent of
  // the bounded fault set above.
  if (shared_texture_cache_ && !faulted_ids.empty()) {
    shared_texture_cache_->OnSubmissionsFaulted(faulted_ids);
  }
  for (const FaultedCompletion& completion : faulted) {
    id<MTLCommandBuffer> command_buffer =
        (__bridge_transfer id<MTLCommandBuffer>)completion.command_buffer;
    const uint64_t faulted_submission = completion.submission;
    // Episode assignment BEFORE logging, so every fault line carries the
    // episode it belongs to and root/collateral can be told apart without
    // reconstructing it from revoke lines afterwards.
    const uint64_t episode =
        NoteFaultEpisodeMember(faulted_submission, completion.submit_epoch);
    const uint32_t s_cb_errors = ++cb_error_count_;
    if (s_cb_errors <= 32 || (s_cb_errors & 255) == 0) {
      LogCommandBufferFault(command_buffer, "frame commit", swap_count_,
                            faulted_submission, episode);
      REXLOG_ERROR("  state: residency members={} in-flight={} (latest submission "
             "{}, completed {}), texture slots {}/{}, footprint {:.0f} MB",
             residency_members_.size(),
             submission_counter_ -
                 completed_submission_.load(std::memory_order_acquire),
             submission_counter_,
             completed_submission_.load(std::memory_order_acquire),
             texture_cache_ ? texture_cache_->slots_used() : 0,
             texture_cache_ ? texture_cache_->slots_capacity() : 0,
             ProcessFootprintMiB());
      REXLOG_ERROR("  committed by {}; recent loads: {}",
             submission_counter_ - faulted_submission < 64
                 ? metal::SeamBoundaryReasonName(metal::SeamBoundaryReason(
                       submission_reason_ring_[faulted_submission % 64]))
                 : "(unknown)",
             shared_texture_cache_ ? shared_texture_cache_->DescribeRecentLoads()
                                   : std::string("(no shared cache)"));
      {
        std::map<std::pair<uint64_t, uint64_t>, std::pair<uint32_t, uint32_t>>
            pairs;
        for (const DrawPairNote& note : draw_pair_ring_) {
          if (note.submission == faulted_submission) {
            auto& entry = pairs[{note.vs, note.ps}];
            entry.first += note.count;
            entry.second = note.prim;
          }
        }
        std::string draws;
        for (const auto& [pair, entry] : pairs) {
          draws += fmt::format(" {:016X}/{:016X}:{}x{}", pair.first,
                               pair.second, entry.second, entry.first);
        }
        REXLOG_ERROR("  draws (vs/ps:prim x count):{}",
               draws.empty() ? std::string(" (none recorded)") : draws);
        // The same runs in issue order, by draw index, to place them in the
        // encoders the execution status names (draws@ labels).
        std::string sequence;
        uint32_t runs = 0;
        for (uint32_t i = 0; i < 8192; ++i) {
          const DrawPairNote& note =
              draw_pair_ring_[(draw_pair_next_ + i) % 8192];
          if (note.submission != faulted_submission) {
            continue;
          }
          if (++runs > 400) {
            sequence += " ...";
            break;
          }
          sequence += fmt::format(" @{}:{:08X}/{:08X}:{}x{}", note.first_draw,
                                  uint32_t(note.vs), uint32_t(note.ps),
                                  note.prim, note.count);
        }
        if (!sequence.empty()) {
          REXLOG_ERROR("  draw sequence:{}", sequence);
        }
        std::string rects;
        for (uint32_t i = 0; i < 256; ++i) {
          const RectDrawNote& note = rect_draw_ring_[(rect_draw_next_ + i) % 256];
          if (note.submission != faulted_submission) {
            continue;
          }
          rects += fmt::format(" @{}:ps={:08X} pso={} n={} fmt={}/{}", note.draw,
                               uint32_t(note.ps), note.pipeline,
                               note.index_count, note.color_format,
                               note.depth_format);
        }
        if (!rects.empty()) {
          REXLOG_ERROR("  rect draws:{}", rects);
        }
      }
      if (s_cb_errors > 32) {
        REXLOG_ERROR("Metal GPU FAULT: {} total this session", s_cb_errors);
      }
    }
    // AUTO-RECOVERY: error code 4 (access revoked) LATCHES — recreate the
    // queue (GPU thread; the provider/presenter aren't touched from the
    // completion-handler thread). Throttled against fault storms.
    if (command_buffer.error && command_buffer.error.code == 4) {
      static uint32_t s_last_recovery_swap = 0;
      if (swap_count_ - s_last_recovery_swap > 120 ||
          s_last_recovery_swap == 0) {
        s_last_recovery_swap = swap_count_;
        auto* provider = GetGraphicsDriver().GetProvider();
        if (provider && provider->RecreateQueue()) {
          if (auto* presenter = static_cast<rex::ui::metal::MetalPresenter*>(
                  GetGraphicsDriver().GetHostPresenter())) {
            presenter->SetCommandQueue(provider->command_queue());
          }
          // Epoch bump defines episode membership: everything that failed
          // before this recreate belongs to the episode now closing.
          // Close the episode for the epoch being retired, then advance.
          // Late callbacks carrying the OLD epoch still resolve correctly
          // because membership keys on the submission's own epoch.
          MarkFaultEpochClosed(fault_episodes_.epoch());
          fault_episodes_.BumpEpoch();
          REXLOG_ERROR(
              "Metal GPU FAULT: queue revoked -> RECREATED (swap#{}, "
              "epoch={}); display should resume",
              swap_count_, fault_episodes_.epoch());
        }
      }
    }
  }
}


bool MetalCommandProcessor::ArenaAllocate(uint32_t size, uint32_t alignment,
                                          MetalUploadAllocation* out) {
  if (!upload_arena_) {
    return false;
  }
  if (upload_arena_->Allocate(size, alignment, out)) {
    return true;
  }
  // Ring full. Reclaim first runs only at completion pumps, so through a long
  // run of draws the regions of submissions the GPU already finished still
  // count as live: reclaim them now (pure bookkeeping, safe mid-draw).
  upload_arena_->Reclaim(completed_submission_.load(std::memory_order_acquire));
  if (upload_arena_->Allocate(size, alignment, out)) {
    return true;
  }
  // Then wait for committed submissions, oldest first, until the space is
  // free. Before this, every caller skipped its draw on a full ring: GTA IV
  // dropped up to 900k draws a run once the GPU thread ran far enough ahead.
  // The open submission is never waited for (submission_counter_ is the last
  // committed one); if it alone fills the ring the draw still fails.
  while (completed_submission_.load(std::memory_order_acquire) <
         submission_counter_) {
    const uint64_t next =
        completed_submission_.load(std::memory_order_acquire) + 1;
    if (!SeamTimedDirectWait(metal::SeamDirectWait::kArenaReclaim, next)) {
      break;
    }
    upload_arena_->Reclaim(
        completed_submission_.load(std::memory_order_acquire));
    if (upload_arena_->Allocate(size, alignment, out)) {
      return true;
    }
  }
  return false;
}

void MetalCommandProcessor::PumpCompletedActions() {
  // GPU-thread only: completion_actions_ isn't synchronized; only the
  // published counter crosses threads.
  DrainFaultedCommandBuffers();
  uint64_t completed = completed_submission_.load(std::memory_order_acquire);
  while (!completion_actions_.empty() &&
         completion_actions_.front().first <= completed) {
    auto action = std::move(completion_actions_.front().second);
    completion_actions_.pop_front();
    action();
  }
  // Query slots are submission-gated the same way: a visibility counter is
  // only readable once the command buffer that wrote it has completed.
  PumpQueryResolves();
}

void MetalCommandProcessor::ClearCaches() {
  CommandProcessor::ClearCaches();
  // Latch only. The request arrives through GraphicsSystem::ClearCaches ->
  // CallInThread (F5 / GPU menu) or from a trace player rewinding to an
  // earlier command, so it can land mid-encoder with submissions in flight.
  // Releasing here would free resources the GPU is still reading. D3D12 makes
  // the same choice for the same reason.
  cache_clear_requested_ = true;
}

void MetalCommandProcessor::ExecuteDeferredCacheClear(bool publication_failed) {
  // No-request hot path: a single predictable branch. No commit, no wait, no
  // allocation for a title that never requests a clear.
  if (!cache_clear_requested_) {
    return;
  }
  // At most three passes -- quiesce, publish, execute. Each pass satisfies at
  // most one outstanding precondition; anything still unsatisfied leaves the
  // request LATCHED for the next boundary rather than dropping it or
  // releasing early.
  for (int pass = 0; pass < 3; ++pass) {
    metal::CacheClearAdmissionInputs in{};
    in.request_latched = cache_clear_requested_;
    in.encoder_open = frame_open_;
    in.has_unsubmitted_work = frame_command_buffer_ != nullptr;
    in.last_submitted_submission = submission_counter_;
    in.completed_submission =
        completed_submission_.load(std::memory_order_acquire);
    in.has_pending_producers =
        !pending_writebacks_.empty() || !pending_memexports_.empty();
    in.publication_failed = publication_failed;
    in.can_end_submission = true;
    in.can_publish_pending = true;
    switch (metal::DecideCacheClearAdmission(in)) {
      case metal::CacheClearAdmission::kEndSubmissionFirst:
        // Steps 1-3: end the encoder, commit, await every submission, and pump
        // completion actions so submission-gated retirement finishes before
        // anything is released. At the swap boundary the frame's own
        // EndFrameEncoderAndWait has already done this, so this is a no-op
        // there; it is what makes the routine safe from any other boundary.
        EndFrameEncoderAndWait(metal::SeamBoundaryReason::kCacheClear);
        // EndFrameEncoderAndWait waits only for a buffer it ended itself. An
        // async submission committed earlier (the swap's own frontbuffer
        // resolve) can still be running, and the admission check then asked
        // for this same step on every pass: Tiger Woods 14 and Silent Hill:
        // Homecoming kept the clear latched on nearly every swap.
        if (completed_submission_.load(std::memory_order_acquire) <
                submission_counter_ &&
            WaitForSubmission(submission_counter_, 4000, nullptr)) {
          PumpCompletedActions();
        }
        continue;
      case metal::CacheClearAdmission::kPublishPendingFirst: {
        // Step 4: completing a submission makes a drain POSSIBLE without
        // performing it. A queued memexport or render-target writeback is
        // guest-visible data that has not yet reached RAM -- authoritative
        // state under the cross-writer authority contract, not derived cache
        // content -- so it must land before anything is released. Same
        // full-domain publication the swap performs, through the same
        // chronological authority executor.
        metal::GuestRangeSet publication_domain;
        publication_domain.Add(metal::GuestRange::FromBaseLength(
            0, static_cast<uint32_t>(metal::GuestRange::kGuestPhysicalSize)));
        if (!ResolveRamConsumerDependencies(metal::ConsumerKind::kHostCpuRead,
                                            publication_domain)) {
          // Fail closed: keep the pending set intact and the request latched.
          publication_failed = true;
        }
        continue;
      }
      case metal::CacheClearAdmission::kExecute:
        // Step 5: every precondition holds -- encoder closed, every submission
        // complete, completion actions pumped, and all GPU-produced guest data
        // published to RAM. Only now may anything be released.
        if (!ReleaseCachesForClear()) {
          // A precondition failed and nothing was released, so the request is
          // NOT satisfied: leave it latched and do not count it.
          return;
        }
        // A GUEST logical report open across this clear (BEGIN seen, END not
        // yet) is the one ZPD state a clear could strand: the pool and its
        // in-flight resolves are retained, but the report must still retire
        // afterwards. Record only handles actually observed in that state --
        // never a merely in-flight resolve, which the boundary has already
        // drained -- so PumpQueryResolves can report the matching retirement.
        // Ordinary titles never populate this set.
        if (zpd_active_segment_.logical_active &&
            zpd_active_segment_.report_handle != kInvalidReportHandle) {
          zpd_handles_spanning_clear_.insert(zpd_active_segment_.report_handle);
          REXLOG_INFO("MetalZPD: report handle={} spans cache clear (swap #{})",
                 zpd_active_segment_.report_handle.index, swap_count_);
        }
        // Step 6: the request is satisfied. Consume the latch and publish the
        // completed clear (release, so the release work above is visible to
        // whichever thread reads the count).
        cache_clear_requested_ = false;
        {
          const uint32_t executed =
              cache_clears_executed_.fetch_add(1, std::memory_order_release) +
              1;
          if (executed <= 4 || (executed & 63) == 0) {
            REXLOG_INFO("MetalCommandProcessor: cache clear #{} executed at swap#{}",
                   executed, swap_count_);
          }
        }
        return;
      case metal::CacheClearAdmission::kDefer:
      case metal::CacheClearAdmission::kNoRequest:
        return;
    }
  }
  // Three passes ran out with the request still latched (a producer that the
  // publication pass leaves pending keeps asking for another publish).
  static uint32_t s_unsatisfied_logs = 0;
  if (s_unsatisfied_logs++ < 4 || (s_unsatisfied_logs & 255) == 0) {
    REXLOG_WARN("MetalCommandProcessor: cache clear still latched after 3 passes "
           "at swap#{} (writebacks {}, memexports {}, publication_failed {})",
           swap_count_, pending_writebacks_.size(), pending_memexports_.size(),
           publication_failed);
    const uint64_t completed =
        completed_submission_.load(std::memory_order_acquire);
    for (size_t i = 0; i < pending_writebacks_.size() && i < 4; ++i) {
      const PendingWriteback& wb = pending_writebacks_[i];
      REXLOG_WARN("  retained writeback {:08X}+{:X} {}x{} seq={} sub={} "
             "completed={} committed={} gpu_current={} lazy_armed={} "
             "staging={}",
             wb.guest_addr, wb.range_bytes(), wb.width, wb.height,
             wb.authority_sequence, wb.submission, completed,
             submission_counter_, wb.gpu_current ? 1 : 0,
             uint32_t(wb.lazy_armed), wb.staging ? 1 : 0);
    }
  }
}

bool MetalCommandProcessor::ReleaseCachesForClear() {
  // Step 5 of the deferred cache-clear ordering. Reached only through
  // ExecuteDeferredCacheClear's kExecute decision, which is what guarantees
  // the device is idle and every GPU-produced guest write has already reached
  // RAM. Every release below is therefore immediate rather than retired.
  //
  // DURABLE PIPELINE STORAGE IS DELIBERATELY NOT TOUCHED HERE (task 3.3f of
  // implement-metal-shader-pipeline-lifetime). The promoted cache-clearing
  // decision already retains pipelines and MSC-translated shaders by design and
  // records that shader/pipeline lifetime is not covered by it, so the on-disk
  // store follows the same rule as its in-memory counterparts. A clear releases
  // DERIVED state that can be rebuilt from guest memory; the durable store is
  // not derived from guest memory at all, and erasing it would turn a
  // cache-control request into a permanent cold start for that title — every
  // stall the census measured, paid again, with no guest-visible benefit.
  // Deleting it is a separate, separately gated behavior if it is ever wanted.
  //
  // ALL preconditions are checked FIRST, before a single object is released,
  // so a failure is reported with everything still intact rather than half way
  // through a partial release. Both of these describe submission-gated state
  // that step 3's completion pumping must already have drained at a boundary
  // where every submission has completed; a survivor of either would name
  // resources this function is about to free.
  uint32_t queued_actions = uint32_t(completion_actions_.size());
  uint32_t consumed_ranges =
      shared_memory_ ? shared_memory_->consumed_range_count() : 0;
  if (queued_actions || consumed_ranges) {
    REXLOG_ERROR(
        "MetalCommandProcessor: cache clear aborted -- {} completion action(s) "
        "and {} consumed range(s) still held at a quiesced boundary; "
        "submission-gated retirement did not drain",
        queued_actions, consumed_ranges);
    assert_always();
    return false;  // nothing released; the request stays latched.
  }

  // Resource-return evidence (task 4.5). Sampled only on the clear path, so a
  // title that never requests one pays nothing. Footprint is read through the
  // shared sampler both here and after the release, so the pair is measured
  // the same way -- see the log below for what it can and cannot show.
  struct ClearResourceSample {
    uint32_t textures = 0;
    uint32_t bridges = 0;
    uint32_t snapshots = 0;
    uint32_t slots_used = 0;
    uint32_t slots_free = 0;
    uint32_t slots_stale = 0;
    double footprint_mib = 0.0;
  };
  auto sample_resources = [this]() {
    ClearResourceSample s;
    if (texture_cache_) {
      s.textures = texture_cache_->cached_texture_count();
      s.bridges = texture_cache_->resolved_bridge_count();
      s.slots_used = texture_cache_->slots_used();
      s.slots_free = texture_cache_->slots_free();
      s.slots_stale = texture_cache_->slots_stale();
    }
    if (render_target_cache_) {
      s.snapshots = render_target_cache_->resolve_snapshot_count();
    }
    s.footprint_mib = ProcessFootprintMiB();
    return s;
  };
  const ClearResourceSample before = sample_resources();

  // The order is load-bearing, not cosmetic: every step that RETIRES into the
  // legacy cache's pools must run before the step that DRAINS them.

  // 1. The shared TextureCache subclass FIRST: it retires its binding slots
  //    and views into the LEGACY cache's pools.
  if (shared_texture_cache_) {
    shared_texture_cache_->ClearCache();
  }
  // 2. Classify the resolve-snapshot bridges and release the derived ones
  //    (current-generation RAM-backed color: the clear published their
  //    writebacks in step 4, so guest RAM holds THIS generation's content and
  //    their serve path already reads it).
  //    This also retires into the legacy pools, so it precedes the drain.
  //    Bridges that are !generation_ram_backed (this content generation was
  //    never written to guest RAM, so the snapshot is the only copy) or
  //    is_depth (served from the snapshot regardless of RAM) are retained.
  std::vector<std::pair<uint32_t, void*>> released_bridges;
  if (texture_cache_) {
    texture_cache_->ReleaseDerivedResolveBridges(&released_bridges);
  }
  // 3. Release exactly the snapshot textures those bridges named, plus the
  //    command-processor-owned tip textures and per-base resolve metadata for
  //    the same bases. Nothing else's snapshot is touched.
  uint32_t released_snapshots = 0;
  std::vector<uint32_t> released_snapshot_bases;
  if (render_target_cache_ && !released_bridges.empty()) {
    released_snapshots = render_target_cache_->ReleaseResolveSnapshotsForBases(
        released_bridges, &released_snapshot_bases);
  }
  // Per-base state is keyed off what was ACTUALLY released, never off what was
  // requested. A skipped identity mismatch means a newer snapshot generation
  // lives at that base, and its tip texture, RAM colour layout, snapshot
  // generation, and held writeback content belong to that generation -- they
  // must survive whole, exactly like the snapshot itself.
  for (uint32_t base : released_snapshot_bases) {
    auto tip_it = tip_view_textures_.find(base);
    if (tip_it != tip_view_textures_.end()) {
      if (tip_it->second) {
        id<MTLTexture> released =
            (__bridge_transfer id<MTLTexture>)tip_it->second;
        (void)released;
      }
      tip_view_textures_.erase(tip_it);
    }
    ram_color_layouts_.erase(base);
    resolve_snapshot_generation_.erase(base);
    held_writeback_content_.erase(base);
  }
  // 4. The legacy cache DRAIN: cached textures, their descriptors, the slot
  //    pools, and both retire lists -- including everything steps 1 and 2 just
  //    retired into them.
  if (texture_cache_) {
    texture_cache_->ClearCache();
  }
  // 5. Render targets: drops derived state keyed by render-target identity and
  //    drains deferred releases, then the shared clear keeps every target still
  //    owning EDRAM data. Canonical EDRAM is untouched.
  if (render_target_cache_) {
    render_target_cache_->ClearCache();
  }
  // 6. Shared memory. The consumed-range precondition was verified at the top,
  //    before anything was released; re-check here only to catch a release
  //    path above that somehow recorded a new hazard range.
  if (shared_memory_) {
    uint32_t consumed_now = shared_memory_->consumed_range_count();
    if (consumed_now) {
      REXLOG_ERROR(
          "MetalCommandProcessor: {} consumed range(s) appeared DURING the "
          "cache-clear release -- a release path is recording hazard state",
          consumed_now);
      assert_always();
    }
    shared_memory_->ClearCache();
  }
  // 7. Metal-owned transient pools with no shared equivalent. The arena reset
  //    is a hard ring reset -- documented as safe only when nothing is in
  //    flight, which is exactly what this boundary proves. It is unconditional:
  //    the S7 arena-reset bisect switch governs per-frame reclamation policy,
  //    not whether a cache clear releases the pool.
  if (upload_arena_) {
    upload_arena_->Reset();
  }
  for (auto& pair : dummy_depth_textures_) {
    if (pair.second) {
      id<MTLTexture> released = (__bridge_transfer id<MTLTexture>)pair.second;
      (void)released;
    }
  }
  dummy_depth_textures_.clear();

  // NOT released, and each for a stated reason:
  //   - pipeline_cache_ (pipeline states + MSC-translated shaders): the D3D12
  //     contract retains what live pipelines reference; destroying them would
  //     make this a translation-layer reset and risk post-clear draw skips.
  //   - sampler_states_/sampler_slot_cache_ and depth_stencil_states_:
  //     immutable state objects of the same class as pipelines.
  //   - the ZPD visibility pool, zpd_resolves_in_flight_, and the active
  //     segment: D3D12's clear does not touch its query pool either, and a
  //     logical report can span the request.
  //   - canonical EDRAM and EDRAM-owning render targets: authoritative guest
  //     state, retained by the shared clear's own rule.

  // Retire-list consistency: nothing may remain queued against a submission
  // whose resources were just released. Completion actions are pumped by step
  // 3 at a boundary where every submission has completed, so this must already
  // be empty -- verify rather than assume, since a survivor would run against
  // caches that no longer hold what it expects.
  // Re-check: nothing above may have enqueued new submission-gated work.
  if (!completion_actions_.empty()) {
    REXLOG_ERROR(
        "MetalCommandProcessor: cache clear ENQUEUED {} completion action(s) "
        "while releasing -- a release path is retiring against a submission "
        "that will never be revisited",
        uint32_t(completion_actions_.size()));
    assert_always();
  }
  // Every retained bridge must satisfy the documented retention invariant.
  if (texture_cache_ && !texture_cache_->retained_bridges_are_authoritative()) {
    REXLOG_ERROR(
        "MetalCommandProcessor: cache clear retained a current-generation "
        "RAM-backed color resolve bridge (generation_ram_backed) -- derived "
        "state was classified as authoritative");
    assert_always();
  }
  // One machine-parsable before->after line per executed clear. The ENUMERABLE
  // cache counters are the evidence that derived state was actually returned:
  // they are exact, owned by this backend, and bounded by construction.
  //
  // footprint_mib is reported for completeness and is deliberately NOT an
  // acceptance criterion. Releasing a Metal object returns it to the driver's
  // and the allocator's pools, which need not shrink the process's physical
  // footprint at that instant or ever; a flat or rising number here is not
  // evidence that a cache retained anything, and a falling one would not prove
  // it released everything. What the counters prove is cache-level return to
  // baseline; what footprint cannot prove is either direction of that claim.
  const ClearResourceSample after = sample_resources();
  REXLOG_INFO(
      "MetalCacheClearStats swap={} textures={}->{} "
      "bridges={}->{}(released={},retained={}) "
      "snapshots={}->{}(released={}) slots_used={}->{} slots_free={}->{} "
      "slots_stale={}->{} slots_capacity={} footprint_mib={:.2f}->{:.2f}",
      swap_count_, before.textures, after.textures, before.bridges,
      after.bridges, uint32_t(released_bridges.size()), after.bridges,
      before.snapshots, after.snapshots, released_snapshots, before.slots_used,
      after.slots_used, before.slots_free, after.slots_free,
      before.slots_stale, after.slots_stale,
      texture_cache_ ? texture_cache_->slots_capacity() : 0,
      before.footprint_mib, after.footprint_mib);
  return true;
}

void MetalCommandProcessor::ResetDerivedReplayState() {
  // Quiescent replay-boundary derived-state retirement
  // (fix-metal-trace-replay-state-reset tasks 2.1-2.3). Invoked ONLY from
  // TracePlayer's frame-initial playback entry -- immediately BEFORE the
  // trace's kMemoryRead / kEdramSnapshot commands re-deliver authoritative
  // guest RAM + EDRAM -- and from conformance harnesses via the same public
  // method. ALL-or-nothing with NO live retention rules: under replay
  // restoration the cache clear's "the snapshot is the only copy of
  // guest-visible content" retention is exactly inverted (restored RAM/EDRAM
  // is about to become the only authority), so every derived carrier dies:
  //   C1 resolve-snapshot textures        (render-target cache)
  //   C2 resolved-target bridge registry  (texture cache)
  //   C3 descriptor/view-heap slot state  (texture cache drain/rebind-null)
  //   C4 per-base resolve metadata        (this class -- incl. the
  //      held_writeback_content_ hold-last-value guard, a genuine cross-loop
  //      content carrier)
  //   C5 RT-pool texel lineage            (render-target cache, STRONGER than
  //      the shared ClearCache: ownership is re-seeded by the imminent
  //      restore)
  // plus the shared texture cache and shared memory for uniformity with the
  // deferred clear's release order. Canonical EDRAM, pipelines/shaders,
  // sampler/depth-stencil states, and the ZPD pool are retained for the same
  // stated reasons as ReleaseCachesForClear.

  // Live-path guard (task 2.2): replay/test context must have been declared
  // (TracePlayer does so on this thread before any playback command; a
  // harness must call SetTracePlaybackContext()). The live frame path never
  // does either, so a trip here is a wiring bug -- fail closed, retire
  // nothing, and leave live behavior untouched.
  if (true) {
    REXLOG_ERROR(
        "MetalCommandProcessor: ResetDerivedReplayState invoked OUTSIDE "
        "trace-playback/test context -- live-path invocation is forbidden; "
        "nothing was retired");
    assert_always();
    return;
  }

  // Defensive quiesce: a strict no-op at the sanctioned boundary (the
  // previous loop's swap already ended the frame encoder, awaited every
  // submission, and pumped completion actions; the first playback starts
  // from process-initial state with nothing open). Kept so the seam is safe
  // from any future call site at zero cost when already quiesced.
  EndFrameEncoderAndWait(metal::SeamBoundaryReason::kReplayReset);
  PumpCompletedActions();

  // Quiescence assert (task 2.1): the SAME inputs the deferred cache-clear
  // admission predicate decides on, but demanded to ALREADY hold --
  // can_end_submission/can_publish_pending are false because this seam cures
  // nothing: a violated invariant means the replay-boundary contract is
  // broken, and retiring would release resources in-flight work can touch.
  metal::CacheClearAdmissionInputs in{};
  in.request_latched = true;  // Value-form reuse: evaluate the preconditions.
  in.encoder_open = frame_open_;
  in.has_unsubmitted_work = frame_command_buffer_ != nullptr;
  in.last_submitted_submission = submission_counter_;
  in.completed_submission =
      completed_submission_.load(std::memory_order_acquire);
  in.has_pending_producers =
      !pending_writebacks_.empty() || !pending_memexports_.empty();
  in.publication_failed = false;
  in.can_end_submission = false;
  in.can_publish_pending = false;
  uint32_t queued_actions = uint32_t(completion_actions_.size());
  uint32_t consumed_ranges =
      shared_memory_ ? shared_memory_->consumed_range_count() : 0;
  if (metal::DecideCacheClearAdmission(in) !=
          metal::CacheClearAdmission::kExecute ||
      queued_actions || consumed_ranges) {
    REXLOG_ERROR(
        "MetalCommandProcessor: replay-reset boundary NOT quiescent "
        "(encoder_open={} unsubmitted_work={} submitted={} completed={} "
        "pending_producers={} completion_actions={} consumed_ranges={}) -- "
        "fail closed, NOTHING retired; this loop replays against stale "
        "derived state and any determinism gate on it must fail",
        in.encoder_open, in.has_unsubmitted_work,
        in.last_submitted_submission, in.completed_submission,
        in.has_pending_producers, queued_actions, consumed_ranges);
    assert_always();
    return;
  }

  const uint32_t bridges_before =
      texture_cache_ ? texture_cache_->resolved_bridge_count() : 0;
  const uint32_t textures_before =
      texture_cache_ ? texture_cache_->cached_texture_count() : 0;
  const uint32_t snapshots_before =
      render_target_cache_ ? render_target_cache_->resolve_snapshot_count()
                           : 0;

  // The order is the deferred clear's, for the same load-bearing reason:
  // every step that RETIRES into the legacy texture cache's pools must run
  // before the step that DRAINS them.
  // 1. Shared TextureCache subclass first (retires its binding slots/views
  //    into the legacy pools).
  if (shared_texture_cache_) {
    shared_texture_cache_->ClearCache();
  }
  // 2. C2: EVERY bridge registration -- no classification, no retention.
  if (texture_cache_) {
    texture_cache_->RetireAllResolvedTargets();
  }
  // 3. C1: EVERY resolve snapshot texture, color and depth alike.
  uint32_t snapshots_released =
      render_target_cache_ ? render_target_cache_->ReleaseAllResolveSnapshots()
                           : 0;
  // 4. C4: per-base resolve metadata for ALL bases (the clear erases only
  //    released bases; here every generation is about to be superseded by
  //    the restore). held_writeback_content_ is the one genuine content
  //    carrier -- loop N-1 words re-injected into loop N's writebacks.
  for (auto& tip_pair : tip_view_textures_) {
    if (tip_pair.second) {
      id<MTLTexture> released =
          (__bridge_transfer id<MTLTexture>)tip_pair.second;
      (void)released;
    }
  }
  tip_view_textures_.clear();
  ram_color_layouts_.clear();
  resolve_snapshot_generation_.clear();
  held_writeback_content_.clear();
  // 5. C3 drain: frees cached textures and everything steps 1-2 retired,
  //    returning every freed view-heap descriptor to the null texture.
  if (texture_cache_) {
    texture_cache_->ClearCache();
  }
  // 6. C5: the RT pool, stronger than the shared ClearCache -- all pool
  //    textures (incl. MSAA companions), presentable target, d2c lineage,
  //    deferred releases. Ownership is re-seeded by the imminent restore.
  if (render_target_cache_) {
    render_target_cache_->ResetForReplayRestore();
  }
  // 7. Shared memory + Metal-owned transients, mirroring the clear's tail.
  if (shared_memory_) {
    shared_memory_->ClearCache();
  }
  if (upload_arena_) {
    upload_arena_->Reset();
  }
  for (auto& pair : dummy_depth_textures_) {
    if (pair.second) {
      id<MTLTexture> released = (__bridge_transfer id<MTLTexture>)pair.second;
      (void)released;
    }
  }
  dummy_depth_textures_.clear();

  replay_resets_executed_.fetch_add(1, std::memory_order_release);
  REXLOG_INFO(
      "MetalReplayResetStats swap={} bridges_retired={} textures_released={} "
      "snapshots_released={}/{} resets_executed={}",
      swap_count_, bridges_before, textures_before, snapshots_released,
      snapshots_before,
      replay_resets_executed_.load(std::memory_order_relaxed));
}

void MetalCommandProcessor::EnsureZPDQueryResources() {
  if (GetZPDMode() == ZPDMode::kFake) {
    return;
  }
  auto* provider = static_cast<rex::ui::metal::MetalProvider*>(
      GetGraphicsDriver().GetProvider());
  if (!provider || !provider->device()) {
    return;
  }
  zpd_visibility_pool_.EnsureInitialized(provider->device(),
                                         kZPDQueryPoolCapacity);
}

void MetalCommandProcessor::ShutdownZPDQueryResources() {
  zpd_resolves_in_flight_.clear();
  zpd_handles_spanning_clear_.clear();
  zpd_query_open_ = false;
  encoder_has_zpd_visibility_ = false;
  zpd_visibility_pool_.Shutdown();
}

bool MetalCommandProcessor::IsZPDQueryPoolReady() const {
  return zpd_visibility_pool_.is_initialized();
}

bool MetalCommandProcessor::ZPDSegmentPending() const {
  return GetZPDMode() != ZPDMode::kFake && !zpd_force_fake_fallback_ &&
         zpd_active_segment_.logical_active &&
         zpd_active_segment_.segment_pending_begin;
}

bool MetalCommandProcessor::CanOpenZPDQuery() const {
  // Only "a render encoder exists". Deliberately NOT "and it carries the
  // visibility buffer": the shared OpenQuerySegment tests this BEFORE calling
  // EnsureZPDQueryResources, so requiring the buffer here would stop the pool
  // from ever being created, and would also skip the fake-fallback latch that
  // a failed pool creation is supposed to trigger. Whether this particular
  // encoder can carry a query is decided in OpenZPDQuery, which defers.
  return frame_open_ && frame_render_encoder_ != nullptr;
}

QueryOpenResult MetalCommandProcessor::OpenZPDQuery(
    ReportHandle report_handle, bool can_close_submission) {
  // Drain first, so the admission decision sees slots freed by already
  // completed submissions rather than declaring a false exhaustion.
  if (!zpd_visibility_pool_.has_free_indices()) {
    PumpQueryResolves();
  }

  ZPDMode mode = GetZPDMode();
  ZPDQueryAdmissionInputs admission;
  admission.pool_ready = zpd_visibility_pool_.is_initialized();
  admission.query_already_open = zpd_query_open_;
  admission.encoder_can_carry_query =
      CanOpenZPDQuery() && encoder_has_zpd_visibility_;
  admission.has_free_slot = zpd_visibility_pool_.has_free_indices();
  admission.fast_mode = mode == ZPDMode::kFast || mode == ZPDMode::kFastAlt;
  admission.has_pending_resolve = !zpd_resolves_in_flight_.empty();
  admission.oldest_pending_submission =
      admission.has_pending_resolve ? zpd_resolves_in_flight_.front().submission
                                    : 0;
  admission.current_encoding_submission = CurrentEncodingSubmission();
  admission.can_close_submission = can_close_submission;

  const ZPDQueryAdmission admission_decision =
      DecideZPDQueryAdmission(admission);
  static const bool s_zpd_trace = std::getenv("XE_METAL_ZPD_TRACE") != nullptr;
  if (s_zpd_trace) {
    REXLOG_INFO(
        "MetalZPDTrace open draw={} handle={} decision={} encoder_open={} "
        "encoder_has_vis={} free_slot={} already_open={}",
        trace_draw_index_, report_handle.index, uint32_t(admission_decision),
        frame_open_ && frame_render_encoder_ != nullptr,
        encoder_has_zpd_visibility_, admission.has_free_slot,
        zpd_query_open_);
  }
  switch (admission_decision) {
    case ZPDQueryAdmission::kAcquire:
      break;
    case ZPDQueryAdmission::kDefer:
      return QueryOpenResult::kDeferred;
    case ZPDQueryAdmission::kDeferAfterClosingSubmission:
      EndFrameEncoder(metal::SeamBoundaryReason::kQueryAdmission);
      return QueryOpenResult::kDeferred;
    case ZPDQueryAdmission::kPoolExhausted:
      return QueryOpenResult::kPoolExhausted;
    case ZPDQueryAdmission::kFailed:
      return QueryOpenResult::kFailed;
    case ZPDQueryAdmission::kWaitForOldestResolve:
      if (!SeamTimedDirectWait(metal::SeamDirectWait::kZpdAdmission,
                               admission.oldest_pending_submission)) {
        return QueryOpenResult::kFailed;
      }
      PumpQueryResolves();
      if (!zpd_visibility_pool_.has_free_indices()) {
        return QueryOpenResult::kPoolExhausted;
      }
      break;
  }

  uint32_t index = 0;
  uint32_t generation = 0;
  size_t offset = 0;
  if (!zpd_visibility_pool_.Acquire(index, generation, offset)) {
    return QueryOpenResult::kFailed;
  }
  // Through the stream: the draws before it may still be recording.
  encode_stream_->SetVisibilityResultMode(MTLVisibilityResultModeCounting,
                                          offset);
  zpd_active_index_ = index;
  zpd_active_generation_ = generation;
  zpd_query_open_ = true;
  return QueryOpenResult::kOpened;
}

bool MetalCommandProcessor::RetireActiveZPDQuery(ReportHandle report_handle,
                                                 uint64_t* out_submission) {
  static const bool s_zpd_trace = std::getenv("XE_METAL_ZPD_TRACE") != nullptr;
  if (s_zpd_trace) {
    REXLOG_INFO("MetalZPDTrace retire draw={} handle={} query_open={} frame_open={} "
           "encoder_has_vis={} slot={}",
           trace_draw_index_, report_handle.index, zpd_query_open_, frame_open_,
           encoder_has_zpd_visibility_, zpd_active_index_);
  }
  if (!zpd_query_open_) {
    return false;
  }
  // If the encoder already ended, counting stopped with it and there is
  // nothing to disable -- but the slot still has a pending GPU write, so it
  // must be queued either way.
  if (frame_open_ && frame_render_encoder_ && encoder_has_zpd_visibility_) {
    encode_stream_->SetVisibilityResultMode(MTLVisibilityResultModeDisabled, 0);
  }

  MetalZPDResolve resolve;
  // The command buffer being encoded now is the one that will write this slot.
  resolve.submission = CurrentEncodingSubmission();
  resolve.index = zpd_active_index_;
  resolve.generation = zpd_active_generation_;
  resolve.report_handle = report_handle;
  zpd_resolves_in_flight_.push_back(resolve);
  if (out_submission) {
    *out_submission = resolve.submission;
  }
  zpd_query_open_ = false;
  return true;
}

bool MetalCommandProcessor::CloseZPDQuery(ReportHandle report_handle,
                                          uint64_t& out_submission) {
  return RetireActiveZPDQuery(report_handle, &out_submission);
}

bool MetalCommandProcessor::DiscardZPDQuery() {
  // kInvalidReportHandle: the slot is reclaimed on completion but its count is
  // attributed to nothing.
  return RetireActiveZPDQuery(kInvalidReportHandle, nullptr);
}

void MetalCommandProcessor::PumpQueryResolves() {
  if (!zpd_visibility_pool_.is_initialized()) {
    return;
  }
  uint64_t completed = completed_submission_.load(std::memory_order_acquire);
  while (!zpd_resolves_in_flight_.empty() &&
         zpd_resolves_in_flight_.front().submission <= completed) {
    MetalZPDResolve resolve = zpd_resolves_in_flight_.front();
    zpd_resolves_in_flight_.pop_front();
    if (!zpd_visibility_pool_.IsGenerationCurrent(resolve.index,
                                                  resolve.generation)) {
      // The slot was recycled out from under this resolve; attributing it now
      // would corrupt whichever report owns the slot.
      continue;
    }
    // A faulted submission still publishes as completed while its GPU work
    // never ran. The slot was zeroed at acquire, so such a report reads 0
    // rather than stale content.
    uint64_t raw_samples = zpd_visibility_pool_.Read(resolve.index);
    zpd_visibility_pool_.Release(resolve.index, resolve.generation);
    if (resolve.report_handle != kInvalidReportHandle) {
      REXLOG_DEBUG("MetalZPD: resolved handle={} slot={} submission={} samples={}",
             resolve.report_handle.index, resolve.index, resolve.submission,
             raw_samples);
      OnZPDQueryResolved(resolve.report_handle, raw_samples);
      // Cache-clear span observability. The set is empty for every title that
      // never spans a clear, so an ordinary resolve pays one branch.
      if (!zpd_handles_spanning_clear_.empty()) {
        auto spanning = zpd_handles_spanning_clear_.find(resolve.report_handle);
        if (spanning != zpd_handles_spanning_clear_.end() &&
            logical_zpd_reports_.find(resolve.report_handle) ==
                logical_zpd_reports_.end()) {
          // The report that was live across a clear has now completed the
          // shared retirement path (accumulated, committed, and erased) rather
          // than being stranded by the release.
          REXLOG_INFO("MetalZPD: clear-spanning report handle={} retired",
                 resolve.report_handle.index);
          zpd_handles_spanning_clear_.erase(spanning);
        }
      }
    }
  }
}

bool MetalCommandProcessor::AwaitQueryResolve(ReportHandle report_handle,
                                              uint64_t wait_for_submission) {
  if (GetZPDMode() == ZPDMode::kFake) {
    return false;
  }
  PumpQueryResolves();

  auto report = logical_zpd_reports_.find(report_handle);
  if (report == logical_zpd_reports_.end()) {
    return true;
  }
  if (report->second.pending_segments == 0 && report->second.ended) {
    return true;
  }
  if (!wait_for_submission) {
    return false;
  }

  if (wait_for_submission >= CurrentEncodingSubmission()) {
    if (!frame_command_buffer_) {
      return false;
    }
    // The segment is in the command buffer still open; commit it so it can
    // complete. Strict mode's stall backstops bound how often this happens.
    EndFrameEncoder(metal::SeamBoundaryReason::kQueryAwait);
  }
  if (wait_for_submission >
          completed_submission_.load(std::memory_order_acquire) &&
      !SeamTimedDirectWait(metal::SeamDirectWait::kQueryResolve,
                           wait_for_submission)) {
    return false;
  }
  PumpQueryResolves();

  report = logical_zpd_reports_.find(report_handle);
  return report == logical_zpd_reports_.end() ||
         (report->second.pending_segments == 0 && report->second.ended);
}

// XE_METAL_RESOLVE_CONSUMER_CENSUS=1 (diagnostic, default off): for each
// resolve, the draw distance to the first texture fetch overlapping its
// destination and how many render passes ended in between (the resolve's own
// pass end makes 1 = the consumer sits in the pass resumed after the resolve,
// the case an in-pass resolve could keep open). Resolves never fetched before
// the swap count as unconsumed. Reported with MetalFrameStats.
namespace {
struct ResolveConsumerCensus {
  struct Entry {
    metal::GuestRange range;
    uint64_t draw;
    uint64_t pass_ends;
    uint32_t cls;  // bit 0 depth, bit 1 >= 1 MB
  };
  std::vector<Entry> live;
  uint64_t pass_ends = 0;
  uint64_t resolves[4] = {};
  uint64_t unconsumed[4] = {};
  // Draw distance buckets: 0, 1, 2-9, 10-99, 100-999, 1000+.
  uint64_t distance[4][6] = {};
  // Pass ends in between: 0, 1, 2, 3+.
  uint64_t passes[4][4] = {};
};
ResolveConsumerCensus& RcCensus() {
  static ResolveConsumerCensus census;
  return census;
}
bool RcCensusEnabled() {
  static const bool enabled =
      std::getenv("XE_METAL_RESOLVE_CONSUMER_CENSUS") != nullptr;
  return enabled;
}
void RcCensusNoteResolve(uint32_t start, uint32_t length, uint64_t draw,
                         bool depth) {
  auto range = metal::GuestRange::FromBaseLength(start, length);
  if (!range) {
    return;
  }
  ResolveConsumerCensus& c = RcCensus();
  uint32_t cls = (depth ? 1u : 0u) | (length >= 1024 * 1024 ? 2u : 0u);
  ++c.resolves[cls];
  c.live.push_back({*range, draw, c.pass_ends, cls});
}
void RcCensusNoteTextureRequest(const metal::GuestRangeSet& ranges,
                                uint64_t draw) {
  ResolveConsumerCensus& c = RcCensus();
  if (c.live.empty() || ranges.empty()) {
    return;
  }
  for (size_t i = 0; i < c.live.size();) {
    const ResolveConsumerCensus::Entry& e = c.live[i];
    if (!ranges.OverlapsAny(e.range)) {
      ++i;
      continue;
    }
    uint64_t d = draw - e.draw;
    uint32_t db = d == 0 ? 0 : d == 1 ? 1 : d < 10 ? 2 : d < 100 ? 3
                  : d < 1000 ? 4 : 5;
    ++c.distance[e.cls][db];
    ++c.passes[e.cls][std::min<uint64_t>(c.pass_ends - e.pass_ends, 3)];
    c.live[i] = c.live.back();
    c.live.pop_back();
  }
}
void RcCensusNoteSwap(uint32_t swap) {
  ResolveConsumerCensus& c = RcCensus();
  for (const ResolveConsumerCensus::Entry& e : c.live) {
    ++c.unconsumed[e.cls];
  }
  c.live.clear();
  if ((swap & 127) || !swap) {
    return;
  }
  static const char* const kNames[4] = {"color<1MB", "depth<1MB", "color>=1MB",
                                        "depth>=1MB"};
  for (uint32_t k = 0; k < 4; ++k) {
    if (!c.resolves[k]) {
      continue;
    }
    REXLOG_INFO(
        "MetalResolveConsumers swap#{} {}: {:.1f}/frame unconsumed {:.1f} "
        "dist[0,1,2-9,10-99,100-999,1000+]={},{},{},{},{},{} "
        "pass_ends[0,1,2,3+]={},{},{},{}",
        swap, kNames[k], double(c.resolves[k]) / 128.0,
        double(c.unconsumed[k]) / 128.0, c.distance[k][0], c.distance[k][1],
        c.distance[k][2], c.distance[k][3], c.distance[k][4],
        c.distance[k][5], c.passes[k][0], c.passes[k][1], c.passes[k][2],
        c.passes[k][3]);
  }
  ResolveConsumerCensus fresh;
  std::swap(fresh.live, c.live);
  fresh.pass_ends = c.pass_ends;
  c = fresh;
}
}  // namespace

void MetalCommandProcessor::EndRenderEncoder(metal::MetalPassEndReason reason,
                                             uint32_t detail,
                                             bool resolve_touches_pass) {
  if (!frame_open_) {
    // Whoever ends a pass is about to use the frame command buffer.
    DrainUndrainedPassEnd();
    return;
  }
  if (PassCensusEnabled()) {
    pass_census_.EndPass(reason, detail, resolve_touches_pass);
  }
  // The encoder is a query-segment boundary (Metal's analogue of a Vulkan
  // render pass): close the active segment while setVisibilityResultMode can
  // still be issued. The logical report survives and reopens on the next
  // visibility-carrying encoder.
  if (zpd_query_open_) {
    CloseQuerySegment();
  }
  if (RcCensusEnabled()) {
    ++RcCensus().pass_ends;
  }
  if (frame_encoder_deferred_) {
    encode_stream_->EndRenderPass();
    frame_render_encoder_ = nullptr;
    frame_encoder_deferred_ = false;
    frame_open_ = false;
    encoder_has_zpd_visibility_ = false;
    // BeginFrameEncoder ending the pass for the next one: that pass's begin
    // is recorded behind this end, so no wait (its guard drains if it is not).
    // Every other end hands the command buffer to the command processor.
    if (ending_for_next_pass_) {
      encode_stream_->Commit();
      pass_end_undrained_ = true;
    } else {
      encode_stream_->Drain();
    }
    return;
  }
  if (encode_stream_) {
    // Every recorded op of this encoder is replayed before it ends.
    encode_stream_->SetEncoder(nil);
    encode_stream_->Drain();
  }
  id<MTLRenderCommandEncoder> encoder =
      (__bridge_transfer id<MTLRenderCommandEncoder>)frame_render_encoder_;
  if (PassTimingEnabled()) {
    PassTimingEndPass(draw_count_);
  }
  frame_render_encoder_ = nullptr;
  frame_open_ = false;
  encoder_has_zpd_visibility_ = false;
  [encoder endEncoding];
}

bool MetalCommandProcessor::DeferredPassLifecycle() const {
  // Render pass begin/end on the encoder thread: discrete AMD only by default.
  // Needs the encoder thread, and no per-encoder residency sweep (it runs on
  // the encoder object at creation). Apple GPUs (residency set) keep pass
  // begin/end on the command processor: there it measured no gain (M1 Max
  // Mafia II 81.4 vs 81.3) and Judgment's command buffers failed with
  // IOGPUCommandQueueErrorDomain 256 "Internal Error" every run on the M1 Max
  // (35-55 faults a route, ~20% of draws lost), 0 with it off.
  // XE_METAL_ENCODE_PASSES=0 keeps it off everywhere, =1 also enables it on
  // Apple GPUs.
  static const int s_mode = [] {
    const char* v = std::getenv("XE_METAL_ENCODE_PASSES");
    if (v && !v[1] && (v[0] == '0' || v[0] == '1')) {
      return v[0] - '0';
    }
    return -1;
  }();
  if (!s_mode || !encode_stream_ || !encode_stream_->deferred()) {
    return false;
  }
  if (residency_set_) {
    return s_mode == 1;
  }
  auto* provider =
      static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider());
  return provider && !ResidentSweepEnabled(
                         (__bridge id<MTLDevice>)provider->device());
}

void MetalCommandProcessor::DrainUndrainedPassEnd() {
  if (!pass_end_undrained_) {
    return;
  }
  pass_end_undrained_ = false;
  encode_stream_->Drain();
}

bool MetalCommandProcessor::SeamTimingEnabled() {
  // Exact-1 opt-in, warn-once fail-closed, per the house flag contract. An
  // enabled run is an ATTRIBUTION condition (clock reads per boundary), never
  // comparable to the pinned performance baselines.
  static const bool s_enabled = [] {
    const char* value = std::getenv("XE_METAL_SEAM_TIMING");
    if (!value || !value[0]) {
      return false;
    }
    if (value[0] == '1' && !value[1]) {
      return true;
    }
    if (!(value[0] == '0' && !value[1])) {
      REXLOG_WARN(
          "XE_METAL_SEAM_TIMING='{}' is malformed; failing closed to off "
          "(use 0 or 1)",
          value);
    }
    return false;
  }();
  return s_enabled;
}

namespace {
// Monotonic clock for seam timing. Production-only; the accumulator itself is
// clock-free so the device-free tests feed synthetic deltas instead.
inline uint64_t SeamNowNs() {
  return uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(
                      std::chrono::steady_clock::now().time_since_epoch())
                      .count());
}
}  // namespace

bool MetalCommandProcessor::SeamTimedDirectWait(metal::SeamDirectWait site,
                                                uint64_t submission) {
  ScopedPacingWaitSite pacing_site(kPacingSeamDirect);
  if (!SeamTimingEnabled()) {
    return WaitForSubmission(submission);
  }
  auto& d = seam_timing_.direct[uint32_t(site)];
  ++d.calls;
  const uint64_t t0 = SeamNowNs();
  bool did_block = false;
  bool ok = WaitForSubmission(submission, 4000, &did_block);
  d.wait.Record(SeamNowNs() - t0);
  if (did_block) {
    ++d.blocked;
  }
  if (!ok) {
    ++d.timeouts;
  }
  return ok;
}

void MetalCommandProcessor::EmitSeamTimingReport(const char* site) {
  if (!SeamTimingEnabled() || !seam_timing_.AnyActivity()) {
    return;
  }
  char reasons_buf[1536];
  char consumers_buf[2048];
  char direct_buf[512];
  seam_timing_.FormatReasons(reasons_buf, sizeof(reasons_buf));
  seam_timing_.FormatConsumers(consumers_buf, sizeof(consumers_buf));
  seam_timing_.FormatDirect(direct_buf, sizeof(direct_buf));
  REXLOG_INFO("MetalSeamTiming[{}]: reasons{} | consumers{} | direct{}", site,
         reasons_buf, consumers_buf, direct_buf);
  seam_timing_.Reset();
}

void MetalCommandProcessor::EmitNeedBasedWaitReport(const char* site) {
  const bool enabled = NeedBasedWaitsEnabled();
  // Printed even when nothing reached the corridor: "requests=0" is the honest
  // denominator of a run that never needed a consumer boundary (route-all JC2
  // serves every texture consumer GPU-ordered), and gate arms read this line as
  // the flag banner that proves which wait mode ran.
  char buf[512];
  need_wait_meter_.Format(buf, sizeof(buf), enabled);
  // The meter is NOT reset here. Seam timing resets per emission because it
  // reports rates within a window; this reports the session's engagement, which
  // a gate arm reads once from the final line -- resetting would make the last
  // line describe only the tail of the run.
  REXLOG_INFO("MetalNeedBasedWaits[{}]: {}{}", site, buf,
         enabled && !need_wait_meter_.Engaged()
             ? " ENGAGEMENT=NONE (an enabled arm that never published "
               "immediately and never took a narrow wait is invalid, not data)"
             : "");
}

void MetalCommandProcessor::EmitLifecycleReports(const char* site) {
  EmitSeamTimingReport(site);
  EmitNeedBasedWaitReport(site);
  if (PassCensusEnabled()) {
    REXLOG_INFO("{}", pass_census_.Format(site, /*window=*/false));
  }
}

void MetalCommandProcessor::EndFrameEncoder(metal::SeamBoundaryReason reason) {
  const bool seam_on = SeamTimingEnabled();
  // Clock starts at ENTRY so `close` includes EndRenderEncoder -- "encoder
  // close through commit" measured as claimed. A noop (no buffer) is counted
  // but never timed; the entry read is the only cost it pays.
  const uint64_t seam_t0 = seam_on ? SeamNowNs() : 0;
  EndRenderEncoder(metal::MetalPassEndReason::kSubmission, uint32_t(reason));
  if (!frame_command_buffer_) {
    if (seam_on) {
      // Free call: no buffer to close. Counted apart so boundary frequency is
      // never inflated by no-ops.
      ++seam_timing_.reason[uint32_t(reason)].noop_calls;
    }
    return;
  }
  uint64_t seam_close_ns = 0;   // entry through [command_buffer commit]
  uint64_t seam_wait_ns = 0;    // the actual GPU stall (see header)
  id<MTLCommandBuffer> command_buffer =
      (__bridge_transfer id<MTLCommandBuffer>)frame_command_buffer_;
  frame_command_buffer_ = nullptr;
  ++frame_commit_count_;
  draws_since_commit_ = 0;
  // S7/S8: assign this commit its submission id; the completion handler
  // publishes it and records faults (drained + logged + auto-recovered on
  // the GPU thread from PumpCompletedActions — a fault otherwise fails the
  // command buffer SILENTLY and reads on-screen as a freeze).
  uint64_t submission = ++submission_counter_;
  submission_reason_ring_[submission % 64] = uint8_t(reason);
  ++commit_reason_counts_[size_t(reason)];
  signal_since_commit_.store(0, std::memory_order_release);
  // Epoch AT SUBMISSION: a late callback must still join its original episode.
  //
  // CONCURRENCY INVARIANT (GPU THREAD ONLY): reading the epoch and reserving
  // its outstanding slot must not interleave with BumpEpoch()/the finalize
  // sweep, or a recreate could observe zero outstanding and finalize an epoch
  // between our read and our increment -- publishing a root that this
  // submission could still revise. Both sides are serialized by running on the
  // GPU thread: this path, and PumpCompletedActions ->
  // DrainFaultedCommandBuffers (documented GPU-thread-only) which owns every
  // epoch mutation and every finalize. The ONLY cross-thread participant is the
  // completion handler's DECREMENT, which is why the counter is atomic. If
  // submission ever moves off the GPU thread, this pair needs real
  // synchronization shared with the epoch mutations.
  AssertFaultEpochOwnership();
  const uint64_t submit_epoch = fault_episodes_.epoch();
  epoch_outstanding_[submit_epoch % kFaultEpochSlots].fetch_add(
      1, std::memory_order_release);
  // The reservation is released by the completion handler below. This guard
  // releases it if we return before that handler is attached -- today there is
  // no such path, but a future early-out would otherwise leak the reservation
  // and the epoch could NEVER finalize.
  struct ReservationGuard {
    std::atomic<uint32_t>* counter;
    ~ReservationGuard() {
      if (counter) {
        counter->fetch_sub(1, std::memory_order_release);
      }
    }
  } reservation{&epoch_outstanding_[submit_epoch % kFaultEpochSlots]};
  const std::pair<uint64_t, uint64_t> pass_timing_range =
      PassTimingEnabled() ? PassTimingTakeCommitRange()
                          : std::pair<uint64_t, uint64_t>{0, 0};
  [command_buffer addCompletedHandler:^(id<MTLCommandBuffer> cb) {
    if (GpuBusyTimingEnabled()) {
      NoteGpuBusyInterval(cb.GPUStartTime, cb.GPUEndTime);
    }
    if (PassTimingEnabled()) {
      PassTimingResolve(pass_timing_range);
    }
    if (cb.status == MTLCommandBufferStatusError) {
      std::lock_guard<std::mutex> lock(fault_mutex_);
      faulted_completions_.push_back(
          FaultedCompletion{(__bridge_retained void*)cb, submission,
                            submit_epoch});
    }
    // Ordered: this epoch stops being outstanding BEFORE the submission is
    // published, so a finalize sweep can never observe published-but-still-
    // outstanding and emit a provisional root.
    epoch_outstanding_[submit_epoch % kFaultEpochSlots].fetch_sub(
        1, std::memory_order_release);
    PublishCompletedSubmission(submission);
  }];
  // Ownership of the reservation has transferred to the handler.
  reservation.counter = nullptr;
  // Stamp the upload ring: everything allocated since the previous mark is
  // owned by this submission until it completes.
  if (upload_arena_) {
    upload_arena_->MarkSubmission(submission);
  }
  // Discrete mirror: GPU-produced ranges back to the CPU mirror, last in
  // this submission (every producer encoder has ended).
  EncodeDiscreteMirrorReadback((__bridge void*)command_buffer, submission);
  // Side loads first: the queue runs command buffers in commit order, and
  // the frame's draws read what they loaded.
  CommitSideCommandBuffer(submission, submit_epoch);
  [command_buffer commit];
  if (lazy_rearm_needed_.exchange(false, std::memory_order_acq_rel)) {
    
  }
  if (seam_on) {
    // `close` ends HERE, at the commit: entry -> commit, nothing after.
    seam_close_ns = SeamNowNs() - seam_t0;
  }
  // Zero-copy cost evidence, counted AT the commit: this is the submission
  // cadence, not an inference from frames or swaps.
  zero_copy_cost_.Count(metal::ZeroCopyCostCounter::kSubmissionCommits);
  // S8: NO synchronous wait — the GPU pipelines behind CPU encoding.
  // PROMOTED default (async). XE_METAL_SYNC_WAIT restores the commit+wait on
  // the ring/tags lifetime (arm-B diagnostic); XE_METAL_ASYNC=0 restores the
  // full pre-promotion sync semantics via AsyncSubmissionEnabled().
  static const bool s_sync_wait =
      std::getenv("XE_METAL_SYNC_WAIT") != nullptr ||
      !AsyncSubmissionEnabled();
  // Bisect lever: XE_METAL_SYNC_WAIT_REASONS=<hex mask of SeamBoundaryReason>
  // waits for completion only after commits for those reasons.
  static const uint32_t s_sync_wait_reasons = [] {
    const char* v = std::getenv("XE_METAL_SYNC_WAIT_REASONS");
    return v ? uint32_t(strtoul(v, nullptr, 16)) : 0u;
  }();
  if (s_sync_wait || (s_sync_wait_reasons >> uint32_t(reason)) & 1u) {
    // Counted on the branch that actually stalls, not from the mode flag: a
    // commit that returns and a commit that waits for the GPU are different
    // costs, and only the taken branch is evidence of which one happened.
    zero_copy_cost_.Count(metal::ZeroCopyCostCounter::kSyncCommitWaits);
    // Seam timing: THIS is the principal GPU wait on the default path. It is
    // recorded as its own stage precisely so it cannot be mislabeled as
    // "encoder close" wrapper time (and so the AndWait wrapper's pre-satisfied
    // WaitForSubmission cannot masquerade as the stall being free).
    const uint64_t seam_w0 = seam_on ? SeamNowNs() : 0;
    [command_buffer waitUntilCompleted];
    if (seam_on) {
      seam_wait_ns = SeamNowNs() - seam_w0;
    }
    PublishCompletedSubmission(submission);
  } else {
    // Bound the pipeline depth: cap in-flight submissions so a fast CPU
    // can't queue unbounded GPU work (memory + latency + ring pressure).
    // XE_METAL_MAX_IN_FLIGHT=<n>: the depth cap (default 16; 8 was the
    // default before 2026-10-06). Red Dead gameplay commits ~25 command
    // buffers per frame, so a cap of 8 held the command processor a third of
    // a frame ahead of the GPU and stalled it ~1.5 ms/frame in
    // WaitForSubmission while the GPU still had slack: 8 -> 16 measured
    // 24.2 -> 26.7 fps (32: 26.8, +100 MB footprint). USF4 2026-10-04 also
    // showed 10 ms/frame of depth-cap wait at a cap of 8.
    // metal_max_in_flight (cvar) sets the cap when the environment does
    // not; 0 keeps the default. metal_serialize_submissions (user switch,
    // default off) forces 1: with more than one submission in flight Rise of
    // the Tomb Raider's transient ring (CPU scratch interleaved with
    // memexport and resolve destinations, reused as soon as the guest's
    // fence says the GPU is done) produces a whole-frame colour-grading
    // flash in ~8% of gameplay seconds (xenia-mac-evidence
    // tombraider-stretch-20261025 knob census: every serializing arm 0,
    // every non-serializing arm unchanged; ~1/580 s after the 2026-10-27
    // write-commit fixes). The title no longer pins it (M1 Max 30 -> 21
    // fps); remove the switch once the root cause is fixed.
    static const uint64_t kMaxInFlightSubmissions = [] {
      const char* v = std::getenv("XE_METAL_MAX_IN_FLIGHT");
      uint64_t n = v ? strtoull(v, nullptr, 10) : 0;
      if (!n && ::rex::graphics::metal::GetMetalSettings().metal_serialize_submissions.Get()) {
        n = 1;
      }
      if (!n) {
        n = ::rex::graphics::metal::GetMetalSettings().metal_max_in_flight.Get();
      }
      return n ? n : uint64_t(16);
    }();
    if (submission > kMaxInFlightSubmissions) {
      // Under XE_METAL_ASYNC the depth-cap wait is this boundary's only
      // GPU-side stall; it lands in the same gpu_wait stage, disclosed by the
      // run's environment.
      const uint64_t seam_w0 = seam_on ? SeamNowNs() : 0;
      {
        ScopedPacingWaitSite pacing_site(kPacingInFlightCap);
        WaitForSubmission(submission - kMaxInFlightSubmissions);
      }
      if (seam_on) {
        seam_wait_ns = SeamNowNs() - seam_w0;
      }
    }
  }
  // Reclamation runs once THIS submission has completed: snapshot textures
  // retired mid-frame are then no longer referenced by any in-flight draw,
  // bindless slots can recycle, the upload-ring region frees, and later
  // uploads may rewrite any shared-memory range the submission consumed.
  completion_actions_.emplace_back(submission, [this, submission]() {
    if (upload_arena_) {
      upload_arena_->Reclaim(submission);
    }
    if (render_target_cache_) {
      render_target_cache_->DrainDeferredReleases(submission);
    }
    if (shared_texture_cache_) {
      // LRU destruction gated on completed submissions; retired slots/views
      // land in texture_cache_'s pools reclaimed below/next cycle.
      shared_texture_cache_->CompletedSubmissionUpdated(submission);
    }
    if (texture_cache_) {
      texture_cache_->ReclaimStaleSlots(submission);
    }
    if (shared_memory_) {
      shared_memory_->ReleaseConsumedRanges(submission);
    }
  });
  PumpCompletedActions();
  if (seam_on) {
    // Post-completion work (completion-action bookkeeping + pump) is its own
    // named stage -- neither hidden inside `close` nor inside the wait.
    const uint64_t seam_retire_ns =
        (SeamNowNs() - seam_t0) - seam_close_ns - seam_wait_ns;
    auto& r = seam_timing_.reason[uint32_t(reason)];
    ++r.boundaries;
    r.close.Record(seam_close_ns);
    r.gpu_wait.Record(seam_wait_ns);
    r.retire.Record(seam_retire_ns);
  }
}

void MetalCommandProcessor::EndFrameEncoderAndWait(
    metal::SeamBoundaryReason reason) {
  // For sites that read GPU results on the CPU right after the commit
  // (writeback drains, guest fence waits, EDRAM/RT readbacks, shutdown):
  // full synchronous semantics.
  const bool seam_on = SeamTimingEnabled();
  bool had_buffer = frame_command_buffer_ != nullptr;
  EndFrameEncoder(reason);
  if (had_buffer) {
    // Normally pre-satisfied on the default path (the sync commit already
    // waited and published); recorded separately so a genuinely blocking
    // post-wait is visible and a satisfied one reads as ~0, not as "free
    // stall". Blocked-ness comes from WaitForSubmission's LOCKED re-check
    // (out_did_block), the only exact fact -- never from an unlocked
    // pre-check that races with completion.
    const uint64_t seam_w0 = seam_on ? SeamNowNs() : 0;
    bool did_block = false;
    ScopedPacingWaitSite pacing_site(kPacingSyncWait);
    if (WaitForSubmission(submission_counter_, 4000,
                          seam_on ? &did_block : nullptr)) {
      PumpCompletedActions();
    }
    if (seam_on) {
      auto& r = seam_timing_.reason[uint32_t(reason)];
      r.post_wait.Record(SeamNowNs() - seam_w0);
      if (did_block) {
        ++r.post_wait_blocked;
      }
    }
  }
}

::rex::gpu::Shader* MetalCommandProcessor::LoadShader(xenos::ShaderType shader_type,
                                          uint32_t guest_address,
                                          const uint32_t* host_address,
                                          uint32_t dword_count) {
  if (!pipeline_cache_) {
    return nullptr;
  }
  return pipeline_cache_->LoadShader(shader_type, host_address, dword_count);
}

// Bring-up diagnostic toggle: replace the guest pixel shader with a solid color
// so we can tell whether the vertex side (positions/constants) is producing
// visible geometry independent of the guest pixel shader / textures.
static constexpr bool kDebugSolidFragment = false;

// Returns a cached id<MTLRenderPipelineState> pairing the given guest vertex
// function with a hardcoded solid-color fragment function.
static void* GetDebugSolidPipeline(
    void* device_ptr, void* vs_function, void*& debug_solid_fragment,
    std::unordered_map<void*, void*>& cache) {
  auto it = cache.find(vs_function);
  if (it != cache.end()) {
    return it->second;
  }
  id<MTLDevice> device = (__bridge id<MTLDevice>)device_ptr;
  if (!debug_solid_fragment) {
    NSString* src = @R"METAL(
      #include <metal_stdlib>
      using namespace metal;
      fragment float4 solid_fs(constant float4& c [[buffer(8)]]) { return c; }
    )METAL";
    NSError* err = nil;
    id<MTLLibrary> lib = [device newLibraryWithSource:src options:nil error:&err];
    id<MTLFunction> fs = lib ? [lib newFunctionWithName:@"solid_fs"] : nil;
    if (!fs) {
      cache.emplace(vs_function, nullptr);
      return nullptr;
    }
    debug_solid_fragment = (__bridge_retained void*)fs;
  }
  MTLRenderPipelineDescriptor* d = [[MTLRenderPipelineDescriptor alloc] init];
  d.vertexFunction = (__bridge id<MTLFunction>)vs_function;
  d.fragmentFunction = (__bridge id<MTLFunction>)debug_solid_fragment;
  d.colorAttachments[0].pixelFormat =
      (MTLPixelFormat)MetalRenderTargetCache::kColorFormat;
  NSError* err = nil;
  id<MTLRenderPipelineState> ps =
      [device newRenderPipelineStateWithDescriptor:d error:&err];
  void* ps_ptr = ps ? (__bridge_retained void*)ps : nullptr;
  cache.emplace(vs_function, ps_ptr);
  return ps_ptr;
}

// Env-configured, diagnostics-default-off (house rule): XE_METAL_AUTO_TRACE=1
// enables — EXACTLY "1"; anything else fails closed to off. Numeric tuning
// values (_SKIPS / _COOLDOWN / _MAX) must parse completely or the default is
// kept and a warning names the rejected value. Parsed once at first swap on
// the GPU thread.
static bool ParseAutoTraceUint(const char* name, uint32_t* out) {
  const char* value = std::getenv(name);
  if (!value) {
    return false;
  }
  char* end = nullptr;
  unsigned long parsed = std::strtoul(value, &end, 10);
  if (!value[0] || !end || *end || parsed > UINT32_MAX) {
    REXLOG_WARN("MetalAutoTrace: malformed {}='{}' ignored; keeping default {}",
           name, value, *out);
    return false;
  }
  *out = uint32_t(parsed);
  return true;
}

static MetalAutoTraceConfig ParseAutoTraceConfigFromEnv() {
  MetalAutoTraceConfig config;
  const char* enabled = std::getenv("XE_METAL_AUTO_TRACE");
  if (enabled && enabled[0]) {
    if (std::strcmp(enabled, "1") == 0) {
      config.enabled = true;
    } else if (std::strcmp(enabled, "0") != 0) {
      REXLOG_WARN(
          "MetalAutoTrace: malformed XE_METAL_AUTO_TRACE='{}' fails closed "
          "(off); use 1 to enable",
          enabled);
    }
  }
  ParseAutoTraceUint("XE_METAL_AUTO_TRACE_SKIPS", &config.skip_threshold);
  ParseAutoTraceUint("XE_METAL_AUTO_TRACE_COOLDOWN", &config.cooldown_frames);
  ParseAutoTraceUint("XE_METAL_AUTO_TRACE_MAX", &config.max_captures);
  return config;
}

// Swap-boundary finalization shared by EVERY IssueSwap return path, including
// the suppressed-present and no-presenter/no-queue early exits. Evaluating the
// auto-trace trigger only on successful publication would misattribute faults
// and skips carried across a failed swap to a later good one — and a
// PERSISTENT publication failure (the case most likely caused by GPU faults)
// would never capture at all. Uses its own monotonic index for cooldown math:
// swap_count_ does not advance on suppressed frames.
void MetalCommandProcessor::FinalizeSwapFrame() {
  playback_gpu_written_.clear();
  uint64_t finalize_index = ++swap_finalize_index_;
  // Seam-timing per-frame emission FROM THE LIFECYCLE BOUNDARY: this runs for
  // suppressed and early-return swaps too, so boundary attribution can never
  // silently skip a frame that did work but presented nothing. Reset after
  // emission; ShutdownContext / the headless-tool hook emit the remainder.
  {
    char site_buf[32];
    std::snprintf(site_buf, sizeof(site_buf), "swap %llu",
                  (unsigned long long)finalize_index);
    EmitSeamTimingReport(site_buf);
  }
  // Diagnostic (diagnose-jc2-exposure-oscillation, default off):
  // XE_METAL_TRACE_AT_DRAWS=<min_draws_per_frame>,<captures>[,<settle_swaps>]
  // arms single-frame traces on the first <captures> swaps after the frame
  // draw count has stayed >= <min_draws_per_frame> for <settle_swaps> swaps
  // (default 30). A swap-number capture is a lottery on this title (the boot
  // phase runs 40-100 swaps/s and its length varies per run), so the SCENE
  // is the trigger. Traces land under --trace_gpu_prefix like the hotkey's.
  {
    static const std::array<uint32_t, 3> s_trace_at_draws = [] {
      std::array<uint32_t, 3> cfg = {0, 0, 30};
      if (const char* v = std::getenv("XE_METAL_TRACE_AT_DRAWS")) {
        char* end = nullptr;
        cfg[0] = uint32_t(strtoul(v, &end, 10));
        if (end && *end == ',') cfg[1] = uint32_t(strtoul(end + 1, &end, 10));
        if (end && *end == ',') cfg[2] = uint32_t(strtoul(end + 1, &end, 10));
      }
      return cfg;
    }();
    static uint64_t s_last_draw_count = 0;
    static uint32_t s_settled_swaps = 0;
    static uint32_t s_captures_left = s_trace_at_draws[1];
    if (s_trace_at_draws[0] && s_captures_left) {
      // draw_count_ is the cumulative encoded-draw counter (the IssueSwap
      // log's "draws"), so its delta is this frame's draw count.
      uint64_t frame_draws = draw_count_ - s_last_draw_count;
      s_last_draw_count = draw_count_;
      if (frame_draws >= s_trace_at_draws[0]) {
        ++s_settled_swaps;
      } else {
        s_settled_swaps = 0;
      }
      if (s_settled_swaps > s_trace_at_draws[2] &&
          true) {
        --s_captures_left;
        REXLOG_WARN("MetalTraceAtDraws: capturing NEXT frame at swap#{} "
               "(frame draws {}, {} captures left) -> {}",
               swap_count_, frame_draws, s_captures_left,
               (""));
      }
    }
  }
  if (!auto_trace_trigger_) {
    auto_trace_trigger_ =
        std::make_unique<MetalAutoTraceTrigger>(ParseAutoTraceConfigFromEnv());
    if (auto_trace_trigger_->config().enabled) {
      REXLOG_INFO(
          "MetalAutoTrace: armed (skips>={}, on-fault={}, cooldown={} frames, "
          "budget={})",
          auto_trace_trigger_->config().skip_threshold,
          auto_trace_trigger_->config().on_gpu_fault,
          auto_trace_trigger_->config().cooldown_frames,
          auto_trace_trigger_->config().max_captures);
    }
  }
  // Only arm when no capture is pending or streaming: RequestFrameTrace would
  // reject anyway, but going through it would log a spurious error.
  if (auto_trace_trigger_->config().enabled &&
      true) {
    MetalAutoTraceTrigger::Decision auto_trace = auto_trace_trigger_->Evaluate(
        finalize_index, draw_skip_accounting_.frame_actionable_count(),
        frame_gpu_fault_count_);
    if (auto_trace.fire) {
      REXLOG_WARN(
          "MetalAutoTrace: {} at swap#{} (actionable-skips={} gpu-faults={}); "
          "capturing NEXT frame ({}/{}) -> {}",
          auto_trace.reason, swap_count_,
          draw_skip_accounting_.frame_actionable_count(),
          frame_gpu_fault_count_, auto_trace_trigger_->fired_count(),
          auto_trace_trigger_->config().max_captures,
          (""));
    }
  }
  // Task 5.4: bounded overlap evidence on a documented cadence, from the GPU
  // thread's frame boundary rather than from the fault callback that records
  // it. Here rather than in the successful-present body because THIS is the
  // site every IssueSwap return path reaches: a title stuck in persistent
  // publication failure never advances swap_count_, and that is exactly the run
  // whose in-flight CPU rewrite evidence matters most. The schedule itself is a
  // pure predicate over the monotonic finalization index (conformance-pinned in
  // metal_zero_copy_overlap.h); ShutdownContext emits the final line
  // independently of it.
  // The runtime cost line (tasks 6.3/6.4) rides the SAME cadence and the same
  // snapshot: a second schedule would be a second thing to keep honest, and the
  // cost question is asked about the same frame boundaries.
  if (metal::ZeroCopyOverlapReportDue(finalize_index,
                                      kZeroCopyOverlapSwapReportInterval)) {
    ReportZeroCopyLifecycle("swap");
    // Need-based-waits engagement rides this BOUNDED cadence, not the per-swap
    // seam cadence: the meter reports session totals rather than a window, so a
    // per-swap line would restate a growing number ~30x/second while the seam
    // report legitimately prints a fresh window each time.
    EmitNeedBasedWaitReport("swap");
  }
  frame_gpu_fault_count_ = 0;
  draw_skip_accounting_.EndFrame();
}

void MetalCommandProcessor::RecordDrawSkip(MetalDrawSkipReason reason,
                                           const char* site) {
  {
    static const int64_t s_draw_trace_skip = [] {
      const char* v = std::getenv("XE_METAL_DRAW_TRACE");
      return v ? strtoll(v, nullptr, 10) : -1ll;
    }();
    if (s_draw_trace_skip >= 0 &&
        int64_t(trace_draw_index_) - 1 == s_draw_trace_skip) {
      REXLOG_WARN("MetalDrawTrace SKIP draw={} site={}", s_draw_trace_skip, site);
    }
  }
  ++draw_skip_count_;
  if (ZPDCensusEnabled()) {
    NoteZPDCensusDraw(ZPDCensusDraw::kSkipped);
  }
  const RegisterFile& regs = *register_file_;
  uint32_t prim_type =
      uint32_t(regs.Get<reg::VGT_DRAW_INITIATOR>().prim_type);
  const ::rex::gpu::Shader* vs = GetActiveVertexShader();
  const ::rex::gpu::Shader* ps = GetActivePixelShader();
  bool first_in_session = draw_skip_accounting_.Record(
      site, reason, trace_draw_index_, prim_type,
      vs ? vs->GetUcodeDataHash() : 0, ps ? ps->GetUcodeDataHash() : 0);
  // One log line per site per session, actionable severities only: the info
  // tier (expected pruning, diagnostic rollbacks) is high-frequency by nature
  // and lives in the swap report / XE_METAL_SKIP_REPORT dump instead.
  if (first_in_session) {
    MetalDrawSkipSeverity severity = MetalDrawSkipSeverityFor(reason);
    if (severity == MetalDrawSkipSeverity::kError) {
      REXLOG_ERROR("MetalDrawSkip[{}] {} first draw={} prim={} vs={:016X} ps={:016X}",
             MetalDrawSkipReasonName(reason), site, trace_draw_index_,
             prim_type, vs ? vs->GetUcodeDataHash() : 0,
             ps ? ps->GetUcodeDataHash() : 0);
    } else if (severity == MetalDrawSkipSeverity::kWarning) {
      REXLOG_WARN("MetalDrawSkip[{}] {} first draw={} prim={} vs={:016X} ps={:016X}",
             MetalDrawSkipReasonName(reason), site, trace_draw_index_,
             prim_type, vs ? vs->GetUcodeDataHash() : 0,
             ps ? ps->GetUcodeDataHash() : 0);
    }
  }
}

// A write fault over a GPU-owned range whose producer is still in the open
// command buffer (see OnLazyRead) needs that buffer committed before the
// faulting thread can wait for the producer. Serviced from the GPU thread
// only: at each draw, so the commit is an ordinary pass end, and from the idle
// and WAIT_REG_MEM loops (OnIdlePoll), where the writing thread is often the
// one that would have queued the next draw.
void MetalCommandProcessor::ServiceLazyCommitRequest() {
  const uint64_t requested =
      lazy_commit_request_.load(std::memory_order_acquire);
  if (!requested) {
    return;
  }
  // Not gated on frame_open_: a command buffer recording only compute or blit
  // work (resolves, uploads) has no render encoder open but still holds the
  // requested producer. EndFrameEncoder is a no-op without a buffer.
  if (requested > submission_counter_) {
    EndFrameEncoder(metal::SeamBoundaryReason::kHazardFlush);
  }
  lazy_commit_request_.store(0, std::memory_order_release);
}

// Diagnostics XE_METAL_DUMP_RT / XE_METAL_DUMP_RT_PS (see the block): called
// from every IssueDraw encode path that ends a draw, including the
// geometry-emulated one that returns before the common tail.
void MetalCommandProcessor::DumpBoundColorRtDiagnostic(
    const ::rex::gpu::Shader* pixel_shader) {
  // Diagnostic: XE_METAL_DUMP_RT=<trace draw index> dumps the bound color-0
  // RT texture to /tmp/xe_rt_<index>.ppm right after that draw encodes —
  // TEXTURE-space ground truth vs the EDRAM-mapped view of the capture
  // pipeline (splits "content mislaid in the texture" from "the dump/EDRAM
  // mapping mislays it").
  static const int64_t s_dump_rt_at = [] {
    const char* v = std::getenv("XE_METAL_DUMP_RT");
    return v ? strtoll(v, nullptr, 10) : -1ll;
  }();
  // Live variant: XE_METAL_DUMP_RT_PS=<pixel shader ucode hash hex>[:<every>]
  // dumps the bound color-0 RT after every <every>-th draw using that pixel
  // shader (default every 60th) to /tmp/xe_rtps_<swap>_<n>.ppm, so a live
  // pass output can be compared with the same pass in a replay.
  // Several shaders: "hash[:every],hash[:every],...". Each has its own
  // occurrence counter; the file name carries the swap, the shader's hash
  // prefix and its occurrence count.
  struct DumpRtPsEntry {
    uint64_t hash;
    uint32_t every;
    uint32_t seen;
  };
  static std::vector<DumpRtPsEntry> s_dump_rt_ps = [] {
    std::vector<DumpRtPsEntry> entries;
    const char* v = std::getenv("XE_METAL_DUMP_RT_PS");
    if (!v) return entries;
    std::string spec(v);
    size_t pos = 0;
    while (pos < spec.size()) {
      size_t comma = spec.find(',', pos);
      std::string item = spec.substr(
          pos, comma == std::string::npos ? std::string::npos : comma - pos);
      char* end = nullptr;
      uint64_t hash = strtoull(item.c_str(), &end, 16);
      uint32_t every = 60u;
      if (end && *end == ':') {
        every = !strcmp(end + 1, "trace")
                    ? 0u
                    : uint32_t(strtoul(end + 1, nullptr, 10));
        if (every == 0u && strcmp(end + 1, "trace") != 0) every = 60u;
      }
      if (hash) entries.push_back({hash, every, 0u});
      if (comma == std::string::npos) break;
      pos = comma + 1;
    }
    return entries;
  }();
  bool dump_ps_now = false;
  uint32_t s_dump_rt_ps_seen = 0;
  uint64_t dump_ps_hash = 0;
  if (pixel_shader) {
    for (DumpRtPsEntry& e : s_dump_rt_ps) {
      if (e.hash == pixel_shader->GetUcodeDataHash()) {
        ++e.seen;
        if (e.every == 0u ? false : (e.seen % e.every) == 0) {
          dump_ps_now = true;
          s_dump_rt_ps_seen = e.seen;
          dump_ps_hash = e.hash;
        }
        break;
      }
    }
  }
  // XE_METAL_DUMP_RT_CONSTS=<c,c,...>: with every dump, log those pixel
  // shader float constants (exposure / curve parameters live vs replay).
  if (dump_ps_now) {
    static const std::vector<uint32_t> s_dump_consts = [] {
      std::vector<uint32_t> out;
      const char* v = std::getenv("XE_METAL_DUMP_RT_CONSTS");
      if (!v) return out;
      std::string spec(v);
      size_t pos = 0;
      while (pos < spec.size()) {
        size_t comma = spec.find(',', pos);
        out.push_back(uint32_t(strtoul(spec.substr(pos).c_str(), nullptr, 10)));
        if (comma == std::string::npos) break;
        pos = comma + 1;
      }
      return out;
    }();
    for (uint32_t c : s_dump_consts) {
      if (c >= 256) continue;
      uint32_t r = XE_GPU_REG_SHADER_CONSTANT_256_X + c * 4;
      REXLOG_WARN("XE_METAL_DUMP_RT: swap#{} ps c{} = ({}, {}, {}, {})", swap_count_,
             c, register_file_->Get<float>(r), register_file_->Get<float>(r + 1),
             register_file_->Get<float>(r + 2), register_file_->Get<float>(r + 3));
    }
  }
  if (dump_ps_now ||
      (s_dump_rt_at >= 0 && int64_t(trace_draw_index_) - 1 == s_dump_rt_at)) {
    EndFrameEncoderAndWait(metal::SeamBoundaryReason::kDebugProbe);
    void* rt_ptr = render_target_cache_->current_color_texture(0, nullptr);
    if (rt_ptr) {
      __unsafe_unretained id<MTLTexture> rt_tex = (__bridge id<MTLTexture>)rt_ptr;
      uint32_t tw = uint32_t(rt_tex.width), th = uint32_t(rt_tex.height);
      uint32_t bpp = 4;
      switch (rt_tex.pixelFormat) {
        case MTLPixelFormatRGBA16Float:
        case MTLPixelFormatRGBA16Unorm:
        case MTLPixelFormatRGBA16Snorm:
        case MTLPixelFormatRGBA16Uint:
        case MTLPixelFormatRG32Float:
        case MTLPixelFormatRG32Uint:
          bpp = 8;
          break;
        case MTLPixelFormatRGBA32Float:
        case MTLPixelFormatRGBA32Uint:
          bpp = 16;
          break;
        default:
          break;
      }
      id<MTLBuffer> rb =
          [rt_tex.device newBufferWithLength:size_t(tw) * th * bpp
                                     options:MTLResourceStorageModeShared];
      __unsafe_unretained id<MTLCommandQueue> dq = (__bridge id<MTLCommandQueue>)
          static_cast<rex::ui::metal::MetalProvider*>(
              GetGraphicsDriver().GetProvider())->command_queue();
      if (rb && dq) {
        id<MTLCommandBuffer> dcb = [dq commandBuffer];
        id<MTLBlitCommandEncoder> dbl = [dcb blitCommandEncoder];
        [dbl copyFromTexture:rt_tex
                  sourceSlice:0
                  sourceLevel:0
                 sourceOrigin:MTLOriginMake(0, 0, 0)
                   sourceSize:MTLSizeMake(tw, th, 1)
                     toBuffer:rb
            destinationOffset:0
       destinationBytesPerRow:tw * bpp
     destinationBytesPerImage:size_t(tw) * th * bpp];
        [dbl endEncoding];
        [dcb commit];
        [dcb waitUntilCompleted];
        std::string path =
            dump_ps_now ? fmt::format("/tmp/xe_rtps_{}_{:08X}_{}.ppm",
                                      swap_count_, uint32_t(dump_ps_hash >> 32),
                                      s_dump_rt_ps_seen)
                        : fmt::format("/tmp/xe_rt_{}.ppm", s_dump_rt_at);
        if (bpp != 4) {
          // Raw texels beside the PPM for 64/128-bit targets (half floats);
          // the PPM shows each texel's first 3 bytes.
          if (FILE* fr = fopen((path + ".raw").c_str(), "wb")) {
            fwrite(rb.contents, 1, size_t(tw) * th * bpp, fr);
            fclose(fr);
          }
        }
        FILE* f = fopen(path.c_str(), "wb");
        if (f) {
          fprintf(f, "P6\n%u %u\n255\n", tw, th);
          const uint8_t* px = static_cast<const uint8_t*>(rb.contents);
          uint64_t a_sum = 0;
          uint8_t a_min = 255, a_max = 0;
          for (size_t i = 0; i < size_t(tw) * th; ++i) {
            fwrite(px + i * bpp, 1, 3, f);  // RGBA8 storage: bytes are R,G,B.
            uint8_t a = px[i * bpp + 3];
            a_sum += a;
            a_min = std::min(a_min, a);
            a_max = std::max(a_max, a);
          }
          fclose(f);
          REXLOG_WARN("XE_METAL_DUMP_RT: wrote {} ({}x{} fmt={} bpp={}) alpha min={} max={} mean={:.2f}",
                 path, tw, th, uint32_t(rt_tex.pixelFormat), bpp, a_min, a_max,
                 double(a_sum) / (double(tw) * th));
        }
      }
    }
  }
}

namespace {
// Captures the position and the vertex kill flag of one interpreted vertex.
class OverwritePositionSink : public ::rex::gpu::ShaderInterpreter::ExportSink {
 public:
  void Export(xenos::ucode::ExportRegister export_register, const float* value,
              uint32_t value_mask) override {
    if (export_register == xenos::ucode::ExportRegister::kVSPosition) {
      for (uint32_t i = 0; i < 4; ++i) {
        if (value_mask & (1u << i)) {
          position[i] = value[i];
          position_mask |= 1u << i;
        }
      }
    } else if (export_register ==
                   xenos::ucode::ExportRegister::kVSPointSizeEdgeFlagKillVertex &&
               (value_mask & 0b0100)) {
      killed = (Reinterpret<uint32_t>(value[2]) &
                ~(UINT32_C(1) << 31)) != 0;
    }
  }
  float position[4] = {};
  uint32_t position_mask = 0;
  bool killed = false;
};
}  // namespace

uint32_t MetalCommandProcessor::ComputeDrawOverwrite(
    xenos::PrimitiveType prim_type, const ::rex::gpu::Shader* vertex_shader,
    const ::rex::gpu::Shader* pixel_shader, uint32_t normalized_color_mask,
    reg::RB_DEPTHCONTROL depth, float rect_out[4]) {
  // Default on; XE_METAL_OVERWRITE_SKIP=0 materializes as before.
  static const bool s_enabled = [] {
    const char* v = std::getenv("XE_METAL_OVERWRITE_SKIP");
    return !(v && v[0] == '0' && !v[1]);
  }();
  if (!s_enabled || prim_type != xenos::PrimitiveType::kRectangleList ||
      !vertex_shader || !vertex_shader->IsUcodeAnalyzed()) {
    return 0;
  }
  // XE_METAL_OVERWRITE_LOG=1: why rectangles are not overwrite candidates.
  static const bool s_log = std::getenv("XE_METAL_OVERWRITE_LOG") != nullptr;
  static uint32_t s_logs = 0;
  auto reject = [&](const char* why, float a = 0, float b = 0, float c = 0,
                    float d = 0) -> uint32_t {
    // The first 300, then one in 32 (gameplay past the menus).
    if (s_log && (s_logs++ < 300 || (s_logs & 31u) == 0)) {
      REXLOG_WARN("MetalOverwrite reject {} ({}, {}, {}, {}) vs={:016X}", why, a,
             b, c, d, vertex_shader->GetUcodeDataHash());
    }
    return 0;
  };
  const RegisterFile& regs = *register_file_;
  auto initiator = regs.Get<reg::VGT_DRAW_INITIATOR>();
  if (initiator.num_indices != 3 ||
      (initiator.source_select != xenos::SourceSelect::kDMA &&
       initiator.source_select != xenos::SourceSelect::kAutoIndex)) {
    return reject("draw-shape");
  }
  if (xenos::IsMajorModeExplicit(initiator.major_mode, initiator.prim_type) &&
      regs.Get<reg::VGT_OUTPUT_PATH_CNTL>().path_select ==
          xenos::VGTOutputPath::kTessellationEnable) {
    return reject("tessellation");
  }
  const xenos::EDRAMMode edram_mode = regs.Get<reg::RB_MODECONTROL>().edram_mode;
  if (edram_mode != xenos::EDRAMMode::kColorDepth &&
      edram_mode != xenos::EDRAMMode::kDepthOnly) {
    return reject("edram-mode");
  }
  auto mode_cntl = regs.Get<reg::PA_SU_SC_MODE_CNTL>();
  auto window_offset = regs.Get<reg::PA_SC_WINDOW_OFFSET>();
  if (mode_cntl.cull_front || mode_cntl.cull_back ||
      mode_cntl.poly_mode != xenos::PolygonModeEnable::kDisabled ||
      (mode_cntl.vtx_window_offset_enable &&
       (window_offset.window_x_offset || window_offset.window_y_offset))) {
    return reject("raster-state",
                  float(mode_cntl.cull_front | (mode_cntl.cull_back << 1)),
                  float(uint32_t(mode_cntl.poly_mode)),
                  float(window_offset.window_x_offset),
                  float(window_offset.window_y_offset));
  }
  auto clip_cntl = regs.Get<reg::PA_CL_CLIP_CNTL>();
  auto color_control = regs.Get<reg::RB_COLORCONTROL>();
  if (clip_cntl.ucp_ena || color_control.alpha_to_mask_enable ||
      (pixel_shader && pixel_shader->DoesKillPixels())) {
    return reject("pixel-discard", float(clip_cntl.ucp_ena),
                  float(color_control.alpha_to_mask_enable),
                  float(pixel_shader && pixel_shader->DoesKillPixels()));
  }
  // GTA IV's alpha-tested clear rectangles test alpha != 0 with alpha 0: they
  // write nothing, so they are not overwrites.
  if (color_control.alpha_test_enable &&
      color_control.alpha_func != xenos::CompareFunction::kAlways) {
    return reject("alpha-test", float(color_control.alpha_func),
                  regs.Get<float>(XE_GPU_REG_RB_ALPHA_REF));
  }
  // Slots every covered sample of which the draw writes regardless of the old
  // content.
  uint32_t slots = 0;
  auto stencil_replaces = [](xenos::CompareFunction func, xenos::StencilOp op,
                             reg::RB_STENCILREFMASK mask) {
    return func == xenos::CompareFunction::kAlways &&
           op == xenos::StencilOp::kReplace && mask.stencilwritemask == 0xFF;
  };
  if (depth.z_enable && depth.z_write_enable &&
      depth.zfunc == xenos::CompareFunction::kAlways && depth.stencil_enable &&
      stencil_replaces(depth.stencilfunc, depth.stencilzpass,
                       regs.Get<reg::RB_STENCILREFMASK>()) &&
      (!depth.backface_enable ||
       stencil_replaces(depth.stencilfunc_bf, depth.stencilzpass_bf,
                        regs.Get<reg::RB_STENCILREFMASK>(
                            XE_GPU_REG_RB_STENCILREFMASK_BF)))) {
    slots |= 1u;
  }
  for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets &&
                      edram_mode == xenos::EDRAMMode::kColorDepth;
       ++i) {
    if (((normalized_color_mask >> (i * 4)) & 0xFu) != 0xFu || !pixel_shader ||
        !pixel_shader->IsColorTargetWritten(i)) {
      continue;
    }
    auto blend = regs.Get<reg::RB_BLENDCONTROL>(
        xenos::compat::BlendControlRegisterIndex(i));
    if (blend.color_srcblend == xenos::BlendFactor::kOne &&
        blend.color_destblend == xenos::BlendFactor::kZero &&
        blend.color_comb_fcn == xenos::BlendOp::kAdd &&
        blend.alpha_srcblend == xenos::BlendFactor::kOne &&
        blend.alpha_destblend == xenos::BlendFactor::kZero &&
        blend.alpha_comb_fcn == xenos::BlendOp::kAdd) {
      slots |= 1u << (1 + i);
    }
  }
  if (!slots || !::rex::gpu::ShaderInterpreter::CanInterpretShader(*vertex_shader)) {
    return reject("no-full-write", float(slots), float(depth.value & 0xFFFF),
                  float(depth.value >> 16), float(normalized_color_mask));
  }
  // The window position as DrawExtentEstimator derives it: xy divided by w
  // unless pre-transformed, then the enabled viewport scale and offset.
  auto vte = regs.Get<reg::PA_CL_VTE_CNTL>();
  const bool viewport_enabled = vte.vport_x_scale_ena &&
                                vte.vport_x_offset_ena &&
                                vte.vport_y_scale_ena && vte.vport_y_offset_ena;
  // vtx_w0_fmt (set by Direct3D 9 for everything) describes the VTE's W
  // output, not the divide, which DrawExtentEstimator applies regardless.
  if (!clip_cntl.clip_disable &&
      (!viewport_enabled || vte.vtx_xy_fmt || vte.vtx_z_fmt)) {
    // Clipping in a space this check does not model.
    return reject("clip-space", float(vte.value), float(viewport_enabled));
  }
  const float x_scale =
      vte.vport_x_scale_ena ? regs.Get<float>(XE_GPU_REG_PA_CL_VPORT_XSCALE)
                            : 1.0f;
  const float x_offset =
      vte.vport_x_offset_ena ? regs.Get<float>(XE_GPU_REG_PA_CL_VPORT_XOFFSET)
                             : 0.0f;
  const float y_scale =
      vte.vport_y_scale_ena ? regs.Get<float>(XE_GPU_REG_PA_CL_VPORT_YSCALE)
                            : 1.0f;
  const float y_offset =
      vte.vport_y_offset_ena ? regs.Get<float>(XE_GPU_REG_PA_CL_VPORT_YOFFSET)
                             : 0.0f;
  const float center =
      regs.Get<reg::PA_SU_VTX_CNTL>().pix_center == xenos::PixelCenter::kD3DZero
          ? 0.5f
          : 0.0f;

  // Vertex indices as the primitive processor and DrawExtentEstimator read
  // them.
  uint32_t indices[3];
  auto dma_size = regs.Get<reg::VGT_DMA_SIZE>();
  if (initiator.source_select == xenos::SourceSelect::kDMA) {
    if (dma_size.num_words < 3) {
      return reject("dma-short");
    }
    xenos::Endian endian = dma_size.swap_mode;
    uint32_t base = regs[XE_GPU_REG_VGT_DMA_BASE];
    if (initiator.index_size == xenos::IndexFormat::kInt16) {
      if (endian == xenos::Endian::k8in32) {
        endian = xenos::Endian::k8in16;
      } else if (endian == xenos::Endian::k16in32) {
        endian = xenos::Endian::kNone;
      }
      auto source = TranslateGuest<const uint16_t*>(
          base & ~uint32_t(sizeof(uint16_t) - 1));
      for (uint32_t i = 0; i < 3; ++i) {
        indices[i] = xenos::GPUSwap(uint32_t(source[i]), endian) & 0xFFFFFF;
      }
    } else {
      auto source = TranslateGuest<const uint32_t*>(
          base & ~uint32_t(sizeof(uint32_t) - 1));
      for (uint32_t i = 0; i < 3; ++i) {
        indices[i] = xenos::GPUSwap(source[i], endian) & 0xFFFFFF;
      }
    }
    if (mode_cntl.multi_prim_ib_ena) {
      const uint32_t reset =
          regs.Get<reg::VGT_MULTI_PRIM_IB_RESET_INDX>().reset_indx;
      for (uint32_t i = 0; i < 3; ++i) {
        if (indices[i] == reset) {
          return reject("reset-index");
        }
      }
    }
  } else {
    for (uint32_t i = 0; i < 3; ++i) {
      indices[i] = i;
    }
  }
  const uint32_t index_offset = regs.Get<reg::VGT_INDX_OFFSET>().indx_offset;
  const uint32_t min_index = regs.Get<reg::VGT_MIN_VTX_INDX>().min_indx;
  const uint32_t max_index = regs.Get<reg::VGT_MAX_VTX_INDX>().max_indx;

  if (!overwrite_interpreter_) {
    overwrite_interpreter_ =
        std::make_unique<::rex::gpu::ShaderInterpreter>(regs, physical_memory_);
  }
  ::rex::gpu::ShaderInterpreter& interpreter = *overwrite_interpreter_;
  interpreter.SetShader(*vertex_shader);
  OverwritePositionSink sink;
  interpreter.SetExportSink(&sink);
  float x[3], y[3];
  bool ok = true;
  for (uint32_t i = 0; i < 3 && ok; ++i) {
    sink = OverwritePositionSink();
    interpreter.GetTempRegisters()[0] = float(std::min(
        max_index, std::max(min_index, (indices[i] + index_offset) & 0xFFFFFF)));
    interpreter.Execute();
    const float* p = sink.position;
    const uint32_t needed_mask = vte.vtx_xy_fmt ? 0b0011u : 0b1011u;
    if (sink.killed || (sink.position_mask & needed_mask) != needed_mask ||
        (!vte.vtx_xy_fmt && !(p[3] > 0.0f)) || !std::isfinite(p[0]) ||
        !std::isfinite(p[1])) {
      ok = false;
      break;
    }
    if (!clip_cntl.clip_disable) {
      // The whole rectangle must lie inside the depth clip range.
      const float z_min = clip_cntl.dx_clip_space_def ? 0.0f : -p[3];
      if (!(sink.position_mask & 0b0100) || !std::isfinite(p[2]) ||
          p[2] < z_min || p[2] > p[3]) {
        ok = false;
        break;
      }
    }
    const float inv_w = vte.vtx_xy_fmt ? 1.0f : 1.0f / p[3];
    x[i] = p[0] * inv_w * x_scale + x_offset + center;
    y[i] = p[1] * inv_w * y_scale + y_offset + center;
  }
  interpreter.SetExportSink(nullptr);
  if (!ok) {
    return reject("vertex");
  }
  // Three corners of an axis-aligned rectangle: two distinct values on each
  // axis (the fourth corner is then that rectangle's).
  auto two_values = [](const float v[3], float& lo, float& hi) {
    lo = std::min(v[0], std::min(v[1], v[2]));
    hi = std::max(v[0], std::max(v[1], v[2]));
    for (uint32_t i = 0; i < 3; ++i) {
      if (v[i] != lo && v[i] != hi) {
        return false;
      }
    }
    return lo < hi;
  };
  float x0, x1, y0, y1;
  if (!two_values(x, x0, x1) || !two_values(y, y0, y1)) {
    return reject("not-axis-aligned");
  }
  // The viewport bounds the host's coverage even with guest clipping off.
  if (viewport_enabled) {
    const float ax = std::abs(x_scale), ay = std::abs(y_scale);
    x0 = std::max(x0, x_offset - ax + center);
    x1 = std::min(x1, x_offset + ax + center);
    y0 = std::max(y0, y_offset - ay + center);
    y1 = std::min(y1, y_offset + ay + center);
  }
  ::rex::gpu::draw_state::Scissor scissor;
  ::rex::gpu::draw_state::GetScissor(regs, scissor, true);
  x0 = std::max(x0, float(scissor.offset[0]));
  y0 = std::max(y0, float(scissor.offset[1]));
  x1 = std::min(x1, float(scissor.offset[0] + scissor.extent[0]));
  y1 = std::min(y1, float(scissor.offset[1] + scissor.extent[1]));
  if (!(x0 < x1) || !(y0 < y1)) {
    return reject("empty");
  }
  rect_out[0] = x0;
  rect_out[1] = y0;
  rect_out[2] = x1;
  rect_out[3] = y1;
  return slots;
}

bool MetalCommandProcessor::IssueDraw(xenos::PrimitiveType prim_type,
                                      uint32_t index_count,
                                      ::rex::gpu::CommandProcessor::IndexBuffer* index_buffer_info,
                                      bool major_mode_explicit) {
  // Draw-for-draw trace, field-for-field identical to the one the Vulkan backend writes
  // (src/graphics/vulkan/command_processor.cpp, REX_TRACE), so the two backends can be diffed draw by draw. It was
  // lost from this backend in the port, and without it "the quad list draws over-add" cannot be turned into "this
  // draw asks for N and we issue M".
  {
    static FILE* trace_entry = nullptr;
    static bool trace_entry_tried = false;
    static uint64_t trace_entry_index = 0;
    if (!trace_entry_tried) {
      trace_entry_tried = true;
      if (const char* trace_path = std::getenv("REX_TRACE")) {
        std::string path = std::string(trace_path) + ".metal.entries";
        trace_entry = std::fopen(path.c_str(), "w");
        if (trace_entry != nullptr) {
          std::fprintf(trace_entry,
                       "draw,primitive,index_count,fmt0,fmt1,mask0,mask1,depth_en,depth_wr,depth_cmp,"
                       "const_crc,swap,blend0,scissor_tl,scissor_br\n");
        }
      }
    }
    if (trace_entry != nullptr) {
      uint32_t fmt0 = 0, fmt1 = 0, mask0 = 0, mask1 = 0, den = 0, dwr = 0, dcmp = 0;
      uint32_t crc = 2166136261u;
      if (register_file_ != nullptr) {
        const reg::RB_COLOR_INFO i0 = register_file_->Get<reg::RB_COLOR_INFO>();
        const reg::RB_COLOR_INFO i1 = register_file_->Get<reg::RB_COLOR_INFO>(
            static_cast<uint32_t>(xenos::compat::ColorInfoRegisterIndex(0)) + 1);
        const reg::RB_COLOR_MASK m = register_file_->Get<reg::RB_COLOR_MASK>();
        const reg::RB_DEPTHCONTROL dc = register_file_->Get<reg::RB_DEPTHCONTROL>();
        fmt0 = uint32_t(i0.color_format) & 15;
        fmt1 = uint32_t(i1.color_format) & 15;
        mask0 = uint32_t(m.write_red0) | (uint32_t(m.write_green0) << 1) |
                (uint32_t(m.write_blue0) << 2) | (uint32_t(m.write_alpha0) << 3);
        mask1 = uint32_t(m.write_red1) | (uint32_t(m.write_green1) << 1) |
                (uint32_t(m.write_blue1) << 2) | (uint32_t(m.write_alpha1) << 3);
        den = dc.z_enable != 0 ? 1u : 0u;
        dwr = dc.z_write_enable != 0 ? 1u : 0u;
        dcmp = uint32_t(dc.zfunc) & 7u;
        const uint32_t* words = &(*register_file_)[XE_GPU_REG_SHADER_CONSTANT_000_X];
        for (uint32_t i = 0; i < 1024; ++i) {
          crc = (crc ^ words[i]) * 16777619u;
        }
      }
      // The swap travels with each row so two backends' traces can be aligned: presented frame numbers arrive after
      // different amounts of guest work, so comparing rows by position compares different moments.
      std::fprintf(trace_entry, "%llu,%u,%u,%u,%u,%u,%u,%u,%u,%u,%08X,%u,%08X,%08X,%08X\n",
                   (unsigned long long)trace_entry_index, uint32_t(prim_type), index_count,
                   fmt0, fmt1, mask0, mask1, den, dwr, dcmp, crc, swap_count(),
                   uint32_t((*register_file_)[XE_GPU_REG_RB_BLENDCONTROL0]),
                   uint32_t((*register_file_)[XE_GPU_REG_PA_SC_WINDOW_SCISSOR_TL]),
                   uint32_t((*register_file_)[XE_GPU_REG_PA_SC_WINDOW_SCISSOR_BR]));
      // The game is killed at the stop frame, so a block-buffered file keeps only its flushed prefix and the row
      // counts measure buffering instead of draws. One flush per row makes the two backends' traces comparable.
      std::fflush(trace_entry);
      ++trace_entry_index;
      // The pixel shader behind the quad-list draws is the last untested layer, and every shader dump lever is keyed
      // by ucode hash, so name the hashes here rather than guessing which shader to dump.
      if (prim_type == xenos::PrimitiveType::kQuadList && GetActivePixelShader() != nullptr) {
        static std::set<uint64_t> s_quad_ps_hashes;
        const uint64_t quad_hash = GetActivePixelShader()->GetUcodeDataHash();
        if (s_quad_ps_hashes.insert(quad_hash).second) {
          REXLOG_INFO("MetalQuadPs hash={:016X}", quad_hash);
        }
      }
    }
  }
  {
    // UI DRAW CENSUS: on one late swap, list every draw with the texture it fetches and the blend state it uses, so
    // the draw that should paint the menu panel can be identified by its inputs rather than by guessing.
    static uint32_t s_ui_census_swap = [] {
      const char* v = std::getenv("XE_METAL_UI_CENSUS_SWAP");
      return v ? uint32_t(strtoul(v, nullptr, 10)) : 0u;
    }();
    static bool s_ui_census_done = false;
    if (s_ui_census_swap && !s_ui_census_done && swap_count_ >= s_ui_census_swap) {
      // Draws belonging to the first frame at or after the requested swap.

      const auto fetch0 = register_file_->GetTextureFetch(0);
      if (draw_count_ == 1) { REXLOG_WARN("UIDraw frame begins at swap {}", swap_count_); }
      REXLOG_WARN("UIDraw {}: prim {} count {} texbase {:08X} fmt {} size {}x{} swz {:03X} | blendctl {:08X}",
                  draw_count_, uint32_t(prim_type), index_count,
                  uint32_t(fetch0.base_address) << 12, uint32_t(fetch0.format),
                  uint32_t(1u << fetch0.size_2d.width), uint32_t(1u << fetch0.size_2d.height),
                  uint32_t(fetch0.swizzle) & 0xFFFu,
                  uint32_t(register_file_->values[XE_GPU_REG_RB_BLENDCONTROL0]));
    }
  }
  ServiceLazyCommitRequest();
  // Diagnostic (XE_METAL_COMMIT_EVERY_DRAWS=N): commit the frame's command
  // buffer once N draws are encoded in it, so a GPU-timeout fault's draw
  // sequence names at most N draws.
  {
    static const uint32_t s_commit_every = [] {
      const char* v = std::getenv("XE_METAL_COMMIT_EVERY_DRAWS");
      return v ? uint32_t(strtoul(v, nullptr, 10)) : 0u;
    }();
    if (s_commit_every && draws_since_commit_ >= s_commit_every) {
      EndFrameEncoder(metal::SeamBoundaryReason::kDebugProbe);
    }
  }
  // ArenaAllocate can only wait for committed submissions, so one open
  // submission that fills the upload arena drops every later draw in it
  // (Dishonored's ~17k-draw loading frame lost 16-41k draws on sysconst-alloc
  // once its count-only occlusion draws ran). Commit at a draw boundary, before
  // this draw allocates anything, once the open submission holds a quarter of
  // the ring. XE_METAL_ARENA_SPLIT_BYTES=<bytes> moves the threshold; 0 turns
  // the split off.
  {
    static const uint64_t s_arena_split_bytes = [this]() -> uint64_t {
      const char* v = std::getenv("XE_METAL_ARENA_SPLIT_BYTES");
      if (v) {
        return std::strtoull(v, nullptr, 10);
      }
      return upload_arena_ ? upload_arena_->size() / 4 : 0;
    }();
    if (s_arena_split_bytes && upload_arena_ && draws_since_commit_ > 0 &&
        upload_arena_->open_bytes() >= s_arena_split_bytes) {
      EndFrameEncoder(metal::SeamBoundaryReason::kArenaSplit);
    }
  }
  const bool state_dedupe = StateDedupeEnabled();
  // Diagnostic (XE_METAL_DRAW_TRACE=<draw>): log entry into IssueDraw for one
  // trace draw, with the primitive and index count, before any early exit.
  {
    static const int64_t s_draw_trace = [] {
      const char* v = std::getenv("XE_METAL_DRAW_TRACE");
      return v ? strtoll(v, nullptr, 10) : -1ll;
    }();
    if (s_draw_trace >= 0 && int64_t(trace_draw_index_) - 1 == s_draw_trace) {
      REXLOG_WARN("MetalDrawTrace enter draw={} prim={} index_count={} indexed={}",
             s_draw_trace, uint32_t(prim_type), index_count,
             index_buffer_info != nullptr);
    }
  }
  // An EDRAM "copy mode" draw is not geometry — it's a resolve (EDRAM ->
  // guest). The D3D12/Vulkan backends dispatch this from IssueDraw; without the
  // check our backend treated resolves as normal draws and IssueCopy never fired
  // (the gameplay gray screen: the scene is resolved to a guest texture we never
  // populate, so the composite samples the null/gray texture).
  if (register_file_->Get<reg::RB_MODECONTROL>().edram_mode ==
      xenos::EDRAMMode::kCopy) {
    return IssueCopy();
  }
  // Diagnostic (XE_METAL_SKIP_DRAWS=<first>-<last>): drop the geometry draws
  // with trace draw indices in the range (as XE_METAL_DRAW_TRACE counts), for
  // bisecting which draw produces a defect in a replayed frame.
  {
    static const std::pair<int64_t, int64_t> s_skip_draws = [] {
      const char* v = std::getenv("XE_METAL_SKIP_DRAWS");
      if (!v) {
        return std::pair<int64_t, int64_t>(-1, -2);
      }
      char* end;
      int64_t first = strtoll(v, &end, 10);
      int64_t last = *end == '-' ? strtoll(end + 1, nullptr, 10) : first;
      REXLOG_WARN("MetalSkipDraws: dropping draws {}..{}", first, last);
      return std::pair<int64_t, int64_t>(first, last);
    }();
    const int64_t draw = int64_t(trace_draw_index_) - 1;
    if (draw >= s_skip_draws.first && draw <= s_skip_draws.second) {
      return true;
    }
    // XE_METAL_SKIP_PRIM=<xenos primitive type>: drop every draw of one type.
    static const int s_skip_prim = [] {
      const char* v = std::getenv("XE_METAL_SKIP_PRIM");
      return v ? std::atoi(v) : -1;
    }();
    if (int(prim_type) == s_skip_prim) {
      return true;
    }
  }


  // XE_METAL_DRAW_PHASE_TIMING=1: nanoseconds between consecutive milestones
  // of IssueDraw, accumulated per label (plus "tail" from the last milestone
  // to the function's exit), reported per stats tick as ms/frame. The
  // attribution for the inlined body of IssueDraw that samplers cannot split.
  static const bool s_phase_timing =
      std::getenv("XE_METAL_DRAW_PHASE_TIMING") != nullptr;
  struct PhaseTimer {
    bool on;
    uint64_t last;
    MetalCommandProcessor* self;
    ~PhaseTimer() {
      if (on) {
        self->NoteDrawPhase("tail", last);
      }
    }
  } phase_timer{s_phase_timing,
                s_phase_timing ? uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(
                                     std::chrono::steady_clock::now().time_since_epoch()).count())
                               : 0,
                this};
  auto draw_trace_milestone = [&](const char* where) {
    static const int64_t s_draw_trace_ms = [] {
      const char* v = std::getenv("XE_METAL_DRAW_TRACE");
      return v ? strtoll(v, nullptr, 10) : -1ll;
    }();
    if (s_draw_trace_ms >= 0 && int64_t(trace_draw_index_) - 1 == s_draw_trace_ms) {
      REXLOG_WARN("MetalDrawTrace {} draw={}", where, s_draw_trace_ms);
    }
    if (phase_timer.on) {
      phase_timer.last = NoteDrawPhase(where, phase_timer.last);
    }
  };
  auto* vertex_shader = static_cast<MetalShader*>(GetActiveVertexShader());
  auto* pixel_shader = static_cast<MetalShader*>(GetActivePixelShader());
  // Replay experiment (XE_METAL_PS_CONST_OVERRIDE=<ps hash hex>:<c>=<x,y,z,w>
  // [;...]): overwrite pixel-shader float constants in the register file
  // before this draw marshals them. Diagnostic only.
  {
    struct PsConstOverride {
      uint64_t hash;
      uint32_t c;
      float v[4];
    };
    static const std::vector<PsConstOverride> s_overrides = [] {
      std::vector<PsConstOverride> out;
      const char* env = std::getenv("XE_METAL_PS_CONST_OVERRIDE");
      if (!env) return out;
      std::string spec(env);
      size_t pos = 0;
      while (pos < spec.size()) {
        size_t semi = spec.find(';', pos);
        std::string item = spec.substr(
            pos, semi == std::string::npos ? std::string::npos : semi - pos);
        PsConstOverride o{};
        char* end = nullptr;
        o.hash = strtoull(item.c_str(), &end, 16);
        if (end && *end == ':') {
          o.c = uint32_t(strtoul(end + 1, &end, 10));
          if (end && *end == '=') {
            const char* p = end + 1;
            for (int i = 0; i < 4; ++i) {
              o.v[i] = strtof(p, &end);
              p = (end && *end == ',') ? end + 1 : end;
            }
            if (o.hash && o.c < 256) out.push_back(o);
          }
        }
        if (semi == std::string::npos) break;
        pos = semi + 1;
      }
      return out;
    }();
    if (!s_overrides.empty() && pixel_shader) {
      for (const PsConstOverride& o : s_overrides) {
        if (o.hash != pixel_shader->GetUcodeDataHash()) continue;
        uint32_t r = XE_GPU_REG_SHADER_CONSTANT_256_X + o.c * 4;
        for (int i = 0; i < 4; ++i) {
          uint32_t bits;
          std::memcpy(&bits, &o.v[i], 4);
          // Through WriteRegister so constant dirty tracking and memos see it.
          WriteRegister(r + i, bits);
        }
        static uint32_t s_override_logs = 0;
        if (s_override_logs++ < 4) {
          REXLOG_WARN("MetalPsConstOverride: ps={:016X} c{} = ({}, {}, {}, {})",
                 o.hash, o.c, o.v[0], o.v[1], o.v[2], o.v[3]);
        }
      }
    }
  }
  if (!vertex_shader || !pipeline_cache_ || !upload_arena_) {
    RecordDrawSkip(!vertex_shader ? MetalDrawSkipReason::kInvalidGuestState
                                  : MetalDrawSkipReason::kResourceFailure,
                   !vertex_shader ? "no-vertex-shader" : "draw-objects-missing");
    return true;
  }
  // CEILING PROBE (re5-perf-20261015): XE_METAL_PROBE_SKIP_SMALL_RT=<pitch>
  // skips every draw whose RB_SURFACE_INFO pitch is <= that many pixels. RE5
  // renders a 128x128 cube map (6 faces + ~42 per-mip quad passes) every
  // frame; the ~48 tiny passes cost ~10 ms of GPU fixed overhead. The probe
  // measures what removing that overhead would buy; the cube content is wrong
  // while it is on. Never on by default.
  static const uint32_t s_probe_skip_small_rt = [] {
    const char* v = std::getenv("XE_METAL_PROBE_SKIP_SMALL_RT");
    return v ? uint32_t(strtoul(v, nullptr, 10)) : 0u;
  }();
  if (s_probe_skip_small_rt) {
    const uint32_t surface_pitch =
        (*register_file_)[XE_GPU_REG_RB_SURFACE_INFO] & 0x3FFFu;
    if (surface_pitch && surface_pitch <= s_probe_skip_small_rt) {
      RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect, "probe-small-rt");
      return true;
    }
  }

  // --- Gated tessellation route (port-xenios-tessellation task 4.1, design
  // D5b): selected BEFORE the geometry-emulation classification and
  // MapPrimitiveType, keyed on the exact predicate the shared
  // ::rex::gpu::PrimitiveProcessor uses (primitive_processor.cc:326-330). With the gate
  // OFF, this whole block reduces to today's behavior exactly: tessellated
  // quad lists still (mis)route into geometry emulation, patch primitives
  // still exit as prim-unmappable, tessellated triangle lists still draw as
  // plain triangles. With the gate ON, the shared processor's
  // ProcessingResult is the sole shape/host-VS-type authority (never
  // re-derived locally), and every unsupported condition is a reason-coded
  // fail-closed skip — the packet always succeeds. ---
  // implement-metal-host-tessellation (promoted 2026-09-20): tessellated
  // draws take the host route - the D3D11 reference tessellator on the CPU
  // + the ordinary vertex pipeline under the domain_as_vertex translation.
  // The MSC object/mesh emulation route was deleted at promotion.
  bool use_tessellation_emulation = false;
  ::rex::gpu::PrimitiveProcessor::ProcessingResult tess_pp{};
  {
    const RegisterFile& tess_regs = *register_file_;
    auto tess_draw_initiator = tess_regs.Get<reg::VGT_DRAW_INITIATOR>();
    bool tessellation_enabled =
        xenos::IsMajorModeExplicit(tess_draw_initiator.major_mode,
                                   prim_type) &&
        tess_regs.Get<reg::VGT_OUTPUT_PATH_CNTL>().path_select ==
            xenos::VGTOutputPath::kTessellationEnable;
    {
      // Upstream-delta census (XE_GPU_DELTA_CENSUS=1): tessellation-enabled
      // draws whose guest topology is outside the list/patch set (Canary
      // 3eab2b8b3 normalizes tessellated strips/fans). Logged regardless of
      // the local tessellation gate.
      static const bool s_delta_census =
          std::getenv("XE_GPU_DELTA_CENSUS") != nullptr;
      static const bool s_delta_selftest =
          s_delta_census &&
          std::strcmp(std::getenv("XE_GPU_DELTA_CENSUS"), "selftest") == 0;
      static uint32_t s_delta_census_lines = 0;
      if (s_delta_census && (tessellation_enabled || s_delta_selftest) &&
          prim_type != xenos::PrimitiveType::kTriangleList &&
          prim_type != xenos::PrimitiveType::kQuadList &&
          prim_type != xenos::PrimitiveType::kTrianglePatch &&
          prim_type != xenos::PrimitiveType::kQuadPatch &&
          s_delta_census_lines++ < 20000) {
        REXLOG_INFO("DeltaCensus tess_topology draw={} prim={} index_count={} vs={:016X}",
               trace_draw_index_, uint32_t(prim_type), index_count,
               vertex_shader->GetUcodeDataHash());
      }
    }
    if (tessellation_enabled && MetalTessellationGateOn() &&
        TessDrawRangeAllows(trace_draw_index_)) {
      // Tessellation + memexport is explicitly out of scope (proposal
      // non-goals / port notes gotcha 4): checked BEFORE engaging the route
      // so the draw takes a fail-closed skip — neither rendered nor exported.
      // memexport_eM_written() is an analysis product, and this route runs
      // ahead of the main path's AnalyzeUcode call — analyze here
      // (idempotent) so the first draw with a shader answers correctly.
      if (!vertex_shader->IsUcodeAnalyzed()) {
        ::rex::string::StringBuffer tess_ucode_disasm;
        vertex_shader->AnalyzeUcode(tess_ucode_disasm, std::string());
      }
      if (vertex_shader->GetMemExportEMWritten()) {
        RecordDrawSkip(MetalDrawSkipReason::kUnsupportedCapability,
                       "tess-memexport");
        return true;
      }
      if (!primitive_processor_) {
        RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                       "tess-no-primitive-processor");
        return true;
      }
      // The shared processor maps {TriangleList,QuadList} x
      // {discrete,continuous} to the CPIndexed domains and
      // TrianglePatch/QuadPatch to the PatchIndexed domains
      // (primitive_processor.cc:325-400); it FAILS for patch strips/fans,
      // unsupported mode/domain cells, and an adaptive draw without a 32-bit
      // DMA factor stream. Its RequestGuestIndexSharedMemoryRange override is
      // a no-op here, so Process performs no shared-memory upload — the
      // index/factor stream is materialized into the upload arena at encode.
      if (!primitive_processor_->Process(tess_pp)) {
        RecordDrawSkip(MetalDrawSkipReason::kTessellationUnsupportedShape,
                       "tess-process");
        return true;
      }
      if (!tess_pp.IsTessellated()) {
        // The register predicate matched but the processor did not emit a
        // domain host VS type — never expected (the predicates are
        // identical); fail closed rather than risk a double-Process below.
        RecordDrawSkip(MetalDrawSkipReason::kTessellationUnsupportedShape,
                       "tess-shape");
        return true;
      }
      // The four host primitive shapes the patch dispatch supports (XeniOS
      // :5431-5456). Tessellated triangle strips and fans arrive here as
      // triangle lists (shared processor, Canary 3eab2b8b3); every other
      // tessellated topology keeps host == guest.
      switch (tess_pp.host_primitive_type) {
        case xenos::PrimitiveType::kTriangleList:
        case xenos::PrimitiveType::kQuadList:
        case xenos::PrimitiveType::kTrianglePatch:
        case xenos::PrimitiveType::kQuadPatch:
          break;
        default:
          RecordDrawSkip(MetalDrawSkipReason::kTessellationUnsupportedShape,
                         "tess-shape");
          return true;
      }
      // Index stream shapes the arena staging serves: none (auto-indexed),
      // guest DMA, and -- for tessellated strips and fans converted to
      // triangle lists -- the host-converted per-frame pool or the built-in
      // auto fan table.
      if (tess_pp.index_buffer_type !=
              ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kNone &&
          tess_pp.index_buffer_type !=
              ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kGuestDMA &&
          tess_pp.index_buffer_type !=
              ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kHostConverted &&
          tess_pp.index_buffer_type !=
              ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::
                  kHostBuiltinForAuto) {
        RecordDrawSkip(MetalDrawSkipReason::kTessellationUnsupportedShape,
                       "tess-shape");
        return true;
      }
      // ENDIAN DECISION (design D5, task 4.3): this route reuses the
      // CPU-swap upload-arena staging every other indexed draw uses
      // (SwapIndicesInto) and keeps publishing vertex_index_endian = kNone,
      // so the prebuilt tess VS's in-shader XeEndianSwap32 is the identity.
      // Chosen over XeniOS's raw-stream + true-endian shape because it is
      // the smallest divergence from this backend's one index mechanism —
      // mixing conventions corrupts factors silently (port notes gotcha 3).
      // The pure predicate rejects the 32-bit endians the staging helper
      // cannot reproduce; the L0 endian oracle pins the round trip.
      if (tess_pp.index_buffer_type ==
              ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kGuestDMA &&
          !IsMetalTessellationIndexStreamSupported(
              tess_pp.host_index_format, tess_pp.host_shader_index_endian)) {
        RecordDrawSkip(MetalDrawSkipReason::kTessellationUnsupportedShape,
                       "tess-endian");
        return true;
      }
      // A zero-count draw is a successful no-op; never hand the IR runtime's
      // threadgroup math a zero.
      if (!tess_pp.host_draw_vertex_count) {
        RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                       "tess-degenerate");
        return true;
      }
      use_tessellation_emulation = true;
    }
  }

  // Rectangle and quad lists (fullscreen/composite surfaces) and point lists
  // (light-volume sprites — plain Metal points can't expand size/texcoords,
  // and their pipelines fail on the xespritetexcoord0 VS/PS mismatch) can't be
  // drawn directly; expand them via MSC geometry emulation, which needs a
  // mesh-shader-capable device and a pixel shader for the fragment stage.
  PipelineGeometryShader geometry_type = PipelineGeometryShader::kNone;
  // Auto-indexed quad lists on convert_auto_quads_ devices are triangle lists
  // from the shared built-in table instead (routed below).
  const bool auto_quad_route =
      convert_auto_quads_ && primitive_processor_ &&
      IsAutoQuadRoutable(*register_file_, prim_type);
  const bool dma_quad_route =
      convert_auto_quads_ && index_buffer_info &&
      index_buffer_info->guest_base &&
      IsDmaQuadRoutable(*register_file_, prim_type);
  const bool dma_line_loop_route =
      index_buffer_info && index_buffer_info->guest_base &&
      IsDmaLineLoopRoutable(*register_file_, prim_type);
  // Converted classes (2026-10-26): guest-DMA fans/loops (any reset), DMA
  // quads on converting devices, and reset-enabled strips with a custom or
  // 32-bit reset index all normalize through the shared ::rex::gpu::PrimitiveProcessor's
  // host-converted index buffer; the inline expansions above are now only
  // the fallback when the route does not engage.
  const bool converted_class_route =
      primitive_processor_ && index_buffer_info &&
      index_buffer_info->guest_base &&
      IsConvertedClassRoutable(*register_file_, prim_type,
                               convert_auto_quads_);
  // Point sprites expanded in the vertex shader (two-triangle strips, 4 host
  // vertices per point) instead of the object+mesh geometry emulation.
  const bool point_strip_route =
      prim_type == xenos::PrimitiveType::kPointList &&
      PointSpriteVsExpansionEnabled();
  // Rectangle lists the same way (rect_vs_expansion_): 4 host vertices per
  // guest rectangle, the vertex shader running the guest program for its 3
  // vertices. Cleared below for draws that only export memory.
  bool rect_strip_route =
      prim_type == xenos::PrimitiveType::kRectangleList && rect_vs_expansion_ &&
      (rect_vs_env_forced_ || !::rex::graphics::metal::GetMetalSettings().metal_rect_vs_title_off.Get());
  {
    const uint64_t vs_hash = vertex_shader->GetUcodeDataHash();
    const uint64_t ps_hash = pixel_shader ? pixel_shader->GetUcodeDataHash() : 0;
    DrawPairNote& last = draw_pair_ring_[(draw_pair_next_ - 1) % 8192];
    if (draw_pair_next_ && last.submission == submission_counter_ + 1 &&
        last.vs == vs_hash && last.ps == ps_hash) {
      ++last.count;
    } else {
      DrawPairNote& note = draw_pair_ring_[draw_pair_next_++ % 8192];
      note.submission = submission_counter_ + 1;
      note.vs = vs_hash;
      note.ps = ps_hash;
      note.count = 1;
      note.prim = uint32_t(prim_type);
      note.first_draw = draw_count_;
    }
  }
  if (prim_type == xenos::PrimitiveType::kRectangleList && !rect_strip_route) {
    geometry_type = PipelineGeometryShader::kRectangleList;
  } else if (prim_type == xenos::PrimitiveType::kPointList &&
             !point_strip_route) {
    geometry_type = PipelineGeometryShader::kPointList;
  } else if (prim_type == xenos::PrimitiveType::kQuadList &&
             !auto_quad_route && !dma_quad_route) {
    geometry_type = PipelineGeometryShader::kQuadList;
  }
  // A tessellated draw never classifies into geometry emulation (design D5b:
  // tessellated quad lists would otherwise misroute into the quad-list GS
  // path). With the gate off use_tessellation_emulation is always false and
  // this is exactly the pre-existing expression.
  draw_trace_milestone("after-shaders");
  // XE_METAL_REPEAT_DRAW_CENSUS=1 (diagnostic): how many draws repeat the
  // previous draw's texture inputs -- the same shader pair, and no fetch
  // constant either shader binds rewritten since -- and how many of those
  // also have no pending GPU producer (resolve writeback or memexport) that
  // could change what a texture serves. Those draws are the ceiling of a
  // per-draw texture-binding reuse (Burnout: ~7,700 draws a frame, ~20% of
  // the command-processor thread in per-draw texture work, 2026-10-19).
  {
    static const bool s_repeat_census =
        std::getenv("XE_METAL_REPEAT_DRAW_CENSUS") != nullptr;
    if (s_repeat_census) {
      static const void* s_prev_vs = nullptr;
      static const void* s_prev_ps = nullptr;
      static uint64_t s_draws = 0, s_same_shaders = 0, s_repeat = 0,
                      s_repeat_quiet = 0, s_textured = 0;
      uint32_t bound_mask = 0;
      for (MetalShader* shader : {vertex_shader, pixel_shader}) {
        if (!shader) {
          continue;
        }
        for (const auto& binding : shader->GetTextureBindingsAfterTranslation()) {
          if (binding.fetch_constant < 32) {
            bound_mask |= 1u << binding.fetch_constant;
          }
        }
      }
      ++s_draws;
      if (bound_mask) {
        ++s_textured;
      }
      if (vertex_shader == s_prev_vs && pixel_shader == s_prev_ps) {
        ++s_same_shaders;
        if (bound_mask && !(fetch_constant_dirty_mask_ & bound_mask)) {
          ++s_repeat;
          if (pending_writebacks_.empty() && pending_memexports_.empty()) {
            ++s_repeat_quiet;
          }
        }
      }
      s_prev_vs = vertex_shader;
      s_prev_ps = pixel_shader;
      if ((s_draws & 65535) == 0) {
        REXLOG_INFO(
            "MetalRepeatDrawCensus draws={} textured={:.1f}% same-shaders="
            "{:.1f}% textured-repeat={:.1f}% repeat-without-pending="
            "{:.1f}%",
            s_draws, 100.0 * double(s_textured) / double(s_draws),
            100.0 * double(s_same_shaders) / double(s_draws),
            100.0 * double(s_repeat) / double(s_draws),
            100.0 * double(s_repeat_quiet) / double(s_draws));
      }
      // v2: per binding, are the slot's six fetch words unchanged since the
      // slot was last bound, and is the producer state (authority sequence,
      // pending writeback/memexport counts) unchanged since then? That pair
      // is the ceiling of a per-slot memo of the texture phase.
      {
        struct SlotSeen {
          uint32_t words[6];
          uint64_t sequence;
          size_t writebacks, memexports;
          bool valid;
        };
        static SlotSeen s_seen[32] = {};
        static uint64_t s_bindings = 0, s_same_words = 0, s_same_all = 0,
                        s_draws_tex = 0, s_draws_all = 0;
        bool draw_all = bound_mask != 0;
        for (uint32_t slot = 0; slot < 32; ++slot) {
          if (!(bound_mask & (1u << slot))) {
            continue;
          }
          const uint32_t* w =
              &register_file_->values[XE_GPU_REG_SHADER_CONSTANT_FETCH_00_0 +
                                      slot * 6];
          SlotSeen& seen = s_seen[slot];
          ++s_bindings;
          const bool same_words =
              seen.valid && std::memcmp(seen.words, w, sizeof(seen.words)) == 0;
          const bool same_state =
              seen.valid && seen.sequence == memory_authority_sequence_ &&
              seen.writebacks == pending_writebacks_.size() &&
              seen.memexports == pending_memexports_.size();
          s_same_words += same_words;
          s_same_all += same_words && same_state;
          draw_all = draw_all && same_words && same_state;
          std::memcpy(seen.words, w, sizeof(seen.words));
          seen.sequence = memory_authority_sequence_;
          seen.writebacks = pending_writebacks_.size();
          seen.memexports = pending_memexports_.size();
          seen.valid = true;
        }
        s_draws_tex += bound_mask != 0;
        s_draws_all += draw_all;
        if ((s_draws & 65535) == 0 && s_bindings) {
          REXLOG_INFO(
              "MetalSlotReuseCensus bindings={} same-words={:.1f}% "
              "same-words+producers={:.1f}% | textured draws all-reusable="
              "{:.1f}%",
              s_bindings, 100.0 * double(s_same_words) / double(s_bindings),
              100.0 * double(s_same_all) / double(s_bindings),
              s_draws_tex ? 100.0 * double(s_draws_all) / double(s_draws_tex)
                          : 0.0);
        }
      }
    }
  }
  // Diagnostic (XE_METAL_DRAW_LIST=<first>-<last>): one line per draw in the
  // range (as XE_METAL_DRAW_TRACE counts) with its shaders and depth state,
  // for finding which draws of a replayed frame make up a pass.
  {
    static const std::pair<int64_t, int64_t> s_draw_list = [] {
      const char* v = std::getenv("XE_METAL_DRAW_LIST");
      if (!v) {
        return std::pair<int64_t, int64_t>(-1, -2);
      }
      char* end;
      int64_t first = strtoll(v, &end, 10);
      int64_t last = *end == '-' ? strtoll(end + 1, nullptr, 10) : first;
      return std::pair<int64_t, int64_t>(first, last);
    }();
    const int64_t draw = int64_t(trace_draw_index_) - 1;
    if (draw >= s_draw_list.first && draw <= s_draw_list.second) {
      REXLOG_WARN("MetalDrawList draw={} prim={} count={} vs={:016X} ps={:016X} "
             "depthcontrol={:08X} color_mask={:08X} colorcontrol={:08X} "
             "window_offset={:08X} su_sc_mode={:08X} ps_rts={:X} ps_kill={} "
             "ps_depth={} blend0={:08X} stencilrefmask={:08X}",
             draw, uint32_t(prim_type), index_count,
             vertex_shader ? vertex_shader->GetUcodeDataHash() : 0ull,
             pixel_shader ? pixel_shader->GetUcodeDataHash() : 0ull,
             (*register_file_)[XE_GPU_REG_RB_DEPTHCONTROL],
             (*register_file_)[XE_GPU_REG_RB_COLOR_MASK],
             (*register_file_)[XE_GPU_REG_RB_COLORCONTROL],
             (*register_file_)[XE_GPU_REG_PA_SC_WINDOW_OFFSET],
             (*register_file_)[XE_GPU_REG_PA_SU_SC_MODE_CNTL],
             pixel_shader ? pixel_shader->GetWritesColorTargets() : 0u,
             pixel_shader && pixel_shader->DoesKillPixels() ? 1 : 0,
             pixel_shader && pixel_shader->IsDepthWritten() ? 1 : 0,
             (*register_file_)[XE_GPU_REG_RB_BLENDCONTROL0],
             (*register_file_)[XE_GPU_REG_RB_STENCILREFMASK]);
    }
  }
  static const char* const s_draw_trace_env =
      std::getenv("XE_METAL_DRAW_TRACE");
  if (s_draw_trace_env &&
      int64_t(trace_draw_index_) - 1 ==
          strtoll(s_draw_trace_env, nullptr, 10)) {
    REXLOG_WARN("MetalDrawTrace shaders draw={} vs={:016X} ps={:016X}",
           trace_draw_index_ - 1,
           vertex_shader ? vertex_shader->GetUcodeDataHash() : 0ull,
           pixel_shader ? pixel_shader->GetUcodeDataHash() : 0ull);
    REXLOG_WARN("MetalDrawTrace   window_offset={:08X} window_scissor_tl={:08X} "
           "br={:08X} screen_scissor_tl={:08X} br={:08X} surface_info={:08X} "
           "depth_info={:08X} vte={:08X} su_sc_mode={:08X}",
           (*register_file_)[XE_GPU_REG_PA_SC_WINDOW_OFFSET],
           (*register_file_)[XE_GPU_REG_PA_SC_WINDOW_SCISSOR_TL],
           (*register_file_)[XE_GPU_REG_PA_SC_WINDOW_SCISSOR_BR],
           (*register_file_)[XE_GPU_REG_PA_SC_SCREEN_SCISSOR_TL],
           (*register_file_)[XE_GPU_REG_PA_SC_SCREEN_SCISSOR_BR],
           (*register_file_)[XE_GPU_REG_RB_SURFACE_INFO],
           (*register_file_)[XE_GPU_REG_RB_DEPTH_INFO],
           (*register_file_)[XE_GPU_REG_PA_CL_VTE_CNTL],
           (*register_file_)[XE_GPU_REG_PA_SU_SC_MODE_CNTL]);
    REXLOG_WARN("MetalDrawTrace   depthcontrol={:08X} stencilrefmask={:08X} "
           "colorcontrol={:08X} modecontrol={:08X} color_mask={:08X} "
           "vport z scale={} offset={} clip_cntl={:08X}",
           (*register_file_)[XE_GPU_REG_RB_DEPTHCONTROL],
           (*register_file_)[XE_GPU_REG_RB_STENCILREFMASK],
           (*register_file_)[XE_GPU_REG_RB_COLORCONTROL],
           (*register_file_)[XE_GPU_REG_RB_MODECONTROL],
           (*register_file_)[XE_GPU_REG_RB_COLOR_MASK],
           register_file_->Get<float>(XE_GPU_REG_PA_CL_VPORT_ZSCALE),
           register_file_->Get<float>(XE_GPU_REG_PA_CL_VPORT_ZOFFSET),
           (*register_file_)[XE_GPU_REG_PA_CL_CLIP_CNTL]);
    REXLOG_WARN("MetalDrawTrace   sq_program_cntl={:08X} sq_context_misc={:08X} "
           "vs_writes_interp={:X} ps_interp_mask={:X}",
           (*register_file_)[XE_GPU_REG_SQ_PROGRAM_CNTL],
           (*register_file_)[XE_GPU_REG_SQ_CONTEXT_MISC],
           vertex_shader ? vertex_shader->GetWritesInterpolators() : 0u,
           pixel_shader ? [&] {
             uint32_t pgp = UINT32_MAX;
             return pixel_shader->GetInterpolatorInputMask(
                 register_file_->Get<reg::SQ_PROGRAM_CNTL>(),
                 register_file_->Get<reg::SQ_CONTEXT_MISC>(), pgp);
           }() : 0u);
    for (uint32_t c : {0u, 23u, 132u, 254u, 255u}) {
      uint32_t r = XE_GPU_REG_SHADER_CONSTANT_256_X + c * 4;
      REXLOG_WARN("MetalDrawTrace   ps c{} = ({}, {}, {}, {})", c,
             register_file_->Get<float>(r), register_file_->Get<float>(r + 1),
             register_file_->Get<float>(r + 2),
             register_file_->Get<float>(r + 3));
    }
    // Every float constant the pixel shader actually reads (bounded).
    if (pixel_shader) {
      const auto& pmap = pixel_shader->GetConstantRegisterMap();
      uint32_t printed = 0;
      for (uint32_t i = 0; i < rex::countof(pmap.float_bitmap) && printed < 48;
           ++i) {
        uint64_t bits = pmap.float_bitmap[i];
        while (bits && printed < 48) {
          uint32_t j = uint32_t(rex::tzcnt(bits));
          bits &= bits - 1;
          uint32_t c = i * 64 + j;
          uint32_t r = XE_GPU_REG_SHADER_CONSTANT_256_X + c * 4;
          REXLOG_WARN("MetalDrawTrace   ps uses c{} = ({}, {}, {}, {}) [{:08X} {:08X} {:08X} {:08X}]",
                 c, register_file_->Get<float>(r),
                 register_file_->Get<float>(r + 1),
                 register_file_->Get<float>(r + 2),
                 register_file_->Get<float>(r + 3), (*register_file_)[r],
                 (*register_file_)[r + 1], (*register_file_)[r + 2],
                 (*register_file_)[r + 3]);
          ++printed;
        }
      }
    }
    if (pixel_shader) {
      for (const auto& binding :
           pixel_shader->GetTextureBindingsAfterTranslation()) {
        auto f = register_file_->GetTextureFetch(binding.fetch_constant);
        REXLOG_WARN("MetalDrawTrace   ps fetch fc={} base={:08X} fmt={} {}x{} "
               "dim={} tiled={} endian={} swz={:03X} pitch={}",
               binding.fetch_constant, f.base_address << 12,
               uint32_t(f.format), f.size_2d.width + 1, f.size_2d.height + 1,
               uint32_t(f.dimension), uint32_t(f.tiled),
               uint32_t(f.endianness), f.swizzle & 0xFFF, f.pitch << 5);
        REXLOG_WARN("MetalDrawTrace     sampler clamp=({},{},{}) mag={} min={} "
               "mip={} aniso={} border={} mip_min={} mip_max={} lod_bias={} "
               "num_format={} sign_x={} exp_adjust={}",
               uint32_t(f.clamp_x), uint32_t(f.clamp_y), uint32_t(f.clamp_z),
               uint32_t(f.mag_filter), uint32_t(f.min_filter),
               uint32_t(f.mip_filter), uint32_t(f.aniso_filter),
               uint32_t(f.border_color), uint32_t(uint32_t(f.mip_min_level)),
               uint32_t(uint32_t(f.mip_max_level)), int32_t(f.lod_bias),
               uint32_t(f.num_format), uint32_t(f.sign_x),
               int32_t(f.exp_adjust));
      }
      // Pixel-shader vertex fetches (vfetch in a PS: per-pixel indexed
      // buffer reads through the fetch constants, RotTR's dynamic-weight
      // skinning pass).
      for (const auto& vb : pixel_shader->GetVertexBindings()) {
        xenos::VertexFetch vf =
            register_file_->GetVertexFetch(vb.fetch_constant);
        REXLOG_WARN("MetalDrawTrace   ps vfetch fc={} addr={:08X} size_dw={} "
               "endian={} stride_dw={} type={}",
               vb.fetch_constant, vf.address << 2, uint32_t(vf.size),
               uint32_t(vf.endian), vb.stride_words, uint32_t(vf.type));
      }
    }
  }
  // XE_METAL_DISABLE_GEO_TYPES=<mask> (diagnostic): bit 1 point lists, bit 2
  // rectangle lists, bit 3 quad lists take the non-mesh fallback instead of
  // the object+mesh geometry emulation (bisecting the 2026-10-18 M1 Max
  // command-buffer faults by primitive type).
  static const uint32_t s_disable_geometry_types = [] {
    const char* v = std::getenv("XE_METAL_DISABLE_GEO_TYPES");
    return v ? uint32_t(strtoul(v, nullptr, 0)) : 0u;
  }();
  bool use_geometry_emulation =
      !use_tessellation_emulation &&
      geometry_type != PipelineGeometryShader::kNone &&
      mesh_shader_supported_ && pixel_shader != nullptr &&
      !(s_disable_geometry_types & (1u << uint32_t(geometry_type)));

  RegisterFile& regs = *register_file_;
  // PP3-auto line loops are intentionally absent from the guest primitive
  // mapping: they must first normalize through the shared ::rex::gpu::PrimitiveProcessor
  // to the already-mapped host kLineStrip topology.
  bool auto_line_loop_route = IsAutoLineLoopRoutable(regs, prim_type);
  // PP4: enabled 16-bit DMA strips whose reset value already equals Metal's
  // fixed 0xFFFF sentinel need normalization fields only, never conversion.
  bool fixed_reset_strip_route = IsFixedResetStripRoutable(regs, prim_type);
  // A skipped draw is not an error (the base loop treats false as failure); we
  // return true and just render nothing so the game keeps advancing.
  MTLPrimitiveType mtl_prim = MTLPrimitiveTypeTriangle;
  // Tessellated draws bypass the host primitive mapping: patch primitives
  // have no MTLPrimitiveType — the IR runtime's patch dispatch owns the
  // topology (task 4.4).
  if (!use_tessellation_emulation && !use_geometry_emulation &&
      !auto_line_loop_route && !auto_quad_route && !dma_quad_route &&
      !dma_line_loop_route && !converted_class_route && !rect_strip_route &&
      !MapPrimitiveType(prim_type, &mtl_prim)) {
    ++prim_census_[uint32_t(prim_type) & 31][6];
    RecordDrawSkip(MetalDrawSkipReason::kUnsupportedCapability,
                   "prim-unmappable");
    return true;
  }
  ++prim_census_[uint32_t(prim_type) & 31]
                [use_tessellation_emulation ? 5
                 : use_geometry_emulation   ? 4
                 : auto_line_loop_route || dma_line_loop_route ||
                           (converted_class_route &&
                            prim_type == xenos::PrimitiveType::kLineLoop)
                                            ? 3
                 : dma_quad_route           ? 2
                 : auto_quad_route          ? 1
                                            : 0];

  if (!AreMetalConstantBankBasesSupported(regs[XE_GPU_REG_SQ_VS_CONST],
                                          regs[XE_GPU_REG_SQ_PS_CONST])) {
    static uint32_t invalid_constant_bank_logs = 0;
    if (invalid_constant_bank_logs++ < 16) {
      REXLOG_WARN("MetalCommandProcessor: skipping draw with unsupported constant "
             "banks VS={:08X} PS={:08X}",
             regs[XE_GPU_REG_SQ_VS_CONST], regs[XE_GPU_REG_SQ_PS_CONST]);
    }
    RecordDrawSkip(MetalDrawSkipReason::kUnsupportedCapability,
                   "constant-banks");
    return true;
  }

  // Analyze microcode (once) so constant maps / bindings are available.
  // The disassembly buffer mallocs 16 KiB on construction: build it only for
  // a shader's first draw (it used to be built and freed on every draw).
  if (!vertex_shader->IsUcodeAnalyzed() ||
      (pixel_shader && !pixel_shader->IsUcodeAnalyzed())) {
    ::rex::string::StringBuffer ucode_disasm;
    if (!vertex_shader->IsUcodeAnalyzed()) {
      vertex_shader->AnalyzeUcode(ucode_disasm, std::string());
    }
    if (pixel_shader && !pixel_shader->IsUcodeAnalyzed()) {
      pixel_shader->AnalyzeUcode(ucode_disasm, std::string());
    }
  }
  // The D3D12/Vulkan raster gate: no rasterization in kNoOperation, with a
  // multipass vertex shader export mode, a zero surface pitch or both faces
  // culled. Such a draw has no effect unless its vertex shader exports to
  // memory (those keep today's path, which routes the exports).
  if (!::rex::gpu::draw_state::IsRasterizationPotentiallyDone(
          regs, ::rex::gpu::draw_state::IsPrimitivePolygonal(regs)) &&
      !vertex_shader->GetMemExportEMWritten()) {
    RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect, "no-rasterization");
    return true;
  }
  // The D3D12/Vulkan rule: the pixel shader runs only in kColorDepth and when
  // it has an effect (colour written, kill, depth or memexport, or coverage
  // from alpha); depth-only passes (shadow maps, depth pre-passes, depth
  // clears in kDepth) draw with no fragment function, no interpolators and
  // no pixel-shader textures. The normalized colour mask is already 0 for
  // every such draw. XE_METAL_PS_DROP=0 keeps the pixel shader bound.
  // Corpus: 40/40 traces 0 px; RDR 15297 moves 34 EDRAM bytes by 1-3 LSB at
  // a 2x-MSAA draw after kDepth occlusion-style draws lose their fragment
  // function (which wrote [[sample_mask]] = ~0) - the M4 MSAA LSB class, not
  // a semantic change.
  static const bool s_ps_drop = [] {
    const char* value = std::getenv("XE_METAL_PS_DROP");
    return !value || std::strcmp(value, "0") != 0;
  }();
  // Geometry-emulation draws keep theirs (that route was selected above with
  // the pixel shader present), and so do rectangle lists expanded in the
  // vertex shader in its place: the MSAA clear fold matches the clear's
  // shader pair, and without the pixel shader no clear folded on the 580X
  // (Gears 3 19.4 fps there vs 30 on the RX 6900 XT, 2026-11-03).
  if (s_ps_drop && pixel_shader && !use_geometry_emulation &&
      !rect_strip_route &&
      !::rex::gpu::draw_state::IsPixelShaderNeededWithRasterization(*pixel_shader, regs)) {
    pixel_shader = nullptr;
  }
  // Attribution bound (XE_METAL_DIAG_PS_NULL=1, never for play): drop EVERY
  // pixel shader without side effects (no kill, depth output or memexport),
  // so the draw rasterizes depth only. GPU busy with it on is the ceiling the
  // translated pixel shaders' ALU, texture and colour-write work could buy.
  // Classes (the value): 1 = every such shader; 2 = only shaders with dynamic
  // register addressing; 3 = only shaders with >= 6 texture bindings; 4 =
  // only shaders of >= 512 ucode dwords; 5 = only shaders whose static
  // register bound is >= 32; 6 = the hash buckets or hashes below. The
  // complement of a class's gain is what the rest costs.
  static const uint32_t s_diag_ps_null = [] {
    const char* v = std::getenv("XE_METAL_DIAG_PS_NULL");
    return v ? uint32_t(strtoul(v, nullptr, 10)) : 0u;
  }();
  if (s_diag_ps_null && pixel_shader && !use_geometry_emulation &&
      !pixel_shader->DoesKillPixels() && !pixel_shader->IsDepthWritten() &&
      !pixel_shader->GetMemExportEMWritten()) {
    bool in_class = true;
    switch (s_diag_ps_null) {
      case 2:
        in_class = pixel_shader->HasRegisterDynamicAddressing();
        break;
      case 3:
        in_class = pixel_shader->GetTextureBindings().size() >= 6;
        break;
      case 4:
        in_class = pixel_shader->GetUcodeDwordCount() >= 512;
        break;
      case 5:
        in_class = pixel_shader->GetRegisterStaticAddressBound() >= 32;
        break;
      case 6:
        // Hash buckets for bisecting: XE_METAL_DIAG_PS_NULL_BUCKET=k/n drops
        // the shaders whose ucode hash is k mod n; XE_METAL_DIAG_PS_NULL_HASH
        // (comma-separated hex) drops exactly those.
        {
          static const std::pair<uint64_t, uint64_t> s_bucket = [] {
            const char* v = std::getenv("XE_METAL_DIAG_PS_NULL_BUCKET");
            uint64_t k = 0, n = 0;
            if (v) {
              char* end = nullptr;
              k = strtoull(v, &end, 10);
              if (end && *end == '/') n = strtoull(end + 1, nullptr, 10);
            }
            return std::make_pair(k, n);
          }();
          static const std::unordered_set<uint64_t> s_hashes = [] {
            std::unordered_set<uint64_t> hashes;
            const char* v = std::getenv("XE_METAL_DIAG_PS_NULL_HASH");
            while (v && *v) {
              char* end = nullptr;
              hashes.insert(strtoull(v, &end, 16));
              v = (end && *end == ',') ? end + 1 : nullptr;
            }
            return hashes;
          }();
          uint64_t hash = pixel_shader->GetUcodeDataHash();
          in_class = (s_bucket.second &&
                      hash % s_bucket.second == s_bucket.first) ||
                     s_hashes.count(hash) != 0;
        }
        break;
      default:
        break;
    }
    if (in_class) {
      pixel_shader = nullptr;
    }
  }
  // XE_METAL_PS_CLASS_CENSUS=1: one line per distinct pixel shader (bounded)
  // with the class fields above, to size the classes.
  static const bool s_ps_class_census =
      std::getenv("XE_METAL_PS_CLASS_CENSUS") != nullptr;
  if (s_ps_class_census && pixel_shader) {
    static std::unordered_set<uint64_t> s_seen;
    if (s_seen.size() < 2048 &&
        s_seen.insert(pixel_shader->GetUcodeDataHash()).second) {
      REXLOG_INFO("MetalPsClass ps={:016X} dyn={} fetches={} dwords={} regs={} "
             "kill={} depth={} memexport={}",
             pixel_shader->GetUcodeDataHash(),
             pixel_shader->HasRegisterDynamicAddressing() ? 1 : 0,
             pixel_shader->GetTextureBindings().size(),
             pixel_shader->GetUcodeDwordCount(),
             pixel_shader->GetRegisterStaticAddressBound(),
             pixel_shader->DoesKillPixels() ? 1 : 0,
             pixel_shader->IsDepthWritten() ? 1 : 0,
             pixel_shader->GetMemExportEMWritten() ? 1 : 0);
    }
    // Draw counts per shader, the top 24 logged every 2^20 draws.
    static std::unordered_map<uint64_t, uint64_t> s_draws;
    static uint64_t s_total = 0;
    ++s_draws[pixel_shader->GetUcodeDataHash()];
    if ((++s_total & ((1u << 20) - 1)) == 0) {
      std::vector<std::pair<uint64_t, uint64_t>> top(s_draws.begin(),
                                                     s_draws.end());
      std::sort(top.begin(), top.end(),
                [](const auto& a, const auto& b) { return a.second > b.second; });
      top.resize(std::min<size_t>(top.size(), 24));
      std::string line;
      for (const auto& [hash, count] : top) {
        line += fmt::format(" {:016X}:{:.2f}", hash, double(count) / s_total);
      }
      REXLOG_INFO("MetalPsDraws total={}{}", s_total, line);
    }
  }
  // Diagnostic: XE_METAL_DUMP_PS=<hex ucode hash> writes that pixel shader's
  // ucode disassembly to /tmp/xe_ps_<hash>.txt once, for single-shader
  // forensics (what inputs drive the color output).
  static const char* const s_dump_ps_env = std::getenv("XE_METAL_DUMP_PS");
  if (const char* dump_ps = s_dump_ps_env) {
    uint64_t dump_hash = strtoull(dump_ps, nullptr, 16);
    // Matches the PS hash OR the VS hash (several VSes share one PS).
    if ((pixel_shader && pixel_shader->GetUcodeDataHash() == dump_hash) ||
        vertex_shader->GetUcodeDataHash() == dump_hash) {
      static bool s_dumped = false;
      if (!s_dumped) {
        s_dumped = true;
        auto write_disasm = [](const char* kind, uint64_t hash,
                               const std::string& text) {
          std::string path = fmt::format("/tmp/xe_{}_{:016X}.txt", kind, hash);
          FILE* f = fopen(path.c_str(), "w");
          if (f) {
            fwrite(text.data(), 1, text.size(), f);
            fclose(f);
            REXLOG_INFO("MetalCommandProcessor: dumped {} disasm to {}", kind, path);
          }
        };
        write_disasm("ps", pixel_shader->GetUcodeDataHash(),
                     pixel_shader->GetUcodeDisassembly());
        // The paired vertex shader (feeds the PS's interpolators).
        write_disasm("vs", vertex_shader->GetUcodeDataHash(),
                     vertex_shader->GetUcodeDisassembly());
        // Raw ucode words too — the shader-executor harness's input.
        auto write_ucode = [](const char* kind, uint64_t hash,
                              const std::vector<uint32_t>& words) {
          std::string path =
              fmt::format("/tmp/xe_{}_{:016X}.ucode.bin", kind, hash);
          FILE* f = fopen(path.c_str(), "wb");
          if (f) {
            fwrite(words.data(), sizeof(uint32_t), words.size(), f);
            fclose(f);
            REXLOG_INFO("MetalCommandProcessor: dumped {} ucode ({} words) to {}",
                   kind, words.size(), path);
          }
        };
        if (pixel_shader) {
          write_ucode("ps", pixel_shader->GetUcodeDataHash(),
                      pixel_shader->GetUcodeData());
        }
        write_ucode("vs", vertex_shader->GetUcodeDataHash(),
                    vertex_shader->GetUcodeData());
      }
    }
  }

  // --- Guest render-target binding. The normalized color mask folds
  // RB_MODECONTROL + RB_COLOR_MASK + the PS's static writes; each enabled
  // color slot's EDRAM base/format and RB_DEPTH_INFO key the per-target views
  // in the RT cache. ---
  uint32_t normalized_color_mask =
      pixel_shader ? ::rex::gpu::draw_state::GetNormalizedColorMask(
                         regs, pixel_shader->GetWritesColorTargets())
                   : 0;
  reg::RB_DEPTHCONTROL norm_depth = ::rex::gpu::draw_state::GetNormalizedDepthControl(regs);
  bool depth_bound = norm_depth.z_enable || norm_depth.stencil_enable;
  auto rb_depth_info = regs.Get<reg::RB_DEPTH_INFO>();
  // MSAA fast-clear fold (metal_msaa_clear_fold.h): a qualifying runtime
  // clear is presented to the rest of the draw as a 1x draw over the same
  // tiles (RB_SURFACE_INFO rewritten for this draw only, restored on every
  // exit path) with screen coordinates scaled into the 1x view.
  // Default on (promoted 2026-10-01: Gears 3 18.4 -> 30.0 fps, corpus 60/60
  // 0 px); the ::rex::graphics::metal::GetMetalSettings().metal_msaa_clear_fold.Get() option or XE_METAL_MSAA_CLEAR_FOLD=0 is
  // the exact rollback.
  // XE_METAL_MSAA_CLEAR_FOLD_LOG=1 reports folded/refused counts per swap.
  uint32_t msaa_fold_scale_x = 1, msaa_fold_scale_y = 1;
  // Folded depth clears pin their depth (NDC z = this, z scale 0) to the value
  // the replaced canonical transfer would leave in the 1x view.
  bool msaa_fold_pin_depth = false;
  float msaa_fold_pin_ndc_z = 0.0f;
  struct MsaaFoldSurfaceRestore {
    RegisterFile* regs = nullptr;
    ::rex::gpu::RenderTargetCache* render_target_cache = nullptr;
    uint32_t saved = 0;
    // A depth clear drawn into the colour view also rewrites these.
    uint32_t colour_alias_count = 0;
    std::array<std::pair<uint32_t, uint32_t>, 4> colour_alias_saved{};
    ~MsaaFoldSurfaceRestore() {
      if (regs) {
        regs->values[XE_GPU_REG_RB_SURFACE_INFO] = saved;
        for (uint32_t i = 0; i < colour_alias_count; ++i) {
          regs->values[colour_alias_saved[i].first] =
              colour_alias_saved[i].second;
        }
      }
      if (render_target_cache) {
        render_target_cache->SetDrawExtentYScale(1);
      }
    }
  } msaa_fold_restore;
  {
    static const bool s_fold_enabled = metal::MetalSwitchEnabled(
        ::rex::graphics::metal::GetMetalSettings().metal_msaa_clear_fold.Get(), std::getenv("XE_METAL_MSAA_CLEAR_FOLD"));
    static const bool s_fold_log =
        std::getenv("XE_METAL_MSAA_CLEAR_FOLD_LOG") != nullptr;
    // Depth clears into the colour view of the same tiles
    // (QualifyMsaaDepthClearColourFold): default on with the fold;
    // XE_METAL_DEPTH_CLEAR_COLOR_FOLD=0 rolls back to the transfer path
    // (2026-11-03: Iron Man's title and menus 39-45 -> 60 fps on the M1 Max).
    static const bool s_colour_fold_enabled =
        s_fold_enabled && metal::ParseMetalEnvironmentFlag(
                              std::getenv("XE_METAL_DEPTH_CLEAR_COLOR_FOLD"),
                              /*default_enabled=*/true);
    if (s_fold_enabled || s_fold_log) {
      const uint64_t fold_vs_hash =
          vertex_shader ? vertex_shader->GetUcodeDataHash() : 0;
      const uint64_t fold_ps_hash =
          pixel_shader ? pixel_shader->GetUcodeDataHash() : 0;
      // A depth clear over the colour target's own tiles is drawn into the
      // colour view; anything it refuses tries the ordinary fold.
      // Not inside an occlusion query: those count the depth clear's
      // samples against its own state.
      metal::MsaaClearFoldDecision fold;
      if (s_colour_fold_enabled && !zpd_active_segment_.logical_active) {
        fold = metal::QualifyMsaaDepthClearColourFold(
            regs, fold_vs_hash, fold_ps_hash, prim_type, index_count,
            norm_depth, normalized_color_mask);
      }
      bool colour_alias = fold.fold();
      if (!colour_alias) {
        fold = metal::QualifyMsaaClearFold(regs, fold_vs_hash, fold_ps_hash,
                                           prim_type, index_count, norm_depth,
                                           normalized_color_mask);
      }
      if (s_fold_log &&
          fold.refusal == metal::MsaaClearFoldRefusal::kShaderPair &&
          prim_type == xenos::PrimitiveType::kRectangleList &&
          index_count == 3) {
        static uint32_t s_pair_logs = 0;
        if (s_pair_logs < 24) {
          ++s_pair_logs;
          REXLOG_INFO("MetalMsaaClearFold shader-pair rect draw={} vs={:016X} "
                 "ps={:016X} msaa={}",
                 trace_draw_index_, fold_vs_hash, fold_ps_hash,
                 uint32_t(regs.Get<reg::RB_SURFACE_INFO>().msaa_samples));
        }
      }
      // Value invariance, edge alignment and the depth the transfer path
      // would leave (design D3): evaluate the clear's vertices on the CPU.
      if (fold.fold()) {
        if (!msaa_fold_interpreter_) {
          msaa_fold_interpreter_ =
              std::make_unique<::rex::gpu::ShaderInterpreter>(*register_file_, *&physical_memory_);
        }
        metal::MsaaClearFoldVertices vertices;
        if (!vertex_shader ||
            !metal::EvaluateMsaaClearFoldVertices(
                regs, *msaa_fold_interpreter_, *vertex_shader, vertices)) {
          fold.refusal = metal::MsaaClearFoldRefusal::kVertexEvaluation;
        } else {
          switch (metal::CheckMsaaClearFoldValues(
              regs, vertices, normalized_color_mask != 0 || colour_alias,
              false)) {
            case metal::MsaaClearFoldValueRefusal::kNone:
              break;
            case metal::MsaaClearFoldValueRefusal::kVertexEvaluation:
              fold.refusal = metal::MsaaClearFoldRefusal::kVertexEvaluation;
              break;
            case metal::MsaaClearFoldValueRefusal::kHomogeneousW:
              fold.refusal = metal::MsaaClearFoldRefusal::kHomogeneousW;
              break;
            case metal::MsaaClearFoldValueRefusal::kDepthVaries:
              fold.refusal = metal::MsaaClearFoldRefusal::kDepthVaries;
              break;
            case metal::MsaaClearFoldValueRefusal::kColourVaries:
              fold.refusal = metal::MsaaClearFoldRefusal::kColourVaries;
              break;
            case metal::MsaaClearFoldValueRefusal::kEdgeAlignment:
              fold.refusal = metal::MsaaClearFoldRefusal::kEdgeAlignment;
              break;
          }
        }
        if (fold.fold() && norm_depth.z_enable && norm_depth.z_write_enable) {
          // Host depth the MSAA clear would rasterize: only the plain
          // mapping (NDC z scale 1, offset 0, viewport z [0, 1] or [0, 0.5]
          // for float24) is reproduced exactly on the CPU.
          draw_util::ViewportInfo fold_viewport;
          draw_util::GetViewportInfoArgs fold_vp_args = GetMetalViewportInfoArgs(
              regs, norm_depth, pixel_shader && pixel_shader->IsDepthWritten(),
              (1u << fold.scale_x_log2) * draw_resolution_scale_x_,
              (1u << fold.scale_y_log2) * draw_resolution_scale_y_,
              draw_resolution_scale_x_, draw_resolution_scale_y_);
          draw_util::GetHostViewportInfo(&fold_vp_args, GetXenosSettings(), fold_viewport);
          if (fold_viewport.ndc_scale[2] != 1.0f ||
              fold_viewport.ndc_offset[2] != 0.0f ||
              fold_viewport.z_min != 0.0f ||
              (fold_viewport.z_max != 1.0f && fold_viewport.z_max != 0.5f) ||
              (pixel_shader && pixel_shader->IsDepthWritten())) {
            fold.refusal = metal::MsaaClearFoldRefusal::kDepthRange;
          } else if (colour_alias) {
            // The word the transfer path would carry into the colour view
            // (depth pack of the rasterized depth, stencil REPLACE) must be
            // the k_8_8_8_8 word of the colour the pass-through PS writes.
            // Out of [0, 1] the host clamps only with clipping off (as the
            // depth pack saturates); with clipping on the clear is clipped.
            float host_depth = vertices.position[0][2] * fold_viewport.z_max;
            const bool depth_clamped =
                regs.Get<reg::PA_CL_CLIP_CNTL>().clip_disable ||
                ::rex::graphics::metal::GetMetalSettings().force_depth_clamp.Get();
            uint32_t colour_word = 0;
            const uint32_t depth_word = metal::MsaaClearFoldD24S8Word(
                host_depth, regs.Get<reg::RB_STENCILREFMASK>().stencilref);
            const bool colour_exact = metal::MsaaClearFoldColour8888Word(
                vertices.interpolator0[0], colour_word);
            if (!(depth_clamped ||
                  (host_depth >= 0.0f && host_depth <= 1.0f)) ||
                !colour_exact || colour_word != depth_word) {
              fold.refusal = metal::MsaaClearFoldRefusal::kWordMismatch;
              static uint32_t s_mismatch_logs = 0;
              if (s_fold_log && s_mismatch_logs < 16) {
                ++s_mismatch_logs;
                REXLOG_INFO(
                    "MetalMsaaClearFold word-mismatch draw={} depth={} "
                    "word={:08X} colour=({}, {}, {}, {}) exact={} "
                    "word={:08X} clamped={}",
                    uint32_t(trace_draw_index_), host_depth, depth_word,
                    vertices.interpolator0[0][0], vertices.interpolator0[0][1],
                    vertices.interpolator0[0][2], vertices.interpolator0[0][3],
                    colour_exact, colour_word, depth_clamped);
              }
            }
          } else {
            float host_depth = vertices.position[0][2] * fold_viewport.z_max;
            float transferred = render_target_cache_->CanonicalDepthTransferResult(
                host_depth, rb_depth_info.depth_format);
            msaa_fold_pin_depth = true;
            msaa_fold_pin_ndc_z = transferred / fold_viewport.z_max;
          }
        }
      }
      // Census over the runtime clear pair only (other draws are not
      // candidates and would drown the refusal reasons).
      if (fold.refusal != metal::MsaaClearFoldRefusal::kShaderPair) {
        ++msaa_fold_census_[uint32_t(fold.refusal)];
        msaa_fold_colour_alias_census_ += colour_alias && fold.fold();
      }
      if (!s_fold_enabled || !fold.fold()) {
        msaa_fold_pin_depth = false;
      }
      if (s_fold_enabled && fold.fold()) {
        msaa_fold_restore.regs = register_file_;
        msaa_fold_restore.saved = regs.values[XE_GPU_REG_RB_SURFACE_INFO];
        register_file_->values[XE_GPU_REG_RB_SURFACE_INFO] =
            fold.surface_info_1x;
        msaa_fold_scale_x = 1u << fold.scale_x_log2;
        msaa_fold_scale_y = 1u << fold.scale_y_log2;
        // The render-target cache estimates the used height from guest
        // (MSAA-level) rows; scale it into the 1x view's rows.
        msaa_fold_restore.render_target_cache = render_target_cache_.get();
        render_target_cache_->SetDrawExtentYScale(msaa_fold_scale_y);
        if (colour_alias) {
          // Present the depth clear as a colour clear of the same tiles:
          // colour target 0 (already at the depth base, k_8_8_8_8) fully
          // written with replace blending, depth and stencil off.
          auto rewrite = [&](uint32_t index, uint32_t value) {
            msaa_fold_restore.colour_alias_saved
                [msaa_fold_restore.colour_alias_count++] = {
                index, register_file_->values[index]};
            register_file_->values[index] = value;
          };
          reg::RB_MODECONTROL mode = regs.Get<reg::RB_MODECONTROL>();
          mode.edram_mode = xenos::EDRAMMode::kColorDepth;
          reg::RB_BLENDCONTROL blend = regs.Get<reg::RB_BLENDCONTROL>(
              xenos::compat::BlendControlRegisterIndex(0));
          blend.color_srcblend = xenos::BlendFactor::kOne;
          blend.color_destblend = xenos::BlendFactor::kZero;
          blend.color_comb_fcn = xenos::BlendOp::kAdd;
          blend.alpha_srcblend = xenos::BlendFactor::kOne;
          blend.alpha_destblend = xenos::BlendFactor::kZero;
          blend.alpha_comb_fcn = xenos::BlendOp::kAdd;
          rewrite(XE_GPU_REG_RB_MODECONTROL, mode.value);
          rewrite(XE_GPU_REG_RB_COLOR_MASK, 0xFu);
          rewrite(XE_GPU_REG_RB_DEPTHCONTROL, 0u);
          rewrite(uint32_t(xenos::compat::BlendControlRegisterIndex(0)), blend.value);
          normalized_color_mask = ::rex::gpu::draw_state::GetNormalizedColorMask(
              regs, pixel_shader->GetWritesColorTargets());
          norm_depth = ::rex::gpu::draw_state::GetNormalizedDepthControl(regs);
          depth_bound = false;
          msaa_fold_pin_depth = false;
        }
      }
    }
  }
  // Write-provenance probe (XE_METAL_DEPTH_PROVENANCE): the pack-shader-
  // INDEPENDENT answer to "does the guest ever write real depth into the 4x
  // view?" — read straight from guest registers, so it can't be fooled by a
  // pack misread the way a host-texture nonzero count can. For the cross-MSAA
  // depth bypass this is the authority question: if no draw ever binds a 4x
  // depth surface with z-write, the 4x view carries no guest content and the
  // resample to/from it is pure churn; if some do, the empty shadow reads are a
  // pack artifact and the bypass would drop real depth. Throttled; grep
  // MetalDepthWrite and count by msaa/zwrite over depth_base 720.
  if (depth_bound) {
    static const bool s_depth_prov = std::getenv("XE_METAL_DEPTH_PROVENANCE");
    if (s_depth_prov) {
      static uint32_t s_prov_logs = 0;
      if (s_prov_logs++ < 4096) {
        uint32_t msaa = uint32_t(regs.Get<reg::RB_SURFACE_INFO>().msaa_samples);
        REXLOG_WARN("MetalDepthWrite @draw {}: base={}t msaa={}x fmt={} z_enable={} "
               "z_write={} sten_enable={}",
               trace_draw_index(), uint32_t(rb_depth_info.depth_base),
               1u << msaa,
               uint32_t(rb_depth_info.depth_format),
               uint32_t(norm_depth.z_enable),
               uint32_t(norm_depth.z_write_enable),
               uint32_t(norm_depth.stencil_enable));
      }
    }
  }
  bool color_bound = HasMetalColorTarget(normalized_color_mask);
  std::array<reg::RB_COLOR_INFO, xenos::kMaxColorRenderTargets> color_infos;
  for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
    color_infos[i] = regs.Get<reg::RB_COLOR_INFO>(
        xenos::compat::ColorInfoRegisterIndex(i));
  }
  const reg::RB_COLOR_INFO& rt0_info = color_infos[0];
  {
    // Log each unique RT configuration once (kept from the MRT-proof pass; it
    // is the ground truth for the per-target model).
    uint64_t cfg_key =
        (uint64_t(normalized_color_mask) << 33) ^
        (color_bound ? regs[xenos::compat::ColorInfoRegisterIndex(0)] : 0) ^
        (depth_bound ? (uint64_t(rb_depth_info.value) | (1ull << 32)) : 0);
    static std::unordered_set<uint64_t> s_seen_rt_configs;
    // Consecutive draws nearly always repeat the configuration: test the
    // previous key before the set insert.
    static uint64_t s_last_rt_config = ~uint64_t(0);
    if (cfg_key != s_last_rt_config &&
        (s_last_rt_config = cfg_key, s_seen_rt_configs.insert(cfg_key).second)) {
      REXLOG_INFO(
          "MetalRTConfig: color={} (base={} fmt={} mask={:X} expbias={}) "
          "depth={} (base={} fmt={}) ncm={:04X}",
          color_bound, uint32_t(rt0_info.color_base),
          uint32_t(rt0_info.color_format), normalized_color_mask & 0b1111,
          int32_t(rt0_info.color_exp_bias), depth_bound,
          uint32_t(rb_depth_info.depth_base),
          uint32_t(rb_depth_info.depth_format), normalized_color_mask);
    }
  }
  // Memexport: draws that bind neither color nor depth but whose VS has
  // valid export streams execute as vertex-only rasterization-disabled
  // pipelines in an attachment-less pass, writing the shared-memory UAV
  // (JC2's HDR/lighting chain: 3x2MB point-list exports per frame).
  // XE_METAL_MEMEXPORT_LOG=1 logs executions and remaining skips.
  static const bool s_memexport_log =
      std::getenv("XE_METAL_MEMEXPORT_LOG") != nullptr;
  // The validated VS-only route is part of the default pipeline. Exact
  // XE_METAL_MEMEXPORT=0 retains the pre-promotion skip path as a rollback;
  // explicit 1 enables and malformed values fail closed through the same
  // strict environment contract as canonical EDRAM.
  static const bool s_memexport_exec = metal::ParseMetalEnvironmentFlag(
      std::getenv("XE_METAL_MEMEXPORT"), /*default_enabled=*/true);
  bool memexport_draw = false;
  std::vector<::rex::gpu::draw_state::MemExportRange> memexport_ranges;
  if (s_memexport_exec && vertex_shader->GetMemExportEMWritten()) {
    ::rex::gpu::draw_state::AddMemExportRanges(regs, *vertex_shader, memexport_ranges);
  }
  // The vertex stage's ranges come first; the pixel stage's follow (as in
  // the reference backends' AddMemExportRanges for VS then PS), so the gap
  // report, preparation and publication see both stages' real destinations.
  const size_t vertex_memexport_range_count = memexport_ranges.size();
  if (s_memexport_exec && pixel_shader &&
      pixel_shader->GetMemExportEMWritten()) {
    ::rex::gpu::draw_state::AddMemExportRanges(regs, *pixel_shader, memexport_ranges);
  }
  const bool pixel_memexport_ranges_present =
      memexport_ranges.size() > vertex_memexport_range_count;
  // Destination preparation, shared by BOTH memexport producer routes
  // (task 1.2 reuse audit: the VS-only route's call shape generalizes
  // untouched -- normalized range through DecideMemexportDestinationPreparation
  // + PrepareMemexportDestination, i.e. the same ::rex::gpu::SharedMemory::RequestRange the
  // direct call site used before). MUST run before the frame encoder opens,
  // because RequestRange uploads guest RAM into the shared buffer.
  //
  // It also runs the WRITER-BEFORE-WRITER ordering the export depends on. The
  // store this draw is about to encode is the NEWEST writer of its destination
  // bytes, so every older pending producer overlapping them is converged and
  // retired here, at the same barrier every consumer already uses. Without it
  // the older record is drained later and writes its bytes over the export --
  // survivable on the mirror backing only because memexport convergence copies
  // buffer -> RAM afterwards, and NOT survivable once the shared buffer aliases
  // guest RAM, where that convergence is a self-copy with nothing to restore.
  // Selection is the ordinary intersecting-producer closure, so disjoint
  // writers are never drained and an empty selection costs no commit or wait.
  auto prepare_memexport_destinations = [&]() -> bool {
    bool ranges_ok = true;
    // Normalize every destination FIRST. The ordering barrier is then taken
    // once over their union, so a drain triggered by one range cannot
    // invalidate pages another range already requested.
    std::vector<metal::MemexportDestinationPreparation> preparations;
    preparations.reserve(memexport_ranges.size());
    for (const auto& range : memexport_ranges) {
      uint32_t range_base = range.base_address_dwords << 2;
      auto preparation = metal::DecideMemexportDestinationPreparation(
          range_base, range.size_bytes);
      if (!preparation) {
        REXLOG_ERROR("MetalMemexport: failed to normalize range {:08X}(+{})",
               range_base, range.size_bytes);
        ranges_ok = false;
        continue;
      }
      preparations.push_back(*preparation);
    }
    MetalMemexportPreparationTarget preparation_target(shared_memory_.get());
    // GPU-ordered destinations (stage 2 of the gpu-resident coherence
    // change): when every older overlapping producer is GPU-resident the
    // export is ordered behind it on the queue instead of waiting for it on
    // the CPU. XE_METAL_MEMEXPORT_ORDERING=0 restores the await/drain
    // barrier; capture and playback keep it (the recorded RAM must be
    // converged).
    static const bool s_memexport_ordering = [] {
      const char* g = std::getenv("XE_METAL_GPU_ORDERING");
      const char* v = std::getenv("XE_METAL_MEMEXPORT_ORDERING");
      return !(g && g[0] == '0' && !g[1]) && !(v && v[0] == '0' && !v[1]);
    }();
    const bool gpu_ordered_destinations = s_memexport_ordering &&
                                          true &&
                                          true;
    metal::MemexportDestinationPreparationOutcome outcome =
        metal::PrepareOrderedMemexportDestinations(
            preparations, SnapshotPendingProducers(),
            completed_submission_.load(std::memory_order_acquire),
            preparation_target,
            [&](const metal::ConsumerDecision& selected) {
              // The one boundary/commit/wait/selective-drain implementation.
              // Nothing here mints completion evidence of its own.
              //
              // The ordering barrier is counted HERE, inside the callback that
              // performs it, rather than beside the outcome: the seam invokes
              // this only when the snapshot selected older overlapping
              // producers, so reaching this line IS the barrier. Counting it
              // from the outcome would count consultations, and counting it
              // from the backing mode would count configuration.
              zero_copy_cost_.Count(
                  metal::ZeroCopyCostCounter::kMemexportOrderingBarriers);
              zero_copy_cost_.Add(
                  metal::ZeroCopyCostCounter::kMemexportSelectedPredecessors,
                  uint64_t(selected.selected.size()));
              return ResolvePendingProducerDependencies(selected).drain;
            },
            gpu_ordered_destinations);
    if (outcome.ordering ==
        metal::MemexportDestinationOrdering::kOlderProducersGpuOrdered) {
      static uint64_t s_gpu_ordered_exports = 0;
      if (++s_gpu_ordered_exports <= 4 ||
          (s_gpu_ordered_exports & 4095) == 0) {
        REXLOG_INFO(
            "MetalMemexport: GPU-ordered destination #{} ({} older "
            "producers, max_order_submission={})",
            s_gpu_ordered_exports, outcome.decision.selected.size(),
            outcome.decision.max_order_submission);
      }
    }
    // Preparation cost, from the outcome's own facts. The no-older fast path is
    // separated from the barrier above because it is the case that costs
    // nothing, and folding the two together would hide exactly the difference
    // this evidence is collected to measure.
    zero_copy_cost_.Count(
        metal::ZeroCopyCostCounter::kMemexportDestinationPreparations);
    if (outcome.ordering ==
        metal::MemexportDestinationOrdering::kNoOlderProducer) {
      zero_copy_cost_.Count(
          metal::ZeroCopyCostCounter::kMemexportNoOlderFastPaths);
    } else if (outcome.ordering ==
               metal::MemexportDestinationOrdering::kOlderProducersRetained) {
      // A short drain: the destination is NOT prepared and at least one older
      // producer is still pending.
      zero_copy_cost_.Count(
          metal::ZeroCopyCostCounter::kMemexportOrderingRetained);
    }
    if (!outcome.prepared()) {
      zero_copy_cost_.Count(
          metal::ZeroCopyCostCounter::kMemexportPreparationFailures);
      REXLOG_ERROR(
          "MetalMemexport: destination preparation failed draw={} ordering={} "
          "selected={} retired={} requested={}/{}",
          trace_draw_index_,
          metal::MemexportDestinationOrderingName(outcome.ordering),
          uint32_t(outcome.decision.selected.size()),
          outcome.drain.drained_records, outcome.requested_ranges,
          outcome.range_count);
      for (const auto& preparation : preparations) {
        REXLOG_ERROR("MetalMemexport: unprepared destination {:08X}(+{})",
               preparation.range.start(), preparation.range.length());
      }
      ranges_ok = false;
    }
    return ranges_ok;
  };
  const bool rt_bound_for_export = color_bound || (kDepthEnabled && depth_bound);
  const bool ps_writes_eM =
      pixel_shader && pixel_shader->GetMemExportEMWritten();
  // extend-metal-rasterizing-memexport-producers tasks 2.2/2.3 (design D1):
  // a draw that rasterizes AND exports executes ONCE -- routing is BINDING
  // (writable shared-memory UAV on the stage(s) MSC runs the guest VS on) and
  // ORDERING (prepare, publish, converge), never a shadow draw. The pure
  // predicate owns the whole decision matrix, including the two permanent
  // exclusions (pixel-stage export; tessellated producers, which the
  // tessellation route already fail-closed skips upstream at "tess-memexport").
  // A pixel shader that exports with no render target bound (color writes
  // off, no depth) still rasterizes on the guest: its exports are the whole
  // effect of the draw. Route it like a rasterizing pixel producer, in a pass
  // of its own with only a scratch depth attachment (see
  // MetalMemexportPixelNoTargetGateOn).
  bool pixel_export_only =
      !rt_bound_for_export && ps_writes_eM && pixel_memexport_ranges_present &&
      MetalMemexportPixelGateOn() && MetalMemexportPixelNoTargetGateOn();
  const metal::MetalMemexportRasterRoute memexport_raster_route =
      metal::DecideMetalMemexportRoute(
          MetalMemexportRasterGateOn(), MetalMemexportPixelGateOn(),
          rt_bound_for_export || pixel_export_only,
          vertex_memexport_range_count != 0, ps_writes_eM,
          pixel_memexport_ranges_present, use_tessellation_emulation);
  bool memexport_raster_routed =
      metal::MetalMemexportRasterRouteRoutes(memexport_raster_route);
  // Bisect filter (XE_METAL_MEMEXPORT_RASTER_ONLY, empty by default and
  // therefore inert): de-route a producer whose destination is not on the
  // list, so one destination at a time can be attributed to an image delta.
  // A de-routed producer falls back to the unrouted path in full, gap report
  // included -- the filter never produces a half-routed draw.
  if (memexport_raster_routed && !MemexportRasterOnlyBases().empty()) {
    for (const auto& range : memexport_ranges) {
      if (!MemexportRasterBaseAdmitted(range.base_address_dwords << 2)) {
        memexport_raster_routed = false;
        break;
      }
    }
  }
  // Anything the route did not accept (tessellated, vertex gate off, bisect
  // filter) keeps the old no-target skip below.
  pixel_export_only = pixel_export_only && memexport_raster_routed;
  // Report memexport producer classes this backend does not route. Bounded and
  // deduplicated by MemexportGapReporter; unconditional by design, because the
  // symptom is missing guest data with nothing to attribute it to, and a
  // switch-gated report cannot catch what nobody is yet looking for. The class
  // accounting flips ONLY when the class is actually routed -- never merely
  // because the gate is on.
  if (!memexport_raster_routed) {
    if (rt_bound_for_export && (!memexport_ranges.empty() || ps_writes_eM)) {
      const MemexportProducerClass producer_class =
          ps_writes_eM ? MemexportProducerClass::kPixelStage
                       : (use_geometry_emulation
                              ? MemexportProducerClass::kRasterizingVertexGeometry
                              : MemexportProducerClass::kRasterizingVertex);
      auto report = [&](uint32_t base_dwords, uint32_t size_bytes) {
        switch (memexport_gap_reporter_.Observe(producer_class, base_dwords,
                                                size_bytes)) {
          case MemexportGapReporter::Action::kReport:
            // Guest addresses and producer classification only.
            REXLOG_WARN(
                "MetalMemexportUnrouted class={} guest_base=0x{:08X} size={} "
                "-- UNPUBLISHED: this backend routes only the vertex-stage "
                "no-render-target class, so these writes never reach guest "
                "memory",
                MemexportProducerClassName(producer_class), base_dwords << 2,
                size_bytes);
            break;
          case MemexportGapReporter::Action::kEmitSuppressionSummary:
            REXLOG_WARN(
                "MetalMemexportUnrouted: reached {} distinct unrouted export "
                "reports this title; further reports suppressed",
                MemexportGapReporter::kMaxDistinctReports);
            break;
          case MemexportGapReporter::Action::kSuppressed:
            break;
        }
      };
      if (memexport_ranges.empty()) {
        // An export whose stream constants produced no valid range still has
        // a class worth reporting once; key it on a zero range.
        report(0u, 0u);
      } else {
        for (const auto& r : memexport_ranges) {
          report(r.base_address_dwords, r.size_bytes);
        }
      }
    }
  } else {
    // Routed rasterizing producer: prepare the destination pages BEFORE any
    // encoding, exactly like the VS-only route. Failure means the exports have
    // nowhere to land, so the draw fail-closed skips with its OWN reason -- it
    // is never rasterized-without-exporting behind the caller's back, because
    // that would silently reintroduce the stale-RAM condition this route
    // exists to remove.
    if (!prepare_memexport_destinations()) {
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                     "memexport-raster-range");
      return true;
    }
    if (s_memexport_log) {
      for (const auto& range : memexport_ranges) {
        REXLOG_WARN(
            "MetalMemexportRasterExec draw={} VS shader={:016X} PS shader="
            "{:016X} ps_exports={} dest={:08X} "
            "bytes={} prim={} n={} geometry_emulated={} eM_mask={:02X} "
            "stage_mask={:X} writing_stage={:X}",
            trace_draw_index_, vertex_shader->GetUcodeDataHash(),
            pixel_shader ? pixel_shader->GetUcodeDataHash() : 0ull,
            ps_writes_eM ? 1 : 0,
            range.base_address_dwords << 2, range.size_bytes,
            uint32_t(prim_type), index_count, use_geometry_emulation ? 1 : 0,
            uint32_t(vertex_shader->GetMemExportEMWritten()),
            metal::GetMetalMemexportRasterStageMask(use_geometry_emulation),
            metal::GetMetalMemexportRasterWritingStage(use_geometry_emulation));
      }
    }
  }

  // ACCESS CENSUS (XE_METAL_MEMEXPORT_WATCH, default off): every draw-input
  // guest range this draw reads that OVERLAPS the watched range, reported by
  // overlap alone. Deliberately independent of pending-producer state, of the
  // memexport gate, and of whether this draw exports anything -- so it answers
  // "does ANYTHING downstream read this range in this frame?" rather than the
  // much weaker "was a still-pending producer selected?".
  if (MemexportWatch().enabled) {
    auto report_access = [&](const char* kind, uint32_t fetch_constant,
                             uint32_t base, uint32_t size) {
      if (!MemexportWatchOverlaps(base, size)) {
        return;
      }
      REXLOG_WARN(
          "MetalMemexportWatch draw={} access={} fc={} range={:08X}(+{}) "
          "vs={:016X} ps={:016X}",
          trace_draw_index_, kind, fetch_constant, base, size,
          vertex_shader ? vertex_shader->GetUcodeDataHash() : 0ull,
          pixel_shader ? pixel_shader->GetUcodeDataHash() : 0ull);
    };
    auto census_textures = [&](MetalShader* shader, const char* kind) {
      if (!shader) {
        return;
      }
      for (const auto& binding : shader->GetTextureBindingsAfterTranslation()) {
        auto fetch = regs.GetTextureFetch(binding.fetch_constant);
        if (!(fetch.base_address << 12)) {
          continue;
        }
        metal::FetchGuestRanges ranges = ComputeFetchGuestRanges(fetch);
        report_access(kind, binding.fetch_constant, ranges.base_begin,
                      ranges.base_end - ranges.base_begin);
        if (ranges.mip_end > ranges.mip_begin) {
          report_access(kind, binding.fetch_constant, ranges.mip_begin,
                        ranges.mip_end - ranges.mip_begin);
        }
      }
    };
    census_textures(vertex_shader, "vs-texture");
    census_textures(pixel_shader, "ps-texture");
    const ::rex::gpu::Shader::ConstantRegisterMap& census_map =
        vertex_shader->GetConstantRegisterMap();
    for (uint32_t i = 0; i < rex::countof(census_map.vertex_fetch_bitmap); ++i) {
      uint32_t bits = census_map.vertex_fetch_bitmap[i];
      uint32_t j;
      while (rex::bit_scan_forward(bits, &j)) {
        bits = ((bits) & ((bits) - 1));
        uint32_t fetch_constant = i * 32 + j;
        xenos::VertexFetch fetch = regs.GetVertexFetch(fetch_constant);
        if (fetch.type != xenos::FetchConstantType::kVertex &&
            fetch.type != xenos::FetchConstantType::kInvalidVertex) {
          continue;
        }
        report_access("vfetch", fetch_constant, fetch.address << 2,
                      fetch.size * uint32_t(sizeof(uint32_t)));
      }
    }
    if (index_buffer_info && index_buffer_info->guest_base && index_count) {
      report_access(
          "index", 0, index_buffer_info->guest_base,
          index_count * (index_buffer_info->format == xenos::IndexFormat::kInt32
                             ? 4u
                             : 2u));
    }
    if (use_tessellation_emulation &&
        tess_pp.index_buffer_type ==
            ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kGuestDMA &&
        tess_pp.guest_index_base) {
      report_access("tess-factor-stream", 0, tess_pp.guest_index_base,
                    tess_pp.host_draw_vertex_count *
                        (tess_pp.host_index_format == xenos::IndexFormat::kInt32
                             ? 4u
                             : 2u));
    }
  }

  // See MetalZPDCountNoTargetDrawsOn. Only a draw with nothing to export, so
  // the memory export paths below are untouched.
  const bool zpd_count_only_draw =
      !color_bound && !(kDepthEnabled && depth_bound) && !pixel_export_only &&
      memexport_ranges.empty() &&
      !(pixel_shader && pixel_shader->GetMemExportEMWritten()) &&
      zpd_active_segment_.logical_active && MetalZPDCountNoTargetDrawsOn();
  if (!color_bound && !(kDepthEnabled && depth_bound) && !pixel_export_only &&
      !zpd_count_only_draw) {
    bool ps_exports = pixel_shader && pixel_shader->GetMemExportEMWritten();
    if (memexport_ranges.empty() || ps_exports) {
      // Nothing to render and nothing exportable via the v1 path (plain
      // no-op draw, or a rasterizing PS export which v1 doesn't run).
      if (s_memexport_log) {
        if (ps_exports) {
          REXLOG_WARN("MetalMemexportSkip draw={} PS-export (unsupported in v1)",
                 trace_draw_index_);
        } else {
          static uint32_t s_plain_skips = 0;
          if (s_plain_skips++ < 8) {
            REXLOG_WARN("MetalMemexportSkip draw={} NO-RT draw without memexport "
                   "(plain skip)",
                   trace_draw_index_);
          }
        }
      }
      // Diagnostic (2026-09-19, Gears of War 3): a no-RT draw issued while an
      // occlusion (ZPD) query is logically open is a sample-count query, not a
      // no-op; skipping it reports zero visible samples. Bounded log.
      {
        static uint32_t s_zpd_skip_logs = 0;
        if (zpd_active_segment_.logical_active && s_zpd_skip_logs < 16) {
          ++s_zpd_skip_logs;
          REXLOG_WARN(
              "MetalZPDSkip draw={} no-RT draw skipped inside a logically "
              "active ZPD segment (segment_active={} pending_begin={} "
              "zfunc={} z_en={} prim={} index_count={} edram_mode={} "
              "color_mask={:08X} ps={} stencil={})",
              trace_draw_index_, zpd_active_segment_.segment_active,
              zpd_active_segment_.segment_pending_begin,
              uint32_t(regs.Get<reg::RB_DEPTHCONTROL>().zfunc),
              uint32_t(regs.Get<reg::RB_DEPTHCONTROL>().z_enable),
              uint32_t(prim_type), index_count,
              uint32_t(regs.Get<reg::RB_MODECONTROL>().edram_mode),
              regs.Get<reg::RB_COLOR_MASK>().value, pixel_shader != nullptr,
              uint32_t(regs.Get<reg::RB_DEPTHCONTROL>().stencil_enable));
        }
      }
      RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                     "no-rt-no-export");
      return true;
    }
    // Commit the destination pages; failure means the exports have nowhere
    // to land — skip like the reference backends fail the draw. Routed
    // through the typed task-3.3 destination-preparation seam (normalized
    // range + the same RequestRange call the direct call site used before).
    if (!prepare_memexport_destinations()) {
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure, "memexport-range");
      return true;
    }
    // Rasterization is disabled on this path: the pixel shader (if any) and
    // geometry emulation are irrelevant; the guest VS runs per-vertex as a
    // plain vertex function.
    memexport_draw = true;
    pixel_shader = nullptr;
    use_geometry_emulation = false;
    rect_strip_route = false;
    if (!MapPrimitiveType(prim_type, &mtl_prim)) {
      if (s_memexport_log) {
        REXLOG_WARN("MetalMemexportSkip draw={} unmappable prim {} for export",
               trace_draw_index_, uint32_t(prim_type));
      }
      RecordDrawSkip(MetalDrawSkipReason::kUnsupportedCapability,
                     "memexport-prim-unmappable");
      return true;
    }
    if (s_memexport_log) {
      for (const auto& range : memexport_ranges) {
        REXLOG_WARN(
            "MetalMemexportExec draw={} VS shader={:016X} dest={:08X} "
            "bytes={} prim={} n={}",
            trace_draw_index_, vertex_shader->GetUcodeDataHash(),
            range.base_address_dwords << 2, range.size_bytes,
            uint32_t(prim_type), index_count);
      }
      // The export VS's index math runs off these — log once per draw so the
      // CPU-side simulation of the ucode has ground-truth inputs.
      auto logc = [&](uint32_t creg) {
        const float* c = reinterpret_cast<const float*>(
            &regs[XE_GPU_REG_SHADER_CONSTANT_000_X + creg * 4]);
        REXLOG_WARN("MetalMemexportExec   c{}=({:g}, {:g}, {:g}, {:g})", creg, c[0],
               c[1], c[2], c[3]);
      };
      logc(0);
      logc(1);
      logc(2);
      logc(253);
      logc(254);
      logc(255);
    }
  }
  // DIAGNOSTICS (JC2 lighting investigation, closed): the producer and
  // consumer logs below did hash-set and resolve-snapshot lookups on every
  // draw to log once per shader (about 1% of the Burnout command-processor
  // thread, 2026-10-20). XE_METAL_RT_CONSUMER_LOG=1 (or
  // XE_METAL_RT_CONSUMER_ALL) arms them.
  static const bool s_rt_consumer_log =
      std::getenv("XE_METAL_RT_CONSUMER_LOG") != nullptr ||
      std::getenv("XE_METAL_RT_CONSUMER_ALL") != nullptr;
  // DIAGNOSTIC: the quarter-res lighting producer — log draws into small-pitch
  // color RTs (the inferred-lighting buffer) with everything they sample.
  if (s_rt_consumer_log && color_bound && pixel_shader &&
      regs.Get<reg::RB_SURFACE_INFO>().surface_pitch <= 400) {
    static std::unordered_set<uint64_t> s_seen_light_producer;
    if (s_seen_light_producer.insert(pixel_shader->GetUcodeDataHash()).second &&
        s_seen_light_producer.size() <= 16) {
      REXLOG_INFO(
          "MetalLightProducer: ps={:016X} pitch={} fmt={} prim={} n={} geo={} "
          "blend={:08X} mask={:X} rt={:X} samples:",
          pixel_shader->GetUcodeDataHash(),
          uint32_t(regs.Get<reg::RB_SURFACE_INFO>().surface_pitch),
          uint32_t(rt0_info.color_format), uint32_t(prim_type), index_count,
          use_geometry_emulation, regs[XE_GPU_REG_RB_BLENDCONTROL0],
          normalized_color_mask & 0b1111,
          uintptr_t(render_target_cache_->current_color_texture(0, nullptr)));
      for (const auto& binding :
           pixel_shader->GetTextureBindingsAfterTranslation()) {
        auto f = regs.GetTextureFetch(binding.fetch_constant);
        uint32_t fetch_base = f.base_address << 12;
        REXLOG_INFO("MetalLightProducer:   fc={} base={:08X}{} fmt={} {}x{}",
               binding.fetch_constant, fetch_base,
               render_target_cache_->GetResolveSnapshot(fetch_base)
                   ? " [SNAPSHOT]"
                   : "",
               uint32_t(f.format), f.size_2d.width + 1, f.size_2d.height + 1);
      }
    }
  }
  // DIAGNOSTIC (lighting-term ~0): log, once per (pixel shader, RT config),
  // every draw whose PS samples a RESOLVED SNAPSHOT (the RT-consuming passes —
  // deferred lighting, composite, post) with what it samples and where it
  // writes, so the black lighting can be traced through the pass graph.
  if (s_rt_consumer_log && color_bound && pixel_shader &&
      render_target_cache_) {
    bool samples_snapshot = false;
    for (const auto& binding :
         pixel_shader->GetTextureBindingsAfterTranslation()) {
      auto f = regs.GetTextureFetch(binding.fetch_constant);
      if (render_target_cache_->GetResolveSnapshot(f.base_address << 12)) {
        samples_snapshot = true;
        break;
      }
    }
    if (samples_snapshot) {
      static std::unordered_set<uint64_t> s_seen_consumer_ps;
      // XE_METAL_RT_CONSUMER_ALL=1 logs every consuming draw, not only the
      // first per (pixel shader, RT config), for per-draw bisection.
      static const bool s_consumer_all =
          std::getenv("XE_METAL_RT_CONSUMER_ALL") != nullptr;
      uint64_t seen_key = pixel_shader->GetUcodeDataHash() ^
                          (uint64_t(rt0_info.value) << 1);
      if (s_seen_consumer_ps.insert(seen_key).second || s_consumer_all) {
        REXLOG_INFO(
            "MetalRTConsumer: draw={} ps={:016X} -> color(base={} fmt={}) "
            "prim={} depth={} zfunc={} samples:",
            int64_t(trace_draw_index_) - 1, pixel_shader->GetUcodeDataHash(),
            uint32_t(rt0_info.color_base),
            uint32_t(rt0_info.color_format), uint32_t(prim_type), depth_bound,
            uint32_t(norm_depth.zfunc));
        for (const auto& binding :
             pixel_shader->GetTextureBindingsAfterTranslation()) {
          auto f = regs.GetTextureFetch(binding.fetch_constant);
          uint32_t fetch_base = f.base_address << 12;
          bool is_snap =
              render_target_cache_->GetResolveSnapshot(fetch_base) != nullptr;
          REXLOG_INFO(
              "MetalRTConsumer:   fc={} base={:08X}{} fmt={} {}x{} "
              "swz={:03X} signs={:02X}",
              binding.fetch_constant, fetch_base, is_snap ? " [SNAPSHOT]" : "",
              uint32_t(f.format), f.size_2d.width + 1, f.size_2d.height + 1,
              f.swizzle & 0xFFF, ::rex::xenos::SwizzleSigns(f));
        }
      }
    }
  }
  // Task 4.2: collect every draw-input vertex range before any CPU-side draw
  // estimation, trace capture, primitive processing, or Metal encoding reads
  // it. The exact DMA index interval participates in the same kVertex request
  // because this backend materializes indices directly from guest RAM. Only
  // vfetch ranges are revalidated in the shared buffer below; indices remain a
  // RAM consumer.
  const ::rex::gpu::Shader::ConstantRegisterMap& vs_map =
      vertex_shader->GetConstantRegisterMap();
  struct VertexFetchDependency {
    uint32_t fetch_constant;
    xenos::VertexFetch fetch;
    metal::GuestRange range;
  };
  // Per-draw scratch kept across draws so the command processor does not
  // allocate and free them ~7,000 times a frame (IssueDraw is not reentrant).
  static std::vector<VertexFetchDependency> vertex_fetch_dependencies;
  static metal::GuestRangeSet vertex_dependency_ranges;
  vertex_fetch_dependencies.clear();
  vertex_dependency_ranges.Clear();
  draw_vfetch_renames_.clear();
  // A pixel shader can vfetch too (Rise of the Tomb Raider's dynamic-weight
  // skinning pass reads the cloth vertex positions per pixel through fetch
  // constant 95). Those ranges are guest-RAM consumers exactly like the
  // vertex shader's: they must be uploaded, hazard-ordered and joined with a
  // pending memexport producer. Before 2026-10-25 only the vertex shader's
  // bitmap was walked, so the pixel pass read whatever bytes the shared
  // buffer happened to hold for that page (live: a stale or never-uploaded
  // CPU write; the weight sum then collapses and the vertices fly off as a
  // stretched sheet).
  const ::rex::gpu::Shader::ConstantRegisterMap* ps_map =
      pixel_shader ? &pixel_shader->GetConstantRegisterMap() : nullptr;
  static uint32_t s_ps_vfetch_logged = 0;
  for (uint32_t i = 0; i < rex::countof(vs_map.vertex_fetch_bitmap); ++i) {
    const uint32_t ps_bits = ps_map ? ps_map->vertex_fetch_bitmap[i] : 0u;
    uint32_t bits = vs_map.vertex_fetch_bitmap[i] | ps_bits;
    uint32_t j;
    while (rex::bit_scan_forward(bits, &j)) {
      bits = ((bits) & ((bits) - 1));
      uint32_t fetch_constant = i * 32 + j;
      xenos::VertexFetch fetch =
          regs.GetVertexFetch(fetch_constant);
      if (fetch.type != xenos::FetchConstantType::kVertex &&
          fetch.type != xenos::FetchConstantType::kInvalidVertex) {
        continue;
      }
      uint32_t fetch_base = fetch.address << 2;
      auto range = metal::GuestRange::FromBounds(
          fetch_base,
          uint64_t(fetch_base) + uint64_t(fetch.size) * sizeof(uint32_t));
      if (!range) {
        continue;
      }
      if ((ps_bits & (1u << j)) && s_ps_vfetch_logged < 8) {
        ++s_ps_vfetch_logged;
        REXLOG_INFO("MetalPsVfetch: draw {} ps={:016X} fc={} base={:08X} size={}",
               trace_draw_index_, pixel_shader->GetUcodeDataHash(),
               fetch_constant, fetch_base, uint32_t(fetch.size) * 4);
      }
      vertex_fetch_dependencies.push_back(
          {fetch_constant, fetch, *range});
      vertex_dependency_ranges.Add(*range);
      // XE_METAL_MEMEXPORT_LOG: a memexport producer's vertex input as the
      // CPU and the GPU buffer see it (Child of Eden's video copy exported a
      // constant live while the headless replay was right).
      if (s_memexport_log && vertex_shader->GetMemExportEMWritten()) {
        uint32_t pending_overlaps = 0;
        for (const metal::PendingProducer& p : SnapshotPendingProducers()) {
          if (p.range.Overlaps(*range)) {
            ++pending_overlaps;
          }
        }
        const uint32_t* ram =
            TranslateGuest<const uint32_t*>(fetch_base);
        const uint32_t* buf = nullptr;
        if (shared_memory_) {
          __unsafe_unretained id<MTLBuffer> b = (__bridge id<MTLBuffer>)shared_memory_->GetCpuBuffer();
          if (b && b.storageMode != MTLStorageModePrivate && b.contents) {
            buf = reinterpret_cast<const uint32_t*>(
                static_cast<const uint8_t*>(b.contents) + fetch_base);
          }
        }
        REXLOG_WARN(
            "MetalMemexportVfetch draw={} fc={} base={:08X} size={} "
            "pending_overlaps={} ram={:08X} {:08X} {:08X} {:08X} "
            "buf={:08X} {:08X} {:08X} {:08X}",
            trace_draw_index_, fetch_constant, fetch_base,
            uint32_t(fetch.size) * 4, pending_overlaps, ram ? ram[0] : 0,
            ram ? ram[1] : 0, ram ? ram[2] : 0, ram ? ram[3] : 0,
            buf ? buf[0] : 0, buf ? buf[1] : 0, buf ? buf[2] : 0,
            buf ? buf[3] : 0);
      }
    }
  }
  {
    // Upstream-delta census, tier-3 candidates (2026-10-09):
    //  viz_draw      - draws with a visibility query active (Canary 692cd59cf
    //                  VIZ_QUERY; kill=1 are coverage-only surveys).
    //  window_offset - draws with a nonzero PA_SC_WINDOW_OFFSET applied
    //                  (Canary e1f4a0d00 / 6579cc2a4, predicated tiling).
    //  msaa_draw     - multisampled draws by sample count and viewport offset
    //                  fraction (Canary cc4981a46 Xenos sample positions; UE3
    //                  offsets the viewport to align a sample with 1x depth).
    static const bool s_tier3_census =
        std::getenv("XE_GPU_DELTA_CENSUS") != nullptr;
    if (s_tier3_census) {
      auto viz = regs.Get<reg::PA_SC_VIZ_QUERY>();
      if (viz.viz_query_ena) {
        uint64_t n = DeltaCensusKeyedCount(
            1, uint64_t(viz.viz_query_id) | (uint64_t(viz.kill_pix_post_hi_z) << 8));
        if (DeltaCensusLogCount(n)) {
          REXLOG_INFO("DeltaCensus viz_draw draw={} id={} kill={} count={}",
                 trace_draw_index_, uint32_t(viz.viz_query_id),
                 uint32_t(viz.kill_pix_post_hi_z), n);
        }
      }
      auto sc_mode = regs.Get<reg::PA_SU_SC_MODE_CNTL>();
      auto window_offset = regs.Get<reg::PA_SC_WINDOW_OFFSET>();
      if (sc_mode.vtx_window_offset_enable &&
          (window_offset.window_x_offset || window_offset.window_y_offset)) {
        uint64_t n = DeltaCensusKeyedCount(2, window_offset.value);
        if (DeltaCensusLogCount(n)) {
          REXLOG_INFO("DeltaCensus window_offset draw={} x={} y={} count={}",
                 trace_draw_index_, int32_t(window_offset.window_x_offset),
                 int32_t(window_offset.window_y_offset), n);
        }
      }
      auto surface_info = regs.Get<reg::RB_SURFACE_INFO>();
      if (surface_info.msaa_samples != xenos::MSAASamples::k1X) {
        auto vte = regs.Get<reg::PA_CL_VTE_CNTL>();
        float xoffset = vte.vport_x_offset_ena
                            ? regs.Get<float>(XE_GPU_REG_PA_CL_VPORT_XOFFSET)
                            : 0.0f;
        float yoffset = vte.vport_y_offset_ena
                            ? regs.Get<float>(XE_GPU_REG_PA_CL_VPORT_YOFFSET)
                            : 0.0f;
        // Fraction in 1/16 pixel.
        uint32_t frac_x =
            uint32_t(std::lround((xoffset - std::floor(xoffset)) * 16.0f)) & 15;
        uint32_t frac_y =
            uint32_t(std::lround((yoffset - std::floor(yoffset)) * 16.0f)) & 15;
        uint32_t depth_on = regs.Get<reg::RB_DEPTHCONTROL>().z_enable;
        uint64_t n = DeltaCensusKeyedCount(
            3, uint64_t(surface_info.msaa_samples) | (frac_x << 4) |
                   (frac_y << 8) | (depth_on << 12));
        if (DeltaCensusLogCount(n)) {
          REXLOG_INFO(
              "DeltaCensus msaa_draw draw={} samples={} vport_frac=({},{})/16 "
              "z={} count={}",
              trace_draw_index_, 1u << uint32_t(surface_info.msaa_samples),
              frac_x, frac_y, depth_on, n);
        }
      }
    }
  }
  {
    // Upstream-delta census (XE_GPU_DELTA_CENSUS=1, diagnostic): vertex
    // fetches whose last addressed word lies past the fetch constant's size.
    // Canary 9e9d3cdd3 masks such words to zero; the local translator reads
    // whatever follows in guest memory. max_index scans the DMA index buffer
    // (reset indices 0xFFFF/0xFFFFFFFF excluded) and adds VGT_INDX_OFFSET.
    static const bool s_delta_census =
        std::getenv("XE_GPU_DELTA_CENSUS") != nullptr;
    static const bool s_delta_selftest =
        s_delta_census &&
        std::strcmp(std::getenv("XE_GPU_DELTA_CENSUS"), "selftest") == 0;
    static uint32_t s_delta_census_lines = 0;
    if (s_delta_census && index_count && s_delta_census_lines < 20000) {
      int64_t max_index = -1;
      bool indexed = false;
      if (index_buffer_info && index_buffer_info->guest_base) {
        indexed = true;
        const bool is32 =
            index_buffer_info->format == xenos::IndexFormat::kInt32;
        const uint8_t* ib = TranslateGuest<const uint8_t*>(
            index_buffer_info->guest_base);
        for (uint32_t k = 0; k < index_count; ++k) {
          uint32_t v;
          if (is32) {
            v = xenos::GPUSwap(reinterpret_cast<const uint32_t*>(ib)[k],
                               index_buffer_info->endianness);
            if (v == 0xFFFFFFFFu) continue;
          } else {
            v = xenos::GPUSwap(reinterpret_cast<const uint16_t*>(ib)[k],
                               index_buffer_info->endianness);
            if (v == 0xFFFFu) continue;
          }
          if (int64_t(v) > max_index) max_index = int64_t(v);
        }
      } else {
        max_index = int64_t(index_count) - 1;
      }
      max_index += int64_t(regs.Get<reg::VGT_INDX_OFFSET>().indx_offset);
      if (max_index >= 0) {
        for (const auto& binding : vertex_shader->GetVertexBindings()) {
          xenos::VertexFetch vf =
              regs.GetVertexFetch(binding.fetch_constant);
          if (vf.type != xenos::FetchConstantType::kVertex) continue;
          // Per attribute: the translated address is base + index*stride +
          // offset with the INSTRUCTION's stride, and the index is whatever
          // register the shader passes. `raw_index` records whether that
          // operand is the untouched vertex-id register (r0.x); a shader that
          // derives its own index (r0.x/4 etc.) makes this bound an
          // over-approximation, so the aggregator separates the two.
          uint64_t end_word = 0;
          uint32_t end_stride = 0, end_attr_end = 0;
          bool end_raw_index = false;
          for (const auto& attr : binding.attributes) {
            const auto& a = attr.fetch_instr.attributes;
            uint32_t words = xenos::GetVertexFormatNeededWords(
                a.data_format, attr.fetch_instr.result.GetUsedResultComponents());
            if (!words) words = 1;
            uint32_t stride = a.stride ? a.stride : binding.stride_words;
            uint32_t attr_end = uint32_t(std::max<int32_t>(a.offset, 0)) + words;
            uint64_t e = uint64_t(max_index) * stride + attr_end;
            const auto& idx_op = attr.fetch_instr.operands[0];
            bool raw =
                attr.fetch_instr.operand_count > 0 &&
                idx_op.storage_source == ::rex::gpu::InstructionStorageSource::kRegister &&
                idx_op.storage_index == 0 &&
                idx_op.components[0] == ::rex::gpu::SwizzleSource::kX;
            if (e > end_word) {
              end_word = e; end_stride = stride; end_attr_end = attr_end;
              end_raw_index = raw;
            }
          }
          if ((s_delta_selftest || end_word > vf.size) &&
              s_delta_census_lines++ < 20000) {
            uint64_t overshoot = end_word > vf.size ? end_word - vf.size : 0;
            REXLOG_INFO(
                "DeltaCensus vfetch_oob draw={} vs={:016X} fc={} indexed={} "
                "raw_index={} index_count={} max_index={} stride_w={} "
                "attr_end_w={} end_word={} size_words={} overshoot_w={} "
                "elements_past={} base={:08X}",
                trace_draw_index_, vertex_shader->GetUcodeDataHash(),
                binding.fetch_constant, indexed ? 1 : 0, end_raw_index ? 1 : 0,
                index_count, max_index, end_stride, end_attr_end, end_word,
                uint32_t(vf.size), overshoot,
                end_stride ? (overshoot + end_stride - 1) / end_stride : 0,
                vf.address << 2);
          }
        }
      }
    }
  }
  // FAULT INJECTION (default none): on a tessellated draw, suppress the
  // PRE-EXISTING guest-index interval too. Measured on every VP frame, that
  // interval is byte-identical to the host factor-stream extent
  // (index_count == host_draw_vertex_count), so suppressing only the task-2.4
  // mutation leaves the consumer range fully covered and proves nothing. To
  // observe the staleness backstop at all, the consumer range has to actually
  // go missing.
  const bool suppress_consumer_range =
      use_tessellation_emulation &&
      MemexportRasterFault() != MetalMemexportRasterFault::kNone;
  if (index_buffer_info && index_buffer_info->guest_base && index_count &&
      !suppress_consumer_range) {
    uint32_t index_size_bytes =
        index_buffer_info->format == xenos::IndexFormat::kInt32 ? 4 : 2;
    vertex_dependency_ranges.Add(metal::GuestRange::FromBounds(
        index_buffer_info->guest_base,
        uint64_t(index_buffer_info->guest_base) +
            uint64_t(index_count) * index_size_bytes));
  }
  // extend-metal-rasterizing-memexport-producers task 2.4: same-frame consumer
  // ordering for the ONE consumer shape the existing vfetch/index request set
  // does not already cover. The gated tessellation route reads its
  // index/FACTOR stream directly from guest RAM at encode time, and its extent
  // is the HOST patch-stream extent (tess_pp.host_draw_vertex_count), not the
  // guest draw's index_count -- so the interval added above can under-cover it.
  // That stream is exactly what a rasterizing memexport producer writes
  // earlier in the same frame (VP: the geometry-emulated producer exports the
  // adaptive factor stream, the tessellated terrain draw consumes it two draws
  // later). Adding it here puts it through the SAME
  // QueryPendingProducerDependencies -> ResolvePendingProducerDependencies
  // barrier the depth-resolve writeback established, so convergence is proven
  // before the read or the draw fail-closed skips.
  //
  // Gated on XE_METAL_MEMEXPORT_RASTER: with the gate off nothing publishes
  // into these ranges, and keeping the request set byte-identical is what makes
  // the OFF arm bit-identical (an unconditional add would also start selecting
  // overlapping pending RESOLVES that the pre-change code never selected).
  bool memexport_raster_consumer_range = false;
  // Set when this draw's vertex or texture inputs were served by command
  // order against a pending memexport (kOrderAgainstGpuProducers): a routed
  // rasterizing producer in the SAME render encoder is not ordered by Metal's
  // hazard tracking, which works per encoder, so the draw needs an in-encoder
  // buffer barrier (see the encode below).
  bool ordered_against_memexport = false;
  auto note_memexport_ordering = [&](const metal::ConsumerDecision& decision) {
    if (decision.action !=
        metal::AuthorityAction::kOrderAgainstGpuProducers) {
      return;
    }
    for (const metal::PendingProducer& p : decision.selected) {
      if (p.state == metal::TransitState::kPendingMemexport) {
        ordered_against_memexport = true;
        return;
      }
    }
  };
  if (MetalMemexportRasterGateOn() && use_tessellation_emulation &&
      tess_pp.index_buffer_type ==
          ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kGuestDMA &&
      tess_pp.guest_index_base && tess_pp.host_draw_vertex_count) {
    // The HOST patch-stream extent, through the pure helper the L0 boundary
    // matrix pins (host > guest index_count is the under-covering case).
    //
    // KEPT DELIBERATELY THOUGH REDUNDANT ON ALL OBSERVED CONTENT (2026-08-02):
    // every VP tessellated draw has index_count == host_draw_vertex_count, so
    // the pre-existing guest-index interval already covers this stream —
    // measured by suppressing ONLY this mutation, which produced a
    // byte-identical image with zero stale skips. Retained for the host >
    // guest shape, which adaptive tessellation can produce because the host
    // patch stream is sized from host_draw_vertex_count rather than the guest
    // index count. Without it in that shape the read is uncovered and the
    // backstop below FAILS CLOSED — correct, but a dropped draw. With it the
    // barrier converges and the draw renders. One interval per tessellated
    // draw buys that.
    //
    // FAULT INJECTION (default none) breaks exactly this mutation so the
    // staleness backstop at the read site can be OBSERVED failing closed.
    const MetalMemexportRasterFault fault = MemexportRasterFault();
    uint32_t mutation_count = tess_pp.host_draw_vertex_count;
    if (fault == MetalMemexportRasterFault::kUndersizeTessRange) {
      mutation_count = 1;
    }
    metal::MetalGuestStreamExtent tess_extent =
        metal::ComputeMetalIndexStreamExtent(
            tess_pp.guest_index_base, mutation_count,
            tess_pp.host_index_format == xenos::IndexFormat::kInt32);
    auto tess_stream_range =
        (tess_extent.valid && fault != MetalMemexportRasterFault::kNoTessRange)
            ? metal::GuestRange::FromBaseLength(tess_extent.base,
                                                tess_extent.size)
            : std::nullopt;
    // Add the interval ONLY when the guest-index interval does not already
    // contain it. On today's VP content the two are byte-identical, so this
    // costs the request set nothing; the protection survives for the
    // host > guest expansion case, where containment fails and the interval is
    // the difference between a converged read and a fail-closed skip.
    const metal::MetalGuestStreamExtent guest_index_extent =
        (index_buffer_info && index_buffer_info->guest_base && index_count &&
         !suppress_consumer_range)
            ? metal::ComputeMetalIndexStreamExtent(
                  index_buffer_info->guest_base, index_count,
                  index_buffer_info->format == xenos::IndexFormat::kInt32)
            : metal::MetalGuestStreamExtent{};
    const bool already_covered =
        metal::MetalExtentContains(guest_index_extent, tess_extent);
    if (tess_stream_range && !already_covered) {
      vertex_dependency_ranges.Add(*tess_stream_range);
    }
    // The distinct fail-closed reason applies whenever the factor stream is
    // part of this consumer's request AT ALL -- whether it got there via the
    // guest-index interval or the addition above. The reason names the
    // investigation ("exported factors could not be proven converged"), not
    // which interval carried the range.
    memexport_raster_consumer_range =
        tess_stream_range != std::nullopt || already_covered;
  }
  vertex_dependency_ranges.Normalize();

  if (!vertex_dependency_ranges.empty() &&
      (!pending_writebacks_.empty() || !pending_memexports_.empty())) {
    // Vertex and index data are fetched from the shared buffer, so a pending
    // GPU-current resolve or memexport under the range only needs command
    // order, not a CPU wait-and-publish (the same Stage B ordering the
    // texture path declares; memexport output lands in the buffer at
    // execution time). XE_METAL_GPU_ORDERING=0 or XE_METAL_VERTEX_ORDERING=0
    // restore the pre-change RAM-domain request.
    static const bool s_vertex_ordering = [] {
      const char* g = std::getenv("XE_METAL_GPU_ORDERING");
      const char* v = std::getenv("XE_METAL_VERTEX_ORDERING");
      return !(g && g[0] == '0' && !g[1]) && !(v && v[0] == '0' && !v[1]);
    }();
    // Persistent scratch: the request's two range vectors keep their
    // capacity across draws instead of being allocated and freed per draw
    // (operator new / free were 3-4% of the command-processor thread in GTA
    // IV and Burnout, 2026-10-17 samples).
    metal::ConsumerRequest& vertex_request = vertex_request_scratch_;
    vertex_request.resolve_ranges = vertex_dependency_ranges;
    vertex_request.memexport_ranges = vertex_dependency_ranges;
    vertex_request.access = metal::ConsumerAccess::kGuestRam;
    vertex_request.order_memexport_producers = false;
    // The host tessellation route reads its index/factor stream from guest RAM
    // on the CPU (TranslatePhysical at encode time), not from the shared
    // buffer, so command order alone leaves a routed rasterizing producer's
    // factors unpublished and the staleness backstop skips the draw. Viva
    // Pinata's adaptive terrain dropped every frame this way with
    // XE_METAL_MEMEXPORT_RASTER=1 (title-screen ground missing, 29 draws per
    // frame). Such a request keeps the RAM-domain wait-and-publish.
    if (s_vertex_ordering && !memexport_raster_consumer_range) {
      vertex_request.access = metal::ConsumerAccess::kSharedBuffer;
      vertex_request.order_memexport_producers = true;
    }
    metal::ConsumerDecision authority_decision =
        QueryPendingProducerDependencies(metal::ConsumerKind::kVertex,
                                         vertex_request);
    note_memexport_ordering(authority_decision);
    // Consumer-attribution diagnostic (XE_METAL_MEMEXPORT_LOG=1, default off,
    // log only): names the CONSUMING draw for every exported range this
    // vertex/index read depends on -- the evidence task 1.1 needs to decide
    // whether a producer's destination has a same-frame consumer at all.
    if (s_memexport_log) {
      for (const metal::PendingProducer& producer : authority_decision.selected) {
        if (producer.state != metal::TransitState::kPendingMemexport) {
          continue;
        }
        REXLOG_WARN(
            "MetalMemexportConsumer draw={} kind=vertex range={:08X}(+{}) "
            "producer_seq={} await={}",
            trace_draw_index_, producer.range.start(), producer.range.length(),
            producer.sequence, authority_decision.await ? 1 : 0);
      }
    }
    ProducerDependencyOutcome dependency_outcome =
        ResolvePendingProducerDependencies(authority_decision);
    if (!dependency_outcome.complete) {
      REXLOG_ERROR(
          "MetalCommandProcessor: vertex dependency convergence retired {} "
          "of {} selected producers; skipping draw",
          dependency_outcome.drain.drained_records,
          authority_decision.selected.size());
      // Distinct reason when a routed rasterizing memexport range is part of
      // this consumer's request: "the exported factors could not be proven
      // converged before this read" is a different investigation from a
      // generic vertex-dependency drain failure.
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                     memexport_raster_consumer_range
                         ? "memexport-raster-consumer-drain"
                         : "vertex-dependency-drain");
      return true;
    }
  }

  // VB sentinel probe (XE_METAL_VB_SENTINEL=<draw>): overwrite the draw's
  // vertex floats with per-dword sentinels z = (w+1)*8 + 0.5 so a consumer
  // like frc(z*c254) encodes WHICH dword the translated vfetch actually
  // read into the output color (o1.y = (w+1)/8 + 0.0078 -> G ~= 7,15,22,
  // 29,36,44 * tex.a for w=0..5). Settles offset-vs-endian in the
  // light-VS zero-output hunt empirically.
  static const int64_t s_vb_sentinel = [] {
    const char* v = std::getenv("XE_METAL_VB_SENTINEL");
    return v ? strtoll(v, nullptr, 10) : -1ll;
  }();
  if (s_vb_sentinel >= 0 &&
      int64_t(trace_draw_index_) - 1 == s_vb_sentinel && vertex_shader) {
    for (const auto& vb : vertex_shader->GetVertexBindings()) {
      xenos::VertexFetch vf = regs.GetVertexFetch(vb.fetch_constant);
      uint32_t vaddr = vf.address << 2;
      uint32_t stride = vb.stride_words ? vb.stride_words : 4;
      if (!vaddr || !vf.size) continue;
      uint32_t* vdata = TranslateGuest<uint32_t*>(vaddr);
      uint32_t vcount = std::min<uint32_t>(vf.size / stride, 8);
      for (uint32_t vtx = 0; vtx < vcount; ++vtx) {
        // Keep dwords 0-2 (position) intact — sentinel only the tail
        // (uv/packed attributes) so the quad still rasterizes.
        for (uint32_t w = 3; w < stride && w < 8; ++w) {
          float sentinel = float(w + 1) * 8.0f + 0.5f;
          uint32_t bits;
          std::memcpy(&bits, &sentinel, 4);
          vdata[vtx * stride + w] =
              xenos::GPUSwap(bits, xenos::Endian(vf.endian));
        }
      }
      if (shared_memory_) {
        shared_memory_->RangeWrittenByGPU(vaddr, vf.size * 4);
      }
      REXLOG_WARN("MetalVBSentinel: draw {} fc={} addr={:08X} patched {} verts",
             s_vb_sentinel, vb.fetch_constant, vaddr, vcount);
    }
  }

  // Revalidate each exact vfetch interval only after all selected producer
  // records have converged to RAM and after the diagnostic writer above. This
  // is still before ::rex::gpu::RenderTargetCache::Update and BeginFrameEncoder, so both
  // CPU shader interpretation and the consuming Metal draw see the same bytes.
  static const char* s_log_vf = std::getenv("XE_METAL_LOG_VF");
  bool log_vf =
      s_log_vf &&
      vertex_shader->GetUcodeDataHash() == strtoull(s_log_vf, nullptr, 16);
  // DIAGNOSTIC (JC2 shadow-clear): XE_METAL_LOG_VF_DUMP=<vs hash> dumps the
  // index stream head and every non-zero 7-dword vertex of each vertex fetch
  // range for draws using that vertex shader (first 4 draws).
  static const char* s_log_vf_dump = std::getenv("XE_METAL_LOG_VF_DUMP");
  static uint32_t s_log_vf_dump_count = 0;
  if (s_log_vf_dump && s_log_vf_dump_count < 4 &&
      vertex_shader->GetUcodeDataHash() ==
          strtoull(s_log_vf_dump, nullptr, 16)) {
    ++s_log_vf_dump_count;
    std::string idx;
    if (index_buffer_info && index_buffer_info->guest_base) {
      const uint8_t* ib = TranslateGuest<const uint8_t*>(index_buffer_info->guest_base);
      bool i32 = index_buffer_info->format == xenos::IndexFormat::kInt32;
      for (uint32_t k = 0; k < std::min<uint32_t>(index_count, 8) && ib; ++k) {
        uint32_t v = 0;
        if (i32) {
          std::memcpy(&v, ib + k * 4, 4);
          v = rex::byte_swap(v);
        } else {
          uint16_t v16;
          std::memcpy(&v16, ib + k * 2, 2);
          v = rex::byte_swap(v16);
        }
        idx += fmt::format("{}{}", k ? "," : "", v);
      }
    }
    REXLOG_WARN("MetalVfDump draw={} prim={} index_count={} ib_base={:08X} idx=[{}] "
           "indx_offset={}",
           trace_draw_index_, uint32_t(prim_type), index_count,
           index_buffer_info ? index_buffer_info->guest_base : 0u, idx,
           regs.Get<uint32_t>(XE_GPU_REG_VGT_INDX_OFFSET));
    for (const VertexFetchDependency& dep : vertex_fetch_dependencies) {
      const uint8_t* vb = TranslateGuest<const uint8_t*>(dep.range.start());
      uint32_t bytes = uint32_t(dep.range.length());
      std::string dump;
      uint32_t shown = 0;
      for (uint32_t v = 0; (v + 1) * 28 <= bytes && shown < 12; ++v) {
        float fl[7];
        bool nz = false;
        for (uint32_t k = 0; k < 7; ++k) {
          uint32_t raw;
          std::memcpy(&raw, vb + v * 28 + k * 4, 4);
          raw = rex::byte_swap(raw);
          std::memcpy(&fl[k], &raw, 4);
          nz |= raw != 0;
        }
        if (!nz) continue;
        ++shown;
        dump += fmt::format(" v{}=({:g},{:g},{:g},{:g},{:g},{:g},{:g})", v,
                            fl[0], fl[1], fl[2], fl[3], fl[4], fl[5], fl[6]);
      }
      REXLOG_WARN("MetalVfDump   fc={} base={:08X} bytes={} endian={}:{}",
             dep.fetch_constant, dep.range.start(), bytes,
             uint32_t(dep.fetch.endian), dump);
    }
  }
  static uint32_t s_log_vf_count = 0;
  for (const VertexFetchDependency& dependency :
       vertex_fetch_dependencies) {
    if (log_vf && s_log_vf_count < 24) {
      ++s_log_vf_count;
      const uint32_t* words = reinterpret_cast<const uint32_t*>(
          TranslateGuest<const uint8_t*>(dependency.range.start()));
      uint32_t sampled_words[4] = {};
      if (words) {
        std::memcpy(sampled_words, words,
                    std::min<size_t>(dependency.range.length(),
                                     sizeof(sampled_words)));
      }
      REXLOG_WARN("MetalVF draw={} slot={} type={} addr={:08X} size_dw={} "
             "endian={} words={:08X} {:08X} {:08X} {:08X}",
             trace_draw_index_, dependency.fetch_constant,
             uint32_t(dependency.fetch.type), dependency.range.start(),
             uint32_t(dependency.fetch.size),
             uint32_t(dependency.fetch.endian), sampled_words[0],
             sampled_words[1], sampled_words[2], sampled_words[3]);
    }
    bool vertex_range_ok;
    if (MetalSharedMemory::VfetchRenameEnabled() && true) {
      MetalSharedMemory::VfetchRename rename;
      vertex_range_ok = shared_memory_->RequestVertexFetchRange(
          dependency.range.start(), dependency.range.length(), &rename);
      if (vertex_range_ok && rename.length) {
        draw_vfetch_renames_.push_back({dependency.fetch_constant,
                                        rename.guest_start, rename.length,
                                        rename.buffer_offset});
      }
    } else {
      vertex_range_ok = shared_memory_->RequestConsumedRange(
          dependency.range.start(), dependency.range.length());
    }
    if (!vertex_range_ok) {
      REXLOG_ERROR("MetalCommandProcessor: failed to validate vertex range "
             "{:08X}(+{})",
             dependency.range.start(), dependency.range.length());
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                     "vertex-range-validate");
      return true;
    }
  }
  draw_trace_milestone("after-vfetch");
  // Frame-trace recording: this backend reads guest indices directly from
  // RAM (not through shared memory), so record the range for replay. No-op
  // unless a trace file is open.
  if (index_buffer_info && index_buffer_info->guest_base && index_count) {
    uint32_t index_size_bytes =
        index_buffer_info->format == xenos::IndexFormat::kInt32 ? 4 : 2;
    (void)index_size_bytes;  // the SDK's trace writer, which recorded this read, no longer exists
  }
  // Base-class EDRAM ownership update: derives the RenderTargetKeys from the
  // registers, creates/accumulates the bound host RTs, and computes+executes
  // the ownership transfers this draw needs (stage 2 of the render chain).
  // Memexport-only draws touch no EDRAM: skip the update (the next normal
  // draw re-runs it) and the attachment checks below.
  // Predicated tiling (Canary e1f4a0d00): a whole-tile negative
  // PA_SC_WINDOW_OFFSET moves into the EDRAM bases so every tile rasterizes
  // at the same position as the full-surface depth prepass. The viewport,
  // scissor and PsParamGen then use window offset 0 (the shader adds the
  // offset back to PsParamGen). --window_offset_in_edram=false rolls back.
  const int32_t window_offset_tiles =
      (memexport_draw || pixel_export_only) ? 0
                     : render_target_cache_->GetWindowOffsetTiles(
                           regs, norm_depth, normalized_color_mask,
                           swap_count_);
  {
    // Census: which window offsets reach the EDRAM bases (in_base=1) and which
    // stay in the viewport (a wrapping base, an x offset, a 64bpp next-period
    // target or --window_offset_in_edram off).
    static const bool s_wo_census =
        std::getenv("XE_GPU_DELTA_CENSUS") != nullptr;
    auto window_offset = regs.Get<reg::PA_SC_WINDOW_OFFSET>();
    if (s_wo_census && !memexport_draw &&
        regs.Get<reg::PA_SU_SC_MODE_CNTL>().vtx_window_offset_enable &&
        (window_offset.window_x_offset || window_offset.window_y_offset)) {
      uint64_t n = DeltaCensusKeyedCount(
          4, uint64_t(window_offset.value) |
                 (uint64_t(window_offset_tiles != 0) << 32));
      if (DeltaCensusLogCount(n)) {
        REXLOG_INFO(
            "DeltaCensus window_offset_route draw={} x={} y={} in_base={} "
            "tiles={} count={} pitch_px={} msaa={} tile_h={} pitch_tiles={}",
            trace_draw_index_, int32_t(window_offset.window_x_offset),
            int32_t(window_offset.window_y_offset),
            window_offset_tiles != 0 ? 1 : 0, window_offset_tiles, n,
            regs.Get<reg::RB_SURFACE_INFO>().surface_pitch,
            uint32_t(regs.Get<reg::RB_SURFACE_INFO>().msaa_samples),
            int32_t(xenos::kEDRAMTileHeightSamples >>
                    uint32_t(regs.Get<reg::RB_SURFACE_INFO>().msaa_samples >=
                             xenos::MSAASamples::k2X)),
            (((uint32_t(regs.Get<reg::RB_SURFACE_INFO>().surface_pitch)
               << uint32_t(regs.Get<reg::RB_SURFACE_INFO>().msaa_samples >=
                           xenos::MSAASamples::k4X)) +
              (xenos::kEDRAMTileWidthSamples - 1)) /
             xenos::kEDRAMTileWidthSamples));
      }
    }
  }
  // A count-only ZPD draw rasterizes with no target of its own: the shared
  // cache then keeps the accumulated targets bound, as on D3D12 and Vulkan.
  if (!memexport_draw && !pixel_export_only &&
      !render_target_cache_->UpdateWithWindowOffset(
          color_bound || depth_bound || zpd_count_only_draw, norm_depth,
          normalized_color_mask, *vertex_shader, window_offset_tiles)) {
    RecordDrawSkip(MetalDrawSkipReason::kResourceFailure, "rt-cache-update");
    return true;
  }
  // A/B probe: XE_METAL_NO_SMALL_DEPTH=1 disables the depth test on
  // small-pitch (quarter-res lighting) draws to isolate the light buffer's
  // zero output (depth-test vs shader-math).
  static const bool s_no_small_depth = std::getenv("XE_METAL_NO_SMALL_DEPTH");
  if (s_no_small_depth && depth_bound &&
      regs.Get<reg::RB_SURFACE_INFO>().surface_pitch <= 400) {
    norm_depth.value = 0;
    depth_bound = false;
    if (!render_target_cache_->UpdateWithWindowOffset(color_bound, norm_depth,
                                      normalized_color_mask, *vertex_shader,
                                      window_offset_tiles)) {
      RecordDrawSkip(MetalDrawSkipReason::kDiagnosticRollback,
                     "rt-cache-update-nosmalldepth");
      return true;
    }
  }
  // The truth of what's bound now comes from the accumulated RTs.
  uint64_t color_pixel_formats[xenos::kMaxColorRenderTargets] = {};
  bool have_color = false;
  for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
    color_pixel_formats[i] = uint64_t(MTLPixelFormatInvalid);
    if (!memexport_draw &&
        render_target_cache_->current_color_texture(
            i, &color_pixel_formats[i]) != nullptr) {
      have_color = true;
    }
  }
  depth_bound = !memexport_draw && kDepthEnabled &&
                render_target_cache_->current_depth_texture() != nullptr;
  if (!have_color && !depth_bound && !memexport_draw && !pixel_export_only) {
    RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                   zpd_count_only_draw ? "zpd-count-no-targets"
                                       : "no-bound-targets");
    return true;
  }
  // Diagnostic: XE_METAL_PRECLEAR_RT=<trace draw index> clears the bound
  // color-0 RT to magenta right before encoding that draw. Combined with
  // XE_METAL_DUMP_RT on the same index, the post-draw dump shows the draw's
  // raster coverage exactly: any non-magenta pixel was written BY this draw.
  static const int64_t s_preclear_rt_at = [] {
    const char* v = std::getenv("XE_METAL_PRECLEAR_RT");
    return v ? strtoll(v, nullptr, 10) : -1ll;
  }();
  if (s_preclear_rt_at >= 0 &&
      int64_t(trace_draw_index_) - 1 == s_preclear_rt_at && have_color) {
    EndFrameEncoderAndWait(metal::SeamBoundaryReason::kDebugProbe);
    void* rt_ptr = render_target_cache_->current_color_texture(0, nullptr);
    if (rt_ptr) {
      __unsafe_unretained id<MTLCommandQueue> pq = (__bridge id<MTLCommandQueue>)
          static_cast<rex::ui::metal::MetalProvider*>(
              GetGraphicsDriver().GetProvider())->command_queue();
      id<MTLCommandBuffer> pcb = [pq commandBuffer];
      MTLRenderPassDescriptor* pd = [MTLRenderPassDescriptor renderPassDescriptor];
      pd.colorAttachments[0].texture = (__bridge id<MTLTexture>)rt_ptr;
      pd.colorAttachments[0].loadAction = MTLLoadActionClear;
      pd.colorAttachments[0].storeAction = MTLStoreActionStore;
      // Alpha 0 so post-draw alpha == the accumulated SRC alpha (additive
      // light passes: out = src*srcA + dst — separating "src small" from
      // "alpha small" in the zero-contribution hunt).
      pd.colorAttachments[0].clearColor = MTLClearColorMake(1.0, 0.0, 1.0, 0.0);
      id<MTLRenderCommandEncoder> pe = [pcb renderCommandEncoderWithDescriptor:metal::MetalApplyXenosSamplePositions(pd)];
      [pe endEncoding];
      [pcb commit];
      [pcb waitUntilCompleted];
      REXLOG_WARN("XE_METAL_PRECLEAR_RT: cleared RT to magenta before draw {}",
             s_preclear_rt_at);
    }
  }

  // Translate to MTLFunctions (cached per modification).
  auto sq_program_cntl = regs.Get<reg::SQ_PROGRAM_CNTL>();

  // Interpolator mask + PsParamGen destination: which VS-output interpolators
  // (texcoords etc.) the PS consumes, and whether the PS needs the
  // auto-generated pixel-position/point-coord register. This MUST be threaded
  // into BOTH shader modifications and MUST match between them, or the DXBC
  // translator wires VS outputs to PS inputs wrong -> scrambled/scaled texcoords
  // (the splash quad sampled only a sub-rect of its texture = the on-screen
  // zoom). Mirrors the D3D12 backend's UpdateBindings path exactly.
  uint32_t ps_param_gen_pos = UINT32_MAX;
  uint32_t interpolator_mask =
      pixel_shader ? (vertex_shader->GetWritesInterpolators() &
                      pixel_shader->GetInterpolatorInputMask(
                          sq_program_cntl, regs.Get<reg::SQ_CONTEXT_MISC>(),
                          ps_param_gen_pos))
                   : 0;
  // Unwritten-interpolator census (XE_GPU_INTERP_CENSUS=1, default off):
  // draws whose PS input range covers interpolators the VS never writes. The
  // translator feeds those zero (Canary D3D12 semantics); hardware leaves them
  // undefined. Logged per (VS, PS, masks) at power-of-two counts; each flagged
  // PS's disassembly is written once to XE_GPU_INTERP_CENSUS_DIR when set, so
  // reads-before-writes can be checked offline (the input range is register
  // count based, not a read set).
  {
    static const bool s_interp_census =
        std::getenv("XE_GPU_INTERP_CENSUS") != nullptr;
    if (s_interp_census && pixel_shader) {
      uint32_t census_pgp = UINT32_MAX;
      uint32_t ps_inputs = pixel_shader->GetInterpolatorInputMask(
          sq_program_cntl, regs.Get<reg::SQ_CONTEXT_MISC>(), census_pgp);
      uint32_t unwritten = ps_inputs & ~vertex_shader->GetWritesInterpolators();
      if (unwritten) {
        uint64_t key = vertex_shader->GetUcodeDataHash() ^
                       (pixel_shader->GetUcodeDataHash() * 31) ^
                       (uint64_t(ps_inputs) << 40) ^ unwritten;
        uint64_t count = DeltaCensusKeyedCount(0x7F, key);
        if (DeltaCensusLogCount(count)) {
          auto colorcontrol = regs.Get<reg::RB_COLORCONTROL>();
          auto depthcontrol = regs.Get<reg::RB_DEPTHCONTROL>();
          REXLOG_INFO(
              "InterpCensus draw={} count={} vs={:016X} ps={:016X} "
              "vs_writes={:X} ps_inputs={:X} unwritten={:X} kill={} "
              "tfetch={} alpha_test={} alpha_func={} z_write={} "
              "color_mask={:08X} prim={}",
              trace_draw_index_, count, vertex_shader->GetUcodeDataHash(),
              pixel_shader->GetUcodeDataHash(),
              vertex_shader->GetWritesInterpolators(), ps_inputs, unwritten,
              uint32_t(pixel_shader->DoesKillPixels()),
              pixel_shader->GetTextureBindings().size(),
              uint32_t(colorcontrol.alpha_test_enable),
              uint32_t(colorcontrol.alpha_func),
              uint32_t(depthcontrol.z_enable && depthcontrol.z_write_enable),
              regs[XE_GPU_REG_RB_COLOR_MASK], uint32_t(prim_type));
          static const char* s_census_dir =
              std::getenv("XE_GPU_INTERP_CENSUS_DIR");
          static std::unordered_set<uint64_t> s_dumped;
          if (s_census_dir &&
              s_dumped.insert(pixel_shader->GetUcodeDataHash()).second) {
            std::string path = fmt::format("{}/ps_{:016X}.txt", s_census_dir,
                                           pixel_shader->GetUcodeDataHash());
            if (FILE* f = std::fopen(path.c_str(), "w")) {
              std::fputs(pixel_shader->GetUcodeDisassembly().c_str(), f);
              std::fclose(f);
            }
          }
        }
      }
    }
  }
  // Diagnostic (2026-09-19): XE_METAL_IMASK_PS_ONLY=1 keeps every
  // interpolator the pixel shader reads even when the vertex shader writes
  // none (the VS declares and zero-fills them), so the PS variant matches
  // the one used when a VS does write them.
  static const bool s_imask_ps_only =
      std::getenv("XE_METAL_IMASK_PS_ONLY") != nullptr;
  if (s_imask_ps_only && pixel_shader) {
    interpolator_mask = pixel_shader->GetInterpolatorInputMask(
        sq_program_cntl, regs.Get<reg::SQ_CONTEXT_MISC>(), ps_param_gen_pos);
  }
  // metal_unwritten_interpolators: a VS that writes no interpolators with a PS
  // that reads some (RE5's second shadow-cascade clear runs the bound alpha
  // kill PS, which at zero kills the whole clear) gets the PS's inputs wired
  // and filled with 0.5 by the VS. Only position-only VSes: every real read
  // in the 2026-10-13 census (interp-census-20261013) was one.
  bool fill_unwritten_interpolators = false;
  if (pixel_shader && !vertex_shader->GetWritesInterpolators() &&
      UnwrittenInterpolatorFillEnabled()) {
    uint32_t ps_inputs = pixel_shader->GetInterpolatorInputMask(
        sq_program_cntl, regs.Get<reg::SQ_CONTEXT_MISC>(), ps_param_gen_pos);
    if (ps_inputs) {
      interpolator_mask = ps_inputs;
      fill_unwritten_interpolators = true;
    }
  }

  // Tessellated draws translate the guest VS as the DOMAIN shader the shared
  // processor chose (ProcessingResult::host_vertex_shader_type — task 4.1
  // consumes it, never re-derives); everything else stays kVertex.
  ::rex::gpu::DXBCShaderTranslator::Modification vs_mod_decoded(
      pipeline_cache_->shader_translator()->GetDefaultVertexShaderModification(
          vertex_shader->GetDynamicAddressableRegisterCount(
              sq_program_cntl.vs_num_reg),
          use_tessellation_emulation ? tess_pp.host_vertex_shader_type
          : point_strip_route
              ? ::rex::gpu::Shader::HostVertexShaderType::kPointListAsTriangleStrip
          : rect_strip_route
              ? ::rex::gpu::Shader::HostVertexShaderType::kRectangleListAsTriangleStrip
              : ::rex::gpu::Shader::HostVertexShaderType::kVertex));
  vs_mod_decoded.vertex.interpolator_mask = interpolator_mask;
  vs_mod_decoded.vertex.fill_unwritten_interpolators =
      fill_unwritten_interpolators ? 1 : 0;
  // Host tessellation route: the guest VS is translated as a VERTEX shader
  // that reads its domain registers from the host-generated record stream
  // (dxbc_shader_translator.h Modification::vertex.domain_as_vertex).
  vs_mod_decoded.vertex.domain_as_vertex = use_tessellation_emulation ? 1 : 0;
  {
    static const bool s_imask_log = std::getenv("XE_METAL_IMASK_LOG") != nullptr;
    static uint32_t s_imask_logs = 0;
    if (s_imask_log && s_imask_logs < 64 && pixel_shader) {
      ++s_imask_logs;
      REXLOG_WARN("MetalInterp draw={} vs={:016X} ps={:016X} vs_writes={:X} ps_input={:X} "
             "mask={:X} pgen={} ps_num_reg={} vs_num_reg={}",
             trace_draw_index_, vertex_shader->GetUcodeDataHash(),
             pixel_shader->GetUcodeDataHash(),
             vertex_shader->GetWritesInterpolators(),
             pixel_shader->GetInterpolatorInputMask(
                 sq_program_cntl, regs.Get<reg::SQ_CONTEXT_MISC>(),
                 ps_param_gen_pos),
             interpolator_mask, ps_param_gen_pos,
             uint32_t(sq_program_cntl.ps_num_reg),
             uint32_t(sq_program_cntl.vs_num_reg));
    }
  }
  {
    auto pa_cl_clip_cntl = regs.Get<reg::PA_CL_CLIP_CNTL>();
    uint32_t user_clip_planes =
        pa_cl_clip_cntl.clip_disable ? 0 : pa_cl_clip_cntl.ucp_ena;
    vs_mod_decoded.vertex.user_clip_plane_count =
        ::rex::BitCount(user_clip_planes);
    vs_mod_decoded.vertex.user_clip_plane_cull =
        uint32_t(user_clip_planes && pa_cl_clip_cntl.ucp_cull_only_ena);
    vs_mod_decoded.vertex.vertex_kill_and = uint32_t(
        (vertex_shader->GetWritesPointSizeEdgeFlagKillVertex() & 0b100) &&
        !pa_cl_clip_cntl.vtx_kill_or);
    // Metal has no cull distances: the Metal Shader Converter output never
    // culls on SV_CullDistance, so AND-mode vertex kill (and cull-only user
    // clip planes) culled nothing. Banjo-Kazooie: Nuts & Bolts kills each
    // grass tuft whose density-map texel is below its threshold this way;
    // without it every tuft drew, covering Spiral Mountain's dirt path and
    // its flowers. Emit them as clip distances instead. The geometry shader
    // path culls in its generated shader already. XE_METAL_CULL_AS_CLIP=0
    // restores the old, non-culling output; =2 is a diagnostic arm that kills
    // AND-mode vertices with the OR operator instead (a NaN position: any
    // killed vertex drops the primitive).
    static const uint32_t s_cull_as_clip = [] {
      const char* v = std::getenv("XE_METAL_CULL_AS_CLIP");
      if (v && !v[1] && (v[0] == '0' || v[0] == '2')) {
        return uint32_t(v[0] - '0');
      }
      return 1u;
    }();
    if (s_cull_as_clip == 2 && !use_geometry_emulation) {
      vs_mod_decoded.vertex.vertex_kill_and = 0;
    }
    vs_mod_decoded.vertex.cull_distances_as_clip =
        uint32_t(s_cull_as_clip == 1 && !use_geometry_emulation &&
                 vs_mod_decoded.GetVertexCullDistanceCount() != 0);
    if (vs_mod_decoded.vertex.cull_distances_as_clip) {
      // Engagement evidence (bounded): which vertex shaders take the route.
      static uint32_t s_cull_as_clip_logs = 0;
      if (s_cull_as_clip_logs < 8) {
        ++s_cull_as_clip_logs;
        REXLOG_INFO(
            "MetalCullAsClip: vs={:016X} vertex_kill_and={} ucp_cull={} "
            "planes={} at draw {}",
            vertex_shader->GetUcodeDataHash(),
            uint32_t(vs_mod_decoded.vertex.vertex_kill_and),
            uint32_t(vs_mod_decoded.vertex.user_clip_plane_cull),
            uint32_t(vs_mod_decoded.vertex.user_clip_plane_count),
            trace_draw_index_);
      }
    }
    // XEPSIZE feeds the geometry-emulation mesh stage only; the vertex-shader
    // point expansion consumes the size inside the vertex shader and writes
    // the sprite coordinates the pixel shader's point PsParamGen reads.
    vs_mod_decoded.vertex.output_point_size = uint32_t(
        (vertex_shader->GetWritesPointSizeEdgeFlagKillVertex() & 0b001) &&
        !point_strip_route &&
        regs.Get<reg::VGT_DRAW_INITIATOR>().prim_type ==
            xenos::PrimitiveType::kPointList);
    vs_mod_decoded.vertex.output_point_coordinates = uint32_t(
        point_strip_route && ps_param_gen_pos < xenos::kMaxInterpolators);
  }
  uint64_t vs_mod = vs_mod_decoded.value;
  auto* vs_translation = static_cast<MetalShader::MetalTranslation*>(
      vertex_shader->GetOrCreateTranslation(vs_mod));
  // Background pipelines (::rex::graphics::metal::GetMetalSettings().metal_async_pipelines.Get()): the pipeline step below
  // translates, on a worker when the draw may use a stand-in. Not for traces,
  // memexport-only draws or geometry emulation.
  const bool async_pipelines = MetalPipelineCache::AsyncPipelinesEnabled() &&
                               true &&
                               true && !memexport_draw &&
                               !use_geometry_emulation && !kDebugSolidFragment;
  if (!async_pipelines && !pipeline_cache_->TranslateShader(*vs_translation)) {
    RecordDrawSkip(MetalDrawSkipReason::kTranslationFailure, "vs-translate");
    return true;
  }
  MetalShader::MetalTranslation* ps_translation = nullptr;
  uint64_t ps_mod_value = 0;
  if (pixel_shader) {
    ::rex::gpu::DXBCShaderTranslator::Modification ps_mod_decoded(
        pipeline_cache_->shader_translator()->GetDefaultPixelShaderModification(
            pixel_shader->GetDynamicAddressableRegisterCount(
                sq_program_cntl.ps_num_reg)));
    ps_mod_decoded.pixel.interpolator_mask = interpolator_mask;
    // Plain-unsigned fetch variant: certify, from the bound fetch constants,
    // that no sampled component is signed, biased or gamma, so the translator
    // omits the per-component decode switch after every fetch (a third of
    // Far Cry 3's fragment time). XE_METAL_FETCH_SPECIALIZE=0 keeps one
    // variant with the full decode.
    static const bool s_fetch_specialize = [] {
      const char* v = std::getenv("XE_METAL_FETCH_SPECIALIZE");
      return !(v && v[0] == '0' && !v[1]);
    }();
    if (s_fetch_specialize) {
      // The shader's sampled fetch constants, as a bit mask (cached per
      // shader); then the plain bits, refreshed only for constants written
      // since the last look.
      uint32_t fetch_mask;
      {
        auto it = pixel_shader_fetch_masks_.find(pixel_shader->GetUcodeDataHash());
        if (it == pixel_shader_fetch_masks_.end()) {
          fetch_mask = 0;
          for (const auto& binding : pixel_shader->GetTextureBindings()) {
            if (binding.fetch_constant < 32) {
              fetch_mask |= 1u << binding.fetch_constant;
            }
          }
          pixel_shader_fetch_masks_.emplace(pixel_shader->GetUcodeDataHash(),
                                            fetch_mask);
        } else {
          fetch_mask = it->second;
        }
      }
      uint32_t unknown = fetch_mask & ~fetch_plain_known_mask_;
      uint32_t slot;
      while (rex::bit_scan_forward(unknown, &slot)) {
        unknown = ((unknown) & ((unknown) - 1));
        const auto f = regs.GetTextureFetch(slot);
        // What the shader would read for this constant: the swizzled sign
        // byte, the integer scale bits under those signs, the exponent bias.
        MetalShader::FetchStaticInfo& info = fetch_static_info_[slot];
        info.swizzled_signs = ::rex::xenos::SwizzleSigns(f);
        info.integer_scale_bits =
            texture_integer_scale::IntegerScaleBits(f, info.swizzled_signs);
        if (::rex::graphics::metal::GetMetalSettings().dxbc_implicit_lod.Get()) {
          info.integer_scale_bits |= SnapMipsBit(f, info.integer_scale_bits);
        }
        info.exp_adjust = int8_t(f.exp_adjust);
        bool plain = true;
        for (uint32_t c = 0; c < 4; ++c) {
          const uint32_t sign = (info.swizzled_signs >> (c * 2)) & 3;
          if (sign == uint32_t(xenos::TextureSign::kUnsignedBiased) ||
              sign == uint32_t(xenos::TextureSign::kGamma)) {
            plain = false;
          }
        }
        fetch_plain_mask_ = plain ? (fetch_plain_mask_ | (1u << slot))
                                  : (fetch_plain_mask_ & ~(1u << slot));
        fetch_plain_known_mask_ |= 1u << slot;
      }
      const uint32_t plain_mask = fetch_mask & fetch_plain_mask_;
      uint32_t pattern = 0;
      if (fetch_mask) {
        MetalShader::FetchPattern fp = {};
        fp.fetch_mask = fetch_mask;
        uint32_t bits = fetch_mask;
        while (rex::bit_scan_forward(bits, &slot)) {
          bits = ((bits) & ((bits) - 1));
          fp.info[slot] = fetch_static_info_[slot];
        }
        pattern = static_cast<MetalShader*>(pixel_shader)->FindOrAddFetchPattern(fp);
      }
      uint32_t static_mask = 0;
      {
        uint32_t bits = fetch_mask;
        while (rex::bit_scan_forward(bits, &slot)) {
          bits = ((bits) & ((bits) - 1));
          const MetalShader::FetchStaticInfo& info = fetch_static_info_[slot];
          if (info.swizzled_signs == 0 && info.exp_adjust == 0 &&
              (info.integer_scale_bits & ((1u << 26) - 1)) == 0) {
            static_mask |= 1u << slot;
          }
        }
      }
      ps_mod_decoded.pixel.fetch_plain_pattern = pattern;
      static uint64_t s_ps_draws = 0, s_pattern_draws = 0, s_fetch_bits = 0,
                      s_plain_bits = 0, s_static_bits = 0, s_table_full = 0;
      ++s_ps_draws;
      s_fetch_bits += ::rex::BitCount(fetch_mask);
      if (pattern) {
        ++s_pattern_draws;
        s_plain_bits += ::rex::BitCount(plain_mask);
        s_static_bits += ::rex::BitCount(static_mask);
      } else if (fetch_mask) {
        ++s_table_full;
      }
      if ((s_ps_draws & 65535) == 0) {
        REXLOG_INFO(
            "MetalFetchSpecialize ps draws={} with-pattern={} ({:.1f}%) "
            "plain fetches {}/{} ({:.1f}%) static-unsigned {} ({:.1f}%) "
            "table-full={}",
            s_ps_draws, s_pattern_draws,
            100.0 * double(s_pattern_draws) / double(s_ps_draws),
            s_plain_bits, s_fetch_bits,
            s_fetch_bits ? 100.0 * double(s_plain_bits) / double(s_fetch_bits)
                         : 0.0,
            s_static_bits,
            s_fetch_bits ? 100.0 * double(s_static_bits) / double(s_fetch_bits)
                         : 0.0,
            s_table_full);
      }
    }
    // A/B: XE_METAL_NO_CENTROID=1 forces center sampling. Gameplay surfaces are
    // 4x MSAA (menus 1x), and at 4x the PS modification requests CENTROID
    // interpolation on some inputs — if MSC mis-links centroid-decorated PS
    // inputs against the (non-centroid) VS outputs, lighting interpolators read
    // garbage.
    static const bool s_no_centroid = std::getenv("XE_METAL_NO_CENTROID");
    ps_mod_decoded.pixel.interpolators_centroid =
        s_no_centroid ? 0
                      : (interpolator_mask &
                         ~xenos::GetInterpolatorSamplingPattern(
                             regs.Get<reg::RB_SURFACE_INFO>().msaa_samples,
                             regs.Get<reg::SQ_CONTEXT_MISC>().sc_sample_cntl,
                             regs.Get<reg::SQ_INTERPOLATOR_CNTL>()
                                 .sampling_pattern));
    if (ps_param_gen_pos < xenos::kMaxInterpolators) {
      ps_mod_decoded.pixel.param_gen_enable = 1;
      ps_mod_decoded.pixel.param_gen_interpolator = ps_param_gen_pos;
      ps_mod_decoded.pixel.param_gen_point =
          uint32_t(regs.Get<reg::VGT_DRAW_INITIATOR>().prim_type ==
                   xenos::PrimitiveType::kPointList);
    }
    // RT0 MIN/MAX blend with a source factor (as D3D12's pipeline cache): the
    // Xbox 360 applies blend factors to MIN/MAX but Metal, like D3D12,
    // ignores them, so with SrcAlpha / One the pixel shader premultiplies its
    // RT0 output by source alpha. kOne (no premultiply) otherwise; a zeroed
    // modification would mean kZero, forcing RT0 to black.
    ps_mod_decoded.pixel.rt0_blend_rgb_factor_for_premult =
        uint32_t(xenos::BlendFactor::kOne);
    ps_mod_decoded.pixel.rt0_blend_a_factor_for_premult =
        uint32_t(xenos::BlendFactor::kOne);
    if (pixel_shader->IsColorTargetWritten(0)) {
      auto blend_control = regs.Get<reg::RB_BLENDCONTROL>(
          xenos::compat::BlendControlRegisterIndex(0));
      if ((blend_control.color_comb_fcn == xenos::BlendOp::kMin ||
           blend_control.color_comb_fcn == xenos::BlendOp::kMax) &&
          blend_control.color_srcblend == xenos::BlendFactor::kSrcAlpha &&
          blend_control.color_destblend == xenos::BlendFactor::kOne) {
        ps_mod_decoded.pixel.rt0_blend_rgb_factor_for_premult =
            uint32_t(xenos::BlendFactor::kSrcAlpha);
      }
      if ((blend_control.alpha_comb_fcn == xenos::BlendOp::kMin ||
           blend_control.alpha_comb_fcn == xenos::BlendOp::kMax) &&
          blend_control.alpha_srcblend == xenos::BlendFactor::kSrcAlpha &&
          blend_control.alpha_destblend == xenos::BlendFactor::kOne) {
        ps_mod_decoded.pixel.rt0_blend_a_factor_for_premult =
            uint32_t(xenos::BlendFactor::kSrcAlpha);
      }
    }
    // Stage A (implement-metal-depth-semantics): float24 depth invariance.
    // Without XE_METAL_F24_PS, the shared depth_float24_convert_in_pixel_shader
    // cvar drives it directly (kCvarDriven honors depth_float24_round too).
    // XE_METAL_F24_PS, when set, is authoritative over the shared cvars: 0
    // force-disables even a true cvar; 1 re-enables cvar-driven behavior;
    // trunc / round force a mode; anything else fails closed to off with a
    // one-shot warning. Engaged only when a 20e4 (kD24FS8) depth target is
    // actually bound, so kD24S8 titles get zero new pipeline permutations.
    // MSC acceptance of both modes proven by task 1.1
    // (xenia-gpu-metal-float24-conformance); early-Z survival of the
    // truncating form is measured, not assumed (task 2.4).
    static const bool s_early_hint = [] {
      const char* value = std::getenv("XE_METAL_EARLY_HINT");
      return !value || std::strcmp(value, "0") != 0;
    }();
    // Diagnostic (XE_METAL_EARLY_HINT_DRAWS=<first>-<last>): the hint only
    // inside the draw range (as XE_METAL_DRAW_TRACE counts).
    static const std::pair<int64_t, int64_t> s_early_hint_draws = [] {
      const char* v = std::getenv("XE_METAL_EARLY_HINT_DRAWS");
      if (!v) {
        return std::pair<int64_t, int64_t>(INT64_MIN, INT64_MAX);
      }
      char* end;
      int64_t first = strtoll(v, &end, 10);
      int64_t last = *end == '-' ? strtoll(end + 1, nullptr, 10) : first;
      return std::pair<int64_t, int64_t>(first, last);
    }();
    const bool early_hint_in_range =
        int64_t(trace_draw_index_) - 1 >= s_early_hint_draws.first &&
        int64_t(trace_draw_index_) - 1 <= s_early_hint_draws.second;
    // Which early-hint draws keep the alpha test code, so that the function
    // has a discard and is shaded per triangle (the modification's
    // early_hint_keep_alpha_test): blended draws by default.
    // XE_METAL_EARLY_HINT_PER_PRIMITIVE=all: every hinted draw; =none: no
    // draw (as before 2026-11-10); =nohint: no hint for blended draws.
    enum class EarlyHintPerPrimitive { kBlended, kAll, kNone, kNoHint };
    static const EarlyHintPerPrimitive s_early_hint_per_primitive = [] {
      const char* value = std::getenv("XE_METAL_EARLY_HINT_PER_PRIMITIVE");
      if (!value) {
        return EarlyHintPerPrimitive::kBlended;
      }
      if (!std::strcmp(value, "all")) {
        return EarlyHintPerPrimitive::kAll;
      }
      if (!std::strcmp(value, "none")) {
        return EarlyHintPerPrimitive::kNone;
      }
      if (!std::strcmp(value, "nohint")) {
        return EarlyHintPerPrimitive::kNoHint;
      }
      return EarlyHintPerPrimitive::kBlended;
    }();
    // A colour target the draw writes with anything but a plain replace.
    bool early_hint_blended = false;
    for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
      if (!((normalized_color_mask >> (i * 4)) & 0xFu)) {
        continue;
      }
      auto blend = regs.Get<reg::RB_BLENDCONTROL>(
          xenos::compat::BlendControlRegisterIndex(i));
      if (blend.color_srcblend != xenos::BlendFactor::kOne ||
          blend.color_destblend != xenos::BlendFactor::kZero ||
          blend.color_comb_fcn != xenos::BlendOp::kAdd ||
          blend.alpha_srcblend != xenos::BlendFactor::kOne ||
          blend.alpha_destblend != xenos::BlendFactor::kZero ||
          blend.alpha_comb_fcn != xenos::BlendOp::kAdd) {
        early_hint_blended = true;
        break;
      }
    }
    static const MetalF24PsMode s_f24_mode = [=] {
      const char* value = std::getenv("XE_METAL_F24_PS");
      MetalF24PsMode mode = EffectiveMetalF24PsMode(
          value, ::rex::graphics::metal::GetMetalSettings().depth_float24_convert_in_pixel_shader.Get());
      if (mode == MetalF24PsMode::kMalformed) {
        REXLOG_WARN("XE_METAL_F24_PS='{}' is malformed; failing closed to off "
               "(use 1, trunc, or round)",
               value);
        return MetalF24PsMode::kOff;
      }
      return mode;
    }();
    if (MetalF24PsEngaged(s_f24_mode) && depth_bound &&
        regs.Get<reg::RB_DEPTH_INFO>().depth_format ==
            xenos::DepthRenderTargetFormat::kD24FS8) {
      bool round_mode =
          s_f24_mode == MetalF24PsMode::kRounding ||
          (s_f24_mode == MetalF24PsMode::kCvarDriven &&
           ::rex::graphics::metal::GetMetalSettings().depth_float24_round.Get());
      ps_mod_decoded.pixel.depth_stencil_mode =
          round_mode ? ::rex::gpu::DXBCShaderTranslator::Modification::DepthStencilMode::
                           kFloat24Rounding
                     : ::rex::gpu::DXBCShaderTranslator::Modification::DepthStencilMode::
                           kFloat24Truncating;
      // One-shot engagement evidence for headless/live A/B: without this, a
      // pixel-identical run cannot distinguish "engaged and invariant" from
      // "gate never fired".
      static bool s_f24_logged = false;
      if (!s_f24_logged) {
        s_f24_logged = true;
        REXLOG_INFO("MetalF24: engaged mode={} at draw {}",
               round_mode ? "round" : "trunc", trace_draw_index_);
      }
    } else if (s_early_hint && early_hint_in_range &&
               !(early_hint_blended && s_early_hint_per_primitive ==
                                           EarlyHintPerPrimitive::kNoHint) &&
               !pixel_shader->IsDepthWritten() &&
               (!pixel_shader->IsColorTargetWritten(0) ||
                !::rex::gpu::draw_state::IsCoverageAlphaDependent(
                    regs.Get<reg::RB_COLORCONTROL>()))) {
      // The D3D12 rule (d3d12/pipeline_cache.cc): no kill, depth write,
      // memexport or alpha-dependent coverage -> [earlydepthstencil], and the
      // translator drops the dynamic alpha test and alpha-to-coverage code
      // (a static discard and an SV_Coverage write in every colour-writing
      // shader otherwise, which keeps Apple's hidden-surface removal and
      // early depth off for the whole draw). Default on; XE_METAL_EARLY_HINT=0
      // disables it. It moves 4x-MSAA blend results by +-1 LSB on silhouettes
      // (RDR 8111 draw 104: blended 8888 samples round differently once the
      // function stops writing [[sample_mask]]). M4 2026-10-22: Mafia II
      // 80.8 -> 102.7 fps, GTA IV 50.5 -> 52.9, 47-title sweep unchanged
      // otherwise.
      ps_mod_decoded.pixel.depth_stencil_mode =
          ::rex::gpu::DXBCShaderTranslator::Modification::DepthStencilMode::kEarlyHint;
      // Blended draws keep the alpha test code: a function without a
      // discard is shaded once per pixel across the draw's triangles on
      // Apple GPUs, which gave RDR's hair cards (alpha blended, 2x MSAA)
      // the wrong mip level and alpha where cards meet (2026-11-10).
      ps_mod_decoded.pixel.early_hint_keep_alpha_test =
          s_early_hint_per_primitive == EarlyHintPerPrimitive::kAll ||
          (early_hint_blended &&
           s_early_hint_per_primitive == EarlyHintPerPrimitive::kBlended);
    }
    uint64_t ps_mod = ps_mod_decoded.value;
    ps_mod_value = ps_mod;
    ps_translation = static_cast<MetalShader::MetalTranslation*>(
        pixel_shader->GetOrCreateTranslation(ps_mod));
    if (!async_pipelines && !pipeline_cache_->TranslateShader(*ps_translation)) {
      ps_translation = nullptr;
    }
  }

  void* pipeline;
  // Guest PS exports depth but this draw binds no depth target (z + stencil
  // disabled). Metal rejects a depth-writing fragment function without a
  // depth attachment — the draw used to NULL-PIPELINE skip (Sonic's
  // fullscreen bloom composite 1088: skipped -> the resolve exported stale
  // mip debris = the top-band scramble). Attach a scratch throwaway depth
  // target instead; the default encoder depth state (test Always, write off)
  // gives hardware semantics: with z disabled, oDepth is ignored.
  // XE_METAL_NO_DUMMY_DEPTH=1 restores the old NULL-PIPELINE skip for A/B
  // (e.g. Sonic: the skip hid a white-out from bad composite inputs).
  static const bool s_no_dummy_depth =
      std::getenv("XE_METAL_NO_DUMMY_DEPTH") != nullptr;
  // A pixel-export-only draw always carries the scratch depth: its pass has
  // no other attachment to rasterize against.
  bool dummy_depth =
      pixel_export_only ||
      (!s_no_dummy_depth && pixel_shader && pixel_shader->IsDepthWritten() &&
       !(kDepthEnabled && depth_bound));
  uint64_t pipeline_depth_format =
      ((kDepthEnabled && depth_bound) || dummy_depth)
          ? MetalRenderTargetCache::kDepthFormat
          : uint64_t(MTLPixelFormatInvalid);
  uint32_t blend_controls[xenos::kMaxColorRenderTargets] = {};
  for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
    blend_controls[i] =
        regs.Get<reg::RB_BLENDCONTROL>(
                xenos::compat::BlendControlRegisterIndex(i))
            .value;
  }
  // D2 (reduce-metal-draw-pass-traffic, metal_pass_attachment_use.h): the
  // attachments present in the accumulated set, the subset this draw can
  // touch, and the set its pass binds (the open same-key pass's set when it
  // covers the draw, else the union: hysteresis splits once per transition).
  // The pipeline declares exactly the bound set, as it declares the present
  // set under the legacy policy (unwritten targets keep a zero write mask).
  uint32_t pass_present = 0;
  for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
    if (color_pixel_formats[i] != uint64_t(MTLPixelFormatInvalid)) {
      pass_present |= metal::MetalPassColorAttachmentBit(i);
    }
  }
  if (kDepthEnabled && depth_bound) {
    pass_present |= metal::kMetalPassAttachmentDepthStencil;
  }
  uint32_t pass_bound = pass_present;
  if (PassAttachmentsByUseEnabled() && !memexport_draw && !pixel_export_only) {
    metal::MetalPassAttachmentUse use = metal::GetMetalPassAttachmentUse(
        norm_depth, normalized_color_mask, blend_controls,
        regs[XE_GPU_REG_RB_STENCILREFMASK],
        regs[XE_GPU_REG_RB_STENCILREFMASK_BF],
        pixel_shader && pixel_shader->IsDepthWritten());
    uint32_t used = use.used();
    if (used & metal::kMetalPassAttachmentStencil) {
      // The combined Depth32Float_Stencil8 texture binds its stencil plane
      // only alongside its depth plane.
      used |= metal::kMetalPassAttachmentDepth;
    }
    used &= pass_present;
    // Attribution aid: XE_METAL_PASS_STENCIL_KEEP=<mode> re-adds the stencil
    // plane for a class of depth-using draws (1: draws using a colour target,
    // 2: draws using none, 3: depth-writing draws, 4: depth-read-only draws).
    static const int s_stencil_keep = [] {
      const char* v = std::getenv("XE_METAL_PASS_STENCIL_KEEP");
      return v ? atoi(v) : 0;
    }();
    if (s_stencil_keep && (used & metal::kMetalPassAttachmentDepth)) {
      bool colour = (used & ~metal::kMetalPassAttachmentDepthStencil) != 0;
      bool zwrite = (use.writes & metal::kMetalPassAttachmentDepth) != 0;
      if ((s_stencil_keep == 1 && colour) || (s_stencil_keep == 2 && !colour) ||
          (s_stencil_keep == 3 && zwrite) || (s_stencil_keep == 4 && !zwrite)) {
        used |= metal::kMetalPassAttachmentStencil & pass_present;
      }
    }
    if (used) {
      // Learned set for this key (see pass_learned_use_): the pass binds what
      // any draw under the key has ever used, so a steady-state frame has no
      // "attachment needed" splits. XE_METAL_PASS_ATTACHMENTS_HYSTERESIS=1
      // binds the running union instead (the design's original D2, split per
      // transition; attribution only).
      static const bool s_hysteresis_only = [] {
        const char* v = std::getenv("XE_METAL_PASS_ATTACHMENTS_HYSTERESIS");
        return v && v[0] == '1' && v[1] == '\0';
      }();
      const uint64_t key = PassAttachmentKey(dummy_depth, false);
      const bool same_key_open = frame_open_ && encoder_attachment_key_ == key;
      // Pass signature: the open pass's when this draw joins it, else the key
      // mixed with this (first) draw's shader pair.
      uint64_t signature = same_key_open ? encoder_pass_signature_ : key;
      if (!same_key_open) {
        signature ^= (vertex_shader ? vertex_shader->GetUcodeDataHash() : 0) *
                     0x9E3779B97F4A7C15ull;
        signature ^= (pixel_shader ? pixel_shader->GetUcodeDataHash() : 0) *
                     0xC2B2AE3D27D4EB4Full;
      }
      pending_pass_signature_ = signature;
      if (!s_hysteresis_only) {
        uint32_t* learned = pass_learned_use_.Find(signature);
        if (learned) {
          *learned |= used;
          used = *learned & pass_present;
        } else {
          pass_learned_use_.Insert(signature, used, false);
        }
      }
      // A draw that touches nothing present keeps the legacy set (a pass needs
      // an attachment; the census counts how often this happens).
      metal::MetalPassBindingDecision decision = metal::DecideMetalPassBinding(
          pass_present, used, same_key_open, encoder_bound_attachments_);
      pass_bound = decision.bound;
    } else if (zpd_count_only_draw && frame_open_ &&
               encoder_attachment_key_ ==
                   PassAttachmentKey(dummy_depth, false) &&
               (encoder_bound_attachments_ & pass_present)) {
      // A count-only ZPD draw touches no attachment: join the open pass with
      // the set it already binds rather than splitting it for the legacy set.
      pass_bound = encoder_bound_attachments_ & pass_present;
    }
    // Attribution aid: XE_METAL_PASS_ATTACHMENTS_DROPPABLE=<hex set> limits
    // which attachments by-use binding may leave unbound (bits: 1 depth,
    // 2 stencil, 4.. colour 0..3); the rest stay bound as under legacy.
    static const uint32_t s_droppable = [] {
      const char* v = std::getenv("XE_METAL_PASS_ATTACHMENTS_DROPPABLE");
      return v ? uint32_t(strtoul(v, nullptr, 16)) : metal::kMetalPassAttachmentAll;
    }();
    pass_bound |= pass_present & ~s_droppable;
    for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
      if (!(pass_bound & metal::MetalPassColorAttachmentBit(i))) {
        color_pixel_formats[i] = uint64_t(MTLPixelFormatInvalid);
      }
    }
    if (!(pass_bound & metal::kMetalPassAttachmentDepth)) {
      if (!dummy_depth) {
        pipeline_depth_format = uint64_t(MTLPixelFormatInvalid);
      }
    } else if (!(pass_bound & metal::kMetalPassAttachmentStencil)) {
      pipeline_depth_format |= MetalPipelineCache::kDepthWithoutStencilBit;
    }
  }
  // A deferred pipeline request (::rex::graphics::metal::GetMetalSettings().metal_async_pipelines.Get()): `pipeline` points at
  // it and the encoder thread resolves it.
  std::shared_ptr<void> deferred_pipeline;
  // Geometry-emulation config (VS output size + GS max input primitives per mesh
  // threadgroup), filled by the geometry pipeline and passed to the draw call.
  uint32_t gs_vertex_size = 0;
  uint32_t gs_max_input_primitives = 0;
  // The pipeline sample count must exactly match the selected raster working
  // views. The default and sample-only gates remain single-sample; task 4.1's
  // strict raster gate selects the common real 2x/4x attachment count.
  MetalPipelineRasterState pipeline_raster_state =
      GetMetalPipelineRasterState(
          (memexport_draw || pixel_export_only)
              ? 1u
              : render_target_cache_->current_raster_sample_count(),
          regs.Get<reg::RB_COLORCONTROL>());
  uint32_t raster_sample_count =
      pipeline_raster_state.pipeline_key().raster_sample_count;
  if (memexport_draw) {
    // Vertex-only, rasterization disabled, zero attachments.
    pipeline = pipeline_cache_->GetOrCreateMemexportPipelineState(vs_translation);
  } else if (kDebugSolidFragment) {
    pipeline = GetDebugSolidPipeline(
        static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider())
            ->device(),
        vs_translation->metal_function(), debug_solid_fragment_,
        debug_solid_pipelines_);
  draw_trace_milestone("before-geometry-pipeline");
  } else if (use_geometry_emulation) {
    pipeline = pipeline_cache_->GetOrCreateGeometryPipelineState(
        vs_translation, ps_translation, geometry_type,
        ::rex::gpu::DXBCShaderTranslator::Modification(vs_mod),
        ::rex::gpu::DXBCShaderTranslator::Modification(ps_mod_value), color_pixel_formats,
        pipeline_depth_format, pipeline_raster_state.pipeline_key(),
        blend_controls,
        normalized_color_mask,
        &gs_vertex_size, &gs_max_input_primitives);
  } else if (async_pipelines) {
    // A stand-in (skipping the draw until the real pipeline exists) is only
    // harmless in a pass redrawn every frame: not for a render target drawn
    // only now (a one-off render to a texture), a small one (generated data)
    // or a draw with memory exports (Xenia Edge de8e60601).
    // The fork asked its render target cache to classify the bound target (redrawn every frame, or small); that bookkeeping
    // never reached this tree, and guessing it wrong means skipping a draw that only happens once. So take the conservative
    // answer: treat the target as possibly one-off and skip the stand-in.
    const bool target_recurring = false;
    const bool target_small = true;
    const bool stand_in_allowed =
        target_recurring && !target_small && memexport_ranges.empty();
    // A draw that waits hands its pipeline to the encoder thread when that
    // replays the draws (XE_METAL_DEFERRED_PIPELINES=0: the command processor
    // waits instead), so the pass's other new pipelines are queued meanwhile.
    static const bool s_defer = [] {
      const char* v = std::getenv("XE_METAL_DEFERRED_PIPELINES");
      return !(v && v[0] == '0' && !v[1]);
    }();
    const bool may_defer =
        s_defer && !stand_in_allowed &&
        encode_stream_->mode() == MetalEncodeStream::Mode::kThreaded;
    MetalShader::MetalTranslation* ps_used = nullptr;
    const auto async_start = std::chrono::steady_clock::now();
    const MetalPipelineCache::AsyncPipelineStatus status =
        pipeline_cache_->GetRenderPipelineStateAsync(
            vs_translation, ps_translation, color_pixel_formats,
            pipeline_depth_format, pipeline_raster_state.pipeline_key(),
            blend_controls, normalized_color_mask, stand_in_allowed, may_defer,
            &pipeline, &ps_used, &deferred_pipeline);
    if (status == MetalPipelineCache::AsyncPipelineStatus::kDeferred) {
      pipeline = deferred_pipeline.get();
    }
    if (!stand_in_allowed) {
      // Why draws waited (attribution, logged every 900 swaps): only waits
      // over 1 ms count, which is a build or a queued build finishing.
      const double waited_ms =
          std::chrono::duration<double, std::milli>(
              std::chrono::steady_clock::now() - async_start)
              .count();
      if (waited_ms > 1.0) {
        const int why = !memexport_ranges.empty() ? 2
                        : target_small            ? 1
                                                  : 0;
        ++async_wait_counts_[why];
        async_wait_ms_[why] += waited_ms;
      }
    }
    if (swap_count_ != async_wait_logged_swap_ && swap_count_ % 900 == 0 &&
        (async_wait_counts_[0] | async_wait_counts_[1] |
         async_wait_counts_[2])) {
      async_wait_logged_swap_ = swap_count_;
      REXLOG_INFO(
          "MetalAsyncPipelines swap#{}: draws that waited: target not "
          "recurring {} ({:.0f} ms), small target {} ({:.0f} ms), memexport "
          "{} ({:.0f} ms)",
          swap_count_, async_wait_counts_[0], async_wait_ms_[0],
          async_wait_counts_[1], async_wait_ms_[1], async_wait_counts_[2],
          async_wait_ms_[2]);
    }
    if (status == MetalPipelineCache::AsyncPipelineStatus::kPending) {
      GetMetalShaderBuildCensus().async_skips.fetch_add(
          1, std::memory_order_relaxed);
      RecordDrawSkip(MetalDrawSkipReason::kAsyncPipelinePending,
                     "async-pipeline-pending");
      return true;
    }
    if (!vs_translation->has_metal_function()) {
      RecordDrawSkip(MetalDrawSkipReason::kTranslationFailure, "vs-translate");
      return true;
    }
    ps_translation = ps_used;
  } else {
    pipeline = pipeline_cache_->GetOrCreateRenderPipelineState(
        vs_translation, ps_translation, color_pixel_formats,
        pipeline_depth_format, pipeline_raster_state.pipeline_key(),
        blend_controls,
        normalized_color_mask);
  }
  if (!pipeline) {
    draw_trace_milestone("before-encode-geometry");
  if (use_geometry_emulation) {
      ++geo_pipeline_fail_count_;
    }
    static std::unordered_set<uint64_t> s_null_pipeline_ps;
    if (pixel_shader &&
        s_null_pipeline_ps.insert(pixel_shader->GetUcodeDataHash()).second &&
        s_null_pipeline_ps.size() <= 16) {
      REXLOG_WARN("MetalCommandProcessor: NULL PIPELINE skip ps={:016X} fmt={:X}",
             pixel_shader->GetUcodeDataHash(), color_pixel_formats[0]);
    }
    RecordDrawSkip(MetalDrawSkipReason::kPipelineFailure, "pipeline-null");
    return true;
  }

  // STAGE 3 lazy writeback flush: if this draw SAMPLES a range a pending
  // resolve writeback covers (same-frame consumer — e.g. each luminance
  // pyramid level reads the previous level's resolve), commit + drain so the
  // fetch's guest-RAM upload sees the resolved content. MUST run before the
  // encoder opens (a flush here would kill an open encoder — the
  // setViewport-on-ended-encoder crash class). Cross-frame consumers cost
  // nothing: their writebacks drained at a prior swap.
  draw_gpu_ordering_active_ = false;
  // XE_METAL_TEX_DEP_MEMO: 1 on (default), 0 off, 2 verify (run the full
  // block anyway and count memo hits whose real decision was not empty; 0 of
  // ~80M across Burnout, JC2, RDR, Sonic, Gears 3, VP, Judgment, FEAR and
  // GTA IV). See TexDependencyMemo in the header.
  static const uint32_t s_tex_dep_memo = [] {
    const char* v = std::getenv("XE_METAL_TEX_DEP_MEMO");
    return v ? uint32_t(strtoul(v, nullptr, 10)) : 1u;
  }();
  bool tex_dep_memo_hit = false;
  uint64_t tex_dep_memo_hash = 0;
  if (s_tex_dep_memo &&
      (!pending_writebacks_.empty() || !pending_memexports_.empty())) {
    TexDependencyMemo& memo = tex_dependency_memo_;
    // Completion is not part of the key unless XE_METAL_TEX_DEP_MEMO_COMPLETED
    // is set: an empty decision means no overlap with any pending record, and
    // retiring a record changes the pending counts, which are.
    static const bool s_key_completed =
        std::getenv("XE_METAL_TEX_DEP_MEMO_COMPLETED") != nullptr;
    const uint64_t completed =
        s_key_completed ? completed_submission_.load(std::memory_order_acquire)
                        : 0;
    const uint64_t epoch = texture_cache_ ? texture_cache_->registry_epoch() : 0;
    const bool trace_open = false;
    if (memo.sequence != memory_authority_sequence_ ||
        memo.completed != completed || memo.registry_epoch != epoch ||
        memo.writebacks != pending_writebacks_.size() ||
        memo.memexports != pending_memexports_.size() ||
        memo.trace_open != trace_open) {
      if (!memo.Empty()) {
        memo.Clear();
        ++memo.clears;
      }
      memo.sequence = memory_authority_sequence_;
      memo.completed = completed;
      memo.registry_epoch = epoch;
      memo.writebacks = pending_writebacks_.size();
      memo.memexports = pending_memexports_.size();
      memo.trace_open = trace_open;
    }
    std::vector<uint32_t>& key = memo.key_scratch;
    key.clear();
    const uint64_t vs_bits = uint64_t(uintptr_t(vertex_shader));
    const uint64_t ps_bits = uint64_t(uintptr_t(pixel_shader));
    key.push_back(uint32_t(vs_bits));
    key.push_back(uint32_t(vs_bits >> 32));
    key.push_back(uint32_t(ps_bits));
    key.push_back(uint32_t(ps_bits >> 32));
    uint32_t bound_mask = 0;
    for (MetalShader* shader : {vertex_shader, pixel_shader}) {
      if (!shader) {
        continue;
      }
      for (const auto& binding : shader->GetTextureBindingsAfterTranslation()) {
        if (binding.fetch_constant < 32) {
          bound_mask |= 1u << binding.fetch_constant;
        }
      }
    }
    key.push_back(bound_mask);
    for (uint32_t m = bound_mask; m;) {
      const uint32_t slot = uint32_t(__builtin_ctz(m));
      m &= m - 1;
      const uint32_t* w = &register_file_->values
          [XE_GPU_REG_SHADER_CONSTANT_FETCH_00_0 + slot * 6];
      key.insert(key.end(), w, w + 6);
    }
    uint64_t hash = 0xcbf29ce484222325ull;
    for (uint32_t v : key) {
      hash = (hash ^ v) * 0x100000001b3ull;
    }
    tex_dep_memo_hash = hash;
    tex_dep_memo_hit = memo.Contains(hash, key);
    if (tex_dep_memo_hit) {
      ++memo.hits;
    } else {
      ++memo.misses;
    }
    if (((memo.hits + memo.misses) & 0xFFFFF) == 0) {
      REXLOG_INFO(
          "MetalTexDepMemo hits={} misses={} ({:.1f}% hit) inserts={} "
          "clears={} verify checked={} mismatches={}",
          memo.hits, memo.misses,
          100.0 * double(memo.hits) / double(memo.hits + memo.misses),
          memo.inserts, memo.clears, memo.verify_checked,
          memo.verify_mismatches);
    }
  }
  if ((!pending_writebacks_.empty() || !pending_memexports_.empty()) &&
      !(tex_dep_memo_hit && s_tex_dep_memo == 1)) {
    // CENSUS ONLY: the same request with GPU-served fetches omitting their
    // resolve range, so the decision the repair WOULD take can be compared
    // against the one taken. Never passed to the production path.
  draw_trace_milestone("after-tex-ranges");
    metal::ConsumerRequest census_corrected_request;
    // Stage B endgame (reopen 4.1): true while every fetch that contributed
    // a resolve range is provably served by the shared-cache load route
    // (reads the shared buffer). Any legacy-served or ineligible fetch
    // clears it, and the request then keeps guest-RAM access semantics.
    bool texture_resolve_consumers_buffer_read = true;
    static const bool s_gpu_ordering = [] {
      // DEFAULT ON since the 2026-08-29 counted gate (with
      // XE_METAL_GPU_RESOLVE); exact-0 rollback, like the other promoted
      // flags. The blocker census below stays an explicit =1 opt-in.
      const char* v = std::getenv("XE_METAL_GPU_ORDERING");
      return !(v && v[0] == '0' && !v[1]);
    }();
    // Per-fetch overlap gate (probe #2's lesson): only a fetch whose ranges
    // actually overlap a pending GPU-current record constrains the access
    // declaration. Innocent co-bound material textures (the 65M blocked DXT
    // fetches) read ranges no GPU-current producer owns; the ordering path's
    // safety only needs RAM readers kept off GPU-current ranges, which
    // DecideConsumer's all-selected-gpu-current rule composes with this
    // per-fetch check to guarantee.
    // Index-backed (exact): the queue walk per binding was 21 ms of a 66 ms
    // frame on Red Dead gameplay (2026-10-05). XE_METAL_PRODUCER_INDEX=0
    // restores the walk.
    static const bool s_overlap_index = [] {
      const char* v = std::getenv("XE_METAL_PRODUCER_INDEX");
      return !(v && v[0] == '0' && !v[1]);
    }();
    auto overlaps_pending_gpu_current =
        [&](const std::optional<metal::GuestRange>& r) {
          if (!r) {
            return false;
          }
          if (s_overlap_index) {
            return IndexRangeOverlapsProducers(r->start(), r->end(),
                                               /*gpu_current_writebacks=*/true,
                                               /*memexports=*/false);
          }
          for (const PendingWriteback& p : pending_writebacks_) {
            if (!p.gpu_current) {
              continue;
            }
            auto pr = metal::GuestRange::FromBaseLength(p.guest_addr,
                                                        p.range_bytes());
            if (pr && pr->Overlaps(*r)) {
              return true;
            }
          }
          return false;
        };
    auto overlaps_pending_memexport =
        [&](const std::optional<metal::GuestRange>& r) {
          if (!r) {
            return false;
          }
          if (s_overlap_index) {
            return IndexRangeOverlapsProducers(r->start(), r->end(),
                                               /*gpu_current_writebacks=*/false,
                                               /*memexports=*/true);
          }
          for (const PendingMemexport& p : pending_memexports_) {
            auto pr = metal::GuestRange::FromBaseLength(p.base_address,
                                                        p.size_bytes);
            if (pr && pr->Overlaps(*r)) {
              return true;
            }
          }
          return false;
        };
    // Memexport ordering is safe only while every consumer of a pending
    // memexport range reads the shared buffer. A bridge-served fetch reads a
    // SNAPSHOT the memexport bytes never reach, and a legacy RAM fetch reads
    // guest RAM the export has not converged to — either one forces the
    // historical wait-and-drain for this draw.
    bool memexport_order_safe = true;
    auto collect_texture_ranges = [&](MetalShader* shader,
                                      metal::ConsumerRequest& request) {
      if (!shader) return;
      for (const auto& binding : shader->GetTextureBindingsAfterTranslation()) {
        auto f = regs.GetTextureFetch(binding.fetch_constant);
        uint32_t fbase = f.base_address << 12;
        if (!fbase) continue;
        // DEAD SIGN BINDING: the translator declares an unsigned and a signed
        // binding per fetch and samples each component through the one its
        // sign selects, so a binding whose signedness no component uses is
        // never sampled (the serve path never loads it either). It must not
        // veto GPU ordering: Tomb Raider's 640x360 k_16_16_16_16 velocity
        // buffer (signs=1111) made its draw a RAM consumer through the
        // unsigned binding alone, 11 commits + ~11 ms GPU wait a frame.
        // XE_METAL_DEAD_SIGN_BINDINGS=0 restores the veto.
        static const bool s_skip_dead_sign_bindings = [] {
          const char* v = std::getenv("XE_METAL_DEAD_SIGN_BINDINGS");
          return !(v && v[0] == '0' && !v[1]);
        }();
        if (s_skip_dead_sign_bindings) {
          auto is_signed_sign = [](xenos::TextureSign s) {
            return s == xenos::TextureSign::kSigned;
          };
          uint32_t signed_components =
              uint32_t(is_signed_sign(f.sign_x)) +
              uint32_t(is_signed_sign(f.sign_y)) +
              uint32_t(is_signed_sign(f.sign_z)) +
              uint32_t(is_signed_sign(f.sign_w));
          if (binding.is_signed ? signed_components == 0
                                : signed_components == 4) {
            continue;
          }
        }

        metal::FetchGuestRanges rng = ComputeFetchGuestRanges(f);
        auto base_range =
            metal::GuestRange::FromBounds(rng.base_begin, rng.base_end);
        auto mip_range =
            metal::GuestRange::FromBounds(rng.mip_begin, rng.mip_end);

        // Every RAM-backed fetch can depend on memexport. A bridge-served
        // resolve is already GPU-ordered, while memexport at the same address
        // still needs convergence because the bridge does not contain it.
        request.memexport_ranges.Add(base_range);
        if (rng.mip_end > rng.mip_begin) {
          request.memexport_ranges.Add(mip_range);
        }
        bool bridge_served =
            texture_cache_ &&
            texture_cache_->BridgeServes(fbase, f.size_2d.width + 1,
                                          f.size_2d.height + 1,
                                          uint32_t(f.pitch) << 5);
        // CENSUS ONLY (XE_METAL_SERVING_CENSUS=1, task 1.1 of
        // implement-metal-gpu-visible-resolve-authority): count how often this
        // dependency declaration disagrees with the serve chain's own
        // classification. Observational: it does not change the declaration.
        // Analytically the only default-config divergence is the exact-cover
        // class (kBridgeSnapshot's condition is equivalent to BridgeServes when
        // color_bridge is off, and covered_r32f implies !ram_backed); the
        // census measures how often that class actually fires on real content.
        if (ScaleCoverageCensusEnabled() && texture_cache_) {
          metal::ScaleCoverageCensus::Get().RecordFetch(
              fbase, f.size_2d.width + 1, f.size_2d.height + 1,
              texture_cache_->ClassifyFetchService(f, binding.is_signed));
        }
        if (ServingCensusEnabled() && texture_cache_) {
          ResolvedFetchService service =
              texture_cache_->ClassifyFetchService(f, binding.is_signed);
          metal::ServingCensus::Record(service, bridge_served);
          // Mirror of the declaration below, but keyed on the serve chain's
          // classification instead of the narrower duplicate predicate.
          census_corrected_request.memexport_ranges.Add(base_range);
          if (rng.mip_end > rng.mip_begin) {
            census_corrected_request.memexport_ranges.Add(mip_range);
          }
          if (!metal::ServingCensus::IsGpuServed(service)) {
            census_corrected_request.resolve_ranges.Add(base_range);
            if (rng.mip_end > rng.mip_begin) {
              census_corrected_request.resolve_ranges.Add(mip_range);
            }
          }
        }
        if (bridge_served && s_gpu_ordering &&
            (overlaps_pending_memexport(base_range) ||
             (rng.mip_end > rng.mip_begin &&
              overlaps_pending_memexport(mip_range)))) {
          // Snapshot serving cannot observe buffer-resident memexport bytes.
          memexport_order_safe = false;
        }
        // CEILING PROBE (re5-perf-20261015): XE_METAL_PROBE_SKIP_CUBE_DEPS=1
        // drops cube fetches from the dependency request. Cube maps cannot
        // take the shared route, so a per-frame rendered cube (RE5's 128x128
        // environment probe, mips 0-7) makes its draw a RAM consumer that
        // drains ~55 GPU-resident resolves every frame. The probe serves
        // stale RAM (wrong reflections) and only measures what GPU-side cube
        // serving would be worth. Never on by default.
        static const bool s_probe_skip_cube_deps = [] {
          const char* v = std::getenv("XE_METAL_PROBE_SKIP_CUBE_DEPS");
          return v && v[0] == '1' && !v[1];
        }();
        if (s_probe_skip_cube_deps &&
            f.dimension == xenos::DataDimension::kCube) {
          continue;
        }
        if (!bridge_served) {
          request.resolve_ranges.Add(base_range);
          if (rng.mip_end > rng.mip_begin) {
            request.resolve_ranges.Add(mip_range);
          }
          // Stage B endgame (reopen 4.1): decide whether THIS fetch reads
          // the shared buffer — the exact predicate the C1T-R mask uses
          // below (M2: prep and serve cannot disagree), re-derived here
          // because the dependency decision precedes the mask computation.
          // A fetch that overlaps NO pending GPU-current record AND no
          // pending memexport is innocent and constrains nothing.
          bool touches_gc =
              overlaps_pending_gpu_current(base_range) ||
              (rng.mip_end > rng.mip_begin &&
               overlaps_pending_gpu_current(mip_range));
          bool touches_me =
              overlaps_pending_memexport(base_range) ||
              (rng.mip_end > rng.mip_begin &&
               overlaps_pending_memexport(mip_range));
          if (s_gpu_ordering && !touches_gc && !touches_me) {
            continue;
          }
          bool fetch_buffer_read =
              shared_texture_cache_ && true &&
              binding.fetch_constant < xenos::kTextureFetchConstantCount &&
              IsTextureFetchConstantServable(
                  f.type, ::rex::graphics::metal::GetMetalSettings().gpu_allow_invalid_fetch_constants.Get());
          bool strict_eligible = false;
          ResolvedFetchService fetch_service =
              ResolvedFetchService::kRamContent;
          if (fetch_buffer_read) {
            uint32_t fw = fetch_width_serve(f);
            uint32_t fh = fetch_height_serve(f);
            uint32_t fp = fetch_pitch_serve(f);
            strict_eligible =
                SharedRouteEligible(f, binding.is_signed, fw, fh, fp, nullptr);
            fetch_service =
                texture_cache_->ClassifyFetchService(f, binding.is_signed);
            fetch_buffer_read =
                (strict_eligible &&
                 RouteServiceOk(fetch_service, f.base_address << 12, true)) ||
                // Served GPU-side from the registered snapshot: reads neither
                // guest RAM nor the shared buffer, so it neither needs the
                // drain nor vetoes ordering for the fetches that do.
                fetch_service == ResolvedFetchService::kExactCoverSnapshot ||
                fetch_service == ResolvedFetchService::kBridgeSnapshot ||
                // Draw resolution scaling: the scaled-cover snapshot is the
                // same never-reads-RAM service as exact cover; before
                // 2026-10-03 it was missing here, so at 2x2 every scaled-
                // cover fetch over a pending resolve forced a CPU wait (JC2:
                // 5 blocking waits, ~50 ms, per frame; GPU idle ~19%).
                // XE_METAL_SCALED_COVER_ORDERING=0 restores the wait.
                (fetch_service == ResolvedFetchService::kScaledCoverSnapshot &&
                 ScaledCoverOrderingEnabled());
            if (touches_me &&
                (fetch_service == ResolvedFetchService::kExactCoverSnapshot ||
                 fetch_service == ResolvedFetchService::kScaledCoverSnapshot ||
                 fetch_service == ResolvedFetchService::kBridgeSnapshot)) {
              // Snapshot serving cannot observe buffer-resident memexport
              // bytes (the same veto the bridge-served branch applies): keep
              // the memexport producers on the wait-and-drain path. Found by
              // Viva Pinata at 2x2 rendering black once scaled-cover fetches
              // were ordered on the GPU.
              memexport_order_safe = false;
            }
          }
          if (!fetch_buffer_read) {
            texture_resolve_consumers_buffer_read = false;
            // Name the precise failing condition, bounded (reopen census).
            static uint32_t s_blocker_detail_logs = 0;
            // XE_METAL_ORDERING_DETAIL_LOGS=N raises the bound (RE5 census:
            // the default 24 were spent in the menus).
            static const uint32_t s_blocker_detail_cap = [] {
              const char* v = std::getenv("XE_METAL_ORDERING_DETAIL_LOGS");
              return v ? uint32_t(strtoul(v, nullptr, 10)) : 24u;
            }();
            if (s_gpu_ordering && s_blocker_detail_logs < s_blocker_detail_cap) {
              ++s_blocker_detail_logs;
              REXLOG_INFO(
                  "MetalGpuOrderingBlockDetail draw={} base={:08X} fmt={} "
                  "signed={} type={} cache={} writer={} strict={} svc={} "
                  "signs={}{}{}{} mips={}-{} tiled={} pitch={} dim={} "
                  "stacked={} {}x{}",
                  uint32_t(trace_draw_index_), f.base_address << 12,
                  uint32_t(f.format), binding.is_signed ? 1 : 0,
                  uint32_t(f.type), shared_texture_cache_ != nullptr,
                  false ? 1 : 0, strict_eligible,
                  uint32_t(fetch_service), uint32_t(f.sign_x),
                  uint32_t(f.sign_y), uint32_t(f.sign_z), uint32_t(f.sign_w),
                  uint32_t(f.mip_min_level), uint32_t(f.mip_max_level), uint32_t(f.tiled),
                  uint32_t(f.pitch), uint32_t(f.dimension),
                  uint32_t(f.stacked), f.size_2d.width + 1,
                  f.size_2d.height + 1);
            }
            // Blocker census (reopen 4.2 probe follow-up): WHAT blocks the
            // ordering path on real corridors. Key = guest format, the serve
            // classification, and the strict-eligibility verdict. Only under
            // the diagnostic flag; bounded map, periodic dump.
            static const bool s_ord_census = [] {
              const char* v = std::getenv("XE_METAL_GPU_ORDERING");
              return v && v[0] == '1' && !v[1];
            }();
            if (s_ord_census) {
              static std::map<uint32_t, uint64_t> s_blockers;
              static uint64_t s_blocked_fetches = 0;
              uint32_t key = (uint32_t(f.format) << 8) |
                             (uint32_t(fetch_service) << 1) |
                             uint32_t(strict_eligible);
              if (s_blockers.size() < 256) {
                ++s_blockers[key];
              }
              if ((++s_blocked_fetches & 0xFFFFF) == 1 &&
                  s_blocked_fetches > 1) {
                std::string top;
                std::vector<std::pair<uint64_t, uint32_t>> ranked;
                for (const auto& kv : s_blockers) {
                  ranked.emplace_back(kv.second, kv.first);
                }
                std::sort(ranked.rbegin(), ranked.rend());
                for (size_t r = 0; r < ranked.size() && r < 6; ++r) {
                  top += fmt::format(" fmt={} svc={} strict={} n={}",
                                     ranked[r].second >> 8,
                                     (ranked[r].second >> 1) & 0x7F,
                                     ranked[r].second & 1, ranked[r].first);
                }
                REXLOG_INFO("MetalGpuOrderingBlockers total={}:{}",
                       s_blocked_fetches, top);
              }
            }
          }
        }
      }
    };
    // Persistent scratch (see vertex_request_scratch_).
    metal::ConsumerRequest& texture_request = texture_request_scratch_;
    texture_request.resolve_ranges.Clear();
    texture_request.memexport_ranges.Clear();
    texture_request.access = metal::ConsumerAccess::kGuestRam;
    texture_request.order_memexport_producers = false;
    collect_texture_ranges(pixel_shader, texture_request);
    collect_texture_ranges(vertex_shader, texture_request);
    // Stage B endgame (reopen 4.1, XE_METAL_GPU_ORDERING=1, default OFF):
    // declare shared-buffer access when EVERY fetch that contributed a
    // resolve range will actually be served by the shared-cache load route,
    // which reads the shared buffer on the GPU timeline. With the
    // straddling-page fix the pages of a pending GPU-current record stay
    // valid+gpu_written, so the route's PrepareEligible uploads nothing and
    // the load shader reads the producing dispatch's bytes under command-
    // buffer ordering — no completion wait needed. DecideConsumer stays the
    // sole authority: it takes the ordering path only when ALL selected
    // producers are GPU-current; any legacy-served fetch, memexport
    // producer, or predecessor-chain record falls back to the boundary.
    if (s_gpu_ordering && !texture_request.resolve_ranges.ranges().empty()) {
      static uint32_t s_ord_eligible = 0, s_ord_blocked = 0;
      if (texture_resolve_consumers_buffer_read) {
        texture_request.access = metal::ConsumerAccess::kSharedBuffer;
        // Memexport products are buffer-resident at execution time exactly
        // like GPU-current resolves (see ConsumerRequest); a shared-buffer
        // reader orders against them instead of waiting — but only while no
        // snapshot-served fetch in this draw overlaps a pending export.
        texture_request.order_memexport_producers = memexport_order_safe;
        ++s_ord_eligible;
      } else {
        ++s_ord_blocked;
      }
      const uint32_t total = s_ord_eligible + s_ord_blocked;
      if ((total & 0xFFFFu) == 1) {
        REXLOG_INFO("MetalGpuOrdering: buffer-read declared={} blocked={}",
               s_ord_eligible, s_ord_blocked);
      }
    }
    if (RcCensusEnabled()) {
      RcCensusNoteTextureRequest(texture_request.resolve_ranges,
                                 trace_draw_index_);
    }
    metal::ConsumerDecision authority_decision =
        QueryPendingProducerDependencies(metal::ConsumerKind::kTexture,
                                         texture_request);
    draw_trace_milestone("after-tex-query");
    // Boundary-taker census (attribution follow-up): the seam data shows the
    // corridor's texture boundaries are memexport-only selections on draws
    // whose access was NEVER declared (resolve ranges empty or blocked).
    // Name those draws' fetches: for each boundary-taking decision at
    // guest-RAM access, log the pending-overlapping fetches' format/serve/
    // eligibility so the widening step is data-named.
    // Widened 2026-09-27: every boundary-taking texture decision (either
    // access mode) is named, so the per-frame texture wait is attributable.
    if (s_gpu_ordering && !authority_decision.selected.empty() &&
        authority_decision.action !=
            metal::AuthorityAction::kOrderAgainstGpuProducers) {
      static uint32_t s_taker_logs = 0;
      static uint32_t s_taker_total = 0;
      // The first 64 takers name the boot period; afterwards every 512th is
      // sampled so the steady-state scene's takers are attributable too.
      if (s_taker_logs < 64 || (++s_taker_total & 511) == 0) {
        std::string fetches;
        auto census_fetches = [&](MetalShader* shader) {
          if (!shader) return;
          for (const auto& binding :
               shader->GetTextureBindingsAfterTranslation()) {
            auto f = regs.GetTextureFetch(binding.fetch_constant);
            if (!(f.base_address << 12)) continue;
            metal::FetchGuestRanges rng = ComputeFetchGuestRanges(f);
            auto br = metal::GuestRange::FromBounds(rng.base_begin,
                                                    rng.base_end);
            bool gc = overlaps_pending_gpu_current(br);
            bool me = overlaps_pending_memexport(br);
            if (!gc && !me) continue;
            bool bridge = texture_cache_ &&
                          texture_cache_->BridgeServes(f.base_address << 12,
                                                       f.size_2d.width + 1,
                                                       f.size_2d.height + 1,
                                                       uint32_t(f.pitch) << 5);
            uint32_t fw = fetch_width_serve(f), fh = fetch_height_serve(f);
            uint32_t fp = f.pitch ? (uint32_t(f.pitch) << 5)
                                  : ((fw + 31u) & ~31u);
            bool strict = SharedRouteEligible(f, false, fw, fh, fp, nullptr);
            ResolvedFetchService svc =
                texture_cache_
                    ? texture_cache_->ClassifyFetchService(f,
                                                           binding.is_signed)
                    : ResolvedFetchService::kRamContent;
            fetches += fmt::format(
                " [base={:08X} fmt={} {}x{} gc={} me={} bridge={} strict={} "
                "svc={} signed={} type={}]",
                f.base_address << 12, uint32_t(f.format), fw, fh, gc, me,
                bridge, strict, uint32_t(svc), binding.is_signed ? 1 : 0,
                uint32_t(f.type));
          }
        };
        census_fetches(pixel_shader);
        census_fetches(vertex_shader);
        if (!fetches.empty()) {
          ++s_taker_logs;
          uint32_t sel_r = 0, sel_m = 0;
          for (const auto& p : authority_decision.selected) {
            if (p.state == metal::TransitState::kPendingMemexport) {
              ++sel_m;
            } else {
              ++sel_r;
            }
          }
          REXLOG_INFO("MetalGpuOrderingTaker draw={} access={} await={} sel_r={} "
                 "sel_m={}:{}",
                 trace_draw_index_,
                 texture_request.access == metal::ConsumerAccess::kSharedBuffer
                     ? "buffer"
                     : "ram",
                 authority_decision.await ? 1 : 0, sel_r, sel_m, fetches);
        }
      }
    }
    // Mixed-break census (probe #7 follow-up): access was declared but the
    // ordering action did not fire — count which producer STATES broke the
    // all-gpu-current set, so the next widening step is named by data.
    if (s_gpu_ordering &&
        texture_request.access == metal::ConsumerAccess::kSharedBuffer &&
        !authority_decision.selected.empty() &&
        authority_decision.action !=
            metal::AuthorityAction::kOrderAgainstGpuProducers) {
      static uint64_t s_break_resolve = 0, s_break_memexport = 0,
                      s_break_total = 0;
      for (const auto& p : authority_decision.selected) {
        if (p.state == metal::TransitState::kPendingResolve) {
          ++s_break_resolve;
        } else if (p.state == metal::TransitState::kPendingMemexport) {
          ++s_break_memexport;
        }
      }
      if ((++s_break_total & 4095) == 1) {
        // Name the breaking producers (first 8 of them): a record that is
        // neither GPU-current nor a memexport is the one the consumer waits on.
        std::string breakers;
        uint32_t named = 0;
        for (const auto& p : authority_decision.selected) {
          if (p.state != metal::TransitState::kPendingResolve || named >= 8) {
            continue;
          }
          ++named;
          breakers += fmt::format(" [{:08X}+{:X} sub={} seq={}]",
                                  p.range.start(), p.range.length(),
                                  p.submission, p.sequence);
        }
        REXLOG_INFO(
            "MetalGpuOrderingMixedBreak decisions={} plain_resolve={} "
            "memexport={} open_sub={} completed={}:{}",
            s_break_total, s_break_resolve, s_break_memexport,
            CurrentEncodingSubmission(),
            completed_submission_.load(std::memory_order_acquire), breakers);
      }
    }
    if (ServingCensusEnabled()) {
      // BOUNDARY-LEVEL census: the same query against the corrected request.
      // `QueryPendingProducerDependencies` is const and owns no authority
      // state, so this second evaluation cannot perturb the run; the decision
      // is discarded. A request whose dependency disappears is the only cell
      // that maps to recovered frame time.
      metal::ConsumerDecision corrected = QueryPendingProducerDependencies(
          metal::ConsumerKind::kTexture, census_corrected_request);
      auto has_dependency = [](const metal::ConsumerDecision& d) {
        return d.action != metal::AuthorityAction::kNoDependency;
      };
      using Requests = metal::ServingCensus::Requests;
      Requests::Total().fetch_add(1, std::memory_order_relaxed);
      if (has_dependency(authority_decision) && !has_dependency(corrected)) {
        Requests::BoundaryAvoided().fetch_add(1, std::memory_order_relaxed);
      } else if (has_dependency(authority_decision) &&
                 has_dependency(corrected)) {
        Requests::BoundaryRetained().fetch_add(1, std::memory_order_relaxed);
      } else if (!has_dependency(authority_decision) &&
                 has_dependency(corrected)) {
        Requests::CorrectedStricter().fetch_add(1, std::memory_order_relaxed);
      }
    }
    // Same consumer-attribution diagnostic as the vertex seam (log only).
    if (s_memexport_log) {
      for (const metal::PendingProducer& producer : authority_decision.selected) {
        if (producer.state != metal::TransitState::kPendingMemexport) {
          continue;
        }
        REXLOG_WARN(
            "MetalMemexportConsumer draw={} kind=texture range={:08X}(+{}) "
            "producer_seq={} await={}",
            trace_draw_index_, producer.range.start(), producer.range.length(),
            producer.sequence, authority_decision.await ? 1 : 0);
      }
    }
    // Task 4.3 routes both texture-cache implementations through the common
    // selected-record executor: one boundary, selective drain, before either
    // cache consumes the RAM-derived bytes below.
    // Fail-closed marker for the serve site: while an ordering-served draw
    // is being marshalled, a routed fetch that falls back to the legacy RAM
    // path would read bytes the elided wait was supposed to converge — such
    // a draw must be skipped (counted), never silently mis-served.
    // Bisect lever (10395 corner artifact): comma-separated trace draw
    // indices whose ordered execution is demoted to the await+drain boundary.
    static const char* s_order_skip_env =
        std::getenv("XE_METAL_ORDER_SKIP_DRAWS");
    if (s_order_skip_env &&
        authority_decision.action ==
            metal::AuthorityAction::kOrderAgainstGpuProducers) {
      for (const char* p = s_order_skip_env; *p;) {
        char* end;
        uint32_t v = uint32_t(strtoul(p, &end, 10));
        if (end == p) {
          break;
        }
        if (v == trace_draw_index_) {
          authority_decision.action = metal::AuthorityAction::kAwaitProducer;
          break;
        }
        p = (*end == ',') ? end + 1 : end;
      }
    }
    draw_gpu_ordering_active_ =
        authority_decision.action ==
        metal::AuthorityAction::kOrderAgainstGpuProducers;
    note_memexport_ordering(authority_decision);
    // Bounded ordered-execution log (10395 corner artifact): name every draw
    // whose wait was elided and the producer ranges it was ordered against.
    static const bool s_order_log = std::getenv("XE_METAL_ORDER_LOG") != nullptr;
    if (s_order_log && draw_gpu_ordering_active_) {
      static uint32_t s_order_logs = 0;
      if (s_order_logs++ < 512) {
        std::string sel;
        for (const auto& p : authority_decision.selected) {
          sel += fmt::format(" {:08X}(+{}){}", p.range.start(),
                             p.range.length(),
                             p.state == metal::TransitState::kPendingMemexport
                                 ? "M"
                                 : "R");
        }
        REXLOG_INFO("MetalOrderedDraw draw={} producers={}:{}", trace_draw_index_,
               authority_decision.selected.size(), sel);
      }
    }
    ProducerDependencyOutcome dependency_outcome =
        ResolvePendingProducerDependencies(authority_decision);
    if (!dependency_outcome.complete) {
      REXLOG_ERROR(
          "MetalCommandProcessor: texture dependency convergence retired {} "
          "of {} selected producers; skipping draw",
          dependency_outcome.drain.drained_records,
          authority_decision.selected.size());
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                     "texture-dependency-drain");
      return true;
    }
    if (s_tex_dep_memo) {
      TexDependencyMemo& memo = tex_dependency_memo_;
      const bool no_dependency =
          authority_decision.selected.empty() &&
          authority_decision.action == metal::AuthorityAction::kNoDependency;
      if (tex_dep_memo_hit) {
        // Verify mode only (mode 1 skipped this block on a hit).
        ++memo.verify_checked;
        if (!no_dependency && ++memo.verify_mismatches <= 32) {
          REXLOG_ERROR(
              "MetalTexDepMemo VERIFY MISMATCH draw={} action={} selected={}",
              trace_draw_index_, uint32_t(authority_decision.action),
              authority_decision.selected.size());
        }
      } else if (no_dependency) {
        memo.Insert(tex_dep_memo_hash, memo.key_scratch);
        ++memo.inserts;
      }
    }
  }

  // C1T-R prepass: prepare eligible strict-RGBA8 kRamContent
  // misses through the shared TextureCache subclass at the proven
  // post-overlap/drain pre-encoder seam. The mask computed here is THE
  // per-draw routing decision — descriptor marshalling serves exactly these
  // indices from the subclass (seam audit M2: prep and serve can never
  // disagree), and classification/eligibility are the single existing
  // contracts (ClassifyFetchService + metal_texture_load_eligibility.h).
  draw_shared_route_mask_ = 0;
  // XE_METAL_TEX_ROUTE=0: exact rollback for the shared-cache GPU load
  // route (the C1T-R mask never populates; every fetch serves legacy).
  // Default ON. Also the micro-drift bisect lever: a legacy-only arm
  // isolates whether the SF4 ±1-3 field originates in route serving.
  static const bool s_tex_route_enabled = [] {
    const char* v = std::getenv("XE_METAL_TEX_ROUTE");
    return !(v && v[0] == '0' && !v[1]);
  }();
  // SIGNED bindings route ONLY for corridor fetches — see
  // FetchOverlapsPendingGpuCurrent (SF4 bisect: the ±1-LSB drift is
  // entirely the signed class on ordinary content; the corridor is where
  // routing pays).
  // Capture disengage: while a frame trace is being recorded the CPU path
  // serves everything, so the capture records exactly the CPU-oracle
  // read-set — recorded ranges are IDENTICAL to route-off by construction
  // (a routed prep during capture would add page-granular shared-memory
  // upload records the CPU path never emits). Replays re-engage the route
  // from restored RAM.
  if (s_tex_route_enabled && shared_texture_cache_ && texture_cache_ &&
      true) {
    uint32_t route_signed_mask = 0;
    auto accumulate_eligible = [&](MetalShader* shader) {
      if (!shader) {
        return;
      }
      for (const auto& binding : shader->GetTextureBindingsAfterTranslation()) {
        if (binding.fetch_constant >= xenos::kTextureFetchConstantCount ||
            (draw_shared_route_mask_ & (1u << binding.fetch_constant))) {
          continue;
        }
        auto fetch = regs.GetTextureFetch(binding.fetch_constant);
        if (!IsTextureFetchConstantServable(
                fetch.type, ::rex::graphics::metal::GetMetalSettings().gpu_allow_invalid_fetch_constants.Get())) {
          continue;
        }
        // Per-dimension size (1D and 3D pack their sizes differently).
        uint32_t fetch_width = fetch_width_serve(fetch);
        uint32_t fetch_height = fetch_height_serve(fetch);
        uint32_t fetch_pitch_texels = fetch.pitch
                                          ? (uint32_t(fetch.pitch) << 5)
                                          : ((fetch_width + 31u) & ~31u);
        // Two mutually exclusive strict classes: the single-mip predicate keeps
        // deciding its own class unchanged, and the mipped sibling decides the
        // chain-bearing one. A SIGNED binding routes through its own sibling
        // predicate and is served as an RGBA8Snorm view of the same bytes.
        // XE_METAL_TEX_ROUTE_SIGNED=0: micro-drift bisect lever — signed
        // bindings stay on the legacy path.
        static const bool s_route_signed = [] {
          const char* v = std::getenv("XE_METAL_TEX_ROUTE_SIGNED");
          return !(v && v[0] == '0' && !v[1]);
        }();
        bool corridor_required = false;
        if (!SharedRouteEligible(fetch, binding.is_signed, fetch_width,
                                 fetch_height, fetch_pitch_texels,
                                 &corridor_required)) {
          continue;
        }
        if (binding.is_signed &&
            (!s_route_signed ||
             (corridor_required && !FetchOverlapsPendingGpuCurrent(fetch)))) {
          continue;
        }
        // Bisect lever (any format, any service): XE_METAL_TEX_ROUTE_SKIP_ANY=
        // <hex base,...> keeps the named fetch bases on the legacy path.
        {
          static const std::vector<uint32_t> s_skip_any = [] {
            std::vector<uint32_t> v;
            if (const char* e = std::getenv("XE_METAL_TEX_ROUTE_SKIP_ANY")) {
              for (const char* c = e; *c;) {
                char* end = nullptr;
                uint32_t b = uint32_t(strtoul(c, &end, 16));
                if (end == c) break;
                v.push_back(b);
                c = (*end == ',') ? end + 1 : end;
              }
            }
            return v;
          }();
          if (!s_skip_any.empty() &&
              std::find(s_skip_any.begin(), s_skip_any.end(),
                        uint32_t(fetch.base_address << 12)) != s_skip_any.end()) {
            continue;
          }
        }
        {
          const ResolvedFetchService mask_service =
              texture_cache_->ClassifyFetchService(fetch, binding.is_signed);
          if (!RouteServiceOk(mask_service, fetch.base_address << 12)) {
            continue;
          }
          if (mask_service == ResolvedFetchService::kNotResolveBacked) {
            // Route-all bisect (SF4 10395 oracle): XE_METAL_ROUTE_SKIP_BASE=
            // <hex,...> keeps the named not-resolve-backed bases on the legacy
            // path; XE_METAL_ROUTE_ALL_LOG=1 names every routed one (bounded,
            // unique by base).
            static const bool s_route_all_log =
                std::getenv("XE_METAL_ROUTE_ALL_LOG") != nullptr;
            const uint32_t fetch_base = fetch.base_address << 12;
            const bool skip = false;  // skips never reach here (RouteServiceOk)
            if (s_route_all_log) {
              static std::set<uint32_t> s_seen;
              if (s_seen.size() < 128 && s_seen.insert(fetch_base).second) {
                REXLOG_INFO(
                    "MetalRouteAll base={:08X} fmt={} {}x{} pitch={} mips={}-{} "
                    "mip_addr={:08X} signed={} signs={}{}{}{} endian={} "
                    "tiled={} skip={}",
                    fetch_base, uint32_t(fetch.format), fetch_width,
                    fetch_height, fetch_pitch_texels, uint32_t(fetch.mip_min_level),
                    uint32_t(fetch.mip_max_level), fetch.mip_address << 12,
                    binding.is_signed ? 1 : 0, uint32_t(fetch.sign_x),
                    uint32_t(fetch.sign_y), uint32_t(fetch.sign_z),
                    uint32_t(fetch.sign_w), uint32_t(fetch.endianness),
                    uint32_t(fetch.tiled), skip ? 1 : 0);
              }
            }
            (void)skip;
          }
        }
        // Alias-class census (micro-drift bisect, XE_METAL_TEX_ROUTE_LOG=1):
        // the fields of every masked fmt-50 fetch, bounded.
        static const bool s_route_log =
            std::getenv("XE_METAL_TEX_ROUTE_LOG") != nullptr;
        if (s_route_log &&
            fetch.format == xenos::TextureFormat::k_8_8_8_8_AS_16_16_16_16) {
          static uint32_t s_alias_logs = 0;
          if (s_alias_logs++ < 16) {
            REXLOG_INFO(
                "MetalTexRouteAlias base={:08X} {}x{} pitch={} endian={} "
                "signs={}{}{}{} signed={} mips={}-{} mip_addr={:08X} "
                "packed={} swizzle={:03X}",
                fetch.base_address << 12, fetch_width, fetch_height,
                fetch_pitch_texels, uint32_t(fetch.endianness),
                uint32_t(fetch.sign_x), uint32_t(fetch.sign_y),
                uint32_t(fetch.sign_z), uint32_t(fetch.sign_w),
                binding.is_signed ? 1 : 0, uint32_t(fetch.mip_min_level),
                uint32_t(fetch.mip_max_level), fetch.mip_address << 12,
                uint32_t(fetch.packed_mips), uint32_t(fetch.swizzle));
          }
        }
        draw_shared_route_mask_ |= 1u << binding.fetch_constant;
        if (binding.is_signed) {
          route_signed_mask |= 1u << binding.fetch_constant;
        }
      }
    };
  draw_trace_milestone("after-tex-census");
    accumulate_eligible(vertex_shader);
    accumulate_eligible(pixel_shader);
    if (draw_shared_route_mask_) {
  draw_trace_milestone("after-eligible");
      static const bool s_fetch_dirty = [] {
        const char* v = std::getenv("XE_METAL_FETCH_DIRTY");
        return !(v && v[0] == '0' && !v[1]);
      }();
      shared_texture_cache_->PrepareEligible(
          draw_shared_route_mask_,
          s_fetch_dirty ? fetch_constant_dirty_mask_ : ~0u);
      {
        // Census: how many eligible bindings were actually rewritten since
        // the previous draw (the ceiling of what the dirty mask can skip).
        static uint64_t s_draws = 0, s_eligible_bits = 0, s_dirty_bits = 0;
        s_eligible_bits += ::rex::BitCount(draw_shared_route_mask_);
        s_dirty_bits += ::rex::BitCount(draw_shared_route_mask_ &
                                      fetch_constant_dirty_mask_);
        if ((++s_draws & 65535) == 0) {
          REXLOG_INFO("MetalFetchDirty draws={} eligible/draw={:.2f} dirty/draw={:.2f}",
                 s_draws, double(s_eligible_bits) / s_draws,
                 double(s_dirty_bits) / s_draws);
        }
      }
      fetch_constant_dirty_mask_ &= ~draw_shared_route_mask_;
      // Verify every routed fetch is actually servable now (its load may
      // have been refused: unmappable range, view or slot failure). A fetch
      // that cannot be served GPU-side leaves the mask, and if this draw
      // elided the consumer drain on the strength of buffer serving, that
      // fetch's ranges are drained here -- still before the consuming
      // encoder opens -- so the legacy path reads converged RAM instead of
      // the draw being skipped.
      draw_route_verify_submission_ = CurrentEncodingSubmission();
      uint32_t bits = draw_shared_route_mask_;
      uint32_t index;
      metal::GuestRangeSet& unserved_ranges = unserved_ranges_scratch_;
      unserved_ranges.Clear();
      while (rex::bit_scan_forward(bits, &index)) {
        bits = ((bits) & ((bits) - 1));
        const bool is_signed = (route_signed_mask >> index) & 1u;
        if (shared_texture_cache_->GetServedSlot(index, is_signed)) {
          shared_texture_cache_->LatchServe(index);
          continue;
        }
        draw_shared_route_mask_ &= ~(1u << index);
        auto fetch = regs.GetTextureFetch(index);
        metal::FetchGuestRanges rng = ComputeFetchGuestRanges(fetch);
        if (auto r = metal::GuestRange::FromBounds(rng.base_begin,
                                                   rng.base_end)) {
          unserved_ranges.Add(*r);
        }
        if (rng.mip_end > rng.mip_begin) {
          if (auto r = metal::GuestRange::FromBounds(rng.mip_begin,
                                                     rng.mip_end)) {
            unserved_ranges.Add(*r);
          }
        }
        static uint32_t s_unserved_logs = 0;
        // XE_METAL_UNSERVED_LOG=N raises the bound (per-title attribution:
        // the first 64 of a streaming title are all one reason).
        static const uint32_t s_unserved_log_limit = [] {
          const char* v = std::getenv("XE_METAL_UNSERVED_LOG");
          return v ? uint32_t(strtoul(v, nullptr, 10)) : 64u;
        }();
        if (s_unserved_logs++ < s_unserved_log_limit) {
          REXLOG_WARN(
              "MetalSharedTex UNSERVED fc={} fmt={} base={:08X} {}x{} "
              "mips={}..{} mip_addr={:08X} signed={} draw={} ordering={} "
              "why={}",
              index, uint32_t(fetch.format), fetch.base_address << 12,
              fetch.size_2d.width + 1, fetch.size_2d.height + 1,
              uint32_t(uint32_t(fetch.mip_min_level)), uint32_t(uint32_t(fetch.mip_max_level)),
              uint32_t(fetch.mip_address) << 12, is_signed ? 1 : 0,
              trace_draw_index_, draw_gpu_ordering_active_ ? 1 : 0,
              shared_texture_cache_->DescribeServeState(index, is_signed));
        }
      }
      if (!unserved_ranges.empty() && draw_gpu_ordering_active_) {
        unserved_ranges.Normalize();
        if (!ResolveRamConsumerDependencies(metal::ConsumerKind::kTexture,
                                            unserved_ranges)) {
          REXLOG_ERROR(
              "MetalCommandProcessor: unserved routed fetch RAM convergence "
              "incomplete at draw {}",
              trace_draw_index_);
        }
      }
    }
  }

  draw_trace_milestone("after-texture-route");
  // PP1 + PP2-auto + PP3-auto + PP4-fixed: normalize the routed draws through
  // the shared
  // ::rex::gpu::PrimitiveProcessor — the single normalization authority for the routed set.
  // PP1 routes native restart-disabled line/triangle list/strip draws;
  // PP2-auto additionally routes auto-indexed triangle fans (to the built-in
  // fan table), PP3-auto routes auto-indexed line loops to a host line strip
  // plus a closing-index remap, and PP4-fixed routes only matching 16-bit DMA
  // strip reset without conversion. This runs at the proven pre-encoder seam
  // (before BeginFrameEncoder below); the Metal override of
  // RequestGuestIndexSharedMemoryRange is a no-op, so Process performs no
  // shared-memory RequestRange — avoiding the unwanted shared-buffer upload and
  // its intra-frame hazard flush (commit/wait). The routed set reads no guest
  // index memory inside Process (PP1 pass-through and auto fans alike), so it
  // emits no trace record of its own; the existing explicit WriteMemoryRead of
  // any DMA index range above preserves capture (auto fans/loops have no such
  // range).
  // A routed draw skipped downstream is harmless. The bind/draw is emitted from
  // pp_result below.
  bool pp_routed = false;
  // PP2-auto: auto-indexed triangle fans additionally route through Process to
  // the shared kHostBuiltinForAuto fan table (center-first order, byte/order-
  // identical to the inline auto-fan expansion). DMA/reset fans stay inline.
  bool auto_fan_route = IsAutoFanRoutable(regs, prim_type);
  ::rex::gpu::PrimitiveProcessor::ProcessingResult pp_result{};
  draw_trace_milestone("before-primitive-processor");
  if (primitive_processor_ && !use_geometry_emulation && !point_strip_route &&
      !rect_strip_route &&
      (IsPp1Routable(regs, prim_type) || auto_fan_route ||
       auto_quad_route || auto_line_loop_route || fixed_reset_strip_route ||
       converted_class_route) &&
      IsPp1DrawViewConsistent(
          regs, index_count, index_buffer_info != nullptr,
          index_buffer_info ? index_buffer_info->guest_base : 0,
          index_buffer_info ? index_buffer_info->format : xenos::IndexFormat::kInt16,
          index_buffer_info ? index_buffer_info->endianness : xenos::Endian::kNone,
          index_buffer_info ? index_buffer_info->count : 0)) {
    if (primitive_processor_->Process(pp_result)) {
      // The shared processor is the normalization authority for every routed
      // class. Accept any result the emission below can bind: a plain vertex
      // host VS type, a host topology Metal maps (the native list/strip set,
      // kTriangleList for converted fans/quads, kLineStrip for converted
      // loops) and one of the five index-buffer types. Anything else means
      // the routing predicates and Process disagree about the draw; fail
      // closed to the inline path (or the skip below for classes without
      // one) rather than bind a shape the emission never audited.
      MTLPrimitiveType mapped_host_prim = MTLPrimitiveTypeTriangle;
      const bool host_type_ok =
          pp_result.host_vertex_shader_type ==
              ::rex::gpu::Shader::HostVertexShaderType::kVertex &&
          MapPrimitiveType(pp_result.host_primitive_type, &mapped_host_prim) &&
          pp_result.host_primitive_type != xenos::PrimitiveType::kTriangleFan;
      bool index_type_ok;
      switch (pp_result.index_buffer_type) {
        case ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kNone:
        case ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kGuestDMA:
        case ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kHostConverted:
        case ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kHostBuiltinForAuto:
        case ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kHostBuiltinForDMA:
          index_type_ok = true;
          break;
        default:
          index_type_ok = false;
          break;
      }
      // Auto-indexed classes never produce a guest-DMA-backed stream, and the
      // PP1/PP4 pass-through classes never change topology: both are
      // invariants of the shared code, pinned here so a shared-side change
      // cannot silently reach the emission.
      const bool auto_source =
          regs.Get<reg::VGT_DRAW_INITIATOR>().source_select ==
          xenos::SourceSelect::kAutoIndex;
      const bool source_ok =
          !auto_source ||
          (pp_result.index_buffer_type !=
               ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kGuestDMA &&
           pp_result.index_buffer_type !=
               ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kHostBuiltinForDMA);
      const bool topology_ok =
          (prim_type != xenos::PrimitiveType::kLineList &&
           prim_type != xenos::PrimitiveType::kLineStrip &&
           prim_type != xenos::PrimitiveType::kTriangleList &&
           prim_type != xenos::PrimitiveType::kTriangleStrip) ||
          pp_result.host_primitive_type == prim_type;
      if (host_type_ok && index_type_ok && source_ok && topology_ok) {
        pp_routed = true;
      } else {
        REXLOG_ERROR(
            "MetalPrimitiveProcessor: routed draw produced a shape the "
            "emission cannot bind (guest_prim {} host_prim {} vs_type {} "
            "count {}/{} reset {} ibt {} format {}); staying inline.",
            uint32_t(prim_type), uint32_t(pp_result.host_primitive_type),
            uint32_t(pp_result.host_vertex_shader_type),
            pp_result.host_draw_vertex_count, index_count,
            pp_result.host_primitive_reset_enabled,
            uint32_t(pp_result.index_buffer_type),
            uint32_t(pp_result.host_index_format));
        assert_always();
      }
    }
  }

  draw_trace_milestone("after-primitive-processor");
  if (pp_routed &&
      pp_result.index_buffer_type ==
          ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kHostConverted) {
    ++prim_census_[uint32_t(prim_type) & 31][7];
  }

  // Auto line loops have no valid inline Metal fallback: the guest topology is
  // intentionally unmapped. If view consistency, Process, or the exact shape
  // guard rejected the route, preserve the prior behavior and skip.
  if (auto_line_loop_route && !pp_routed) {
    RecordDrawSkip(MetalDrawSkipReason::kUnsupportedCapability,
                   "line-loop-route");
    return true;
  }
  // Likewise a quad list taken off geometry emulation has no inline path.
  if (auto_quad_route && !pp_routed) {
    RecordDrawSkip(MetalDrawSkipReason::kUnsupportedCapability, "quad-route");
    return true;
  }
  // A guest-DMA line loop with primitive reset has no inline path either
  // (the inline loop route only closes reset-disabled loops).
  if (converted_class_route && !pp_routed &&
      prim_type == xenos::PrimitiveType::kLineLoop && !dma_line_loop_route) {
    RecordDrawSkip(MetalDrawSkipReason::kUnsupportedCapability,
                   "line-loop-route");
    return true;
  }
  // A converted or built-in stream with nothing to draw (fan/quad with fewer
  // than 3/4 indices, a loop with one) is a successful no-draw; skip before
  // opening an encoder, matching the inline expansions' degenerate skips.
  if (pp_routed && pp_result.host_draw_vertex_count == 0 &&
      (pp_result.index_buffer_type ==
           ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kHostConverted ||
       pp_result.index_buffer_type ==
           ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kHostBuiltinForDMA)) {
    RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect, "pp-degenerate");
    return true;
  }
  // A degenerate loop is a successful no-draw. Skip before opening an encoder
  // or allocating constants, and never expose the synthetic closing vertex.
  if (auto_line_loop_route && pp_result.host_draw_vertex_count == 0) {
    RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                   "line-loop-degenerate");
    return true;
  }

  // A routed guest-DMA index buffer can be bound straight from the shared
  // memory buffer with the vertex shader swapping it (vertex_index_endian),
  // instead of the CPU byte-swapping every index into the upload arena. The
  // range is requested like a vertex fetch (consumed-range hazard tracking,
  // rename on a rewrite hazard), so the bound bytes are the ones the CPU path
  // would have swapped. Only the endian shapes SwapIndicesInto treats
  // identically to the shader are taken; 4-byte alignment is Metal's
  // index-buffer offset rule.
  // Default on; XE_METAL_GPU_INDEX_SWAP=0 restores the CPU swap.
  bool direct_index = false;
  xenos::Endian direct_index_endian = xenos::Endian::kNone;
  uint32_t direct_index_offset = 0;
  static const bool s_gpu_index_swap = [] {
    const char* v = std::getenv("XE_METAL_GPU_INDEX_SWAP");
    return !v || std::strcmp(v, "0") != 0;
  }();
  if (s_gpu_index_swap && pp_routed && !use_tessellation_emulation &&
      true &&
      pp_result.index_buffer_type ==
          ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kGuestDMA &&
      pp_result.host_draw_vertex_count &&
      !(pp_result.guest_index_base & 3)) {
    const bool i32 = pp_result.host_index_format == xenos::IndexFormat::kInt32;
    const xenos::Endian e = pp_result.host_shader_index_endian;
    bool endian_ok;
    xenos::Endian shader_endian;
    if (i32) {
      endian_ok = e == xenos::Endian::kNone || e == xenos::Endian::k8in32;
      shader_endian = e;
    } else {
      endian_ok = e == xenos::Endian::kNone || e == xenos::Endian::k8in16 ||
                  e == xenos::Endian::k8in32;
      shader_endian =
          e == xenos::Endian::kNone ? xenos::Endian::kNone
                                    : xenos::Endian::k8in16;
    }
    const uint32_t bytes = pp_result.host_draw_vertex_count * (i32 ? 4u : 2u);
    if (endian_ok) {
      MetalSharedMemory::VfetchRename rename;
      bool ok;
      if (MetalSharedMemory::VfetchRenameEnabled()) {
        ok = shared_memory_->RequestVertexFetchRange(pp_result.guest_index_base,
                                                     bytes, &rename);
      } else {
        ok = shared_memory_->RequestConsumedRange(pp_result.guest_index_base,
                                                  bytes);
      }
      if (ok) {
        direct_index = true;
        direct_index_endian = shader_endian;
        direct_index_offset =
            rename.length ? rename.buffer_offset +
                                (pp_result.guest_index_base - rename.guest_start)
                          : pp_result.guest_index_base;
        ++direct_index_draws_;
      }
    }
  }

  dummy_depth_pass_ = dummy_depth;
  memexport_pass_ = memexport_draw;
  pixel_export_pass_ = pixel_export_only;
  if (pixel_export_only) {
    // The pass's only attachment is a scratch depth covering the guest
    // scissor (and the viewport when clipping is on), bucketed to powers of
    // two so consecutive export draws share one encoder and one texture.
    ::rex::gpu::draw_state::Scissor export_scissor;
    ::rex::gpu::draw_state::GetScissor(regs, export_scissor, true);
    uint32_t export_right = export_scissor.offset[0] + export_scissor.extent[0];
    uint32_t export_bottom =
        export_scissor.offset[1] + export_scissor.extent[1];
    if (!regs.Get<reg::PA_CL_CLIP_CNTL>().clip_disable) {
      draw_util::ViewportInfo export_viewport;
      draw_util::GetViewportInfoArgs export_vp_args = GetMetalViewportInfoArgs(
          regs, norm_depth, pixel_shader->IsDepthWritten());
      draw_util::GetHostViewportInfo(&export_vp_args, GetXenosSettings(), export_viewport);
      auto viewport_end = [&](uint32_t axis) {
        int64_t end = int64_t(export_viewport.xy_offset[axis]) +
                      int64_t(export_viewport.xy_extent[axis]);
        return uint32_t(std::max<int64_t>(end, 0));
      };
      export_right = std::min(export_right, viewport_end(0));
      export_bottom = std::min(export_bottom, viewport_end(1));
    }
    export_right *= draw_resolution_scale_x_;
    export_bottom *= draw_resolution_scale_y_;
    if (!export_right || !export_bottom) {
      RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                     "pixel-export-empty-area");
      return true;
    }
    auto bucket = [](uint32_t v) {
      uint32_t b = 64;
      while (b < v && b < 16384) {
        b <<= 1;
      }
      return b;
    };
    pixel_export_extent_[0] = bucket(export_right);
    pixel_export_extent_[1] = bucket(export_bottom);
    if (s_memexport_log) {
      for (const auto& range : memexport_ranges) {
        REXLOG_WARN(
            "MetalMemexportPixelNoRTExec draw={} PS shader={:016X} "
            "dest={:08X} bytes={} prim={} n={} area={}x{} pass={}x{}",
            trace_draw_index_, pixel_shader->GetUcodeDataHash(),
            range.base_address_dwords << 2, range.size_bytes,
            uint32_t(prim_type), index_count, export_right, export_bottom,
            pixel_export_extent_[0], pixel_export_extent_[1]);
      }
    }
  }
  pending_pass_bound_ = pass_bound;
  // Host scissor rows of this draw (pack census dirty rows); whole range
  // until the scissor is applied below.
  uint32_t draw_host_y0 = 0, draw_host_y1 = UINT32_MAX;
  bool draw_full_width = true;  // the scissor spans the render width
  // Attribution aid: XE_METAL_PASS_SPLIT_EVERY=<n> ends the open pass every n
  // draws (legacy binding), to measure what a pass boundary alone does to
  // attachment contents on this GPU.
  static const uint32_t s_split_every = [] {
    const char* v = std::getenv("XE_METAL_PASS_SPLIT_EVERY");
    return v ? uint32_t(strtoul(v, nullptr, 10)) : 0u;
  }();
  if (s_split_every && frame_open_ && (draw_count_ % s_split_every) == 0) {
    EndRenderEncoder(metal::MetalPassEndReason::kAttachmentKey);
  }
  // Snapshot fit (texture cache): prepare fetch-sized views of bridge
  // snapshots BEFORE this draw's encoder opens — the blit is a transfer
  // (pass boundary) and cannot be encoded once the render encoder exists.
  if (texture_cache_) {
    auto prepare_fits = [&](MetalShader* shader) {
      if (!shader) return;
      for (const auto& binding : shader->GetTextureBindingsAfterTranslation()) {
        if (binding.fetch_constant >= xenos::kTextureFetchConstantCount) {
          continue;
        }
        auto f = regs.GetTextureFetch(binding.fetch_constant);
        if (!(f.base_address << 12)) continue;
        texture_cache_->PrepareSnapshotFit(f, binding.is_signed);
      }
    };
    prepare_fits(pixel_shader);
    prepare_fits(vertex_shader);
  }
  draw_trace_milestone("after-snapshot-fit");
  {
    // Set for every draw: a stale mask must never reach another draw.
    float overwrite_rect[4] = {};
    const uint32_t overwrite_slots =
        memexport_draw ? 0u
                       : ComputeDrawOverwrite(prim_type, vertex_shader,
                                              pixel_shader,
                                              normalized_color_mask,
                                              norm_depth, overwrite_rect);
    render_target_cache_->SetDrawOverwrite(overwrite_slots, overwrite_rect);
  }
  __unsafe_unretained id<MTLRenderCommandEncoder> encoder =
      (__bridge id<MTLRenderCommandEncoder>)BeginFrameEncoder();
  if (!encoder) {
    RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                   "encoder-unavailable");
    return true;
  }
  if (ZPDCensusEnabled()) {
    NoteZPDCensusDraw(zpd_count_only_draw ? ZPDCensusDraw::kCountOnly
                      : zpd_query_open_   ? ZPDCensusDraw::kMeasured
                                          : ZPDCensusDraw::kUnmeasured,
                      kDepthEnabled && depth_bound && norm_depth.z_enable);
  }
  // Every encoder call below goes through the stream; whatever path returns,
  // the draw's ops are published (or replayed inline) on the way out.
  MetalEncodeStream& es = *encode_stream_;
  struct StreamCommit {
    MetalEncodeStream& stream;
    ~StreamCommit() { stream.Commit(); }
  } stream_commit{es};
  draw_trace_milestone("after-encoder");
  // In-encoder ordering for routed rasterizing memexport. Halo: Reach skins
  // its faces this way: two exporting draws write a 576 KiB scratch range,
  // the next two draws vertex-fetch it, then the next producer pair
  // overwrites it, three times a frame, all in one render pass. Metal orders
  // tracked resources between encoders only, so without a barrier the
  // consumer's fetch races the producer's vertex-stage stores (faces drew as
  // spikes) and the next producer races the previous consumer's reads.
  // XE_METAL_RASTER_EXPORT_BARRIER=0 drops the barriers (diagnostic).
  {
    static const bool s_raster_export_barrier = [] {
      const char* v = std::getenv("XE_METAL_RASTER_EXPORT_BARRIER");
      return !(v && v[0] == '0' && !v[1]);
    }();
    const uintptr_t encoder_id = uintptr_t((__bridge void*)encoder);
    const bool encoder_has_raster_export =
        raster_export_encoder_ != 0 && raster_export_encoder_ == encoder_id;
    if (s_raster_export_barrier && encoder_has_raster_export &&
        (memexport_raster_routed || ordered_against_memexport)) {
      es.BufferBarrier(MTLRenderStageVertex,
                       MTLRenderStageVertex | MTLRenderStageFragment);
    }
    if (memexport_raster_routed) {
      raster_export_encoder_ = encoder_id;
    }
  }
  if (PassCensusEnabled() && !memexport_draw) {
    pass_census_.NoteDraw(metal::GetMetalPassAttachmentUse(
        norm_depth, normalized_color_mask, blend_controls,
        regs[XE_GPU_REG_RB_STENCILREFMASK],
        regs[XE_GPU_REG_RB_STENCILREFMASK_BF],
        pixel_shader && pixel_shader->IsDepthWritten()));
  }

  // --- Marshal the constant buffers (b0-b4), matching the D3D12 backend. ---
  MetalUploadAllocation system_alloc{};
  ::rex::gpu::DXBCShaderTranslator::SystemConstants system_constants;
  std::memset(&system_constants, 0, sizeof(system_constants));
  {
    MetalSystemConstantGuestState system_constant_guest_state =
        GetMetalSystemConstantGuestState(regs);
    // Viewport -> ndc_scale/offset (position-critical: zeroing collapses output).
    draw_util::ViewportInfo viewport_info;
    // x_max/y_max is the maximum host viewport extent, NOT the render-target
    // size. Both reference backends pass the device max (D3D12:
    // D3D12_VIEWPORT_BOUNDS_MAX, Vulkan: maxViewportDimensions) and let the
    // render target clip an oversized guest viewport. Passing 1280x720 here
    // instead made GetHostViewportInfo *rescale* (zoom-crop) any guest viewport
    // wider/taller than the RT into it — the splash-screen "zoom". Use the max
    // guest RT extent (8192, already the clip-disabled cap and within Metal's
    // 16384 viewport limit) so guest content beyond 1280x720 is clipped, not
    // scaled.
    draw_util::GetViewportInfoArgs vp_args = GetMetalViewportInfoArgs(
        regs, norm_depth, pixel_shader && pixel_shader->IsDepthWritten(),
        msaa_fold_scale_x * draw_resolution_scale_x_,
        msaa_fold_scale_y * draw_resolution_scale_y_, draw_resolution_scale_x_,
        draw_resolution_scale_y_, window_offset_tiles != 0);
    draw_util::GetHostViewportInfo(&vp_args, GetXenosSettings(), viewport_info);
    for (uint32_t i = 0; i < 3; ++i) {
      system_constants.ndc_scale[i] = viewport_info.ndc_scale[i];
      system_constants.ndc_offset[i] = viewport_info.ndc_offset[i];
    }
    // Window offset carried in the EDRAM bases: PsParamGen adds it back.
    {
      auto pa_sc_window_offset = regs.Get<reg::PA_SC_WINDOW_OFFSET>();
      system_constants.param_gen_window_offset[0] =
          window_offset_tiles ? float(pa_sc_window_offset.window_x_offset)
                              : 0.0f;
      system_constants.param_gen_window_offset[1] =
          window_offset_tiles ? float(pa_sc_window_offset.window_y_offset)
                              : 0.0f;
      system_constants.param_gen_window_offset_padding[0] = 0;
      system_constants.param_gen_window_offset_padding[1] = 0;
    }
    // Exact representative pixel at an even draw resolution scale
    // (metal_draw_resolution_scale.h): shift geometry half a host pixel right
    // and down so the representative host pixel samples the guest pixel's own
    // sample point. Host NDC Y points up (Metal's viewport maps +1 to the top
    // row), so moving down is a negative Y offset.
    for (uint32_t i = 0; i < 2; ++i) {
      float shift = metal::MetalScaledPixelShiftHostPixels(
          i ? draw_resolution_scale_y_ : draw_resolution_scale_x_);
      if (shift != 0.0f && viewport_info.xy_extent[i]) {
        system_constants.ndc_offset[i] +=
            (i ? -shift : shift) * 2.0f / float(viewport_info.xy_extent[i]);
      }
    }
    if (msaa_fold_pin_depth) {
      // Constant depth = the canonical transfer's result (see the fold).
      system_constants.ndc_scale[2] = 0.0f;
      system_constants.ndc_offset[2] = msaa_fold_pin_ndc_z;
    }
    draw_util::NormalizedUserClipPlanes user_clip_planes =
        draw_util::GetNormalizedUserClipPlanes(regs);
    std::memcpy(system_constants.user_clip_planes,
                user_clip_planes.equations,
                sizeof(system_constants.user_clip_planes));
    draw_util::NormalizedPointParameters point_parameters =
        draw_util::GetNormalizedPointParameters(regs, viewport_info,
                                                draw_resolution_scale_x_,
                                                draw_resolution_scale_y_);
    system_constants.point_vertex_diameter_min =
        point_parameters.vertex_diameter_min;
    system_constants.point_vertex_diameter_max =
        point_parameters.vertex_diameter_max;
    system_constants.point_constant_diameter[0] =
        point_parameters.constant_diameter[0];
    system_constants.point_constant_diameter[1] =
        point_parameters.constant_diameter[1];
    system_constants.point_screen_diameter_to_ndc_radius[0] =
        point_parameters.screen_diameter_to_ndc_radius[0];
    system_constants.point_screen_diameter_to_ndc_radius[1] =
        point_parameters.screen_diameter_to_ndc_radius[1];
    // Position-relevant flags.
    auto pa_cl_vte_cntl = regs.Get<reg::PA_CL_VTE_CNTL>();
    uint32_t flags = 0;
    if (memexport_draw || memexport_raster_routed) {
      // The translator predicates every eA/eM store on this flag (exports
      // compile in but no-op without it — the "stores did not land" oracle).
      // Task 2.2: the routed RASTERIZING producer needs it for exactly the
      // same reason; binding the writable UAV without publishing this flag
      // produces a silently export-free draw (measured: VP draws 530/693/733/
      // 734/735 published GPU-written ranges whose buffer bytes never changed).
      flags |= ::rex::gpu::DXBCShaderTranslator::kSysFlagSharedMemoryIsUAV;
    }
    if (pa_cl_vte_cntl.vtx_xy_fmt) flags |= ::rex::gpu::DXBCShaderTranslator::kSysFlagXYDividedByW;
    if (pa_cl_vte_cntl.vtx_z_fmt) flags |= ::rex::gpu::DXBCShaderTranslator::kSysFlagZDividedByW;
    if (pa_cl_vte_cntl.vtx_w0_fmt) flags |= ::rex::gpu::DXBCShaderTranslator::kSysFlagWNotReciprocal;
    if (system_constant_guest_state.primitive_polygonal) {
      flags |= ::rex::gpu::DXBCShaderTranslator::kSysFlagPrimitivePolygonal;
    }
    // Line lists and strips, and also line loops, 2D line strips and line
    // patches (the shared rule D3D12 uses; it sets the PsParamGen line bit).
    if (::rex::gpu::draw_state::IsPrimitiveLine(regs)) {
      flags |= ::rex::gpu::DXBCShaderTranslator::kSysFlagPrimitiveLine;
    }
    if (system_constant_guest_state.depth_float24) {
      flags |= ::rex::gpu::DXBCShaderTranslator::kSysFlagDepthFloat24;
    }
    // Alpha test: the compare function is a 3-bit (less|equal|greater) mask in
    // the flags. Leaving it 0 means kNever -> the pixel shader discards EVERY
    // fragment. When alpha test is disabled it must be kAlways (pass all).
    auto rb_colorcontrol = regs.Get<reg::RB_COLORCONTROL>();
    xenos::CompareFunction alpha_test_function =
        rb_colorcontrol.alpha_test_enable ? rb_colorcontrol.alpha_func
                                          : xenos::CompareFunction::kAlways;
    // Gamma write conversion: a k_8_8_8_8_GAMMA render target stores piecewise-
    // linear gamma; the PS must encode its linear output (matches D3D12).
    // Without this the scene was written LINEAR and every downstream pass that
    // gamma-decodes it (composite, bloom) darkened it (0.5 -> ~0.22),
    // compounding into the near-black gameplay image.
    // A/B (XE_METAL_NO_GAMMA_ENCODE=1): skip the PS linear->gamma encode on
    // gamma RTs — the exposure/history-loop stability probe (gamma decode
    // NO_SIGNS flattens the oscillation; this tests the encode leg).
    static const bool s_no_gamma_encode =
        std::getenv("XE_METAL_NO_GAMMA_ENCODE") != nullptr;
    if (!s_no_gamma_encode && color_bound) {
      flags |= GetMetalGammaRenderTargetMask(color_infos)
               << ::rex::gpu::DXBCShaderTranslator::kSysFlagConvertColor0ToGammaShift;
    }
    // Pixel-shader coverage side effects (alpha test, alpha to mask) apply
    // only when the RB runs the pixel shader at all: EdramMode::kColorDepth and
    // draw_util::IsPixelShaderNeededWithRasterization -- the same rule the
    // D3D12/Vulkan backends use to drop the pixel shader entirely. Just Cause 2
    // clears its three shadow-cascade depth buffers with depth-only rects in
    // EdramMode::kDepth while RB_COLORCONTROL still carries the previous
    // draw's alpha test (GEQUAL 1/255) and the rect's vertex alpha is 0: the
    // reference backends drop the PS and the clear lands; running the alpha
    // test here discarded every fragment, the cascade depth stayed stale, the
    // memexport shadow LUT copied garbage and the world rendered dark, with a
    // correct ("flash") frame whenever the game happened to leave alpha test
    // disabled. XE_METAL_PS_COVERAGE_LEGACY=1 restores the unconditional
    // alpha test (rollback); XE_METAL_ALPHA_TEST_LOG=1 logs alpha-tested
    // color-masked draws.
    static const bool s_ps_coverage_legacy =
        std::getenv("XE_METAL_PS_COVERAGE_LEGACY") != nullptr;
    static const bool s_alpha_test_log =
        std::getenv("XE_METAL_ALPHA_TEST_LOG") != nullptr;
    const bool ps_coverage_effects =
        regs.Get<reg::RB_MODECONTROL>().edram_mode ==
            xenos::EDRAMMode::kColorDepth &&
        pixel_shader && pixel_shader->IsUcodeAnalyzed() &&
        ::rex::gpu::draw_state::IsPixelShaderNeededWithRasterization(*pixel_shader, regs);
    bool alpha_to_mask_effects = true;
    if (!s_ps_coverage_legacy && !ps_coverage_effects) {
      alpha_test_function = xenos::CompareFunction::kAlways;
      alpha_to_mask_effects = false;
    }
    if (s_alpha_test_log && rb_colorcontrol.alpha_test_enable) {
      static uint32_t s_alpha_logs = 0;
      if (s_alpha_logs++ < 64) {
        REXLOG_WARN(
            "MetalAlphaTest draw={} func={} ref={} colorcontrol={:08X} "
            "color_bound={} rb_color_mask={:08X} edram_mode={} "
            "ps_coverage_effects={}",
            trace_draw_index_, uint32_t(rb_colorcontrol.alpha_func),
            regs.Get<float>(XE_GPU_REG_RB_ALPHA_REF), rb_colorcontrol.value,
            color_bound ? 1 : 0, regs.Get<reg::RB_COLOR_MASK>().value,
            uint32_t(regs.Get<reg::RB_MODECONTROL>().edram_mode),
            ps_coverage_effects ? 1 : 0);
      }
    }
    flags |= uint32_t(alpha_test_function)
             << ::rex::gpu::DXBCShaderTranslator::kSysFlagAlphaPassIfLessShift;
    system_constants.flags = flags;
    system_constants.alpha_test_reference =
        regs.Get<float>(XE_GPU_REG_RB_ALPHA_REF);
    // The DXBC translator implements the exact Xenos alpha-to-mask thresholds,
    // dither offsets, and coverage output in the pixel shader. Populate its
    // dynamic ABI from the same normalized count used by the pipeline and
    // attachments; Metal hardware alpha-to-coverage stays off to avoid
    // filtering the shader-produced mask a second time.
    system_constants.sample_count_log2[0] =
        pipeline_raster_state.sample_count_log2_x;
    system_constants.sample_count_log2[1] =
        pipeline_raster_state.sample_count_log2_y;
    system_constants.alpha_to_mask =
        alpha_to_mask_effects ? pipeline_raster_state.alpha_to_mask : 0u;
    // Texture signedness / gamma (8 bits per fetch constant): tells the PS/VS
    // to decode gamma-signed fetches (TextureSign::kGamma) to linear on sample
    // and handle signed formats. Left zeroed, every gamma texture (incl. the
    // resolved scene the composite samples) was read raw.
    // Unsigned fixed-point integer texture scaling
    // (openspec/changes/implement-unsigned-integer-texture-scaling).
    // ::rex::graphics::metal::GetMetalSettings().metal_texture_integer_scale.Get()=false is the EXACT rollback: no scale is
    // published, so every fetch reads a zero packed value and takes the
    // shader's uniform early-out, leaving output identical to before this
    // capability existed. The shader ABI is emitted either way, so the rollback
    // does not change which cached shaders are valid.
    const bool integer_texture_scaling_enabled =
        ::rex::graphics::metal::GetMetalSettings().metal_texture_integer_scale.Get();
    auto fill_texture_signs = [&](MetalShader* shader) {
      if (!shader) return;
      for (const auto& binding : shader->GetTextureBindingsAfterTranslation()) {
        uint32_t fc = binding.fetch_constant;
        auto fetch = regs.GetTextureFetch(fc);
        // fetch_static_info_ holds the signs and scale bits of every constant
        // whose known bit survives (cleared by WriteRegister on a changed
        // dword); recomputing them per binding per draw was ~1.5% of the
        // Burnout command-processor thread. XE_METAL_FETCH_SIGNS_MEMO=0
        // recomputes.
        static const bool s_signs_memo = [] {
          const char* v = std::getenv("XE_METAL_FETCH_SIGNS_MEMO");
          return !(v && v[0] == '0' && !v[1]);
        }();
        const bool signs_known =
            s_signs_memo && fc < 32 && (fetch_plain_known_mask_ & (1u << fc));
        uint32_t signs = signs_known ? fetch_static_info_[fc].swizzled_signs
                                     : ::rex::xenos::SwizzleSigns(fetch);
        system_constants.texture_swizzled_signs[fc >> 2] |=
            signs << ((fc & 3) * 8);
        // Integer num_format on a fixed-point format needs the guest's
        // unnormalized range restored in the shader. Derive it HERE, beside the
        // signs, from the same fetch constant.
        //
        // Deliberately not routed through shared TextureCache::RequestTextures
        // / TextureBinding the way upstream does: MetalTextureCache is a
        // standalone class, not a shared-TextureCache subclass, and shared
        // RequestTextures only ever runs for the C1T-R eligible subset. A
        // census probe placed there reported two binding classes for an entire
        // Just Cause 2 frame — a false zero that would have closed this work
        // wrongly. This loop, over GetTextureBindingsAfterTranslation, is the
        // site that sees EVERY Metal binding.
        //
        // fetch.swizzle is passed as the swizzle, matching SwizzleSigns above
        // exactly: both resolve output component i back to the same source
        // component, so the scale field for a lane always describes the same
        // component as that lane's sign. They are consumed together, in the
        // same shader, one immediately after the other.
        if (integer_texture_scaling_enabled) {
          if (signs_known) {
            if (fc < kMetalIntegerScaleSlotCount) {
              system_constants.texture_integer_scale_bits[fc] =
                  fetch_static_info_[fc].integer_scale_bits;
            }
          } else {
            PublishIntegerScaleBits(fc, fetch, uint8_t(signs),
                                    system_constants.texture_integer_scale_bits,
                                    kMetalIntegerScaleSlotCount,
                                    ::rex::graphics::metal::GetMetalSettings().dxbc_implicit_lod.Get());
          }
        }
        // Draw resolution scaling: a fetch served from a resolve snapshot reads
        // the scaled snapshot, so the shader applies the scaled texel-offset
        // convention to it. Decided by the shared serve classification, the
        // same one GetTextureSlot serves from; every other source is 1x.
        if ((draw_resolution_scale_x_ > 1 || draw_resolution_scale_y_ > 1) &&
            texture_cache_) {
          ResolvedFetchService service =
              texture_cache_->ClassifyFetchService(fetch, binding.is_signed);
          if (service == ResolvedFetchService::kBridgeSnapshot ||
              service == ResolvedFetchService::kExactCoverSnapshot ||
              service == ResolvedFetchService::kScaledCoverSnapshot) {
            system_constants.textures_resolution_scaled |= uint32_t(1) << fc;
          }
        }
        // Gamma-parity diagnostic: the game's signs describe the raw bytes
        // hardware resolves preserve — compare against the resolve source's
        // gamma-ness we recorded (see IssueCopy).
        static const bool s_gamma_parity = std::getenv("XE_METAL_GAMMA_PARITY");
        if (s_gamma_parity) {
          uint32_t fbase = fetch.base_address << 12;
          auto it = gamma_parity_resolves_.find(fbase);
          if (it != gamma_parity_resolves_.end()) {
            bool fetch_gamma = (signs & 0b11) == 0b11;  // component 0 kGamma
            if (fetch_gamma != it->second &&
                gamma_parity_reported_.insert(fbase).second) {
              REXLOG_WARN(
                  "MetalGammaParity MISMATCH base={:08X}: resolve source "
                  "{}GAMMA but fetch signs={:02X} ({}gamma) — byte domain "
                  "disagreement",
                  fbase, it->second ? "" : "NOT-", signs,
                  fetch_gamma ? "" : "not-");
            } else if (gamma_parity_reported_.insert(fbase ^ 0x80000000u)
                           .second) {
              REXLOG_INFO("MetalGammaParity ok base={:08X}: src_gamma={} signs={:02X}",
                     fbase, it->second, signs);
            }
          }
        }
      }
    };
    // A/B: XE_METAL_NO_SIGNS=1 leaves signs zeroed (all-unsigned, no gamma
    // decode) to isolate sign-driven fetch behavior (signed-SRV selection).
    static const bool s_no_signs = std::getenv("XE_METAL_NO_SIGNS") != nullptr;
    if (!s_no_signs) {
      fill_texture_signs(vertex_shader);
      fill_texture_signs(pixel_shader);
    }
    // Sonic black-sky task 3.2 (diagnostic, replay-scale): one line per
    // texture binding per draw, so a captured frame's sampled-source
    // inventory can be walked offline. Bounded hard for live safety.
    // The value is the line budget (any non-number = 8192).
    static const uint32_t s_draw_tex_log = [] {
      const char* v = std::getenv("XE_METAL_DRAW_TEX_LOG");
      if (!v) return 0u;
      uint32_t lines = uint32_t(strtoul(v, nullptr, 10));
      return lines > 1 ? lines : 8192u;
    }();
    if (s_draw_tex_log) {
      static uint32_t s_draw_tex_lines = 0;
      // XE_METAL_DRAW_TEX_FROM_SWAP=<swap>: only log once that guest swap has been reached. Without it the line budget
      // is spent on the first few boot frames and the frame under investigation is never described.
      static const uint32_t s_draw_tex_from_swap = [] {
        const char* v = std::getenv("XE_METAL_DRAW_TEX_FROM_SWAP");
        return v ? uint32_t(strtoul(v, nullptr, 10)) : 0u;
      }();
      const bool s_draw_tex_active = !s_draw_tex_from_swap || swap_count_ >= s_draw_tex_from_swap;
      auto log_bindings = [&](MetalShader* shader, const char* stage) {
        if (!s_draw_tex_active || !shader) return;
        for (const auto& binding : shader->GetTextureBindingsAfterTranslation()) {
          if (s_draw_tex_lines >= s_draw_tex_log) return;
          ++s_draw_tex_lines;
          auto fetch = regs.GetTextureFetch(binding.fetch_constant);
          REXLOG_INFO(
              "DrawTex draw={} {} fc={} base={:08X} fmt={} {}x{} pitch={} "
              "endian={} signed={} type={} num_format={} exp_adjust={} "
              "signs={},{},{},{} tiled={} packed_mips={} dim={} mips={}",
              trace_draw_index_, stage, binding.fetch_constant,
              fetch.base_address << 12, uint32_t(fetch.format),
              fetch.size_2d.width + 1, fetch.size_2d.height + 1,
              uint32_t(fetch.pitch) << 5, uint32_t(fetch.endianness),
              binding.is_signed ? 1 : 0, uint32_t(fetch.type),
              uint32_t(fetch.num_format), int32_t(fetch.exp_adjust),
              uint32_t(fetch.sign_x), uint32_t(fetch.sign_y),
              uint32_t(fetch.sign_z), uint32_t(fetch.sign_w),
              uint32_t(fetch.tiled), uint32_t(fetch.packed_mips),
              uint32_t(fetch.dimension), uint32_t(uint32_t(fetch.mip_max_level)));
        }
      };
      log_bindings(vertex_shader, "vs");
      log_bindings(pixel_shader, "ps");
    }
    // Color exponent bias multiplies the pixel output. Metal stores the fixed
    // 16-bit formats in SNORM host targets, which truncate to -1..1, so unlike
    // a backend configured for full-range fixed16 storage we must not apply
    // the additional /32 remap here. Doing so starves temporal luminance
    // passes and made SF4 compensate into a live white-out. The guest exponent
    // is still required for HDR formats (notably Red Dead's 7e3 chain).
    for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
      system_constants.color_exp_bias[i] =
          std::ldexp(1.0f, int32_t(color_infos[i].color_exp_bias));
    }
    // Index/vfetch helpers used by the vertex shader. The endian here must
    // describe the index buffer AS BOUND, not the guest's: our draw paths
    // CPU-swap the guest indices into the upload arena (SwapIndicesInto /
    // the fan expansion), so the value reaching SV_VertexID is already
    // host-order. Passing the guest endianness made the translated VS swap
    // it AGAIN — every indexed draw fetched byte-swapped vertex slots
    // (terrain chunks as giant wedges; chunks whose swapped indices left
    // the lattice rasterized nothing).
    //
    // Tessellated draws keep the SAME convention (design D5 endian decision):
    // the index/factor stream is CPU-swapped into the arena too, so the
    // prebuilt tess VS's in-shader XeEndianSwap32 sees kNone and is the
    // identity. Publishing the guest endian here while binding a pre-swapped
    // stream would double-swap every adaptive factor silently.
    //
    // The exception is a direct-bound draw (above): its raw guest indices are
    // bound unswapped, so the shader swaps them.
    system_constants.vertex_index_endian =
        direct_index ? direct_index_endian : xenos::Endian::kNone;
    system_constants.vertex_index_offset =
        system_constant_guest_state.vertex_index_offset;
    system_constants.vertex_index_min =
        system_constant_guest_state.vertex_index_min;
    system_constants.vertex_index_max =
        system_constant_guest_state.vertex_index_max;
    // PP3-auto: only the synthetic final vertex of a routed line loop remaps to
    // guest vertex 0. memset above keeps this 0 (a shader no-op) for every
    // non-loop draw.
    if (auto_line_loop_route) {
      system_constants.line_loop_closing_index = pp_result.line_loop_closing_index;
    }
    // Tessellation factor range (task 4.3, XeniOS :8241-8251): min/max =
    // VGT_HOS_{MIN,MAX}_TESS_LEVEL + 1. The +1 for the RANGE happens on the
    // CPU here; the adaptive per-edge +1 happens in the prebuilt VS. Only
    // tessellation pipelines read the field, and the constants block is
    // rebuilt per draw, so the assignment is gated to keep the OFF arm's
    // upload bytes bit-identical to HEAD.
    if (use_tessellation_emulation) {
      system_constants.tessellation_factor_range_min =
          regs.Get<float>(XE_GPU_REG_VGT_HOS_MIN_TESS_LEVEL) + 1.0f;
      system_constants.tessellation_factor_range_max =
          regs.Get<float>(XE_GPU_REG_VGT_HOS_MAX_TESS_LEVEL) + 1.0f;
    }

    // Diagnostic (rides XE_METAL_EXPO_TRACE=<ps hash>): log the host viewport
    // + window-offset registers for draws using that pixel shader — the
    // tonemap half-screen blocks landed at different texture rows while the
    // guest reuses the same EDRAM tiles for both halves.
    static const uint64_t s_vp_ps_hash = [] {
      const char* v = std::getenv("XE_METAL_EXPO_TRACE");
      return v ? strtoull(v, nullptr, 16) : 0ull;
    }();
    // XE_METAL_VP_RANGE=A,B additionally logs EVERY draw in that trace-draw
    // range (the window-offset placement audit over the post-tonemap chain).
    static const auto s_vp_range = []() -> std::pair<int64_t, int64_t> {
      const char* v = std::getenv("XE_METAL_VP_RANGE");
      if (!v) return {-1, -1};
      int64_t a = 0, b = 0;
      if (sscanf(v, "%lld,%lld", &a, &b) != 2) return {-1, -1};
      return {a, b};
    }();
    int64_t vp_draw_index = int64_t(trace_draw_index_) - 1;
    bool vp_log = (s_vp_ps_hash && pixel_shader &&
                   pixel_shader->GetUcodeDataHash() == s_vp_ps_hash) ||
                  (vp_draw_index >= s_vp_range.first &&
                   vp_draw_index <= s_vp_range.second);
    if (vp_log) {
      auto win_off = regs.Get<reg::PA_SC_WINDOW_OFFSET>();
      auto sc_mode = regs.Get<reg::PA_SU_SC_MODE_CNTL>();
      auto clip = regs.Get<reg::PA_CL_CLIP_CNTL>();
      REXLOG_WARN(
          "MetalVP draw {}: prim={} geo={} vp=({},{} {}x{}) win_off=({},{}) "
          "vtx_wofs_en={} clip_dis={} ndc_y=(s{} o{}) ps={:08X} blend={:08X} "
          "mask={:X} imask={:X} pgen={}",
          vp_draw_index, uint32_t(prim_type), use_geometry_emulation ? 1 : 0,
          viewport_info.xy_offset[0], viewport_info.xy_offset[1],
          viewport_info.xy_extent[0], viewport_info.xy_extent[1],
          int32_t(win_off.window_x_offset), int32_t(win_off.window_y_offset),
          uint32_t(sc_mode.vtx_window_offset_enable),
          uint32_t(clip.clip_disable), viewport_info.ndc_scale[1],
          viewport_info.ndc_offset[1],
          pixel_shader ? uint32_t(pixel_shader->GetUcodeDataHash() >> 32) : 0,
          regs[XE_GPU_REG_RB_BLENDCONTROL0], normalized_color_mask & 0xF,
          interpolator_mask, ps_param_gen_pos);
      // The draw's pixel-shader fetches: base + format + snapshot-hit, the
      // composite-input audit.
      if (pixel_shader && render_target_cache_) {
        for (const auto& binding :
             pixel_shader->GetTextureBindingsAfterTranslation()) {
          auto f = regs.GetTextureFetch(binding.fetch_constant);
          uint32_t fetch_base = f.base_address << 12;
          REXLOG_WARN("MetalVP   fetch fc={} base={:08X}{} fmt={} {}x{} swz={:03X} "
                 "endian={} tiled={} pitch={}",
                 binding.fetch_constant, fetch_base,
                 render_target_cache_->GetResolveSnapshot(fetch_base)
                     ? " [SNAP]"
                     : "",
                 uint32_t(f.format), f.size_2d.width + 1, f.size_2d.height + 1,
                 f.swizzle & 0xFFF, uint32_t(f.endianness), uint32_t(f.tiled),
                 uint32_t(f.pitch) << 5);
        }
      }
      // Geometry-side audit (zero-raster dissection): VTE transform bits,
      // index state, and the first vertices of each VS vertex binding read
      // straight from guest RAM (byteswapped) — shows where positions land.
      REXLOG_WARN("MetalVP   vte={:08X} idx={} cnt={} vgt_ofs={} min={} max={}",
             regs[XE_GPU_REG_PA_CL_VTE_CNTL], index_buffer_info != nullptr,
             index_count, regs[XE_GPU_REG_VGT_INDX_OFFSET],
             regs[XE_GPU_REG_VGT_MIN_VTX_INDX],
             regs[XE_GPU_REG_VGT_MAX_VTX_INDX]);
      {
        const float* vs_c255 = reinterpret_cast<const float*>(
            &regs[XE_GPU_REG_SHADER_CONSTANT_000_X + 255 * 4]);
        REXLOG_WARN("MetalVP   vs_c255=({:g} {:g} {:g} {:g})", vs_c255[0],
               vs_c255[1], vs_c255[2], vs_c255[3]);
      }
      if (vertex_shader) {
        for (const auto& vb : vertex_shader->GetVertexBindings()) {
          xenos::VertexFetch vf =
              regs.GetVertexFetch(vb.fetch_constant);
          uint32_t vaddr = vf.address << 2;
          REXLOG_WARN("MetalVP   vbind fc={} addr={:08X} size_dw={} endian={} "
                 "stride_dw={}",
                 vb.fetch_constant, vaddr, uint32_t(vf.size),
                 uint32_t(vf.endian), vb.stride_words);
          if (vaddr && vf.size) {
            const uint32_t* vdata = reinterpret_cast<const uint32_t*>(
                TranslateGuest<const uint8_t*>(vaddr));
            uint32_t stride = vb.stride_words ? vb.stride_words : 4;
            for (uint32_t vtx = 0;
                 vtx < 4 && (vtx + 1) * stride <= vf.size; ++vtx) {
              std::string words;
              for (uint32_t w = 0; w < stride && w < 8; ++w) {
                uint32_t raw = xenos::GPUSwap(vdata[vtx * stride + w],
                                              xenos::Endian(vf.endian));
                float fv;
                std::memcpy(&fv, &raw, 4);
                words += fmt::format(" {:g}[{:08X}]", fv, raw);
              }
              REXLOG_WARN("MetalVP     v{}:{}", vtx, words);
            }
          }
        }
      }
    }

    bool primitive_polygonal = ::rex::gpu::draw_state::IsPrimitivePolygonal(regs);

    // Set the host viewport from the integer part. Memexport passes have a
    // 1x1 attachment-less render area and rasterization disabled — the guest
    // viewport would exceed the pass bounds (validation error) and shades
    // nothing anyway.
    if (!memexport_draw && viewport_info.xy_extent[0] &&
        viewport_info.xy_extent[1]) {
      MTLViewport vp;
      // A predicated-tiling pass offsets the viewport by a negative amount (Halo 3 uses 0/-160/-320/-480), and the
      // offsets are stored unsigned: read them back as signed or the origin becomes ~4.29e9 and the tile rasterises
      // somewhere no resolve ever reads, which repeats the scene once per band.
      vp.originX = double(int32_t(viewport_info.xy_offset[0]));
      vp.originY = double(int32_t(viewport_info.xy_offset[1]));
      vp.width = viewport_info.xy_extent[0];
      vp.height = viewport_info.xy_extent[1];
      vp.znear = viewport_info.z_min;
      vp.zfar = viewport_info.z_max;
      EncoderFixedState& fs = encoder_fixed_state_;
      const double vp_values[6] = {vp.originX, vp.originY, vp.width,
                                   vp.height,  vp.znear,   vp.zfar};
      if (std::getenv("XE_GPU_DELTA_CENSUS") != nullptr) {
        // What the draw actually rasterises with, next to the tile offset the guest asked for: the pair has to agree
        // once the offset stops living in the EDRAM base.
        auto wo = regs.Get<reg::PA_SC_WINDOW_OFFSET>();
        REXLOG_INFO(
            "DeltaCensus viewport_set draw={} origin=({},{}) extent=({},{}) "
            "guest_window=({},{}) in_base={}",
            trace_draw_index_, vp.originX, vp.originY, vp.width, vp.height,
            int32_t(wo.window_x_offset), int32_t(wo.window_y_offset),
            window_offset_tiles != 0 ? 1 : 0);
      }
      if (!state_dedupe || !fs.viewport_valid ||
          std::memcmp(fs.viewport, vp_values, sizeof(vp_values))) {
        es.SetViewport(vp);
        std::memcpy(fs.viewport, vp_values, sizeof(vp_values));
        fs.viewport_valid = true;
      }
    } else if (!memexport_draw && !vertex_shader->GetMemExportEMWritten()) {
      // A zero-extent viewport rasterizes nothing (D3D12 sets it as is).
      // Metal can't take a zero-size viewport, and skipping setViewport
      // would draw through the previous one, so the draw is a no-op, like
      // both faces culled. A vertex shader that exports to memory still
      // draws, so its exports run.
      RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect, "zero-viewport");
      return true;
    }
    // Apply Xenos polygon culling and front-face winding per normal draw.
    // Metal encoder state persists across draws, so non-polygons explicitly
    // restore no-cull/CCW rather than inheriting the preceding triangle state.
    // Both guest faces culled is a successful raster no-op. Memexport bypasses
    // raster state because its vertex-stage shared-memory stores must execute.
    if (!memexport_draw) {
      MetalDepthClipMode depth_clip_mode = GetMetalDepthClipMode(
          regs.Get<reg::PA_CL_CLIP_CNTL>());
      // force_depth_clamp (per-title config): host depth clamping in place of
      // near/far clipping while the guest keeps X/Y/W clipping, as the Vulkan
      // backend does. Rise of the Tomb Raider's colour-grading LUT slices are
      // drawn at Z/W = -9 and every backend that clips Z drops them.
      EncoderFixedState& fs = encoder_fixed_state_;
      const MTLDepthClipMode metal_clip =
          (depth_clip_mode == MetalDepthClipMode::kClamp ||
           ::rex::graphics::metal::GetMetalSettings().force_depth_clamp.Get())
              ? MTLDepthClipModeClamp
              : MTLDepthClipModeClip;
      if (!state_dedupe || fs.depth_clip != int32_t(metal_clip)) {
        es.SetDepthClipMode(metal_clip);
        fs.depth_clip = int32_t(metal_clip);
      }
      MetalCullFrontFaceState face_state = GetMetalCullFrontFaceState(
          regs.Get<reg::PA_SU_SC_MODE_CNTL>(), primitive_polygonal);
      if (face_state.culls_all()) {
        return true;
      }
      MTLCullMode cull_mode = MTLCullModeNone;
      if (face_state.cull_mode == MetalCullMode::kFront) {
        cull_mode = MTLCullModeFront;
      } else if (face_state.cull_mode == MetalCullMode::kBack) {
        cull_mode = MTLCullModeBack;
      }
      // Diagnostic (Sonic black-sky task 3.4): XE_METAL_NO_CULL=1 forces
      // MTLCullModeNone for every draw, to test whether missing coverage
      // is host face-culling of well-formed guest triangles.
      static const bool s_no_cull = std::getenv("XE_METAL_NO_CULL") != nullptr;
      if (s_no_cull) {
        cull_mode = MTLCullModeNone;
      }
      if (!state_dedupe || fs.cull != int32_t(cull_mode)) {
        es.SetCullMode(cull_mode);
        fs.cull = int32_t(cull_mode);
      }
      const MTLWinding winding = face_state.front_face_clockwise
                                     ? MTLWindingClockwise
                                     : MTLWindingCounterClockwise;
      if (!state_dedupe || fs.winding != int32_t(winding)) {
        es.SetFrontFacingWinding(winding);
        fs.winding = int32_t(winding);
      }

      // Apply a complete fill/depth-bias value every draw so state cannot leak
      // across guest transitions or newly opened render encoders. The slope
      // scales with the larger draw resolution scale axis, as on D3D12.
      float polygon_offset_scale = 0.0f;
      float polygon_offset = 0.0f;
      ::rex::gpu::draw_state::GetPreferredFacePolygonOffset(
          regs, primitive_polygonal, polygon_offset_scale, polygon_offset);
      MetalFillDepthBiasState fill_bias = GetMetalFillDepthBiasState(
          regs.Get<reg::PA_SU_SC_MODE_CNTL>(), primitive_polygonal,
          regs.Get<reg::RB_DEPTH_INFO>().depth_format, polygon_offset_scale,
          polygon_offset,
          std::max(draw_resolution_scale_x_, draw_resolution_scale_y_));
      const MTLTriangleFillMode fill_mode =
          fill_bias.triangle_fill_mode == MetalTriangleFillMode::kLines
              ? MTLTriangleFillModeLines
              : MTLTriangleFillModeFill;
      if (!state_dedupe || fs.fill != int32_t(fill_mode)) {
        es.SetTriangleFillMode(fill_mode);
        fs.fill = int32_t(fill_mode);
      }
      const float depth_bias[2] = {fill_bias.depth_bias_constant,
                                   fill_bias.depth_bias_slope};
      if (!state_dedupe || !fs.depth_bias_valid ||
          std::memcmp(fs.depth_bias, depth_bias, sizeof(depth_bias))) {
        es.SetDepthBias(fill_bias.depth_bias_constant,
                        fill_bias.depth_bias_slope, 0.0f);
        std::memcpy(fs.depth_bias, depth_bias, sizeof(depth_bias));
        fs.depth_bias_valid = true;
      }
    }
    // Stage 17: apply the guest scissor on every normal raster draw. Shared
    // draw_util owns Xenos window/screen/offset/pitch semantics; the Metal-only
    // helper then intersects that result with every active attachment so the
    // MTLScissorRect is validation-safe without expanding guest coverage.
    // Memexport is intentionally excluded: its vertex-stage stores must execute
    // even though raster output is irrelevant.
    if (!memexport_draw) {
      uint32_t render_width = UINT32_MAX;
      uint32_t render_height = UINT32_MAX;
      bool have_render_extent = false;
      void* extent_key[5] = {};
      if (have_color) {
        for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
          extent_key[i] = render_target_cache_->current_color_texture(i, nullptr);
        }
      }
      if (depth_bound) {
        extent_key[4] = render_target_cache_->current_depth_texture();
      }
      EncoderFixedState& efs = encoder_fixed_state_;
      if (state_dedupe && efs.extent_valid &&
          !std::memcmp(efs.extent_key, extent_key, sizeof(extent_key))) {
        render_width = efs.extent_width;
        render_height = efs.extent_height;
        have_render_extent = true;
      } else {
        for (void* texture_ptr : extent_key) {
          if (!texture_ptr) {
            continue;
          }
          __unsafe_unretained id<MTLTexture> texture =
              (__bridge id<MTLTexture>)texture_ptr;
          render_width = std::min(render_width, uint32_t(texture.width));
          render_height = std::min(render_height, uint32_t(texture.height));
          have_render_extent = true;
        }
        if (have_render_extent) {
          std::memcpy(efs.extent_key, extent_key, sizeof(extent_key));
          efs.extent_width = render_width;
          efs.extent_height = render_height;
          efs.extent_valid = true;
        }
      }
      if (pixel_export_only) {
        // The scratch depth is the pass's whole render area.
        render_width = pixel_export_extent_[0];
        render_height = pixel_export_extent_[1];
        have_render_extent = true;
      }
      if (!have_render_extent) {
        RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                       "empty-render-extent");
        return true;
      }
      ::rex::gpu::draw_state::Scissor guest_scissor;
      ::rex::gpu::draw_state::GetScissor(regs, guest_scissor, true);
      // Scale the guest scissor by the same factor as the viewport: the draw
      // resolution scale, times the fold scale of an MSAA clear folded into
      // the 1x view (identity at 1x otherwise).
      guest_scissor.offset[0] *= msaa_fold_scale_x * draw_resolution_scale_x_;
      guest_scissor.extent[0] *= msaa_fold_scale_x * draw_resolution_scale_x_;
      guest_scissor.offset[1] *= msaa_fold_scale_y * draw_resolution_scale_y_;
      guest_scissor.extent[1] *= msaa_fold_scale_y * draw_resolution_scale_y_;
      MetalScissorRect metal_scissor = ClampScissorToRenderExtent(
          guest_scissor, render_width, render_height);
      if (metal_scissor.empty()) {
        // Empty guest coverage is a successful no-op, not a backend failure.
        return true;
      }
      MTLScissorRect scissor_rect{metal_scissor.x, metal_scissor.y,
                                  metal_scissor.width, metal_scissor.height};
      EncoderFixedState& fs = encoder_fixed_state_;
      const uint64_t scissor_values[4] = {
          uint64_t(scissor_rect.x), uint64_t(scissor_rect.y),
          uint64_t(scissor_rect.width), uint64_t(scissor_rect.height)};
      if (!state_dedupe || !fs.scissor_valid ||
          std::memcmp(fs.scissor, scissor_values, sizeof(scissor_values))) {
        es.SetScissorRect(scissor_rect);
        std::memcpy(fs.scissor, scissor_values, sizeof(scissor_values));
        fs.scissor_valid = true;
      }
      draw_host_y0 = uint32_t(metal_scissor.y);
      draw_host_y1 = uint32_t(metal_scissor.y + metal_scissor.height);
      draw_full_width = metal_scissor.x == 0 &&
                        uint32_t(metal_scissor.width) >= render_width;
    }
  draw_trace_milestone("before-rt-probe");
    // Diagnostic (XE_METAL_RT_PROBE=<draw>): the attachments this draw is
    // encoded against.
    // Accepts a single draw or an inclusive range "a-b".
    static const std::pair<int64_t, int64_t> s_rt_probe_range = [] {
      const char* v = std::getenv("XE_METAL_RT_PROBE");
      if (!v) return std::make_pair(int64_t(-1), int64_t(-1));
      char* end = nullptr;
      int64_t a = strtoll(v, &end, 10);
      int64_t b = (end && *end == '-') ? strtoll(end + 1, nullptr, 10) : a;
      return std::make_pair(a, b);
    }();
    const int64_t s_rt_probe = int64_t(trace_draw_index_) - 1;
    if (s_rt_probe_range.first >= 0 && s_rt_probe >= s_rt_probe_range.first &&
        s_rt_probe <= s_rt_probe_range.second) {
      __unsafe_unretained id<MTLTexture> dt =
          (__bridge id<MTLTexture>)render_target_cache_->current_depth_texture();
      REXLOG_WARN("MetalRTProbe draw={} depth_bound={} color={} depth_tex={:X} {}x{} "
             "samples={} fmt={} attachment_key={:016X} z=({},{}) zfunc={} "
             "zwrite={} extent=({},{})",
             s_rt_probe, depth_bound ? 1 : 0, have_color ? 1 : 0,
             uint64_t(uintptr_t((__bridge void*)dt)),
             dt ? uint32_t(dt.width) : 0, dt ? uint32_t(dt.height) : 0,
             dt ? uint32_t(dt.sampleCount) : 0,
             dt ? uint32_t(dt.pixelFormat) : 0,
             render_target_cache_->current_attachment_key(),
             viewport_info.z_min, viewport_info.z_max,
             uint32_t(norm_depth.zfunc), uint32_t(norm_depth.z_write_enable),
             viewport_info.xy_extent[0], viewport_info.xy_extent[1]);
    }
    // Diagnostic (scene depth stuck at clear): log each unique depth
    // configuration of depth-bound draws once — z range, func, write, target.
    if (depth_bound) {
      uint64_t zcfg = (uint64_t(norm_depth.value) << 32) ^
                      uint64_t(viewport_info.z_min * 1000) ^
                      (uint64_t(viewport_info.z_max * 1000) << 10) ^
                      (render_target_cache_->current_attachment_key() << 20);
      static std::unordered_set<uint64_t> s_seen_zcfg;
      static uint64_t s_last_zcfg = ~uint64_t(0);
      if (zcfg != s_last_zcfg &&
          (s_last_zcfg = zcfg, s_seen_zcfg.insert(zcfg).second) &&
          s_seen_zcfg.size() <= 24) {
        REXLOG_INFO(
            "MetalZCfg: z=({},{}) zfunc={} zwrite={} ext=({},{}) color={} "
            "clear={:08X}",
            viewport_info.z_min, viewport_info.z_max,
            uint32_t(norm_depth.zfunc), uint32_t(norm_depth.z_write_enable),
            viewport_info.xy_extent[0], viewport_info.xy_extent[1], have_color,
            regs[XE_GPU_REG_RB_DEPTH_CLEAR]);
      }
    }
    // Bring-up diagnostic: log the transform of the first few draws of the
    // session (any primitive type) to catch off-screen / degenerate output.
    if (tri_log_count_ < 12) {
      ++tri_log_count_;
      REXLOG_INFO(
          "MetalCommandProcessor: DRAW {} prim={} idx={} clipdis={} imask={:X} "
          "pgen={} ext=({},{}) z=({},{}) ndc_s=({},{},{}) ndc_o=({},{},{}) "
          "flags={:X} ps_xlat={} depth={}",
          tri_log_count_, uint32_t(prim_type), index_buffer_info != nullptr,
          uint32_t(regs.Get<reg::PA_CL_CLIP_CNTL>().clip_disable),
          interpolator_mask, ps_param_gen_pos, viewport_info.xy_extent[0],
          viewport_info.xy_extent[1], viewport_info.z_min, viewport_info.z_max,
          viewport_info.ndc_scale[0], viewport_info.ndc_scale[1],
          viewport_info.ndc_scale[2], viewport_info.ndc_offset[0],
          viewport_info.ndc_offset[1], viewport_info.ndc_offset[2],
          system_constants.flags, ps_translation != nullptr, depth_bound);
    }
  }
  if (!ArenaAllocate(sizeof(system_constants), 256, &system_alloc)) {
    RecordDrawSkip(MetalDrawSkipReason::kResourceFailure, "sysconst-alloc");
    return true;
  }
  std::memcpy(system_alloc.cpu_ptr, &system_constants, sizeof(system_constants));

  // Float constants, packed per the shader's float_bitmap (b1). Vertex + pixel.
  // Diagnostic (XE_METAL_FORCE_FLOAT=<v|p><index>:<x>,<y>,<z>,<w>): pin one
  // guest float constant of the vertex (v) or pixel (p) bank for every draw
  // (interpolant/constant flow attribution, e.g. Halo 3 light-volume o4).
  struct ForceFloat {
    bool set = false;
    bool pixel = false;
    uint32_t index = 0;
    float value[4] = {};
  };
  static const ForceFloat s_force_float = [] {
    ForceFloat f;
    const char* v = std::getenv("XE_METAL_FORCE_FLOAT");
    if (v && (v[0] == 'v' || v[0] == 'p')) {
      f.pixel = v[0] == 'p';
      if (std::sscanf(v + 1, "%u:%f,%f,%f,%f", &f.index, &f.value[0],
                      &f.value[1], &f.value[2], &f.value[3]) == 5 &&
          f.index < 256) {
        f.set = true;
      }
    }
    return f;
  }();
  auto marshal_floats = [&](const ::rex::gpu::Shader::ConstantRegisterMap& map, uint32_t reg_base,
                            MetalUploadAllocation* out) -> bool {
    uint32_t count = GetMetalPackedFloatConstantCount(map);
    uint32_t bytes = sizeof(float) * 4 * std::max(count, 1u);
    if (!ArenaAllocate(bytes, 256, out)) {
      return false;
    }
    const bool force_here =
        s_force_float.set &&
        reg_base == (s_force_float.pixel ? XE_GPU_REG_SHADER_CONSTANT_256_X
                                         : XE_GPU_REG_SHADER_CONSTANT_000_X);
    uint32_t saved[4] = {};
    uint32_t* forced_words = nullptr;
    if (force_here) {
      forced_words = const_cast<uint32_t*>(
          &regs.values[reg_base + s_force_float.index * 4]);
      std::memcpy(saved, forced_words, sizeof(saved));
      std::memcpy(forced_words, s_force_float.value, sizeof(saved));
    }
    bool packed = PackMetalFloatConstants(regs, map, reg_base, out->cpu_ptr, bytes);
    if (forced_words) {
      std::memcpy(forced_words, saved, sizeof(saved));
    }
    return packed;
  };
  MetalUploadAllocation float_vertex_alloc{};
  if (!marshal_floats(vs_map, XE_GPU_REG_SHADER_CONSTANT_000_X,
                      &float_vertex_alloc)) {
    RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                   "float-consts-vs-alloc");
    return true;
  }
  // Forensics (with XE_METAL_DUMP_PS): log the packed VS b1 upload once —
  // bitmap words + the packed values for the HIGH constants (bitmap word 3,
  // c192-255: the terrain lighting bank) + direct register reads to compare.
  if (const char* dump_ps2 = s_dump_ps_env) {
    if (pixel_shader &&
        pixel_shader->GetUcodeDataHash() == strtoull(dump_ps2, nullptr, 16)) {
      static bool s_logged_b1 = false;
      if (!s_logged_b1) {
        s_logged_b1 = true;
        REXLOG_INFO("MetalB1: vs bitmap {:016X} {:016X} {:016X} {:016X}",
               vs_map.float_bitmap[0], vs_map.float_bitmap[1],
               vs_map.float_bitmap[2], vs_map.float_bitmap[3]);
        const float* packed = static_cast<const float*>(
            static_cast<const void*>(float_vertex_alloc.cpu_ptr));
        uint32_t packed_idx = 0;
        for (uint32_t i = 0; i < 4; ++i) {
          uint64_t entry = vs_map.float_bitmap[i];
          uint32_t index;
          while (rex::bit_scan_forward(entry, &index)) {
            entry = ((entry) & ((entry) - 1));
            uint32_t creg = i * 64 + index;
            if (creg >= 224 || creg < 12) {
              const float* direct = reinterpret_cast<const float*>(
                  &regs[XE_GPU_REG_SHADER_CONSTANT_000_X + (i << 8) +
                        (index << 2)]);
              REXLOG_INFO(
                  "MetalB1: c{} packed[{}]=({}, {}, {}, {}) direct=({}, {}, "
                  "{}, {})",
                  creg, packed_idx, packed[packed_idx * 4],
                  packed[packed_idx * 4 + 1], packed[packed_idx * 4 + 2],
                  packed[packed_idx * 4 + 3], direct[0], direct[1], direct[2],
                  direct[3]);
            }
            ++packed_idx;
          }
        }
      }
    }
  }
  MetalUploadAllocation float_pixel_alloc{};
  if (pixel_shader) {
    if (!marshal_floats(pixel_shader->GetConstantRegisterMap(),
                        XE_GPU_REG_SHADER_CONSTANT_256_X, &float_pixel_alloc)) {
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                     "float-consts-ps-alloc");
      return true;
    }
    // Exposure telemetry (XE_METAL_EXPO_TRACE=<ps hash hex>): capture the
    // tonemap shader's first float constants — the exposure value the game
    // computed FROM our luminance writebacks and fed back into rendering.
    static const uint64_t s_expo_ps_hash = [] {
      const char* v = std::getenv("XE_METAL_EXPO_TRACE");
      return v ? strtoull(v, nullptr, 16) : 0ull;
    }();
    if (s_expo_ps_hash && float_pixel_alloc.cpu_ptr &&
        pixel_shader->GetUcodeDataHash() == s_expo_ps_hash) {
      std::memcpy(expo_tonemap_c0_, float_pixel_alloc.cpu_ptr,
                  sizeof(expo_tonemap_c0_));
      expo_tonemap_seen_ = true;
      // Also log the full PACKED float-constant buffer once (the c255-class
      // weight forensics: is the last packed register marshaled right?).
      static bool s_packed_logged = false;
      if (!s_packed_logged) {
        s_packed_logged = true;
        const auto& map = pixel_shader->GetConstantRegisterMap();
        uint32_t packed = 0;
        for (uint32_t i = 0; i < 4; ++i) {
          packed += ::rex::BitCount(map.float_bitmap[i]);
        }
        const float* fl = static_cast<const float*>(float_pixel_alloc.cpu_ptr);
        std::string line;
        for (uint32_t i = 0; i < packed; ++i) {
          line += fmt::format(" [{}]=({} {} {} {})", i, fl[i * 4], fl[i * 4 + 1],
                              fl[i * 4 + 2], fl[i * 4 + 3]);
        }
        REXLOG_WARN("MetalPackedC ps={:016X} count={}:{}",
               pixel_shader->GetUcodeDataHash(), packed, line);
      }
    } else if (s_expo_ps_hash && float_pixel_alloc.cpu_ptr &&
               pixel_shader->GetUcodeDataHash() != s_expo_ps_hash) {
      // Tonemap-hash DISCOVERY: the real ucode hash is 64-bit; if the supplied
      // XE_METAL_EXPO_TRACE didn't match any shader, dump each unique pixel
      // shader's hash + first float constants once (capped). The tonemap is the
      // full-screen draw whose constants track exposure -- set EXPO_TRACE to its
      // {:016X} hash to capture expc. grep MetalExpoCandidate.
      static std::unordered_set<uint64_t> s_seen_expo_ps;
      if (s_seen_expo_ps.size() < 64 &&
          s_seen_expo_ps.insert(pixel_shader->GetUcodeDataHash()).second) {
        const float* fl = static_cast<const float*>(float_pixel_alloc.cpu_ptr);
        REXLOG_WARN(
            "MetalExpoCandidate ps={:016X} c0=({:.4f},{:.4f},{:.4f},{:.4f})",
            pixel_shader->GetUcodeDataHash(), fl[0], fl[1], fl[2], fl[3]);
      }
    }
  }

  // Bool/loop (b2), fetch (b3) — verbatim register blocks.
  auto marshal_block = [&](uint32_t reg_base, uint32_t bytes,
                           MetalUploadAllocation* out) -> bool {
    if (!ArenaAllocate(bytes, 256, out)) return false;
    std::memcpy(out->cpu_ptr, &regs[reg_base], bytes);
    // Diagnostic (XE_METAL_FORCE_BOOL=<index>:<0|1>): override one guest
    // boolean constant in the uploaded block, to attribute a defect to a
    // cexec/branch it gates.
    static const std::pair<int, int> s_force_bool = [] {
      const char* v = std::getenv("XE_METAL_FORCE_BOOL");
      int idx = -1, val = 0;
      if (v && std::sscanf(v, "%d:%d", &idx, &val) == 2) return std::make_pair(idx, val);
      return std::make_pair(-1, 0);
    }();
    if (s_force_bool.first >= 0 && s_force_bool.first < 256 &&
        reg_base == XE_GPU_REG_SHADER_CONSTANT_BOOL_000_031) {
      uint32_t* words = static_cast<uint32_t*>(out->cpu_ptr);
      uint32_t w = uint32_t(s_force_bool.first) >> 5;
      uint32_t bit = 1u << (uint32_t(s_force_bool.first) & 31u);
      words[w] = s_force_bool.second ? (words[w] | bit) : (words[w] & ~bit);
    }
    return true;
  };
  MetalUploadAllocation bool_loop_alloc{};
  MetalUploadAllocation fetch_alloc{};
  if (!marshal_block(XE_GPU_REG_SHADER_CONSTANT_BOOL_000_031, kMetalBoolLoopConstantsSize,
                     &bool_loop_alloc) ||
      !marshal_block(XE_GPU_REG_SHADER_CONSTANT_FETCH_00_0, kMetalFetchConstantsSize,
                     &fetch_alloc)) {
    RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                   "boolloop-fetch-alloc");
    return true;
  }
  draw_trace_milestone("after-marshal");
  // Vertex-fetch renames: point this draw's renamed fetch constants at the
  // arena copy (this draw's marshalled block only; the register file is
  // untouched).
  for (const DrawVfetchRename& r : draw_vfetch_renames_) {
    uint32_t* words = static_cast<uint32_t*>(fetch_alloc.cpu_ptr);
    const uint32_t index = r.fetch_constant * 2u;
    if (index + 1 >= kMetalFetchConstantsSize / sizeof(uint32_t)) {
      continue;
    }
    xenos::VertexFetch vf;
    std::memcpy(&vf, &words[index], sizeof(vf));
    const uint32_t fetch_base = vf.address << 2;
    if (fetch_base < r.guest_start || fetch_base >= r.guest_start + r.length) {
      continue;
    }
    vf.address = (r.buffer_offset + (fetch_base - r.guest_start)) >> 2;
    std::memcpy(&words[index], &vf, sizeof(vf));
  }

  // Descriptor indices (b4): for each texture binding, resolve its guest fetch
  // constant to a bindless view-heap slot (real texture, or 0=null/gray if the
  // format isn't supported yet); for each sampler binding, a sampler-heap slot
  // built from the binding's filters (fetch-constant filters where the shader
  // says kUseFetchConst) + the fetch constant's clamp modes. Texture and
  // sampler bindings share one bindless index space (disjoint indices).
  texture_cache_->ResetActive();
  texture_cache_->lineage_draw_ = trace_draw_index_;  // lineage-probe clock
  uint32_t marshal_bytes = 0;
  uint32_t marshal_stage = 0;
  auto marshal_desc_indices = [&](MetalShader* shader,
                                  MetalUploadAllocation* out) -> bool {
    // The cbuffer must cover every FLAT INDEX the translated shader reads:
    // [0, max bindless_descriptor_index]. The translator's index space can be
    // SPARSE (JC2's exposure shader assigns 1..6 with no 0: 4 textures + 2
    // samplers but max index 6), so sizing by list-count under-allocates and
    // the shader reads adjacent arena bytes as a descriptor-heap index — a
    // wild texture pointer and a GPU page fault (the live JC2
    // lost-command-buffer storm). Unassigned gaps read 0 = the null
    // texture/sampler slot, which is always valid.
    MetalDescriptorIndexPlan plan;
    if (shader) {
      const auto& texture_bindings = shader->GetTextureBindingsAfterTranslation();
      const auto& sampler_bindings = shader->GetSamplerBindingsAfterTranslation();
      DescriptorPlanMemo& plan_memo =
          descriptor_plan_memo_[shader->GetType() == xenos::ShaderType::kPixel];
      static const bool s_plan_memo = [] {
        const char* v = std::getenv("XE_METAL_DESCRIPTOR_PLAN_MEMO");
        return !(v && v[0] == '0' && !v[1]);
      }();
      if (s_plan_memo && plan_memo.shader == shader &&
          plan_memo.textures == texture_bindings.data() &&
          plan_memo.texture_count == texture_bindings.size() &&
          plan_memo.samplers == sampler_bindings.data() &&
          plan_memo.sampler_count == sampler_bindings.size()) {
        plan.count = plan_memo.plan_count;
        plan.valid = plan_memo.plan_valid;
      } else {
        plan = GetMetalDescriptorIndexPlan(texture_bindings, sampler_bindings);
        plan_memo.shader = shader;
        plan_memo.textures = texture_bindings.data();
        plan_memo.texture_count = texture_bindings.size();
        plan_memo.samplers = sampler_bindings.data();
        plan_memo.sampler_count = sampler_bindings.size();
        plan_memo.plan_count = plan.count;
        plan_memo.plan_valid = plan.valid;
      }
      if (!plan.valid) {
        REXLOG_WARN("MetalCommandProcessor: skipping draw with invalid {} descriptor "
               "index layout",
               shader->GetType() == xenos::ShaderType::kPixel ? "pixel" : "vertex");
        return false;
      }
    }
    const uint32_t count = plan.count;
    marshal_bytes = count * uint32_t(sizeof(uint32_t));
    if (!ArenaAllocate(count * sizeof(uint32_t), 256, out)) {
      return false;
    }
    // Built in cached memory and copied out once: the arena is
    // write-combined, so reading it back (the binding memo stores these) is
    // uncached -- that readback alone was 11% of GTA IV's command processor.
    std::vector<uint32_t>& scratch = bind_index_scratch_[marshal_stage];
    scratch.resize(count);
    uint32_t* indices = scratch.data();
    if (!InitializeMetalDescriptorIndices(plan, indices, count * sizeof(uint32_t))) {
      return false;
    }
    if (shader) {
      // XE_METAL_TEX_PROBE=<draw>: log every texture binding's fetch fields +
      // resolved bindless slot at that trace draw (slot 0 = null texture ->
      // the shader samples zero; the light-draw zero-output suspect).
      // XE_METAL_TEX_PROBE=A-B probes every draw in that inclusive range.
      static const std::pair<int64_t, int64_t> s_tex_probe_range = [] {
        const char* v = std::getenv("XE_METAL_TEX_PROBE");
        if (!v) {
          return std::pair<int64_t, int64_t>{-1, -1};
        }
        char* end = nullptr;
        int64_t a = strtoll(v, &end, 10);
        int64_t b = (end && *end == '-') ? strtoll(end + 1, nullptr, 10) : a;
        return std::pair<int64_t, int64_t>{a, b};
      }();
      const int64_t probe_draw = int64_t(trace_draw_index_) - 1;
      bool probe = s_tex_probe_range.first >= 0 &&
                   probe_draw >= s_tex_probe_range.first &&
                   probe_draw <= s_tex_probe_range.second;
      for (const auto& binding : shader->GetTextureBindingsAfterTranslation()) {
        if (binding.bindless_descriptor_index < count) {
          auto fetch = regs.GetTextureFetch(binding.fetch_constant);
          // C1T-R serve: indices the prepass prepared come from the shared
          // subclass; anything unserved (prep failure, invalidated between
          // prep and serve, faulted load) falls to the legacy path
          // unchanged.
          uint32_t routed_slot = 0;
          static const bool s_serve_signed = [] {
            const char* v = std::getenv("XE_METAL_TEX_ROUTE_SIGNED");
            return !(v && v[0] == '0' && !v[1]);
          }();
          // A signed binding may share a mask bit with its unsigned twin;
          // the corridor test at serve keeps ordinary signed content on the
          // byte-exact legacy path (see FetchOverlapsPendingGpuCurrent).
          bool serve_corridor_required = false;
          SharedRouteEligible(fetch, binding.is_signed, fetch_width_serve(fetch),
                              fetch_height_serve(fetch),
                              fetch_pitch_serve(fetch),
                              &serve_corridor_required);
          // Draw resolution scaling: the route mask is per fetch constant, so
          // a snapshot-served binding (bridge, exact or scaled cover) can share
          // a bit with a RAM-content twin (its signed variant). At 1x the two
          // hold the same content; at scale only the snapshot is scaled, so it
          // is served from the snapshot, GPU-ordered, never from the shared
          // cache's 1x RAM load.
          bool snapshot_binding_at_scale = false;
          if ((draw_resolution_scale_x_ > 1 || draw_resolution_scale_y_ > 1) &&
              texture_cache_) {
            ResolvedFetchService binding_service =
                texture_cache_->ClassifyFetchService(fetch, binding.is_signed);
            snapshot_binding_at_scale =
                binding_service == ResolvedFetchService::kBridgeSnapshot ||
                binding_service == ResolvedFetchService::kExactCoverSnapshot ||
                binding_service == ResolvedFetchService::kScaledCoverSnapshot;
          }
          const bool route_masked =
              shared_texture_cache_ && !snapshot_binding_at_scale &&
              (!binding.is_signed ||
               (s_serve_signed && (!serve_corridor_required ||
                                   FetchOverlapsPendingGpuCurrent(fetch)))) &&
              (draw_shared_route_mask_ & (1u << binding.fetch_constant));
          if (route_masked) {
            routed_slot = shared_texture_cache_->GetServedSlot(
                binding.fetch_constant, binding.is_signed);
          }
          if (route_masked && !routed_slot && draw_gpu_ordering_active_) {
            // Ordering elided this draw's consumer wait on the strength of
            // buffer serving; a legacy fallback here would read unconverged
            // RAM. Fail closed, counted.
            static uint32_t s_fallback_logs = 0;
            if (s_fallback_logs++ < 32) {
              REXLOG_WARN(
                  "MetalSharedTex ORDERING-FALLBACK fc={} fmt={} base={:08X} "
                  "{}x{} signed={} draw={} verify_sub={} state: {}",
                  binding.fetch_constant, uint32_t(fetch.format),
                  fetch.base_address << 12, fetch.size_2d.width + 1,
                  fetch.size_2d.height + 1, binding.is_signed ? 1 : 0,
                  uint32_t(trace_draw_index_), draw_route_verify_submission_,
                  shared_texture_cache_->DescribeServeState(
                      binding.fetch_constant, binding.is_signed));
            }
            RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                           "ordering-route-fallback");
            return false;
          }
          uint32_t texture_slot = routed_slot;
          if (probe && routed_slot) {
            REXLOG_INFO("MetalTexProbe draw={} routed slot fc={} -> {}", probe_draw,
                   binding.fetch_constant, routed_slot);
          }
          if (!texture_slot) {
            // A failed shared-cache candidate may still have a correct legacy
            // fallback. Only propagate failure if that fallback also can't
            // create the required object or heap slot.
            texture_cache_->ClearBindingAllocationFailure();
            texture_slot = texture_cache_->GetTextureSlot(fetch, binding.is_signed);
            if (probe) {
              REXLOG_INFO("MetalTexProbe draw={} legacy GetTextureSlot fc={} signed={} -> {}",
                     probe_draw, binding.fetch_constant, binding.is_signed,
                     texture_slot);
            }
            if (texture_cache_->binding_allocation_failed()) {
              REXLOG_WARN("MetalCommandProcessor: skipping draw after texture "
                     "binding allocation failure");
              return false;
            }
          }
          // XE_METAL_LINEAGE2=<base hex>: a second watched base for the BIND
          // log only (a ping-pong pair's other half).
          static const uint32_t s_lineage2 = [] {
            const char* v = std::getenv("XE_METAL_LINEAGE2");
            return v ? uint32_t(strtoul(v, nullptr, 16)) : 0u;
          }();
          if ((xe_lineage_base() &&
               (fetch.base_address << 12) == xe_lineage_base()) ||
              (s_lineage2 && (fetch.base_address << 12) == s_lineage2)) {
            // The first two 32-bit words at the base in the shared buffer:
            // what a routed load of texel (0,0) reads (raw guest byte order).
            uint32_t buf_words[2] = {0, 0};
            if (shared_memory_) {
              id<MTLBuffer> lineage_buffer =
                  (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
              if (lineage_buffer && lineage_buffer.contents) {
                std::memcpy(buf_words,
                            static_cast<const uint8_t*>(
                                lineage_buffer.contents) +
                                (fetch.base_address << 12),
                            sizeof(buf_words));
              }
            }
            REXLOG_WARN(
                "MetalLineage BIND swap#{} draw={} base={:08X} fc={} {}x{} "
                "fmt={} signed={} routed={} slot={} svc={} buf={:08X},{:08X}",
                swap_count_, trace_draw_index_, fetch.base_address << 12,
                binding.fetch_constant, fetch.size_2d.width + 1,
                fetch.size_2d.height + 1, uint32_t(fetch.format),
                binding.is_signed, routed_slot != 0, texture_slot,
                texture_cache_ ? uint32_t(texture_cache_->ClassifyFetchService(
                                     fetch, binding.is_signed))
                               : 99u,
                buf_words[0], buf_words[1]);
          }
          indices[binding.bindless_descriptor_index] = texture_slot;
          if (MetalTextureCache::SlotAuditEnabled()) {
            audit_draw_slots_.push_back(texture_slot);
          }
          // The audit's ENCODED side: this is the slot the shader will index,
          // captured with the identity the descriptor holds right now. The
          // stage mask is the draw's own requirement, taken from the same
          // GetMetalBindingStageMask the residency declarations use.
          if (probe) {
            REXLOG_INFO(
                "MetalTexProbe draw={} {} fc={} descidx={} -> slot={} "
                "type={} fmt={} base={:08X} size={}x{} endian={} tiled={} "
                "stacked={} packedmips={} miplevels={}-{} mipaddr={:08X} "
                "lodbias={} filters=mag{}/min{}/mip{} aniso={} clamp=({},{},{}) "
                "swz={:03X} raw={:08X},{:08X},{:08X},{:08X},{:08X},{:08X}",
                probe_draw, shader->GetType() == xenos::ShaderType::kPixel ? "PS" : "VS",
                binding.fetch_constant, binding.bindless_descriptor_index,
                indices[binding.bindless_descriptor_index],
                uint32_t(fetch.dimension), uint32_t(fetch.format),
                fetch.base_address << 12, fetch.size_2d.width + 1,
                fetch.size_2d.height + 1, uint32_t(fetch.endianness),
                uint32_t(fetch.tiled), uint32_t(fetch.stacked),
                uint32_t(fetch.packed_mips), uint32_t(fetch.mip_min_level),
                uint32_t(fetch.mip_max_level), fetch.mip_address << 12,
                int32_t(fetch.lod_bias), uint32_t(fetch.mag_filter),
                uint32_t(fetch.min_filter), uint32_t(fetch.mip_filter),
                uint32_t(fetch.aniso_filter), uint32_t(fetch.clamp_x),
                uint32_t(fetch.clamp_y), uint32_t(fetch.clamp_z),
                uint32_t(fetch.swizzle), fetch.dword_0, fetch.dword_1,
                fetch.dword_2, fetch.dword_3, fetch.dword_4, fetch.dword_5);
          }
        }
      }
      for (const auto& sb : shader->GetSamplerBindingsAfterTranslation()) {
        if (sb.bindless_descriptor_index >= count) {
          continue;
        }
        auto f = regs.GetTextureFetch(sb.fetch_constant);
        {
          // Upstream-delta census (XE_GPU_DELTA_CENSUS=1): fetch constants
          // carrying a nonzero per-axis gradient exponent bias, which the
          // local DXBC path compiles out (#if 0) and Canary 0f2980de4 applies.
          static const bool s_delta_census =
              std::getenv("XE_GPU_DELTA_CENSUS") != nullptr;
          static const bool s_delta_selftest =
              s_delta_census &&
              std::strcmp(std::getenv("XE_GPU_DELTA_CENSUS"), "selftest") == 0;
          static uint32_t s_delta_census_lines = 0;
          // Same probe family: force_bc_w_to_max (border alpha forced to 1)
          // on a fetch whose normalized clamp modes use the border — the
          // D3D12/Vulkan sampler contract applies it, the Metal key omits it.
          if (s_delta_census && s_delta_census_lines < 20000) {
            xenos::ClampMode bcx, bcy, bcz;
            ::rex::xenos::GetClampModesForDimension(f, bcx, bcy, bcz);
            bool bc_border = xenos::ClampModeUsesBorder(bcx) ||
                             xenos::ClampModeUsesBorder(bcy) ||
                             xenos::ClampModeUsesBorder(bcz);
            if (s_delta_selftest || (f.force_bc_w_to_max && bc_border)) {
              ++s_delta_census_lines;
              REXLOG_INFO(
                  "DeltaCensus bc_w_max draw={} fc={} force={} border_used={} "
                  "border_color={} fmt={} shader={:016X}",
                  uint32_t(trace_draw_index_), sb.fetch_constant,
                  uint32_t(f.force_bc_w_to_max), bc_border ? 1 : 0,
                  uint32_t(f.border_color), uint32_t(f.format),
                  shader->GetUcodeDataHash());
            }
          }
          if (s_delta_census &&
              (s_delta_selftest || f.grad_exp_adjust_h != 0 ||
               f.grad_exp_adjust_v != 0) &&
              s_delta_census_lines++ < 20000) {
            REXLOG_INFO(
                "DeltaCensus grad_bias draw={} fc={} h={} v={} lod_bias={} "
                "fmt={} {}x{} base={:08X} shader={:016X}",
                trace_draw_index_, sb.fetch_constant,
                int32_t(f.grad_exp_adjust_h), int32_t(f.grad_exp_adjust_v),
                int32_t(f.lod_bias), uint32_t(f.format), f.size_2d.width + 1,
                f.size_2d.height + 1, f.base_address << 12,
                shader->GetUcodeDataHash());
          }
        }
        auto resolve_filter = [](xenos::TextureFilter binding_filter,
                                 uint32_t fetch_filter) {
          return binding_filter == xenos::TextureFilter::kUseFetchConst
                     ? fetch_filter
                     : uint32_t(binding_filter);
        };
        uint32_t mag = resolve_filter(sb.mag_filter, uint32_t(f.mag_filter));
        uint32_t mn = resolve_filter(sb.min_filter, uint32_t(f.min_filter));
        uint32_t mip = resolve_filter(sb.mip_filter, uint32_t(f.mip_filter));
        uint32_t an = sb.aniso_filter == xenos::AnisoFilter::kUseFetchConst
                          ? uint32_t(f.aniso_filter)
                          : uint32_t(sb.aniso_filter);
        {
          // Upstream-delta census (2026-10-09): point-sampled bindings, which
          // Canary c3cd8617b snaps to guest texel values and centers. narrow=1
          // marks a fixed format with a 4-7 bit unsigned component read as
          // normalized, the class whose returned values change.
          static const bool s_point_census =
              std::getenv("XE_GPU_DELTA_CENSUS") != nullptr;
          if (s_point_census &&
              mag == uint32_t(xenos::TextureFilter::kPoint) &&
              mn == uint32_t(xenos::TextureFilter::kPoint) &&
              (mip == uint32_t(xenos::TextureFilter::kPoint) ||
               mip == uint32_t(xenos::TextureFilter::kBaseMap)) &&
              an == uint32_t(xenos::AnisoFilter::kDisabled)) {
            const ::rex::xenos::FormatInfo* point_format = ::rex::xenos::FormatInfo::Get(f.format);
            uint32_t narrow = 0;
            if (point_format && texture_integer_scale::ComponentBits(f.format, 3) != 0 && !f.num_format) {
              for (uint32_t c = 0; c < 4; ++c) {
                uint32_t bits = texture_integer_scale::ComponentBits(f.format, c);
                xenos::TextureSign sign =
                    c == 0 ? f.sign_x : c == 1 ? f.sign_y
                                      : c == 2 ? f.sign_z : f.sign_w;
                if (bits >= 4 && bits <= 7 &&
                    sign == xenos::TextureSign::kUnsigned) {
                  narrow = 1;
                }
              }
            }
            uint64_t n = DeltaCensusKeyedCount(
                4, uint64_t(f.format) | (uint64_t(f.dimension) << 8) |
                       (uint64_t(f.num_format) << 12) |
                       (uint64_t(narrow) << 13));
            if (DeltaCensusLogCount(n)) {
              REXLOG_INFO(
                  "DeltaCensus point_snap draw={} fc={} fmt={} dim={} "
                  "num_format={} narrow={} {}x{} count={}",
                  uint32_t(trace_draw_index_), sb.fetch_constant, uint32_t(f.format),
                  uint32_t(f.dimension), uint32_t(f.num_format), narrow,
                  f.size_2d.width + 1, f.size_2d.height + 1, n);
            }
          }
        }
        {
          // Upstream-delta census (2026-10-12): unsigned-biased components of
          // fixed formats fetched with a normalized num_format. The translator
          // decodes them as 2u - 1; Canary c3cd8617b decodes offset binary,
          // (n - 2^(w-1)) / (2^(w-1) - 1), so an 8-bit 128 returns 0. bits is
          // the widest biased component.
          static const bool s_biased_census =
              std::getenv("XE_GPU_DELTA_CENSUS") != nullptr;
          const ::rex::xenos::FormatInfo* biased_format =
              s_biased_census ? ::rex::xenos::FormatInfo::Get(f.format) : nullptr;
          if (texture_integer_scale::ComponentBits(f.format, 3) != 0 && !f.num_format) {
            uint32_t biased_bits = 0;
            for (uint32_t c = 0; c < 4; ++c) {
              xenos::TextureSign sign =
                  c == 0 ? f.sign_x : c == 1 ? f.sign_y
                                    : c == 2 ? f.sign_z : f.sign_w;
              if (sign == xenos::TextureSign::kUnsignedBiased) {
                biased_bits = std::max(biased_bits,
                                       texture_integer_scale::ComponentBits(f.format, c));
              }
            }
            if (biased_bits) {
              uint64_t n = DeltaCensusKeyedCount(
                  6, uint64_t(f.format) | (uint64_t(biased_bits) << 8));
              if (DeltaCensusLogCount(n)) {
                REXLOG_INFO(
                    "DeltaCensus biased_norm draw={} fc={} fmt={} bits={} "
                    "{}x{} count={}",
                    uint32_t(trace_draw_index_), sb.fetch_constant, uint32_t(f.format),
                    biased_bits, f.size_2d.width + 1, f.size_2d.height + 1,
                    n);
              }
            }
          }
        }
        // Sampler parameters follow the shared D3D12/Vulkan contract
        // (D3D12TextureCache::GetSamplerParameters / WriteSampler):
        //  - clamp modes normalized per dimension (unused axes and every cube
        //    axis are clamp-to-edge);
        //  - border color from the fetch only when a clamp uses the border;
        //  - LOD clamped to the normalized mip minimum; base-map pins the LOD
        //    to that level;
        //  - any anisotropy setting forces linear min/mag/mip and sets the
        //    max anisotropy.
        // The 2026-09-04 sampler census ranked what the previous raw key
        // dropped: JC2/Sonic/LEGO/RDR shadow maps are clamp-to-border with a
        // WHITE border (20k/9k bindings per frame; the default transparent
        // black border put everything outside the map in shadow), SF4/JC2/RDR
        // use anisotropy with point filters, RDR fetches with mip_min > 0.
        xenos::ClampMode ncx, ncy, ncz;
        ::rex::xenos::GetClampModesForDimension(f, ncx, ncy, ncz);
        uint32_t nmin_level = 0, nmax_level = 0;
        ::rex::xenos::GetSubresourcesFromFetchConstant(
            f, nullptr, nullptr, nullptr, nullptr, nullptr, &nmin_level,
            &nmax_level);
        const bool border_used = xenos::ClampModeUsesBorder(ncx) ||
                                 xenos::ClampModeUsesBorder(ncy) ||
                                 xenos::ClampModeUsesBorder(ncz);
        const uint32_t border = border_used ? uint32_t(f.border_color) : 0u;
        // force_bc_w_to_max: border alpha forced to 1 (shared contract); like
        // the colour it only matters when a clamp uses the border.
        const uint32_t force_bc_w =
            border_used ? uint32_t(f.force_bc_w_to_max) : 0u;
        const uint32_t base_map = mip == uint32_t(xenos::TextureFilter::kBaseMap)
                                      ? 1u
                                      : 0u;
        // XE_METAL_SAMPLER_LEGACY=1 is the exact rollback: raw clamp modes,
        // no border color, no LOD clamp, anisotropy without the linear
        // forcing (the pre-2026-09-04 sampler).
        static const bool s_sampler_legacy =
            std::getenv("XE_METAL_SAMPLER_LEGACY") != nullptr;
        uint64_t skey;
        if (s_sampler_legacy) {
          skey = (mag & 3) | ((mn & 3) << 2) | ((mip & 3) << 4) |
                 ((uint32_t(f.clamp_x) & 7) << 6) |
                 ((uint32_t(f.clamp_y) & 7) << 9) |
                 ((uint32_t(f.clamp_z) & 7) << 12) | ((an & 7) << 15) |
                 (uint64_t(1) << 25);
        } else {
          skey = (mag & 3) | ((mn & 3) << 2) | ((mip & 3) << 4) |
                 ((uint32_t(ncx) & 7) << 6) | ((uint32_t(ncy) & 7) << 9) |
                 ((uint32_t(ncz) & 7) << 12) | ((an & 7) << 15) |
                 (uint64_t(border & 3) << metal::kMetalSamplerKeyBorderShift) |
                 (uint64_t(nmin_level & 15) << 20) |
                 (uint64_t(base_map) << 24) |
                 (uint64_t(force_bc_w & 1)
                  << metal::kMetalSamplerKeyForceBcWShift) |
                 (metal::SharedRouteMinMipEnabled()
                      ? (uint64_t(nmax_level & 15) << 26)
                      : 0ull);
        }
        // Sampler-semantics census (XE_METAL_SAMPLER_CENSUS=1): every guest
        // sampler field, raw and as the shared D3D12/Vulkan contract
        // normalizes it, per unique combination, so the ledger's "sampler
        // semantics" gap row can be ranked by real engagement instead of
        // listed as a family. First sight logs the fields; ShutdownContext
        // logs the counts. Bounded, default off.
        static const bool s_sampler_census =
            std::getenv("XE_METAL_SAMPLER_CENSUS") != nullptr;
        if (s_sampler_census) {
          xenos::ClampMode ncx, ncy, ncz;
          ::rex::xenos::GetClampModesForDimension(f, ncx, ncy, ncz);
          uint32_t nmin = 0, nmax = 0;
          ::rex::xenos::GetSubresourcesFromFetchConstant(
              f, nullptr, nullptr, nullptr, nullptr, nullptr, &nmin, &nmax);
          uint64_t ckey =
              (uint64_t(skey) & 0x3FFFFu) | (uint64_t(f.dimension) << 18) |
              (uint64_t(f.border_color) << 20) |
              (uint64_t(uint32_t(f.lod_bias) & 0x3FF) << 22) |
              (uint64_t(f.tri_clamp) << 32) | (uint64_t(nmin) << 34) |
              (uint64_t(nmax) << 38) | (uint64_t(f.vol_mag_filter) << 42) |
              (uint64_t(f.vol_min_filter) << 43) |
              (uint64_t(uint32_t(ncx)) << 44) | (uint64_t(uint32_t(ncy)) << 47) |
              (uint64_t(uint32_t(ncz)) << 50);
          auto& count = sampler_census_[ckey];
          if (count++ == 0 && sampler_census_.size() <= 4096) {
            bool border_used = xenos::ClampModeUsesBorder(ncx) ||
                               xenos::ClampModeUsesBorder(ncy) ||
                               xenos::ClampModeUsesBorder(ncz);
            REXLOG_INFO(
                "MetalSamplerCensus new key={:016X} dim={} clamp=({},{},{}) "
                "norm=({},{},{}) border_used={} border_color={} force_bc_w={} "
                "lod_bias={} "
                "tri_clamp={} mag={} min={} mip={} aniso={} mip_range={}-{} "
                "vol=({},{}) shader_ovr=(mag={} min={} mip={} aniso={}) "
                "fmt={} {}x{} fc={} draw={}",
                ckey, uint32_t(f.dimension), uint32_t(f.clamp_x),
                uint32_t(f.clamp_y), uint32_t(f.clamp_z), uint32_t(ncx),
                uint32_t(ncy), uint32_t(ncz), border_used ? 1 : 0,
                uint32_t(f.border_color), uint32_t(f.force_bc_w_to_max),
                int32_t(f.lod_bias),
                uint32_t(f.tri_clamp), mag, mn, mip, an, nmin, nmax,
                uint32_t(f.vol_mag_filter), uint32_t(f.vol_min_filter),
                sb.mag_filter != xenos::TextureFilter::kUseFetchConst ? 1 : 0,
                sb.min_filter != xenos::TextureFilter::kUseFetchConst ? 1 : 0,
                sb.mip_filter != xenos::TextureFilter::kUseFetchConst ? 1 : 0,
                sb.aniso_filter != xenos::AnisoFilter::kUseFetchConst ? 1 : 0,
                uint32_t(f.format), f.size_2d.width + 1,
                f.size_2d.height + 1, sb.fetch_constant, trace_draw_index_);
          }
        }
        uint32_t sampler_slot;
        if (!GetOrCreateSamplerSlot(skey, &sampler_slot)) {
          REXLOG_WARN("MetalCommandProcessor: skipping draw after sampler binding "
                 "allocation failure");
          return false;
        }
        indices[sb.bindless_descriptor_index] = sampler_slot;
      }
    }
    if (count) {
      std::memcpy(out->cpu_ptr, indices, count * sizeof(uint32_t));
    }
    return true;
  };
  MetalUploadAllocation desc_idx_vertex_alloc{};
  MetalUploadAllocation desc_idx_pixel_alloc{};
  draw_trace_milestone("before-marshal");
  // Binding memo: a draw whose texture inputs repeat the previous draw's, with
  // nothing in either texture cache or the producer state changed since,
  // resolves every binding to the same slots, so the previous index arrays
  // and residency list are reused (~70% of Burnout's draws: command
  // processor 29-31 -> 27-28 ms/frame on the Mac Pro; Mafia II, GTA IV and
  // Apple neutral). The key holds the inputs and the state AFTER the
  // previous draw's own resolution. Verify mode found 0 mismatches in 16
  // titles (quick tier + Mafia II).
  // XE_METAL_BIND_MEMO=0 off, 2 = verify (resolve anyway and compare).
  static const uint32_t s_bind_memo = [] {
    const char* v = std::getenv("XE_METAL_BIND_MEMO");
    if (v) {
      return uint32_t(std::strtoul(v, nullptr, 10));
    }
    // The memo skips the per-binding diagnostics.
    if (std::getenv("XE_METAL_TEX_PROBE") || std::getenv("XE_GPU_DELTA_CENSUS")) {
      return 0u;
    }
    return 1u;
  }();
  const bool bind_memo_on = s_bind_memo && !xe_lineage_base() &&
                            !MetalTextureCache::SlotAuditEnabled();
  audit_draw_slots_.clear();
  // The key: fixed state compared as one block, plus "no fetch constant the
  // shaders read was written since the memo was stored" (WriteRegister marks
  // written slots in bind_memo_fetch_written_; storing clears it).
  auto build_bind_memo_key = [&](BindMemo::Key& key) {
    std::memset(&key, 0, sizeof(key));
    key.vertex_shader = vertex_shader;
    key.pixel_shader = pixel_shader;
    key.route_mask = draw_shared_route_mask_;
    key.flags = uint32_t(draw_gpu_ordering_active_) |
                (uint32_t(false) << 1);
    key.scale = draw_resolution_scale_x_ | (draw_resolution_scale_y_ << 16);
    key.pending_writebacks = uint32_t(pending_writebacks_.size());
    key.pending_memexports = uint32_t(pending_memexports_.size());
    key.submission = CurrentEncodingSubmission();
    key.binding_generation = texture_cache_->binding_generation();
    key.registry_epoch = texture_cache_->registry_epoch();
    key.serve_generation =
        shared_texture_cache_ ? shared_texture_cache_->serve_generation() : 0;
    key.authority_sequence = memory_authority_sequence_;
  };
  auto bind_memo_fetch_mask = [&]() {
    uint32_t mask = 0;
    for (MetalShader* shader : {vertex_shader, pixel_shader}) {
      if (!shader) {
        continue;
      }
      for (const auto& b : shader->GetTextureBindingsAfterTranslation()) {
        mask |= 1u << (b.fetch_constant & 31);
      }
      for (const auto& b : shader->GetSamplerBindingsAfterTranslation()) {
        mask |= 1u << (b.fetch_constant & 31);
      }
    }
    return mask;
  };
  BindMemo& memo = bind_memo_;
  bool memo_hit = false;
  if (bind_memo_on && memo.valid &&
      !(bind_memo_fetch_written_ & memo.fetch_mask) &&
      !texture_cache_->HasPendingInvalidations()) {
    BindMemo::Key key;
    build_bind_memo_key(key);
    memo_hit = !std::memcmp(&key, &memo.key, sizeof(key));
  }
  if (memo_hit && s_bind_memo == 1) {
    ++memo.hits;
    for (uint32_t i = 0; i < 2; ++i) {
      MetalUploadAllocation* out = i ? &desc_idx_pixel_alloc : &desc_idx_vertex_alloc;
      const std::vector<uint32_t>& indices = memo.indices[i];
      if (!ArenaAllocate(uint32_t(indices.size() * sizeof(uint32_t)), 256, out)) {
        RecordDrawSkip(MetalDrawSkipReason::kResourceFailure, "desc-index-alloc");
        return true;
      }
      std::memcpy(out->cpu_ptr, indices.data(), indices.size() * sizeof(uint32_t));
    }
    for (void* texture : memo.active) {
      texture_cache_->AddActiveTexture(texture);
    }
  } else {
    uint32_t desc_idx_bytes[2] = {};
    marshal_stage = 0;
    bool resolved = marshal_desc_indices(vertex_shader, &desc_idx_vertex_alloc);
    desc_idx_bytes[0] = marshal_bytes;
    marshal_stage = 1;
    resolved = resolved &&
               marshal_desc_indices(pixel_shader, &desc_idx_pixel_alloc);
    if (!resolved) {
      memo.valid = false;
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure, "desc-index-alloc");
      return true;
    }
    desc_idx_bytes[1] = marshal_bytes;
    if (bind_memo_on) {
      const auto& active = texture_cache_->active_textures();
      if (memo_hit) {
        // Verify mode: the memo would have served this draw.
        bool same = memo.active == active;
        for (uint32_t i = 0; i < 2 && same; ++i) {
          same = memo.indices[i].size() * sizeof(uint32_t) == desc_idx_bytes[i] &&
                 (!desc_idx_bytes[i] ||
                  !std::memcmp(memo.indices[i].data(),
                               bind_index_scratch_[i].data(), desc_idx_bytes[i]));
        }
        ++memo.verified;
        if (!same && memo.mismatches++ < 20) {
          REXLOG_WARN("MetalBindMemo MISMATCH swap#{} draw={} vs={:016X} ps={:016X}",
                 swap_count_, trace_draw_index_,
                 vertex_shader ? vertex_shader->GetUcodeDataHash() : 0,
                 pixel_shader ? pixel_shader->GetUcodeDataHash() : 0);
        }
      } else {
        ++memo.misses;
      }
      for (uint32_t i = 0; i < 2; ++i) {
        const uint32_t* p = bind_index_scratch_[i].data();
        memo.indices[i].assign(p, p + desc_idx_bytes[i] / sizeof(uint32_t));
      }
      memo.active.assign(active.begin(), active.end());
      // The state as this draw's resolution left it.
      build_bind_memo_key(memo.key);
      if (memo.key.vertex_shader != memo.mask_vertex_shader ||
          memo.key.pixel_shader != memo.mask_pixel_shader) {
        memo.mask_vertex_shader = vertex_shader;
        memo.mask_pixel_shader = pixel_shader;
        memo.fetch_mask = bind_memo_fetch_mask();
      }
      bind_memo_fetch_written_ = 0;
      memo.valid = true;
    }
  }

  // --- Build the top-level argument buffer from the root-layout authority. ---
  __unsafe_unretained id<MTLBuffer> view_heap = (__bridge id<MTLBuffer>)view_bindless_heap_;
  __unsafe_unretained id<MTLBuffer> sampler_heap = (__bridge id<MTLBuffer>)sampler_bindless_heap_;
  __unsafe_unretained id<MTLBuffer> system_view = (__bridge id<MTLBuffer>)system_view_tables_;
  __unsafe_unretained id<MTLBuffer> null_buffer = (__bridge id<MTLBuffer>)null_buffer_;
  // gpuAddress is an Objective-C call into the driver; these buffers are
  // long-lived, so their addresses are re-read only when a pointer changes.
  {
    void* const ptrs[4] = {view_bindless_heap_, sampler_bindless_heap_,
                           system_view_tables_, null_buffer_};
    if (std::memcmp(fixed_gpu_address_ptrs_, ptrs, sizeof(ptrs))) {
      std::memcpy(fixed_gpu_address_ptrs_, ptrs, sizeof(ptrs));
      fixed_gpu_addresses_[0] = [view_heap gpuAddress];
      fixed_gpu_addresses_[1] = [sampler_heap gpuAddress];
      fixed_gpu_addresses_[2] = [system_view gpuAddress];
      fixed_gpu_addresses_[3] = [null_buffer gpuAddress];
    }
  }
  uint64_t view_heap_gpu = fixed_gpu_addresses_[0];
  uint64_t sampler_heap_gpu = fixed_gpu_addresses_[1];
  uint64_t system_view_gpu = fixed_gpu_addresses_[2];
  uint64_t null_gpu = fixed_gpu_addresses_[3];

  MetalUploadAllocation ab_alloc{};
  if (!ArenaAllocate(kMetalBindingSlotCount * sizeof(uint64_t), 256, &ab_alloc)) {
    RecordDrawSkip(MetalDrawSkipReason::kResourceFailure, "argbuffer-alloc");
    return true;
  }

  // --- Host tessellation route: expand the patch stream (task 3.4). ---
  // Stages the guest control-point index / factor stream into host order with
  // the SAME staging primitive and stale-stream backstop as the mesh route,
  // runs the reference tessellator per patch, and writes the
  // XeTessellationVertex records + 32-bit triangle indices straight into
  // upload-arena transients. The records are exposed to the domain_as_vertex
  // vertex shader through a per-draw two-entry SRV space-0 table (entry 0 =
  // the shared-memory SRV, entry 1 = the records), so only routed draws
  // differ from the fixed system table (design D8).
  MetalUploadAllocation tess_host_records_alloc{};
  MetalUploadAllocation tess_host_indices_alloc{};
  MetalUploadAllocation tess_host_table_alloc{};
  uint32_t tess_host_index_count = 0;
  if (use_tessellation_emulation) {
    metal::MetalHostTessellationShape tess_shape;
    if (!metal::DescribeMetalHostTessellationShape(
            tess_pp.host_vertex_shader_type, tess_pp.tessellation_mode,
            &tess_shape)) {
      RecordDrawSkip(MetalDrawSkipReason::kTessellationUnsupportedShape,
                     "tess-host-shape");
      return true;
    }
    metal::MetalHostTessellationDrawInput tess_in{};
    tess_in.shape = tess_shape;
    tess_in.mode = tess_pp.tessellation_mode;
    tess_in.factor_range_min =
        regs.Get<float>(XE_GPU_REG_VGT_HOS_MIN_TESS_LEVEL) + 1.0f;
    tess_in.factor_range_max =
        regs.Get<float>(XE_GPU_REG_VGT_HOS_MAX_TESS_LEVEL) + 1.0f;
    {
      MetalSystemConstantGuestState tess_guest_state =
          GetMetalSystemConstantGuestState(regs);
      tess_in.index_offset = tess_guest_state.vertex_index_offset;
      tess_in.min_index = tess_guest_state.vertex_index_min;
      tess_in.max_index = tess_guest_state.vertex_index_max;
    }
    tess_in.stream = nullptr;
    tess_in.stream_32bit =
        tess_pp.host_index_format == xenos::IndexFormat::kInt32;
    tess_in.stream_word_count = tess_pp.host_draw_vertex_count;
    if (tess_pp.index_buffer_type ==
        ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kGuestDMA) {
      uint32_t index_size = tess_in.stream_32bit ? 4 : 2;
      uint32_t host_count = tess_pp.host_draw_vertex_count;
      uint32_t total = host_count * index_size;
      const void* guest_indices =
          TranslateGuest<const uint8_t*>(tess_pp.guest_index_base);
      if (!guest_indices) {
        RecordDrawSkip(MetalDrawSkipReason::kInvalidGuestState,
                       "tess-index-guest-null");
        return true;
      }
      // Fail-closed staleness backstop (identical to the mesh route's): a
      // pending memexport still owing these bytes to RAM means the barrier
      // did not converge them; skip rather than tessellate stale factors.
      {
        metal::MetalGuestStreamExtent staged_extent =
            metal::ComputeMetalIndexStreamExtent(
                tess_pp.guest_index_base, host_count, tess_in.stream_32bit);
        for (const PendingMemexport& pending : pending_memexports_) {
          if (!metal::MetalStreamReadWouldBeStale(staged_extent,
                                                  pending.base_address,
                                                  pending.size_bytes)) {
            continue;
          }
          REXLOG_ERROR(
              "MetalMemexportRasterStale draw={} tessellation factor stream "
              "{:08X}(+{}) still owed by pending memexport {:08X}(+{}); "
              "skipping rather than tessellating from stale RAM",
              trace_draw_index_, staged_extent.base, staged_extent.size,
              pending.base_address, pending.size_bytes);
          RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                         "memexport-raster-stale-factor-stream");
          return true;
        }
      }
      host_tessellation_stream_scratch_.resize((total + 3) / 4 + 1);
      SwapIndicesInto(host_tessellation_stream_scratch_.data(), guest_indices,
                      host_count, tess_pp.host_index_format,
                      tess_pp.host_shader_index_endian);
      tess_in.stream = host_tessellation_stream_scratch_.data();
      if (s_memexport_log) {
        REXLOG_WARN(
            "MetalMemexportJoin draw={} consumer stream={:08X}(+{}) "
            "raw_guest_hash={:016X}",
            trace_draw_index_, tess_pp.guest_index_base, total,
            metal::MetalMemexportJoinHash(guest_indices, total));
      }
    } else if (tess_pp.index_buffer_type ==
                   ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::
                       kHostConverted ||
               tess_pp.index_buffer_type ==
                   ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::
                       kHostBuiltinForAuto) {
      // Tessellated strip / fan converted to a triangle list (Canary
      // 3eab2b8b3): the control-point indices come from this frame's
      // host-converted pool (in the endianness the processor reports, swapped
      // per element exactly like the non-tessellated converted draw) or from
      // the built-in auto fan table (host order). Both are staged into the
      // same scratch the guest-DMA stream uses, so the host tessellator sees
      // one stream convention.
      uint32_t index_size = tess_in.stream_32bit ? 4 : 2;
      uint32_t host_count = tess_pp.host_draw_vertex_count;
      uint32_t total = host_count * index_size;
      host_tessellation_stream_scratch_.resize((total + 3) / 4 + 1);
      if (tess_pp.index_buffer_type ==
          ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kHostConverted) {
        const void* converted = primitive_processor_->GetConvertedIndexData(
            tess_pp.host_index_buffer_handle, total);
        if (!converted) {
          RecordDrawSkip(MetalDrawSkipReason::kInternalInvariant,
                         "tess-converted-range");
          return true;
        }
        SwapConvertedIndicesInto(host_tessellation_stream_scratch_.data(),
                                 converted, host_count,
                                 tess_pp.host_index_format,
                                 tess_pp.host_shader_index_endian);
      } else if (!primitive_processor_->CopyBuiltinIndexData(
                     tess_pp.host_index_buffer_handle, total,
                     host_tessellation_stream_scratch_.data())) {
        RecordDrawSkip(MetalDrawSkipReason::kInternalInvariant,
                       "tess-builtin-copy");
        return true;
      }
      tess_in.stream = host_tessellation_stream_scratch_.data();
    }
    if (!host_tessellator_) {
      host_tessellator_ = std::make_unique<HostTessellator>();
    }
    metal::MetalHostTessellationCounts tess_counts =
        metal::CountMetalHostTessellation(tess_in, *host_tessellator_);
    if (tess_counts.over_budget) {
      static uint32_t s_budget_logs = 0;
      if (s_budget_logs++ < 16) {
        REXLOG_WARN(
            "MetalHostTess draw={} over budget: patches={} vertices>{} "
            "(range=[{},{}]); skipping whole draw",
            trace_draw_index_, tess_counts.patch_count,
            metal::kMaxMetalHostTessellationVerticesPerDraw,
            tess_in.factor_range_min, tess_in.factor_range_max);
      }
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure, "tess-budget");
      return true;
    }
    if (!tess_counts.vertex_count || !tess_counts.index_count) {
      RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                     "tess-host-degenerate");
      return true;
    }
    if (!ArenaAllocate(
            tess_counts.vertex_count * metal::kXeTessellationVertexSizeBytes,
            16, &tess_host_records_alloc) ||
        !ArenaAllocate(tess_counts.index_count * sizeof(uint32_t),
                                 16, &tess_host_indices_alloc) ||
        !ArenaAllocate(2 * sizeof(IRDescriptorTableEntry), 256,
                                 &tess_host_table_alloc)) {
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                     "tess-record-alloc");
      return true;
    }
    metal::WriteMetalHostTessellation(
        tess_in, *host_tessellator_,
        static_cast<metal::XeTessellationVertex*>(
            tess_host_records_alloc.cpu_ptr),
        static_cast<uint32_t*>(tess_host_indices_alloc.cpu_ptr));
    tess_host_index_count = tess_counts.index_count;
    // UNCONDITIONAL log-once engagement proof (the live fault harness anchors
    // its post-engagement floor on this line for the host route, exactly as
    // it anchors on "built tessellation pipeline" for the mesh route).
    static bool s_host_tess_engaged_logged = false;
    if (!s_host_tess_engaged_logged) {
      s_host_tess_engaged_logged = true;
      REXLOG_INFO(
          "MetalHostTessellation: engaged (host route) first draw={} type={} "
          "mode={} patches={} vertices={}",
          trace_draw_index_, uint32_t(tess_pp.host_vertex_shader_type),
          uint32_t(tess_pp.tessellation_mode), tess_counts.patch_count,
          tess_counts.vertex_count);
    }
    auto* tess_table_entries =
        static_cast<IRDescriptorTableEntry*>(tess_host_table_alloc.cpu_ptr);
    std::memset(tess_table_entries, 0, 2 * sizeof(IRDescriptorTableEntry));
    __unsafe_unretained id<MTLBuffer> tess_shared_buffer =
        (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
    IRDescriptorTableSetBuffer(&tess_table_entries[0],
                               [tess_shared_buffer gpuAddress],
                               shared_memory_->gpu_visible_length());
    IRDescriptorTableSetBuffer(
        &tess_table_entries[1], tess_host_records_alloc.gpu_address,
        tess_counts.vertex_count * metal::kXeTessellationVertexSizeBytes);
    static const bool s_host_tess_log =
        std::getenv("XE_METAL_HOST_TESS_LOG") != nullptr;
    static uint32_t s_host_tess_logs = 0;
    if (s_host_tess_log && s_host_tess_logs++ < 256) {
      REXLOG_INFO(
          "MetalHostTess draw={} type={} mode={} patches={} vertices={} "
          "indices={} range=[{},{}] cache={}/{} misses={}",
          trace_draw_index_, uint32_t(tess_pp.host_vertex_shader_type),
          uint32_t(tess_pp.tessellation_mode), tess_counts.patch_count,
          tess_counts.vertex_count, tess_counts.index_count,
          tess_in.factor_range_min, tess_in.factor_range_max,
          host_tessellator_->pattern_cache_size(),
          host_tessellator_->pattern_cache_capacity(),
          host_tessellator_->pattern_cache_misses());
    }
  }

  // Rectangle VS expansion: the rectangles' guest vertex indices in host
  // order, 3 dwords per rectangle (auto-indexed: 3r..3r+2), exposed to the
  // vertex shader as entry 1 of a per-draw SRV space-0 table like the host
  // tessellation records; host indices 4r..4r+3 and a strip restart.
  MetalUploadAllocation rect_index_table_alloc{};
  MetalUploadAllocation rect_host_indices_alloc{};
  MetalUploadAllocation rect_srv_table_alloc{};
  uint32_t rect_host_index_count = 0;
  if (rect_strip_route) {
    const uint32_t rects = index_count / 3;
    if (!rects) {
      RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                     "rect-degenerate");
      return true;
    }
    rect_host_index_count = rects * 5;
    if (!ArenaAllocate(rects * 3 * sizeof(uint32_t), 16,
                       &rect_index_table_alloc) ||
        !ArenaAllocate(rect_host_index_count * sizeof(uint32_t), 16,
                       &rect_host_indices_alloc) ||
        !ArenaAllocate(2 * sizeof(IRDescriptorTableEntry), 256,
                       &rect_srv_table_alloc)) {
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                     "rect-index-alloc");
      return true;
    }
    // The arena is write-combined: write only, swap in cached stack chunks.
    uint32_t* table = static_cast<uint32_t*>(rect_index_table_alloc.cpu_ptr);
    const uint32_t table_count = rects * 3;
    if (index_buffer_info && index_buffer_info->guest_base) {
      const void* guest_indices =
          TranslateGuest<const uint8_t*>(index_buffer_info->guest_base);
      if (!guest_indices) {
        RecordDrawSkip(MetalDrawSkipReason::kInvalidGuestState,
                       "rect-index-guest-null");
        return true;
      }
      auto widen = [&](auto* src) {
        using T = std::remove_const_t<std::remove_pointer_t<decltype(src)>>;
        constexpr uint32_t kChunk = 256;
        T chunk[kChunk];
        uint32_t widened[kChunk];
        for (uint32_t i0 = 0; i0 < table_count; i0 += kChunk) {
          const uint32_t n = std::min(kChunk, table_count - i0);
          SwapIndicesInto(chunk, src + i0, n, index_buffer_info->format,
                          index_buffer_info->endianness);
          for (uint32_t i = 0; i < n; ++i) {
            widened[i] = uint32_t(chunk[i]);
          }
          std::memcpy(table + i0, widened, n * sizeof(uint32_t));
        }
      };
      if (index_buffer_info->format == xenos::IndexFormat::kInt32) {
        widen(static_cast<const uint32_t*>(guest_indices));
      } else {
        widen(static_cast<const uint16_t*>(guest_indices));
      }
    } else {
      for (uint32_t i = 0; i < table_count; ++i) {
        table[i] = i;
      }
    }
    uint32_t* host_indices =
        static_cast<uint32_t*>(rect_host_indices_alloc.cpu_ptr);
    for (uint32_t r = 0; r < rects; ++r) {
      uint32_t* o = host_indices + size_t(r) * 5;
      o[0] = r * 4u;
      o[1] = r * 4u + 1;
      o[2] = r * 4u + 2;
      o[3] = r * 4u + 3;
      o[4] = UINT32_MAX;
    }
    auto* rect_table_entries =
        static_cast<IRDescriptorTableEntry*>(rect_srv_table_alloc.cpu_ptr);
    std::memset(rect_table_entries, 0, 2 * sizeof(IRDescriptorTableEntry));
    __unsafe_unretained id<MTLBuffer> rect_shared_buffer =
        (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
    IRDescriptorTableSetBuffer(&rect_table_entries[0],
                               [rect_shared_buffer gpuAddress],
                               shared_memory_->gpu_visible_length());
    IRDescriptorTableSetBuffer(&rect_table_entries[1],
                               rect_index_table_alloc.gpu_address,
                               table_count * sizeof(uint32_t));
    static bool s_rect_engaged_logged = false;
    if (!s_rect_engaged_logged) {
      s_rect_engaged_logged = true;
      REXLOG_INFO("MetalCommandProcessor: rectangle VS expansion engaged, first "
             "draw={} rectangles={} {}",
             trace_draw_index_, rects,
             index_buffer_info && index_buffer_info->guest_base ? "indexed"
                                                                : "auto");
    }
  }

  MetalBindingAddresses binding_addresses;
  binding_addresses.null_buffer = null_gpu;
  binding_addresses.view_heap = view_heap_gpu;
  binding_addresses.sampler_heap = sampler_heap_gpu;
  binding_addresses.shared_memory_srv =
      tess_host_table_alloc.buffer
          ? tess_host_table_alloc.gpu_address
      : rect_srv_table_alloc.buffer
          ? rect_srv_table_alloc.gpu_address
          : system_view_gpu +
                kSystemViewSharedMemorySRV * sizeof(IRDescriptorTableEntry);
  binding_addresses.null_uav =
      system_view_gpu + kSystemViewNullUAV * sizeof(IRDescriptorTableEntry);
  binding_addresses.shared_memory_uav =
      system_view_gpu + kSystemViewSharedMemoryUAV * sizeof(IRDescriptorTableEntry);
  binding_addresses.system_constants = system_alloc.gpu_address;
  binding_addresses.float_vertex = float_vertex_alloc.gpu_address;
  binding_addresses.bool_loop = bool_loop_alloc.gpu_address;
  draw_trace_milestone("after-descriptors");
  binding_addresses.fetch = fetch_alloc.gpu_address;
  binding_addresses.descriptor_indices_vertex = desc_idx_vertex_alloc.gpu_address;
  binding_addresses.float_pixel = float_pixel_alloc.gpu_address;
  binding_addresses.descriptor_indices_pixel = desc_idx_pixel_alloc.gpu_address;
  // Design D2 (stage-true UAV binding): `memexport_draw` is the VS-only
  // attachment-less pass; `memexport_raster_routed` is the NEW rasterizing
  // class. Both need u0/space0 pointed at the writable shared-memory UAV
  // instead of the null UAV -- and nothing else about the rasterizing draw
  // changes (same pipeline, same attachments, same primitive).
  const bool memexport_uav_bound = memexport_draw || memexport_raster_routed;
  std::array<uint64_t, kMetalBindingSlotCount> argument_buffer =
      BuildMetalTopLevelArgumentBuffer(binding_addresses, pixel_shader != nullptr,
                                       memexport_uav_bound);
  std::memcpy(ab_alloc.cpu_ptr, argument_buffer.data(), sizeof(argument_buffer));

  // --- Bind. ---
  if (!state_dedupe || encoder_fixed_state_.pipeline != pipeline) {
    if (deferred_pipeline) {
      es.SetRenderPipelineStateDeferred(
          MetalPipelineCache::ResolveDeferredPipeline, pipeline,
          deferred_pipeline);
    } else {
      es.SetRenderPipelineState((__bridge id<MTLRenderPipelineState>)pipeline);
    }
    encoder_fixed_state_.pipeline = pipeline;
    encoder_fixed_state_.pipeline_owner = std::move(deferred_pipeline);
  }

  // Apply complete blend/stencil dynamic values on every normal draw. Metal
  // encoder state persists across draws, while a new encoder begins with its
  // own defaults, so even blend colors that a particular pipeline doesn't
  // consume are established rather than assumed. Memexport has no raster
  // output and stays outside this state. The helper also prevents raw
  // back-face stencil state from leaking into non-polygon primitives.
  reg::RB_STENCILREFMASK stencil_ref_mask =
      regs.Get<reg::RB_STENCILREFMASK>();
  reg::RB_STENCILREFMASK stencil_ref_mask_back =
      regs.Get<reg::RB_STENCILREFMASK>(XE_GPU_REG_RB_STENCILREFMASK_BF);
  MetalBlendStencilState blend_stencil = GetMetalBlendStencilState(
      regs.Get<float>(XE_GPU_REG_RB_BLEND_RED),
      regs.Get<float>(XE_GPU_REG_RB_BLEND_GREEN),
      regs.Get<float>(XE_GPU_REG_RB_BLEND_BLUE),
      regs.Get<float>(XE_GPU_REG_RB_BLEND_ALPHA), norm_depth,
      ::rex::gpu::draw_state::IsPrimitivePolygonal(regs), stencil_ref_mask,
      stencil_ref_mask_back);
  if (!memexport_draw) {
    EncoderFixedState& fs = encoder_fixed_state_;
    const float blend_color[4] = {
        blend_stencil.blend_color_red, blend_stencil.blend_color_green,
        blend_stencil.blend_color_blue, blend_stencil.blend_color_alpha};
    if (!state_dedupe || !fs.blend_color_valid ||
        std::memcmp(fs.blend_color, blend_color, sizeof(blend_color))) {
      es.SetBlendColor(blend_stencil.blend_color_red,
                       blend_stencil.blend_color_green,
                       blend_stencil.blend_color_blue,
                       blend_stencil.blend_color_alpha);
      std::memcpy(fs.blend_color, blend_color, sizeof(blend_color));
      fs.blend_color_valid = true;
    }
  }
  if (kDepthEnabled && depth_bound &&
      (encoder_bound_attachments_ & metal::kMetalPassAttachmentDepthStencil)) {
    // Only when the pass has a depth attachment — setting a depth-test state on
    // an encoder without one is a Metal validation error. norm_depth already
    // collapsed "always, no write" to disabled. (D2: a by-use pass may leave
    // depth unbound; its draws then neither test nor write it.)
    void* depth_state = GetOrCreateDepthStencilState(
        norm_depth.value, stencil_ref_mask.value, stencil_ref_mask_back.value);
    if (depth_state) {
      // Encoder state persists across draws; skip re-setting what the open
      // encoder already carries.
      if (depth_state != encoder_depth_stencil_state_) {
        es.SetDepthStencilState(
            (__bridge id<MTLDepthStencilState>)depth_state);
        encoder_depth_stencil_state_ = depth_state;
      }
      if (blend_stencil.stencil_enabled &&
          (blend_stencil.stencil_reference_front != encoder_stencil_ref_front_ ||
           blend_stencil.stencil_reference_back != encoder_stencil_ref_back_)) {
        es.SetStencilReferenceValues(blend_stencil.stencil_reference_front,
                                     blend_stencil.stencil_reference_back);
        encoder_stencil_ref_front_ = blend_stencil.stencil_reference_front;
        encoder_stencil_ref_back_ = blend_stencil.stencil_reference_back;
      }
    }
  }
  if (kDebugSolidFragment) {
    // Per-vertex-shader color so distinct draw types show as distinct regions:
    // many colors = real structured scene geometry, one flat color = a single
    // fullscreen quad covering everything.
    uintptr_t p = reinterpret_cast<uintptr_t>(vs_translation->metal_function());
    uint32_t h = uint32_t(p * 2654435761u);
    float debug_color[4] = {0.2f + 0.8f * ((h & 0xFF) / 255.0f),
                            0.2f + 0.8f * (((h >> 8) & 0xFF) / 255.0f),
                            0.2f + 0.8f * (((h >> 16) & 0xFF) / 255.0f), 1.0f};
    es.SetBytes(MetalEncodeStream::kStageFragment, debug_color,
                sizeof(debug_color), 8);
  }
  __unsafe_unretained id<MTLBuffer> ab_buffer = (__bridge id<MTLBuffer>)ab_alloc.buffer;
  // Geometry emulation runs mesh-path pipelines (object + mesh stages), so
  // the argument buffer + bindless heaps bind to object/mesh instead of
  // vertex. The fragment stage is unchanged.
  const bool use_mesh_path = use_geometry_emulation;
  // Stage kinds 0 vertex, 1 fragment, 2 object, 3 mesh; the three argument
  // bind points map to slots 0..2. Same buffer and offset: skip; same buffer,
  // new offset: the cheaper offset-only setter.
  const bool encoder_dedupe = EncoderDedupeEnabled();
  auto bind_stage = [&](uint32_t kind, uint32_t slot, __unsafe_unretained id<MTLBuffer> buf, NSUInteger off,
                        NSUInteger idx) {
    if (encoder_dedupe && slot < 3) {
      EncoderBufferBind& b = encoder_buffer_binds_[kind][slot];
      void* raw = (__bridge void*)buf;
      if (b.buffer == raw) {
        if (b.offset == off) {
          return;
        }
        b.offset = off;
        es.SetBufferOffset(kind, off, idx);
        return;
      }
      b.buffer = raw;
      b.offset = off;
    }
    es.SetBuffer(kind, buf, off, idx);
  };
  auto bind_arg_buffer = [&](__unsafe_unretained id<MTLBuffer> buf, NSUInteger off, NSUInteger idx) {
    const uint32_t slot = idx == kIRArgumentBufferBindPoint   ? 0u
                          : idx == kIRDescriptorHeapBindPoint ? 1u
                          : idx == kIRSamplerHeapBindPoint    ? 2u
                                                              : 3u;
    if (use_mesh_path) {
      bind_stage(2, slot, buf, off, idx);
      bind_stage(3, slot, buf, off, idx);
    } else {
      bind_stage(0, slot, buf, off, idx);
    }
    bind_stage(1, slot, buf, off, idx);
  };
  bind_arg_buffer(ab_buffer, ab_alloc.offset, kIRArgumentBufferBindPoint);
  bind_arg_buffer(view_heap, 0, kIRDescriptorHeapBindPoint);
  bind_arg_buffer(sampler_heap, 0, kIRSamplerHeapBindPoint);
  if (use_mesh_path) {
    // MSC manual: the object stage expects an IRRuntimeVertexBuffers table at
    // kIRVertexBufferBindPoint. Our guest VS fetches in-shader from shared memory
    // (zero stage-in inputs), so a zeroed table satisfies the binding without
    // supplying any real vertex streams.
    IRRuntimeVertexBuffers vertex_buffers = {};
    es.SetBytes(MetalEncodeStream::kStageObject, &vertex_buffers,
                sizeof(vertex_buffers), kIRVertexBufferBindPoint);
  }
  // Residency for everything the shaders reach through gpuAddresses.
  __unsafe_unretained id<MTLBuffer> shared_buffer =
      (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
  __unsafe_unretained id<MTLTexture> null_texture = (__bridge id<MTLTexture>)null_texture_;
  uint32_t binding_stage_mask = GetMetalBindingStageMask(use_mesh_path);
  MTLRenderStages stages = 0;
  if (binding_stage_mask & kMetalBindingStageVertex) {
    stages |= MTLRenderStageVertex;
  }
  if (binding_stage_mask & kMetalBindingStageObject) {
    stages |= MTLRenderStageObject;
  }
  if (binding_stage_mask & kMetalBindingStageMesh) {
    stages |= MTLRenderStageMesh;
  }
  if (binding_stage_mask & kMetalBindingStageFragment) {
    stages |= MTLRenderStageFragment;
  }
  // Residency: `stages` already spans exactly the stages this draw's shaders
  // run on (vertex+fragment, or object+mesh+fragment under emulation), which
  // is a superset of the memexport WRITING stage -- MSC compiles the guest
  // VS's eM# stores onto the vertex stage for a plain draw and the OBJECT
  // stage under geometry emulation (the mesh stage is the GENERATED GS, which
  // declares no UAV; see metal_memexport_raster_flags.h's D2 note).
  // A declaration already made on this encoder with a superset of the usage
  // and stages covers this draw too (useResource applies to the whole pass).
  // retain: a cache-owned texture a later draw's decision can evict while the
  // op still waits for replay.
  auto use_resource = [&](__unsafe_unretained id<MTLResource> resource,
                          MTLResourceUsage usage, bool retain = false) {
    if (encoder_dedupe) {
      const uint32_t bits = uint32_t(usage) | (uint32_t(stages) << 8);
      void* raw = (__bridge void*)resource;
      if (uint32_t* declared = encoder_declared_resources_.Find(raw)) {
        if ((*declared & bits) == bits) {
          return;
        }
        *declared |= bits;
      }
    }
    es.UseResource(resource, usage, stages, retain);
  };
  use_resource(shared_buffer, memexport_uav_bound ? (MTLResourceUsageRead | MTLResourceUsageWrite)
                                                  : MTLResourceUsageRead);
  use_resource(ab_buffer, MTLResourceUsageRead);
  use_resource(view_heap, MTLResourceUsageRead);
  use_resource(sampler_heap, MTLResourceUsageRead);
  use_resource(system_view, MTLResourceUsageRead);
  use_resource(null_buffer, MTLResourceUsageRead);
  use_resource(null_texture, MTLResourceUsageRead);
  // Texture heaps (discrete AMD): every heap is resident for the stages
  // declared so far on this encoder; a new heap, or a draw needing more
  // stages, re-declares. Textures allocated from a heap then skip the
  // per-texture declaration (tagged in the dedupe table on first sight).
  const bool heaps_active = encoder_dedupe && texture_cache_->texture_heaps_enabled();
  if (heaps_active) {
    const uint32_t heap_count = texture_cache_->texture_heap_count();
    const uint32_t stage_bits = uint32_t(stages);
    const bool new_stages = (stage_bits & ~encoder_heap_stages_) != 0;
    if (heap_count && (new_stages || heap_count > encoder_heaps_declared_)) {
      const uint32_t first = new_stages ? 0 : encoder_heaps_declared_;
      encoder_heap_stages_ |= stage_bits;
      __unsafe_unretained id<MTLHeap> heaps[64];
      uint32_t n = 0;
      for (uint32_t h = first; h < heap_count && n < 64; ++h) {
        heaps[n++] = (__bridge id<MTLHeap>)texture_cache_->texture_heap(h);
      }
      es.UseHeaps(heaps, n, MTLRenderStages(encoder_heap_stages_));
      encoder_heaps_declared_ = heap_count;
      ++heap_declarations_;
    }
  }
  if (MetalTextureCache::SlotAuditEnabled()) {
    texture_cache_->AuditDrawSlots(audit_draw_slots_.data(),
                                   audit_draw_slots_.size(),
                                   CurrentEncodingSubmission());
  }
  constexpr uint32_t kHeapBackedBit = 0x80000000u;
  for (void* tex : texture_cache_->active_textures()) {
    if (heaps_active) {
      if (uint32_t* declared = encoder_declared_resources_.Find(tex)) {
        if (!*declared) {
          __unsafe_unretained id<MTLTexture> t = (__bridge id<MTLTexture>)tex;
          // A view's memory is its root texture's.
          for (uint32_t depth = 0; t && depth < 4; ++depth) {
            if (t.heap) {
              *declared = kHeapBackedBit;
              break;
            }
            t = t.parentTexture;
          }
          if (!*declared) {
            LogHeapMissTexture(tex);
          }
        }
        if (*declared & kHeapBackedBit) {
          ++heap_skipped_declarations_;
          continue;
        }
      }
      ++texture_declarations_;
    }
    use_resource((__bridge id<MTLTexture>)tex, MTLResourceUsageRead, true);
  }

  draw_trace_milestone("after-use-resources");
  // Draw parameters (XE_METAL_DRAW_PARAMS): the IRRuntime draw helpers upload
  // the draw arguments and the index-type word with setVertexBytes on every
  // draw. The translated vertex shaders fetch vertices themselves (no
  // stage-in) and every draw here passes instance count 1, base vertex 0 and
  // base instance 0, so only those fields can matter; mode 1 (default) binds
  // canonical arguments and re-binds only when the pair changes on the open
  // encoder. Burnout: ~6,000 draws in the main pass, whose vertex phase is
  // front-end bound (vertex occupancy ~4%). 0 = the IRRuntime helpers;
  // 2 = probe: the per-draw-only fields hold junk (must render identically).
  static const uint32_t s_draw_params_mode = [] {
    const char* v = std::getenv("XE_METAL_DRAW_PARAMS");
    return v ? uint32_t(strtoul(v, nullptr, 10)) : 1u;
  }();
  auto bind_draw_params = [&](bool indexed, uint16_t ir_index_type) {
    const int32_t key = indexed ? int32_t(ir_index_type) : -2;
    if (encoder_fixed_state_.draw_params == key) {
      return;
    }
    IRRuntimeDrawParams dp = {};
    const uint32_t junk = s_draw_params_mode == 2 ? 0x00012345u : 0u;
    if (indexed) {
      dp.drawIndexed.indexCountPerInstance = junk;
      dp.drawIndexed.instanceCount = 1;
      dp.drawIndexed.startIndexLocation = junk;
    } else {
      dp.draw.vertexCountPerInstance = junk;
      dp.draw.instanceCount = 1;
    }
    es.SetBytes(MetalEncodeStream::kStageVertex, &dp, sizeof(dp),
                kIRArgumentBufferDrawArgumentsBindPoint);
    const uint16_t uniform = indexed ? ir_index_type : kIRNonIndexedDraw;
    es.SetBytes(MetalEncodeStream::kStageVertex, &uniform, sizeof(uniform),
                kIRArgumentBufferUniformsBindPoint);
    encoder_fixed_state_.draw_params = key;
  };
  auto ir_draw_indexed = [&](MTLPrimitiveType prim, uint64_t index_count_host,
                             MTLIndexType index_type,
                             __unsafe_unretained id<MTLBuffer> index_buffer,
                             uint64_t index_offset, uint64_t instance_count,
                             int64_t base_vertex, uint64_t base_instance) {
    if (!s_draw_params_mode) {
      es.IRDrawIndexedPrimitives(prim, index_count_host, index_type,
                                 index_buffer, index_offset, instance_count,
                                 base_vertex, base_instance);
      return;
    }
    // IRMetalIndexToIRIndex (implementation-only in the runtime header).
    bind_draw_params(true, uint16_t(uint16_t(index_type) + 1u));
    es.DrawIndexedPrimitives(prim, index_count_host, index_type, index_buffer,
                             index_offset, instance_count, base_vertex,
                             base_instance);
  };
  auto ir_draw = [&](MTLPrimitiveType prim, uint64_t vertex_start,
                     uint64_t vertex_count) {
    if (!s_draw_params_mode) {
      es.IRDrawPrimitives(prim, vertex_start, vertex_count);
      return;
    }
    bind_draw_params(false, 0);
    es.DrawPrimitives(prim, vertex_start, vertex_count);
  };
  auto mark_raster_targets_written = [&] {
    if (pixel_export_only) {
      // Only a scratch depth is bound; no guest target was written.
      return;
    }
    if (PassCensusEnabled()) {
      // Materialize-fate census: can this draw observe each target's old
      // content? Pixel kill and alpha test leave pixels unwritten, so they
      // count as reads of every target.
      const bool kills =
          (pixel_shader && pixel_shader->DoesKillPixels()) ||
          regs.Get<reg::RB_COLORCONTROL>().alpha_test_enable;
      uint32_t color_read_mask = 0;
      for (uint32_t i = 0; i < xenos::kMaxColorRenderTargets; ++i) {
        if (!((normalized_color_mask >> (i * 4)) & 0xFu)) {
          continue;
        }
        auto blend = regs.Get<reg::RB_BLENDCONTROL>(
            xenos::compat::BlendControlRegisterIndex(i));
        const bool replace =
            blend.color_srcblend == xenos::BlendFactor::kOne &&
            blend.color_destblend == xenos::BlendFactor::kZero &&
            blend.color_comb_fcn == xenos::BlendOp::kAdd &&
            blend.alpha_srcblend == xenos::BlendFactor::kOne &&
            blend.alpha_destblend == xenos::BlendFactor::kZero &&
            blend.alpha_comb_fcn == xenos::BlendOp::kAdd;
        if (kills || !replace) {
          color_read_mask |= 1u << i;
        }
      }
      const bool depth_read =
          kills || norm_depth.stencil_enable ||
          (norm_depth.z_enable &&
           norm_depth.zfunc != xenos::CompareFunction::kAlways);
      render_target_cache_->NoteMaterializeFirstUse(
          normalized_color_mask, color_read_mask,
          norm_depth.z_write_enable || norm_depth.stencil_enable, depth_read,
          draw_full_width,
          prim_type == xenos::PrimitiveType::kRectangleList ||
              index_count <= 6,
          draw_host_y0, draw_host_y1);
    }
    render_target_cache_->MarkCurrentRasterTargetsWritten(
        normalized_color_mask,
        norm_depth.z_write_enable || norm_depth.stencil_enable, draw_host_y0,
        draw_host_y1);
  };

  // Post-encode memexport publication, shared by every draw path that can
  // export (task 1.2 reuse: the VS-only route's publication call shape
  // generalizes UNTOUCHED -- DecideMemexportPublication +
  // PublishMemexportWrite register the pending record FIRST and then mark the
  // same normalized range GPU-written, as ONE ordered transition under
  // WriterKind::kMemexport). Every producer class therefore lands in
  // pending_memexports_ identically, so the cross-writer authority's
  // reconciliation, retain-on-failure, and texture invalidation are uniform by
  // construction. Convergence happens at the EXISTING points: the vertex /
  // texture consumer barriers above and the frame-boundary drain.
  auto publish_memexport_ranges = [&] {
    if (memexport_ranges.empty()) {
      return;
    }
    uint64_t export_submission = S7TagsOff() ? 0 : CurrentEncodingSubmission();
    MetalMemexportPublicationTarget publication_target(shared_memory_.get());
    for (const auto& range : memexport_ranges) {
      uint32_t range_base = range.base_address_dwords << 2;
      auto publication = metal::DecideMemexportPublication(
          range_base, range.size_bytes, export_submission);
      metal::MemexportPublicationResult publish_result;
      if (publication) {
        publish_result = metal::PublishMemexportWrite(
            *publication, publication_target,
            [this](const metal::MemexportPublication& owned) {
              pending_memexports_.push_back(PendingMemexport{
                  owned.range.start(), owned.range.length(), owned.submission,
                  ++memory_authority_sequence_});
              NoteDiscreteProducedRange(owned.range.start(),
                                        owned.range.length());
              if (false) {
                playback_gpu_written_.emplace_back(owned.range.start(),
                                                   owned.range.length());
              }
              return true;
            });
      }
      if (!publish_result.marked) {
        REXLOG_ERROR(
            "MetalMemexport: failed to publish GPU write {:08X}(+{}); "
            "no GPU-written notification was issued",
            range_base, range.size_bytes);
      }
    }
  };

  // --- Draw. ---
  // Host tessellation route (task 3.7): the expanded triangle list over the
  // record stream, through the ordinary vertex+fragment pipeline. The arena
  // transients live in the same MTLBuffer the argument buffer does, so their
  // residency is already covered; marked again for clarity.
  if (use_tessellation_emulation) {
    __unsafe_unretained id<MTLBuffer> tess_records_buffer =
        (__bridge id<MTLBuffer>)tess_host_records_alloc.buffer;
    __unsafe_unretained id<MTLBuffer> tess_indices_buffer =
        (__bridge id<MTLBuffer>)tess_host_indices_alloc.buffer;
    __unsafe_unretained id<MTLBuffer> tess_table_buffer =
        (__bridge id<MTLBuffer>)tess_host_table_alloc.buffer;
    use_resource(tess_records_buffer, MTLResourceUsageRead);
    use_resource(tess_indices_buffer, MTLResourceUsageRead);
    use_resource(tess_table_buffer, MTLResourceUsageRead);
    ir_draw_indexed( MTLPrimitiveTypeTriangle, tess_host_index_count,
        MTLIndexTypeUInt32, tess_indices_buffer, tess_host_indices_alloc.offset,
        /*instanceCount=*/1, /*baseVertex=*/0, /*baseInstance=*/0);
    mark_raster_targets_written();
    // Tessellated producers stay fail-closed upstream ("tess-memexport"), so
    // there is nothing to publish here.
    frame_has_render_ = true;
    ++draw_count_;
    return true;
  }

  // Rectangle/point/quad geometry emulation: the guest VS runs
  // as the object stage and a generated GS as the mesh stage; the runtime
  // dispatches the object+mesh threadgroups. rect-list maps to a triangle input
  // topology (the GS synthesizes the 4th corner). See openspec
  // reduce-apple-gpu-frametime handoff.
  if (use_geometry_emulation) {
    IRRuntimeGeometryPipelineConfig geometry_config = {};
    geometry_config.gsVertexSizeInBytes = gs_vertex_size;
    geometry_config.gsMaxInputPrimitivesPerMeshThreadgroup =
        gs_max_input_primitives;
    // The runtime primitive matches the GS input topology: rectangle lists
    // feed triangles, point sprites feed points, and quad lists feed the
    // line-with-adjacency geometry shader through the line primitive family.
    IRRuntimePrimitiveType geometry_primitive;
    switch (geometry_type) {
      case PipelineGeometryShader::kPointList:
        geometry_primitive = IRRuntimePrimitiveTypePoint;
        break;
      case PipelineGeometryShader::kQuadList:
        // The generated geometry shader declares line-with-adjacency. Tell
        // the runtime the full four-vertex primitive type too — passing the
        // ordinary two-vertex line type makes its object stage assemble pairs
        // while the mesh stage consumes groups of four, joining unrelated
        // quad vertices into long wedges (Red Dead's foliage draw 705).
        geometry_primitive = IRRuntimePrimitiveTypeLineWithAdj;
        break;
      case PipelineGeometryShader::kRectangleList:
      default:
        geometry_primitive = IRRuntimePrimitiveTypeTriangle;
        break;
    }
    if (index_buffer_info && index_buffer_info->guest_base) {
      uint32_t index_size =
          index_buffer_info->format == xenos::IndexFormat::kInt32 ? 4 : 2;
      uint32_t total = index_count * index_size;
      const void* guest_indices =
          TranslateGuest<const uint8_t*>(index_buffer_info->guest_base);
      MetalUploadAllocation index_alloc{};
      if (!guest_indices || !ArenaAllocate(total, 16, &index_alloc)) {
        RecordDrawSkip(!guest_indices
                           ? MetalDrawSkipReason::kInvalidGuestState
                           : MetalDrawSkipReason::kResourceFailure,
                       !guest_indices ? "index-guest-null" : "index-alloc");
        return true;
      }
      SwapIndicesInto(index_alloc.cpu_ptr, guest_indices, index_count,
                      index_buffer_info->format, index_buffer_info->endianness);
      __unsafe_unretained id<MTLBuffer> index_buffer = (__bridge id<MTLBuffer>)index_alloc.buffer;
      use_resource(index_buffer, MTLResourceUsageRead);
      MTLIndexType index_type =
          index_size == 4 ? MTLIndexTypeUInt32 : MTLIndexTypeUInt16;
      // The runtime reads the index buffer by gpuAddress; our data lives at the
      // arena byte offset, expressed here as an element start index.
      uint32_t start_index = uint32_t(index_alloc.offset / index_size);
      const uint32_t chunk = GeometryEmulationChunkVertices(
          geometry_primitive, gs_vertex_size, gs_max_input_primitives,
          index_count);
      NoteGeometryEmulationDraw(uint32_t(geometry_type), index_count, chunk);
      for (uint32_t first = 0; first < index_count; first += chunk) {
        const uint32_t count = std::min(chunk, index_count - first);
        es.IRDrawIndexedGeometryEmulation(
            geometry_primitive, index_type, index_buffer, geometry_config,
            /*instance_count=*/1, count, start_index + first,
            /*base_vertex=*/0, /*base_instance=*/0);
      }
    } else {
      const uint32_t chunk = GeometryEmulationChunkVertices(
          geometry_primitive, gs_vertex_size, gs_max_input_primitives,
          index_count);
      NoteGeometryEmulationDraw(uint32_t(geometry_type), index_count, chunk);
      for (uint32_t first = 0; first < index_count; first += chunk) {
        const uint32_t count = std::min(chunk, index_count - first);
        es.IRDrawGeometryEmulation(geometry_primitive, geometry_config,
                                   /*instance_count=*/1, count,
                                   /*base_vertex=*/first, /*base_instance=*/0);
      }
    }
    mark_raster_targets_written();
    // Task 2.3: the geometry-emulated rasterizing producer publishes on the
    // SAME original draw it just encoded (design D1 -- no shadow draw). This
    // path returns before the common tail, so the publication has to happen
    // here or the exports would never acquire a pending record.
    if (memexport_raster_routed) {
      publish_memexport_ranges();
    }
    frame_has_render_ = true;
    ++draw_count_;
    ++geo_draw_count_;
    return true;
  }

  // Triangle fans have no host primitive on Metal: expand to a triangle list
  // with a generated 32-bit index buffer. Fan (v0, v1, v2, v3, ...) becomes
  // triangles (v0,v1,v2), (v0,v2,v3), ... indexing the same vertices, so it
  // works whether the guest draw is indexed or sequential (auto).
  if (prim_type == xenos::PrimitiveType::kTriangleFan && !pp_routed) {
    if (index_count < 3) {
      RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect, "fan-degenerate");
      return true;
    }
    uint32_t host_index_count = (index_count - 2) * 3;
    MetalUploadAllocation fan_alloc{};
    if (!ArenaAllocate(host_index_count * sizeof(uint32_t), 16,
                                 &fan_alloc)) {
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure, "fan-index-alloc");
      return true;
    }
    // Source vertex indices: the (endian-swapped) guest index buffer, or the
    // sequential 0..N-1 for an auto draw.
    std::vector<uint32_t> src(index_count);
    if (index_buffer_info && index_buffer_info->guest_base) {
      const void* gi = TranslateGuest<const uint8_t*>(index_buffer_info->guest_base);
      if (!gi) {
        RecordDrawSkip(MetalDrawSkipReason::kInvalidGuestState,
                       "fan-guest-null");
        return true;
      }
      bool i32 = index_buffer_info->format == xenos::IndexFormat::kInt32;
      xenos::Endian ie = index_buffer_info->endianness;
      for (uint32_t i = 0; i < index_count; ++i) {
        if (i32) {
          uint32_t v = static_cast<const uint32_t*>(gi)[i];
          src[i] = ie == xenos::Endian::kNone ? v : rex::byte_swap(v);
        } else {
          uint16_t v = static_cast<const uint16_t*>(gi)[i];
          bool swap = ie == xenos::Endian::k8in16 || ie == xenos::Endian::k8in32;
          src[i] = swap ? rex::byte_swap(v) : v;
        }
      }
    } else {
      for (uint32_t i = 0; i < index_count; ++i) {
        src[i] = i;
      }
    }
    uint32_t* host_idx = static_cast<uint32_t*>(fan_alloc.cpu_ptr);
    uint32_t o = 0;
    for (uint32_t i = 1; i + 1 < index_count; ++i) {
      host_idx[o++] = src[0];
      host_idx[o++] = src[i];
      host_idx[o++] = src[i + 1];
    }
    __unsafe_unretained id<MTLBuffer> fan_ib = (__bridge id<MTLBuffer>)fan_alloc.buffer;
    use_resource(fan_ib, MTLResourceUsageRead);
    ir_draw_indexed( MTLPrimitiveTypeTriangle,
                                   host_index_count, MTLIndexTypeUInt32, fan_ib,
                                   fan_alloc.offset, /*instanceCount=*/1,
                                   /*baseVertex=*/0, /*baseInstance=*/0);
    mark_raster_targets_written();
    // Same reason as the geometry-emulation path: this branch returns before
    // the common tail, so a routed producer publishes here.
    if (memexport_raster_routed) {
      publish_memexport_ranges();
    }
    frame_has_render_ = true;
    ++draw_count_;
    return true;
  }
  if (rect_strip_route) {
    // Rectangle VS expansion (table and indices built before the bindings).
    __unsafe_unretained id<MTLBuffer> rect_table_buffer =
        (__bridge id<MTLBuffer>)rect_index_table_alloc.buffer;
    __unsafe_unretained id<MTLBuffer> rect_indices_buffer =
        (__bridge id<MTLBuffer>)rect_host_indices_alloc.buffer;
    __unsafe_unretained id<MTLBuffer> rect_srv_table_buffer =
        (__bridge id<MTLBuffer>)rect_srv_table_alloc.buffer;
    use_resource(rect_table_buffer, MTLResourceUsageRead);
    use_resource(rect_indices_buffer, MTLResourceUsageRead);
    use_resource(rect_srv_table_buffer, MTLResourceUsageRead);
    {
      RectDrawNote& note = rect_draw_ring_[rect_draw_next_++ % 256];
      note.submission = submission_counter_ + 1;
      note.ps = pixel_shader ? pixel_shader->GetUcodeDataHash() : 0;
      note.pipeline = pipeline;
      note.draw = draw_count_;
      note.index_count = index_count;
      note.color_format = uint32_t(color_pixel_formats[0]);
      note.depth_format = uint32_t(pipeline_depth_format);
    }
    ir_draw_indexed(MTLPrimitiveTypeTriangleStrip, rect_host_index_count,
                    MTLIndexTypeUInt32, rect_indices_buffer,
                    rect_host_indices_alloc.offset, /*instanceCount=*/1,
                    /*baseVertex=*/0, /*baseInstance=*/0);
    mark_raster_targets_written();
    // Returns before the common tail, like the fan path.
    if (memexport_draw || memexport_raster_routed) {
      publish_memexport_ranges();
    }
    frame_has_render_ = true;
    ++draw_count_;
    ++draws_since_commit_;
    return true;
  }
  if (pp_routed) {
    // Routed draw: the shared ::rex::gpu::PrimitiveProcessor is the normalization authority.
    // Bind/draw from pp_result. host_primitive_type is either one of the four
    // PP1/PP4 native classes (host == guest, non-tessellated), kTriangleList
    // for a PP2-auto fan, or kLineStrip for a PP3-auto loop, so
    // MapPrimitiveType always succeeds. The index MECHANISM is unchanged:
    // PP1 and PP4 kGuestDMA CPU-byte-swap the guest indices into the arena
    // using the NORMALIZED host_index_format / host_shader_index_endian
    // (byte-identical to the inline SwapIndicesInto); PP2-auto copies the
    // built-in fan-table slice into the arena (below).
    MTLPrimitiveType pp_prim = MTLPrimitiveTypeTriangle;
    MapPrimitiveType(pp_result.host_primitive_type, &pp_prim);
    uint32_t host_count = pp_result.host_draw_vertex_count;
    if (direct_index) {
      __unsafe_unretained id<MTLBuffer> index_buffer =
          (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
      ir_draw_indexed(pp_prim, host_count,
                      pp_result.host_index_format == xenos::IndexFormat::kInt32
                          ? MTLIndexTypeUInt32
                          : MTLIndexTypeUInt16,
                      index_buffer, direct_index_offset,
                      /*instanceCount=*/1, /*baseVertex=*/0,
                      /*baseInstance=*/0);
    } else if (pp_result.index_buffer_type == ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kGuestDMA) {
      uint32_t index_size = pp_result.host_index_format == xenos::IndexFormat::kInt32 ? 4 : 2;
      uint32_t total = host_count * index_size;
      const void* guest_indices = TranslateGuest<const uint8_t*>(pp_result.guest_index_base);
      MetalUploadAllocation index_alloc{};
      if (!guest_indices || !ArenaAllocate(total, 16, &index_alloc)) {
        RecordDrawSkip(!guest_indices
                           ? MetalDrawSkipReason::kInvalidGuestState
                           : MetalDrawSkipReason::kResourceFailure,
                       !guest_indices ? "pp-index-guest-null"
                                      : "pp-index-alloc");
        return true;
      }
      SwapIndicesInto(index_alloc.cpu_ptr, guest_indices, host_count, pp_result.host_index_format,
                      pp_result.host_shader_index_endian);
      __unsafe_unretained id<MTLBuffer> index_buffer = (__bridge id<MTLBuffer>)index_alloc.buffer;
      use_resource(index_buffer, MTLResourceUsageRead);
      MTLIndexType index_type = index_size == 4 ? MTLIndexTypeUInt32 : MTLIndexTypeUInt16;
      ir_draw_indexed( pp_prim, host_count, index_type, index_buffer,
                                     index_alloc.offset,
                                     /*instanceCount=*/1, /*baseVertex=*/0,
                                     /*baseInstance=*/0);
    } else if (pp_result.index_buffer_type ==
               ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kNone) {
      // PP1 auto pass-through or PP3-auto line loop: no host index byte stream.
      ir_draw( pp_prim, /*vertexStart=*/uint64_t(0), uint64_t(host_count));
    } else if (pp_result.index_buffer_type ==
                   ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::
                       kHostBuiltinForAuto ||
               pp_result.index_buffer_type ==
                   ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::
                       kHostBuiltinForDMA) {
      // Built-in tables: the auto-indexed fan / quad tables (16-bit) and the
      // two-triangle-strip table for DMA point/rect expansion (32-bit; only
      // produced when the host VS expands those lists, which Metal's point
      // strip route and MSC geometry emulation do not request today).
      // Materialize the needed slice into the transient upload arena (same
      // lifetime as the inline path) and draw with the table's index width.
      // count<3 -> host_count 0 -> no-draw skip, matching the inline path.
      if (host_count == 0) {
        RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                       "pp2-degenerate");
        return true;
      }
      const uint32_t builtin_index_size =
          pp_result.host_index_format == xenos::IndexFormat::kInt32 ? 4u : 2u;
      uint32_t total = host_count * builtin_index_size;
      MetalUploadAllocation index_alloc{};
      if (!ArenaAllocate(total, 16, &index_alloc)) {
        RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                       "pp2-index-alloc");
        return true;
      }
      if (!primitive_processor_->CopyBuiltinIndexData(
              pp_result.host_index_buffer_handle, total, index_alloc.cpu_ptr)) {
        // Out-of-bounds slice (never expected: num_indices is 16-bit and the
        // table covers UINT16_MAX). Fail closed to a skip rather than read past.
        RecordDrawSkip(MetalDrawSkipReason::kInternalInvariant,
                       "pp2-builtin-copy");
        return true;
      }
      __unsafe_unretained id<MTLBuffer> index_buffer = (__bridge id<MTLBuffer>)index_alloc.buffer;
      use_resource(index_buffer, MTLResourceUsageRead);
      ir_draw_indexed(pp_prim, host_count,
                      builtin_index_size == 4 ? MTLIndexTypeUInt32
                                              : MTLIndexTypeUInt16,
                      index_buffer, index_alloc.offset, /*instanceCount=*/1,
                      /*baseVertex=*/0, /*baseInstance=*/0);
    } else if (pp_result.index_buffer_type ==
               ::rex::gpu::PrimitiveProcessor::ProcessedIndexBufferType::kHostConverted) {
      // Host-converted stream (DMA fan -> list, loop -> strip, quad -> list,
      // custom / 32-bit reset replacement, 16-bit reset-disabled widening):
      // the shared processor wrote it into the per-frame CPU pool in the
      // endianness it reports; swap it per element into the transient arena
      // (vertex_index_endian stays kNone, the one index convention of this
      // backend) and draw with the converted width. A zero count was skipped
      // before the encoder opened.
      const uint32_t converted_index_size =
          pp_result.host_index_format == xenos::IndexFormat::kInt32 ? 4u : 2u;
      const uint32_t total = host_count * converted_index_size;
      const void* converted = primitive_processor_->GetConvertedIndexData(
          pp_result.host_index_buffer_handle, total);
      if (!converted) {
        // The handle is this frame's pool offset; an out-of-bounds range means
        // the pool was cleared under a live result (frame-boundary bug).
        RecordDrawSkip(MetalDrawSkipReason::kInternalInvariant,
                       "pp-converted-range");
        return true;
      }
      MetalUploadAllocation index_alloc{};
      if (!ArenaAllocate(total, 16, &index_alloc)) {
        RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                       "pp-converted-alloc");
        return true;
      }
      SwapConvertedIndicesInto(index_alloc.cpu_ptr, converted, host_count,
                               pp_result.host_index_format,
                               pp_result.host_shader_index_endian);
      __unsafe_unretained id<MTLBuffer> index_buffer =
          (__bridge id<MTLBuffer>)index_alloc.buffer;
      use_resource(index_buffer, MTLResourceUsageRead);
      ir_draw_indexed(pp_prim, host_count,
                      converted_index_size == 4 ? MTLIndexTypeUInt32
                                                : MTLIndexTypeUInt16,
                      index_buffer, index_alloc.offset, /*instanceCount=*/1,
                      /*baseVertex=*/0, /*baseInstance=*/0);
    } else {
      // Unreachable: the pre-encoder validator accepts only the five shared
      // index-buffer types, all bound above. Never silently fall into an auto
      // draw for an unexpected index-buffer type.
      REXLOG_ERROR("MetalPrimitiveProcessor: routed draw reached emission with "
             "unexpected index_buffer_type {}; skipping.",
             uint32_t(pp_result.index_buffer_type));
      assert_always();
      RecordDrawSkip(MetalDrawSkipReason::kInternalInvariant,
                     "pp-index-type");
      return true;
    }
  } else if (index_buffer_info && index_buffer_info->guest_base) {
    uint32_t index_size =
        index_buffer_info->format == xenos::IndexFormat::kInt32 ? 4 : 2;
    const void* guest_indices =
        TranslateGuest<const uint8_t*>(index_buffer_info->guest_base);
    if (!guest_indices) {
      RecordDrawSkip(MetalDrawSkipReason::kInvalidGuestState,
                     "dma-index-guest-null");
      return true;
    }
    uint32_t host_index_count = index_count;
    MetalUploadAllocation index_alloc{};
    if (point_strip_route) {
      // Point list -> two-triangle strips: every guest index g becomes the
      // 32-bit host indices 4g+0..4g+3 and a strip restart (the vertex shader
      // recovers g = SV_VertexID >> 2 and the corner from the low 2 bits).
      // Guest indices are swapped in cached stack chunks; the arena is
      // write-combined and never read back.
      if (!index_count) {
        RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                       "point-degenerate");
        return true;
      }
      host_index_count = index_count * 5;
      if (!ArenaAllocate(host_index_count * 4, 16, &index_alloc)) {
        RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                       "point-index-alloc");
        return true;
      }
      auto expand = [&](auto* src) {
        using T = std::remove_const_t<std::remove_pointer_t<decltype(src)>>;
        constexpr uint32_t kChunkPoints = 256;
        T chunk[kChunkPoints];
        uint32_t* dst = static_cast<uint32_t*>(index_alloc.cpu_ptr);
        for (uint32_t p0 = 0; p0 < index_count; p0 += kChunkPoints) {
          const uint32_t n = std::min(kChunkPoints, index_count - p0);
          SwapIndicesInto(chunk, src + p0, n, index_buffer_info->format,
                          index_buffer_info->endianness);
          for (uint32_t p = 0; p < n; ++p) {
            const uint32_t base = uint32_t(chunk[p]) * 4u;
            uint32_t* o = dst + size_t(p0 + p) * 5;
            o[0] = base;
            o[1] = base + 1;
            o[2] = base + 2;
            o[3] = base + 3;
            o[4] = UINT32_MAX;
          }
        }
      };
      if (index_size == 4) {
        expand(static_cast<const uint32_t*>(guest_indices));
      } else {
        expand(static_cast<const uint16_t*>(guest_indices));
      }
      index_size = 4;
      mtl_prim = MTLPrimitiveTypeTriangleStrip;
    } else if (dma_quad_route) {
      // Quad list -> triangle list: (0,1,2),(0,2,3) per quad. The arena is
      // write-combined, so never read it back: swap guest indices in cached
      // stack chunks and only write the expanded triangles to the arena.
      const uint32_t quads = index_count / 4;
      host_index_count = quads * 6;
      if (!host_index_count) {
        RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                       "quad-degenerate");
        return true;
      }
      if (!ArenaAllocate(host_index_count * index_size, 16,
                                   &index_alloc)) {
        RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                       "quad-index-alloc");
        return true;
      }
      auto expand = [&](auto* src, auto* dst) {
        using T = std::remove_const_t<std::remove_pointer_t<decltype(src)>>;
        constexpr uint32_t kChunkQuads = 256;
        T chunk[kChunkQuads * 4];
        for (uint32_t q0 = 0; q0 < quads; q0 += kChunkQuads) {
          const uint32_t n = std::min(kChunkQuads, quads - q0);
          SwapIndicesInto(chunk, src + q0 * 4, n * 4,
                          index_buffer_info->format,
                          index_buffer_info->endianness);
          for (uint32_t q = 0; q < n; ++q) {
            const T* v = chunk + q * 4;
            T* o = dst + (q0 + q) * 6;
            o[0] = v[0]; o[1] = v[1]; o[2] = v[2];
            o[3] = v[0]; o[4] = v[2]; o[5] = v[3];
          }
        }
      };
      if (index_size == 4) {
        expand(static_cast<const uint32_t*>(guest_indices),
               static_cast<uint32_t*>(index_alloc.cpu_ptr));
      } else {
        expand(static_cast<const uint16_t*>(guest_indices),
               static_cast<uint16_t*>(index_alloc.cpu_ptr));
      }
      mtl_prim = MTLPrimitiveTypeTriangle;
    } else if (dma_line_loop_route) {
      // Line loop -> line strip: the guest indices, then the first again to
      // close the loop. The closing index is swapped from guest RAM, never
      // read back from the write-combined arena.
      if (index_count < 2) {
        RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                       "line-loop-degenerate");
        return true;
      }
      host_index_count = index_count + 1;
      if (!ArenaAllocate(host_index_count * index_size, 16,
                                   &index_alloc)) {
        RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                       "line-loop-index-alloc");
        return true;
      }
      SwapIndicesInto(index_alloc.cpu_ptr, guest_indices, index_count,
                      index_buffer_info->format,
                      index_buffer_info->endianness);
      SwapIndicesInto(static_cast<uint8_t*>(index_alloc.cpu_ptr) +
                          size_t(index_count) * index_size,
                      guest_indices, 1, index_buffer_info->format,
                      index_buffer_info->endianness);
      mtl_prim = MTLPrimitiveTypeLineStrip;
    } else {
      if (!ArenaAllocate(index_count * index_size, 16,
                                   &index_alloc)) {
        RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                       "dma-index-alloc");
        return true;
      }
      SwapIndicesInto(index_alloc.cpu_ptr, guest_indices, index_count,
                      index_buffer_info->format,
                      index_buffer_info->endianness);
    }
    __unsafe_unretained id<MTLBuffer> index_buffer = (__bridge id<MTLBuffer>)index_alloc.buffer;
    use_resource(index_buffer, MTLResourceUsageRead);
    MTLIndexType index_type = index_size == 4 ? MTLIndexTypeUInt32
                                              : MTLIndexTypeUInt16;
    ir_draw_indexed( mtl_prim, host_index_count,
                                   index_type, index_buffer, index_alloc.offset,
                                   /*instanceCount=*/1, /*baseVertex=*/0,
                                   /*baseInstance=*/0);
  } else if (point_strip_route) {
    // Auto-indexed point list -> two-triangle strips: host indices
    // 4p+0..4p+3 and a strip restart per guest point p (see the DMA branch).
    if (!index_count) {
      RecordDrawSkip(MetalDrawSkipReason::kExpectedNoEffect,
                     "point-degenerate");
      return true;
    }
    const uint32_t host_index_count = index_count * 5;
    MetalUploadAllocation index_alloc{};
    if (!ArenaAllocate(host_index_count * 4, 16, &index_alloc)) {
      RecordDrawSkip(MetalDrawSkipReason::kResourceFailure,
                     "point-index-alloc");
      return true;
    }
    uint32_t* dst = static_cast<uint32_t*>(index_alloc.cpu_ptr);
    for (uint32_t p = 0; p < index_count; ++p) {
      uint32_t* o = dst + size_t(p) * 5;
      o[0] = p * 4u;
      o[1] = p * 4u + 1;
      o[2] = p * 4u + 2;
      o[3] = p * 4u + 3;
      o[4] = UINT32_MAX;
    }
    __unsafe_unretained id<MTLBuffer> index_buffer =
        (__bridge id<MTLBuffer>)index_alloc.buffer;
    use_resource(index_buffer, MTLResourceUsageRead);
    ir_draw_indexed( MTLPrimitiveTypeTriangleStrip,
                                   host_index_count, MTLIndexTypeUInt32,
                                   index_buffer, index_alloc.offset,
                                   /*instanceCount=*/1, /*baseVertex=*/0,
                                   /*baseInstance=*/0);
  } else {
    ir_draw( mtl_prim, /*vertexStart=*/uint64_t(0),
                            uint64_t(index_count));
  }

  mark_raster_targets_written();

  if (memexport_draw || memexport_raster_routed) {
    // The exports now exist (GPU-ordered) in the shared-memory buffer. Mark
    // the ranges GPU-written (watches + stale-texture invalidation, and so
    // later RequestRange calls don't upload stale CPU RAM over them) and
    // queue the RAM drain for when this submission completes.
    publish_memexport_ranges();
  }

  frame_has_render_ = true;
  ++draw_count_;
  ++draws_since_commit_;
  // Every 65,536 draws: at 5,000-7,500 draws per frame the former 2,000
  // cadence was 2-4 lines per frame (GTA IV: 37k lines in a 7-minute run,
  // one of several per-frame info lines whose formatting was ~2% of the
  // command-processor thread in the 2026-10-17 line profile).
  if (draw_count_ == 1 || (draw_count_ & 0xFFFFu) == 0) {
    REXLOG_INFO("MetalCommandProcessor: encoded draw #{} (prim {}, {} indices, {})",
           draw_count_, uint32_t(prim_type), index_count,
           index_buffer_info ? "indexed" : "auto");
  }
  // Diagnostic: XE_METAL_DUMP_DEPTH=<trace draw index> dumps the bound depth
  // texture (D32F) to /tmp/xe_depth_<index>.ppm as sqrt-toned grayscale right
  // after that draw encodes — splits "depth VALUES wrong" from "the d2c
  // reinterpret scrambles correct values" (smooth image = values fine).
  static const int64_t s_dump_depth_at = [] {
    const char* v = std::getenv("XE_METAL_DUMP_DEPTH");
    return v ? strtoll(v, nullptr, 10) : -1ll;
  }();
  if (s_dump_depth_at >= 0 && int64_t(trace_draw_index_) - 1 == s_dump_depth_at) {
    EndFrameEncoderAndWait(metal::SeamBoundaryReason::kDebugProbe);
    void* dt_ptr = render_target_cache_->current_depth_texture();
    REXLOG_WARN("XE_METAL_DUMP_DEPTH: probe at draw {} depth_texture={}",
           s_dump_depth_at, dt_ptr != nullptr);
    if (dt_ptr) {
      __unsafe_unretained id<MTLTexture> dt = (__bridge id<MTLTexture>)dt_ptr;
      uint32_t tw = uint32_t(dt.width), th = uint32_t(dt.height);
      id<MTLBuffer> rb =
          [dt.device newBufferWithLength:size_t(tw) * th * 4
                                 options:MTLResourceStorageModeShared];
      __unsafe_unretained id<MTLCommandQueue> dq = (__bridge id<MTLCommandQueue>)
          static_cast<rex::ui::metal::MetalProvider*>(
              GetGraphicsDriver().GetProvider())->command_queue();
      if (rb && dq) {
        id<MTLCommandBuffer> dcb = [dq commandBuffer];
        id<MTLBlitCommandEncoder> dbl = [dcb blitCommandEncoder];
        [dbl copyFromTexture:dt
                  sourceSlice:0
                  sourceLevel:0
                 sourceOrigin:MTLOriginMake(0, 0, 0)
                   sourceSize:MTLSizeMake(tw, th, 1)
                     toBuffer:rb
            destinationOffset:0
       destinationBytesPerRow:tw * 4
     destinationBytesPerImage:size_t(tw) * th * 4];
        [dbl endEncoding];
        [dcb commit];
        [dcb waitUntilCompleted];
        {
          // Raw float32 companion for exact-value comparisons.
          std::string raw_path =
              fmt::format("/tmp/xe_depth_{}.f32", s_dump_depth_at);
          FILE* rf = fopen(raw_path.c_str(), "wb");
          if (rf) {
            fwrite(rb.contents, 4, size_t(tw) * th, rf);
            fclose(rf);
          }
        }
        std::string path = fmt::format("/tmp/xe_depth_{}.ppm", s_dump_depth_at);
        FILE* f = fopen(path.c_str(), "wb");
        if (f) {
          fprintf(f, "P6\n%u %u\n255\n", tw, th);
          const float* px = static_cast<const float*>(rb.contents);
          for (size_t i = 0; i < size_t(tw) * th; ++i) {
            float v = px[i];
            v = v < 0.f ? 0.f : (v > 1.f ? 1.f : v);
            uint8_t g = uint8_t(std::sqrt(v) * 255.f + 0.5f);
            uint8_t rgb[3] = {g, g, g};
            fwrite(rgb, 1, 3, f);
          }
          fclose(f);
          REXLOG_WARN("XE_METAL_DUMP_DEPTH: wrote {} ({}x{})", path, tw, th);
        }
      }
    }
  }
  return true;
}

static MTLCompareFunction ToMetalCompareFunction(xenos::CompareFunction f) {
  switch (f) {
    case xenos::CompareFunction::kNever:
      return MTLCompareFunctionNever;
    case xenos::CompareFunction::kLess:
      return MTLCompareFunctionLess;
    case xenos::CompareFunction::kEqual:
      return MTLCompareFunctionEqual;
    case xenos::CompareFunction::kLessEqual:
      return MTLCompareFunctionLessEqual;
    case xenos::CompareFunction::kGreater:
      return MTLCompareFunctionGreater;
    case xenos::CompareFunction::kNotEqual:
      return MTLCompareFunctionNotEqual;
    case xenos::CompareFunction::kGreaterEqual:
      return MTLCompareFunctionGreaterEqual;
    default:
      return MTLCompareFunctionAlways;
  }
}

static MTLStencilOperation ToMetalStencilOperation(xenos::StencilOp op) {
  switch (op) {
    case xenos::StencilOp::kKeep:
      return MTLStencilOperationKeep;
    case xenos::StencilOp::kZero:
      return MTLStencilOperationZero;
    case xenos::StencilOp::kReplace:
      return MTLStencilOperationReplace;
    case xenos::StencilOp::kIncrementClamp:
      return MTLStencilOperationIncrementClamp;
    case xenos::StencilOp::kDecrementClamp:
      return MTLStencilOperationDecrementClamp;
    case xenos::StencilOp::kInvert:
      return MTLStencilOperationInvert;
    case xenos::StencilOp::kIncrementWrap:
      return MTLStencilOperationIncrementWrap;
    case xenos::StencilOp::kDecrementWrap:
      return MTLStencilOperationDecrementWrap;
    default:
      return MTLStencilOperationKeep;
  }
}

// Builds (and caches) an MTLDepthStencilState from RB_DEPTHCONTROL plus the
// read/write masks of RB_STENCILREFMASK(_BF). The stencil REFERENCE is encoder
// state (setStencilReferenceValue at the draw), not part of this object. When
// depth test is disabled the state passes everything and writes nothing.
void* MetalCommandProcessor::GetOrCreateDepthStencilState(
    uint32_t depth_control, uint32_t stencil_ref_mask,
    uint32_t stencil_ref_mask_bf) {
  reg::RB_DEPTHCONTROL dc;
  dc.value = depth_control;
  reg::RB_STENCILREFMASK srm;
  srm.value = stencil_ref_mask;
  reg::RB_STENCILREFMASK srm_bf;
  srm_bf.value = dc.backface_enable ? stencil_ref_mask_bf : stencil_ref_mask;
  uint32_t masks = 0;
  if (dc.stencil_enable) {
    masks = (srm.stencilmask) | (srm.stencilwritemask << 8) |
            (srm_bf.stencilmask << 16) | (srm_bf.stencilwritemask << 24);
  }
  // Depth bits + all stencil fields of RB_DEPTHCONTROL + the masks.
  uint64_t key =
      (uint64_t(masks) << 32) |
      (dc.value & ~0x8u);  // bit 3 is unused padding on Xenos.
  auto it = depth_stencil_states_.find(key);
  if (it != depth_stencil_states_.end()) {
    return it->second;
  }
  auto* provider =
      static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider());
  if (!provider) {
    return nullptr;
  }
  id<MTLDevice> device = (__bridge id<MTLDevice>)provider->device();
  MTLDepthStencilDescriptor* desc = [[MTLDepthStencilDescriptor alloc] init];
  desc.depthCompareFunction = dc.z_enable
                                  ? ToMetalCompareFunction(dc.zfunc)
                                  : MTLCompareFunctionAlways;
  // Diagnostic (Sonic black-sky task 3.4): XE_METAL_NO_DEPTH_TEST=1 forces
  // the depth compare to ALWAYS (writes unchanged) so missing coverage can
  // be attributed to a depth-test failure against the host attachment.
  static const bool s_no_depth_test =
      std::getenv("XE_METAL_NO_DEPTH_TEST") != nullptr;
  if (s_no_depth_test) {
    desc.depthCompareFunction = MTLCompareFunctionAlways;
  }
  // Diagnostic (2026-09-19, Gears of War 3 occlusion): XE_METAL_ZFUNC_INVERT=1
  // maps GEQUAL to LESS (and vice versa) so a zero-count query can be split
  // into "fragment depth below the buffer" vs "compare never passes (NaN)".
  static const bool s_zfunc_invert =
      std::getenv("XE_METAL_ZFUNC_INVERT") != nullptr;
  if (s_zfunc_invert && dc.z_enable) {
    if (dc.zfunc == xenos::CompareFunction::kGreaterEqual) {
      desc.depthCompareFunction = MTLCompareFunctionLess;
    } else if (dc.zfunc == xenos::CompareFunction::kLess) {
      desc.depthCompareFunction = MTLCompareFunctionGreaterEqual;
    }
  }
  desc.depthWriteEnabled = dc.z_enable && dc.z_write_enable;
  // Diagnostic: XE_METAL_FORCE_ZWRITE=1 writes depth on every depth-enabled
  // draw so a depth-only draw's exported values can be dumped.
  static const bool s_force_zwrite =
      std::getenv("XE_METAL_FORCE_ZWRITE") != nullptr;
  if (s_force_zwrite && dc.z_enable) {
    desc.depthWriteEnabled = true;
  }
  {
    static const bool s_ds_log = std::getenv("XE_METAL_DEPTHSTATE_LOG") != nullptr;
    static uint32_t s_ds_logs = 0;
    if (s_ds_log && s_ds_logs < 64) {
      ++s_ds_logs;
      REXLOG_WARN("MetalDepthState draw={} z_enable={} zfunc={} z_write={} "
             "stencil={} -> compare={} write={}",
             trace_draw_index_, uint32_t(dc.z_enable), uint32_t(dc.zfunc),
             uint32_t(dc.z_write_enable), uint32_t(dc.stencil_enable),
             uint32_t(desc.depthCompareFunction),
             uint32_t(desc.depthWriteEnabled));
    }
  }
  if (dc.stencil_enable) {
    MTLStencilDescriptor* front = [[MTLStencilDescriptor alloc] init];
    front.stencilCompareFunction = ToMetalCompareFunction(dc.stencilfunc);
    front.stencilFailureOperation = ToMetalStencilOperation(dc.stencilfail);
    front.depthStencilPassOperation =
        ToMetalStencilOperation(dc.stencilzpass);
    front.depthFailureOperation = ToMetalStencilOperation(dc.stencilzfail);
    front.readMask = srm.stencilmask;
    front.writeMask = srm.stencilwritemask;
    desc.frontFaceStencil = front;
    MTLStencilDescriptor* back = [[MTLStencilDescriptor alloc] init];
    if (dc.backface_enable) {
      back.stencilCompareFunction = ToMetalCompareFunction(dc.stencilfunc_bf);
      back.stencilFailureOperation =
          ToMetalStencilOperation(dc.stencilfail_bf);
      back.depthStencilPassOperation =
          ToMetalStencilOperation(dc.stencilzpass_bf);
      back.depthFailureOperation =
          ToMetalStencilOperation(dc.stencilzfail_bf);
    } else {
      back.stencilCompareFunction = front.stencilCompareFunction;
      back.stencilFailureOperation = front.stencilFailureOperation;
      back.depthStencilPassOperation = front.depthStencilPassOperation;
      back.depthFailureOperation = front.depthFailureOperation;
    }
    back.readMask = srm_bf.stencilmask;
    back.writeMask = srm_bf.stencilwritemask;
    desc.backFaceStencil = back;
  }
  id<MTLDepthStencilState> state =
      [device newDepthStencilStateWithDescriptor:desc];
  void* state_ptr = (__bridge_retained void*)state;
  depth_stencil_states_.emplace(key, state_ptr);
  return state_ptr;
}

bool MetalCommandProcessor::ConvertDepthToSnapshot(void* depth_texture,
                                                   void* dest_snapshot,
                                                   uint32_t width,
                                                   uint32_t height,
                                                   uint32_t dest_y_offset) {
  if (!frame_command_buffer_) {
    return false;
  }
  auto* provider =
      static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider());
  if (!provider) {
    return false;
  }
  id<MTLDevice> device = (__bridge id<MTLDevice>)provider->device();
  if (!depth_convert_pipeline_) {
    // Exact per-pixel read (snapshot pixel (x,y) == depth-texture pixel (x,y)):
    // the depth texture (1280x1024, shadow-map-capable) is LARGER than most
    // snapshots (1280x720 scene), so normalized-uv sampling squashed the whole
    // texture into the snapshot; and a presenter-style Y-flip mirrored depth
    // vertically relative to the (unflipped, blit-copied) color snapshots —
    // together feeding deferred lighting wrong positions everywhere.
    NSString* src = @R"METAL(
      #include <metal_stdlib>
      using namespace metal;
      struct VOut { float4 pos [[position]]; };
      vertex VOut xe_depth_convert_vs(uint vid [[vertex_id]]) {
        VOut o;
        float2 t = float2(float((vid << 1) & 2), float(vid & 2));
        o.pos = float4(t * 2.0 - 1.0, 0.0, 1.0);
        return o;
      }
      fragment float xe_depth_convert_fs(VOut in [[stage_in]],
                                         depth2d<float> d [[texture(0)]]) {
        return d.read(uint2(in.pos.xy));
      }
    )METAL";
    NSError* err = nil;
    id<MTLLibrary> lib = [device newLibraryWithSource:src options:nil error:&err];
    if (!lib) {
      REXLOG_ERROR("MetalCommandProcessor: depth-convert library failed: {}",
             err ? err.localizedDescription.UTF8String : "?");
      return false;
    }
    MTLRenderPipelineDescriptor* d = [[MTLRenderPipelineDescriptor alloc] init];
    d.vertexFunction = [lib newFunctionWithName:@"xe_depth_convert_vs"];
    d.fragmentFunction = [lib newFunctionWithName:@"xe_depth_convert_fs"];
    d.colorAttachments[0].pixelFormat = MTLPixelFormatR32Float;
    id<MTLRenderPipelineState> ps =
        [device newRenderPipelineStateWithDescriptor:d error:&err];
    if (!ps) {
      REXLOG_ERROR("MetalCommandProcessor: depth-convert pipeline failed: {}",
             err ? err.localizedDescription.UTF8String : "?");
      return false;
    }
    depth_convert_pipeline_ = (__bridge_retained void*)ps;
  }
  id<MTLCommandBuffer> cb = (__bridge id<MTLCommandBuffer>)frame_command_buffer_;
  MTLRenderPassDescriptor* pass = [MTLRenderPassDescriptor renderPassDescriptor];
  pass.colorAttachments[0].texture = (__bridge id<MTLTexture>)dest_snapshot;
  pass.colorAttachments[0].slice = 0;
  // Load, not DontCare: a multi-strip resolve converts into a SUB-RECT of a
  // full-height snapshot (dest_y_offset), and the other strip's rows must
  // survive this pass.
  pass.colorAttachments[0].loadAction = MTLLoadActionLoad;
  pass.colorAttachments[0].storeAction = MTLStoreActionStore;
  id<MTLRenderCommandEncoder> encoder =
      [cb renderCommandEncoderWithDescriptor:metal::MetalApplyXenosSamplePositions(pass)];
  encoder.label = @"cp:depth-convert-snapshot";
  [encoder setRenderPipelineState:(__bridge id<MTLRenderPipelineState>)
                                      depth_convert_pipeline_];
  // The viewport clips the fullscreen triangle to the strip's rows; the FS
  // reads the depth texture at the destination pixel coordinate, so source and
  // destination rows align automatically (both are frame-absolute).
  MTLViewport vp{0.0, double(dest_y_offset), double(width), double(height), 0.0,
                 1.0};
  [encoder setViewport:vp];
  [encoder setFragmentTexture:(__bridge id<MTLTexture>)depth_texture atIndex:0];
  [encoder drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3];
  [encoder endEncoding];
  return true;
}

// IssueCopy's diagnostic log switches, read once: getenv on every resolve
// showed in the CP-thread profile (GTA IV on the Mac Pro).
static bool IssueCopyWbGateLog() {
  static const bool s_enabled = std::getenv("XE_METAL_WB_GATE_LOG") != nullptr;
  return s_enabled;
}
static bool IssueCopyGpuResolveLog() {
  static const bool s_enabled =
      std::getenv("XE_METAL_GPU_RESOLVE_LOG") != nullptr;
  return s_enabled;
}
static bool IssueCopyResolveForwardLog() {
  static const bool s_enabled =
      std::getenv("XE_METAL_RESOLVE_FORWARD_LOG") != nullptr;
  return s_enabled;
}
static bool IssueCopyCanonicalSyncLog() {
  static const bool s_enabled =
      std::getenv("XE_METAL_CANONICAL_SYNC_LOG") != nullptr;
  return s_enabled;
}

bool MetalCommandProcessor::IssueCopy() {
  // First slice of the EDRAM->guest resolve (the gameplay gray-screen blocker):
  // decode the resolve with the reusable draw_util helper and record the guest
  // destination base so the texture cache can bridge it to our color RT. No data
  // is copied yet -- this pass logs what JC2 resolves so the RT-as-texture bridge
  // can be built against real addresses/formats.
  // GetResolveInfo decodes the resolve rectangle from vf0 on the host. The
  // D3D9 convention says the CPU normally writes these vertices, but the
  // authority contract must cover the factual address rather than assume its
  // writer. Resolve an aliased pending producer before the host dereference.
  xenos::VertexFetch resolve_fetch =
      register_file_->GetVertexFetch(0);
  if (resolve_fetch.type == xenos::FetchConstantType::kVertex &&
      resolve_fetch.size == 3 * 2) {
    uint32_t resolve_vertices_address =
        xenos::CpuToGpu(resolve_fetch.address * sizeof(uint32_t));
    if (!PrepareGuestMemoryForHostRead(
            resolve_vertices_address,
            resolve_fetch.size * sizeof(uint32_t))) {
      REXLOG_ERROR(
          "MetalCommandProcessor: failed to converge resolve vf0 {:08X}+{}",
          resolve_vertices_address,
          resolve_fetch.size * uint32_t(sizeof(uint32_t)));
      return false;
    }
  }

  draw_util::ResolveInfo resolve_info;
  if (!draw_util::GetResolveInfo(GetXenosSettings(), *register_file_, physical_memory_,
                                 draw_resolution_scale_x_,
                                 draw_resolution_scale_y_,
                                 /*fixed_rg16_truncated_to_minus_1_to_1=*/false,
                                 /*fixed_rgba16_truncated_to_minus_1_to_1=*/false,
                                 resolve_info)) {
    return true;
  }
  // Copy command 2 (compare to k_DXT3A_AS_1_1_1_1) exists only as the shared
  // resolve shader, and the Metal copy routes below do not know it: they would
  // copy the color as-is. Skip the copy but still perform the clears, as
  // Canary does when it can't run that shader (resolution scaling).
  if (resolve_info.rb_copy_control.copy_command ==
      xenos::CopyCommand::kConstantOne) {  // command 2: the DXT3A as 1_1_1_1 comparison
    static uint32_t s_convert_1111_logs = 0;
    if (s_convert_1111_logs++ < 4) {
      REXLOG_WARN("Metal: resolve copy command 2 (DXT3A as 1_1_1_1) copy skipped");
    }
    resolve_info.copy_dest_extent_length = 0;
  }
  // CEILING PROBE (re5-perf-20261015): XE_METAL_PROBE_SKIP_SMALL_RESOLVE=<bytes>
  // skips (copy AND clear) every resolve whose destination extent is at most
  // that many bytes -- RE5's ~77 cube-face/mip resolves per frame (4-64 KB
  // each) cost ~4 ms of per-op GPU overhead. Measurement only; never default.
  static const uint32_t s_probe_skip_small_resolve = [] {
    const char* v = std::getenv("XE_METAL_PROBE_SKIP_SMALL_RESOLVE");
    return v ? uint32_t(strtoul(v, nullptr, 10)) : 0u;
  }();
  if (s_probe_skip_small_resolve && resolve_info.copy_dest_extent_length &&
      resolve_info.copy_dest_extent_length <= s_probe_skip_small_resolve) {
    return true;
  }
  {
    // Upstream-delta census (2026-10-09): depth resolved out of a
    // multisampled surface (Canary cc4981a46: tiled MSAA titles resolve
    // sample 0 depth and test against it again).
    static const bool s_resolve_census =
        std::getenv("XE_GPU_DELTA_CENSUS") != nullptr;
    if (s_resolve_census && resolve_info.IsCopyingDepth() &&
        resolve_info.depth_edram_info.msaa_samples !=
            xenos::MSAASamples::k1X) {
      uint64_t n = DeltaCensusKeyedCount(
          5, uint64_t(resolve_info.depth_edram_info.msaa_samples) |
                 (uint64_t(resolve_info.copy_dest_coordinate_info
                               .copy_sample_select)
                  << 4));
      if (DeltaCensusLogCount(n)) {
        REXLOG_INFO(
            "DeltaCensus msaa_depth_resolve samples={} sample_select={} "
            "dest={:08X} count={}",
            1u << uint32_t(resolve_info.depth_edram_info.msaa_samples),
            uint32_t(resolve_info.copy_dest_coordinate_info.copy_sample_select),
            resolve_info.copy_dest_base, n);
      }
    }
  }
  if (ScaleCoverageCensusEnabled()) {
    metal::ScaleCoverageCensus::Get().RecordResolve(
        resolve_info.copy_dest_extent_start,
        resolve_info.copy_dest_extent_length);
  }
  // XE_METAL_RESOLVE_CLASS_CENSUS=1 (diagnostic, default off): resolves per
  // frame by class -- depth/color, EDRAM format, MSAA, destination format,
  // copy and clear, and whether the source span is an attachment of the open
  // render pass (the in-pass / from-attachment resolve candidates).
  static const bool s_resolve_class_census =
      std::getenv("XE_METAL_RESOLVE_CLASS_CENSUS") != nullptr;
  if (s_resolve_class_census && render_target_cache_) {
    struct ClassStat {
      uint64_t count = 0;
      uint64_t bytes = 0;
    };
    static std::map<uint64_t, ClassStat> s_classes;
    static uint32_t s_census_swap = 0;
    const bool depth = resolve_info.IsCopyingDepth();
    const draw_util::ResolveEdramInfo& edram =
        depth ? resolve_info.depth_edram_info : resolve_info.color_edram_info;
    uint32_t span_base, span_row_length, span_rows, span_pitch;
    resolve_info.GetCopyEDRAMTileSpan(span_base, span_row_length, span_rows, span_pitch);
    const bool open_attached = frame_open_ && frame_render_encoder_ &&
                               render_target_cache_->ResolveSpanTouchesCurrentAttachments(
                                   span_base, span_row_length, span_rows, span_pitch);
    const bool copies = resolve_info.copy_dest_extent_length != 0;
    const bool clears = resolve_info.IsClearingColor() || resolve_info.IsClearingDepth();
    const uint64_t key = uint64_t(depth) | (uint64_t(edram.format) << 1) |
                         (uint64_t(uint32_t(edram.msaa_samples)) << 6) |
                         (uint64_t(uint32_t(resolve_info.copy_dest_info.copy_dest_format)) << 8) |
                         (uint64_t(copies) << 16) | (uint64_t(clears) << 17) |
                         (uint64_t(open_attached) << 18) |
                         (uint64_t(copies && last_frontbuffer_bytes_ &&
                                   resolve_info.copy_dest_extent_start <
                                       last_frontbuffer_base_ + last_frontbuffer_bytes_ &&
                                   resolve_info.copy_dest_extent_start +
                                           resolve_info.copy_dest_extent_length >
                                       last_frontbuffer_base_)
                          << 19);
    ClassStat& stat = s_classes[key];
    ++stat.count;
    stat.bytes += resolve_info.copy_dest_extent_length;
    if (!s_census_swap) {
      s_census_swap = swap_count_;
    }
    const uint32_t frames = swap_count_ - s_census_swap;
    if (frames >= 128) {
      std::vector<std::pair<uint64_t, uint64_t>> ranked;
      for (const auto& [k, v] : s_classes) {
        ranked.emplace_back(v.count, k);
      }
      std::sort(ranked.rbegin(), ranked.rend());
      std::string out;
      for (size_t i = 0; i < ranked.size() && i < 14; ++i) {
        const uint64_t k = ranked[i].second;
        const ClassStat& v = s_classes[k];
        out += fmt::format(" [{} fmt={} msaa={} dst={}{}{}{}{} {:.1f}/f {:.0f}KB/f]",
                           (k & 1) ? "depth" : "color", (k >> 1) & 31, (k >> 6) & 3, (k >> 8) & 255,
                           ((k >> 16) & 1) ? " copy" : "", ((k >> 17) & 1) ? " clear" : "",
                           ((k >> 18) & 1) ? " open-attached" : "",
                           ((k >> 19) & 1) ? " FRONTBUFFER" : "", double(v.count) / frames,
                           double(v.bytes) / 1024.0 / frames);
      }
      REXLOG_INFO("MetalResolveClassCensus frames={}:{}", frames, out);
      s_classes.clear();
      s_census_swap = swap_count_;
    }
  }
  if (RcCensusEnabled() && resolve_info.copy_dest_extent_length) {
    RcCensusNoteResolve(resolve_info.copy_dest_extent_start,
                        resolve_info.copy_dest_extent_length, trace_draw_index_,
                        resolve_info.IsCopyingDepth());
  }
  // Commit encoded draws BEFORE processing the resolve (default-on;
  // XE_METAL_NO_RESOLVE_COMMIT=1 restores the old whole-frame buffer for A/B).
  // Found via the resolve-owner probe: sessions WITHOUT a submission boundary
  // here page-faulted 60-84x/session (the recurring 'draws@N' +
  // 'rtcache:resolve-color-snapshot' fault) and every faulted command buffer
  // DISCARDED its encoded work — scene color lost -> the black flicker bursts.
  // With the boundary: 0 faults, no flicker, ~4 commits/frame at an unchanged
  // 28.4 fps (measured live). This is also the XeniOS submission shape:
  // command buffers split at hazard boundaries.
  // LARGE resolves only: a boundary at EVERY resolve measured 39 commits/frame
  // -> 23.1 fps (-19%), while the proven-0-fault probe configuration bounded
  // only the scene-sized resolve. 1MB splits the scene G-buffers/frontbuffer
  // (1.9-3.7MB) from the pyramid/quarter chain (4-256KB).
  static const bool s_no_resolve_commit =
      std::getenv("XE_METAL_NO_RESOLVE_COMMIT") != nullptr;
  // A/B knobs (defaults = the behavior above): XE_METAL_RESOLVE_COMMIT_MIN_BYTES
  // moves the size threshold; XE_METAL_RESOLVE_COMMIT_MIN_DRAWS=N also commits
  // at any resolve once N draws are encoded (resolves already end the pass,
  // so this adds submissions without adding pass breaks; the GPU starts on
  // the frame sooner and the command processor waits less at the flip).
  static const uint32_t s_resolve_commit_min_bytes = [] {
    const char* v = std::getenv("XE_METAL_RESOLVE_COMMIT_MIN_BYTES");
    // 16 MiB, not the 1 MiB this started at: a 1152x640 colour resolve alone is 2.9 MB, so 1 MiB split the frame
    // at every scene resolve for no hazard. At 16 MiB the split still bounds a single oversized resolve but stops
    // firing on the ordinary ones - measured on Halo 3's loading screen, commits drop 13.7 -> 8.3 per frame with zero
    // faults over a minute, and no fps change in either direction.
    return v ? uint32_t(std::strtoul(v, nullptr, 10)) : 16u * 1024u * 1024u;
  }();
  static const uint32_t s_resolve_commit_min_draws = [] {
    const char* v = std::getenv("XE_METAL_RESOLVE_COMMIT_MIN_DRAWS");
    return v ? uint32_t(std::strtoul(v, nullptr, 10)) : 0u;
  }();
  if (!s_no_resolve_commit && draws_since_commit_ > 0 &&
      (resolve_info.copy_dest_extent_length >= s_resolve_commit_min_bytes ||
       (s_resolve_commit_min_draws &&
        draws_since_commit_ >= s_resolve_commit_min_draws))) {
    EndFrameEncoder(metal::SeamBoundaryReason::kResolveSizeSplit);
  }
  // CRITICAL: the resolve paths below all guard on frame_command_buffer_. If
  // the frame was committed (just above, or by a mid-frame hazard flush,
  // writeback wait, --serialize_draw_range), the buffer is NULL and every
  // resolve op would be SILENTLY SKIPPED — the consumer then samples a stale
  // or never-written snapshot (missing scene / transient black blips; found
  // by the draw-range bisect: one commit after the last scene draw dropped
  // the scene resolve and lost the whole frame). Recreate it up front.
  PrepareTransferCommandBuffer(uint32_t(metal::MetalTransferSite::kResolve));
  // RT-as-texture bridge. A color resolve is the boundary of a render pass: blit
  // what the pass drew into ITS color target (looked up by the resolve's EDRAM
  // base + format — the same key the draws bound it with) out into a
  // per-destination snapshot texture registered at the resolve's guest base, so
  // a later deferred / composite pass that fetches this base samples the real
  // rendered pixels (its guest RAM is never populated by our backend).
  if (!resolve_info.IsCopyingDepth() && resolve_info.copy_dest_extent_length) {
    last_color_resolve_base_ = resolve_info.copy_dest_base;
    last_color_resolve_start_ = resolve_info.copy_dest_extent_start;
    last_color_resolve_length_ = resolve_info.copy_dest_extent_length;

    uint32_t rw = uint32_t(resolve_info.coordinate_info.width_div_8) * 8;
    uint32_t rh = resolve_info.height_div_8 * 8;
    if (rw && rh && render_target_cache_ && texture_cache_ &&
        frame_command_buffer_) {
      // Close the current pass's encoder so its stores are visible to the blit,
      // then copy the color RT region into the snapshot on the frame command
      // buffer (Metal orders the blit after the render encoder and before the
      // later composite encoder that samples the snapshot).
      uint32_t span_base, span_row_length, span_rows, span_pitch;
      resolve_info.GetCopyEDRAMTileSpan(span_base, span_row_length, span_rows,
                                        span_pitch);
      EndRenderEncoder(
          metal::MetalPassEndReason::kColorResolve, 0,
          frame_open_ && render_target_cache_->ResolveSpanTouchesCurrentAttachments(
                             span_base, span_row_length, span_rows, span_pitch));
      // Ownership truth: ask the base class which render target owns the
      // resolve's EDRAM tiles. The snapshot's pixel format mirrors the
      // source's so the blit is format-compatible.
      // The snapshot format mirrors the first color owner's; the copy itself is
      // per-owner + per-tile with FULL layout remapping (owner pitch vs the
      // resolve's linear span -- a naive rect blit scrambles any owner whose
      // pitch differs, e.g. 4x-MSAA keys twice as wide). Strips coalesce like
      // depth (the guest splits 720p buffers into adjacent strip resolves).
      uint64_t src_pixel_format = 0;
      void* probe = render_target_cache_->GetResolveSourceTexture(
          span_base, span_row_length, span_rows, span_pitch, /*is_depth=*/false,
          &src_pixel_format);
      const bool canonical_resolve =
          render_target_cache_->sample_edram_raster_enabled();
      if (probe || canonical_resolve) {
        // Diagnostic: XE_METAL_PROBE_RESOLVE=<hex dest base> reads back the
        // OWNER texture's top-left region at resolve time (forces a mid-frame
        // commit) — splits "the producing draw rendered zero" from "the
        // resolve remap reads the wrong place".
        static const char* s_probe_resolve =
            std::getenv("XE_METAL_PROBE_RESOLVE");
        if (probe && s_probe_resolve &&
            uint32_t(strtoul(s_probe_resolve, nullptr, 16)) ==
                resolve_info.copy_dest_base) {
          EndFrameEncoderAndWait(metal::SeamBoundaryReason::kDebugProbe);
          PrepareTransferCommandBuffer(uint32_t(metal::MetalTransferSite::kResolve));
          id<MTLTexture> owner_tex = (__bridge id<MTLTexture>)probe;
          uint32_t pw = std::min<uint32_t>(uint32_t(owner_tex.width), 64);
          id<MTLBuffer> pstage =
              [owner_tex.device newBufferWithLength:pw * 4 * 4
                                            options:MTLResourceStorageModeShared];
          if (pstage) {
            id<MTLCommandQueue> pq =
                (__bridge id<MTLCommandQueue>)static_cast<rex::ui::metal::MetalProvider*>(
                    GetGraphicsDriver().GetProvider())->command_queue();
            id<MTLCommandBuffer> pcb = [pq commandBuffer];
            id<MTLBlitCommandEncoder> pbl = [pcb blitCommandEncoder];
            [pbl copyFromTexture:owner_tex
                      sourceSlice:0
                      sourceLevel:0
                     sourceOrigin:MTLOriginMake(0, 0, 0)
                       sourceSize:MTLSizeMake(pw, 4, 1)
                         toBuffer:pstage
                destinationOffset:0
           destinationBytesPerRow:pw * 4
         destinationBytesPerImage:pw * 4 * 4];
            [pbl endEncoding];
            [pcb commit];
            [pcb waitUntilCompleted];
            const uint32_t* w = static_cast<const uint32_t*>(pstage.contents);
            REXLOG_WARN(
                "MetalProbeResolve {:08X}: owner {}x{} row0 {:08X} {:08X} "
                "{:08X} {:08X} row2 {:08X} {:08X}",
                resolve_info.copy_dest_base, uint32_t(owner_tex.width),
                uint32_t(owner_tex.height), w[0], w[1], w[8], w[32],
                w[pw * 2], w[pw * 2 + 8]);
          }
        }
        // Honor the GUEST's copy_dest_format: the Xenos resolve CONVERTS. The
        // auto-exposure luminance pyramid resolves k_8_8_8_8 EDRAM into
        // k_32_FLOAT (fmt 36) textures the game (and the next pyramid level)
        // reads as f32 — registering a BGRA8-content snapshot instead made
        // consumers decode BGRA8 bytes as floats (denormals ≈ 0): pyramid
        // levels 2+ rendered genuinely black and the CPU exposure loop read
        // ~0 (the black flicker/darkness). R32Float attachments keep .r of
        // the sampled float4 — exactly the hardware's 8888→k_32_FLOAT rule.
        uint64_t dest_pixel_format = src_pixel_format;
        switch (resolve_info.copy_dest_info.copy_dest_format) {
          case xenos::ColorFormat::k_8_8_8_8:
          case xenos::ColorFormat::k_8_8_8_8_A:
          case xenos::ColorFormat::k_8_8_8_8_AS_16_16_16_16:
            dest_pixel_format = MetalRenderTargetCache::kColorFormat;
            break;
          case xenos::ColorFormat::k_16_16_FLOAT:
            dest_pixel_format = uint64_t(MTLPixelFormatRG16Float);
            break;
          case xenos::ColorFormat::k_16_16_16_16_FLOAT:
            dest_pixel_format = uint64_t(MTLPixelFormatRGBA16Float);
            break;
          case xenos::ColorFormat::k_32_FLOAT:
            dest_pixel_format = uint64_t(MTLPixelFormatR32Float);
            break;
          default:
            break;
        }
        uint32_t strip_y_offset = 0;
        void* parent_snap = render_target_cache_->FindContainingSnapshot(
            resolve_info.copy_dest_base, dest_pixel_format, &strip_y_offset);
        // Half-pass placement audit (XE_METAL_RESOLVE_LOG=1): the guest splits
        // 720p into EDRAM-capacity halves; each half's resolve must land at
        // its own dest rows. Log the raw placement inputs for big resolves.
        static const bool s_resolve_log =
            std::getenv("XE_METAL_RESOLVE_LOG") != nullptr;
        // XE_METAL_RESOLVE_LOG=2: log ALL color resolves (incl. small mips).
        static const bool s_resolve_log_all = [] {
          const char* v = std::getenv("XE_METAL_RESOLVE_LOG");
          return v && v[0] == '2';
        }();
        if ((s_resolve_log && rw * rh * 4 >= 1024 * 1024) ||
            s_resolve_log_all) {
          REXLOG_WARN(
              "MetalResolve @draw {}: dest base={:08X} extent=[{:08X},+{}] "
              "rect={}x{} edram_base={} pitch={} msaa={} sample={} dest_pitch={} "
              "off_x={} off_y={} dest_fmt={} swap={} endian={} exp_bias={} "
              "parent={} strip_y={}",
              trace_draw_index_, resolve_info.copy_dest_base,
              resolve_info.copy_dest_extent_start,
              resolve_info.copy_dest_extent_length, rw, rh,
              uint32_t(resolve_info.color_edram_info.base_tiles),
              uint32_t(resolve_info.color_edram_info.pitch_tiles),
              uint32_t(resolve_info.color_edram_info.msaa_samples),
              uint32_t(resolve_info.copy_dest_coordinate_info
                           .copy_sample_select),
              uint32_t(resolve_info.copy_dest_coordinate_info.pitch_aligned_div_32)
                  * 32,
              uint32_t(resolve_info.copy_dest_coordinate_info.offset_x_div_8)
                  * 8,
              uint32_t(resolve_info.copy_dest_coordinate_info.offset_y_div_8)
                  * 8,
              uint32_t(resolve_info.copy_dest_info.copy_dest_format),
              uint32_t(resolve_info.copy_dest_info.copy_dest_swap),
              uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
              int32_t(resolve_info.copy_dest_info.copy_dest_exp_bias),
              parent_snap != nullptr, strip_y_offset);
        }
        // The strip's rows start at its destination offset below the
        // adjusted base: draw_util aligns copy_dest_base down to a 32-row
        // tile row and leaves the rest in offset_y (Tiger Woods PGA Tour 06
        // tiles 720p 4x as 240-row strips; the middle one lands at base row
        // 224 with offset 16 and joined at 224, so rows 464-479 stayed
        // stale). An x offset is not a vertical strip: no join.
        if (parent_snap &&
            !ApplyStripJoinDestOffset(resolve_info, strip_y_offset)) {
          parent_snap = nullptr;
          strip_y_offset = 0;
        }
        // A resolve must NEVER join a parent strip of a different format:
        // "render in the snapshot's REAL format" would silently skip the
        // guest-requested conversion. JC2 exposed this first with an
        // 8888->float luminance resolve whose raw color bytes were consumed
        // as floats; Red Dead adds the inverse HDR-float->8888 frontbuffer
        // case. Keep mixed-format destinations as independent snapshots.
        if (parent_snap &&
            uint64_t(((__bridge id<MTLTexture>)parent_snap).pixelFormat) !=
                dest_pixel_format) {
          parent_snap = nullptr;
          strip_y_offset = 0;
        }
        // A parent-strip join is only valid when the strip actually FITS:
        // same width, and the y range inside the parent texture. SF4's intro
        // double-buffers 1280-pitch column dests 0x11000 apart — the second
        // frame's 544x720 resolve "joined" the first frame's 544-wide
        // snapshot at strip_y=32 (69632/544/4 = exactly 32 rows), rendering
        // 720 rows into a 720-tall texture: the bottom 32 rows clipped and
        // the writeback blit read out of bounds -> stale bottom-of-column
        // bands live (the lower-right smear zones) and every-other-frame
        // ghosting. Reject the join; the resolve gets its own snapshot and
        // stage-3 RAM assembly handles placement.
        if (parent_snap) {
          // Snapshot textures are at the draw resolution scale; compare guest
          // pixels.
          id<MTLTexture> parent_tex = (__bridge id<MTLTexture>)parent_snap;
          if (rw != uint32_t(parent_tex.width) / draw_resolution_scale_x_ ||
              strip_y_offset + rh >
                  uint32_t(parent_tex.height) / draw_resolution_scale_y_) {
            parent_snap = nullptr;
            strip_y_offset = 0;
          }
        }
        void* snap = parent_snap;
        bool is_new_snapshot = false;
        // Colour snapshots are only read by presentation (the frontbuffer),
        // exact-cover fetches (guest RAM holds the same bytes) and bridges of
        // resolves that wrote no guest copy. With the canonical write-back on
        // at 1x, a resolve that does not overlap a recent frontbuffer and has
        // no snapshot yet skips creating one: its write-back is the only copy
        // anything needs, and fetches load it from guest memory. USF4 does 38
        // colour resolves a frame, 1 into the frontbuffer
        // (reduce-edram-pass-traffic Lever 3). XE_METAL_SNAPSHOT_ALL=1 is the
        // exact rollback.
        static const bool s_snapshot_writeback = [] {
          const char* v = std::getenv("XE_METAL_STAGE3");
          return (!v || v[0] != '0') && !std::getenv("XE_METAL_NO_WRITEBACK");
        }();
        // XE_METAL_SEED_FRONTBUFFER=<hexbase>,<hexlen> (trace replay): a
        // single-frame replay has no previous swap, so every resolve keeps a
        // snapshot and the write-back-only path live runs takes is never
        // exercised. Seeding the frontbuffer range the live run used puts the
        // replay on the same policy.
        if (!last_frontbuffer_bytes_) {
          static const std::pair<uint32_t, uint32_t> s_seed_frontbuffer = [] {
            std::pair<uint32_t, uint32_t> seed = {0, 0};
            const char* value = std::getenv("XE_METAL_SEED_FRONTBUFFER");
            if (value) {
              char* end = nullptr;
              seed.first = uint32_t(std::strtoul(value, &end, 16));
              if (end && *end == ',') {
                seed.second = uint32_t(std::strtoul(end + 1, nullptr, 16));
              }
            }
            return seed;
          }();
          if (s_seed_frontbuffer.second) {
            last_frontbuffer_base_ = s_seed_frontbuffer.first;
            last_frontbuffer_bytes_ = s_seed_frontbuffer.second;
            recent_frontbuffers_[0] = s_seed_frontbuffer;
          }
        }
        const bool skip_snapshot =
            !snap && last_frontbuffer_bytes_ && !ResolveSnapshotsForAllEnabled() &&
            canonical_resolve &&
            s_snapshot_writeback && draw_resolution_scale_x_ == 1 &&
            draw_resolution_scale_y_ == 1 &&
            !ResolveOverlapsRecentFrontbuffer(
                resolve_info.copy_dest_extent_start,
                resolve_info.copy_dest_extent_length) &&
            !render_target_cache_->GetResolveSnapshot(
                resolve_info.copy_dest_base);
        if (skip_snapshot) {
          static uint64_t s_snapshots_skipped = 0;
          ++s_snapshots_skipped;
          if ((s_snapshots_skipped & (s_snapshots_skipped - 1)) == 0) {
            REXLOG_INFO("MetalSnapshotPolicy: {} colour snapshots skipped (latest "
                   "dest {:08X} {}x{})",
                   s_snapshots_skipped, resolve_info.copy_dest_base, rw, rh);
          }
        }
        if (!snap && !skip_snapshot) {
          snap = render_target_cache_->EnsureResolveSnapshot(
              resolve_info.copy_dest_base, rw, rh, dest_pixel_format);
          is_new_snapshot = snap != nullptr;
          strip_y_offset = 0;
        }
        // A coalesced parent strip may predate the format decision — always
        // render in the snapshot texture's REAL format.
        if (snap) {
          dest_pixel_format =
              uint64_t(((__bridge id<MTLTexture>)snap).pixelFormat);
        }
        float exp_bias_scale = std::ldexp(
            1.0f,
            int32_t(resolve_info.copy_dest_info.copy_dest_exp_bias));
        // Integer-number-format destination (RB_COPY_DEST_INFO
        // copy_dest_number 2/3): the hardware stores the biased value as an
        // integer and the guest fetches it back as integer (the fetch's
        // texture_integer_scale_bits rescales normalized samples by
        // 2^bits-1). A float snapshot therefore holds value * 2^bias /
        // (2^bits-1) per channel, the RAM texture's normalized bits. Crysis 3
        // resolves its 7e3 HDR scene with exp_bias +6 into integer 11:11:10
        // and fetches it with exp_adjust -6; the fraction pack saturated the
        // whole scene copy to white.
        uint32_t dest_int_bits = 0;
        {
          const xenos::SurfaceNumberFormat dest_number =
              resolve_info.copy_dest_info.copy_dest_number;
          if (dest_number == xenos::SurfaceNumberFormat::kUnsignedInteger ||
              dest_number == xenos::SurfaceNumberFormat::kSignedInteger) {
            const ::rex::xenos::FormatInfo* dest_format_info =
                ::rex::xenos::FormatInfo::Get(xenos::TextureFormat(
                    resolve_info.copy_dest_info.copy_dest_format));
            if (texture_integer_scale::ComponentBits(xenos::TextureFormat(resolve_info.copy_dest_info.copy_dest_format), 3)) {
              for (uint32_t c = 0; c < 4; ++c) {
                dest_int_bits |=
                    uint32_t(texture_integer_scale::ComponentBits(xenos::TextureFormat(resolve_info.copy_dest_info.copy_dest_format), c) & 0xFF)
                    << (c * 8);
              }
            }
          }
        }
        // Raw-copy eligibility is shared resolve semantics, not a Metal
        // decision: ask draw_util rather than re-deriving the condition here,
        // so shared changes to it cannot silently skip this backend.
        const bool canonical_raw_copy = resolve_info.IsColorRawCopySafe();
        bool resolved = false;
        bool canonical_prepared = false;
        // Array / slice destinations (a 3D LUT built one slice at a time)
        // take the shared resolve shaders (3D destination addressing is
        // native there) even with the general switch off.
        const bool array_dest =
            resolve_info.copy_dest_info.copy_dest_array ||
            resolve_info.copy_dest_info.copy_dest_layer;
        const bool shared_resolve_route =
            SharedResolveShadersEnabled() ||
            (array_dest && SharedResolveArraysEnabled());
        if (canonical_resolve) {
          // Direct colour resolve: read the open colour attachment instead of
          // packing it into canonical EDRAM first (scope closed at the end of
          // this colour branch). The shared resolve route reads canonical, so
          // it keeps the pack -- for the array route too: with only the
          // array switch on, the direct path skipped the pack and the shared
          // shader resolved whatever canonical EDRAM last held (Rise of the
          // Tomb Raider's colour LUT: every slice the stale magenta tile).
          // Resolves without a snapshot (Lever 3) take it too: the guest
          // write-back reads the attachment the same way.
          const bool direct_color =
              !shared_resolve_route &&
              render_target_cache_->BeginDirectColorResolve(
                  uint32_t(resolve_info.color_edram_info.base_tiles),
                  uint32_t(resolve_info.color_edram_info.pitch_tiles),
                  uint32_t(resolve_info.color_edram_info.msaa_samples),
                  resolve_info.color_edram_info.format,
                  resolve_info.color_edram_info.format_is_64bpp != 0,
                  span_base, span_row_length, span_rows, span_pitch,
                  uint32_t(resolve_info.coordinate_info.edram_offset_x_div_8)
                      << 3,
                  uint32_t(resolve_info.coordinate_info.edram_offset_y_div_8)
                      << 3,
                  rw, rh,
                  uint32_t(resolve_info.copy_dest_coordinate_info
                               .copy_sample_select),
                  snap);
          canonical_prepared =
              direct_color ||
              render_target_cache_->PrepareCanonicalEdramForResolve(
                  span_base, span_row_length, span_rows, span_pitch);
          if (snap && canonical_prepared) {
            resolved = render_target_cache_->ResolveCanonicalToSnapshot(
                         frame_command_buffer_, /*is_depth=*/false,
                         uint32_t(resolve_info.color_edram_info.base_tiles),
                         uint32_t(resolve_info.color_edram_info.pitch_tiles),
                         uint32_t(resolve_info.color_edram_info.msaa_samples),
                         resolve_info.color_edram_info.format,
                         resolve_info.color_edram_info.format_is_64bpp != 0,
                         uint32_t(resolve_info.coordinate_info
                                      .edram_offset_x_div_8)
                             << 3,
                         uint32_t(resolve_info.coordinate_info
                                      .edram_offset_y_div_8)
                             << 3,
                         uint32_t(resolve_info.copy_dest_coordinate_info
                                      .copy_sample_select),
                         resolve_info.copy_dest_info.copy_dest_swap != 0,
                         canonical_raw_copy,
                         snap, dest_pixel_format, rw, rh, strip_y_offset,
                         exp_bias_scale, /*dest_x_offset=*/0, dest_int_bits);
          }
        } else if (snap) {
          resolved = render_target_cache_->ResolveColorToSnapshot(
              frame_command_buffer_, span_base, span_row_length, span_rows,
              span_pitch,
              uint32_t(resolve_info.color_edram_info.msaa_samples), snap,
              dest_pixel_format, rw, rh, strip_y_offset, exp_bias_scale,
              dest_int_bits);
        }
        // Draw resolution scaling: a column of a destination wider than the
        // resolve (no offset, dest pitch > width, not a vertical strip) also
        // renders into the destination's column assembly at its x offset, so
        // a fetch of the whole destination can be served at scale. The x
        // offset is the column whose tiled address is this base's delta from
        // an assembly's x = 0 base. Only formats scaled cover serves.
        uint32_t assembly_base = 0, assembly_x = 0, assembly_pitch = 0;
        void* assembly_snap = nullptr;
        if (resolved && canonical_resolve && canonical_prepared && !parent_snap &&
            (draw_resolution_scale_x_ > 1 || draw_resolution_scale_y_ > 1)) {
          const auto& dca = resolve_info.copy_dest_coordinate_info;
          uint32_t dest_pitch = uint32_t(dca.pitch_aligned_div_32) << 5;
          uint32_t bpp_log2 =
              dest_pixel_format == uint64_t(MTLPixelFormatRGBA16Float) ? 3u
              : (dest_pixel_format == uint64_t(MTLPixelFormatRGBA8Unorm) ||
                 dest_pixel_format == uint64_t(MTLPixelFormatR32Float))
                  ? 2u
                  : 0u;
          if (bpp_log2 && dest_pitch > rw && !dca.offset_x_div_8 &&
              !dca.offset_y_div_8) {
            assembly_base = resolve_info.copy_dest_base;
            for (const auto& assembly : scaled_assembly_pitches_) {
              if (assembly.second != dest_pitch ||
                  resolve_info.copy_dest_base <= assembly.first) {
                continue;
              }
              uint32_t delta = resolve_info.copy_dest_base - assembly.first;
              for (uint32_t x = 32; x < dest_pitch; x += 32) {
                if (uint32_t(texture_address::Tiled2D(int32_t(x), 0, dest_pitch,
                                                      bpp_log2)) == delta) {
                  assembly_base = assembly.first;
                  assembly_x = x;
                  break;
                }
              }
              if (assembly_x) {
                break;
              }
            }
            if (assembly_x + rw <= dest_pitch) {
              assembly_snap = render_target_cache_->EnsureAssemblySnapshot(
                  assembly_base, dest_pitch, rh, dest_pixel_format);
            }
            if (assembly_snap) {
              scaled_assembly_pitches_[assembly_base] = dest_pitch;
              assembly_pitch = dest_pitch;
              if (!render_target_cache_->ResolveCanonicalToSnapshot(
                      frame_command_buffer_, /*is_depth=*/false,
                      uint32_t(resolve_info.color_edram_info.base_tiles),
                      uint32_t(resolve_info.color_edram_info.pitch_tiles),
                      uint32_t(resolve_info.color_edram_info.msaa_samples),
                      resolve_info.color_edram_info.format,
                      resolve_info.color_edram_info.format_is_64bpp != 0,
                      uint32_t(resolve_info.coordinate_info
                                   .edram_offset_x_div_8)
                          << 3,
                      uint32_t(resolve_info.coordinate_info
                                   .edram_offset_y_div_8)
                          << 3,
                      uint32_t(resolve_info.copy_dest_coordinate_info
                                   .copy_sample_select),
                      resolve_info.copy_dest_info.copy_dest_swap != 0,
                      canonical_raw_copy, assembly_snap, dest_pixel_format, rw,
                      rh, /*dest_y_offset=*/0, exp_bias_scale, assembly_x,
                      dest_int_bits)) {
                assembly_snap = nullptr;
              }
            }
          }
        }
        if (resolved) {
          // Advance provenance for every successful resolve, including a
          // coalesced parent-strip update. Only an encoded color writeback
          // below stamps its layout with this generation; skipped or failed
          // writeback therefore leaves the previous layout provably stale.
          ++resolve_snapshot_generation_[resolve_info.copy_dest_base];
        }
        if (resolved && !parent_snap) {
          // Register (or re-register) every own-snapshot resolve: the entry's
          // dims must track the LAST resolve to the base — base reuse (JC2's
          // mid-frame G-buffer dump into the history base) downgrades them so
          // the covered-fetch bridge fast path correctly falls back to RAM
          // for the composite's full-height temporal read. Parent-strip joins
          // must NOT register: the strip base would alias the parent texture
          // without its y-offset.
          texture_cache_->RegisterResolvedTarget(resolve_info.copy_dest_base,
                                                 snap, rw, rh,
                                                 /*is_depth=*/false,
                                                 canonical_resolve,
                                                 resolve_info.copy_dest_extent_start,
                                                 resolve_info.copy_dest_extent_length);
          // XE_METAL_TIP_SNAP_VIEW (stabilize 6.6 experiment, default off):
          // maintain a derived 1x1 R32F copy of the snapshot's guest texel
          // (0,0) so 1x1 fetches (the exposure tips) sample the correct
          // texel instead of the middle of the full snapshot. One 4-byte
          // GPU-ordered blit per tip resolve; no wait, no control flow.
          static const bool s_tip_snap_view =
              std::getenv("XE_METAL_TIP_SNAP_VIEW") != nullptr;
          if (s_tip_snap_view &&
              dest_pixel_format == uint64_t(MTLPixelFormatR32Float)) {
            void*& tip = tip_view_textures_[resolve_info.copy_dest_base];
            if (!tip) {
              MTLTextureDescriptor* td = [[MTLTextureDescriptor alloc] init];
              td.textureType = MTLTextureType2DArray;
              td.pixelFormat = MTLPixelFormatR32Float;
              td.width = 1;
              td.height = 1;
              td.arrayLength = 1;
              td.mipmapLevelCount = 1;
              td.usage = MTLTextureUsageShaderRead;
              // Shared: the drain updates this texture CPU-side from the
              // POST-HOLD guest word, so the zero-luminance guard reaches the
              // path the tonemap actually samples. A GPU blit from the
              // snapshot bypassed the guard: one sun-blowout zero tile
              // latched exposure black (most view angles black live).
              td.storageMode = MTLStorageModeShared;
              id<MTLTexture> t = [((__bridge id<MTLTexture>)snap).device
                  newTextureWithDescriptor:td];
              tip = (__bridge_retained void*)t;
            }
            if (tip) {
              texture_cache_->RegisterResolvedTipView(
                  resolve_info.copy_dest_base, tip);
            }
          }
          if (xe_lineage_base() &&
              resolve_info.copy_dest_base == xe_lineage_base()) {
            REXLOG_WARN(
                "MetalLineage RESOLVE-REG draw={} base={:08X} {}x{} fmt={} "
                "(re-registers dims; coverage for the composite fetch)",
                trace_draw_index_, resolve_info.copy_dest_base, rw, rh,
                dest_pixel_format == MetalRenderTargetCache::kColorFormat
                    ? 0u
                    : uint32_t(dest_pixel_format));
          }
        }
        static const bool s_resolve_log2 =
            std::getenv("XE_METAL_RESOLVE_LOG") != nullptr;
        if (s_resolve_log2 && (!resolved || (!is_new_snapshot && !parent_snap))) {
          REXLOG_WARN(
              "MetalResolve @draw {} COLOR {:08X} {}x{}: resolved={} snap={} "
              "new={} parent={} (bridge {})",
              trace_draw_index_, resolve_info.copy_dest_base, rw, rh,
              resolved, snap != nullptr, is_new_snapshot,
              parent_snap != nullptr,
              resolved && is_new_snapshot ? "registered" : "NOT registered");
        }
        // Stage-3 slice: SMALL resolves also write back into REAL guest memory
        // at frame end. JC2's auto-exposure loop is CPU-side: the game reads
        // the resolved 1x1 luminance from RAM to compute the next frame's
        // exposure constant — snapshot-only resolves leave that RAM unwritten.
        static const bool s_no_writeback =
            std::getenv("XE_METAL_NO_WRITEBACK") != nullptr;
        // STAGE 3 (default ON; XE_METAL_STAGE3=0 disables): write back at
        // EVERY size — the composite's temporal history buffer (3.7MB) and
        // the G-buffer dests all live in guest RAM; fetches read RAM (color
        // bridge retired). Viable since the copy_dest_swap fix: the scatter
        // now matches hardware channel order, and SF4's x-offset column
        // resolves REQUIRE exact-address placement (the bridge can't).
        static const bool s_stage3 = [] {
          const char* v = std::getenv("XE_METAL_STAGE3");
          return !v || v[0] != '0';
        }();
        const uint64_t wb_cap =
            s_stage3 ? UINT32_MAX : 256u * 1024u;
        const uint32_t dest_format =
            uint32_t(resolve_info.copy_dest_info.copy_dest_format);
        const ::rex::xenos::FormatInfo& wb_format_info =
            *::rex::xenos::FormatInfo::Get(xenos::TextureFormat(dest_format));
        const uint32_t wb_bpp = wb_format_info.bits_per_pixel >> 3u;
        const uint32_t wb_bpp_log2 = rex::log2_floor(wb_bpp);
        const bool canonical_packed = canonical_resolve && canonical_prepared;
        const bool legacy_blit_format =
            dest_pixel_format == MetalRenderTargetCache::kColorFormat ||
            dest_pixel_format == uint64_t(MTLPixelFormatR32Float) ||
            dest_pixel_format == uint64_t(MTLPixelFormatRGBA16Float);
        // At a draw resolution scale the snapshot is scaled, so only the
        // canonical kernel (which reads representative pixels) can write guest
        // memory; the snapshot blit is a 1x-only source.
        const bool writeback_source_available =
            canonical_packed ||
            (resolved && snap && legacy_blit_format &&
             draw_resolution_scale_x_ == 1 && draw_resolution_scale_y_ == 1);
        // TASK 6.3: which gate decides whether the INCUMBENT writes this
        // destination. The byte comparison showed Metal leaves the implicated
        // wide-pitch dest ~98.7% zero, so "baseline" there may be UNWRITTEN
        // memory rather than correct output -- in which case the shared route
        // is not producing wrong pixels, it is producing pixels where the
        // incumbent produces none.
        if (IssueCopyWbGateLog()) {
          // Materialization coverage: what Metal PREPARED for this resolve
          // versus the source rect the shared shader will read. If the shader
          // reads tiles outside the prepared span, it reads whatever the
          // canonical buffer happens to hold.
          REXLOG_WARN(
              "MetalWbSpan dest={:08X} prepared_span(base={} row_len={} "
              "rows={} pitch={}) edram(base={} pitch={}) src_off=({},{}) "
              "rect={}x{}",
              resolve_info.copy_dest_base, span_base, span_row_length,
              span_rows, span_pitch,
              uint32_t(uint32_t(resolve_info.color_edram_info.base_tiles)),
              uint32_t(uint32_t(resolve_info.color_edram_info.pitch_tiles)),
              uint32_t(resolve_info.coordinate_info.edram_offset_x_div_8) << 3,
              uint32_t(resolve_info.coordinate_info.edram_offset_y_div_8) << 3,
              rw, rh);
        }
        if (IssueCopyWbGateLog()) {
          const uint64_t wb_bytes = uint64_t(rw) * rh * wb_bpp;
          REXLOG_WARN(
              "MetalWbGate dest={:08X} {}x{} bpp={} bytes={} cap={} "
              "src_avail={} canonical_packed={} resolved={} snap={} "
              "legacy_fmt={} no_wb={} size_ok={} => encodes={}",
              resolve_info.copy_dest_base, rw, rh, wb_bpp, wb_bytes, wb_cap,
              writeback_source_available ? 1 : 0, canonical_packed ? 1 : 0,
              resolved ? 1 : 0, snap ? 1 : 0, legacy_blit_format ? 1 : 0,
              s_no_writeback ? 1 : 0, wb_bytes <= wb_cap ? 1 : 0,
              (writeback_source_available && !s_no_writeback &&
               wb_bytes <= wb_cap &&
               (canonical_packed || legacy_blit_format))
                  ? 1
                  : 0);
        }
        if (writeback_source_available && !s_no_writeback &&
            uint64_t(rw) * rh * wb_bpp <= wb_cap &&
            (canonical_packed || legacy_blit_format)) {
          id<MTLDevice> wb_device = (__bridge id<MTLDevice>)
              static_cast<rex::ui::metal::MetalProvider*>(
                  GetGraphicsDriver().GetProvider())
                  ->device();
          // SHARED RESOLVE ROUTE (XE_METAL_SHARED_RESOLVE, default OFF): the
          // cross-backend copy shader writes EDRAM straight to the guest tiled
          // destination in the shared buffer, exactly as D3D12/Vulkan do. When
          // it dispatches, the record is GPU-current and no staging buffer or
          // CPU scatter is created; when it declines (unsupported shader index,
          // uncommitted destination, pipelines unavailable) the existing paths
          // below run unchanged.
          bool shared_resolve_dispatched = false;
          if (!canonical_packed && IssueCopyGpuResolveLog()) {
            // The legacy-blit writeback: never GPU-current, so every draw
            // sampling its range commits and waits (Tomb Raider: 32 a frame).
            REXLOG_WARN(
                "MetalLegacyWriteback draw={} base={:08X} {}x{} bpp={} fmt={} "
                "canonical_resolve={} canonical_prepared={} legacy_blit={}",
                trace_draw_index_, resolve_info.copy_dest_base, rw, rh, wb_bpp,
                dest_format, canonical_resolve ? 1 : 0,
                canonical_prepared ? 1 : 0, legacy_blit_format ? 1 : 0);
          }
          // Array / slice destinations cannot take the canonical scatter;
          // they take the shared resolve shaders even with the general
          // switch off (XE_METAL_SHARED_RESOLVE_ARRAYS=0 drops them back to
          // the CPU writeback). Decided above, before the canonical pack.
          if (shared_resolve_route) {
            if (canonical_prepared) {
              shared_resolve_dispatched =
                  DispatchSharedResolveCopy(resolve_info);
            } else {
              static uint32_t s_gate_logs = 0;
              if (s_gate_logs++ < 8) {
                REXLOG_WARN(
                    "MetalSharedResolve: gate closed (canonical_prepared=0, "
                    "canonical_resolve={}) dest={:08X}",
                    canonical_resolve ? 1 : 0, resolve_info.copy_dest_base);
              }
            }
          }
          // STAGE B eligibility (XE_METAL_GPU_RESOLVE, default OFF). Every
          // condition is a proof obligation; anything unproven falls back to
          // the staging + CPU-scatter path, which is always correct.
          const auto& dc_pre = resolve_info.copy_dest_coordinate_info;
          uint32_t scatter_extent_bytes =
              resolve_info.copy_dest_extent_start -
              resolve_info.copy_dest_base +
              resolve_info.copy_dest_extent_length;
          bool scatter_eligible = false;
          id<MTLBuffer> shared_scatter_buffer = nil;
          // The shared route already wrote the destination; the bespoke
          // scatter must not also run for the same resolve.
          if (!shared_resolve_dispatched && GpuResolveScatterEnabled() &&
              canonical_packed && shared_memory_ &&
              scatter_extent_bytes &&
              // 2D only: the kernel ports Tiled2D, not Tiled3D.
              !resolve_info.copy_dest_info.copy_dest_array &&
              !resolve_info.copy_dest_info.copy_dest_layer) {
            shared_scatter_buffer =
                (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
            auto dest_range = metal::GuestRange::FromBaseLength(
                resolve_info.copy_dest_base, scatter_extent_bytes);
            if (shared_scatter_buffer && dest_range &&
                uint64_t(resolve_info.copy_dest_base) + scatter_extent_bytes <=
                    shared_scatter_buffer.length) {
              // WRITER ORDERING, the same precondition a memexport store must
              // satisfy: this scatter writes the shared buffer, so an older
              // overlapping producer whose drain lands afterwards would
              // overwrite it (unrecoverably when the buffer aliases RAM).
              // Conservative: ANY overlapping pending producer disqualifies
              // the scatter rather than trying to order against it here.
              // Stage 2 (optimize-metal-gpu-resident-resolve-coherence): an
              // unpublished GPU-resident record under the destination no
              // longer refuses the scatter. Both writers land in the shared
              // buffer in command order, publication walks records in
              // authority-sequence order (older first), the validity bits keep
              // RequestRange from uploading stale RAM over the older bytes,
              // and the straddler refresh already excludes pending
              // GPU-current spans. Staging resolves and memexports still
              // refuse (their bytes are not in the buffer in command order).
              // XE_METAL_GPU_RESOLVE_OVERLAP=0 restores the old refusal.
              static const bool s_overlap_gpu_current = [] {
                const char* v = std::getenv("XE_METAL_GPU_RESOLVE_OVERLAP");
                return !(v && v[0] == '0' && !v[1]);
              }();
              // A pending memexport under the destination is buffer-resident
              // in command order too (the export wrote the shared buffer on
              // the GPU; its RAM convergence copies from the buffer), so it
              // orders the same way. Without this the JC2 lighting chain's
              // resolve into the export region took the host-staged path and
              // every consumer of it awaited the frame (one 6 ms boundary
              // per frame). XE_METAL_GPU_RESOLVE_OVERLAP_MEMEXPORT=0 refuses.
              static const bool s_overlap_memexport = [] {
                const char* v =
                    std::getenv("XE_METAL_GPU_RESOLVE_OVERLAP_MEMEXPORT");
                return !(v && v[0] == '0' && !v[1]);
              }();
              bool overlapping_pending = false;
              for (const metal::PendingProducer& p :
                   SnapshotPendingProducers()) {
                if (!p.range.Overlaps(*dest_range)) {
                  continue;
                }
                if (s_overlap_gpu_current &&
                    p.state == metal::TransitState::kGpuCurrentShared) {
                  continue;
                }
                if (s_overlap_gpu_current && s_overlap_memexport &&
                    p.state == metal::TransitState::kPendingMemexport) {
                  continue;
                }
                overlapping_pending = true;
                break;
              }
              // DIAGNOSTIC BISECT (XE_METAL_GPU_RESOLVE_FULLRECT=1): restrict
              // the scatter to full-rect, offset-zero destinations to test
              // whether offset/strip destinations are the divergence source.
              static const bool s_fullrect_only =
                  std::getenv("XE_METAL_GPU_RESOLVE_FULLRECT") != nullptr;
              const bool full_rect_dest =
                  dc_pre.offset_x_div_8 == 0 && dc_pre.offset_y_div_8 == 0 &&
                  (uint32_t(dc_pre.pitch_aligned_div_32) << 5) == rw;
              // Bisect lever: XE_METAL_SCATTER_SKIP_BASE=<hex,...> sends the
              // named destinations to the staging + CPU-scatter path.
              static const char* s_scatter_skip_env =
                  std::getenv("XE_METAL_SCATTER_SKIP_BASE");
              bool scatter_skipped = false;
              if (s_scatter_skip_env) {
                for (const char* sp = s_scatter_skip_env; *sp;) {
                  char* end;
                  uint32_t v = uint32_t(strtoul(sp, &end, 16));
                  if (end == sp) {
                    break;
                  }
                  if (v == resolve_info.copy_dest_base) {
                    scatter_skipped = true;
                    break;
                  }
                  sp = (*end == ',') ? end + 1 : end;
                }
              }
              scatter_eligible = !overlapping_pending && !scatter_skipped &&
                                 (!s_fullrect_only || full_rect_dest);
              if (scatter_eligible &&
                  !shared_memory_->RequestRange(
                      resolve_info.copy_dest_extent_start,
                      resolve_info.copy_dest_extent_length)) {
                // Commit the destination pages from RAM BEFORE the kernel,
                // exactly as the shared route does: the extent's tiled
                // ALIGNMENT PADDING is never written by the scatter, and an
                // uncommitted buffer leaves stale bytes there that
                // edge-sampling consumers read (SF4 10581: a deterministic
                // 74-px route-only residual).
                scatter_eligible = false;
              }
              if (IssueCopyGpuResolveLog()) {
                REXLOG_WARN(
                    "MetalGpuScatter draw={} base={:08X} {}x{} bpp={} "
                    "bpp_log2={} pitch_aligned={} off=({},{}) extent={} "
                    "endian={} swap={} fmt={} raw={} 64bpp={} msaa={} "
                    "sample_select={} eligible={} full_rect={}",
                    uint32_t(trace_draw_index_), resolve_info.copy_dest_base, rw, rh,
                    wb_bpp, wb_bpp_log2,
                    uint32_t(dc_pre.pitch_aligned_div_32) << 5,
                    uint32_t(dc_pre.offset_x_div_8) << 3,
                    uint32_t(dc_pre.offset_y_div_8) << 3, scatter_extent_bytes,
                    uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
                    uint32_t(resolve_info.copy_dest_info.copy_dest_swap),
                    dest_format, canonical_raw_copy ? 1 : 0,
                    resolve_info.color_edram_info.format_is_64bpp ? 1 : 0,
                    uint32_t(resolve_info.color_edram_info.msaa_samples),
                    uint32_t(dc_pre.copy_sample_select),
                    scatter_eligible ? 1 : 0, full_rect_dest ? 1 : 0);
              }
            }
          }
          // The shared route already wrote the destination; like the bespoke
          // scatter it needs NO staging buffer and NO CPU scatter. Without
          // this the route is ADDITIVE -- both paths run, guest RAM is still
          // written by the CPU scatter, and any "identical output" result is
          // trivially true because the OLD path produced it.
          const bool gpu_resident_resolve =
              shared_resolve_dispatched || scatter_eligible;
          id<MTLBuffer> staging =
              gpu_resident_resolve
                  ? nil
                  : [wb_device newBufferWithLength:size_t(rw) * rh * wb_bpp
                                           options:MTLResourceStorageModeShared];
          MetalRenderTargetCache::CanonicalScatterDest scatter_dest{
              resolve_info.copy_dest_base,
              // SAME fallback the CPU scatter applies: a zero aligned pitch
              // means "derive it from the width". Passing the raw zero through
              // makes every outer-tile term vanish and scatters the whole
              // surface to wrong addresses.
              (uint32_t(dc_pre.pitch_aligned_div_32) << 5)
                  ? (uint32_t(dc_pre.pitch_aligned_div_32) << 5)
                  : ((rw + 31u) & ~31u),
              uint32_t(dc_pre.offset_x_div_8) << 3,
              uint32_t(dc_pre.offset_y_div_8) << 3,
              scatter_extent_bytes};
          // The destination RequestRange above can take an intra-frame
          // rewrite hazard whose flush commits the frame command buffer
          // (synchronous mode, or XE_METAL_HAZARD_STAGED=0). Encoding on the
          // null buffer returns false and the resolve is SILENTLY DROPPED (SF4
          // 10395 luminance pyramid under XE_METAL_ASYNC=0), so recreate it
          // before any writeback encode, as IssueCopy does on entry.
          // XE_METAL_RESOLVE_NULL_CB_LEGACY=1 restores the old behavior.
          static const bool s_null_cb_legacy =
              std::getenv("XE_METAL_RESOLVE_NULL_CB_LEGACY") != nullptr;
          if (!s_null_cb_legacy) {
            PrepareTransferCommandBuffer(uint32_t(metal::MetalTransferSite::kResolve));
          }
          // Diagnostic (XE_METAL_DIRECT_COLOR_VERIFY=1, never for play): for
          // a resolve that took the direct colour path, also resolve it the
          // pack-first way, both into linear staging buffers, and log the
          // resolves whose guest bytes differ when the frame completes.
          static const bool s_direct_verify =
              std::getenv("XE_METAL_DIRECT_COLOR_VERIFY") != nullptr;
          if (s_direct_verify && canonical_packed && frame_command_buffer_ &&
              render_target_cache_->IsDirectColorResolveActive()) {
            const size_t verify_bytes = size_t(rw) * rh * wb_bpp;
            id<MTLBuffer> verify_direct =
                [wb_device newBufferWithLength:verify_bytes
                                       options:MTLResourceStorageModeShared];
            id<MTLBuffer> verify_packed =
                [wb_device newBufferWithLength:verify_bytes
                                       options:MTLResourceStorageModeShared];
            const uint32_t verify_number =
                ResolveNumberFormatEnabled()
                    ? uint32_t(resolve_info.copy_dest_info.copy_dest_number)
                    : 0u;
            auto verify_encode = [&](id<MTLBuffer> destination) {
              return render_target_cache_->ResolveCanonicalColorToBuffer(
                  frame_command_buffer_,
                  uint32_t(resolve_info.color_edram_info.base_tiles),
                  uint32_t(resolve_info.color_edram_info.pitch_tiles),
                  uint32_t(resolve_info.color_edram_info.msaa_samples),
                  resolve_info.color_edram_info.format,
                  resolve_info.color_edram_info.format_is_64bpp != 0,
                  uint32_t(resolve_info.coordinate_info.edram_offset_x_div_8)
                      << 3,
                  uint32_t(resolve_info.coordinate_info.edram_offset_y_div_8)
                      << 3,
                  uint32_t(
                      resolve_info.copy_dest_coordinate_info.copy_sample_select),
                  resolve_info.copy_dest_info.copy_dest_swap != 0,
                  exp_bias_scale, dest_format, wb_bpp_log2,
                  uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
                  canonical_raw_copy, (__bridge void*)destination, rw, rh,
                  nullptr, verify_number);
            };
            const bool direct_ok = verify_direct && verify_encode(verify_direct);
            void* direct_source =
                render_target_cache_->SuspendDirectColorResolve();
            const bool packed_ok =
                verify_packed &&
                render_target_cache_->PrepareCanonicalEdramForResolve(
                    span_base, span_row_length, span_rows, span_pitch) &&
                verify_encode(verify_packed);
            render_target_cache_->ResumeDirectColorResolve(direct_source);
            if (direct_ok && packed_ok) {
              const uint32_t v_draw = trace_draw_index_;
              const uint32_t v_base = resolve_info.copy_dest_base;
              const uint32_t v_rt_format =
                  uint32_t(resolve_info.color_edram_info.format);
              const uint32_t v_msaa =
                  uint32_t(resolve_info.color_edram_info.msaa_samples);
              const uint32_t v_edram_base =
                  uint32_t(resolve_info.color_edram_info.base_tiles);
              const uint32_t v_pitch = uint32_t(resolve_info.color_edram_info.pitch_tiles);
              const uint32_t v_ox =
                  uint32_t(resolve_info.coordinate_info.edram_offset_x_div_8)
                  << 3;
              const uint32_t v_oy =
                  uint32_t(resolve_info.coordinate_info.edram_offset_y_div_8)
                  << 3;
              const uint32_t v_sample = uint32_t(
                  resolve_info.copy_dest_coordinate_info.copy_sample_select);
              const uint32_t v_dest_format = uint32_t(dest_format);
              const uint32_t v_bpp = uint32_t(wb_bpp);
              const uint32_t v_w = rw, v_h = rh;
              const float v_exp = exp_bias_scale;
              const bool v_raw = canonical_raw_copy;
              [(__bridge id<MTLCommandBuffer>)frame_command_buffer_
                  addCompletedHandler:^(id<MTLCommandBuffer>) {
                    static std::atomic<uint64_t> s_checked{0}, s_differ{0};
                    const uint8_t* a =
                        static_cast<const uint8_t*>(verify_direct.contents);
                    const uint8_t* b =
                        static_cast<const uint8_t*>(verify_packed.contents);
                    uint64_t pixels = uint64_t(v_w) * v_h, bad = 0;
                    uint64_t first = UINT64_MAX;
                    for (uint64_t i = 0; i < pixels; ++i) {
                      if (std::memcmp(a + i * v_bpp, b + i * v_bpp, v_bpp)) {
                        if (first == UINT64_MAX) first = i;
                        ++bad;
                      }
                    }
                    const uint64_t checked = ++s_checked;
                    if (bad) {
                      const uint64_t differ = ++s_differ;
                      if (differ <= 64) {
                        uint32_t wa = 0, wb = 0;
                        std::memcpy(&wa, a + first * v_bpp,
                                    std::min<uint32_t>(v_bpp, 4));
                        std::memcpy(&wb, b + first * v_bpp,
                                    std::min<uint32_t>(v_bpp, 4));
                        REXLOG_WARN(
                            "MetalDirectColorVerify DIFF draw={} dest={:08X} "
                            "{}x{} rt_fmt={} msaa={} edram_base={} pitch={} "
                            "off=({},{}) sample={} dest_fmt={} bpp={} exp={} "
                            "raw={} bad_px={}/{} first=({},{}) direct={:08X} "
                            "packed={:08X}",
                            v_draw, v_base, v_w, v_h, v_rt_format, v_msaa,
                            v_edram_base, v_pitch, v_ox, v_oy, v_sample,
                            v_dest_format, v_bpp, v_exp, v_raw, bad, pixels,
                            first % v_w, first / v_w, wa, wb);
                      }
                    }
                    if ((checked & (checked - 1)) == 0) {
                      REXLOG_INFO("MetalDirectColorVerify: {} resolves checked, {} "
                             "differ",
                             checked, s_differ.load());
                    }
                  }];
            }
          }
          // Resolve forwarding: the scatter also writes the shared texture
          // cache's texture of this destination, which then needs no reload.
          MetalSharedTextureCache::ResolveForwardTarget forward_target;
          MetalRenderTargetCache::ResolveForward forward;
          const bool forwarding =
              scatter_eligible && canonical_packed && shared_texture_cache_ &&
              true &&
              shared_texture_cache_->FindResolveForward(
                  scatter_dest.dest_base, scatter_dest.dest_pitch_aligned,
                  wb_bpp_log2, scatter_dest.dest_offset_x,
                  scatter_dest.dest_offset_y, rw, rh,
                  scatter_dest.dest_extent_bytes, &forward_target);
          if (!forwarding && IssueCopyResolveForwardLog()) {
            static uint32_t s_forward_logs = 0;
            if (s_forward_logs++ < 300 || (s_forward_logs & 31u) == 0) {
              REXLOG_INFO("MetalResolveForward path dest={:08X} {}x{} scatter={} "
                     "canonical_packed={} shared_dispatched={}",
                     resolve_info.copy_dest_base, rw, rh,
                     scatter_eligible ? 1 : 0, canonical_packed ? 1 : 0,
                     shared_resolve_dispatched ? 1 : 0);
            }
          }
          if (forwarding) {
            forward.texture = forward_target.mtl_texture;
            forward.kind = forward_target.kind;
            forward.endian = forward_target.endian;
            forward.width = forward_target.width;
            forward.height = forward_target.height;
            forward.origin_y = forward_target.origin_y;
          }
          if (staging || gpu_resident_resolve) {
            bool writeback_encoded = false;
            if (shared_resolve_dispatched) {
              // Already resolved by the shared cross-backend shader straight
              // into the shared buffer at guest tiled addresses: no second
              // kernel, no staging, no CPU scatter.
              writeback_encoded = true;
            } else if (canonical_packed) {
              writeback_encoded =
                  render_target_cache_->ResolveCanonicalColorToBuffer(
                      frame_command_buffer_,
                      uint32_t(resolve_info.color_edram_info.base_tiles),
                      uint32_t(resolve_info.color_edram_info.pitch_tiles),
                      uint32_t(resolve_info.color_edram_info.msaa_samples),
                      resolve_info.color_edram_info.format,
                      resolve_info.color_edram_info.format_is_64bpp != 0,
                      uint32_t(resolve_info.coordinate_info
                                   .edram_offset_x_div_8)
                          << 3,
                      uint32_t(resolve_info.coordinate_info
                                   .edram_offset_y_div_8)
                          << 3,
                      uint32_t(resolve_info.copy_dest_coordinate_info
                                   .copy_sample_select),
                      resolve_info.copy_dest_info.copy_dest_swap != 0,
                      exp_bias_scale, dest_format, wb_bpp_log2,
                      uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
                      canonical_raw_copy,
                      scatter_eligible ? (__bridge void*)shared_scatter_buffer
                                       : (__bridge void*)staging,
                      rw, rh,
                      scatter_eligible ? &scatter_dest : nullptr,
                      // XE_METAL_RESOLVE_NUMBER_FORMAT=0: pack every fixed
                      // destination as an unsigned fraction (the old way).
                      ResolveNumberFormatEnabled()
                          ? uint32_t(
                                resolve_info.copy_dest_info.copy_dest_number)
                          : 0u,
                      forwarding ? &forward : nullptr);
            } else {
              id<MTLCommandBuffer> wb_cb =
                  (__bridge id<MTLCommandBuffer>)frame_command_buffer_;
              id<MTLBlitCommandEncoder> wb_blit = [wb_cb blitCommandEncoder];
              wb_blit.label = @"cp:writeback-blit";
              [wb_blit copyFromTexture:(__bridge id<MTLTexture>)snap
                            sourceSlice:0
                            sourceLevel:0
                           sourceOrigin:MTLOriginMake(0, strip_y_offset, 0)
                             sourceSize:MTLSizeMake(rw, rh, 1)
                               toBuffer:staging
                      destinationOffset:0
                 destinationBytesPerRow:rw * wb_bpp
               destinationBytesPerImage:rw * rh * wb_bpp];
              [wb_blit endEncoding];
              writeback_encoded = true;
            }
            const auto& dc = resolve_info.copy_dest_coordinate_info;
            uint32_t extent_bytes =
                resolve_info.copy_dest_extent_start - resolve_info.copy_dest_base +
                resolve_info.copy_dest_extent_length;
            // copy_dest_swap only applies to multi-channel color packing
            // (resolve.xesli writes .bgra); R32Float has nothing to swap.
            uint32_t wb_swap_rb =
                dest_pixel_format == MetalRenderTargetCache::kColorFormat &&
                !canonical_resolve &&
                resolve_info.copy_dest_info.copy_dest_swap;
            if (writeback_encoded && !gpu_resident_resolve &&
                IssueCopyGpuResolveLog()) {
              // A CPU-staged color writeback (never GPU-current): the draws
              // that sample its range commit and wait on it.
              REXLOG_WARN(
                  "MetalCpuWriteback draw={} base={:08X} {}x{} bpp={} fmt={} "
                  "slice={} array={} canonical_packed={} shared_dispatched={} "
                  "scatter_eligible={}",
                  uint32_t(trace_draw_index_), resolve_info.copy_dest_base, rw, rh,
                  wb_bpp, dest_format,
                  uint32_t(resolve_info.copy_dest_info.copy_dest_layer),
                  uint32_t(resolve_info.copy_dest_info.copy_dest_array),
                  canonical_packed ? 1 : 0, shared_resolve_dispatched ? 1 : 0,
                  scatter_eligible ? 1 : 0);
            }
            if (writeback_encoded) {
              pending_writebacks_.push_back(PendingWriteback{
                  (__bridge_retained void*)staging,
                  resolve_info.copy_dest_base,
                  rw,
                  rh,
                  wb_bpp,
                  canonical_packed
                      ? 0u
                      : uint32_t(
                            resolve_info.copy_dest_info.copy_dest_endian),
                  uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
                  uint32_t(dc.pitch_aligned_div_32) << 5,
                  uint32_t(dc.offset_x_div_8) << 3,
                  uint32_t(dc.offset_y_div_8) << 3,
                  extent_bytes,
                  uint32_t(dc.height_aligned_div_32) << 5,
                  uint32_t(resolve_info.copy_dest_info.copy_dest_layer),
                  uint32_t(resolve_info.copy_dest_info.copy_dest_array),
                  wb_swap_rb,
                  uint32_t(resolve_info.copy_dest_info.copy_dest_swap),
                  uint32_t(canonical_packed),
                  S7TagsOff() ? 0 : CurrentEncodingSubmission(),
                  dest_format,
                  uint32_t(trace_draw_index_),
                  swap_count_,
                  /*depth_encode=*/0u,
                  ++memory_authority_sequence_});
              if (gpu_resident_resolve) {
                // Origin experiment (reopen 2.2): guest RAM at ENCODE time —
                // in a single-frame trace this is the frame-start content of
                // the destination, the candidate source of a page-granular
                // consumer re-upload clobber.
                MetalOriginDumpExtent(
                    "enc", resolve_info.copy_dest_base, rw, rh, wb_bpp,
                    uint32_t(dc.pitch_aligned_div_32) << 5,
                    uint32_t(dc.height_aligned_div_32) << 5,
                    uint32_t(dc.offset_x_div_8) << 3,
                    uint32_t(dc.offset_y_div_8) << 3, extent_bytes,
                    uint32_t(canonical_packed), wb_swap_rb,
                    uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
                    uint32_t(trace_draw_index_),
                    TranslateGuest<const uint8_t*>(
                        resolve_info.copy_dest_base));
                // The record's bytes are in the shared buffer, not staging.
                RegisterGpuResidentResolve(resolve_info.copy_dest_base,
                                           scatter_extent_bytes);
                if (forward.encoded) {
                  shared_texture_cache_->CompleteResolveForward(forward_target);
                }
              }
            }
            if (writeback_encoded &&
                dest_pixel_format == MetalRenderTargetCache::kColorFormat) {
              ram_color_layouts_[resolve_info.copy_dest_base] = RamColorLayout{
                  uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
                  uint32_t(resolve_info.copy_dest_info.copy_dest_swap),
                  resolve_snapshot_generation_[resolve_info.copy_dest_base]};
            }
            // Stage-3 hybrid: RAM now holds (will hold) this dest — fetches
            // of the base must read RAM, not the bridge snapshot. Full-rect
            // geometry (offset 0,0 and pitch == width) lets the exact-cover
            // reader prove snapshot/RAM value equivalence for equal-extent
            // fetches.
            if (writeback_encoded && texture_cache_) {
              texture_cache_->MarkResolvedTargetRamBacked(
                  resolve_info.copy_dest_base, rw, rh,
                  dc.offset_x_div_8 == 0 && dc.offset_y_div_8 == 0 &&
                      (uint32_t(dc.pitch_aligned_div_32) << 5) == rw,
                  uint32_t(resolve_info.copy_dest_info.copy_dest_endian));
              if (assembly_snap) {
                // Draw resolution scaling: this column is in its assembly and
                // in guest RAM.
                texture_cache_->RegisterScaledAssembly(
                    assembly_base, assembly_snap, assembly_pitch, rh,
                    assembly_x, rw, resolve_info.copy_dest_extent_start,
                    resolve_info.copy_dest_extent_length,
                    uint32_t(resolve_info.copy_dest_info.copy_dest_endian));
              }
              if (parent_snap) {
                // Draw resolution scaling: this strip's rows are in the parent
                // snapshot and in guest RAM, so they extend the parent
                // registration's scaled cover (no-op at 1x).
                texture_cache_->ExtendResolvedTargetCoverage(
                    snap, strip_y_offset, rh,
                    resolve_info.copy_dest_extent_start,
                    resolve_info.copy_dest_extent_length,
                    uint32_t(resolve_info.copy_dest_info.copy_dest_endian));
              }
            }
            if (writeback_encoded && xe_lineage_base() &&
                resolve_info.copy_dest_base == xe_lineage_base()) {
              REXLOG_WARN(
                  "MetalLineage WB-ENQUEUE draw={} base={:08X} {}x{} bpp={} "
                  "endian={} swap_rb={} pitch={} off=({},{}) (queued -> RAM at "
                  "drain; ram_backed=true)",
                  uint32_t(trace_draw_index_), resolve_info.copy_dest_base, rw, rh, wb_bpp,
                  uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
                  wb_swap_rb, uint32_t(dc.pitch_aligned_div_32) << 5,
                  uint32_t(dc.offset_x_div_8) << 3,
                  uint32_t(dc.offset_y_div_8) << 3);
            }
          }
        }
      } else {
        static uint32_t s_missing_color_rt_logs = 0;
        if (s_missing_color_rt_logs++ < 8) {
          REXLOG_WARN(
              "MetalCommandProcessor: color resolve base={} fmt={} has no "
              "rendered target",
              resolve_info.color_original_base,
              uint32_t(resolve_info.color_edram_info.format));
        }
      }
    }
    if (render_target_cache_) {
      render_target_cache_->EndDirectColorResolve();
    }
  } else if (resolve_info.IsCopyingDepth() &&
             resolve_info.copy_dest_extent_length) {
    // Depth resolve: deferred lighting samples the depth buffer as a texture to
    // reconstruct position (JC2/Sonic sample fmt 22/23 -> we returned null ->
    // black lighting). Our depth RT is Depth32Float, which Metal only samples as
    // depth2d while MSC shaders declare texture2d_array<float>; convert it to an
    // R32Float snapshot with a small fullscreen pass, and register that. The
    // source is the depth target the pass rendered (by the resolve's EDRAM
    // base), e.g. the shadow map and the scene depth are distinct textures.
    uint32_t rw = uint32_t(resolve_info.coordinate_info.width_div_8) * 8;
    uint32_t rh = resolve_info.height_div_8 * 8;
    if (rw && rh && kDepthEnabled && render_target_cache_ && texture_cache_ &&
        frame_command_buffer_) {
      uint32_t span_base, span_row_length, span_rows, span_pitch;
      resolve_info.GetCopyEDRAMTileSpan(span_base, span_row_length, span_rows,
                                        span_pitch);
      EndRenderEncoder(
          metal::MetalPassEndReason::kDepthResolve, 0,
          frame_open_ && render_target_cache_->ResolveSpanTouchesCurrentAttachments(
                             span_base, span_row_length, span_rows, span_pitch));
      // Multi-strip resolve: if this strip's destination lands inside an
      // existing (full-height) snapshot, convert into that snapshot at the row
      // offset — shaders sample the FIRST strip's base as the whole buffer.
      uint32_t strip_y_offset = 0;
      void* parent_snap = render_target_cache_->FindContainingSnapshot(
          resolve_info.copy_dest_base, uint64_t(MTLPixelFormatR32Float),
          &strip_y_offset);
      static const bool s_resolve_log_d =
          std::getenv("XE_METAL_RESOLVE_LOG") != nullptr;
      if (s_resolve_log_d) {
        REXLOG_WARN(
            "MetalResolve @draw {} DEPTH: dest base={:08X} extent=[{:08X},+{}] "
            "rect={}x{} edram_base={} msaa={} parent={} parent_fmt={} strip_y={}",
            trace_draw_index_, resolve_info.copy_dest_base,
            resolve_info.copy_dest_extent_start,
            resolve_info.copy_dest_extent_length, rw, rh,
            uint32_t(resolve_info.depth_edram_info.base_tiles),
            uint32_t(resolve_info.depth_edram_info.msaa_samples),
            parent_snap != nullptr,
            parent_snap
                ? uint64_t(((__bridge id<MTLTexture>)parent_snap).pixelFormat)
                : 0,
            strip_y_offset);
      }
      // The strip's rows start at its destination offset below the adjusted
      // base, as for colour.
      if (parent_snap &&
          !ApplyStripJoinDestOffset(resolve_info, strip_y_offset)) {
        parent_snap = nullptr;
        strip_y_offset = 0;
      }
      // Address containment alone doesn't prove that this resolve is a
      // vertical strip of the earlier snapshot. Tiled column resolves may
      // have nearby adjusted bases whose byte delta happens to look like a row
      // offset. Joining those clips the bottom and makes later columns sample
      // stale/repeated depth. Require the same concrete texture compatibility
      // and fit used by the color path.
      if (parent_snap) {
        id<MTLTexture> parent_tex = (__bridge id<MTLTexture>)parent_snap;
        if (parent_tex.pixelFormat != MTLPixelFormatR32Float ||
            rw != uint32_t(parent_tex.width) / draw_resolution_scale_x_ ||
            strip_y_offset + rh >
                uint32_t(parent_tex.height) / draw_resolution_scale_y_) {
          parent_snap = nullptr;
          strip_y_offset = 0;
        }
      }
      if (!parent_snap) {
        render_target_cache_->NoteSnapshotStripContinuation(
            resolve_info.copy_dest_base, rw, rh, MTLPixelFormatR32Float);
      }
      void* snap = parent_snap;
      bool is_new_snapshot = false;
      uint32_t strip_x_offset = 0;
      // Column-strip depth destination (2026-10-03, Viva Pinata title
      // screen): the guest resolves a 1280-pitch scene depth as two 640x720
      // columns, the second at the tiled address of x = 640, and samples the
      // FIRST column's base as the whole 1280x720 buffer. Depth is always
      // served from its snapshot, so the parent object must hold both
      // columns: allocate it at the destination pitch and resolve each column
      // at its x. The later column does not register its own base (it would
      // alias the parent without the x offset). XE_METAL_DEPTH_COLUMN_JOIN=0
      // restores one snapshot per column base.
      // Quadrants (2026-11-11, NBA Street Homecourt): a 4x MSAA 1280x720
      // scene is four tiles, 640x384 twice and 640x336 twice, and its depth
      // resolves as four pieces of one 1280-pitch buffer the depth-of-field
      // pass fetches from the first piece's base. The lower pair is a strip
      // too narrow for the vertical join and a column that does not start at
      // row 0, so each became a snapshot of its own and the parent kept rows
      // 0 to 383: everything below row 384 was blurred as if far away. A
      // column that starts on the row where the parent's first column ended
      // joins the parent there. XE_METAL_DEPTH_QUADRANT_JOIN=0 restores
      // columns from row 0 only.
      static const bool s_depth_column_join = metal::ParseMetalEnvironmentFlag(
          std::getenv("XE_METAL_DEPTH_COLUMN_JOIN"), true);
      static const bool s_depth_quadrant_join =
          metal::ParseMetalEnvironmentFlag(
              std::getenv("XE_METAL_DEPTH_QUADRANT_JOIN"), true);
      if (!snap && s_depth_column_join &&
          render_target_cache_->sample_edram_raster_enabled() &&
          !resolve_info.copy_dest_info.copy_dest_array) {
        const auto& dca = resolve_info.copy_dest_coordinate_info;
        uint32_t dest_pitch = uint32_t(dca.pitch_aligned_div_32) << 5;
        if (dest_pitch > rw && !dca.offset_x_div_8 && !dca.offset_y_div_8) {
          uint32_t base0 = resolve_info.copy_dest_base;
          uint32_t x = 0;
          uint32_t y = 0;
          for (const auto& column : depth_column_pitches_) {
            if (column.second != dest_pitch ||
                resolve_info.copy_dest_base <= column.first) {
              continue;
            }
            uint32_t delta = resolve_info.copy_dest_base - column.first;
            for (uint32_t xx = 32; xx < dest_pitch; xx += 32) {
              if (uint32_t(texture_address::Tiled2D(int32_t(xx), 0, dest_pitch,
                                                    2)) == delta) {
                base0 = column.first;
                x = xx;
                break;
              }
            }
            if (x) {
              break;
            }
            // The second row of columns. The parent is 1280 wide, so its
            // snapshot has 720 rows whatever the first column's height.
            auto first_rows = depth_column_rows_.find(column.first);
            if (!s_depth_quadrant_join || dest_pitch < 1280 ||
                first_rows == depth_column_rows_.end() ||
                !first_rows->second || (first_rows->second & 31) ||
                first_rows->second + rh > 720) {
              continue;
            }
            for (uint32_t xx = 0; xx < dest_pitch; xx += 32) {
              if (uint32_t(texture_address::Tiled2D(
                      int32_t(xx), int32_t(first_rows->second), dest_pitch,
                      2)) == delta) {
                base0 = column.first;
                x = xx;
                y = first_rows->second;
                break;
              }
            }
            if (y) {
              break;
            }
          }
          if (x + rw <= dest_pitch) {
            void* column_snap = render_target_cache_->EnsureResolveSnapshot(
                base0, dest_pitch, rh, MTLPixelFormatR32Float);
            if (column_snap) {
              if (!depth_column_pitches_.count(base0)) {
                REXLOG_INFO(
                    "MetalResolve: depth column parent base={:08X} pitch={} "
                    "rows={} (first column {}x{})",
                    base0, dest_pitch, rh, rw, rh);
              }
              depth_column_pitches_[base0] = dest_pitch;
              if (!x && !y) {
                depth_column_rows_[base0] = rh;
              } else if (y) {
                static uint32_t s_quadrant_logs = 0;
                if (s_quadrant_logs++ < 8) {
                  REXLOG_INFO(
                      "MetalResolve: depth quadrant {:08X} {}x{} joins the "
                      "parent at {:08X} at ({}, {})",
                      resolve_info.copy_dest_base, rw, rh, base0, x, y);
                }
              }
              snap = column_snap;
              strip_x_offset = x;
              strip_y_offset = y;
              // The x = 0 column (re)registers the parent base; a later column
              // is a join and must not register.
              is_new_snapshot = !x && !y;
            }
          }
        }
      }
      if (!snap) {
        snap = render_target_cache_->EnsureResolveSnapshot(
            resolve_info.copy_dest_base, rw, rh, MTLPixelFormatR32Float);
        is_new_snapshot = snap != nullptr;
        strip_y_offset = 0;
      }
      // Per-owner conversion (the span can be owned piecewise): depth owners
      // read directly, color owners (raw EDRAM bits, e.g. the restored trace
      // snapshot) decode the guest 24-bit depth.
      bool is_float24 = resolve_info.depth_edram_info.format ==
                        uint32_t(xenos::DepthRenderTargetFormat::kD24FS8);
      bool resolved = false;
      if (snap && render_target_cache_->sample_edram_raster_enabled()) {
        resolved = render_target_cache_->PrepareCanonicalEdramForResolve(
                       span_base, span_row_length, span_rows, span_pitch) &&
                   render_target_cache_->ResolveCanonicalToSnapshot(
                       frame_command_buffer_, /*is_depth=*/true,
                       uint32_t(resolve_info.depth_edram_info.base_tiles),
                       uint32_t(resolve_info.depth_edram_info.pitch_tiles),
                       uint32_t(resolve_info.depth_edram_info.msaa_samples),
                       resolve_info.depth_edram_info.format,
                       /*is_64bpp=*/false,
                       uint32_t(resolve_info.coordinate_info
                                    .edram_offset_x_div_8)
                           << 3,
                       uint32_t(resolve_info.coordinate_info
                                    .edram_offset_y_div_8)
                           << 3,
                       uint32_t(resolve_info.copy_dest_coordinate_info
                                    .copy_sample_select),
                       /*dest_swap=*/false,
                       /*raw_copy=*/false,
                       snap, MTLPixelFormatR32Float, rw, rh, strip_y_offset,
                       1.0f, strip_x_offset);
      } else if (snap) {
        resolved = render_target_cache_->ResolveDepthToSnapshot(
            frame_command_buffer_, span_base, span_row_length, span_rows,
            span_pitch,
            uint32_t(resolve_info.depth_edram_info.msaa_samples), is_float24,
            snap, rw, rh, strip_y_offset);
      }
      if (resolved) {
        // A depth resolve cannot produce color layout metadata. Advance
        // provenance even when it reuses an existing snapshot so any prior
        // color layout at this base is rejected.
        ++resolve_snapshot_generation_[resolve_info.copy_dest_base];
      }
      if (resolved && is_new_snapshot) {
        texture_cache_->RegisterResolvedTarget(resolve_info.copy_dest_base,
                                               snap, rw, rh, /*is_depth=*/true,
                                               /*requires_fetch_swizzle=*/true,
                                               resolve_info.copy_dest_extent_start,
                                               resolve_info.copy_dest_extent_length);
      }
      // DEPTH RAM writeback: texture consumers get the snapshot (bridge),
      // but VFETCH consumers read guest RAM — JC2's memexport light-atlas VS
      // vfetches the 1024x1024 depth resolve at 121E1000, which stayed
      // permanently zero without this (the black-ambient root, one level
      // above the skipped exports). Blit the R32F snapshot to staging; the
      // canonical path stages the selected raw D24S8/D24FS8 word (including
      // stencil); the legacy fallback still packs its R32F snapshot.
      static const bool s_no_writeback_d =
          std::getenv("XE_METAL_NO_WRITEBACK") != nullptr;
      if (resolved && !s_no_writeback_d) {
        id<MTLDevice> wb_device = ((__bridge id<MTLTexture>)snap).device;
        // The staging buffer is allocated only when the GPU-resident scatter
        // below cannot take the resolve: a 720p depth resolve is a 3.6 MB
        // shared buffer, ~15 per Red Dead frame, that used to be created and
        // freed unused (~0.6% of the command-processor thread).
        // XE_METAL_DEPTH_STAGING_EAGER=1 restores the up-front allocation.
        static const bool s_depth_staging_eager =
            std::getenv("XE_METAL_DEPTH_STAGING_EAGER") != nullptr;
        id<MTLBuffer> staging =
            s_depth_staging_eager
                ? [wb_device newBufferWithLength:size_t(rw) * rh * 4u
                                         options:MTLResourceStorageModeShared]
                : nil;
        if (staging || !s_depth_staging_eager) {
          const bool canonical_depth_writeback =
              render_target_cache_->sample_edram_raster_enabled();
          bool writeback_encoded = false;
          // Stage B for depth (optimize-metal-gpu-resident-resolve-coherence):
          // scatter the raw guest words straight into the shared buffer under
          // the same eligibility as color; the record is then GPU-resident and
          // never needs a staging copy or a CPU drain wait.
          bool depth_scatter = false;
          // Resolve forwarding of the scatter (see the colour path).
          MetalSharedTextureCache::ResolveForwardTarget depth_forward_target;
          MetalRenderTargetCache::ResolveForward depth_forward;
          {
            const auto& dc_d = resolve_info.copy_dest_coordinate_info;
            uint32_t depth_extent_bytes = resolve_info.copy_dest_extent_start -
                                          resolve_info.copy_dest_base +
                                          resolve_info.copy_dest_extent_length;
            if (canonical_depth_writeback && GpuResolveScatterEnabled() &&
                shared_memory_ && depth_extent_bytes &&
                !resolve_info.copy_dest_info.copy_dest_array &&
                !resolve_info.copy_dest_info.copy_dest_layer) {
              id<MTLBuffer> depth_scatter_buffer =
                  (__bridge id<MTLBuffer>)shared_memory_->GetBuffer();
              auto dest_range = metal::GuestRange::FromBaseLength(
                  resolve_info.copy_dest_base, depth_extent_bytes);
              if (depth_scatter_buffer && dest_range &&
                  uint64_t(resolve_info.copy_dest_base) + depth_extent_bytes <=
                      depth_scatter_buffer.length) {
                bool overlapping_pending = false;
                for (const metal::PendingProducer& p :
                     SnapshotPendingProducers()) {
                  if (p.range.Overlaps(*dest_range) &&
                      p.state != metal::TransitState::kGpuCurrentShared) {
                    overlapping_pending = true;
                    break;
                  }
                }
                depth_scatter =
                    !overlapping_pending &&
                    shared_memory_->RequestRange(
                        resolve_info.copy_dest_extent_start,
                        resolve_info.copy_dest_extent_length);
              }
            }
            // Same null-buffer hazard as the color writeback (see there).
            static const bool s_depth_null_cb_legacy =
                std::getenv("XE_METAL_RESOLVE_NULL_CB_LEGACY") != nullptr;
            if (!s_depth_null_cb_legacy) {
              PrepareTransferCommandBuffer(uint32_t(metal::MetalTransferSite::kResolve));
            }
            if (depth_scatter) {
              MetalRenderTargetCache::CanonicalScatterDest depth_dest{
                  resolve_info.copy_dest_base,
                  (uint32_t(dc_d.pitch_aligned_div_32) << 5)
                      ? (uint32_t(dc_d.pitch_aligned_div_32) << 5)
                      : ((rw + 31u) & ~31u),
                  uint32_t(dc_d.offset_x_div_8) << 3,
                  uint32_t(dc_d.offset_y_div_8) << 3, depth_extent_bytes};
              if (shared_texture_cache_ && true &&
                  shared_texture_cache_->FindResolveForward(
                      depth_dest.dest_base, depth_dest.dest_pitch_aligned, 2u,
                      depth_dest.dest_offset_x, depth_dest.dest_offset_y, rw,
                      rh, depth_dest.dest_extent_bytes,
                      &depth_forward_target)) {
                depth_forward.texture = depth_forward_target.mtl_texture;
                depth_forward.kind = depth_forward_target.kind;
                depth_forward.endian = depth_forward_target.endian;
                depth_forward.width = depth_forward_target.width;
                depth_forward.height = depth_forward_target.height;
                depth_forward.origin_y = depth_forward_target.origin_y;
              }
              writeback_encoded =
                  render_target_cache_->ResolveCanonicalDepthToBuffer(
                      frame_command_buffer_,
                      uint32_t(resolve_info.depth_edram_info.base_tiles),
                      uint32_t(resolve_info.depth_edram_info.pitch_tiles),
                      uint32_t(resolve_info.depth_edram_info.msaa_samples),
                      resolve_info.depth_edram_info.format,
                      uint32_t(resolve_info.coordinate_info
                                   .edram_offset_x_div_8)
                          << 3,
                      uint32_t(resolve_info.coordinate_info
                                   .edram_offset_y_div_8)
                          << 3,
                      uint32_t(resolve_info.copy_dest_coordinate_info
                                   .copy_sample_select),
                      shared_memory_->GetBuffer(), rw, rh,
                      uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
                      &depth_dest,
                      depth_forward.texture ? &depth_forward : nullptr);
              if (!writeback_encoded) {
                depth_scatter = false;
              }
            }
            if (IssueCopyGpuResolveLog()) {
              // Same census as MetalGpuScatter for the depth path: which depth
              // resolves stay on the CPU writeback (their consumers then
              // commit and wait on the record instead of ordering after it).
              REXLOG_WARN(
                  "MetalDepthScatter draw={} base={:08X} {}x{} fmt={} msaa={} "
                  "pitch_aligned={} off=({},{}) extent={} canonical={} "
                  "encoded={} scatter={}",
                  uint32_t(trace_draw_index_), resolve_info.copy_dest_base, rw, rh,
                  uint32_t(resolve_info.depth_edram_info.format),
                  uint32_t(resolve_info.depth_edram_info.msaa_samples),
                  uint32_t(dc_d.pitch_aligned_div_32) << 5,
                  uint32_t(dc_d.offset_x_div_8) << 3,
                  uint32_t(dc_d.offset_y_div_8) << 3, depth_extent_bytes,
                  canonical_depth_writeback ? 1 : 0, writeback_encoded ? 1 : 0,
                  depth_scatter ? 1 : 0);
            }
          }
          if (!depth_scatter && !staging) {
            staging = [wb_device newBufferWithLength:size_t(rw) * rh * 4u
                                             options:MTLResourceStorageModeShared];
          }
          if (depth_scatter) {
            // Encoded above, straight into the shared buffer.
          } else if (!staging) {
            // Allocation failed: nothing to write back into.
          } else if (canonical_depth_writeback) {
            writeback_encoded =
                render_target_cache_->ResolveCanonicalDepthToBuffer(
                    frame_command_buffer_,
                    uint32_t(resolve_info.depth_edram_info.base_tiles),
                    uint32_t(resolve_info.depth_edram_info.pitch_tiles),
                    uint32_t(resolve_info.depth_edram_info.msaa_samples),
                    resolve_info.depth_edram_info.format,
                    uint32_t(resolve_info.coordinate_info
                                 .edram_offset_x_div_8)
                        << 3,
                    uint32_t(resolve_info.coordinate_info
                                 .edram_offset_y_div_8)
                        << 3,
                    uint32_t(resolve_info.copy_dest_coordinate_info
                                 .copy_sample_select),
                    (__bridge void*)staging, rw, rh);
          } else {
            id<MTLCommandBuffer> wb_cb =
                (__bridge id<MTLCommandBuffer>)frame_command_buffer_;
            id<MTLBlitCommandEncoder> wb_blit = [wb_cb blitCommandEncoder];
            wb_blit.label = @"cp:depth-writeback-blit";
            [wb_blit copyFromTexture:(__bridge id<MTLTexture>)snap
                          sourceSlice:0
                          sourceLevel:0
                         sourceOrigin:MTLOriginMake(strip_x_offset, strip_y_offset, 0)
                           sourceSize:MTLSizeMake(rw, rh, 1)
                             toBuffer:staging
                    destinationOffset:0
               destinationBytesPerRow:rw * 4
             destinationBytesPerImage:rw * rh * 4];
            [wb_blit endEncoding];
            writeback_encoded = true;
          }
          const auto& dc = resolve_info.copy_dest_coordinate_info;
          uint32_t extent_bytes = resolve_info.copy_dest_extent_start -
                                  resolve_info.copy_dest_base +
                                  resolve_info.copy_dest_extent_length;
          if (writeback_encoded && !depth_scatter &&
              IssueCopyGpuResolveLog()) {
            // CPU-staged depth writeback (never GPU-current).
            REXLOG_WARN(
                "MetalCpuWriteback draw={} base={:08X} {}x{} depth fmt={} "
                "slice={} array={} canonical={}",
                trace_draw_index_, resolve_info.copy_dest_base, rw, rh,
                uint32_t(resolve_info.copy_dest_info.copy_dest_format),
                uint32_t(resolve_info.copy_dest_info.copy_dest_layer),
                uint32_t(resolve_info.copy_dest_info.copy_dest_array),
                canonical_depth_writeback ? 1 : 0);
          }
          if (writeback_encoded) {
            void* staging_retained = nullptr;
            if (!depth_scatter) {
              staging_retained = (__bridge_retained void*)staging;
            }
            pending_writebacks_.push_back(PendingWriteback{
                staging_retained,
                resolve_info.copy_dest_base, rw, rh, 4u,
                depth_scatter
                    ? 0u
                    : uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
                uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
                uint32_t(dc.pitch_aligned_div_32) << 5,
                uint32_t(dc.offset_x_div_8) << 3,
                uint32_t(dc.offset_y_div_8) << 3, extent_bytes,
                uint32_t(dc.height_aligned_div_32) << 5,
                uint32_t(resolve_info.copy_dest_info.copy_dest_layer),
                uint32_t(resolve_info.copy_dest_info.copy_dest_array),
                /*swap_rb=*/0u,
                /*layout_swap_rb=*/0u,
                /*packed_bytes=*/0u,
                S7TagsOff() ? 0 : CurrentEncodingSubmission(),
                uint32_t(resolve_info.copy_dest_info.copy_dest_format),
                uint32_t(trace_draw_index_), swap_count_,
                /*depth_encode=*/canonical_depth_writeback
                    ? 0u
                    : (is_float24 ? 2u : 1u),
                ++memory_authority_sequence_});
            if (depth_scatter) {
              pending_writebacks_.back().gpu_current = 1u;
              RegisterGpuResidentResolve(resolve_info.copy_dest_base,
                                         extent_bytes);
              if (depth_forward.encoded) {
                shared_texture_cache_->CompleteResolveForward(
                    depth_forward_target);
              }
            }
          }
        }
      }
    }
  }
  // Resolve CLEARS: guests set render-target base values this way (JC2's
  // quarter-res scene multiplies by DESTINATION — an unset base of 0 blackens
  // the chain; shadow cascades clear depth between renders).
  {
    static const bool s_clear_req_log =
        std::getenv("XE_METAL_RESOLVE_LOG") != nullptr;
    if (s_clear_req_log) {
      REXLOG_WARN("MetalResolveClearReq @draw {}: copy_depth={} clear_color={} "
             "clear_depth={} copy_control={:08X} cb={}",
             trace_draw_index_, uint32_t(resolve_info.IsCopyingDepth()),
             uint32_t(resolve_info.IsClearingColor()),
             uint32_t(resolve_info.IsClearingDepth()),
             resolve_info.rb_copy_control.value,
             frame_command_buffer_ != nil);
    }
  }
  if ((resolve_info.IsClearingColor() || resolve_info.IsClearingDepth()) &&
      render_target_cache_ && frame_command_buffer_) {
    uint32_t span_base, span_row_length, span_rows, span_pitch;
    resolve_info.GetCopyEDRAMTileSpan(span_base, span_row_length, span_rows,
                                      span_pitch);
    {
      // Census own/other: the copied surface's span, plus the other surface a
      // dual clear names through its own edram_info.
      bool touches = false;
      if (frame_open_) {
        touches = render_target_cache_->ResolveSpanTouchesCurrentAttachments(
            span_base, span_row_length, span_rows, span_pitch);
        if (!touches && resolve_info.IsClearingDepth()) {
          uint32_t b, rl, r;
          ::rex::gpu::draw_state::GetResolveEDRAMTileSpan(resolve_info.depth_edram_info,
                                             resolve_info.coordinate_info,
                                             resolve_info.height_div_8, b, rl,
                                             r);
          touches = render_target_cache_->ResolveSpanTouchesCurrentAttachments(
              b, rl, r, uint32_t(resolve_info.depth_edram_info.pitch_tiles));
        }
        if (!touches && resolve_info.IsClearingColor()) {
          uint32_t b, rl, r;
          ::rex::gpu::draw_state::GetResolveEDRAMTileSpan(resolve_info.color_edram_info,
                                             resolve_info.coordinate_info,
                                             resolve_info.height_div_8, b, rl,
                                             r);
          touches = render_target_cache_->ResolveSpanTouchesCurrentAttachments(
              b, rl, r, uint32_t(resolve_info.color_edram_info.pitch_tiles));
        }
      }
      EndRenderEncoder(metal::MetalPassEndReason::kResolveClear, 0, touches);
    }
    static const bool s_clear_log =
        std::getenv("XE_METAL_RESOLVE_LOG") != nullptr;
    if (s_clear_log) {
      REXLOG_WARN(
          "MetalResolveClear @draw {}: color={} depth={} span base={} "
          "rowlen={} rows={} pitch={} c_edram(base={} pitch={} msaa={}) "
          "d_edram(base={} pitch={} msaa={}) clearval c={:08X} d={:08X}",
          trace_draw_index_, uint32_t(resolve_info.IsClearingColor()),
          uint32_t(resolve_info.IsClearingDepth()), span_base, span_row_length,
          span_rows, span_pitch, uint32_t(resolve_info.color_edram_info.base_tiles),
          uint32_t(resolve_info.color_edram_info.pitch_tiles),
          uint32_t(resolve_info.color_edram_info.msaa_samples),
          uint32_t(resolve_info.depth_edram_info.base_tiles),
          uint32_t(resolve_info.depth_edram_info.pitch_tiles),
          uint32_t(resolve_info.depth_edram_info.msaa_samples),
          resolve_info.rb_color_clear, resolve_info.rb_depth_clear);
    }
    // Each clear must use ITS OWN surface's tile span: GetCopyEDRAMTileSpan
    // returns the span of the surface being COPIED (color unless
    // IsCopyingDepth), but a dual clear also names the OTHER surface via its
    // own edram_info. Passing the color span (base 768) to the depth clear
    // found no depth owners there and silently did nothing — the guest's
    // depth never cleared between the 720p half-passes, and the composite's
    // depth tests ran against the previous half's stale depth (the hard
    // half-screen seam: sky/objects failing GE tests only below y=384).
    const bool canonical_clear =
        render_target_cache_->sample_edram_raster_enabled();
    const uint32_t clear_source_x =
        uint32_t(resolve_info.coordinate_info.edram_offset_x_div_8) << 3;
    const uint32_t clear_source_y =
        uint32_t(resolve_info.coordinate_info.edram_offset_y_div_8) << 3;
    const uint32_t clear_width =
        uint32_t(uint32_t(resolve_info.coordinate_info.width_div_8)) << 3;
    const uint32_t clear_height = resolve_info.height_div_8 << 3;
    // Match the reference backends' command order. If the declared depth and
    // color spans alias, the later color clear is the final physical producer.
    if (resolve_info.IsClearingDepth()) {
      uint32_t dbase, drowlen, drows;
      ::rex::gpu::draw_state::GetResolveEDRAMTileSpan(resolve_info.depth_edram_info,
                                         resolve_info.coordinate_info,
                                         resolve_info.height_div_8, dbase,
                                         drowlen, drows);
      bool cleared = canonical_clear &&
                     render_target_cache_->PerformCanonicalResolveClear(
                         frame_command_buffer_, dbase, drowlen, drows,
                         uint32_t(resolve_info.depth_edram_info.pitch_tiles),
                         uint32_t(resolve_info.depth_edram_info.base_tiles),
                         uint32_t(resolve_info.depth_edram_info.pitch_tiles),
                         uint32_t(
                             resolve_info.depth_edram_info.msaa_samples),
                         /*is_depth=*/true, /*is_64bpp=*/false,
                         clear_source_x, clear_source_y, clear_width,
                         clear_height, resolve_info.rb_depth_clear,
                         resolve_info.rb_depth_clear);
      if (!cleared) {
        render_target_cache_->PerformResolveClear(
            frame_command_buffer_, dbase, drowlen, drows,
            uint32_t(resolve_info.depth_edram_info.pitch_tiles), /*is_depth=*/true,
            resolve_info.rb_depth_clear);
      }
    }
    if (resolve_info.IsClearingColor()) {
      // The packed clear value's low and high dwords (Canary 16e1eb8e2): for
      // 64bpp formats RB_COLOR_CLEAR_LO is the low dword (red | green << 16
      // for 16_16_16_16, red for 32_32_FLOAT) and RB_COLOR_CLEAR the high;
      // 32bpp clears take only RB_COLOR_CLEAR.
      const bool color_64bpp =
          resolve_info.color_edram_info.format_is_64bpp != 0;
      const uint32_t color_clear_lo = color_64bpp
                                          ? resolve_info.rb_color_clear_lo
                                          : resolve_info.rb_color_clear;
      const uint32_t color_clear_hi = resolve_info.rb_color_clear;
      uint32_t cbase, crowlen, crows;
      ::rex::gpu::draw_state::GetResolveEDRAMTileSpan(resolve_info.color_edram_info,
                                         resolve_info.coordinate_info,
                                         resolve_info.height_div_8, cbase,
                                         crowlen, crows);
      bool cleared = canonical_clear &&
                     render_target_cache_->PerformAttachmentColorResolveClear(
                         frame_command_buffer_, cbase, crowlen, crows,
                         uint32_t(resolve_info.color_edram_info.pitch_tiles),
                         uint32_t(resolve_info.color_edram_info.base_tiles),
                         uint32_t(resolve_info.color_edram_info.pitch_tiles),
                         uint32_t(
                             resolve_info.color_edram_info.msaa_samples),
                         resolve_info.color_edram_info.format_is_64bpp != 0,
                         clear_source_x, clear_source_y, clear_width,
                         clear_height, color_clear_lo, color_clear_hi);
      cleared = cleared ||
                (canonical_clear &&
                     render_target_cache_->PerformCanonicalResolveClear(
                         frame_command_buffer_, cbase, crowlen, crows,
                         uint32_t(resolve_info.color_edram_info.pitch_tiles),
                         uint32_t(resolve_info.color_edram_info.base_tiles),
                         uint32_t(resolve_info.color_edram_info.pitch_tiles),
                         uint32_t(
                             resolve_info.color_edram_info.msaa_samples),
                         /*is_depth=*/false,
                         resolve_info.color_edram_info.format_is_64bpp != 0,
                         clear_source_x, clear_source_y, clear_width,
                         clear_height, color_clear_lo, color_clear_hi));
      if (!cleared) {
        if (IssueCopyCanonicalSyncLog()) {
          REXLOG_WARN("MetalCanonicalSync colour-clear FALLBACK draw={} canonical={} "
                 "base={} pitch={} msaa={} 64bpp={} span=[{},+{}x{}] "
                 "rect=({},{} {}x{})",
                 trace_draw_index_, canonical_clear,
                 uint32_t(resolve_info.color_edram_info.base_tiles),
                 uint32_t(resolve_info.color_edram_info.pitch_tiles),
                 uint32_t(resolve_info.color_edram_info.msaa_samples),
                 uint32_t(resolve_info.color_edram_info.format_is_64bpp), cbase, crowlen,
                 crows, clear_source_x, clear_source_y, clear_width,
                 clear_height);
        }
        render_target_cache_->PerformResolveClear(
            frame_command_buffer_, cbase, crowlen, crows,
            uint32_t(resolve_info.color_edram_info.pitch_tiles), /*is_depth=*/false,
            resolve_info.rb_color_clear);
      }
    }
  }
  // Gamma-parity diagnostic (XE_METAL_GAMMA_PARITY=1): record each color
  // resolve's dest base -> whether its EDRAM SOURCE format was
  // k_8_8_8_8_GAMMA. Raw resolves preserve the byte domain, so a consumer
  // fetch's gamma signs must MATCH the source's gamma-ness; a mismatch means
  // our derived RT format (and thus the PS gamma-encode flag) disagrees with
  // the game's own declaration — the non-cancelling leg of the history
  // cycle (the temporal-oscillator hunt).
  static const bool s_gamma_parity = std::getenv("XE_METAL_GAMMA_PARITY");
  if (s_gamma_parity && !resolve_info.IsCopyingDepth()) {
    bool src_gamma = resolve_info.color_edram_info.format ==
                     uint32_t(xenos::ColorRenderTargetFormat::k_8_8_8_8_GAMMA);
    gamma_parity_resolves_[resolve_info.copy_dest_base] = src_gamma;
  }
  static uint32_t s_copy_count = 0;
  if (s_copy_count++ < 256) {
    REXLOG_INFO(
        "MetalCommandProcessor::IssueCopy draw={} dest_base={:08X} "
        "extent=[{:08X}+{}] depth={} fmt={} w_div8={} h_div8={} "
        "src(base_tiles={} pitch_tiles={} msaa={} fmt={}) "
        "edram_off=({},{}) dest_pitch={} dest_swap={} sample_select={} "
        "dest_endian={} dest_number={} dest_exp_bias={} dest_coord=({},{})",
        trace_draw_index_, resolve_info.copy_dest_base,
        resolve_info.copy_dest_extent_start,
        resolve_info.copy_dest_extent_length, resolve_info.IsCopyingDepth(),
        uint32_t(resolve_info.copy_dest_info.copy_dest_format),
        uint32_t(resolve_info.coordinate_info.width_div_8), resolve_info.height_div_8,
        resolve_info.IsCopyingDepth() ? uint32_t(resolve_info.depth_edram_info.base_tiles)
                                      : uint32_t(resolve_info.color_edram_info.base_tiles),
        resolve_info.IsCopyingDepth() ? uint32_t(resolve_info.depth_edram_info.pitch_tiles)
                                      : uint32_t(resolve_info.color_edram_info.pitch_tiles),
        resolve_info.IsCopyingDepth()
            ? uint32_t(resolve_info.depth_edram_info.msaa_samples)
            : uint32_t(resolve_info.color_edram_info.msaa_samples),
        uint32_t(resolve_info.IsCopyingDepth() ? resolve_info.depth_edram_info.format
                                               : resolve_info.color_edram_info.format),
        resolve_info.coordinate_info.edram_offset_x_div_8 << 3,
        resolve_info.coordinate_info.edram_offset_y_div_8 << 3,
        resolve_info.copy_dest_coordinate_info.pitch_aligned_div_32 << 5,
        uint32_t(resolve_info.copy_dest_info.copy_dest_swap),
        uint32_t(resolve_info.copy_dest_coordinate_info.copy_sample_select),
        uint32_t(resolve_info.copy_dest_info.copy_dest_endian),
        uint32_t(resolve_info.copy_dest_info.copy_dest_number),
        int32_t(resolve_info.copy_dest_info.copy_dest_exp_bias),
        resolve_info.copy_dest_coordinate_info.offset_x_div_8 << 3,
        resolve_info.copy_dest_coordinate_info.offset_y_div_8 << 3);
  }
  // Experiment (XE_METAL_SERIALIZE_RESOLVES): commit+wait after each resolve so
  // every snapshot blit fully completes before any later draw samples it. Far
  // cheaper than per-draw serialization (dozens of resolves/frame). If the tile
  // stipple clears under this, the defect is a resolve->sample inter-pass GPU
  // hazard (bindless-sampled snapshots not ordered after their resolve blit).
  static const bool s_serialize_resolves =
      std::getenv("XE_METAL_SERIALIZE_RESOLVES") != nullptr;
  if (s_serialize_resolves) {
    EndFrameEncoderAndWait(metal::SeamBoundaryReason::kDebugProbe);
  }
  // XE_METAL_RESOLVE_DUMP: after each resolve completes, write its destination
  // extent's guest bytes to /tmp/xe_rd_<draw>_<base>.bin, so a 1x and a scaled
  // replay can be compared resolve by resolve.
  // XE_METAL_RESOLVE_DUMP=1 dumps every resolve (replay use);
  // XE_METAL_RESOLVE_DUMP=<hex dest base>[:<every>] dumps only resolves to
  // that destination base, every <every>-th one (live use: one pass output
  // at a comparable cost to a screenshot).
  struct ResolveDumpSpec {
    bool enabled;
    uint32_t base;
    uint32_t every;
  };
  static const ResolveDumpSpec s_resolve_dump_spec = [] {
    const char* v = std::getenv("XE_METAL_RESOLVE_DUMP");
    if (!v) return ResolveDumpSpec{false, 0u, 1u};
    if (!strcmp(v, "1")) return ResolveDumpSpec{true, 0u, 1u};
    char* end = nullptr;
    uint32_t base = uint32_t(strtoul(v, &end, 16));
    // ":trace" = only while a frame trace is being recorded (every = 0), so
    // the live bytes and the trace's replay describe the same frame.
    uint32_t every = 1u;
    if (end && *end == ':') {
      every = !strcmp(end + 1, "trace") ? 0u
                                        : uint32_t(strtoul(end + 1, nullptr, 10));
      if (every == 0u && strcmp(end + 1, "trace") != 0) every = 1u;
    }
    return ResolveDumpSpec{true, base, every};
  }();
  static uint32_t s_resolve_dump_seen = 0;
  const bool s_resolve_dump =
      s_resolve_dump_spec.enabled &&
      (!s_resolve_dump_spec.base ||
       (resolve_info.copy_dest_base == s_resolve_dump_spec.base &&
        (s_resolve_dump_spec.every == 0u
             ? (false && (++s_resolve_dump_seen, true))
             : (++s_resolve_dump_seen % s_resolve_dump_spec.every) == 0)));
  if (s_resolve_dump && resolve_info.copy_dest_extent_length) {
    EndFrameEncoderAndWait(metal::SeamBoundaryReason::kDebugProbe);
    std::string path =
        s_resolve_dump_spec.base
            ? fmt::format("/tmp/xe_rd_s{}_{:08X}_{}.bin", swap_count_,
                          resolve_info.copy_dest_base, s_resolve_dump_seen)
            : fmt::format("/tmp/xe_rd_{:06}_{:08X}.bin", trace_draw_index_,
                          resolve_info.copy_dest_base);
    if (FILE* f = fopen(path.c_str(), "wb")) {
      // The shared buffer, not guest RAM: GPU-resident publication leaves
      // resolved bytes only in the buffer.
      shared_memory_->EnsureCpuCurrent(resolve_info.copy_dest_extent_start,
                                       resolve_info.copy_dest_extent_length);
      id<MTLBuffer> shared_buffer =
          (__bridge id<MTLBuffer>)shared_memory_->GetCpuBuffer();
      fwrite(static_cast<const uint8_t*>([shared_buffer contents]) +
                 resolve_info.copy_dest_extent_start,
             1, resolve_info.copy_dest_extent_length, f);
      fclose(f);
    }
  }
  return true;
}

// metal_eager_publish_title: demand-driven publication is on or off for a
// whole title, and off is exactly the XE_METAL_LAZY_PUBLISH=0 state (no read
// callback, so nothing arms and swaps / fence packets publish eagerly). Rise
// of the Tomb Raider needs it off: its XenonFlush thread writes pages that a
// memory export in the open or just-committed submission still owns about
// once every two seconds of gameplay (MetalLazyStale, 153 in a 260 s run on
// an M5 Max), and the frame flashes white, draws its snow particles as huge
// rings, or goes false-colour at about that rate. Which copy is wrong is not
// established: waiting under the lock (XE_METAL_LAZY_LOCKED_WAIT=1) left 42
// stale writes, all owned by the open submission, and as many flashes;
// completion waits and serialized submissions change nothing. Eager
// publication: 0 flash frames in 725 one-second shots (2026-11-14).
// The mode only changes while nothing is armed, so a record is never left
// owning pages that no callback serves.

void MetalCommandProcessor::InitializeShaderStorage(
    const std::filesystem::path& cache_root, uint32_t title_id, bool blocking) {
  REXLOG_INFO("MetalShaderStorage: backend entry, cache_root='{}' title {:08X}", cache_root.string(), title_id);
  // Qualified so it binds to the base implementation: the unqualified four-argument form forwards back to this
  // three-argument virtual, which was an immediate infinite recursion once this override existed.
  CommandProcessor::InitializeShaderStorage(cache_root, title_id, blocking);
  // Title/session boundary, after the title's config is loaded: apply the
  // per-title publication mode.
  
  // Title/session boundary: start a fresh unrouted-export reporting session.
  // Touches only the reporter's own counters -- no cache state, no guest state.
  memexport_gap_reporter_.Reset();
  // Title/session boundary: the base class re-seeds its default ramp without
  // invoking the write hook, so re-arm rather than trusting the flag to have
  // survived.
  gamma_ramp_dirty_ = true;
  if (pipeline_cache_) {
    pipeline_cache_->InitializeDurableStorage(cache_root, title_id);
    // After the durable caches open, so rebuilt pipelines hit them.
    pipeline_cache_->InitializeShaderStorage(cache_root, title_id);
  }
}

void MetalCommandProcessor::SaveShaderStorageToDisk() {
  // The app quits through std::quick_exit right after this (GPU paused), so it
  // is the last point at which the session's new pipelines can be persisted.
  if (pipeline_cache_) {
    pipeline_cache_->SaveBinaryArchive("exit", true);
    pipeline_cache_->ShutdownShaderStorage();
  }
}



bool MetalCommandProcessor::EncodeSwapFxaa(void* command_buffer_ptr,
                                           void* mailbox_ptr, bool extreme) {
  id<MTLCommandBuffer> command_buffer =
      (__bridge id<MTLCommandBuffer>)command_buffer_ptr;
  id<MTLTexture> mailbox = (__bridge id<MTLTexture>)mailbox_ptr;
  id<MTLDevice> device = mailbox.device;
  const uint32_t index = extreme ? 1 : 0;
  if (swap_fxaa_pipeline_format_ != uint64_t(mailbox.pixelFormat)) {
    for (uint32_t i = 0; i < 2; ++i) {
      if (swap_fxaa_pipelines_[i]) {
        id<MTLRenderPipelineState> old_pipeline =
            (__bridge_transfer id<MTLRenderPipelineState>)
                swap_fxaa_pipelines_[i];
        (void)old_pipeline;
        swap_fxaa_pipelines_[i] = nullptr;
      }
      swap_fxaa_pipeline_failed_[i] = false;
    }
    swap_fxaa_pipeline_format_ = uint64_t(mailbox.pixelFormat);
  }
  if (!swap_fxaa_pipelines_[index]) {
    if (swap_fxaa_pipeline_failed_[index]) {
      return false;
    }
    NSError* error = nil;
    id<MTLLibrary> library =
        [device newLibraryWithSource:(extreme ? kMetalFxaaExtremeShader
                                              : kMetalFxaaShader)
                             options:nil
                               error:&error];
    id<MTLRenderPipelineState> pipeline = nil;
    if (library) {
      MTLRenderPipelineDescriptor* descriptor =
          [[MTLRenderPipelineDescriptor alloc] init];
      descriptor.label = extreme ? @"cp:swap-fxaa-extreme" : @"cp:swap-fxaa";
      descriptor.vertexFunction = [library newFunctionWithName:@"xe_fxaa_vs"];
      descriptor.fragmentFunction =
          [library newFunctionWithName:@"xe_fxaa_fs"];
      descriptor.colorAttachments[0].pixelFormat = mailbox.pixelFormat;
      pipeline = [device newRenderPipelineStateWithDescriptor:descriptor
                                                        error:&error];
    }
    if (!pipeline) {
      REXLOG_ERROR("MetalFxaa: pipeline creation failed: {}",
             error ? error.localizedDescription.UTF8String : "unknown");
      swap_fxaa_pipeline_failed_[index] = true;
      return false;
    }
    swap_fxaa_pipelines_[index] = (__bridge_retained void*)pipeline;
  }
  if (!swap_fxaa_sampler_) {
    MTLSamplerDescriptor* descriptor = [[MTLSamplerDescriptor alloc] init];
    descriptor.minFilter = MTLSamplerMinMagFilterLinear;
    descriptor.magFilter = MTLSamplerMinMagFilterLinear;
    descriptor.mipFilter = MTLSamplerMipFilterNotMipmapped;
    descriptor.sAddressMode = MTLSamplerAddressModeClampToEdge;
    descriptor.tAddressMode = MTLSamplerAddressModeClampToEdge;
    id<MTLSamplerState> sampler =
        [device newSamplerStateWithDescriptor:descriptor];
    if (!sampler) {
      return false;
    }
    swap_fxaa_sampler_ = (__bridge_retained void*)sampler;
  }
  // The pass cannot read the texture it renders to, so it reads a copy, kept
  // at the mailbox's size and format.
  id<MTLTexture> source = (__bridge id<MTLTexture>)swap_fxaa_source_texture_;
  if (source && (source.width != mailbox.width ||
                 source.height != mailbox.height ||
                 source.pixelFormat != mailbox.pixelFormat)) {
    id<MTLTexture> old_source =
        (__bridge_transfer id<MTLTexture>)swap_fxaa_source_texture_;
    (void)old_source;
    swap_fxaa_source_texture_ = nullptr;
    source = nil;
  }
  if (!source) {
    MTLTextureDescriptor* descriptor = [MTLTextureDescriptor
        texture2DDescriptorWithPixelFormat:mailbox.pixelFormat
                                     width:mailbox.width
                                    height:mailbox.height
                                 mipmapped:NO];
    descriptor.usage = MTLTextureUsageShaderRead;
    descriptor.storageMode = MTLStorageModePrivate;
    source = [device newTextureWithDescriptor:descriptor];
    if (!source) {
      return false;
    }
    source.label = @"cp:swap-fxaa-source";
    swap_fxaa_source_texture_ = (__bridge_retained void*)source;
  }
  id<MTLBlitCommandEncoder> blit = [command_buffer blitCommandEncoder];
  [blit copyFromTexture:mailbox
            sourceSlice:0
            sourceLevel:0
           sourceOrigin:MTLOriginMake(0, 0, 0)
             sourceSize:MTLSizeMake(mailbox.width, mailbox.height, 1)
              toTexture:source
       destinationSlice:0
       destinationLevel:0
      destinationOrigin:MTLOriginMake(0, 0, 0)];
  [blit endEncoding];
  MTLRenderPassDescriptor* pass =
      [MTLRenderPassDescriptor renderPassDescriptor];
  pass.colorAttachments[0].texture = mailbox;
  pass.colorAttachments[0].loadAction = MTLLoadActionDontCare;
  pass.colorAttachments[0].storeAction = MTLStoreActionStore;
  id<MTLRenderCommandEncoder> encoder =
      [command_buffer renderCommandEncoderWithDescriptor:pass];
  [encoder setRenderPipelineState:(__bridge id<MTLRenderPipelineState>)
                                      swap_fxaa_pipelines_[index]];
  [encoder setFragmentTexture:source atIndex:0];
  [encoder setFragmentSamplerState:(__bridge id<MTLSamplerState>)
                                       swap_fxaa_sampler_
                           atIndex:0];
  [encoder drawPrimitives:MTLPrimitiveTypeTriangle
              vertexStart:0
              vertexCount:3];
  [encoder endEncoding];
  if (!swap_fxaa_applications_++) {
    REXLOG_INFO("MetalFxaa: anti-aliasing the guest output ({}, {}x{})",
           extreme ? "fxaa_extreme" : "fxaa", uint32_t(mailbox.width),
           uint32_t(mailbox.height));
  }
  return true;
}

// The base implementation is preserved by calling through, so guest ramp
// tracking is unchanged.
void MetalCommandProcessor::OnGammaRamp256EntryTableValueWritten() {
  CommandProcessor::OnGammaRamp256EntryTableValueWritten();
  // Mark stale so the next swap re-uploads. Deliberately unconditional on the
  // switch: the flag is a single bool with no allocation behind it, and gating
  // it would let a ramp written while disabled be missed if the switch were
  // ever flipped at runtime. Nothing is uploaded until IssueSwap looks.
  gamma_ramp_dirty_ = true;
}

void MetalCommandProcessor::OnGammaRampPWLValueWritten() {
  CommandProcessor::OnGammaRampPWLValueWritten();
  ++gamma_pwl_writes_;
}

bool MetalCommandProcessor::PwlGammaSelected() {
  if (!::rex::graphics::metal::GetMetalSettings().metal_pwl_gamma.Get()) {
    return false;
  }
  const uint32_t control = (*register_file_)[XE_GPU_REG_DC_LUTA_CONTROL];
  if (control == kPwlGammaControlIncrement3) {
    return true;
  }
  if (control) {
    // Never observed (docs/dev/metal_pwl_gamma_audit.md): present through the
    // 256-entry table rather than guess the field layout.
    static bool s_logged = false;
    if (!s_logged) {
      s_logged = true;
      REXLOG_WARN("MetalPwlGamma: DC_LUTA_CONTROL {:08X} is not the observed "
             "increment-3 PWL encoding; using the 256-entry table",
             control);
    }
  }
  return false;
}

void* MetalCommandProcessor::PwlRampBufferForSwap(void* device_opaque) {
  id<MTLDevice> device = (__bridge id<MTLDevice>)device_opaque;
  void*& slot = pwl_ramp_ring_[swap_count_ % kGammaRampRing];
  if (!slot) {
    id<MTLBuffer> buf =
        [device newBufferWithLength:kPwlGammaTableBytes
                            options:MTLResourceStorageModeShared];
    if (!buf) {
      return nullptr;
    }
    buf.label = @"cp:gamma-pwl";
    slot = (__bridge_retained void*)buf;
  }
  id<MTLBuffer> buf = (__bridge id<MTLBuffer>)slot;
  // A ring slot is reused only after the swaps that could read it retired.
  // XE_METAL_PRESENT_GAMMA=<g>: replace the guest's display curve with a plain power curve, so the presented image
  // can be matched to a reference by eye while the cause of a lift is being found. g > 1 darkens, g < 1 lifts. The
  // guest's own ramp is untouched and comes back the moment the variable is unset.
  static const float s_present_gamma = [] {
    const char* v = std::getenv("XE_METAL_PRESENT_GAMMA");
    return v ? float(atof(v)) : 1.0f;
  }();
  if (s_present_gamma > 0.0f && s_present_gamma != 1.0f) {
    auto* dst = static_cast<reg::DC_LUT_PWL_DATA*>(buf.contents);
    for (uint32_t i = 0; i < kPwlGammaEntries; ++i) {
      const float in = float(i * 8) / 1023.0f;
      const float out = std::pow(in, s_present_gamma);
      const uint32_t base = uint32_t(std::lround(std::min(out, 1.0f) * 1023.0f * 64.0f));
      for (uint32_t ch = 0; ch < 3; ++ch) {
        dst[i * 3 + ch].base = uint16_t(base);
        dst[i * 3 + ch].delta = 512;
      }
    }
  } else
  std::memcpy(buf.contents, GetGammaRampPWLRGB(), kPwlGammaTableBytes);
  // XE_METAL_GAMMA_DUMP=<swap>: dump the ramp the shader will read, once, at or after that guest swap. The applied
  // ramp is the first thing to look at when the presented picture has the right geometry and the wrong tone, and at
  // the first present the guest has not finished programming it.
  {
    static const uint32_t s_dump_swap = [] {
      const char* v = std::getenv("XE_METAL_GAMMA_DUMP");
      return v ? uint32_t(strtoul(v, nullptr, 10)) : 0u;
    }();
    static bool s_logged = false;
    if (s_dump_swap && !s_logged && swap_count_ >= s_dump_swap) {
      s_logged = true;
      const reg::DC_LUT_PWL_DATA* t = GetGammaRampPWLRGB();
      const reg::DC_LUT_30_COLOR* t256 = GetGammaRamp256EntryTable();
      REXLOG_WARN("MetalGammaRampAtSwap {}: pwl_selected {} control {:08X}", swap_count_,
                  PwlGammaSelected() ? 1 : 0, (*register_file_)[XE_GPU_REG_DC_LUTA_CONTROL]);
      for (uint32_t i : {0u, 32u, 64u, 96u, 127u}) {
        REXLOG_WARN("MetalGammaRampAtSwap pwl[{}] R {:04X} G {:04X} B {:04X}", i, t[i * 3 + 0].value,
                    t[i * 3 + 1].value, t[i * 3 + 2].value);
      }
      for (uint32_t i : {0u, 64u, 128u, 192u, 255u}) {
        REXLOG_WARN("MetalGammaRampAtSwap table256[{}] R {} G {} B {}", i, t256[i].color_10_red,
                    t256[i].color_10_green, t256[i].color_10_blue);
      }
    }
  }
  return slot;
}

void* MetalCommandProcessor::PwlGammaPipeline(void* device_opaque,
                                              uint64_t pixel_format,
                                              bool array) {
  void*& slot = array ? pwl_pipeline_array_ : pwl_pipeline_2d_;
  if (slot) {
    id<MTLRenderPipelineState> ps = (__bridge id<MTLRenderPipelineState>)slot;
    (void)ps;
    return slot;
  }
  id<MTLDevice> device = (__bridge id<MTLDevice>)device_opaque;
  NSError* err = nil;
  id<MTLLibrary> lib =
      [device newLibraryWithSource:kMetalPwlGammaShader
                           options:MetalPwlGammaCompileOptions()
                             error:&err];
  if (!lib) {
    REXLOG_ERROR("MetalPwlGamma: library failed: {}",
           err ? err.localizedDescription.UTF8String : "unknown");
    return nullptr;
  }
  MTLRenderPipelineDescriptor* d = [[MTLRenderPipelineDescriptor alloc] init];
  d.vertexFunction = [lib newFunctionWithName:@"xe_pwl_vs"];
  d.fragmentFunction =
      [lib newFunctionWithName:array ? @"xe_pwl_fs_array" : @"xe_pwl_fs_2d"];
  d.colorAttachments[0].pixelFormat = MTLPixelFormat(pixel_format);
  id<MTLRenderPipelineState> ps =
      [device newRenderPipelineStateWithDescriptor:d error:&err];
  if (!ps) {
    REXLOG_ERROR("MetalPwlGamma: pipeline failed: {}",
           err ? err.localizedDescription.UTF8String : "unknown");
    return nullptr;
  }
  slot = (__bridge_retained void*)ps;
  return slot;
}

// Guest gamma-state census — implement-metal-pwl-gamma-ramp task 1.5, and the
// instrument that would LIFT that change's NO-GO. Bounded: logs only when the
// structured signature below changes.
//
// COST WHEN DISABLED, stated accurately rather than as "zero": one call and one
// predictable branch on a function-local static per SWAP (not per draw), one
// unconditional increment in OnGammaRampPWLValueWritten, and 24 bytes of member
// state. The table hash and the asymmetry scan happen only when enabled. That is
// small enough to leave in, and it is not nothing.
//
// RETAINED rather than removed with the rest of the audit scaffolding: the
// audit stopped because DC_LUTA_CONTROL has only ever been observed holding two
// values and no title with asymmetric PWL channels has been found
// (docs/dev/metal_pwl_gamma_audit.md §7). More census coverage over more titles is
// precisely what would settle the bit layout, the valid increment domain, and
// the RGB write order. Re-run it over any new corpus.
//
// Deliberately reports RAW state and performs NO engagement classification. Two
// reasons, both measured: the default PWL table is nonzero and byte-identical
// to 4D5307E6's sRGB setup ramp, so content proves nothing; and SetGammaRamp's
// trace-restore path fires the written-callback, so a nonzero write count
// proves nothing either. The removed PWL identity classifier failed on exactly
// the first of these.
void MetalCommandProcessor::CensusGammaState() {
  static const bool s_enabled = [] {
    const char* v = std::getenv("XE_GAMMA_CENSUS");
    return v && v[0] == '1';
  }();
  if (!s_enabled) {
    return;
  }
  const auto& regs = *register_file_;
  const uint32_t control = regs[XE_GPU_REG_DC_LUTA_CONTROL];
  const uint32_t rw_mode = regs[XE_GPU_REG_DC_LUT_RW_MODE];
  const uint32_t write_en = regs[XE_GPU_REG_DC_LUT_WRITE_EN_MASK];
  const uint32_t black_b = regs[XE_GPU_REG_DC_LUTA_BLACK_OFFSET_BLUE];
  const uint32_t black_g = regs[XE_GPU_REG_DC_LUTA_BLACK_OFFSET_GREEN];
  const uint32_t black_r = regs[XE_GPU_REG_DC_LUTA_BLACK_OFFSET_RED];
  const uint32_t white_b = regs[XE_GPU_REG_DC_LUTA_WHITE_OFFSET_BLUE];
  const uint32_t white_g = regs[XE_GPU_REG_DC_LUTA_WHITE_OFFSET_GREEN];
  const uint32_t white_r = regs[XE_GPU_REG_DC_LUTA_WHITE_OFFSET_RED];

  // Content hash of the full PWL table, plus whether the three channels are
  // byte-identical. Channel ASYMMETRY is the fact that would let the corpus
  // resolve the unverified R,G,B write order; symmetric tables cannot.
  const reg::DC_LUT_PWL_DATA* pwl = GetGammaRampPWLRGB();
  const uint64_t pwl_hash = XXH3_64bits(pwl, sizeof(reg::DC_LUT_PWL_DATA) * 128 * 3);
  bool channels_asymmetric = false;
  bool pwl_all_zero = true;
  for (uint32_t entry = 0; entry < 128; ++entry) {
    const reg::DC_LUT_PWL_DATA* triple = pwl + entry * 3;
    if (triple[0].value != triple[1].value || triple[1].value != triple[2].value) {
      channels_asymmetric = true;
    }
    if (triple[0].value || triple[1].value || triple[2].value) {
      pwl_all_zero = false;
    }
  }
  // Structured signature over EVERY field this line reports. A hand-rolled XOR
  // of a subset was the first attempt and it was a real blind spot: write_en,
  // four of the six offsets and the exact write count could all change without
  // producing a new line — in an instrument whose entire job is catching rare
  // state. Packing the reported fields and hashing the struct makes "reported"
  // and "compared" the same set by construction, so adding a field to the log
  // without adding it here is no longer possible without editing this struct.
  struct CensusSignatureFields {
    uint64_t pwl_hash;
    uint64_t pwl_writes;
    uint32_t control;
    uint32_t rw_mode;
    uint32_t write_en;
    uint32_t black_b, black_g, black_r;
    uint32_t white_b, white_g, white_r;
    uint32_t channels_asymmetric;
    uint32_t pwl_all_zero;
  } fields = {pwl_hash,   gamma_pwl_writes_,
              control,    rw_mode,
              write_en,   black_b,
              black_g,    black_r,
              white_b,    white_g,
              white_r,    channels_asymmetric ? 1u : 0u,
              pwl_all_zero ? 1u : 0u};
  const uint64_t signature = XXH3_64bits(&fields, sizeof(fields));
  if (signature == gamma_census_signature_ && gamma_census_reports_) {
    return;
  }
  gamma_census_signature_ = signature;
  ++gamma_census_reports_;
  REXLOG_INFO(
      "GammaCensus|swap={}|DC_LUTA_CONTROL={:08X}|RW_MODE={:08X}|WRITE_EN={:08X}"
      "|pwl_writes={}|pwl_hash={:016X}|pwl_all_zero={}|channels_asymmetric={}"
      "|black_bgr={:08X}/{:08X}/{:08X}|white_bgr={:08X}/{:08X}/{:08X}",
      swap_count_, control, rw_mode, write_en, gamma_pwl_writes_, pwl_hash,
      pwl_all_zero ? 1 : 0, channels_asymmetric ? 1 : 0, black_b, black_g,
      black_r, white_b, white_g, white_r);
}


std::string MetalCommandProcessor::GetCaptureDeviceInfoJson() const {
  auto* provider = static_cast<rex::ui::metal::MetalProvider*>(
      GetGraphicsDriver().GetProvider());
  id<MTLDevice> device =
      provider ? (__bridge id<MTLDevice>)provider->device() : nil;
  if (!device) {
    return std::string();
  }
  const char* device_name =
      device.name.UTF8String ? device.name.UTF8String : "unknown";
  return fmt::format(
      "{{\"device_name\":\"{}\",\"registry_id\":{},"
      "\"unified_memory\":{},\"low_power\":{},\"removable\":{},"
      "\"recommended_max_working_set_size\":{}}}",
      device_name, uint64_t(device.registryID),
      device.hasUnifiedMemory ? "true" : "false",
      device.isLowPower ? "true" : "false",
      device.isRemovable ? "true" : "false",
      uint64_t(device.recommendedMaxWorkingSetSize));
}

void* MetalCommandProcessor::GetRamFrontbufferTexture(uint32_t base,
                                                      uint32_t width,
                                                      uint32_t height) {
  if (!base || !width || !height || width > 2048 || height > 2048) {
    return nullptr;
  }
  const uint8_t* guest = TranslateGuest<const uint8_t*>(base);
  if (!guest) {
    return nullptr;
  }
  // The frontbuffer is a tiled k_8_8_8_8 surface (a resolve dest). Bound the
  // readable range by the tiled extent (rows padded to the 32-row macro tile).
  uint32_t pitch_aligned = (width + 31u) & ~31u;
  uint32_t rows_padded = (height + 31u) & ~31u;
  uint64_t range_bytes = uint64_t(pitch_aligned) * rows_padded * 4;
  constexpr uint64_t kPhysicalMemorySize = 512ull * 1024 * 1024;
  if (uint64_t(base) + range_bytes > kPhysicalMemorySize) {
    return nullptr;
  }
  // The decode below depends on the resolve layout (presence, endian,
  // copy_dest_swap) recorded for this base, not just the raw bytes. Fold that
  // metadata AND the snapshot generation into the reuse key so identical guest
  // bytes decoded under changed metadata can't reuse a stale decoded texture.
  auto layout_it = ram_color_layouts_.find(base);
  bool has_resolve_layout = layout_it != ram_color_layouts_.end();
  RamColorLayout resolve_layout =
      has_resolve_layout ? layout_it->second : RamColorLayout{};
  struct DecodeKey {
    uint64_t bytes_hash;
    uint32_t present;
    uint32_t endian;
    uint32_t swap_rb;
    uint32_t generation;
  } decode_key{XXH3_64bits(guest, size_t(range_bytes)),
               has_resolve_layout ? 1u : 0u, resolve_layout.endian,
               resolve_layout.swap_rb, resolve_layout.generation};
  uint64_t hash = XXH3_64bits(&decode_key, sizeof(decode_key));
  id<MTLTexture> tex = (__bridge id<MTLTexture>)fb_ram_texture_;
  if (tex && fb_ram_width_ == width && fb_ram_height_ == height &&
      fb_ram_content_hash_ == hash) {
    return fb_ram_texture_;  // unchanged frame (video below refresh rate).
  }
  auto* provider =
      static_cast<rex::ui::metal::MetalProvider*>(GetGraphicsDriver().GetProvider());
  id<MTLDevice> device =
      provider ? (__bridge id<MTLDevice>)provider->device() : nil;
  if (!device) {
    return nullptr;
  }
  if (!tex || fb_ram_width_ != width || fb_ram_height_ != height) {
    if (fb_ram_texture_) {
      CFRelease(fb_ram_texture_);
      fb_ram_texture_ = nullptr;
    }
    MTLTextureDescriptor* desc = [MTLTextureDescriptor
        texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm
                                     width:width
                                    height:height
                                 mipmapped:NO];
    desc.usage = MTLTextureUsageShaderRead;
    desc.storageMode = MTLStorageModeShared;
    tex = [device newTextureWithDescriptor:desc];
    if (!tex) {
      return nullptr;
    }
    tex.label = @"cp:ram-frontbuffer";
    fb_ram_texture_ = (__bridge_retained void*)tex;
    fb_ram_width_ = width;
    fb_ram_height_ = height;
  }
  fb_ram_content_hash_ = hash;
  // Untile guest RAM -> linear RGBA. GPU resolve destinations carry their
  // exact endian / copy_dest_swap packing, which is reversed here. Buffers
  // without a recorded resolve layout are CPU-produced scanout (FMV) in
  // [A][R][G][B] byte order, retained via the legacy rotate-right-8 path.
  std::vector<uint32_t> linear(size_t(width) * height);
  uint32_t* out = linear.data();
  auto untile_row = [&](size_t y) {
    for (uint32_t x = 0; x < width; ++x) {
      uint32_t off = uint32_t(texture_address::Tiled2D(
          int32_t(x), int32_t(y), pitch_aligned, 2));
      uint32_t v;
      std::memcpy(&v, guest + off, 4);
      if (has_resolve_layout) {
        if (resolve_layout.endian <=
            uint32_t(xenos::Endian128::k16in32)) {
          v = xenos::GPUSwap(
              v, xenos::Endian(resolve_layout.endian));
        }
        if (resolve_layout.swap_rb) {
          v = (v & 0xFF00FF00u) | ((v & 0xFFu) << 16) |
              ((v >> 16) & 0xFFu);
        }
        out[y * width + x] = v;
      } else {
        out[y * width + x] = (v >> 8) | (v << 24);
      }
    }
  };
  dispatch_apply(height, DISPATCH_APPLY_AUTO,
                 ^(size_t y) { untile_row(y); });
  [tex replaceRegion:MTLRegionMake2D(0, 0, width, height)
         mipmapLevel:0
           withBytes:linear.data()
         bytesPerRow:size_t(width) * 4];
  static uint32_t s_fb_ram_logs = 0;
  if (s_fb_ram_logs++ < 8) {
    REXLOG_INFO("MetalCommandProcessor: RAM frontbuffer present {}x{} @ {:08X}",
           width, height, base);
  }
  return fb_ram_texture_;
}

// Stage-1 widening (optimize-metal-gpu-resident-resolve-coherence): route
// eligibility for one binding. The promoted RGBA8 class keeps its exact
// predicates (and the signed corridor, applied by the callers); every other
// table format routes both signs on the shared shape rules.
bool MetalCommandProcessor::SharedRouteEligible(
    const xenos::TextureFetch& fetch_in, bool is_signed,
    uint32_t width, uint32_t height, uint32_t pitch_texels,
    bool* corridor_required_out) {
  // A raw minimum level above the maximum (Banjo's 512x512 k_8 fetches: min 1,
  // max 0) is one level by GetSubresourcesFromFetchConstant: the base when the
  // fetch has no mip page, else mip `min` alone. The cache key and the sampler
  // already take those levels; the predicates below read the raw fields and
  // refused both shapes, leaving each such draw on the CPU-wait path (M1 Max:
  // 11k blocked fetches, Banjo 20 fps; routed, 0 and 30 fps).
  // XE_METAL_TEX_ROUTE_INVERTED_MIPS=0 restores the refusal.
  static const bool s_inverted_mips = [] {
    const char* v = std::getenv("XE_METAL_TEX_ROUTE_INVERTED_MIPS");
    return !(v && v[0] == '0' && !v[1]);
  }();
  xenos::TextureFetch fetch = fetch_in;
  if (s_inverted_mips && uint32_t(fetch.mip_min_level) > uint32_t(fetch.mip_max_level)) {
    uint32_t min_level = 0, max_level = 0;
    ::rex::xenos::GetSubresourcesFromFetchConstant(
        fetch_in, nullptr, nullptr, nullptr, nullptr, nullptr, &min_level,
        &max_level);
    fetch.mip_min_level = min_level;
    fetch.mip_max_level = max_level;
  }
  const bool rgba8_class =
      fetch.format == xenos::TextureFormat::k_8_8_8_8 ||
      fetch.format == xenos::TextureFormat::k_8_8_8_8_AS_16_16_16_16;
  // The signed-RGBA8 corridor is lifted by default since the 2026-09-27
  // counted gate (every signed RGBA8 fetch routes, not only those overlapping
  // a pending GPU-current record; the SF4 4942 drift is 16 px / MAE 0.0025).
  // XE_METAL_TEX_ROUTE_SIGNED_ALL=0 restores the corridor.
  static const bool s_signed_all = [] {
    const char* v = std::getenv("XE_METAL_TEX_ROUTE_SIGNED_ALL");
    return !(v && v[0] == '0' && !v[1]);
  }();
  if (corridor_required_out) {
    *corridor_required_out = rgba8_class && is_signed && !s_signed_all;
  }
  // Stacked RGBA8 is outside the strict class (single-slice direct loads)
  // and takes the generic family route like every other stacked format.
  // The strict RGBA8 class is the tiled 2D promotion; a linear or cube RGBA8
  // fetch takes the general predicates (family loaders) like any other
  // format, else it stayed on the legacy cache (RE5's cube map 2026-10-16).
  const bool rgba8_general =
      (!fetch.tiled && metal::SharedRouteLinearEnabled()) ||
      (fetch.dimension == xenos::DataDimension::kCube &&
       metal::SharedRouteCubeEnabled()) ||
      (fetch.dimension == xenos::DataDimension::k3D &&
       metal::SharedRouteVolumeEnabled());
  if (rgba8_class && !rgba8_general &&
      !(fetch.stacked && metal::SharedRouteStackedEnabled())) {
    if (is_signed) {
      if (metal::IsStrictRgba8SignedRouteEligible(fetch, width, height,
                                                  pitch_texels)) {
        return true;
      }
      // Signed mipped RGBA8: served as a Snorm view of the mipped texture,
      // the same as the unsigned mipped class, once the corridor is lifted.
      return s_signed_all &&
             metal::IsSharedRouteMipEligible(fetch, true, width, height,
                                             pitch_texels);
    }
    return metal::IsStrictRgba8RouteEligible(fetch, false, width, height,
                                             pitch_texels) ||
           metal::IsStrictRgba8MipRouteEligible(fetch, false, width, height,
                                                pitch_texels);
  }
  return metal::IsSharedRouteEligible(fetch, is_signed, width, height,
                                      pitch_texels) ||
         metal::IsSharedRouteMipEligible(fetch, is_signed, width, height,
                                         pitch_texels);
}

bool MetalCommandProcessor::FetchOverlapsPendingGpuCurrent(
    const xenos::TextureFetch& fetch) {
  if (pending_writebacks_.empty() && pending_memexports_.empty()) {
    return false;
  }
  // Bisect lever (10395 corner artifact): comma-separated hex guest bases
  // whose fetches are treated as non-corridor. This is the single authority
  // both the mask-time and serve-time signed gates consult, so the fetch
  // consistently drops to the legacy drain path — no admitted-then-starved
  // fail-closed draw skip.
  static const char* s_signed_skip_env =
      std::getenv("XE_METAL_SIGNED_SKIP_BASE");
  if (s_signed_skip_env) {
    uint32_t fetch_base = fetch.base_address << 12;
    for (const char* p = s_signed_skip_env; *p;) {
      char* end;
      uint32_t v = uint32_t(strtoul(p, &end, 16));
      if (end == p) {
        break;
      }
      if (v == fetch_base) {
        return false;
      }
      p = (*end == ',') ? end + 1 : end;
    }
  }
  metal::FetchGuestRanges rng = ComputeFetchGuestRanges(fetch);
  auto base_range = metal::GuestRange::FromBounds(rng.base_begin,
                                                  rng.base_end);
  auto mip_range = metal::GuestRange::FromBounds(rng.mip_begin, rng.mip_end);
  auto overlaps = [&](uint32_t base, uint32_t length) {
    auto pr = metal::GuestRange::FromBaseLength(base, length);
    if (!pr) {
      return false;
    }
    return (base_range && pr->Overlaps(*base_range)) ||
           (mip_range && pr->Overlaps(*mip_range));
  };
  for (const PendingWriteback& pending : pending_writebacks_) {
    if (pending.gpu_current &&
        overlaps(pending.guest_addr, pending.range_bytes())) {
      return true;
    }
  }
  // Memexport records are buffer-resident like GPU-current resolves and are
  // ordering-servable (order_memexport_producers): a signed fetch covered by
  // MEMEXPORT ordering that dropped to the legacy RAM path here would read
  // unconverged bytes with the wait elided.
  for (const PendingMemexport& pending : pending_memexports_) {
    if (overlaps(pending.base_address, pending.size_bytes)) {
      return true;
    }
  }
  return false;
}

void MetalCommandProcessor::SnapshotPendingProducersInto(
    std::vector<metal::PendingProducer>& out, std::vector<metal::PendingProducer>& scratch) const {
  // Same records and order as SnapshotPendingProducers, without allocating
  // once the vectors have grown: each queue is appended in registration
  // order, so a stable two-way merge by sequence reproduces the stable sort
  // (which remains the fallback when a queue is out of order). `scratch`
  // holds the writebacks, then the memexports after them.
  scratch.clear();
  bool sorted = true;
  for (const PendingWriteback& wb : pending_writebacks_) {
    auto range = metal::GuestRange::FromBaseLength(wb.guest_addr, wb.range_bytes());
    if (range) {
      if (!scratch.empty() && scratch.back().sequence > wb.authority_sequence) {
        sorted = false;
      }
      scratch.push_back({*range,
                         wb.gpu_current ? metal::TransitState::kGpuCurrentShared
                                        : metal::TransitState::kPendingResolve,
                         wb.submission, wb.authority_sequence});
    }
  }
  const size_t writebacks = scratch.size();
  for (const PendingMemexport& me : pending_memexports_) {
    auto range = metal::GuestRange::FromBaseLength(me.base_address, me.size_bytes);
    if (range) {
      if (scratch.size() > writebacks && scratch.back().sequence > me.authority_sequence) {
        sorted = false;
      }
      scratch.push_back(
          {*range, metal::TransitState::kPendingMemexport, me.submission, me.authority_sequence});
    }
  }
  auto by_sequence = [](const metal::PendingProducer& a, const metal::PendingProducer& b) {
    return a.sequence < b.sequence;
  };
  out.clear();
  if (sorted) {
    std::merge(scratch.begin(), scratch.begin() + writebacks, scratch.begin() + writebacks,
               scratch.end(), std::back_inserter(out), by_sequence);
  } else {
    out.assign(scratch.begin(), scratch.end());
    std::stable_sort(out.begin(), out.end(), by_sequence);
  }
}

std::vector<metal::PendingProducer>
MetalCommandProcessor::SnapshotPendingProducers() const {
  // Non-owning read of the two existing pending-producer queues into the
  // device-free authority vocabulary. Ranges are normalized/clamped by
  // GuestRange; a record whose extent has no in-bounds byte is skipped (it can
  // never be a real dependency). The existing records carry one cross-kind
  // registration sequence so the seam sees chronological producer order even
  // though the two backing queues are stored and drained separately.
  std::vector<metal::PendingProducer> producers;
  producers.reserve(pending_writebacks_.size() + pending_memexports_.size());
  for (const PendingWriteback& wb : pending_writebacks_) {
    auto range = metal::GuestRange::FromBaseLength(wb.guest_addr,
                                                   wb.range_bytes());
    if (range) {
      // Stage B: a record whose bytes the GPU scatter already placed in the
      // shared buffer is GPU-current, not merely pending. It still owes RAM
      // its bytes -- only its publication method and who may skip waiting for
      // it differ.
      producers.push_back({*range,
                           wb.gpu_current
                               ? metal::TransitState::kGpuCurrentShared
                               : metal::TransitState::kPendingResolve,
                           wb.submission, wb.authority_sequence});
    }
  }
  for (const PendingMemexport& me : pending_memexports_) {
    auto range =
        metal::GuestRange::FromBaseLength(me.base_address, me.size_bytes);
    if (range) {
      producers.push_back({*range, metal::TransitState::kPendingMemexport,
                           me.submission, me.authority_sequence});
    }
  }
  std::stable_sort(producers.begin(), producers.end(),
                   [](const metal::PendingProducer& a,
                      const metal::PendingProducer& b) {
                     return a.sequence < b.sequence;
                   });
  return producers;
}

bool MetalCommandProcessor::IndexRangeOverlapsProducers(
    uint32_t start, uint32_t end, bool gpu_current_writebacks,
    bool memexports) const {
  if (end <= start) {
    return false;
  }
  EnsureProducerIndex();
  const ProducerIndex& index = producer_index_;
  const uint32_t first = start >> 16;
  const uint32_t last = (end - 1u) >> 16;
  static const bool s_kind_bitmaps = [] {
    const char* v = std::getenv("XE_METAL_KIND_PAGE_BITMAPS");
    return !(v && v[0] == '0' && !v[1]);
  }();
  for (uint32_t page = first; page <= last && page < 8192u; ++page) {
    const uint64_t bit = uint64_t(1) << (page & 63u);
    uint64_t occupied;
    if (s_kind_bitmaps) {
      occupied = (gpu_current_writebacks ? index.pages_gpu_current[page >> 6] : 0) |
                 (memexports ? index.pages_memexport[page >> 6] : 0);
    } else {
      occupied = index.pages[page >> 6];
    }
    if (!(occupied & bit)) {
      continue;
    }
    for (uint32_t k = index.page_begin[page]; k < index.page_end[page]; ++k) {
      const metal::PendingProducer& p = index.producers[index.page_entries[k]];
      const bool kind_ok =
          (gpu_current_writebacks &&
           p.state == metal::TransitState::kGpuCurrentShared) ||
          (memexports && p.state == metal::TransitState::kPendingMemexport);
      if (kind_ok && p.range.start() < end && p.range.end() > start) {
        return true;
      }
    }
  }
  return false;
}

void MetalCommandProcessor::EnsureProducerIndex() const {
  ProducerIndex& index = producer_index_;
  if (!index.valid || index.writebacks != pending_writebacks_.size() ||
      index.memexports != pending_memexports_.size() ||
      index.sequence != memory_authority_sequence_) {
    // XE_METAL_LEAN_INDEX_REBUILD=0 restores the allocating snapshot. The
    // index rebuilds ~65 times per Red Dead frame (every registration and
    // retirement); the lean path reuses the vectors and merges the two
    // queues, each already in registration order, instead of stable-sorting
    // a fresh copy. Sequences are unique, so the order is identical.
    static const bool s_lean_rebuild = [] {
      const char* v = std::getenv("XE_METAL_LEAN_INDEX_REBUILD");
      return !(v && v[0] == '0' && !v[1]);
    }();
    if (s_lean_rebuild) {
      SnapshotPendingProducersInto(index.producers, index.snapshot_scratch);
      static const bool s_verify = std::getenv("XE_METAL_PRODUCER_INDEX_VERIFY") != nullptr;
      if (s_verify) {
        const std::vector<metal::PendingProducer> reference = SnapshotPendingProducers();
        bool same = reference.size() == index.producers.size();
        for (size_t i = 0; same && i < reference.size(); ++i) {
          const metal::PendingProducer& a = reference[i];
          const metal::PendingProducer& b = index.producers[i];
          same = a.sequence == b.sequence && a.state == b.state && a.submission == b.submission &&
                 a.range.start() == b.range.start() && a.range.end() == b.range.end();
        }
        if (!same && ++index.verify_mismatches <= 16) {
          REXLOG_ERROR("MetalProducerIndex VERIFY MISMATCH: lean snapshot differs "
                 "({} vs {} records)",
                 index.producers.size(), reference.size());
        }
      }
    } else {
      index.producers = SnapshotPendingProducers();
    }
    index.pages.fill(0);
    index.pages_gpu_current.fill(0);
    index.pages_memexport.fill(0);
    if (index.page_begin.size() != 8192u) {
      index.page_begin.assign(8192u, 0);
      index.page_end.assign(8192u, 0);
    }
    // Count per occupied page (page_end is the counter, zeroed when the
    // page's bit is first set in this rebuild).
    for (const metal::PendingProducer& p : index.producers) {
      if (!p.range.length()) {
        continue;
      }
      const uint32_t first = p.range.start() >> 16;
      const uint32_t last = (p.range.end() - 1u) >> 16;
      std::array<uint64_t, 128>* kind_pages =
          p.state == metal::TransitState::kGpuCurrentShared   ? &index.pages_gpu_current
          : p.state == metal::TransitState::kPendingMemexport ? &index.pages_memexport
                                                              : nullptr;
      for (uint32_t page = first; page <= last && page < 8192u; ++page) {
        const uint64_t bit = uint64_t(1) << (page & 63u);
        if (!(index.pages[page >> 6] & bit)) {
          index.pages[page >> 6] |= bit;
          index.page_end[page] = 0;
        }
        if (kind_pages) {
          (*kind_pages)[page >> 6] |= bit;
        }
        ++index.page_end[page];
      }
    }
    // Ranges in ascending page order (the dense CSR's layout), then fill in
    // producer order so each page's list keeps registration order.
    uint32_t entry_count = 0;
    for (uint32_t word = 0; word < 128u; ++word) {
      uint64_t bits = index.pages[word];
      while (bits) {
        const uint32_t page = word * 64u + uint32_t(__builtin_ctzll(bits));
        bits &= bits - 1u;
        const uint32_t count = index.page_end[page];
        index.page_begin[page] = entry_count;
        index.page_end[page] = entry_count;
        entry_count += count;
      }
    }
    index.page_entries.assign(entry_count, 0);
    {
      const size_t count = std::min<size_t>(index.producers.size(), 65535);
      for (size_t i = 0; i < count; ++i) {
        const metal::PendingProducer& p = index.producers[i];
        if (!p.range.length()) {
          continue;
        }
        const uint32_t first = p.range.start() >> 16;
        const uint32_t last = (p.range.end() - 1u) >> 16;
        for (uint32_t page = first; page <= last && page < 8192u; ++page) {
          index.page_entries[index.page_end[page]++] = uint16_t(i);
        }
      }
    }
    index.candidate_stamp.assign(index.producers.size(), 0);
    index.selected_stamp.assign(index.producers.size(), 0);
    index.query_stamp = 0;
    index.closure_ready = 0;
    index.mask_words = 0;
    if (ClosureBitsEnabled() && index.producers.size() <= 1024u) {
      const uint32_t words = uint32_t((index.producers.size() + 63u) / 64u);
      if (index.page_mask_slot.size() != 8192u) {
        index.page_mask_slot.assign(8192u, 0);
      }
      uint32_t slots = 0;
      for (uint32_t word = 0; word < 128u; ++word) {
        uint64_t bits = index.pages[word];
        while (bits) {
          index.page_mask_slot[word * 64u + uint32_t(__builtin_ctzll(bits))] =
              slots++;
          bits &= bits - 1u;
        }
      }
      index.page_masks.assign(size_t(slots) * words, 0);
      for (size_t i = 0; i < index.producers.size(); ++i) {
        const metal::PendingProducer& p = index.producers[i];
        if (!p.range.length()) {
          continue;
        }
        const uint32_t first = p.range.start() >> 16;
        const uint32_t last = (p.range.end() - 1u) >> 16;
        for (uint32_t page = first; page <= last && page < 8192u; ++page) {
          index.page_masks[size_t(index.page_mask_slot[page]) * words +
                           (i >> 6)] |= uint64_t(1) << (i & 63u);
        }
      }
      index.candidate_bits.resize(words);
      index.mask_words = words;
    }
    index.writebacks = pending_writebacks_.size();
    index.memexports = pending_memexports_.size();
    index.sequence = memory_authority_sequence_;
    index.valid = true;
    ++index.rebuilds;
  }
}

const std::vector<metal::PendingProducer>&
MetalCommandProcessor::IndexedPendingProducers(
    bool* any_page_hit, const metal::ConsumerRequest& request) const {
  EnsureProducerIndex();
  ProducerIndex& index = producer_index_;
  ++index.queries;
  bool hit = false;
  auto scan = [&](const metal::GuestRangeSet& set) {
    for (const metal::GuestRange& r : set.ranges()) {
      if (hit || !r.length()) {
        continue;
      }
      const uint32_t first = r.start() >> 16;
      const uint32_t last = (r.end() - 1u) >> 16;
      for (uint32_t page = first; page <= last && page < 8192u; ++page) {
        if (index.pages[page >> 6] & (uint64_t(1) << (page & 63u))) {
          hit = true;
          break;
        }
      }
    }
  };
  scan(request.resolve_ranges);
  scan(request.memexport_ranges);
  if (!hit) {
    ++index.fast_empty;
  }
  if (SeamTimingEnabled() && (index.queries & 65535) == 0) {
    REXLOG_INFO("MetalProducerIndex: queries={} fast-empty={} indexed={} "
           "memo-hits={} rebuilds={} pending={} verify-mismatches={} "
           "page-entries={} seed-steps={} closure-steps={} selected={}",
           index.queries, index.fast_empty, index.indexed_decisions,
           index.memo_hits, index.rebuilds, index.producers.size(),
           index.verify_mismatches, index.page_entries.size(),
           index.seed_steps, index.closure_steps, index.selected_total);
  }
  *any_page_hit = hit;
  return index.producers;
}

